(window.GIM_TP=window.GIM_TP||{})["Z.Vayetzei.0"]={"from":0,"a":[[["(בראשית כ״ח:י׳) וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה. רַבִּי חִיָּיא פָּתַח וְאָמַר, (קהלת א׳:ה׳) וזָרַח הַשֶּׁמֶשׁ וּבָא הַשֶּׁמֶשׁ ואֶל מְקוֹמוֹ שׁוֹאֵף זוֹרֵחַ הוּא שָׁם, הַאי קְרָא אוּקְמוּהָ. אֲבָל וְזָרַח הַשֶּׁמֶשׁ דָּא יַעֲקֹב, כַּד הֲוָה בִּבְאֵר שָׁבַע. וּבָא הַשֶּׁמֶשׁ, כַּד אֲזַל לְחָרָן, דִּכְתִיב, (בראשית כ״ח:י״א) וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ. וְאֶל מְקוֹמוֹ שׁוֹאֵף זוִֹרִחַ, דִּכְתִיב וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא.","וְתָּא חֲזֵי, שִׁמְשָׁא אַף עַל גַּב דְּנָהִיר לְכָל עַלְמָא, מַטְלָנוֹי בִּתְרֵין סִטְרִין אִינוּן, כְּמָה דְאַתְּ אָמֵר, (קהלת א׳:ו׳) הוֹלֵךְ אֶל דָּרוֹם וְסוֹבֵב אֶל צָפוֹן, בְּגִין דְּדָא יָמִינָא וְדָא שְׂמָאלָא. (ובגין) וְנָגִיד וְנָפִיק כָּל יוֹמָא מִסִּטְרָא דְּמִזְרָח, וְאָזִיל לְסִטְרָא דְּדָרוֹם, (נ\"א דמערב) וּלְבָתַר לְסִטְרָא דְּצָפוֹן, וּמִסִּטְרָא דְּצָפוֹן לְסִטְרָא דְּמַעֲרָב, וּכְדֵין שִׁמְשָׁא אִתְכְּנִישׁ, וְאָזִיל לְגַבֵּי מַעֲרָב. נָפִיק מִמִּזְרָח דִּכְתִיב, (בראשית כ״ח:י׳) וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע. וְאָזִיל לְמַעֲרָב דִּכְתִיב וַיֵּלֶךְ חָרָנָה.","רִבִּי שִׁמְעוֹן אָמַר, נָפִיק מִכְּלָלָא דְאַרְעָא דְּיִשְׂרָאֵל, דִּכְתִיב וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע. וְאֲזַל לִרְשׁוּ אָחֳרָא, דִּכְתִיב וַיֵּלֶךְ חָרָנָה. (ס\"א נפיק ממזרח, דכתיב ויצא יעקב מבאר שבע, דא שמטה. דנטיל מעומקא עלאה, נהירו דנהיר, ואזיל למערב, דכתיב וילך חרנה, אתר דדינא ורוגזא תמן.","רבי יוסי מוקי האי קרא בגלותא, בקדמיתא הוה נחית נהירו מעומקא עלאה ויעקב הוה נטיל ליה, ואזיל לגבי באר שבע, (במדבר כ״א:י״ח) באר דחפרוה שרים, דהוה נהיר מתמן, ואשלים לההוא באר בכל שלימו. וביומי דגלותא, נטיל מהאי באר שבע, ואזיל לגבי חרנה, דכתיב וילך חרנה, כלומר חרון אף, ומאי היא חרון אפו דקודשא בריך הוא, דרגא בישא), אַרְעָא דִּרְשׁוּ אָחֳרָא.","אָמַר רַבִּי חִיָּיא, כַּד אָזִיל שִׁמְשָׁא לְמַעֲרָב, הַאי מַעֲרָב אִקְרֵי מְקוֹמוֹ דְּשִׁמְשָׁא, כֻּרְסְיָיא דִילֵיהּ, אֲתַר דְּשַׁרְיָא עֲלֵיהּ, הֲדָא הוּא דִכְתִיב, (קהלת א׳:ה׳) וְאֶל מְקוֹמוֹ שׁוֹאֵף זוֹרֵחַ הוּא שָׁם, דְּאָזִיל לְגַבֵּיהּ לְאַנְהָרָא עֲלֵיהּ, וְנָטִיל כָּל נְהוֹרִין וְכָנִישׁ לוֹן לְגַבֵּיהּ.","וְהַיְינוּ כְּמָה דְתָנִינָן, קוּדְשָׁא בְּרִיךְ הוּא אֲנַח תְּפִלֵּי, (ס\"א ותנינן, קודשא בריך הוא אנח תפילין, דכתיב, (ישעיהו ס״ב:ח׳) נשבע יי בימינו ובזרוע עוזו. ותנינן ימינו דא תורה, דכתיב מימינו אש דת למו. ובזרוע עוזו אלין תפילין. וכלהו נטיל יעקב, ומכניש לגבי מערב, וסיהרא כניש לבתר כל אינון נהורין ובוצינין דנטיל יעקב, דאיהו יהיב לה ואנהר לה, והיינו דתנינן קודשא בריך הוא אנח תפילין) בְּגִין דְּנָטִיל כָּל כִּתְרִין עִלָּאִין, וּמַאן נִינְהוּ, רָזָא דְאַבָּא עִלָּאָה, וְרָזָא דְּאִמָּא עִלָּאָה. וְאִינוּן תְּפִלִּין שֶׁבָּרֹאשׁ, כְּמָה דְתָנִינָן כֹּהֵן גָּדוֹל נוֹטֵל בָּרֹאשׁ. וּלְבָתַר דְּנָטִיל אַבָּא וְאִמָּא, נָטִיל יָמִינָא וּשְׂמָאלָא, וְאִשְׁתַּכַּח (דקודשא בריך הוא) דְּנָטִיל כֹּלָּא."],[[0,"ויצא יעקב מבאר שבע וילך חרנה:","ר' חייא פתח, ואמר, וזרח השמש ובא השמש ואל מקומו שואף זורח הוא שם. מקרא זה בארוהו. אבל \u0003וזרח השמש,\u0004 זה יעקב שהוא ז\"א, כשהיה בבאר שבע, שהיא בינה, \u0003ובא השמש,\u0004 כאשר הלך לחרן, שהיא הנוקבא דז\"א. שכתוב וילן שם כי בא השמש. \u0003ואל מקומו שואף זורח,\u0004 הוא שכתוב וישכב במקום ההוא. כלומר, הנוקבא נקראת מקום, ושם הוא שואף ומאיר. ומפרש, \u0003ויצא יעקב,\u0004 שהוא לשון זריחה, כמו השמש יצא וגו'. \u0003ובאר שבע\u0004 היא בינה, שמשם מקבל ז\"א אורו. \u0003וחרן,\u0004 היא הנוקבא המקבלת אור השמש שהוא ז\"א."],[1,"ות\"ח שמשא וכו':","ובוא וראה. השמש, אף על פי שמאיר לכל העולם, נסיעותיו הן רק בב' צדדים, כמו שאתה אומר, הולך אל דרום וסובב אל צפון. משום שדרום הוא קו ימין וצפון הוא קו שמאל, ונמשך ויוצא השמש בכל יום מצד מזרח, שהוא בחינתו עצמו תפארת, והולך לצד דרום, לקו ימין, חסד, ואחר כך סובב לצד צפון לקו שמאל גבורה, כלומר שנכלל מהארת ב' הקוין, ומצד צפון הולך לצד מערב, שהוא הנוקבא, ואז השמש שוקע והולך למערב. ובזה מבאר, יוצא ממזרח, הוא שכתוב ויצא יעקב מבאר שבע, שאז נכלל בב' הקוין דרום צפון כנ\"ל, והולך למערב, שהוא הנוקבא, שכתוב וילך חרנה. ומלמדנו בזה. שההארה המרומזת בהכתוב, ויצא יעקב וגו', הוא הארה שלמה, דהיינו שכלולה מב' הקוין ימין ושמאל שה\"ס חכמה וחסדים יחדיו."],[2,"ר' שמעון אמר וכו':","רש\"א, הוא יצא מכלל ארץ ישראל, שכתוב \u0003ויצא יעקב מבאר שבע,\u0004 שהיא הנוקבא בשלמותה הנקראת באר שבע, ונקראת ארץ ישראל, והלך לרשות אחר, שכתוב \u0003וילך חרנה.\u0004 שהוא חוץ לארץ ישראל, ששם רשות הס\"א. ומפרש דבריו, יצא ממזרח, שה\"ס קו אמצעי הכולל ב' הקוין ימין ושמאל, שכתוב ויצא יעקב מבאר שבע, שהוא שמטה, דהיינו הנוקבא, שלקח מעומק העליון שהיא בינה, את האור המאיר והולך למערב, כלומר, שלקח אותו אור שהולך ושוקע במערב, שהוא קו שמאל בלי הימין, שכתוב \u0003וילך חרנה,\u0004 דהיינו מקום, אשר דין וחרון אף שמה. שהוא רשות הסטרא אחרא, כנ\"ל. כי הארת שמאל בלי ימין היא בחינת הס\"א, והולך ושוקע עד שנסתם כולו. שהוא מטעם חסרון אור החסדים של קו הימין, שאין החכמה יכולה להאיר בלי חסדים, (כנ\"ל לך דף ט\"ז אות כ\"ו ד\"ה עוד)."],[2,"","ונמצא ר\"ש חולק על רבי חייא בד' דברים. א) אשר ויצא יעקב אין פירושו זריחה, אלא יציאה מרשות לרשות. ב) שלא היה כלול בעת היציאה מדרום וצפון, שבסו\"ה הולך אל דרום וסובב אל צפון, אלא שהיה בהארת השמאל בלי הימין, דהיינו מצפון בלבד. ג) אשר באר שבע אינו בינה, אלא הנוקבא בשלמותה בזמן שהיא דבוקה במזרח. ד) אשר חרן אינו הנוקבא דז\"א, אלא רשות דסטרא אחרא."],[3,"ר' יוסי מוקי וכו':","ר\"י מפרש את מקרא הזה, על הגלות. כי בתחילה היה יורד אור מעומק העליון, שהוא בינה, ויעקב, שהוא ז\"א לקח אותו והלך והשפיע לבאר שבע, שה\"ס באר שחפרוה שרים, דהיינו הנוקבא הנבנית מאו\"א הנקראים שרים. שיעקב היה מאיר משם, מאו\"א, והשלים אותה הבאר בכל שלימותה. ובימי הגלות הוא נוסע מבאר שבע זו, והולך לחרן, שכתוב וילך חרנה, כלומר חרון אף, ומהו חרון אף של הקב\"ה, היא מדרגה הרעה, הארץ של רשות אחר, דהיינו המלכות דקליפות. ונמצא שהוא חולק גם כן על ר' חייא, באותן ד' דברים הנ\"ל כמו ר\"ש."],[4,"אמר רבי חייא וכו':","כשהשמש שהוא ז\"א, הולך למערב, שהוא הנוקבא, נקרא מערב הזה \u0003מקום\u0004 של השמש, הכסא שלו, שהוא \u0003המקום\u0004 שהשמש שורה עליו. וזהו שכתוב ואל מקומו שואף זורח הוא שם. שהולך אל המקום להאיר עליו, והוא לוקח כל האורות דהיינו מקו ימין ומקו שמאל, ומאספם אליו, כלומר שמשפיע אותם אל הנוקבא."],[5,"והיינו כמה דתנינן וכו':","והיינו כמו שלמדנו שהקב\"ה דהיינו ז\"א, מניח תפלין, שפירושו, כי לוקח כל כתרים העליונים, ומי הם. הם סוד אבא עלאה ואמא עלאה, כלומר. המוחין דחכמה ובינה, שה\"ס ב' פרשיות קדש והיה כי יביאך. אשר קדש ה\"ס המוחין דאבא עלאה, חכמה. והיה כי יביאך ה\"ס המוחין דאמא עלאה, בינה. והם תפלין שבראש כלומר ג\"ר דתפלין, סוד י\"ה, המכונים ראש. כמו שלמדנו כהן גדול נוטל בראש, שפירושו ג\"ר, אף כאן ראש הוא ג\"ר. ואחר שלקח המוחין דאבא ואמא שהם י\"ה, הוא לוקח ימין ושמאל של מוח הדעת שה\"ס ב' פרשיות שמע והיה אם שמוע, שה\"ס ו\"ה. ונמצא שז\"א לקח בזה כל המוחין. שהם חו\"ב חו\"ג, שהם סוד ד' הפרשיות המכונים תפלין דקב\"ה. כמבואר. (ועי' לעיל בהקדמת הזהר דף רכ\"א מאות רל\"ז עד אות רמ\"ד. שמובא שם סוד התפלין באורך.)"],[5,"","והוכיח ר\"ח בזה לר\"ש, שאין לומר שויצא יעקב מבאר שבע, פירושו שלקח רק הארת השמאל בלי ימין כדברי ר\"ש, כי אין השכינה נקראת \u0003מקום,\u0004 אלא בעת שמשפיע לה מכל האורות, כמבואר בסוד התפילין של הקב\"ה, וכאן כתוב, ויפגע \u0003במקום,\u0004 א\"כ המשמעות הוא שיעקב האיר לה כל האורות, ולא רק הארת שמאל בלבד. וסתר בזה כל דברי ר\"ש, כי לפי\"ז נמצא אשר \u0003ויצא יעקב,\u0004 אין פירושו, שיצא מרשות הקדושה לרשות הס\"א כדברי ר\"ש, אלא שהיא זריחה שלמה, שהרי האיר מכל האורות יחד, שהיא קדושה. וכן באר שבע הוא בינה, שהוא המקור של צד מזרח, הכולל לכל האורות יחד. וחרן הוא הנוקבא דקדושה המקבלת אותה השלמות, ולא בחינת ס\"א כר\"ש. ונמצא שדחה בזה כל דברי ר\"ש, אמנם להלן (באות ח') משיב לו ר\"ש, אשר חרן היא באמת הערלה, אלא אח\"כ חזר יעקב לנוקבא דקדושה, שעליה כתוב, ויפגע במקום, ומיושב הכל."]],[[0,"","וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה. רַבִּי חִיָּיא פָּתַח וְאָמַר, (קהלת א) וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ וְאֶל מְקוֹמוֹ שׁוֹאֵף זוֹרֵחַ הוּא שָׁם. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, אֲבָל וְזָרַח הַשֶּׁמֶשׁ - זֶה יַעֲקֹב כְּשֶׁהָיָה בִּבְאֵר שֶׁבַע. וּבָא הַשָּׁמֶשׁ - כְּשֶׁהָלַךְ לְחָרָן, שֶׁכָּתוּב וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ. וְאֶל מְקוֹמוֹ שׁוֹאֵף זוֹרֵחַ, שֶׁכָּתוּב וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא."],[1,"","וּבֹא וּרְאֵה, אַף עַל גַּב שֶׁהַשֶּׁמֶשׁ מֵאִיר לְכָל הָעוֹלָם, מַסְעוֹתָיו הֵם בִּשְׁנֵי צְדָדִים, כְּמוֹ שֶׁנֶּאֱמַר הוֹלֵךְ אֶל דָּרוֹם וְסוֹבֵב אֶל צָפוֹן, מִשּׁוּם שֶׁזֶּה יָמִין וְזֶה שְׂמֹאל. (ומשום) וְשׁוֹפֵעַ וְיוֹצֵא כָּל יוֹם מִצַּד הַמִּזְרָח, וְהוֹלֵךְ לְצַד הַדָּרוֹם (של מערב), וְאַחַר כָּךְ לְצַד הַצָּפוֹן, וּמִצַּד הַצָּפוֹן לְצַד הַמַּעֲרָב, וְאָז הַשֶּׁמֶשׁ מִתְכַּנֵּס וְיוֹצֵא לְצַד מַעֲרָב. יוֹצֵא מִמִּזְרָח, שֶׁכָּתוּב וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע. וְהוֹלֵךְ לַמַּעֲרָב, שֶׁכָּתוּב וַיֵּלֶךְ חָרָנָה."],[2,"","רַבִּי שִׁמְעוֹן אָמַר, יוֹצֵא מִכְּלַל אֶרֶץ יִשְׂרָאֵל, שֶׁכָּתוּב וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע, וְהוֹלֵךְ לִרְשׁוּת אַחֶרֶת, שֶׁכָּתוּב וַיֵּלֶךְ חָרָנָה. (יוצא ממזרח, שכתוב ויצא יעקב מבאר שבע, זו השמטה שנוטלת מהעמק העליון האור שמאיר, והולכת למערב, שכתוב וילך חרנה, המקום שהדין והרגז שם,"],[3,"","רבי יוסי מבאר את הפסוק הזה בגלות, בראשונה היה יורד אור מן העמק העליון, ויעקב היה נוטל אותו והולך לבאר שבע, הבאר שחפרוה שרים, שהיה מאיר משם, והשלים אותה הבאר בכל השלמות, ובימי הגלות נסע מבאר שבע הזו והלך לחרנה, שכתוב וילך חרנה, כלומר חרון אף, ומה הוא חרון אפו של הקדוש ברוך הוא? הדרגה הרעה, הארץ של רשות אחרת)"],[4,"","אָמַר רַבִּי חִיָּיא, כְּשֶׁהוֹלֵךְ הַשֶּׁמֶשׁ לְמַעֲרָב, הַמַּעֲרָב הַזֶּה נִקְרָא מְקוֹמוֹ שֶׁל הַשֶּׁמֶשׁ, הַכִּסֵּא שֶׁלּוֹ, מָקוֹם שֶׁשּׁוֹלֵט עָלָיו. זֶהוּ שֶׁכָּתוּב אֶל מְקוֹמוֹ שׁוֹאֵף זוֹרֵחַ הוּא שָׁם. שֶׁהוֹלֵךְ אֵלָיו לְהָאִיר עָלָיו, וְנוֹטֵל אֶת כָּל הָאוֹרוֹת וְכוֹנֵס אוֹתָם אֵלָיו."],[5,"","וְהַיְנוּ כְּמוֹ שֶׁשָּׁנִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵנִיחַ תְּפִלִּין, (ס\"א ולמדנו, הקדוש ברוך הוא מניח תפלין, שכתוב נשבע ה' בימינו ובזרוע עזו, ושנינו, ימינו זו התורה, שכתוב מימינו אש דת למו, ובזרוע עזו אלו תפלין, וכלם נטל יעקב ומאסף לצד מערב, והלבנה אוספת לבסוף כל אותם האורות והנרות שנוטל יעקב, שהוא נותן לה ומאיר לה, וזה ששנינו הקדוש ברוך הוא מניח תפלין) מִשּׁוּם שֶׁנּוֹטֵל אֶת כָּל הַכְּתָרִים הָעֶלְיוֹנִים, וּמִי הֵם? הַסּוֹד שֶׁל הָאָב הָעֶלְיוֹן וְסוֹד הָאֵם הָעֶלְיוֹנָה, וְהֵם הַתְּפִלִּין שֶׁבָּרֹאשׁ, כְּמוֹ שֶׁשָּׁנִינוּ, כֹּהֵן גָּדוֹל נוֹטֵל בָּרֹאשׁ. וְאַחַר שֶׁנּוֹטֵל הָאָב וְהָאֵם, נוֹטֵל הַיָּמִין וְהַשְּׂמֹאל, וְנִמְצָא (שהקדוש ברוך הוא) שֶׁנּוֹטֵל הַכֹּל."]]],[["רִבִּי אֶלְעָזָר אָמַר, תִּפְאֶרֶת יִשְׂרָאֵל נָטִיל כֹּלָּא, וְכַד אִתְמַשְּׁכָא כְּנֶסֶת יִשְׂרָאֵל לְעֵילָא, נָטְלָא אוּף הָכִי כֹּלָּא, עַלְמָא דִּדְכוּרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְכֵן עַלְמָא דְּנוּקְבָא דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּנָפְקֵי כָּל נְהוֹרִין מֵהַאי עַלְמָא, הָכִי נָמֵי נָטִיל כֹּלָּא הַאי עַלְמָא. דְּהָא דָּא כְּגַוְונָא דָא, וּבְגִין כָּךְ בְּאֵר שֶׁבַע דָּא יוֹבְלָא, בְּאֵר (שבע) דָּא אִיהִי שְׁמִטָּה. (דהא דא כגוונא דא) (כלא לקודשא בריך הוא) וְשִׁמְשָׁא (דא) לָא נָהִיר אֶלָּא מִיּוֹבְלָא, (ס\"א ואיהו נטיל כל נהורין ויהיב לגו שמטה) וּבְגִין כָּךְ (בראשת כח) וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה, דָּא מַעֲרָב דְּאִיהִי שְׁמִטָּה.","רִבִּי שִׁמְעוֹן אָמַר, וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע, דָּא מַעֲרָב, שְׁנַת הַשְּׁמִטָּה. וַיֵּלֶךְ חָרָנָה, דָּא שְׁנַת עָרְלָה. בְּגִין דְּנָפַק מֵרְשׁוּ קַדִּישָׁא לִרְשׁוּ אָחֳרָא, דְּהֲוָה עָרִיק מֵאֲחוּי, כְּמָה דְאִתְּמָר. וְכַד מָטָא לְבֵית אֵל, דְּאִיהוּ בִּרְשׁוּ קַדִּישָׁא, מַה כְּתִיב, (בראשת כח) וַיִּפְגַּע בַּמָּקוֹם.","מַאן מָקוֹם. רִבִּי חִיָּיא אָמַר, דָּא הוּא מְקוֹמוֹ דְּקָאֲמָרָן, דִּכְתִיב (קהלת א׳:ה׳) וְאֶל מְקוֹמוֹ שׁוֹאֵף (זורח הוא שם). (בראשית כ״ח:י״א) וַיָּלֶן שָׁם כִּי בָא הַשָּׁמֶשׁ. כְּמָה דְאַתְּ אָמֵר שׁוֹאֵף זוִֹרִחַ הוּא שָׁם, דְּהָא בְּגִין לְאַנְהָרָא לֵיהּ קָאַתְיָא.","(בראשית כ״ח:י״א) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם. אַבְנֵי הַמָּקוֹם לָא כְּתִיב, אֶלָּא מֵאַבְנֵי הַמָּקוֹם, אִלֵּין אִינוּן אַבְנֵי יְקָר, מַרְגְּלָאן טָבָאן, דְּאִינוּן תְּרֵיסַר אַבְנִין עִלָּאִין, כְּמָה דִכְתִיב שְׁתֵּים עֶשְׂרֵה אֲבָנִים, וּתְחוֹת אִלֵּין תְּרֵיסַר אֶלֶף (קנ\"א ע\"א), וְרִבְוָון, אַבְנֵי פְסִילָן, וְכֻלְּהוּ אִקְרוּן אַבְנִין, בְּגִין כָּךְ מֵאַבְנֵי הַמָּקוֹם, וְלא אַבְנֵי (ס\"א המקום) דָּא הוּא מָקוֹם דְּקָאֲמַר. (בראשית כ״ח:י״א)","וַיָּשֶׂם מֵרַאֲשֹׂתָיו, מֵרַאֲשׁוֹתָיו דְּמַאן. אֶלָּא מֵרַאֲשׁוֹתָיו דְּהַהוּא מָקוֹם. מַאי מֵרַאֲשׁוֹתָיו. אִי תֵימָא כְּמַאן דְּשַׁוִּי תְּחוֹת רֵישֵׁיהּ, לָא. אֶלָּא מֵרַאֲשׁוֹתָיו, לְאַרְבַּע (ס\"א רישין) סִטְרִין דְּעָלְמָא, תְּלַת אַבְנִין לִסְטַר צָפוֹן, וּתְלַת לִסְטַר מַעֲרָב, וּתְלַת לִסְטַר דָּרוֹם, וּתְלַת לִסְטַר מִזְרָח, וְהַהוּא מָקוֹם עֲלַיְיהוּ, לְאִתְתַּקְּנָא בְּהוּ."],[[0,"רבי אלעזר אמר וכו':","רבי אלעזר בא לחזק את דברי רבי חייא, ואמר, תפארת ישראל, שהוא ז\"א, לוקח הכל, כל הד' מוחין חו\"ב תו\"מ כנ\"ל. וכשנמשכה כנסת ישראל למעלה אל הבינה, לוקחת גם היא את כולם, כמו ז\"א, והיא כוללת את עולם הזכר של הקב\"ה, דהיינו בינה, וכן עולם הנקבה של הקב\"ה, שהוא בחינתה עצמה, וכמו שכל האורות יוצאים מעולם הזה של הבינה, כן לוקח אותם כולם עולם הזה של הנוקבא, כי זו שוה לזו, דהיינו הבינה שוה עתה אל הנוקבא, מטעם שעלתה אליה והלבישה אותה, והתחתון העולה לעליון נעשה כמוהו, ומשום זה באר שבע הוא יובל, שהיא בינה, באר שבע הוא שמטה, שהיא הנוקבא. כלומר משום שאורותיהם של הבינה והנוקבא שוים לכן נקראים שניהן באר שבע. והשמש הזה אינו מאיר אלא מיובל, ועל כן אומר הכתוב, ויצא יעקב מבאר שבע, שהיא בינה הנקראת ג\"כ באר שבע, וילך חרנה שהיא מערב שהיא שמטה, דהיינו הנוקבא, ונמצא שר\"א חזק בזה את דברי ר' חייא, שאמר, אשר באר שבע היא בינה, וחרן היא הנוקבא."],[1,"ר\"ש אמר וכו':","רש\"א, \u0003ויצא יעקב מבאר שבע,\u0004 זהו מערב, שנת השמטה, דהיינו הנוקבא, \u0003וילך חרנה,\u0004 זהו שנת ערלה, משום שיצא מרשות הקדושה לרשות אחר, כי ברח מפני אחיו, כמו שלמדנו, וכאשר הגיע לבית אל שהוא רשות קדוש, מה כתוב ויפגע במקום. פירוש, ר\"ש משיב על הוכחת רבי חייא, לעיל, לסתור דבריו, במה שפירש שיעקב לקח הארת שמאל לבד מכח מה שנאמר ויפגע במקום ואין הנוקבא נקראת מקום אלא בעת שז\"א משפיע לה כל המאורות וכו' כנ\"ל באות ו' ע\"ש, וע\"ז משיב לו כאן שמתחילה יצא מרשות הקדושה משום שלקח הארת שמאל בלי ימין, ולבסוף חזר לקדושה ונכלל מכל האורות ואז נאמר ויפגע במקום. ומתוך שבאמצע מביא הזהר מאמר ר' אלעזר, על כן מביא הזהר פעם ב' תוכן דברי ר\"ש, כדי לסיים, שאח\"כ חזר לקדושה כשהגיע לבית אל וכו'."],[2,"מאן מקום וכו':","שואל אי זה מקום הוא שאומר הכתוב. רבי חייא אמר, זה הוא מקומו של ז\"א, דהיינו הנוקבא, כמו שאמרנו לעיל (באות ו'.), שכתוב, ו אל מקומו שואף, \u0003וילן שם כי בא השמש,\u0004 הוא כמו שאתה אומר, \u0003שואף זורח הוא שם,\u0004 כי כדי להאיר לו הוא בא."],[3,"ויקח מאבני המקום:","לא כתוב אבני המקום, אלא מאבני המקום, שמשמע שבחר אבנים ידועות משם. ואומר, אלו הן אבנים יקרות, מרגליות טובות, שהן שתי עשרה אבנים עליונות, ותחתיהן שתי עשרה אלף ורבבות אבנים מחוטבות, וכולן נקראות אבנים. משום זה אומר הכתוב, מאבני המקום, ולא אבני. \u0003המקום,\u0004 הוא המקום שאמרנו, דהיינו הנוקבא, כנ\"ל."],[3,"","פירוש. הנוקבא נקראת אבן בסו\"ה אבן ישראל. והמדרגות שבה מכונות אבנים טובות. ומשום שמקבלת מנה\"י דז\"א הנקראים רגלין, היא מכונית גם כן מרגליות, מלשון, ותגל מרגלותיו. ומספר י\"ב רומז על חכמה ועשרה על חסדים, כמבואר לעיל (בהקדמת הזהר דף י\"ד במראות הסולם ד\"ה ועם זה ע\"ש) ומלבד הטעם שנתבאר שם, יש עוד טעם על מה שמספר י\"ב מורה על הארת חכמה. והוא כי יורה שממותקת כולה בבינה וראויה לקבלת החכמה, וע\"כ יש בד' ספירות חו\"ב תו\"מ שלה, אחר התכללותם זה בזה, רק י\"ב ספירות, דהיינו חכמה בינה ות\"ת בכל אחת מהן, ובחינת עצמה חסרה, מחמת שנמתקה בבינה. וע\"כ הם ד' פעמים ג', שהם י\"ב, ולא ד' פעמים ד' שהם ט\"ז. וזה סוד הים של שלמה העומד על שני עשר בקר. כי הנוקבא בעת שמקבלת הארת חכמה נקראת \u0003ים,\u0004 ואז עומדת רק על י\"ב ספירות הנקראות בקר, דהיינו ג' לכל רוח, ולא ד' כמבואר."],[3,"","והארותיה העוברות לעולמות מאצילות ולמטה נבחנות ג\"כ למספר י\"ב ולהיותן מבחינת חכמה והן בסוד \u0003אלפים,\u0004 בסו\"ה ואאלפך חכמה. וע\"כ הן י\"ב אלפים אבנים, ומבחינת הארת החסדים המלבשת החכמה, נבחנות \u0003לרבבות,\u0004 כי עשרה אלף ה\"ס ריבוא, שהוא מספר המורה על הארת חסדים כנ\"ל, שבתוכן חכמה. ובהיותן עוברות דרך המסך שמתחת האצילות, הן נחצבות שם, כלומר שנחצבות ונפרדות מאור אצילות מפאת המסך המסיים את עולם האצילות. וז\"ש \u0003ותחות אלין\u0004 תחת י\"ב אבנים שבנוקבא דאצילות \u0003תריסר אלף ורבוון אבני פסילן,\u0004 הארות החכמה ה\"ס י\"ב אלף. והארות החסדים הן רבבות כנ\"ל. והן מחוצבות, מחמת שעברו דרך המסך דאצילות החוצב ומפרידן מאצילות. \u0003וכלהו אקרון אבנין,\u0004 הן י\"ב מדרגות שבה עצמה, והן הארותיה הנמשכות ממנה בסוד י\"ב אלפים ורבבות, כולן נקראות אבנים, \u0003בגין כך מאבני המקום, ולא אבני,\u0004 כי אם אמר אבני המקום היו גם הארות התחתונות בכללם כי גם הן נקראות אבנים, וע\"כ מדייק הכתוב, \u0003מאבני המקום,\u0004 להורות שלקח רק אותן י\"ב אבנים שבה עצמה בלבד."],[4,"וישם מראשותיו:","שואל, מראשותיו של מי. ואומר, אלא מראשותיו של אותו המקום, שהיא הנוקבא. ושואל מהו פירושו של מראשותיו, אם תאמר, שפירושו הוא, כמי ששם דבר תחת ראשו. אינו כן. אלא, מראשותיו פירושו, לארבע ראשים של העולם, היינו לד' רוחות, דרום צפון מזרח מערב, שה\"ס חו\"ב תו\"מ, (כנ\"ל ב\"א דף רי\"ב ד\"ה ודא) והוא מלשון הכתוב, ומשם יפרד והיה לארבע ראשים, שלשה אבנים נתן לרוח צפון, ושלשה לרוח מערב, ושלשה לרוח דרום, ושלשה לרוח מזרח. ואותו המקום עומד עליהן להתתקן בהן. דהיינו בסו\"ה ויעש את הים וגו' עומד על שני עשר בקר, שלשה פנים צפונה ושלשה פנים ימה ושלשה פנים נגבה ושלשה פנים מזרחה והים עליהם מלמעלה, וכמו שנתבאר זה בדבור הסמוך, ע\"ש."]],[[0,"","רַבִּי אֶלְעָזָר אָמַר, תִּפְאֶרֶת יִשְׂרָאֵל נוֹטֵל הַכֹּל, וּכְשֶׁנִּמְשֶׁכֶת כְּנֶסֶת יִשְׂרָאֵל לְמַעְלָה, נוֹטֶלֶת אַף כָּאן הַכֹּל, עוֹלַם הַזָּכָר שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֵן עוֹלַם הַנְּקֵבָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. כְּמוֹ שֶׁיּוֹצְאִים כָּל הָאוֹרוֹת מִן הָעוֹלָם הַזֶּה, כָּךְ גַּם נוֹטֵל הַכֹּל הָעוֹלָם הַזֶּה, שֶׁהֲרֵי זֶה כְּמוֹ זֶה, וּמִשּׁוּם כָּךְ בְּאֵר שֶׁבַע זֶה הַיּוֹבֵל, בְּאֵר (שבע) זוֹ הַשְּׁמִטָּה. (שהרי זה כמו זה) (הכל לקדושברוךהוא) וְהַשֶּׁמֶשׁ (הזה) אֵינוֹ מֵאִיר אֶלָּא מִן הַיּוֹבֵל, (והוא נוטל לתוך האורות ומכניס תוך השמטה) וּמִשּׁוּם כָּךְ וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה, זֶה הַמַּעֲרָב שֶׁהִיא הַשְּׁמִטָּה."],[1,"","רַבִּי שִׁמְעוֹן אָמַר, וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע - זֶה הַמַּעֲרָב, שְׁנַת הַשְּׁמִטָּה. וַיֵּלֶךְ חָרָנָה - זוֹ שְׁנַת הָעָרְלָה, מִשּׁוּם שֶׁיָּצָא מֵרְשׁוּת הַקְּדֻשָּׁה לִרְשׁוּת אַחֶרֶת, שֶׁהָיָה בּוֹרֵחַ מֵאָחִיו, כְּמוֹ שֶׁנִּתְבָּאֵר. וְכַאֲשֶׁר הִגִּיעַ לְבֵית אֵל, שֶׁהִיא בִּרְשׁוּת הַקְּדֻשָּׁה, מַה כָּתוּב? וַיִּפְגַּע בַּמָּקוֹם."],[2,"","מִי הַמָּקוֹם? רַבִּי חִיָּיא אָמַר, זֶהוּ מְקוֹמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב וְאֶל מְקוֹמוֹ שׁוֹאֵף (זורח הוא שם). וַיָּלֶן שָׁם כִּי בָא הַשָּׁמֶשׁ, כְּמוֹ שֶׁנֶּאֱמַר שׁוֹאֵף זוֹרֵחַ הוּא שָׁם, שֶׁהֲרֵי הוּא בָּא כְּדֵי לְהָאִיר לוֹ."],[3,"","וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם. לֹא כָתוּב אַבְנֵי הַמָּקוֹם אֶלָּא מֵאַבְנֵי הַמָּקוֹם. אֵלּוּ הֵם אֲבָנִים יְקָרוֹת מַרְגָּלִיּוֹת טוֹבוֹת שֶׁהֵן שְׁתֵּים עֶשְׂרֵה אֲבָנִים עֶלְיוֹנוֹת, כַּכָּתוּב שְׁתֵּים עֶשְׂרֵה אֲבָנִים. וְתַחַת אֵלּוּ שְׁנֵים עָשָׂר אֶלֶף וּרְבָבוֹת אֲבָנִים פְּסוּלוֹת, וְכֻלָּן נִקְרָאוֹת אֲבָנִים, וּמִשּׁוּם כָּךְ מֵאַבְנֵי הַמָּקוֹם וְלֹא אַבְנֵי (המקום), זֶה הַמָּקוֹם שֶׁאָמַר."],[4,"","וַיָּשֶׂם מְרַאֲשּתָיו. מְרַאֲשֹׁתָיו שֶׁל מִי? אֶלָּא מְרַאֲשּתָיו שֶׁל הַמָּקוֹם הַהוּא. מַה זֶּה מְרַאֲשּתָיו? אִם תֹּאמַר כְּמִי שֶׁשָּׂם תַּחַת רֹאשׁוֹ - לֹא. אֶלָּא מְרַאֲשּתָיו - לְאַרְבָּעָה (ראשי) צִדְדֵי הָעוֹלָם. שָׁלֹשׁ אֲבָנִים לְצַד צָפוֹן, וְשָׁלֹשׁ לְצַד מַעֲרָב, וְשָׁלֹשׁ לְצַד דָּרוֹם, וְשָׁלֹשׁ לְצַד מִזְרָח. וְהַמָּקוֹם הַהוּא עֲלֵיהֶם לְהִתַּקֵּן בָּהֶם."]]],[["וּכְדֵין (בראשית כ״ח:י״א) וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא. (ס\"א וישכב, י\"ב מרגלאן לתתא, וכל אינון דרגין דאינון על האי מקום הא אינון כ\"ב), כֵּיוָן דְּאִתְתַּקַן עַרְסָא, שָׁכִיב בֵּיהּ. מַאן שָׁכִיב בֵּיהּ, שִׁמְשָׁא. וְעַל דָּא כְּתִיב בְּיַעֲקֹב, (בראשית מ״ח:ב׳) וַיֵּשֶׁב עַל הַמִּטָּה, דְּהָא לֵיה אִתְחֲזֵי וְלָא לְאָחֳרָא, וְעַל דָּא וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא. וּבְגִין כָּךְ כְּתִיב, (קהלת א׳:ה׳) וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשֶּׁמֶשׁ.","\u0003סִתְרֵי תּוֹרָה\u0004 (קהלת א׳:ה׳) וזָרַח הַשֶׁמֶשׁ וּבָא הַשֶׁמֶשׁ. מַאי קָא חָמָא שְׁלֹמֹה מַלְכָּא, דְּשִׁירוּתָּא דְּסִפְּרָא דְּחָכְמְתָּא דִּילֵיהּ מֵהָכָא אִיהוּ. אֶלָּא אָמַר רַבִּי אֶלְעָזָר, שְׁלֹמֹה מַלְכָּא הַאי סִפְּרָא, אוֹקִים לֵיהּ עַל שֶׁבַע הֲבָלִים, וְעַלְמָא קָאִים עֲלַיְיהוּ. וְאִינוּן עַמּוּדִין וְסָמְכִין, קִיּוּמָא דְעַלְמָא. דְּבְּגִין כָּךָ אִקְרוּן הֲבָלִים, (ס\"א בהאי הבל דנפיק מפומיה דבר נש ואתקיים ביה ואתערו חברייא אין העולם מתקיים אלא בהבל פיהם של תינוקות של בית רבן. דבר אחר על שלשה דברים העולם עומד על התורה ועל העבודה ועל גמילות חסדים. התורה דא יעקב העבודה דא יצחק גמילות חסדים דא אברהם. שלשה דברים אלין אינון סמכין עלאין תלתא מן שבעה הבלים) מַה גּוּפָּא, לָא אִתְּקְיַּים בְּלָא הֶבֶל, אוּף הָכִי עַלְמָא, לָא אִתְּקְיַּים אֶלָּא עַל הֲבָלִים דְּאָמַר שְׁלֹמֹה מַלְכָּא. וְאִינוּן שֶׁבַע, דִּכְתִּיב, (קהלת א׳:ב׳) הֲבֵל הֲבָלִים אָמַר קֹהֶלֶתּ הֲבֵל הֲבָלִים הַכּל הָבֶל, הָא שֶׁבַע.","וְאִי תֵּימָא, אִי הָכִי דְּאִינוּן מַרְגְּלָאן טָבָאן דְּעַלְמָא קָיְימָא עֲלַיְיהוּ, הָא בְּאֲתַּר אָחֳרָא כְּתִּיב הֲבָלִים בִּישִׁין, וְאִינוּן סְתִּירוּ דְעַלְמָא, כְּגוֹן (קהלת ו׳:ב׳) זֶה הֶבֶל וָחֳלִי רָע הוּא. (קהלתד) זֶה הֶבֶל וּרְעוּתּ רוּחַ. אֶלָּא ודַּאי (אלין) אַף עַל גַּב דְּהַנֵּי שֶׁבַע הֲבָלִים, דְּאִינוּן קַדִּישִׁין קִיּוּמָא דְעַלְמָא, אִיתּ לָקֳבֵל הַנֵּי ז' הֲבָלִים דְּכָל דִּינִין דְּעַלְמָא (מנייהו) נָפְּקִין, וּמִנַּיְיהוּ מִתְּפַּשְׁטִין. (הבלים אחרנין וכלא קיומא דגלותא (ס\"א דעלמא) בגין דאית בהני שבע הבלים דכל דינין דעלמא נפקי ומתפשטי מיניה) ואִקְרוּן הֲבָלִים אָחֳרָנִין, לְאַלְקָאָה בְּנֵי נָשָׁא, וּלְאַתְּקָנָא לוֹן דְּיַהֲכוּן בְּאֹרַח מֵישָׁר, וְאִקְרוּן הֶבֶל דְּשַׁרְיָא בְּהוּ חֳלִי רָע, הֶבֶל דְּאִיהוּ רְעוּתּ רוּחַ. וְאִינוּן קִיּוּמָא (דעלמא). דְּבְגִינֵיהוֹן בְּנֵי נָשָׁא אָזְלִין בְּאֹרַח מֵישָׁר וּדְחִילוּ מִקוּדְשָׁא בְּרִיךָ הוּא, ועל דָּא סַגִּיאִין אִינוּן הֲבָלִים דְּמִתְּפַּשְׁטֵי מֵהַנֵּי שֶׁבַע.","וְשֵׁירוּתָּא דְּאִיהוּ אָמַר, רָזָא דְּשִׁמְשָׁא, דְּאִיהוּ הֶבֶל, דְּקִיֵּים עַלְמָא, ואִיהוּ רָזָא לְאָעֳלָא בַּר נָשׁ לְגוֹ מְהֵימְנוּתָּא עִלָאָה דְּקוּדְשָׁא בְּרִיךָ הוּא. וּבְגִין כָּךָ, כָּל מַה דִּתְּחוֹתּ הַאי דַרְגָּא, לָאו אִיהוּ רָזָא דִמְהֵימְנוּתָּא, וְעַל דָּא כְּתִּיב, (קהלת ב׳:י״א) וְאֵין יִתְּרוֹן תַּחַתּ הַשֶׁמֶשׁ (קהלת ט׳:ג׳) בְּכָל אֲשֶׁר נַעֲשָׂה תַּחַתּ הַשֶׁמֶשׁ, דְּהָא תְּחוֹתּ הַאי לָא אִצְּטְרִיךָ לְאִתְּדַּבָּקָא.","שִׁמְשָׁא בְּסִיהֲרָא, חָדָא אִינוּן בְּלָא פִּירוּדָא, וְסִיהֲרָא אַף על גַּב דְּאִיהוּ תְּחוֹתּ שִׁמְשָׁא, כּלָּא אִיהוּ שִׁמְשָׁא, בְּלָא פִּירוּדָא. וּתְּחוֹתּ הַאי, כּלָּא אִיהוּ רְעוּתּ רוּחַ, וְאָסִיר לְאִתְּדַּבָּקָא בֵּיהּ.","(בראשית כ״ח:י׳) וַיִּצֻּא יַעֲקֹב, בְּקִטְרָא דִּסְתִּימוּ, מִגּוֹ סִתְּרָא סְתִּימָא נָפְּקָא, זֹהַר אַסְפַּקְלַרְיָאה דְּנָהֲרָא, כְּלִילָא מִתְּרֵין גְּוָונִין דְּמִתְּחַבְּרָן כְּחֲדָא, כֵּיוָן דְּאִלֵּין אִתְּכְּלִילוּ דָּא בְּדָא, אִתְּחֲזוּן בֵּיהּ כָּל גְּוונִין. אַרְגָּמָן. אִיהוּ כָּל חֵיזוּ דִּנְהוֹרִין בֵּיהּ כְּלִילָן. רָצּוֹא וָשׁוֹב, אִינוּן נְהוֹרִין לָא מִתְּעַכְּבָן לְמֶחֱמֵי, חִבּוּרָא חָדָא אִתְּחַבְּרָן בְּהַהוּא זֹהַר.","בְּהַאי זֹהַ\"ר שָׁארֵי מַאן דְּשָׁארִי. שְׁמָא אִיהוּ לְהַהוּא דְּסָתִּים דְּלָא יְדִיעַ כְּלָל. קוֹל יַעֲקֹב אִקְרֵי, בְּהַאי אִתְּחֲזֵי מְהֵימְנוּתָּא דְּכֹלָּא. הַהוּא דְּסָתִּים וְלָא יְדִיעַ כְּלָל, בְּהַאי שַׁרְיָא ידו\"ד. שְׁלִימוּ דְכָל סִטְרִין אִיהוּ, עִלָּאָה וְתַּתָּאָה. הָכָא אִשְׁתַּכַּח יַעֲקֹב שְׁלִימוּ דְּאֲבָהָן דְּאָחִיד מִכָּל סִטְרִין. זה\"ר דָּא, עַל בְּרִירוּ דִּשְׁמָא דָא אִקְרֵי, דִּכְתִּיב, (ישעיהו מ״א:ח׳) יַעֲקֹב אֲשֶׁר בְּחַרְתִּיךָ. תְּרֵין שְׁמָהָן אִקְרֵי, יַעֲקֹב וְיִשְׂרָאֵל. בְּקַדְמִיתָּא יַעֲקֹב, וּלְבָתַּר יִשְׂרָאֵל.","סִתְּרָא דְסִתְּרָא דָא, כַּד הֲוָה בְּקַדְמִיתָּא בְּהַאי סוֹפָּא דְמַחְשָׁבָה, דְּאִיהוּ פֵּרוּשָׁא דְאוֹרַיְיתָּא דְּבִכְתַּב, ואִיהִי תּוֹרָה שֶׁבְּעַל פֶּה. וְעַל דָּא אִקְרֵי בְּאֵר, שֶׁנֶּאֱמַר (דברים א׳:ה׳) הוֹאִיל משֶׁה בְּאֵר אֶתּ הַתּוֹרָה, בְּאֵ\"ר אִיהוּ לְהַהוּא דְאִקְּרֵי שֶׁבַע, דִּכְתִּיב, (מלכים א ו׳:ל״ח) וַיִּבְנֵהוּ שֶׁבַע שָׁנִים. והַיְינוּ קוֹל גָּדוֹל.","וְדָא סוֹפָּא דְּמַחְשָׁבָה, בְּאֵ\"ר שָׁבַע אִיהוּ. וְיַעֲקֹב עָאל בְּהַאי רֵישָׁא לִמְהֵימְנוּתָּא, כֵּיוָן דְּאִתְּדָּבַּק בִּמְהֵימְנוּתָּא דָא, אִצְּטְרִיךָ לֵיהּ לְאִתְּבָּחֲנָא, בְּהַהוּא אֲתַּר דְּאִתְּבְּחִינוּ אֲבָהָן דִּילֵיהּ דְּעָאלוּ בִּשְׁלָם וּנְפָּקוּ בִּשְׁלָם.","אָדָם עָאל וְלָא אִסְתַּמַּר, וְאִתְּפַּתָּא אֲבַתְּרָהּ, וְחָטָא בְּהַהִיא (הושע א׳:ב׳) אֵשֶׁתּ זְנוּנִים, נָחָשׁ קַדְמָאָה. נֹחַ עָאל, ולא אִסְתַּמַּר, וְאִתְּפַּתָּא אֲבַתְּרָהּ, וְחָטָא. דִּכְתִּיב (בראשית ט׳:כ״א) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְּגָּל בְּתּוֹךָ אָהֳלה. אַבְרָהָם עָאל וְנָפַּק דִּכְתִּיב, (בראשית י״ב:י׳) וַיִּרֶד אַבְרָם מִצְּרַיְמָה, וּכְתִּיב, (בראשית י״ג:א׳) וַיַּעַל אַבְרָם מִמִּצְּרָיִם. יִצְּחָק עָאל וְנָפַּק, דִּכְתִּיב, (בראשית כ״ו:א׳) וַיֵּלֶךָ יִצְּחָק אֶל אֲבִימֶלֶךָ מֶלֶךָ פְּלִשְׁתִּים גְּרָרָה, וּכְתִּיב, (שם) ויַּעַל משם בְּאֵר שָׁבַע.","יַעֲקֹב כֵּיוָן דְּעָאל בִּמְהֵימְנוּתָּא, אִצְּטְרִיךָ לְמֵיעַל מִנְחָתָּא לְהַהִיא סִטְרָא, בְּגִין דְּמַאן דְּאִשְׁתְּזִיב מִתַּמָּן, אִיהוּ רְחִימָא וּבְרִירָא דְּקוּדְשָׁא בְּרִיךָ הוּא. מַאי (מה) כְּתִּיב, (בראשית כ״ח:י׳) וַיֵּצֵּא יַעֲקֹב מִבְּאֵר שָׁבַע, דִמְהֵימְנוּתָּא. וַיֵּלֶךָ חָרָנָה, סִטְרָא (הושע א) דְאֵשֶׁתּ זְנוּנִים, אִשָׁה מְנָאֶפֶּתּ.","סִתְּרָא דְסִתְּרִין, מִגּוֹ דְתּוּקְפָּא דְטִיהֲרָא דְיִצְּחָק (נפק), מִגּוֹ דוּרְדַּיָא דְחַמְרָא, נָפַּק חַד נְעִיצּוּ קְטִירָא, כָּלִיל חַד דְּכַר וְנוּקְבָא, סוּמְקָא כְּוַורְדָא, מִתְּפָּרְשָׁן לְכַמָּה סִטְרִין וּשְׁבִילִין. דְּכוּרָא אִקְרֵי סמאל, נוּקְבֵיהּ כְּלִילָא בְּגַוִּיהּ תָּדִיר. כְּמָה דְאִיהוּ בִּסְטַר קְדוּשָׁה, הָכִי נָמֵי בְּסִטְרָא אָחֳרָא, דְּכַר וְנוּקְבָא כְּלִילָן דָּא בְּדָא. נוּקְבָא דִּסמאל, נָחָשׁ, אִקְרֵי אשתּ זְנוּנִים, (בראשית י) קֵץ כָּל בָּשָׂר, קֵץ הַיָּמִים.","תְּרֵין רוּחִין בִּישִׁין מִתְּדַּבְּקָן כְּחֲדָא, רוּחָא דִדְכוּרָא דַּקִּיק. רוּחָא דְּנוּקְבָא, בְּכַמָּה אוֹרְחִין וּשְׁבִילִין מִתְּפַּרְשָׁא, וּמִתְּדַּבְּקָא בְּהַהוּא רוּחא דִּדְכוּרָא. קַשִׁיטַתּ גַּרְמָהּ בְּכַמָּה תַּכְשִׁיטִין סִתְּרָא (ס\"א סטרא) דְרָזָא כְּזוֹנָה, מְרַחֲקָא קָיְימַתּ בְּרֵישׁ אוֹרְחִין וּשְׁבִילִין, לְפַּתָּאָה בְּנֵי נָשָׁא.","שַׁטְיָא דְּקָרִיב בַּהֲדָהּ, אַתְּקִיפַּתּ בֵּיהּ וְנַשְׁקַתּ לֵיהּ, מָסְכַתּ לֵיהּ חַמְרָא דְּדוּרְדַיָא, דִּמְרוֹרַתּ פְּתָּנִים. כֵּיוָן דְּשָׁתֵּי, אַסְטֵי אֲבַתְּרָהּ, לְבָתַּר דְּחָמַאתּ לֵיהּ סָטֵי אֲבַתְּרָהּ מֵאוֹרְחָא דִקְשׁוֹט, אַפְּשִׁיטַתּ גַּרְמָהּ מִכָּל אִינוּן תִּקּוּנִין דְּהֲוַתּ מִתְּתַּקְנָא לְגַבֵּי דְהַהוּא שַׁטְיָא.","תִּקּוּנִין דִּילָהּ, לְפַּתָּאָה לִבְנֵי נָשָׁא. שַׂעֲרָהָא מְתַּקְנִין סוּמְקָן כְּוַורְדָא, אַנְפָּהָא חִוְורִין וְסוּמְקִין. בְּאוּדְנָהָא תַּלְיָין שִׁיתָּא תִּקּוּנִין אַטוּנָא דְמִצְּרַיִם, תַּלְיָין עַל קַדְלָהָא כָּל חֵילֵי דְאַרְעָא דְּקָדָם. פִּיהָ מִתְּתַּקְנא בִּפְּתִּיחוּ דַּקִּיק יָאֶה בְּתִּקּוּנהָא, לִישָׁנָא חֲדִידָא כְּחַרְבָּא, שְׁעִיעָן מִלָּהָא כְּמִשְׁחָא. שִׂפְּוָוהָא יָאָן סוּמְקִין כְּוַורְדָא, מְתִּיקוּ בְּכָל מְתִּיקוּ דְעַלְמָא, אַרְגְּוְונָא לְבָשַׁתּ, אִתְּתַּקָּנַתּ בְּאַרְבָּעִין תִּקּוּנִין, חָסֵר (ויקרא קי\"ד ע\"ב) חַד.","שַׁטְיָא (דא) סָטֵי אֲבַתְּרָהָא, וְשָׁתֵּי מִכַּסָּא דְחַמְרָא וְעֲבִיד בָּהּ נִיאוּפִּין ואַסְטֵי אֲבַתְּרָהּ. מָה עָבְדַתּ, שַׁבְקַתּ לֵיהּ נָאִים בְּעַרְסָא, וְסָלְקַתּ לְעֵילָא וְאַלְשִׁינַתּ עֲלֵיהּ, וְנָטְלָא רשוּ וְנַחֲתָּא. אִתְּעַר הַהוּא שַׁטְיָא וְחָשַׁב לְחַיְיכָא בַּהֲדָהּ כְּקַדְמִיתָּא, וְהִיא אַעֲדִיאַתּ תִּקּוּנָהָא מִינָהּ, וְאִתְּהַדְּרַתּ גִּיבַּר תַּקִּיף קָאִים לְקֳבְלֵיהּ, לָבִישׁ לְבוּשָׁא דְּנוּרָא מְלַהֲטָא, בִּדְחִילוּ תַּקִּיף מְרַתְּתָּא גַּרְמָא וְנַפְּשָׁא (ערומה). מַלְיָיא דְּעַיְינִין דַּחֲלָן, חַרְבָּא שְׁנָנָא בִּידֵיהּ (בידה), טִיפִּין מְרִירָן תַּלְיָין מֵהַהוּא חַרְבָּא, קָטִיל לֵיהּ לְהַהוּא שַׁטְיָא, וְאַרְמֵי לֵיהּ לְגוֹ גֵּיהִנֹּם."],[[0,"וכדין וישכב במקום ההוא:","וישכב הוא נוטריקון ויש-כ\"ב, שהם י\"ב מרגליות שלמטה, שהנוקבא עומד עליהם כנ\"ל, המורה על חכמה שבה, וכל אלו המדרגות שהן על מקום הזה שהם עשר ספירות, שמספר הזה מורה על הארת חסדים שבה, הרי הם כ\"ב, הרומז על שלימותה הן מחכמה והן מחסדים, כיון שנתתקן המטה בסוד כ\"ב, שכב בה. ושואל מי שכב בה, ואומר, השמש שהוא ז\"א שכב בה. ועל כן כתוב ביעקב שהוא ז\"א, וישב על המטה, כי לו היא ראויה ולא לזולתו. משום שהיא הנוקבא דז\"א. ועל כן וישכב במקום ההוא. ועל זה כתוב וזרח השמש ובא השמש, (כנ\"ל באות א')"],[1,"וזרח השמש ובא השמש:","שואל, מה ראה שלמה המלך, אשר ההתחלה מספר החכמה שלו הוא מכאן, מסוד זריחת וביאת השמש. אלא אמר רבי אלעזר, שלמה המלך העמיד את ספרו על ז' הבלים, שהעולם עומד עליהם, והם עמודים ואדנים המהוים קיומו של העולם. ומשום זה המה נקראים הבלים, כי כמו הגוף, שאינו מתקיים בלי הבל, אף העולם כן, שאינו מתקיים זולת על ההבלים שאמר שלמה המלך, והם שבע, שכתוב הבל הבלים אמר קהלת הבל הבלים הכל הבל הרי שבע הבלים כאן בהכתוב: \u0003הבל,\u0004 אחד \u0003הבלים,\u0004 הוא לשון רבים, ומיעוט רבים שנים הרי שני הבלים, וביחד הם ג' הבלים. ועוד פעם אומר \u0003הבל הבלים,\u0004 הרי ששה, והכל \u0003הבל\u0004 שלבסוף, הרי ז' הבלים."],[1,"","פירוש. הדבור, שה\"ס הנוקבא כולל בתוכו קול והבל, אשר ההבל הוא שורש אל הקול, והקול הוא שורש אל הדבור, וע\"כ הם נבחנים, לנשמה רוח ונפש, שהבל ה\"ס \u0003הנשמה\u0004 שהיא שורש הרוח, וקול הוא \u0003רוח\u0004 שהוא שורש אל \u0003הנפש.\u0004 המכונה דבור. וז' הבלים ה\"ס ז' ספירות תחתונות של הבינה הנקראת נשמה. שהן מלובשות בז\"ס של ז\"א הנקרא רוח, ובתוך ז\"ס של הנוקבא הנקראת נפש, וכן נקראת עולם. וז\"ש \u0003עלמא\u0004 שה\"ס הנוקבא, \u0003לא אתקיים אלא על הבלים דאמר שלמה מלכא, ואינון שבע\u0004 כי שבעה הבלים הם שבע נשמות בתוך ז' ספירות חג\"ת נהי\"מ של העולם, שהוא הנוקבא. ג' ספירות חג\"ת מכונות עמודים. ונהי\"מ מכונות אדנים."],[2,"ואי תימא אי הכי וכו':","ואם תאמר, אם כן הוא, שהם מרגליות טובות שהעולם עומד עליהן, הרי במקום אחר כתוב הבלים רעים, שהם חורבן העולם, דהיינו שכתוב, זה הבל וחלי רע הוא. זה הבל ורעות רוח. ומשיב אלא ודאי, אף על פי שאלו שבע הבלים שהם קדושים, הם קיום העולם, יש כנגד אלו, ז' הבלים שכל הדינים שבעולם יוצאים מהם ומתפשטים מהם. ונקראים הבלים אחרים, להעניש בני אדם ולתקן אותם, שילכו בדרך הישר. ונקראים: הבל, שחלי רע שורה בו, הבל, שהוא רעות רוח, והם קיום העולם, כי בשבילם הולכים בני אדם בדרך הישר, וביראה מפני הקב\"ה. ועל כן, הרבה הם הבלים הרעים, המתפשטים מאלו שבע הבלים דקדושה, להיותם גם הם קיום העולם."],[3,"ושירותא דאיהו אמר וכו':","ומה שהוא אמר בהתחלה סוד השמש, דהיינו מה שהתחיל הספר בהכתוב, וזרח השמש ובא השמש (כנ\"ל באות י\"ג) הוא, מפני, שהוא הבל המקיים העולם, והוא סוד להביא את האדם בתוך האמונה העליונה של הקב\"ה, כלומר, שיזכה למוחין העליונים דבינה, שנקראת אמונה העליונה דקב\"ה, וע\"כ כל מה שהיא מתחת המדרגה הזו, דהיינו מתחת השמש, אינו סוד האמונה, כלומר שאינו מן הקדושה, וע\"כ כתוב, ואין יתרון תחת השמש, וכתוב בכל אשר נעשה תחת השמש, כי מתחת זו, אין צריכים להתדבק."],[3,"","בכדי להבין הדברים, צריכים לבאר סוד ז' הבלים הקדושים וז' הבלים הרעים, משורשם. ותדע, ששורשם הוא קו שמאל שבישסו\"ת, בעוד שהוא במחלוקת עם קו ימין שבו, שאז נסתמים האורות שבו ונעשים הבל. כלומר, שנעשו הבל ורעות רוח. ומתוך שישסו\"ת הוא בחינת ז\"ס תחתונות דבינה, שהם חג\"ת נהי\"מ, לפיכך יש כאן ז' אורות שנחרבו ונעשו ז' הבלים. ותקונם של ז' הבלים אלו נעשו ע\"י עלית הקול, שהוא ז\"א, אל ישסו\"ת, שהכריע בין ב' הקוין אשר שם, והבדיל ביניהם, שהשמאל יאיר ממטה למעלה, והימין ממעלה למטה, ובזה קיים את שניהם, וז' הבלים חזרו ונעשו לז' אורות. כמ\"ש לעיל (בראשית א' דף ס' ד\"ה מחלוקת ע\"ש.)"],[3,"","וז\"ש בפרשת בא אות קמ\"ה. \u0003ורזא דמלה הכל הבל, את הכל ראיתי בימי הבלי.\u0004 כי ביציאת קו שמאל להאיר בלי ימין, נעשה \u0003הכל הבל,\u0004 ואח\"כ בעלית הקול, שהוא קו אמצעי וקיים את שניהם כנ\"ל, חזרו ז' הבלים ונעשו לז' אורות, אשר ז' אורות הללו, ה\"ס כל המוחין דחכמה המכונים ראיה, המתגלים לתחתונים, וע\"כ אמר שלמה עליהם, \u0003את הכל ראיתי בימי הבלי,\u0004 שבסוד ההבלים, נגלו לו כל המוחין דראיה. כי אלו ז' הבלים מתלבשים בז\"ס דקול, ושניהם בז\"ס דדבור, שה\"ס הנוקבא הנקראת עולם, שבה מקום הגילוי של אלו הבלים שנעשו לז' אורות דראיה. ובהם מתקיים העולם. כנ\"ל."],[3,"","וזה אמרו (לעיל באות י\"ג) שלמה מלכא, האי ספרא אוקים ליה על שבע הבלים. כי ג' ספרים עשה שלמה כנגד ג' קוין, שיר השירים, הוא ביאור לקו ימין, חסד. קהלת, הוא ביאור לקו שמאל, גבורה. משלי, הוא ביאור לקו האמצעי, ת\"ת. כמ\"ש בזהר (פרשת בא אות קמ\"ב) וכל האורות קו השמאל הן בז' הבלים, בסו\"ה את הכל ראיתי בימי הבלי כנ\"ל, ונמצא שכל ספר קהלת, אינו אלא מבאר את ז' הבלים הללו, הטובים עם הרעים, להיותו ביאור לקו השמאל."],[3,"","ונתבאר שכל תקונים של ז' הבלים הוא על ידי קו האמצעי, שהוא ז\"א הנקרא קול, או שמש, שעל ידי שמבדיל בין הארת קו ימין וקו שמאל, שהארת החכמה שבשמאל לא תאיר ממעלה למטה אלא ממטה למעלה, מתקיים הארת שני הקוים, (כנ\"ל ב\"א דף ס' ד\"ה מחלוקת ע\"ש) ואז חוזרים ז' הבלים ונעשים אורות ונשמות להנוקבא, והעולם מתקיים, שמקבלת המוחין הגדולים הנקראים קיום."],[3,"","וז\"ש הזהר (בפרשת בשלח אות שכ\"א) \u0003כל מלין דמתעבדין, ואינון תחות שמשא,\u0004 כל מה שנעשה, והוא תחת השמש. כלומר, שכל מי שממשיך את הארת החכמה אל מתחת השמש, דהיינו ממעלה למטה, \u0003דלאו אינון פולחנא דקב\"ה,\u0004 שאין זה עבודת הקב\"ה, \u0003הבל יתעביד מנייהו איהו תבירא דרוחא\u0004 וכו', על ידי המשכה הזו, נעשה האור להבל שהוא שבירת הרוח, דהיינו שכתוב, הבל ורעות רוח. \u0003אבל ההיא מלה דאיהי פולחנא דמריה\u0004 אבל הדבר שהוא עבודת רבונו, \u0003דא סליק לעילא מן שמשא,\u0004 הוא מעלה את האור למעלה מן השמש, כלומר, שממשיך האור ממטה למעלה, מן השמש ולמעלה ולא מן השמש ולמטה. ואז \u0003ואתעביד מניה הבל קדישא,\u0004 ונעשה ממנו הבל קדוש, כלומר שהבל מתהפך לאור, ונעשה נשמה לנוקבא, ומתקיים העולם."],[3,"","וזהו אמרו כאן, \u0003ושירותא דאיהו אמר רזא דשמשא, דאיהו הבל דקיים עלמא\u0004 דהיינו שמתרץ מה שהקשה בתחילת המאמר, (באות י\"ג) ואומר, שמה שאמר בהתחלה של ספרו, סוד השמש, הוא משום, שהוא הבל המקיים את העולם. כלומר, משום שבכתוב הזה, וזרח השמש וגו', מבואר ההבל שמקיים את העולם, דהיינו הנעשה נשמה אל הנוקבא הנקראת עולם. שהוא התקון של כל ז' הבלים, שעליו ייסד את ספרו, וע\"כ מביא את הכתוב הזה בתחילת ספרו. וסוד הכתוב הוא, כי אחר שהשמש, שהוא ז\"א הכריע בין הקוין ימין ושמאל שבישסו\"ת, בסוד \u0003תלת מחד נפקי,\u0004 קבלם גם הוא בסוד \u0003חד בתלת קיימא,\u0004 (כנ\"ל ב\"א דף רפ\"ז ד\"ה תלת) ואז ממשיך השמש ג' קוין שבבינה בזה אחר זה. ותחלה \u0003וזרח השמש\u0004 מן הבינה דהיינו ישסו\"ת, בסוד קו ימין, שהוא אור החסדים, ואח\"כ ממשיך משם קו שמאל, שה\"ס \u0003ובא השמש\u0004 שנעשה חשך, בסו\"ה כי הכל הבל כנ\"ל. ואח\"כ מגלה בחינתו עצמו שהוא קו אמצעי לייחד הימין ושמאל זה בזה ולהבדיל ביניהם שהימין יאיר ממעלה למטה והשמאל רק ממטה למעלה כנ\"ל, שה\"ס \u0003ואל מקומו שואף,\u0004 דהיינו ששואף ומאיר אל מקום יציאתו ממטה למעלה, אשר אז חוזר ההבל ונעשה אור ונשמה אל הנוקבא הנקראת עולם. וז\"ש, \u0003דאיהו הבל דקיים עלמא.\u0004 וזהו שמסיים הכתוב \u0003זורח הוא שם,\u0004 שבדרך זה חוזר וזורח. כי ההבל חזר להיות אור."],[3,"","וז\"ש \u0003ובגין כך כל מה דתחות האי דרגא לאו איהו רזא דמהימנותא,\u0004 ומשום זה, כל מה שנמשך למתחת מדרגה הזו, דהיינו משמש ולמטה, אין זה סוד האמונה, שאינו בקדושה. וע\"ד כתוב, ואין יתרון תחת השמש בכל אשר נעשה תחת השמש \u0003דהא תחות האי לא אצטריך לאתדבקא,\u0004 כי מתחת מדרגה זו לא צריכים להמשיך ולהדבק, כי אז יחזור האור ויעשה הבל ורעות רוח כנ\"ל. ושיעור הכתוב הוא, שלא נשאר יתרון של כלום אל הממשיך למתחת השמש, וכן, זה רע בכל אשר נעשה, דהיינו מה שממשיך, למתחת השמש, כי הכל יחרב ויעשה הבל."],[4,"שמשא בסיהרא וכו':","השמש בלבנה, היינו ז\"א בזווג עם הנוקבא, הם אחד בלי פירוד, והלבנה, אע\"פ שהיא תחת השמש, כי הנוקבא היא למטה ממדרגת ז\"א, עם כל זה, בעת הזווג, הכל הוא שמש בלי פירוד, כלומר, שגם הלבנה נחשבת אז כחלק מן השמש, כי דבקות הרוחני פירושו השואת הצורה. וע\"כ היא יכולה לקבל החכמה מהשמש שהוא ז\"א, ואינה נחשבת למטה משמש. \u0003ותחות האי, כלא איהו רעות רוח,\u0004 אבל אם ממשיך החכמה למטה משמש, שהם ז\"א ונוקביה, נעשה הכל הבל ורעות רוח, דהיינו שנעשה קליפה ומזיק כנ\"ל בדבור הסמוך, \u0003ואסיר לאתדבקא ביה,\u0004 ואסור להתדבק בו."],[5,"ויצא יעקב:","בתוך סבך הסתום, ומתוך סתר הסתום, יוצא זהר המראה המאירה, כלול משני צבעים המתחברים יחד. כיון שאלו נכללו זה בזה, נראים בו כל הצבעים. והוא נקרא ארגמן, שכל מראות המאורות כלולים בו, כלומר, כמו צבע ארגמן הזה שהוא התכללות מכל מיני צבעים, כן זהר אספקלריאה המאירה נכללים בו כל האורות."],[5,"","פירוש. כבר ידעת שכל המוחין יוצאים על סדר ג' נקודות חלם שורק חירק. שמתחילה עולה מלכות המסיימת לבינה, ונופלים ג' כלים התחתונים שהן ג' אותיות אל\"ה דאלקים, ומסתלקים ממנה ג' אורות עליונים שהם נשמה חיה יחידה, ונשארה בקומת רוח, בב' כלים שה\"ס מ\"י דאלקים. (כנ\"ל ב\"א דף י\"ג ד\"ה כיון עש\"ה). וקומת רוח זו שנשארה, ה\"ס \u0003י'\u0004 שנכנס ב \u0003אור\u0004 ונעשה \u0003אויר\u0004 שה\"ס רוח. (כנ\"ל ב\"א דף ט' ד\"ה ועביד) ואור זה הנשאר מכונה הארת חולם, ו \u0003י'\u0004 זו שנכנסה באור הבינה ועשאה ל \u0003אויר,\u0004 נבחן ל \u0003סבך,\u0004 שזה יורה שאור הבינה נעשה מסובך בקשרים שצריכים לפתחם, דהיינו שצריכים לחזור ולהוריד ה \u0003י',\u0004 מ \u0003אויר,\u0004 ולהחזירה ל \u0003אור\u0004 כמקודם לכן, דהיינו שמורידים המלכות מן הבינה למקומה, וג' אותיות אל\"ה שנפלו ממנה. חוזרות ועולות ומתחברות למדרגת הבינה, וחוזרות ונשלמות עשרת הכלים וג\"ר דאורות. וחזרה זו של ג' אותיות אל\"ה אל הבינה, וירידת ה \u0003י'\u0004 מאויר מכונה הארת השורק (כנ\"ל ב\"א דף ט\"ז ד\"ה ותדע) שעם יציאת הארה זו של השורק נעשה סתימת המאורות, משום שאין החכמה יכולה להאיר בלי חסדים, כמ\"ש שם, עד שבא קו אמצעי, שה\"ס ז\"א, ומכריע ומייחד ב' הקוין, שהם מ\"י אל\"ה, זה בזה, ונכלל אור החכמה מחסדים ואור החסדים מחכמה ונשלמת הארתם."],[5,"","ומטרם ביאת קו אמצעי ליחדם זה בזה, נבחנים ב' הקוין, שהם שניהם סתומים, כי הקו ימין שה\"ס \u0003מ\"י,\u0004 הרי יש בו עוד ה \u0003י'\u0004 שנכנסה ל \u0003אור\u0004 והוא עוד \u0003אויר.\u0004 והוא נבחן משום זה \u0003לסבך סתום,\u0004 שהסבך שלו עוד לא נפתח. והקו שמאל שה\"ס \u0003אל\"ה\u0004 שבהם כבר ירדה ה \u0003י'\u0004 מ \u0003אויר\u0004 והסבך נפתח, אמנם הוא נמצא בהסתרת האור כי הוא חשך ואינו מאיר מחמת חסרון חסדים. והוא נבחן בשם \u0003סתר סתום.\u0004 ונמצא שעם ביאת קו אמצעי המיחדם זה בזה ומשלימם, הוא מסיר \u0003סבך הסתום\u0004 מקו ימין, כי עתה הוא נכלל בהארת השמאל וה \u0003י'\u0004 יורדת \u0003מאויר,\u0004 גם ממנו ונעשה \u0003אור,\u0004 כמו השמאל. וגם הוא מסיר \u0003סתר הסתום\u0004 מקו שמאל, כי עתה הוא נכלל בחסדים שבהארת הימין, וכשהחכמה מלובשת בחסדים היא מאירה בכל השלמות. אמנם זה אינו נעשה בבת אחת, אלא מתחילה הוא משלים קו ימין מבחינתו עצמו בלי התכללות השמאל המוריד \u0003י'\u0004 מן האור שלו. דהיינו שדוחה הארת השמאל ומשליט את החסדים שבהארת הימין. ומתוך שמעדיף החסדים שבימין על הארת החכמה שבשמאל, הרי החסדים נכללים בזה מכל השבח שנמצא בהארת השמאל, על דרך שיש בכלל מאתים מנה. ונמצא שמצד אחד לא הוריד כלל ה \u0003י' מאויר\u0004 שבקו ימין, ועדיין הוא אויר, שפירושו חסדים בלי חכמה. ומצד הב' נבחנים החסדים עתה לבחינת ראש וג\"ר, מתוך שהם עדיפים וחשובים לו יותר מהארת הג\"ר שבשמאל. אמנם ראש זה אינו ראש ממש, משום שה \u0003י'\u0004 עוד לא ירדה \u0003מאויר\u0004 שלו, וע\"כ הוא מכונה \u0003רישא דמהימנותא,\u0004 כי אור החסדים נקרא מהימנותא, וכיון שהוא ראש מבחינת החסדים בלבד, נקרא רישא דמהימנותא. אלא אחר כך שנעשה התכללות הב' של ימין ושמאל, שהימין נכלל משמאל ממש וה \u0003י'\u0004 יורדת מאויר של קו ימין. והשמאל נכלל מימין וגם הוא מאיר עתה כמו הימין, אלא ממטה למעלה (כנ\"ל במאמר ז' הבלים), אז נבחן התכללות הזה לראש ממש, כיון שכבר נפתח הסבך שלו. ואלו ב' המדרגות, הראשונה ה\"ס יעקב, והשניה ה\"ס ישראל, שהוא נוטריקון \u0003ל\"י רא\"ש,\u0004 ויש ג' מיני התכללות של ימין ושמאל, (כמ\"ש בבראשית ב' דף פ' ד\"ה ביאור עש\"ה.) ותדע שהתכללות א' ה\"ס יעקב, והב' והג' ה\"ס ישראל."],[5,"","וזה אמרו, \u0003בקטרא דסתימו, מגו סתרא סתימא,\u0004 דהיינו מתוך הסתימו שבקו ימין והסתימו שבקו השמאל, \u0003נפקא זהר אספקלריאה דנהרא,\u0004 יוצא בסבתם קו אמצעי, כדי ליחדם ולהשלימם, שהוא נקרא, זהר אספקלריאה דנהרא, שהוא הארת הימין כולו, דהיינו חסדים מכוסים. \u0003כלילא מתרין גוונין דמתחברן כחדא.\u0004 דהיינו שכלול מימין ומשמאל. על דרך הנ\"ל, שמתוך שמעדיף את הימין על השמאל, נעשה נכלל מהארתו, ונעשה לבחינת ג\"ר, אע\"פ שעוד לא נפתח הסבך שלו. \u0003כיון דאלין אתכלילו דא בדא אתחזון ביה כל גוונין.\u0004 כיון שהימין נכלל משמאל, נעשה שלם על ידו בכל עשר הספירות כמוהו, שהם ד' גוונים חו\"ב תו\"מ. \u0003ארגמן איהו,\u0004 הוא נקרא בשם ארגמן, משום \u0003כל חיזו דנהורין ביה כלילן,\u0004 שכל הגוונים של האורות כלולים בקו ימין כמו שכלולים כל הצבעים בצבע ארגמן. כלומר שהצבעים אינם נפרדים בו לד' צבעים ממש, להיותו בהארת החסדים בלבד. אלא שכולם כלולים בצבע האחד של חסדים. וע\"כ מדמהו לארגמן."],[5,"רצוא ושוב אינון נהורין:","אלו האורות הם רצוא ושוב, שהארת הימין \u0003רצים\u0004 למקום הארת השמאל להכלל בו, אבל תכף ומיד הם \u0003שבים\u0004 למקומם להארת הימין. \u0003לא מתעכבן למחמי,\u0004 שאינם נעצרים שם לראות, דהיינו להמשיך חכמה, אלא תכף ומיד הם שבים למקומם. \u0003חבורא חדא אתחברן בההוא זהר.\u0004 הארת הימין והשמאל מתחברים בחיבור אחד באותו הזהר. כלומר שהתכללותם מביא את שניהם להיות בימין בהארת החסדים. והארת השמאל אינה נראה כלל אלא שמתבטלת ונכללת בימין."],[6,"בהאי זה\"ר שארי מאן דשארי:","בזהר ההוא שורה מי ששורה, דהיינו השם הויה שורה בו, שהוא ג\"ר כמ\"ש לפנינו, \u0003שמא איהו לההוא דסתים דלא ידיע כלל,\u0004 ועם זה הוא שם. רק לאותו הסתום ולא ידוע כלל כלומר, השם שורה רק על הארת הימין, שעוד לא נפתח הסבך שלו ואינו ידוע כלל, ואינו שורה על השמאל, אע\"פ שכבר נפתח הסבך שלו, דהיינו שכבר יצאה ה \u0003י'\u0004 מאויר שלו, והוא ידוע. \u0003קול יעקב אקרי\u0004 זהר הזה נקרא קול יעקב, ואינו נקרא קול גדול. \u0003בהאי, אתחזי מהימנותא דכלא,\u0004 בזהר הזה נראה אור דג\"ר דבינה, הנקראת מהימנותא דכלא, כי החסדים הללו הם ג\"כ בחינת ג\"ר, כמו החסדים דג\"ר דבינה."],[6,"ההוא דסתים ולא ידיע כלל, בהאי שריא הוי\"ה","אותו הסתום שאינו ידוע כלל, דהיינו הסבך הסתום שבהארת הימין, הנ\"ל, בו שורה השם הוי\"ה, \u0003שלימו דכל סטרין איהו,\u0004 הוא שלם מכל הצדדים, כי \u0003עלאה ותתאה הכא אשתכח\u0004 העליון והתחתון, שהם בינה והנוקבא, נמצאים כאן, ונכללים בזהר הזה, ולכן \u0003יעקב שלימו דאבהן, דאחיד מכל סטרין.\u0004 וע\"כ נבחן יעקב, שהוא בחיר שבאבות, כי הוא כלול מכל הצדדים."],[6,"","פירוש. כי הארתה שמאל אע\"פ שהוא ידוע, כי הורדה הי' מ \u0003אויר\u0004 הבינה, דהיינו שהורדה המלכות מן הבינה, והבינה חזרה להיות \u0003אור\u0004 ג\"ר. הנה מתתקן בזה רק \u0003העלאה\u0004 שהיא בינה, אבל \u0003תתאה,\u0004 שהיא עצמות המלכות, אינה מקבלת מזה שום תקון. משא\"כ זהר הארת הימין, שהחסדים שלו נעשו בבחינת ג\"ר, ושם הויה שורה בו, אע\"פ שהוא לא ידוע כלל, דהיינו, אע\"פ שהמלכות נמצאת עוד בהבינה, כנ\"ל, נמצא שנתקנה בזה גם \u0003תתאה,\u0004 שהיא המלכות הנמצאת בבינה, בשוה כמו \u0003עלאה\u0004 עצמה ועל שניהם שורה שם הוי\"ה בשוה. וז\"ש, \u0003שלימו דכל סטרין איהו, עלאה ותתאה הכא אשתכח,\u0004 כמבואר. ונתבאר שמדרגה זו הם בחינת המוחין דיעקב, ולפיכך נבחן \u0003יעקב שלימו דאבהן,\u0004 כי אברהם ויצחק, אינם מגיעים להמלכות לתקן אותה, כי ה\"ס ב' קוין ימין ושמאל הכלולים זה בזה, ושניהם שולטים, והם בחינת ידוע, שהי' יצא מאויר הבינה ונשאר אור, ותקון זה אינו מגיע לעצמות המלכות, כנ\"ל. משא\"כ מדרגת יעקב, שהג\"ר שלו הם ג\"ר דחסדים והם בבחינת לא ידיע כלל, שתקון זה מגיע למלכות בשוה כמו לבינה. כנ\"ל. וע\"כ נבחן יעקב לבחיר שבאבות. וז\"ש \u0003זהר דא על ברירו דשמא דא אקרי, דכתיב יעקב אשר בחרתיך,\u0004 זהר זה של מדרגת יעקב, על בירור שם הזה, שתיקונו מגיע גם למלכות, הוא נקרא בחיר שבאבות, שכתוב יעקב אשר בחרתיך, \u0003תרין שמהן אקרי, יעקב וישראל, בקדמיתא יעקב ולבתר ישראל.\u0004 הוא נקרא בשני שמות, יעקב וישראל, מתחלה נקרא בשם יעקב, דהיינו בשעה שמשליט רק את הימין כנ\"ל ואח\"כ כשמקיים הארת שניהם, שגם החכמה מאירה אחר שנכללת בחסדים, אז נקרא בשם ישראל."],[7,"סתרא דסתרא דא וכו':","זהו סוד הסודות כי כשהיה בתחילה, מטרם שיצא לחרן, היה בסוף המחשבה הזו, שהוא הפירוש לתורה שבכתב, והיא נקראת תורה שבעל פה, שהיא הנוקבא. מחשבה, פירושו בינה. סוף המחשבה, היינו הנוקבא בעת שהיא נמתקת בבינה, וע\"כ היא נקראת \u0003באר,\u0004 שנאמר הואיל משה \u0003באר\u0004 את התורה, משום שהיא באר, דהיינו ביאור, לאותו הנקרא שבע, שהיא בינה, שהיא מבארת ומגלית החכמה שבה, שנאמר ויבנהו שבע שנים, ובהמ\"ק ראשון ה\"ס בינה. והיינו קול גדול, כשהנוקבא מקבלת חכמה מן הבינה, היא בבחינת קול גדול, ולא קול יעקב, שהיא חסדים כנ\"ל."],[8,"ודא סופא דמחשבה וכו':","וסוף המחשבה הזו הנ\"ל הוא באר שבע. ויעקב שהיה בבאר שבע הזו, השיג בזה, את הראש של האמונה, דהיינו ג\"ר מבחינת חסדים, כנ\"ל, שג\"ר הללו נקראים רישא דמהימנותא, כיון שיעקב נתדבק באמונה הזו, דהיינו בג\"ר דחסדים, היה נצרך להתנסות באותו המקום שנתנסה שם אבותיו, שנכנסו שם בשלום ויצאו בשלום."],[8,"","פירוש. כי נתבאר לעיל (פרשת לך דף מ\"ח ד\"ה ואין המוחין ע\"ש) שמדרגה הראשונה של מוחין דחיה, אינה מקובלת זולת בדרך נסיון, כאברהם שלא צוהו ה' לרדת מצרימה אלא הרעב דחפו, עש\"ה כל ההמשך. וז\"ש \u0003כיון דאתדבק במהימנותא דא,\u0004 דהיינו בג\"ר דחסדים שה\"ס מדרגת הנשמה, ועתה הוצרך עוד להשיג מדרגת חיה, \u0003אצטריך ליה לאתבחנא, בההוא אתר דאתבחינו אבהן דיליה,\u0004 כי אין מדרגת חיה מקובלת אלא על ידי נסיון, כמ\"ש שם."],[9,"אדם עאל ולא אסתמר וכו':","אדם הראשון נכנס בנסיון, שהנחש התגרה בו, ולא נשמר, ונתפתה וחטא באשת זנונים, שהוא נחש הקדמוני. נח נכנס בנסיון, ולא נשמר ונתפתה אחר אשת זנונים, וחטא. שכתוב וישת מן היין וישכר ויתגל בתוך אהלה."],[9,"אברהם עאל ונפק וכו':","אברהם נכנס שם ויצא, שכתוב וירד אברם מצרימה, וכתוב, ויעל אברם ממצרים. יצחק נכנס שם ויצא, שכתוב, וילך יצחק אל אבימלך וגו', וכתוב ויעל משם באר שבע."],[10,"יעקב כיון דעאל וכו':","יעקב, כיון שנכנס במדרגת האמונה, שהיא אור הנשמה. דהיינו הכרעת הארת הימין, כנ\"ל, הוצרך להביא מתנה לצד ההוא גם כן, דהיינו גם להשליט את הארת השמאל, שה\"ס מדרגת חיה, שזהו רק ע\"י נסיון, כנ\"ל, כי כל מי שנצל משם, שעמד בנסיון, הוא אהובו ובחירו של הקב\"ה. מהו כתוב, \u0003ויצא יעקב מבאר שבע\u0004 שהוא הצד של סוד האמונה, דהיינו קו הימין, \u0003וילך חרנה,\u0004 שהוא הצד שמאל, ששם נאחז אשת זנונים אשה מנאפת ואם אמנם יש הרבה חילוקים בין אלו חמשה הנסיונות, שהם: עץ הדעת, יין המשכר, מצרים, פלשתים, וחרן, שנתנסה בהם אדה\"ר, נח, אברהם יצחק ויעקב. מכל מקום שורשם אחד הוא דהיינו המשכת החכמה ממעלה למטה, הנקרא אשת זנונים."],[11,"סתרא דסתרין מגו וכו':","סוד הסודות, מתוך תוקף אורו של יצחק, שהוא קדושה ומתוך שמרי היין, שהם קליפות, יצא משניהם צורה אחת מורכבת מטוב ורע, הכלולה זכר ונקבה כאחד, \u0003נעיצו\u0004 פירושו הרכבה, כמו אין תולין תחובין בתאנה (תוס' שבועות א' ט') ונעיצה ותחובה משמעות אחת להן. \u0003קטירא,\u0004 פירושו צורה, כמו וצר כל קטורין (וי\"ר כ\"ג). היא אדומה כמו ורד, ומתפרשת לכמה צדדים ודרכים, כלומר שיש בה הרבה בחינות. ביאור הדברים. כי הארת יצחק ה\"ס יין המשמח אלקים ואנשים, שה\"ס הארת החכמה המאירה רק ממטה למעלה. ואם מרבה בשתיית היין, דהיינו שממשיך ממעלה למטה, אז \u0003לא זכי הא רע,\u0004 כנ\"ל (בהקדמת הזהר דף קכ\"ג אות קכ\"ב) כי מתגלה המלכות דצמצום א', וכל האורות מסתלקים (כנ\"ל בראשית א' דף ז' ד\"ה וכבר ע\"ש). ומלכות זו, מכונה שמרי היין. וזסו\"ה וישת מן היין וישכר, כי שתה יתר מכשיעור, ואז, ויתגל בתוך אהלה. כי נגלו שמרי היין. וז\"ש, שמאורו של יצחק, שה\"ס יין המשמח, ומשמרי היין, שה\"ס גילוי המלכות דצמצום א', שכל האורות מסתלקים בסבתה, מהרכבתם יחד, כמו יין המלא שמרים, יצאו דכר ונוקבא דטומאה. \u0003דכורא אקרי סמאל וכו'.\u0004 הזכר נקרא סמאל, והנקבה שלו כלולה בו תמיד. כמו שהיא בצד הקדושה בקטנות, שזו\"ן כלולים זב\"ז, כן הוא בסטרא אחרא, זכר ונקבה כלולים זה בזה. הנקבה של סמאל, נקראת נחש, אשת זנונים, קץ כל בשר, וקץ הימים."],[12,"תרין רוחין וכו':","שתי רוחות רעות מתדבקות ביחד. הארת הרוח של הזכר היא דקה כלומר, שהוא ו\"ק בלי ראש, והרוח של הנקבה מתבארת בהרבה דרכים ושבילים, כי הוא פרצוף שלם ראש וגוף, כי בקליפה הנקבה גדולה מן הזכר. והיא מתדבקת ברוח ההוא של הזכר, והיא מתעדית בהרבה עדיים, כמו זונה מתועבת, העומדת בראש דרכים ושבילים לפתות בני אדם. וזה מלמדנו, שהיא מזדקקת רק למתחילים לילך בדרך ה', שהם עלולים לנפול בפח שלה, וזה נבחן כעומדת בראש הדרכים של עבודת ה'. אמנם אלו הרגילים בדרכי ה', כבר אותה הזונה נפרדת מהם, ואין לה שליטה עליהם."],[13,"שטיא דקריב וכו':","השוטה הקרב אליה, היא מחזקת בו ומנשקתו, ומוזגת לו יין מלא שמרים, דמרורת פתנים. כיון ששתה כבר הוא זונה אחריה. לאחר שרואה אותו זונה אחריה וסר מדרך האמת, היא מתפשטת מכל אלו התקונים, שהיתה מתתקנת כלפי אותו השוטה, כמו שנתבאר לפנינו."],[14,"תקונין וכו':","התקונים שלה לפתות את בני אדם, הן: שערותיה מתוקנת. אדומות כשושנה. פניה, לבנות ואדומות. באזניה, תלוים ששה תקונים של אטון מצרים. על ערפה, תלוים כל הכחות שבארץ הקדם. פיה, מתתקן בפתיחה קטנה וצרה יפה בתקוניה. הלשון, כחרב חדה. הוחלקו דבריה כשמן. שפתותיה, יפות אדומות כשושנה, מתוקה מכל מתוק שבעולם. מלובשת ארגמן ונתתקנה בארבעים תקונים חסר אחד."],[15,"שטיא סטי וכו':","השוטה, הולך אחריה ושותה מכוס יינה, ומנאף עמה, וזונה אחריה. מה היא עושה. מניחה אותו יישן במטתו, ועולה למעלה ומסטנת עליו, ומקבלת שם רשות להרגו, ויורדת אליו. והיא כבר הסירה את התקונים מעליה, ונעשתה גבור עריץ עומד לנגדו, לובש לבוש של אש לוהט, מטיל פחד עצום המחריד גוף ונפש. מלא עינים איומות, חרב חדה בידיו, טיפות מרות תליות על חרב ההוא, הורג את שוטה ההוא ומטילו לגיהנם."],[15,"","ביאור הדברים. כבר נתבאר, שעץ הדעת ויין המשכר ואשת זנונים וכו' הם דבר אחד (כנ\"ל באות כ\"ב ד\"ה יעקב ע\"ש), דהיינו המשכת הארת השמאל ממעלה למטה. גם נתבאר לעיל (בהקדמת הזהר דף קכ\"ג אות קכ\"ב ד\"ה ב') אשר הנוקבא, ה\"ס עץ הדעת טוב ורע, כי יש בה ב' נקודות המכונות מפתחא ומנעולא, ואם \u0003זכי הא טוב,\u0004 שפירושו, שהולך בדרך קו אמצעי. שממשיך הארת החכמה שבשמאל רק ממטה למעלה. ואז נגנזה נקודה דמנעולא שבנוקבא דז\"א, שהיא מדת הדין, ונקודה דמדת הרחמים גלויה, ואז משפעת כל טוב לתחתונים. וזה נבחן שהאדם דבוק בזו\"ן דקדושה, והיין שהוא שותה, שהם המוחין דשמאל, הוא שותה במדה, המשמח אלקים ואנשים. אבל אם \u0003לא זכי הא רע,\u0004 שפירושו אם מגביר את קו השמאל וממשיך הארתו ממעלה למטה, אז נגלה בהנוקבא דז\"א נקודה דמנעולא, שהיא מדת הדין, וכל אורות החיים מסתלקים ממנו, שהס\"ה מעפר אתה ואל עפר תשוב, וזה נבחן שהאדם נתדבק באשת זנונים ושתה יין המשכר, דהיינו ששתה יותר מן המדה, כי המשיך הארת השמאל ממעלה למטה. ואז נתגלו שמרים בתוך היין, שה\"ס נקודה דמדת הדין, והיין נעשה בשבילו כוס התרעלה. כי השמרים ממיתים אותו, כנ\"ל. ורצה הקב\"ה להביא את הצדיקים לידי נסיון, כדי שיזכו במוחין הגדולים (כנ\"ל לך דף מ\"ח ד\"ה ויש) ע\"כ בסו\"ה, זה לעומת זה עשה אלקים, שפירושו, שנתן למרכבת הטומאה, כמעט כל מה שיש בקדושה, כדי שיהיה להם כח לפתות בני אדם אחריהם. הנה בסוד הזה, עשה אלו עשתי עשרה התקונים לאשת זנונים המובאים כאן בזהר, שיהיה לה כח לפתות בני אדם. ועל דרך שתמצא בעץ הדעת, שכתוב, ותרא האשה כי טוב העץ למאכל וכי תאוה הוא לעינים ונחמד העץ להשכיל ותקח מפריו ותאכל. שמשמע שאם לא היו אלו התקונים המושכים את הלב, בעץ הדעת, לא היתה אוכלת."],[15,"","וסוד מספר התקונים הם י\"א בסוד עשתי עשרה יריעות עזים. שהם: שערות, פנים, אזנים, עורף, פה, לשון, דיבורים, שפתים, מתיקות, לבוש, ומ' תקונים חסר א'. שכל אלו הגיעו אליה מהנוקבא דקדושה, בסו\"ה אמלאה החרבה, שלא נבנה צור אלא מחורבנה של ירושלים וכו'. וסוד השערות והפנים והערף ופה ולשון ושפתים כבר בארתי אותם בפרצופי הקדושה, בשיעור י\"ג בתלמוד עשר ספירות ע\"ש כי צריכים לאריכות גדול. וסוד צבע אדום שאומר על השערות שלה, הוא להורות על הארת חכמה שבה מן השמאל המכונה אדום. והסוד הוא, כי החכמה נקראת ראיה, והצבעים אינם מושגים על ידי שום חוש אלא על ידי הראיה, שה\"ס חכמה. וצבע אדום, הוא החשוב שבצבעים, כי על כן הוא נראה למרחוק, יותר מכל מיני הצבעים, וז\"ס תקון א) \u0003שערהא מתקנין סומקן כוורדא.\u0004"],[15,"","תקון ב) \u0003אנפהא חוורין וסומקין.\u0004 צבע לבן, יורה על הארת חסדים. וצבע אדום, על הארת החכמה. ונודע שכל השלמות שבחכמה הוא בחבורו עם הארת החסדים. ולפיכך נעשה בהפנים שלה, תקון של מזיגת חכמה בחסדים, שזהו כל היופי שבנוקבא המושכת את הלב."],[15,"","תקון ג) \u0003באודנהא תליין שיתא תקונין אטונא דמצרים.\u0004 אזנים ה\"ס בינה, וסוד אטון מצרים ה\"ס חכמה, בסו\"ה והאבדתי את חכמת מצרים. אמנם שורש חכמה זו הוא מסוד הבינה שחזרה לחכמה, ולא חכמה דאור ישר ממש. כי שורשה היא נהר פישון, (כנ\"ל פרשת חיי שרה דף מ\"ד אות קמ\"ו) והיא נמשך מן נהר היוצא מעדן, שה\"ס בינה החוזרת לחכמה ולא חכמה ממש, ועל כן הן תלוים על אזניה, שהן בינה. ואומר אשר ששה תקונים נעשו לה מאטון מצרים הזו, דהיינו נגד שש הספירות חג\"ת נה\"י, וחסר תקון השביעי כנגד המלכות. והוא מטעם גניזת המלכות דצמצום א' בהנוקבא דקדושה הנקראת מנעולא כנ\"ל, בסוד זכי הא טוב."],[15,"","תקון ד) \u0003תליין על קדלהא כל חילי דארעא דקדם.\u0004 כחות ארץ הקדם ה\"ס חכמה קדומה, כי ע\"כ נקראים קדם, וה\"ס חכמה דאור ישר. שזסו\"ה ותרב חכמת שלמה מחכמת כל בני קדם ומכל חכמת מצרים. אשר חכמת מצרים נמשכה משורש בינה שנהפכה לחכמה, כנ\"ל, וחכמת בני קדם נמשכה מחכמה קדומה. וסוד \u0003העורף\u0004 היא מקום החשך, שבפרצוף, בניגוד \u0003לפנים\u0004 שהוא מקום המאיר ביותר בפרצוף, והוא מטעם כי חכמה קדומה נמשכת מחכמה סתימאה דא\"א, אשר חכמה זו נסתמה ואינה מאירה כלל, וכל הארת החכמה המאירה בעולמות היא רק מן הבינה שחזרה לחכמה, (כנ\"ל בהקסה\"ז דף נ\"ד ד\"ה בראשית) ולפיכך מקום זה הוא בחשך. בסו\"ה פנו אלי עורף ולא פנים, ולפיכך תקון כחות של ארץ הקדם הוא במקום עורף שלה."],[15,"","תקון ה) \u0003פיה מתתקנא בפתיחו דקיק יאה בתקונהא.\u0004 פה ה\"ס מלכות דראש. ויש פתיחה רחבה, מסוד המלכות הבלתי נמתקת ואז אין הפתיחה בחכמה. ואם הפתיחה דקה, דהיינו ממלכות הממותקת בבינה, הפתיחה היא בחכמה. וע\"כ נעשה בה התקון של פתיחה דקה שהיא פתיחה בחכמה. כדי שתהיה יאה בתקונהא, דהיינו שיהיו בהארת החכמה."],[15,"","תקון ו) \u0003לישנא חדידא כחרבא.\u0004 היינו להסית בני אדם. וכן תקון ז) \u0003שעיען מלהא כמשחא.\u0004 שדבריה חלקים כשמן. וע\"כ רב כחה לפתות אחריה בני אדם."],[15,"","תקון ח) \u0003שפווהא יאן מומקין כוורדא\u0004 צבע סומק מראה על תקפו של הארת השמאל כנ\"ל. תקון ט) \u0003מתיקו בכל מתיקו דעלמא,\u0004 אור הראיה, שה\"ס הארת החכמה, הוא מתוק, בסו\"ה מה מתוק האור לעין. תקון יוד) \u0003ארגוונא לבשת,\u0004 צבע ארגמן הוא כלול מכל ד' הגוונים לבן אדום ירוק שחור כנ\"ל באות י\"ז. תקון י\"א) \u0003אתתקנית בארבעין תקינין חסר חד.\u0004 היינו בד' גוונין חו\"ב תו\"מ שבכל אחת ע\"ס, אמנם בע\"ס המלכות אין שם אלא ט\"ס, ומלכות המלכות חסר, כי היא אינה ראויה לקבלת אור, כמו שנתבאר במלכות דקדושה, (לעיל בהקדמת הזהר דף נ\"ח ד\"ה אגליפו ע\"ש). ולפיכך ארבעים חסר אחת."],[15,"","והנך רואה, שכל אלו י\"א התקונים של אשת זנונים, דומים לגמרי אל תיקוני הנוקבא דקדושה, כי לקוחים הם ממנה, בסו\"ה \u0003אמלאה החרבה\u0004 שביארו חז\"ל שאין צור, שהיא מלכות דקליפה, דהיינו אשת זנונים, נבנית, אלא מחורבנה של ירושלים, שהיא מלכות דקדושה, וכן להיפך, ואין ביניהם אלא באחריתם, כי הדבוק בהנוקבא דקדושה, הולך ועולה מדרגה אחר מדרגה עד סו\"ה ואחריתך ישגה מאד (איוב ח') והנופל בפח אשת זנונים, נמצא ואחריתה מרה כלענה, (משלי ה') וכן ואחריתה דרכי מות (משלי י\"ד) כמו שהזהר מבאר לפנינו."],[15,"","וזה אמרו \u0003שטיא סטי אבתרהא\u0004 השוטה סר אחריה. פירוש. כי נתבאר בסוד אמלאה החרבה, שאין צור נבנה אלא מחורבנה של ירושלים. וזה נוהג, הן בדרך כלל כפשוטו, והן בדרך פרט בכל אדם ואדם, שבעת שעוזב את הקדושה ומתדבק בס\"א, הנה כל השפע והמדרגות שהיה לו בשורשו בבנין הקדושה, עוברות לבנין מדרגות הס\"א, והיא מתמלאת מחורבן הקדושה. גם תדע, שהאדם דבוק או בקדושה או בס\"א, ואין אחת נוגעת בחברתה כחוט השערה. כשאדם פונה לרצות בדרכי הס\"א, עוד בטרם שעושה מעשה, תכף מסתלקת הקדושה, והס\"א נוטלת מקומה, ויורשת כל השפע והמדרגות שהיה לו בקדושה, כנ\"ל. ועל זה רמזו חז\"ל, איזה שוטה, המאבד מה שנתנו לו. ויש להקשות, הרי אין אדם עובר עברה אלא אם כן נכנס בו רוח שטות (סוטה ג') ואיך אפשר שיכנס בו רוח שטות כל עוד שלא חטא, והוא דבוק בקדושה, הלא אין אחת נוגעת בחברתה כחוט השערה כנ\"ל. והתשובה היא, כיון שפונה לבו לחטוא עוד בטרם שחטא כבר נסתלקה ממנו הקדושה ואבד כל המדרגות שהיה לו בקדושה, והרוח שטות של הס\"א נתלבשה בו, ואחר זה הוא חוטא בפועל. אמנם מטרם שנתלבשה בו הרוח שטות אינו יכול לחטוא בפועל."],[15,"","וזהו שהזהר קורא את הדבק באשת זנונים בשם \u0003שוטה,\u0004 ואומר \u0003שטיא, סטי אבתרה,\u0004 ללמדנו, שבעת שהוא \u0003סטי אבתרהא\u0004 אע\"פ שעוד לא חטא בה, תכף נסתלקה ממנו הקדושה. וכל המדרגות שזכה בקדושה עברו לאשת זנונים, שמהם נעשו כל י\"א התקונים הנ\"ל, \u0003והרוח שטות\u0004 נתלבש בו, והוא נעשה שוטה, שאחר זה אפשר לו לחטוא בפועל. וע\"כ הזהר קובע שמו, שטיא. ודע, שכל אלו הפעולות שהזהר מביא לפנינו, הם נמשכים זה מזה בחיוב של קודם ונמשך, סבה ומסובב. כי אחר שחשק בס\"א, שהיא פסיעה הראשונה שלא היתה אלא חמדה ורצון בלבד, ולא פעולה ממש, דהיינו רק שסטי אבתרה. הוא בא לידי פעולה ב) דהיינו שכבר יכול לחטוא, מכח התלבשות של הרוח שטות, אמנם מתחילה \u0003ושתי מכסא דחמרא,\u0004 שהוא עוד יין במדה, בדומה לקדושה, אבל מזה נמשך פעולה ג) \u0003ועביד בה ניאופין ואסטי אבתרה,\u0004 דהיינו שמושך משמאל בלי ימין, שהוא יין המשכר הנמשך יתר מהמדה, שנבחן לניאוף עם אשת זנונים כנ\"ל. ומכאן לפעולה ד) \u0003שבקת ליה נאים בערסא,\u0004 כי מחמת הארת השמאל בלי ימין נסתמו לו כל האורות ונפל לבחינת שינה, ומכאן לפעולה ה) \u0003וסלקת לעילא ואלשינת עליה ונטלא רשו ונחתא,\u0004 שעולה למעלה ומגלית עונו, שעי\"ז מקבלת רשות להרגו, דהיינו שמגלית עליו המלכות דמדת הדין, שכל אורות החיים מסתלקים ממנו בסבתו (כנ\"ל דף י\"ד ד\"ה ביאור) ומכאן לפעולה ו) \u0003אתער ההוא שטיא וחשיב לחייכא בהדה,\u0004 כי גלוי מדת הדין מעירו משנתו, ומטרם שיודע מה קרה, הוא חושב לצחק עמה כמקודם לכן. ומכאן לפעולה, ז) \u0003והיא אעדיאת תקונהא מינה,\u0004 כי אחר שנתגלה המלכות דמדת הדין תכף נסתלקו ממנה כל האורות והתקונים. שהיו לה ממלכות דמדת הרחמים. ומכאן לפעולה ח) \u0003ואתהדרת גיבר תקיף קאים לקבליה\u0004 וכו', כי כל עוד שהיו עליה תקוניה, היתה מבחינת קליפות הימין, כי ניאוף קליפת ימין הוא, ועתה שהתנצלה מכל התקונים, מחמת שנגלה בה המלכות דמדת הדין, הוא נתהפכה מקליפת הימין, ונעשה לקליפת השמאל, דהיינו למדת הרציחה, וז\"ש \u0003ואתהדרת וכו'\u0004 כי נהפכה עתה לקליפת השמאל."],[15,"","וצריך שתדע, שהמלכות דמדת הדין, אין בה עוד השעור להמית האדם בתחלת גילויה, אלא שצריכה להתגלות על האדם הרבה פעמים, עד שקבוצם יחד מצטרף לשיעור הממית את האדם. וה\"ס הדין, שאמרו חז\"ל, שדנים את החולה בעת המיתה, דהיינו קבוץ כל הגורמים הנ\"ל המביאים את המלכות דמדת הדין על שיעורה עד כדי להמית, שבעקרם הם ב' גורמים, א) הוא פסיעה הראשונה. \u0003שטיא סטי אבתרהא\u0004 שהוא החשק לדרכי הס\"א, ונבחן זה לעין רעה, משום שהחמדה תלויה בעין, כי העין רואה והלב חומד. וגורם ב) הוא כל שאר הפעולות הנ\"ל המגלים את פעולה ה', ונכללים תחת השם \u0003חרב שנון,\u0004 כי חרב הוא לשון חורבן, דהיינו שמחריב בנין הקדושה, ומגדיל בנין הקליפות. ועל גורם א) אומר כאן \u0003מלייא דעיינין דחלן,\u0004 דהיינו קיבוץ כל החמדות שהיה לו לס\"א מכל ימי חייו. וכן אמרו חז\"ל, מלאך המות מלא עינים, (ע\"ז כ:) וכן תשעים ותשעה מתים מעין הרע. ועל גורם הב' אומר \u0003חרבא שננא בידיה\u0004 שהוא מקבוץ שאר הפעולות הנ\"ל. ועל הצטרפות לשיעור של מדת הדין כדי להמית, אומר, \u0003טיפין מרירן תליין מההוא חרבא, קטיל ליה לההוא שטיא,\u0004 שאותו החרב גורם הצטרפות לשיעור דמדת הדין המכונים טפות מרירן, שאלו הטפות ממיתים לאותו השוטה, ומטילים אותו לגיהנם."]],[[0,"","וְאָז וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא. (וישכב, י\"ב מרגליות למטה, וכל אותן הדרגות שהן על המקום הזה הרי הן כ\"ב,) כֵּיוָן שֶׁנִּתְקְנָה הַמִּטָּה, שָׁכַב בָּהּ. מִי שָׁכַב בָּהּ? הַשֶּׁמֶשׁ. וְעַל כֵּן כָּתוּב בְּיַעֲקֹב וַיֵּשֶׁב עַל הַמִּטָּה, שֶׁהֲרֵי לוֹ רְאוּיָה וְלֹא לְאַחֵר. וְעַל כֵּן וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא, וּמִשּׁוּם כָּךְ כָּתוּב וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ."],[1,"","וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ. מָה רָאָה שְׁלֹמֹה הַמֶּלֶךְ שֶׁרֵאשִׁית סֵפֶר הַחָכְמָה שֶׁלּוֹ הוּא מִכָּאן? אֶלָּא, אָמַר רַבִּי אֶלְעָזָר, הַמֶּלֶךְ שְׁלֹמֹה הֵקִים אֶת הַסֵּפֶר הַזֶּה עַל שִׁבְעָה הֲבָלִים, וְהָעוֹלָם עוֹמֵד עֲלֵיהֶם. וְהֵם הָעַמּוּדִים וְהַתּוֹמְכִים, קִיּוּם הָעוֹלָם. שֶׁמִּשּׁוּם כָּךְ נִקְרְאוּ הֲבָלִים: (ס\"א בהבל זה שיוצא מפיו של אדם ומתקים בו, והתעוררו החברים אין העולם מתקים אלא בהבל פיהם של תינוקות של בית רבן, דבר אחר, על שלשה דברים העולם עומד, על התורה ועל העבודה ועל גמילות חסדים, התורה זה יעקב, העבודה זה יצחק, גמילות חסדים זה אברהם, שלשה דברים אלו הם עמודים עליונים, שלשה מן שבעה הבלים) מָה הַגּוּף אֵינוֹ מִתְקַיֵּם בְּלִי הֶבֶל - אַף כָּךְ הָעוֹלָם אֵינוֹ מִתְקַיֵּם אֶלָּא עַל הַהֲבָלִים שֶׁאָמַר שְׁלֹמֹה הַמֶּלֶךְ, וְהֵם שִׁבְעָה, שֶׁכָּתוּב הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת הֲבֵל הֲבָלִים הַכֹּל הָבֶל. הֲרֵי שִׁבְעָה."],[2,"","וְאִם תֹּאמַר, אִם כָּךְ שֶׁאוֹתָן מַרְגָּלִיּוֹת טוֹבוֹת שֶׁהָעוֹלָם עוֹמֵד עֲלֵיהֶם, הִנֵּה בְּמָקוֹם אַחֵר כָּתוּב הֲבָלִים רָעִים, וְהֵן חֻרְבַּן הָעוֹלָם, כְּמוֹ (קהלת ו) זֶה הֶבֶל וָחֳלִי רָע הוּא. זֶה הֶבֶל וּרְעוּת רוּחַ. אֶלָּא וַדַּאי (אלו), אַף עַל גַּב שֶׁשִּׁבְעָה הַהֲבָלִים הַלָּלוּ, שֶׁהֵם קְדוֹשִׁים, קִיּוּם הָעוֹלָם, יֵשׁ כְּנֶגֶד אֵלּוּ שִׁבְעָה הֲבָלִים שֶׁכָּל דִּינֵי הָעוֹלָם יוֹצְאִים וּמֵהֶם מִתְפַּשְּׁטִים (הבלים אחרים, והכל קיום של הגלות (של העולם), משום שיש באלו שבעה הבלים שכל דיני העולם יוצאים ומתפשטים ממנו) וְנִקְרָאִים הֲבָלִים אֲחֵרִים לְהַלְקוֹת בְּנֵי אָדָם וּלְתַקְּנָם שֶׁיֵּלְכוּ בְּדֶרֶךְ יְשָׁרָה, וְנִקְרָאִים הֶבֶל שֶׁשּׁוֹרֶה בָהֶם חֳלִי רָע, הֶבֶל שֶׁהוּא רְעוּת רוּחַ. וְהֵם הַקִּיּוּם (של העולם) שֶׁבִּגְלָלָם בְּנֵי אָדָם הוֹלְכִים בְּדֶרֶךְ יָשָׁר וּפוֹחֲדִים מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל כֵּן רַבִּים הֵם הַהֲבָלִים שֶׁמִּתְפַּשְּׁטִים מִשִּׁבְעָה הַלָּלוּ."],[3,"","וְהָרֵאשִׁית שֶׁהוּא אָמַר, סוֹד הַשֶּׁמֶשׁ, שֶׁהוּא הֶבֶל שֶׁמְּקַיֵּם אֶת הָעוֹלָם, וְהוּא הַסּוֹד לְהַכְנִיס אֶת הָאָדָם לְתוֹךְ הָאֱמוּנָה הָעֶלְיוֹנָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם כָּךְ, כָּל מַה שֶּׁתַּחַת הַדַּרְגָּה הַזּוֹ אֵינוֹ סוֹד הָאֱמוּנָה, וְעַל כֵּן כָּתוּב (שם ב) וְאֵין יִתְרוֹן תַּחַת הַשָּׁמֶשׁ, בְּכָל אֲשֶׁר נַעֲשָׂה תַּחַת הַשֶּׁמֶשׁ, שֶׁהֲרֵי מִתַּחַת לְזֶה לֹא צָרִיךְ לְהִדָּבֵק."],[4,"","הַשֶּׁמֶשׁ וְהַלְּבָנָה הֵם אֶחָד בְּלִי פֵרוּד. וְאַף עַל גַּב שֶׁהַלְּבָנָה הִיא תַחַת הַשֶּׁמֶשׁ, הַכֹּל הוּא שֶׁמֶשׁ בְּלִי פֵרוּד, וְתַחַת לָזֶה הַכֹּל הוּא רְעוּת רוּחַ וְאָסוּר לְהִדָּבֵק בּוֹ."],[5,"","וַיֵּצא יַעֲקֹב, בַּקֶּשֶׁר שֶׁל הַסָּתוּם, מִתּוֹךְ הַסֵּתֶר הַסָּתוּם יוֹצֵא, זֹהַר הָאַסְפַּקְלַרְיָה הַמְּאִירָה כְּלוּלָה מִשְּׁנֵי גְוָנִים שֶׁמִּתְחַבְּרִים יַחַד. כֵּיוָן שֶׁאֵלּוּ נִכְלְלוּ זֶה עִם זֶה, נִרְאִים בּוֹ כָּל הַגְּוָנִים. הוּא אַרְגָּמָן. כָּל מַרְאֵה הָאוֹרוֹת כְּלוּלִים בּוֹ. רָצוֹא וָשׁוֹב, אוֹתָם הָאוֹרוֹת לֹא מִתְעַכְּבִים לִרְאוֹת, חִבּוּר אֶחָד הֵם מִתְחַבְּרִים בַּזֹּהַר הַהוּא."],[6,"","בַּזֹּהַ\"ר הַזֶּה שׁוֹרֶה מִי שֶׁשּׁוֹרֶה, הוּא שֵׁם לְאוֹתוֹ הַנִּסְתָּר שֶׁלֹּא יָדוּעַ כְּלָל, נִקְרָא קוֹל יַעֲקֹב, בָּזֶה נִרְאֵית הָאֱמוּנָה שֶׁל הַכֹּל. אוֹתוֹ נִסְתָּר שֶׁלֹּא יָדוּעַ כְּלָל, בָּזֶה שׁוֹרֶה יהו\"ה. הוּא הַשְּׁלֵמוּת שֶׁל כָּל הַצְּדָדִים, הָעֶלְיוֹן וְהַתַּחְתּוֹן נִמְצָא כָּאן, יַעֲקֹב הַשְּׁלֵמוּת שֶׁל הָאָבוֹת שֶׁאָחוּז מִכָּל הַצְּדָדִים. הַזֹּהַר הַזֶּה עַל בְּחִירַת הַשֵּׁם הַזֶּה נִקְרָא, שֶׁכָּתוּב יִשְׂרָאֵל אֲשֶׁר בְּחַרְתִּיךְ. שְׁנֵי שֵׁמוֹת נִקְרָא - יַעֲקֹב וְיִשְׂרָאֵל. בָּרִאשׁוֹנָה יַעֲקֹב, וְאַחַר כָּךְ יִשְׂרָאֵל."],[7,"","הַסֵּתֶר שֶׁל הַסֵּתֶר הַזֶּה, כְּשֶׁהָיָה בַּהַתְחָלָה בַּסּוֹף הַזֶּה שֶׁל הַמַּחֲשָׁבָה, שֶׁהוּא הַפֵּרוּשׁ שֶׁל תּוֹרָה שֶׁבִּכְתָב, וְהִיא הַתּוֹרָה שֶׁבְּעַל פֶּה. וְעַל כֵּן נִקְרָא בְּאֵר, שֶׁנֶּאֱמַר (דברים א) הוֹאִיל מֹשֶׁה בֵּאֵר אֶת הַתּוֹרָה. בֵּאֵ\"ר הוּא לְאוֹתוֹ שֶׁנִּקְרָא שֶׁבַע, שֶׁכָּתוּב וַיִּבְנֵהוּ שֶׁבַע שָׁנִים. וְהַיְנוּ קוֹל גָּדוֹל."],[8,"","וְסוֹף הַמַּחֲשָׁבָה הַזֶּה הוּא בְּאֵ\"ר שָׁבַע. וְיַעֲקֹב נִכְנַס בָּרֹאשׁ הַזֶּה לָאֱמוּנָה. כֵּיוָן שֶׁנִּדְבַּק בָּאֱמוּנָה הַזּוֹ, הֻצְרַךְ לוֹ לְהִבָּחֵן בְּאוֹתוֹ הַמָּקוֹם שֶׁנִּבְחֲנוּ אֲבוֹתָיו, שֶׁנִּכְנְסוּ בְשָׁלוֹם וְיָצְאוּ בְשָׁלוֹם."],[9,"","אָדָם נִכְנַס וְלֹא נִשְׁמַר, וְהִתְפַּתָּה אַחֲרֶיהָ, וְחָטָא בְּאוֹתָהּ אֵשֶׁת זְנוּנִים, הַנָּחָשׁ הַקַּדְמוֹנִי. נֹחַ נִכְנַס וְלֹא נִשְׁמַר, וְהִתְפַּתָּה אַחֲרֶיהָ וְחָטָא, שֶׁכָּתוּב וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלֹה. אַבְרָהָם נִכְנַס וְיָצָא, שֶׁכָּתוּב וַיֵּרֶד אַבְרָם מִצְרַיְמָה, וְכָתוּב וַיַּעַל אַבְרָם מִמִּצְרָיִם. יִצְחָק נִכְנַס וְיָצָא, שֶׁכָּתוּב וַיֵּלֶךְ יִצְחָק אֶל אֱבִימֶלֶךְ מֶלֶךְ פְּלִשְׁתִּים גְּרָרָה, וִכָתַב וַיַּעַל מִשָּׁם בְּאֵר שָׁבַע."],[10,"","יַעָֹקֹב, כֵּיוָן שֶׁנִּכְנַס בָּאֱמוּנָה, הִצְטָרֵךְ לְהַכְנִיס מִנְחָה לַצַּד הַהוּא, מִשּׁוּם שֶׁמִּי שֶׁנִּצַּל מִשָּׁם הוּא אָהוּב וְנִבְחָר שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. מַה כָּתוּב? וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע, הַסֵּתֶר שֶׁל סוֹד הָאֱמוּנָה. וַיֵּלֶךְ חָרָנָה - הַצַּד שֶׁל אֵשֶׁת זְנוּנִים, אִשָּׁה מְנָאֶפֶת."],[11,"","סֵתֶר הַסְּתָרִים מִתּוֹךְ הַתֹּקֶף שֶׁל אוֹרוֹ שֶׁל יִצְחָק (יצא) מִתּוֹךְ שִׁמְרֵי הַיַּיִן, יָצְאָה צוּרָה מֻרְכֶּבֶת אַחַת כּוֹלֶלֶת אֶחָד זָכָר וּנְקֵבָה, אֲדֻמָּה כְּמוֹ שׁוֹשַׁנָּה, נִפְרָדִים לְכַמָּה צְדָדִים וּשְׁבִילִים. הַזָּכָר נִקְרָא סמא\"ל, וּנְקֵבָתוֹ כְּלוּלָה בְּתוֹכוֹ תָּמִיד. כְּמוֹ שֶׁהוּא בְּצַד הַקְּדֻשָּׁה, כָּךְ גַּם בַּצַּד הָאַחֵר זָכָר וּנְקֵבָה כְּלוּלִים זֶה עִם זֶה. הַנְּקֵבָה עִם סמא\"ל, נָחָשׁ, נִקְרֵאת אֵשֶׁת זְנוּנִים, קֵץ כָּל בָּשָׂר, קֵץ הַיָּמִים."],[12,"","שְׁתֵּי רוּחוֹת רָעוֹת נִדְבָּקוֹת יַחַד. רוּחַ הַזָּכָר דַּקָּה. רוּחַ הַנְּקֵבָה בְּכַמָּה דְרָכִים וּשְׁבִילִים נִפְרֶדֶת, וְנִדְבֶּקֶת בְּאוֹתָהּ הָרוּחַ שֶׁל הַזָּכָר. מְקַשֶּׁטֶת אֶת עַצְמָהּ בְּכַמָּה תַכְשִׁיטִים, כְּמוֹ זוֹנָה, מְרֻחֶקֶת, עוֹמֶדֶת בְּרֹאשׁ הַדְּרָכִים וְהַשְּׁבִילִים לְפַתּוֹת בְּנֵי אָדָם."],[13,"","הַשּׁוֹטֶה שֶׁקָּרֵב אֵלֶיהָ, מַחֲזִיקָה בּוֹ וּמְנַשֶּׁקֶת אוֹתוֹ, מוֹזֶגֶת לוֹ יַיִן הַמְשֻׁמָּר שֶׁל מְרוֹרַת פְּתָנִים. כֵּיוָן שֶׁשּׁוֹתֶה, סוֹטֶה אַחֲרֶיהָ. אַחַר שֶׁרוֹאָה אוֹתוֹ סוֹטֶה אַחֲרֶיהָ מִדֶּרֶךְ הָאֱמֶת, מַפְשִׁיטָה אֶת עַצְמָהּ מִכָּל אוֹתָם הַתִּקּוּנִים שֶׁהָיְתָה מְתֻקֶּנֶת לַשּׁוֹטֶה הַזֶּה."],[14,"","הַתִּקּוּנִים שֶׁלָּהּ לְפַתּוֹת בְּנֵי אָדָם: שַׂעֲרוֹתֶיהָ מְתֻקָּנִים אֲדֻמִּים כַּשּׁוֹשַׁנָּה, פָּנֶיהָ לְבָנִים וַאֲדֻמִּים, בְּאָזְנֶיהָ תְּלוּיִים שִׁשָּׁה תִקּוּנִים שֶׁל אֲטוֹן מִצְרַים, תְּלוּיִים עַל צַוָּארָהּ כָּל חֵילוֹת אֶרֶץ קֶדֶם, פִּיהָ מְתֻקָּן כִּפְתִיחָה דַקָּה יָפָה בְּתִקּוּנֶיהָ, לָשׁוֹן חַדָּה כַּחֶרֶב, דְּבָרֶיהָ חֲלָקִים כַּשֶּׁמֶן, שִׂפְתוֹתֶיהָ יָפוֹת אֲדֻמּוֹת כַּשּׁוֹשַׁנָּה מְתוּקוֹת בְּכָל הַמְּתִיקוּת שֶׁל הָעוֹלָם, לְבוּשָׁהּ אַרְגָּמָן, מְתֻקֶּנֶת בְּאַרְבָּעִים תִּקּוּנִים חָסֵר אֶחָד."],[15,"","שׁוֹטֶה (זה) שֶׁסּוֹטֶה אַחֲרֶיהָ וְשׁוֹתֶה מִכּוֹס הַיַּיִן וְעוֹשֶׂה עִמָּהּ נִאוּפִים וְסוֹטֶה אַחֲרֶיהָ, מָה הִיא עוֹשָׂה? מַשְׁאִירָה אוֹתוֹ יָשֵׁן בַּמִּטָּה, וְעוֹלָה לְמַעְלָה וּמַלְשִׁינָה עָלָיו, וְנוֹטֶלֶת רְשׁוּת וְיוֹרֶדֶת. מִתְעוֹרֵר הַשּׁוֹטֶה הַהוּא, וְחוֹשֵׁב לִצְחוֹק עִמָּהּ כְּמוֹ בָּרִאשׁוֹנָה, וְהוּא מְסִירָה אֶת תִּקּוּנֶיהָ מִמֶּנָּה, וְחוֹזֶרֶת לְגִבּוֹר חָזָק שֶׁעוֹמֵד כְּנֶגְדּוֹ, לָבוּשׁ בִּלְבוּשׁ שֶׁל אֵשׁ לוֹהֶטֶת, בְּפַחַד חָזָק מְרַתֵּת עַצְמָהּ וְנַפְשָׁהּ עֲרֻמָּה, מְלֵאָה בְּעֵינַיִם מַפְחִידוֹת, חֶרֶב שְׁנוּנָה בְּיָדוֹ (בידה). טִפּוֹת מְרִירוֹת תְּלוּיוֹת מֵהַחֶרֶב הַהִיא. הוֹרֵג אֶת הַשּׁוֹטֶה הַהוּא, וְזוֹרֵק אוֹתוֹ לְתוֹךְ גֵּיהִנֹּם."]]],[["יַעֲקֹב נָחַתּ לְגַבָּהּ, וְאֲזַל לְאַתְּרָהּ. שֶׁנֶּאֱמַר וַיִּלֶךָ חָרָנָה, וְחָמָא כָּל תִּקּוּן בֵּיתָּא, וְאִשְׁתְּזִיב מִינָהּ. דְּכוּרָא דִילָהּ סמאל, אַבְאִישׁ קַמֵּיהּ, וְנָחַתּ לְאֲגָחָא בֵּיהּ קְרָבָא ולא יָכִיל לֵיהּ, דִּכְתִּיב, (בראשית ל״ב:כ״ה) וַיֵּאָבֶק אִישׁ עִמּוֹ וְגו'. כְּדֵין אִשְׁתְּזִיב מִכּלָּא, וְאִשְׁתְּלִים בִּשְׁלִימוּ ואִסְתַּלַּק בְּדַרְגָּא שְׁלִים וְאִתְּקְּרֵי יִשְׂרָאֵל. כְּדֵין סָלִיק בְּדַרְגָּא עִלָּאָה וְאִשְׁתְּלִים בְּכלָּא, וְהֲוָה עַמּוּדָא דְאֶמְצָּעִיתָּא, וְעֲלֵיהּ כְּתִּיב, (שמות כו) והַבְּרִיחַ הַתִּכוֹן וְגו'.","מַהוּ (בראשית לכ) ויִּגַּע בְּכַף יְרֵכוֹ, לֵיהּ לָא יָכִיל, אֲבָל נָגַע בְּכַף יְרֵכוֹ, דְּאִינְהוּ נָדָב וַאֲבִיהוּא, דְּנָפְּקוּ מִן יַרְכוֹ דְאַהֲרֹן, (ס\"א בסיבת אש זרה. והא אתערו לשמרך מאשה זרה וגו', ותפסה לון ברשותהא, תא חזי, מה כתיב ביעקב שלימא) (ועל יעקב כתיב) וְהַבְּרִיחַ הַתִּיכוֹן בְּתּוֹךָ הַקְּרָשִׁים מַבְרִיחַ מִן הַקָּצֶּה אֶל הַקָּצֶּה.","\u0003תּוֹסֶפְתָּא\u0004 בְּנֵי עַלְמָא, רְחִימֵי עִלָּאָה, הוּרְמָנָא דְּבוּרַיְירֵי, קְרִיבוּ שְׁמָעוּ. מַאן חַכִּימָא בָּכוּ, מָארֵי דְעַיְינִין בְּסוּכְלְתָּנוּ, לֵיתֵּי וְלִינְדַע. בְּשַׁעְתָּא דְרֵישָׁא חִוָּורָא נָטִיל תְּלַתּ אַתְּוָון וְגָלִיף לוֹן בְּגִלּוּפָּא בְּגִלּוּפִּין, חַד א', חַד י' וְחַד ן', ואִתְּגְּלִיף אי\"ן, א' רֵישָׁא עִלָּאָה דְּכֹלָּא, טְמִירָא דְּכָל טְמִירִין. י' סְלִיקוּ דִרְעוּתָּא הֲוִי, אִשְׁתַּכְלַל מֵרֵישָׁא לְעֵילָא ונָחַתּ לְתַּתָּא, נָפַּק ואַפִּיק תְּלָתִּין וּתְּרֵין שְׁבִילִין, עַד דְּאִתְּגְּלִיפּוּ בֵּין אַבְנֵי יְקָר דְּמִתְּלַהֲטָן. ואִתְּקַשָׁרוּ בְּאוֹתּ נו\"ן דְּאִיהוּ דְּכַר ונוּקְבָא, תְּרֵין רְחִימִין. קִשׁוּרָא תַּקִּיפָּא, בְּהוּ אִשְׁתַּכְלָלוּ, וּשְׁמָא קַדִּישָׁא בְּהוּ אִתְּקַשַׁר, מִנַּיְיהוּ אִשְׁתַּכַּח מְזוֹנָא לְכֹלָּא (בהו), אִשְׁתַּכְלָלוּ עַלְמִין.","ועַל דָּא אִתְּגְּלִיף ן' פְּשׁוּטָה, כְּלָלָא דִתְּרֵין, נ' כְּפּוּפָּה נוּקְבָא חָדָא, י' דְּאִיהִי רְעוּתָּא דְּאַפִּיק שְׁבִילִין, בָּטַשׁ בֵּין אַתְּוָון, וְעֲבַד רְקִיעָא דְיַעֲקֹב בֵּין תְּרֵין רוּחִין, ואַטִּיל בֵּינִי שַׁיְיפֵּי מִלּוּלֵי, עַד דְּנָחַתּ לְהַאי נ' דְּאִיהִי כְּפּוּפָּה, וחִבְרוּ לָהּ כְּחֲדָא, צָּפּוֹן ודָרוֹם, לְבָתַּר אִתְּקַשָׁרוּ כְּחֲדָא. הַאי נ' כְּפּוּפָּה, בְּאֵר שֶׁבַע אִקְרֵי. וְאִתְּמַלֵּי מִיַּעֲקֹב, לְאַשָׁקָאָה כָּל עֶדְרֵי עָנָא. ועַל דָּא ויֵּצֵּא יַעֲקֹב מִבְּאֵר שָׁבַע ויֵּלֶךָ חָרָנָה. תּוּ, מִבְּאֵר שָׁבַע לְעֵילָא, דְּהָא מִינָהּ נָפִּיק, לְבָתַּר אָזִיל לְאַשְׁקָאָה לְחָרָנָה, דְּאִיהוּ בֵּירָא דִלְתַּתָּא, חֲרוֹן אַף ה', חֶרְב ה', דִּינָא, בֵּי דִינָא, אֱלהִים. ועַל דָּא (תהילים ע״ט:א׳) אֱלֹהִים בָּאוּ גוֹיִם בְּנַחֲלָתֶּךָ. (עד כאן תוספתא)","רִבִּי יִצְחָק הֲוָה יָתִיב יוֹמָא חַד קַמֵּי מְעַרְתָּא דְּאֲפִיקוּתָא, אַעֲבַר חַד בַּר נָשׁ וּתְרֵין בְּנִין עִמֵּיהּ. וְהֲוָה אָמַר חַד לְחַד, דָּא תּוּקְפָא דְּשִׁמְשָׁא, מִסִּטְרָא דְּדָרוֹם אִיהוּ. וְעַלְמָא לָא אִתְקְיַּים אֶלָּא עַל רוּחַ, בְּגִין דְּרוּחַ אִיהוּ קִיּוּמָא שְׁלִימוּ דְּכָל סִטְרִין, וְאִלְמָלֵא דְּאִיהוּ קָיְימָא בִּשְׁלִימוּ, לָא יָכִיל עַלְמָא לְאִתְקַיָּימָא.","אָמַר לֵיהּ אֲחוּהָ זְעֵירָא, אִלְמָלֵא יַעֲקֹב, לָא אִתְקְיַּים עַלְמָא. תָּא חֲזֵי, בְּשַׁעְתָּא דְּיִיחֲדוּ בְּנוֹי יִחוּדָא דִלְעֵילָא, וְאָמְרוּ (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ אלֹהֵינוּ יְיָ אֶחָד, דָּא הוּא שְׁלִימוּ עִלָּאָה, לְאִתְיַחֲדָא בְּיִחוּדָא חַד. כְּדֵין אִתְחַבַּר יַעֲקֹב אֲבוּהוֹן וְנָטִיל בֵּיתֵיהּ, וְיָתִיב בֵּיהּ בְּחִבּוּרָא חָדָא עִם אֲבָהָן, לְאִתְחַבְּרָא דְּכַר וְנוּקְבָא כְּחֲדָא.","אָמַר רִבִּי יִצְחָק, אֶשְׁתַּתַּף בַּהֲדַיְיהוּ, וְאֶשְׁמַע מַאי קָאַמְרֵי. אֲזַל בַּהֲדַיְיהוּ. פָּתַח הַהוּא בַּר נַשׁ וְאָמַר, (תהילים קל״ב:ח׳) קוּמָה יְיָ לִמְנוּחָתֶךָ אַתָּה וַאֲרוֹן עֻזֶּךְ. קוּמָה יְיָ לִמְנוּחָתֶךָ, כְּמַאן דְּאָמַר, יְקוּם מַלְכָּא, לְבֵי נַיְיחָא דְּמַשְׁכְּנֵיהּ.","תְּרֵין אִינוּן הֲווּ דְּאָמְרוּ קוּמָה יְיָ, משֶׁה וְדָוִד. משֶׁה אָמַר, (במדבר י׳:ל״ה) קוּמָה יְיָ וְיָפוּצוּ אוֹיְבֶיךָ. וְדָוִד אָמַר, קוּמָה יְיָ לִמְנוּחָתֶךָ. מַאי אִיכָּא בֵּינַיְיהוּ. אֶלָּא משֶׁה כְּמַאן דְּפָּקִּיד לְבֵיתֵיהּ קָאֲמַר, משֶׁה פַּקִּיד לָהּ, לְאֲגָחָא קְרָבָא לָקֳבֵיל שַׂנְאוֹי. דָּוִד זָמִּין לֵיהּ לְנַיְיחָא, כְּמָה דְּמַזְמִין (ליה) לְמָרִיהּ, זַמִּין לְמַלְכָּא וּלְמַטְרוֹנִיתָא עִמֵּיהּ, הֲדָא הוּא דִכְתִיב, קוּמָה יְיָ לִמְנוּחָתֶךָ אַתָּה וַאֲרוֹן עֻזֶּךָ, בְּגִין דְּלָא לְאַפְרָשָׁא לוֹן.","(תהילים קל״ב:ט׳) כֹּהֲנֶיךָ יִלְבְּשׁוּ צֶדֶק וַחֲסִידֶיךָ יְרַנֵּנוּ. מִכָּאן אוֹלִיפְנָא, דְּמַאן דִּמְזַמֵּן לְמַלְכָּא, יְשַׁנֵּי עוֹבָדוֹי בְּגִין לְמֵיהַב חֶדְוָה לְמַלְכָּא. אִי אָרְחֵיהּ דְּמַלְכָּא דְּחָדָאן לֵיהּ בְּדִיחֵי הֶדְיוֹטֵי, יְסַדַּר קַמֵּיהּ בְּדִיחֵי רוֹפִינוּס וּפַרְדַּשְׁכֵי, וְאִי לָאו, לָאו אִיהוּ (בגין) בְּדִיחוּתָא דְמַלְכָּא.","תָּא חֲזֵי, דָּוִד זַמִּין לֵיהּ לְמַלְכָּא וּלְמַטְרוֹנִיתָא לְנַיְיחָא, מָה עֲבַד, שָׁנֵי בְּדִיחֵי דְמַלְכָּא, בְּגִין רוֹפִינוּס. וּמַאן נִינְהוּ, דִּכְתִיב, (תהילים קל״ב:ט׳) כֹּהֲנֶיךָ יִלְבְּשׁוּ צֶדֶק וַחֲסִידֶיךָ יְרַנֵּנוּ. (ר\"ל ע\"ב, רל\"ד ע\"א) וַחֲסִידֶיךָ יְרַנֵּנוּ, לְוִיֶּיךָ יְרַנֵּנוּ מִבָּעֵי לֵיהּ, דְּהָא לֵיוָאֵי אִינוּן בְּדִיחֵי מַלְכָּא. וְהַשְׁתָּא דָּוִד דְּזַמִּין לֵיהּ לְנַיְיחָא, עֲבַד כֹּהֲנֵי וַחֲסִידֵי דְּלֶיהווּ אִינוּן בְּדִיחֵי מַלְכָּא.","אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, דָּוִד, לָא בָעֵינָא לְאַטְרָחָא עֲלָךְ. (אלין) (נ\"א אמר ליה קודשא בריך הוא, דוד, לאו הכי) אָמַר לֵיהּ דָּוִד, מָארִי (לאו הכי אלא), כַּד אַנְתְּ בְּהֵיכָלָךְ, אַתְּ עָבִיד רְעוּתָךְ. הַשְׁתָּא דְּזַמִּינְנָא לָךְ, בִּרְעוּתִי קַיְימָא מִלָּה לְאַקְרָבָא אִלֵּין, דְּאִינוּן חֲשִׁיבֵי יַתִּיר, אַף עַל גַּב דְּלָאו אָרְחַיְיהוּ בְּהַאי.","מִכָּאן אוֹלִיפְנָא, דְּמַאן דְּאִיהוּ בְּבֵיתֵיהּ, יְסַדֵּר אוֹרְחֵיהּ וְעוֹבָדֵיהּ כִּרְעוּתֵיהּ. אִי מְזַמְּנִין לֵיהּ, יַעֲבִיד רְעוּתֵיהּ דְּאוּשְׁפִּיזֵיהּ, כְּמָה דִמְסַדַּר עֲלוֹי. דְּהָא דָוִד אַחְלַף לֵיוָאֵי וְסַדַּר כַּהֲנֵי, וְקוּדְשָׁא בְּרִיךְ הוּא אוֹקִים מִלָּה כִּרְעוּתֵיהּ.","אָמַר דָּוִד, בַּעֲבוּר דָּוִד עַבְדֶּךָ אַל תָּשֵׁב פְּנֵי מְשִׁיחֶךָ סִדּוּרָא דְּקָא סַדַּרְנָא, לָא יְתוּב לַאֲחוֹרָא. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, דָּוִד, חַיֶּיךָ, אֲפִילּוּ בְּמָאנִין דִילִי לָא אֶשְׁתַּמֵּשׁ, אֶלָּא בְּמָאנִין דִּילָךְ. וְלָא זָז קוּדְשָׁא בְּרִיךְ הוּא מִתַּמָּן, עַד דְּיָהִיב לֵיהּ נְבַזְבְּזָן וּמַתְּנָן, דִּכְתִיב, (תהילים קל״ב:י״א) נִשְׁבַּע יְיָ לְדָוִד אֱמֶת לא יָשׁוּב מִמֶּנָּהּ מִפְּרִי בִטְנְךָ אָשִׁית לְכִסֵּא לָךְ. אֲתָא רִבִּי יִצְחָק וּנְשָׁקֵיהּ, אָמַר אִי לָא אֲתֵינָא לְהַאי אָרְחָא, אֶלָּא לְמִשְׁמַע דָּא דַּיַּי.","פָּתַח חַד בְּרֵיהּ וְאָמַר, (בראשית כ״ח:י׳) וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה, הַיְינוּ דִּכְתִיב, (בראשית ב׳:כ״ד) עַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ וְדָבַק בְּאִשְׁתּוֹ. דָבָר אַחֵר וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה, רָמַז כַּד נָפְקוּ יִשְׂרָאֵל מִבֵּי מַקְדְּשָׁא, וְאִתְגָּלוּ בֵּינֵי עַמְמַיָא, כְּמָה דְאַתְּ אָמֵר, (איכה א׳:ו׳) וַיֵּצֵא מִן בַּת צִיּוֹן כָּל הֲדָרָהּ, וּכְתִיב גָּלְתָה יְהוּדָה מֵעוֹנִי וְגו'.","פָּתַח אָחֳרָא זְעֵירָא וְאָמַר, (בראשית כ״ח:י״א) וַיִּפְגַּע בַּמָּקוֹם וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ וְגו', מַאי (מ\"ט ע\"ב) וַיִּפְגַּע בַּמָּקוֹם, לְמַלְכָּא דְּאָזִיל לְבֵי מַטְרוֹנִיתָא, בָּעֵי לְמִפְגַע לָהּ וּלְבַסְּמָא לָהּ בְּמִלִּין, בְּגִין דְּלָא תִשְׁתַּכַּח גַּבֵּיהּ כְּהֶפְקֵירָא. וְלָא עוֹד, אֶלָּא דְּאָפִילּוּ אִית לֵיהּ עַרְסָא דְדַהֲבָא, וּכְסוּתוּתֵי מְרַקְמָאן בְּאַפְלַטְיָיא, לְמֵיבַת בְּהוּ. וְאִיהִי מְתַקְּנָא עַרְסֵיהּ בְּאַבְנִין (פנחס רכ\"ג ע\"א, רמ\"ג ע\"ב) בְּאַרְעָא, וּבְקִיסְטְרָא דְּתִיבְנָא. יִשְׁבּוֹק דִּידֵיהּ, וְיָבִית בְּהוּ לְמֵיהַב לָהּ נַיְיחָא, וּבְגִין דִּיהֵא רְעוּתָא דִלְהוֹן כְּחֲדָא, בִּדְלָא אֲנִיסוּ. כְּמָה דְאוֹלִיפְנָא הָכָא, דְּכֵיוָן דְּאֲזַל לְגַבָּהּ מַה כְּתִיב, (וילן שם כי בא השמש לאחזאה דאסיר ליה לבר נש לשמשא ערסיה ביומא) (בראשית כ״ח:י״א) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם וַיָּשֶׂם מֵרַאֲשׁוֹתָיו (שם) וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא, בְּגִין לְמֵיהַב לָהּ נַיְיחָא, דְּאָפִילּוּ אַבְנֵי בֵיתָא, רְחִימִין קַמֵּיהּ, לְמֵיבַת בְּהוּ. (ס\"א דכתיב וישכב במקום ההוא)","בָּכָה רִבִּי יִצְחָק, (ד\"א ל\"ג וחייך) וְחָדֵי, אָמַר מַרְגְּלָאן אִלֵּין תְּחוֹת יְדַיְיכוּ, וְלָא אֵזִיל בַּתְרַיְיכוּ. אָמְרוּ לֵיהּ אַתְּ תֵּזִיל לְאוֹרְחָךְ, וְאֲנַן נֵיעוּל לְמָתָא לְהִלּוּלָא דְהַאי בְּרִי. אָמַר רִבִּי יִצְחָק, הַשְׁתָּא אִית לִי לְמֵהַךְ לְאָרְחִי. אָזִיל לֵיהּ, וְסִדֵּר מִלִּין קַמֵּיהּ דְּרִבִּי שִׁמְעוֹן. אָמַר רִבִּי שִׁמְעוֹן וַדַּאי שַׁפִּיר קָאֲמְרוּ, וְכֹלָּא בְּקוּדְשָׁא בְּרִיךְ הוּא אִתְּמָר. אָמַר, מִלִּין אִלֵּין, מִבְּנֵי בְּנוֹי דְּרִבִּי צָדוֹק חֲלָשָׁא נִינְהוּ. מַאי טַעְמָא אִקְּרֵי חֲלָשָׁא, בְּגִין דְּאַרְבָּעִין שְׁנִין אִתְעַנֵּי עַל יְרוּשְׁלֵם, דְּלָא יִתְחְרַב בְּיוֹמוֹי, וְהֲוָה פָּרִישׁ עַל כָּל מִלָּה וּמִלָּה דְאוֹרַיְיתָא, רָזִין עִלָּאִין, וְיָהִיב בְּהוּ אָרְחָא לִבְנֵי עָלְמָא, לְאִתְנַהֲגָא בְּהוּ."],[[0,"יעקב נחת לגבה וכו':","יעקב, ירד אליה, לאשת זנונים והלך למקומה, שנאמר, וילך חרנה, שהיא חרון אף ודינים, וראה שם כל תקון ביתה, וניצל ממנה, וחזר לארץ ישראל. הזכר שלה שהוא סמאל, הרע לו הדבר, מה שניצל ממנה, וירד להלחם עמו ולא יכול לו, שכתוב ויאבק איש עמו וגו'. אז הוא ניצל מכולם, ונשלם בשלימות ונתעלה במדרגה שלמה, שהוא מדרגת חיה, (כנ\"ל דף י\"ב ד\"ה פירוש ע\"ש) ונקרא ישראל שהוא נוטריקון \u0003לי ראש.\u0004 אז עלה במדרגה העליונה ונשלם בכל, ונעשה עמוד האמצעי, ועליו כתוב, והבריח התיכון וגו'. פירוש. כי מקודם לכן בעת שהיה במדרגת יעקב, היה נוטה לימין בעיקר, ולא היה לו ראש ממש אלא בחינת רישא דמהימנותא, אבל עתה אחר שנתנסה בחרן ובסמאל, וניצל מהם, זכה למדרגת חיה, שפירושו שקו אמצעי מקיים הארת שני הקוים, ואינו נוטה לא לימין ולא לשמאל, ואז יש לו ראש ממש, ונקרא ישראל, ונבחן לעמוד האמצעי, המקיים הארת שני הקוין."],[1,"","(ל\"ג מן מהו ויגע עד סוף הסתרי תורה)."],[2,"בני עלמא רחימי עלאה וכו':","בני העולם אהובי עליון, בחירי הממשלה. כלומר התוספתא מזמינה לאלו שזכו להארת ג' קוין, שמצד הארת קו אמצעי מכונים \u0003בני העולם,\u0004 כי ז\"א שהוא קו אמצעי מכונה \u0003עולם\u0004 ומצד הארת קו הימין מכונים \u0003אהובי עליון.\u0004 ומצד הארת קו השמאל מכונים בחירי הממשלה, דהיינו שנבחרו לשלוט בעולם. כי כח השליטה מקו שמאל הוא. קרבו שמעו, מי חכם ביניכם בעלי עינים שבתבונה, כלומר, בעלי חכמה שבתבונה כי עינים, כינוי החכמה היא, והוא לאפוקי חכמה דאור ישר. יבא וידע: בשעה שראש הלבן, דהיינו עתיקא קדישא, לקח ג' אותיות, וחקק אותן בחקיקות, אחת \u0003א',\u0004 אחת \u0003י',\u0004 ואחת \u0003ן',\u0004 ונחקק \u0003אי\"ן:\u0004 אשר \u0003א'\u0004 הוא ראש העליון על כל. נסתר מכל נסתר דהיינו, הראש של א\"א, \u0003י'\u0004 הוא עליית הרצון שנשתכלל מן הראש למעלה, מראש דא\"א, וירד עם שכלולו למטה לזו\"ן, ומפרש, יצא, מראש דא\"א, והוציא ל\"ב שבילין בעת שחזר ונכנס לראש א\"א, עד שנחקקו בין אבני יקר הלוהטות. שה\"ס המסך דחירק. כי מסכים מכונים אבנים כנודע. ונתקשרו באות \u0003ן',\u0004 שהוא סוד התכללות של זכר ונקבה, ב' אוהבים, קשר חזק נשתכלל בהם, והשם הקדוש י\"ה ו\"ה נתקשר בהם, מהם נמשך מזונות לכל, ונשתכללו העולמות, שהם זו\"ן."],[2,"","פירוש. נודע, כי כל המוחין נמשכים בסוד ג' זריעות, המכונות חולם שורק חירק, שתוכנם נתבאר לעיל (בראשית א' דף ט\"ו ד\"ה ההיא נקודה עש\"ה) וז\"ש \u0003דרישא חוורא\u0004 שהוא עתיקא קדישא, \u0003נטיל תלת אתוון וגליף לון בגלופא וכו',\u0004 דהיינו ג' זריעות הנ\"ל הנבחנות לחקיקות. \u0003א' רישא עלאה דכלא,\u0004 דהיינו א\"א הנבחן לראש העליון על כל המדרגות של ד' העולמות אבי\"ע, אבל עתיקא קדישא לא נחשב לראש אלא לא\"א לבדו, ולא להמדרגות שלמטה ממנו, מטעם היותו מצמצום א' (כנ\"ל בראשית א' דף ו' ד\"ה אחר) ורק א\"א, הוא הראשון שקבל לתוכו את הצמצום ב' שה\"ס עלית המלכות לבינה שלו, כמ\"ש שם. ועכ\"ז הוא \u0003טמירא דכל טמירין\u0004 כי ממנו עצמו עוד לא יכלו העולמות לקבל, שה\"ס חכמה קדומה שנסתמה, וכל מה שהתחתונים מקבלים הוא רק מן הבינה שלו, על ידי יציאתה מראש א\"א וחזירתה אליו, ובינה זו ה\"ס אות \u0003י',\u0004 שכוללת בתוכה ארבע פרצופין, או\"א וישסו\"ת כנודע."],[2,"","וז\"ש, \u0003י' סליקו דרעותא הוי,\u0004 שסוד עלית הרצון, שהיא עלית המלכות לבינה, ב \u0003י'\u0004 זו היתה. \u0003אשתכלל מרישא לעילא,\u0004 היא קבלה שכלולה מראש שלמעלה, דהיינו מראש א\"א, \u0003ונחת לתתא,\u0004 והיא ירדה עם שכלולה זה שקבלה, ומשפעת אותו אל זו\"ן שלמטה. ומבאר איך נעשה הדבר, דהיינו איך שקבלה למעלה והשפיעה למטה. ואומר, \u0003נפק, ואפיק תלתין ותרין שבילין,\u0004 יצאה לבר מראש דא\"א, והוציאה ל\"ב שבילין. שע\"י עליית המלכות לראש א\"א יצאה הבינה וגם תו\"מ, מראש דא\"א לבחינת גוף, דהיינו ו\"ק בלי ראש, ונשאר בראש א\"א רק כתר וחכמה. וכן בינה ותו\"מ של ע\"ס הבינה, ירדו לבחינת זו\"ן, ונשארה הבינה בכתר וחכמה דכלים וו\"ק דאורות. ואחר זה לעת גדלות החזיר א\"א את הבינה לראשו. וכן הבינה החזירה למדרגתה, את בינה ותו\"מ שלה שנפלו לזו\"ן, וגם זו\"ן באו אז עם הבינה ותו\"מ ביחד למדרגת בינה להיותם דבוקים בהם, ונמצאת אז הבינה בסוד ל\"ב שבילין, דהיינו עשר ספירות של עצמה, וכ\"ב אותיות שהם הכלים דזו\"ן שעלו אליה. ונמצא שעל ידי יציאתה לחוץ מראש א\"א, הורידה את בינה ותו\"מ מע\"ס שלה, ונתדבקו בזו\"ן, שמסבה זו, אח\"כ בעת גדלות, עלו זו\"ן עם בינה ותו\"מ הללו אל מדרגת הבינה, ונעשתה לל\"ב שבילין, וז\"ש \u0003נפק ואפיק ל\"ב שבילין.\u0004 שבסבת יציאתה לבר מראש דא\"א, הוציאה בתוכה ל\"ב בחינות, הנקר' שבילין, עשרה מעצמה, וכ\"ב מזו\"ן."],[2,"","ונודע, שבחינת כתר וחכמה, שנשארו בבינה בעת יציאתה לחוץ, ה\"ס ב' אותיות מ\"י של אלקים וה\"ס נקודת החולם, וקו ימין. ובינה ותו\"מ של ע\"ס שלה, שהחזירה בעת גדלות, עם זו\"ן הדבוקים בהם, ה\"ס, ג' אותיות אל\"ה שחזרו והשלימו את השם אלקים, וה\"ס נקודת השורק. וקו שמאל. ומפאת חסרון לבוש יקר אל החכמה, נעשה השם אלקים סתים בשמא שהחכמה אינה יכולה להאיר, \u0003עד דאתלבש בלבוש יקר דנהיר,\u0004 דהיינו לבוש מחסדים, ואז מאירה, (כנ\"ל בהקדמת ספר הזהר דף כ\"ב ד\"ה קיימא ע\"ש) וז\"ש \u0003עד דאתגליפו בין אבני יקר דמטלהטן,\u0004 אבני, ה\"ס המסך שנמצא בזו\"ן שעלו בבינה, ואחר שהבינה מוציאה קומת חסדים על מסך זה שבזו\"ן, מתחברים ב' הקוין ימין ושמאל שלה, והחכמה מתלבשת בחסדים אלו שיצאו ממסך דזו\"ן, ונעשה לה ל \u0003לבוש יקר דנהיר,\u0004 וע\"כ מכונה המסך בשם \u0003אבני יקר.\u0004 ואומרו \u0003דמתלהטן,\u0004 הוא, משום שבערך הבינה, יש במסך זה בחינת דינים, להיותו מסך דבחי\"א. ועל כן, \u0003ואתקשרו באות ן' דאיהו דכר ונוקבא, תרין רחימין,\u0004 שהם זו\"ן כמו שהזהר מבאר בדיבור שלאחר זה, כי מתוך שב' הקוין דבינה היו סתומים מקודם שנזדווגה על מסך דזו\"ן, וע\"י המסך דזו\"ן נפתחו להאיר, על כן נתקשרו בזו\"ן. \u0003קשורא תקיפא בהו אשתכללו,\u0004 קשר חזק נשתכלל בהם, בזו\"ן הכלולים ב \u0003ן',\u0004 כי אין החכמה שבבינה יכולה להאיר זולתם, דהיינו זולת לבוש יקר שמקבלת מן הזווג שעל המסך שלהם. \u0003ושמא קדישא בהו אתקשר,\u0004 והשם הקדוש י\"ה ו\"ה נתקשר על ידם, כי י\"ה שה\"ס בינה, ש \u0003י'\u0004 ה\"ס ג\"ר דבינה המלובשים תוך או\"א עלאין, ו \u0003ה'\u0004 ה\"ס ז\"ת דבינה המלובשים תוך ישסו\"ת, הם נתקשרו בב' אותיות \u0003ו\"ה\u0004 שהם זו\"ן, מפני שה \u0003י\"ה\u0004 אינם יכולים להאיר זולתם כנ\"ל. \u0003מנייהו אשתכח מזונא לכלא,\u0004 וע\"י התקשרות י\"ה בו\"ה, נמצא שפע מזונות לכל, כלומר בין חכמה ובין חסדים. \u0003אשתכללו עלמין,\u0004 שעי\"ז נשתכללו זו\"ן הנקראים עלמין, כי תחתון הגורם תוספת אור לעליון, זוכה גם הוא כל אותו השיעור שגרם אל העליון, וע\"כ נשתכללו זו\"ן שה\"ס \u0003ן'\u0004 פשוטה, במוחין של הבינה. ונתבאר היטב איך \u0003הי' אשתכלל מרישא לעילא,\u0004 דהיינו מראש דא\"א \u0003ונחת לתתא,\u0004 דהיינו לזו\"ן, כנ\"ל."],[3,"ועל דא אתנליף ן' פשוטה וכו':","הזהר חוזר, על הדברים הנ\"ל ומבארם יותר. ואומר, ועל זה נחקק \u0003ן'\u0004 פשוטה, שהוא כלל של זכר ונקבה, שהם זו\"ן, כי \u0003נ'\u0004 כפופה, היא נוקבא בלבדה, בלי דכר, \u0003י'\u0004 שהיא הרצון, דהיינו הבינה, שהוציא ל\"ב שבילין, הכה בין האותיות, דהיינו בכ\"ב אותיות, שהם זו\"ן, כמ\"ש לעיל בסוד \u0003אבני יקר דמתלהטן,\u0004 ועשה את הרקיע שהוא יעקב, דהיינו קו אמצעי, בין ב' הרוחות דרום צפון, שהם קו ימין וקו שמאל, והטיל חבור בין הגזרים, דהיינו \u0003מ\"י אל\"ה\u0004 שנתבתרו בתוך, ונעשו לימין ושמאל המכחישים זה את זה, ועתה על ידי זווג דהכאה על מסך דחירק שהוציא את קו האמצעי, חזרו ונתחברו יחד. ויצאו בזה ג' קוין בקו אמצעי עצמו, כנ\"ל בדבור הסמוך. \u0003עד דנחת,\u0004 עד שירד יעקב, \u0003להאי נ' דאיהי כפופה וחברו לה כחדא צפון ודרום,\u0004 עד שירד יעקב אל ה \u0003נ'\u0004 כפופה שהיא הנוקבא, וב' הקוין שלו ימין ושמאל נתחברו בה כאחד, שבזה נבנית הנוקבא, ונעשית ראויה לזווג, \u0003לבתר אתקשרו כחדא,\u0004 אחר זה נתקשרו יעקב והנוקבא כאחד, ונעשו אות \u0003ן'\u0004 פשוטה, שהוא כוללת יעקב ונוקבא."],[3,"האי נ' כפופה וכו': נ'","בכופה זו שהיא הנוקבא, הכלולה ב \u0003ן'\u0004 פשוטה, נקראת באר שבע והיא מתמלאת מיעקב, כנ\"ל בסמוך, להשקות כל עדרי הצאן, דהיינו להשמיע לתחתונים. ועל כן, אומר הכתוב, ויצא יעקב מבאר שבע וילך חרנה. פירוש. שיעקב היה דבוק ב \u0003נ'\u0004 כפופה ביחד בסוד \u0003ן'\u0004 הפשוטה, שאז בחבור הזה, נקראת ה \u0003נ'\u0004 כפופה \u0003באר שבע.\u0004 ואומר הכתוב, שיצא מחיבורו זה עם באר שבע, וילך חרנה שהיא שמאל וחרון אף."],[3,"תו, מבאר שבע וכו':","עוד, יש לומר, \u0003מבאר שבע,\u0004 פירושו למעלה, דהיינו בינה, כי ממנה יוצא, ומקבל שפעו, וע\"כ נאמר עליה ויצא יעקב מבאר שבע, ואחר כך הולך להשקות את \u0003חרן,\u0004 שהוא הבאר של מטה, דהיינו הנוקבא, שבה הדינים המכונים חרון אף ה', וכן חרב ה', שבה הדין של בית הדין הנק' אלקים, וע\"כ אומר הכתוב על שם אלקים, אלקים באו גוים בנחלתך. כי משם הזה נמשכים הדינים. ושיעור הכתוב, \u0003ויצא יעקב,\u0004 היינו שיצא עם שפע, מן הבינה, שנקראת \u0003באר שבע וילך לחרן,\u0004 והלך להשפיע את השפע אל הנוקבא הנקראת חרן בעת שהוא מחוסרת שפע. (ע\"כ תוספתא)."],[4,"רבי יצחק הוה יתיב וכו':","רבי יצחק, היה יושב יום אחד לפני מערת אפיקותא. עבר אדם אחד ושני בניו עמו, והיה אמר אחד לשני, תקפו זה של השמש שהוא ז\"א, הוא מצד דרום, שה\"ס ימין, חסדים. והעולם, שהוא הנוקבא, אינו מתקיים אלא על רוח, שהוא קו אמצעי, משום שהרוח הוא הקיום והשלמות מכל הצדדים, כי קו אמצעי שהוא רוח, כולל ב' הצדדים דרום וצפון, ימין ושמאל, שה\"ס חכמה וחסדים, ואלמלא שהוא נמצא בשלמות, לא היה העולם, שהיא הנוקבא, יכול להתקיים."],[5,"א\"ל אחוה זעירא וכו':","אלמלא יעקב לא נתקיים העולם. בוא וראה, בשעה שיחדו בניו יחוד העליון ואמרו שמע ישראל ה' אלקינו ה' אחד, (ביאורו תמצא בהקדמת ספר הזהר בפקודא תליתאה דף קצ\"ג ודף רמ\"ב עש\"ה) שזה הוא שלימות העליון, מאו\"א, להתיחד ביחוד אחד (כמ\"ש שם) אז נתחבר יעקב אביהם, שהוא קו אמצעי, ת\"ת, ולקח ביתו, שהוא הנוקבא, שה\"ס יחוד התחתון, וישב בו בחבור אחד עם האבות, שהם ב' הקוין ימין ושמאל, כדי להתחבר דכר נוקבא כאחד. כי אין זווג דכר ונוקבא מטרם שקו אמצעי, שהוא יעקב, מכריע ומתחבר בב' הקוין ימין ושמאל, שהם אברהם ויצחק, כנודע."],[6,"אמר רבי יצחק וכו':","אר\"י, אשתתף עמהם, ואשמע מה שאומרים. הלך עמהם. פתח אותו האיש ואמר. קומה ה' למנוחתך אתה וארון עוזך. \u0003קומה ה' למנוחתך\u0004 פירושו, כמי שאומר, יקום המלך לבית המנוחה, למשכנו."],[7,"תרין אנון וכו':","שנים הם שאמרו \u0003קומה ה'\u0004 משה ודוד. משה אמר קומה ה' ויפוצו אויביך. ודוד אמר קומה ה' למנוחתך מה יש ביניהם. אלא משה שהוא בעלה דמטרוניתא אמר, כמי שמצוה לביתו: משה, צוה לה לעשות מלחמה עם שונאיו. דוד, הזמין אותו למנוחה, כאיש המזמין לביתו את רבונו. הזמין את המלך והגבירה עמו, וזהו שכתוב, קומה ה' למנוחתך, אתה, שהוא המלך, וארון עוזך, שהוא הנוקבא, בשביל שלא להפריד ביניהם."],[7,"","ביאור הדברים. \u0003קומה,\u0004 פירושו המשכת חכמה וג\"ר. בדומה לאיש הקם על רנליו שהוא זוקף קומתו. ויש ב' מיני קימה, א) שממשיך הארת השורק שה\"ס הארת חכמה בלי חסדים, כדי להכניע האויבים, דהיינו הס\"א. שאין הסטרא אחרא נכנעת, אלא על ידי הארת החכמה. ובעת הזאת אין זווג לזו\"ן, כי אז השליטה הוא לקו השמאל, ולא לימין שהוא ז\"א."],[7,"","ב) שממשיך הארת החכמה, מסוד קו השמאל שהוא נקודת השורק, כדי להשלים עמה את החסדים בג\"ר, ע\"י התכללות ב' הקוין ימין ושמאל זה בזה, אשר אז באים החסדים בסוד \u0003המנוחה,\u0004 שפירושו, שלמות הסופי, שאין אחריה עוד מה להוסיף. ונמצא המשכה זו, הוא הזמנה לזווג זו\"ן, שז\"א שה\"ס קו ימין לאחר שנשלם בעת הזווג מהארת החכמה שבנוקבא, הוא משפיע אז אור שלם של חסדים אל הנוקבא, שהוא בבחינת ג\"ר, שה\"ס המנוחה. כמבואר."],[7,"","וזהו ההפרש בין משה לדוד, כי משה, להיותו מרכבה לז\"א, שהוא בעלה דמטרוניתא, היה בכחו להמשיך אל הנוקבא, גם את הקימה דמין הא', שה\"ס הארת השמאל בלי ימין, כנ\"ל, ואף על פי שמפרידה אז מן בעלה, אין בכך כלום, כי אחר שמגלה הארתה והאויבים נכנעים, הוא מחזירה תכף אצלו, ומשפיע לה חסדים ונשלמת מחכמה וחסדים יחדיו. וזסו\"ה, שתחילה אמר, \u0003קומה ה' ויפוצו אויביך,\u0004 דהיינו שהמשיך לה הארת החכמה משמאל בלי ימין כדי להפיץ האויבים. ותכף אחר זה אמר, \u0003שובה ה',\u0004 דהיינו שהחזירה לזווג, \u0003רבבות אלפי ישראל.\u0004 והשיגה עתה חסדים וחכמה, כי \u0003רבבות\u0004 הם חסדים \u0003ואלפי,\u0004 ה\"ס חכמה. (כנ\"ל דף ה' ד\"ה והארותיה)."],[7,"","וז\"ש, \u0003משה כמאן דפקיד לביתיה קאמר,\u0004 כי להיותו מרכבה לז\"א שהוא בעלה יכול לצוות עליה כרצונו, ואפילו להפרידה ממנה כרגע, \u0003משה פקיד לה לאגחא קרבא לקביל שנאוי,\u0004 ועל כן היה מצוה אותה להכניע השונאים, שה\"ס הקימה דמין הא' אעפ\"י שנפרדה ממנו, כי תכף היה מחזירה לזווג, בסוד שאמר, \u0003שובה ה' רבבות אלפי ישראל\u0004 כנ\"ל. אבל \u0003דוד, זמין ליה לנייחא,\u0004 כי הזמין והמשיך סוד הקימה דמין הב' אל הנוקבא, שהיא בשביל המנוחה, שפירושו כדי להגדיל את החסדים בג\"ר, שהוא שלימות הסופי הנקרא מנוחה, כנ\"ל. ונמצא, שמה שהמשיך הקימה אל הנוקבא, הוא רק להגדיל את החסדים שבז\"א, וז\"ש, \u0003כמה דמזמין למריה,\u0004 שאע\"פ שהזמין הקימה אל הנוקבא, לא היה זה אלא בשביל \u0003מריה\u0004 שהוא ז\"א, \u0003זמין למלכא ולמטרוניתא עמיה,\u0004 כלומר שהמטרוניתא שה\"ס הנוקבא, שקבלה הקימה, תתכלל בזווג עם מלכא, שה\"ס החסדים, שעל ידי התכללות הזה ישיגו החסדים דז\"א את הג\"ר שלהם בסוד המנוחה כנ\"ל. \u0003הה\"ד קומה ה' למנוחתך,\u0004 שהזמין את הקימה בשביל המנוחה דהיינו להגדיל את החסדים בג\"ר. \u0003אתה וארון עזך, בגין דלא לאפרשא לון.\u0004 כדי שהזווג המרומז ב \u0003אתה\u0004 שהוא ז\"א, \u0003וארון עזך\u0004 שהוא הנוקבא, לא יפסוק ח\"ו. כי אם היה ממשיך הקימה דמין הא' הנ\"ל היה נעשה בעת ההוא פירוד בין זו\"ן, כנ\"ל אצל משה, ודוד להיותו רק מרכבה אל הנוקבא, לא היה רוצה לגרום את זה אפילו לרגע."],[8,"כהניך ילבשו צדק וחסידיך ירננו וכו':","מכאן למדנו, שמי שמזמין את המלך, ישנה את מעשיו, כדי לגרום שמחה אל המלך, אם דרכו של המלך הוא, שמשמחים אותו בדחנים מפשוטי עם, יסדר לפניו בדחנים מכובדים ושרים גדולים, ואם לא יעשה כן, לא השלים שמחת המלך."],[9,"ת\"ח דוד זמין וכו':","בוא וראה. דוד הזמין את המלך והגבירה למנוחה. שאמר קומה ה' למנוחתך וגו', מה עשה, שינה את הבדחנים של המלך, באופן שיהיו שרים מכובדים, ומי המה, היינו שכתוב כהניך ילבשו צדק וחסידיך ירננו, שכתוב \u0003וחסידיך ירננו,\u0004 לוייך ירננו, היה צריך לומר, כי הלוים הם הבדחנים של המלך, ועתה, שדוד הזמין את המלך למנוחה, עשה, שהכהנים והחסידים יהיו הבדחנים של המלך. ולא הלוים."],[9,"","פירוש. כי שמחת המלך, שהוא ז\"א, באה מהמשכת המוחין דהארת החכמה שבקו שמאל, שה\"ס יין המשמח אלקים ואנשים. ולפיכך הלוים להיותם מקו שמאל, הם הממשיכים הארה זו, ונחשבים למשמחים את המלך. וזהו שמקשה, שהיה צריך לומר, \u0003לוייך ירננו,\u0004 כי הם הממשיכים מוחין ההם של רנה ושמחה. להיותם בחינת שמאל, ולמה אומר הכתוב, \u0003וחסידיך ירננו,\u0004 שהם מבחינת ימין, הממשיכים חסדים בלבד, כי על כן הם נקראים חסידים. וז\"ש \u0003דוד זמין ליה למלכא ולמטרוניתא לנייחא,\u0004 דהיינו שאמר קומה ה' למנוחתך וגו', שפירושו, שהזמין את הקימה דמין הא', שהוא המשכת הארת החכמה שבשמאל, להגדלת ג\"ר של החסדים, המביאם אל המנוחה, דהיינו לשלמותן הסופי כנ\"ל, נמצא בזה, ששינה את בדחני המלך, ובעלי הימין, הממשיכים תמיד חסדים, שהם הכהנים והחסידים, נעשו עתה מרכבה להארת החכמה שבשמאל, הנקרא יין המשמח אלקים ואנשים ונעשו הם הבדחנים של המלך ולא הלוים וז\"ש \u0003עביד כהני וחסידי דליהוו אינון בדיחי מלכא.\u0004 ועל כן אמר וחסידיך ירננו, ולא ולוייך ירננו."],[10,"א\"ל קב\"ה דוד וכו':","אמר לו הקב\"ה לדוד: דוד, איני רוצה להטריח את אלו, דהיינו את הכהנים והחסידים שימשיכו את הארת השמאל, כי הם בסו\"ה כי חפץ חסד הוא. אמר לו דוד, רבוני, כאשר אתה בהיכלך, אתה עושה כרצונך, דהיינו כמשה שה\"ס ז\"א, שאמר קומה ה' ויפוצו אויביך, שה\"ס הארת השמאל כשהוא בפני עצמו, שאז רק הלוים הם בדחני המלך, ולא הכהנים והחסידים, עתה שהזמנתי אותך, הרי הדבר תלוי ברצוני, שהוא, להקריב אליך את אלו החשובים יותר, שיהיו לבדחנים לפניך, דהיינו הכהנים והחסידים, אף על פי שאין דרכם בזה, כי הם בסו\"ה כי חפץ חסד הוא כנ\"ל."],[11,"מכאן אוליפנא וכו':","מכאן למדנו, שמי שהוא בביתו, יוכל לסדר דרכיו ומעשיו כרצונו, ואם מזמינים אותו, יעשה רצונו של מארחו, כמו שמסדר לפניו. שהרי דוד החליף הלוים ונתן הכהנים במקומם, והקב\"ה קיים הדבר כרצונו."],[12,"אמר דוד וכו':","אמר דוד, בעבור דוד עבדך אל תשב פני משיחך, הסדר, שסדרתי לא ישוב עוד לאחור, כלומר שלא יתבטל. אמר לו הקב\"ה, חייך, אפילו בכלים שלי לא אשתמש, אלא בכלים שלך (כמ\"ש להלן באות מ\"ב). ולא זז משם הקב\"ה, עד שנתן לו פזרונות ומתנות, שכתוב, נשבע ה' לדוד אמת לא ישוב ממנה מפרי בטנך אשית לכסא לך. בא רבי יצחק ונשקו, אמר אם לא באתי לדרך הזה, אלא בשביל לשמוע זה, דייני."],[13,"פתח חד בריה וכו':","פתח בן אחד, של אותו האיש הנזכר, ואמר, ויצא יעקב מבאר שבע וילך חרנה, היינו שכתוב, על כן יעזב איש את אביו ואת אמו ודבק באשתו. כי יעקב יצא מבאר שבע ועזב את אביו ואמו, וילך חרנה לישא אשה."],[13,"","ד\"א, \u0003ויצא יעקב וגו':\u0004 רומז, כשיצאו ישראל מבית המקדש ונגלו בין העמים. כמו שאתה אומר, ויצא מן בת ציון כל הדרה, וכתוב גלתה יהודה מעוני וגו'."],[14,"פתח אחרא זעירא וכו':","פתח בן האחר הצעיר, ואמר, ויפגע במקום וילן שם וגו'. שאל, מהו ויפגע במקום. ואמר, שזה דומה, למלך ההולך לבית הגבירה, שצריך לפייסה ולשמחה בדברים, כדי שלא תהיה נחשבת אצלו כדבר הפקר. ולא עוד, אלא אפילו אם יש לו, למלך, מטת זהב, וכסתות מרוקמות מעשה רוקם, ללון בהן, והיא עורכת לו מטתו מאבנים, על הארץ, ובחדר של תבן, יעזוב את שלו וילון בהם, כדי לעשות לה נחת רוח, וכדי שיהיו רצונם אחד, בלי כפיה. והוא שלמדנו כאן, שכיון שהלך אצלה יעקב, מה כתוב, ויקח מאבני המקום וישם מראשותיו וישכב במקום ההוא, שה\"ס הנוקבא (כנ\"ל באות ט') כדי לעשות לה נחת רוח, שאפילו אבני בית חביבים לו ללון בהם."],[15,"בכה רבי יצחק וכו':","בכה ר\"י, ושמח. אמר מרגליות אלו תחת ידיכם ולא אלך אחריכם. אמרו לו, אתה תלך לדרכך, ואנחנו נכנס אל העיר, לשמחת נשואים של בני. אמר רבי יצחק, עתה יש לי ללכת לדרכי. כי ראה שאין רצונם שילך עוד עמהם. הלך לו, וסידר הדברים לפני ר' שמעון: אמר רבי שמעון, ודאי יפה אמרו. והכל, מה שנאמר ביעקב נאמר בהקב\"ה, כמו שאמרו."],[15,"אמר מלין וכו':","אמר ר\"ש, דברים אלו מבני בניו של רבי צדוק החלש הם. מהו הטעם שנקרא חלש. הוא משום שארבעים שנה צם על ירושלים שלא תחרב בימיו. והיה מפרש על כל מלה ומלה שבתורה סודות עליונים ונתן בהם דרך לבני העולם, להתנהג על פיהם."]],[[0,"","יַעָקֹב יָרַד אֵלֶיהָ וְהָלַךְ לִמְקוֹמָהּ, שֶׁנֶּאֱמַר וַיֵּלֶךְ חָרָנָה, וְרָאָה אֶת כָּל תִּקּוּן הַבַּיִת, וְנִצַּל מִמֶּנָּה. הַזָּכָר שֶׁלָּהּ סמא\"ל, הֵרַע לְפָנָיו, וְיָרַד לַעֲרֹךְ בּוֹ קְרָב וְלֹא יָכֹל לוֹ, שֶׁכָּתוּב וַיֵּאָבֵק אִישׁ עִמּוֹ וְגוֹ'. אֲזַי נִצַּל מִן הַכֹּל, וְהִשְׁתַּלֵּם בִּשְׁלֵמוּת, וְהִתְעַלָּה בְּדַרְגָּה שְׁלֵמָה וְנִקְרָא יִשְׂרָאֵל. אָז עָלָה לְדַרְגָּה עֶלְיוֹנָה וְנִשְׁלַם בַּכֹּל וְנִהְיָה הָעַמּוּד הָאֶמְצָעִי, וְעָלָיו כָּתוּב וְהַבְּרִיחַ הַתִּיכֹן וְגוֹ'."],[1,"","מַהוּ וַיִּגַּע בְּכַף יְרֵכוֹ? לוֹ לֹא יָכֹל, אֲבָל נָגַע בְּכַף יְרֵכוֹ שֶׁהֵם נָדָב וַאֲבִיהוּא שֶׁיָּצְאוּ מִירֵכוֹ שֶׁל אַהֲרֹן, (בסבת אש זרה, והרי התעוררו לשמרך מאשה זרה וגו', ותפסה אותם ברשותה, בא ראה מה כתוב ביעקב השלם) (ועל יעקב כתוב) וְהַבְּרִיחַ הַתִּיכֹן בְּתוֹךְ הַקְּרָשִׁים מַבְרִחַ מִן הַקָּצֶה אֶל הַקָּצֶה."],[2,"","בְּנֵי הָעוֹלָם, אֲהוּבֵי עֶלְיוֹן, בְּחִירֵי הַמֶּמְשָׁלָה, קִרְבוּ שִׁמְעוּ. מִי חָכָם בָּכֶם, בַּעֲלֵי הָעֵינַיִם בְּהַשְׂכֵּל, יָבֹא וְיֵדַע. בְּשָׁעָה שֶׁהָרֹאשׁ הַלָּבָן נָטַל שָׁלֹשׁ אוֹתִיּוֹת וְחָקַק אוֹתָם בַּחֲקִיקַת הַחֲקִיקוֹת, אַחַת א', אַחַת י', וְאַחַת ן', וְנֶחְקַק אי\"ן - הָא' הָרֹאשׁ הָעֶלְיוֹן שֶׁל הַכֹּל טָמוּן שֶׁל כָּל הַטְּמוּנִים, י' הוּא עֲלִיַּת הָרָצוֹן, נִתְקַן מִן הָרֹאשׁ לְמַעְלָה, וְיָרַד לְמַטָּה. יָצָא וְהוֹצִיא שְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים, עַד שֶׁנֶּחְקְקוּ בַּאֲבָנִים יְקָרוֹת שֶׁלּוֹהֲטוֹת, וְנִקְשְׁרוּ עִם הָאוֹת נוּ\"ן, שֶׁהִיא זָכָר וּנְקֵבָה, שְׁנֵי אוֹהֲבִים. קֶשֶׁר חָזָק, בָּהֶם נִתְקְנוּ, וְהַשֵּׁם הַקָּדוֹשׁ נִקְשָׁר בָּהֶם, מֵהֶם נִמְצָא הַמָּזוֹן לַכֹּל (בהם), נִתְקְנוּ הָעוֹלָמוֹת."],[3,"","וְעַל כֵּן נֶחְקְקָה ן' פְּשׁוּטָה, הַכְּלָל שֶׁל שְׁתַּיִם: נ' כְּפוּפָה נְקֵבָה אַחַת, י' שֶׁהִיא הָרָצוֹן שֶׁמּוֹצִיא שְׁבִילִים הִכָּה בֵּין הָאוֹתִיּוֹת וְעָשָׂה אֶת הָרָקִיעַ שֶׁל יַעֲקֹב בֵּין שְׁתֵּי רוּחוֹת, וְהִטִּיל בֵּין הָאֵיבָרִים דִּבּוּרִים. עַד שֶׁיָּרַד לַנ' הַזּוֹ, שֶׁהִיא כְּפוּפָה, וְחִבְּרוּ אוֹתָהּ יַחַד, צָפוֹן וְדָרוֹם, אַחַר כָּךְ נִקְשְׁרוּ יַחַד. הַנ' הַכְּפוּפָה הַזּוֹ נִקְרֵאת בְּאֵר שֶׁבַע וּמִתְמַלֵּאת מִיַּעֲקֹב לְהַשְׁקוֹת אֶת כָּל עֶדְרֵי הַצֹּאן, וְעַל כֵּן וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה. עוֹד, מִבְּאֵר שֶׁבַע לְמַעְלָה, שֶׁהֲרֵי מִמֶּנָּה יוֹצֵא אַחַר כָּךְ לְהַשְׁקוֹת אֶת חָרָנָה, שֶׁהִיא הַבְּאֵר שֶׁלְּמַטָּה, חֲרוֹן אַף ה', חֶרֶב ה', דִּין, בֵּית הַדִּין, אֱלֹהִים. וְעַל כֵּן אֱלֹהִים בָּאוּ גוֹיִם בְּנַחֲלָתֶךְ. עד כאן התוספתא."],[4,"","רַבִּי יִצְחָק הָיָה יוֹשֵׁב יוֹם אֶחָד לִפְנֵי מְעָרַת אֲפִיקוּתָא. עָבַר אִישׁ אֶחָד וּשְׁנֵי בָנִים עִמּוֹ, וְהָיָה אֶחָד לְאֶחָד אוֹמֵר, חֹזֶק הַשֶּׁמֶשׁ הַזֶּה הוּא מִצַּד הַדָּרוֹם, וְאֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא עַל הָרוּחַ, מִשּׁוּם שֶׁהָרוּחַ הִיא קִיּוּם הַשְּׁלֵמוּת שֶׁל כָּל הַצְּדָדִים, וְאִלְמָלֵא שֶׁהוּא עוֹמֵד בִּשְׁלֵמוּת, אֵין הָעוֹלָם יָכוֹל לְהִתְקַיֵּם."],[5,"","אָמַר לוֹ אָחִיו הַקָּטָן, אִלְמָלֵא יַעֲקֹב, לֹא הִתְקַיֵּם הָעוֹלָם. בֹּא רְאֵה, בְּשָׁעָה שֶׁיִּחֲדוּ בָנָיו אֶת הַיִּחוּד שֶׁלְּמַעְלָה וְאָמְרוּ (דברים ו) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד, זוֹהִי הַשְּׁלֵמוּת הָעֶלְיוֹנָה לְהִתְיַחֵד בְּיִחוּד אֶחָד, אֲזַי הִתְחַבֵּר יַעֲקֹב אֲבִיהֶם, וְנָטַל אֶת בֵּיתוֹ, וְיָשַׁב בּוֹ בְּחִבּוּר אֶחָד עִם הָאָבוֹת, לְהִתְחַבֵּר זָכָר וּנְקֵבָה יַחַד."],[6,"","אָמַר רַבִּי יִצְחָק, אֶשְׁתַּתֵּף עִמָּהֶם וְאֶשְׁמַע מָה הֵם אוֹמְרִים. פָּתַח אוֹתוֹ הָאִישׁ וְאָמַר, קוּמָה ה' לִמְנוּחָתֶךְ אַתָּה וַאֲרוֹן עֻזֶּךְ. קוּמָה ה' לִמְנוּחָתֶךְ - כְּמִי שֶׁאוֹמֵר יָקוּם הַמֶּלֶךְ לְבֵית מְנוּחַת מִשְׁכָּנוֹ."],[7,"","שְׁנַיִם הֵם הָיוּ שֶׁאָמְרוּ קוּמָה ה' - מֹשֶׁה וְדָוִד. מֹשֶׁה אָמַר, (במדבר י) קוּמָה ה' וְיָפֻצוּ אֹיְבֶיךְ. וְדָוִד אָמַר (תהלים קלב) קוּמָה ה' לִמְנוּחָתֶךְ. מָה הַהֶבְדֵּל בֵּינֵיהֶם? אֶלָּא מֹשֶׁה, כְּמוֹ מִי שֶׁמְּצַוֶּה אֶת בֵּיתוֹ הוּא אָמַר. מֹשֶׁה צִוָּה אוֹתָהּ לְהִלָּחֵם קְרָב כְּנֶגֶד שׂוֹנְאָיו, וְדָוִד הִזְמִין אוֹתָהּ לִמְנוּחָה. כְּמוֹ שֶׁמַּזְמִין (לו) אֶת רַבּוֹ, מַזְמִין אֶת הַמֶּלֶךְ וְהַגְּבִירָה עִמּוֹ. זֶהוּ שֶׁכָּתוּב קוּמָה ה' לִמְנוּחָתֶךְ אַתָּה וַאֲרוֹן עֻזֶּךְ, כְּדֵי שֶׁלֹּא לְהַפְרִידָם."],[8,"","כֹּהֲנֶיךָ יִלְבְּשׁוּ צֶדֶק וַחֲסִידֶיךְ יְרַנֵּנוּ. מִכָּאן לָמַדְנוּ, שֶׁמִּי שֶׁמַּזְמִין אֶת הַמֶּלֶךְ, יְשַׁנֶּה אֶת מַעֲשָׂיו כְּדֵי לָתֵת שִׂמְחָה לַמֶּלֶךְ. אִם דֶּרֶךְ הַמֶּלֶךְ שֶׁמְּשַׂמְּחִים אוֹתוֹ בַּדְּחָנִים פְּשׁוּטִים - יְסַדֵּר לְפָנָיו בַּדְּחָנִים נִכְבָּדִים וְשָׂרִים גְּדוֹלִים, וְאִם לֹא - זוֹ לֹא (משום) שִׂמְחַת הַמֶּלֶךְ."],[9,"","בֹּא רְאֵה, דָּוִד הִזְמִין אֶת הַמֶּלֶךְ וְהַגְּבִירָה לִמְנוּחָה, מֶה עָשָׂה? שִׁנָּה אֶת בַּדְּחָנֵי הַמֶּלֶךְ בִּשְׁבִיל שָׂרִים וְנִכְבָּדִים, וּמִי הֵם? שֶׁכָּתוּב כֹּהֲנֶיךְ יִלְבְּשׁוּ צֶדֶק וַחֲסִידֶיךְ יְרַנֵּנוּ. וַחֲסִידֶיךְ יְרַנֵּנוּ? הָיָה צָרִיךְ לִהְיוֹת לְוִיֶּיךְ יְרַנֵּנוּ! שֶׁהֲרֵי הַלְוִיִּים הֵם בַּדְּחָנֵי הַמֶּלֶךְ, וְכָעֵת דָּוִד שֶׁהִזְמִין אוֹתוֹ לִמְנוּחָה, עָשָׂה אֶת הַכֹּהֲנִים וְהַחֲסִידִים שֶׁיִּהְיוּ הֵם בַּדְּחָנֵי הַמֶּלֶךְ."],[10,"","אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, דָּוִד, אֵינִי רוֹצֶה לְהַטְרִיחַ עָלֶיךְ. (אלו) (אמר לו הקדוש ברוך הוא, דוד, לא כך) אָמַר לוֹ דָּוִד, רִבּוֹנִי, (לא כך, אלא) כְּשֶׁאַתָּה בְּהֵיכָלְךְ, אַתָּה עוֹשֶׂה רְצוֹנְךְ. כָּעֵת שֶׁהִזְמַנְתִּי אוֹתְךְ, הַדָּבָר עוֹמֵד בִּרְצוֹנִי לְקָרֵב אֶת אֵלּוּ, שֶׁהֵם יוֹתֵר חֲשׁוּבִים, אַף עַל גַּב שֶׁאֵין דַּרְכָּם בָּזֶה."],[11,"","מִכָּאן לָמַדְנוּ, שֶׁמִּי שֶׁהוּא בְּבֵיתוֹ, יְסַדֵּר דַּרְכּוֹ וּמַעֲשֵׂהוּ כִּרְצוֹנוֹ. אִם מַזְמִינִים אוֹתוֹ, יַעֲשֶׂה אֶת רְצוֹנוֹ שֶׁל מְאָרְחוֹ כְּמוֹ שֶׁמְּסַדֵּר עָלָיו, שֶׁהֲרֵי דָּוִד הֶחְלִיף לְוִיִּים וְסִדֵּר כֹּהֲנִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֵקִים אֶת הַדָּבָר כִּרְצוֹנוֹ."],[12,"","אָמַר דָּוִד, בַּעֲבוּר דָּוִד עַבְדֶּךְ אַל תָּשֵׁב פְּנֵי מְשִׁיחֶךְ. הַסִּדּוּר שֶׁסִּדַּרְתִּי לֹא יָשׁוּב אָחוֹר. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, דָּוִד, חַיֶּיךְ, אֲפִלּוּ בַּכֵּלִים שֶׁלִּי לֹא אֶשְׁתַּמֵּשׁ, אֶלָּא בַּכֵּלִים שֶׁלְּךְ. וְלֹא זָז הַקָּדוֹשׁ בָּרוּךְ הוּא מִשָּׁם עַד שֶׁנָּתַן לוֹ אוֹצָרוֹת וּמַתָּנוֹת, שֶׁכָּתוּב נִשְׁבַּע ה' לְדָוִד אֱמֶת לֹא יָשׁוּב מִמֶּנָּה מִפְּרִי בִטְנְךְ אָשִׁית לְכִסֵּא לָךְ. בָּא רַבִּי יִצְחָק וְנָשַׁק לוֹ. אָמַר, אִם לֹא בָאתִי לַדֶּרֶךְ הַזּוֹ אֶלָּא לִשְׁמֹעַ אֶת זֶה - דַּי לִי."],[13,"","פָּתַח בֵּן אֶחָד שֶׁלּוֹ וְאָמַר, וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה, הַיְנוּ שֶׁכָּתוּב (בראשיתב) עַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ וְדָבַק בְּאִשְׁתּוֹ. דָּבָר אַחֵר וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה - רֶמֶז כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִבֵּית הַמִּקְדָּשׁ וְהֻגְלוּ בֵּין הָעַמִּים, כְּמוֹ שֶׁנֶּאֱמַר (איכה א) וַיֵּצֵא מִן בַּת צִיּוֹן כָּל הֲדָרָהּ, וְכָתוּב גָּלְתָה יְהוּדָה מֵעֹנִי וְגוֹ'."],[14,"","פָּתַח הָאַחֵר הַקָּטָן וְאָמַר, וַיִּפְגַּע בַּמָּקוֹם וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ וְגוֹ'. מַה זֶּה וַיִּפְגַּע בַּמָּקוֹם? לְמֶלֶךְ שֶׁהוֹלֵךְ לְבֵית הַגְּבִירָה, צָרִיךְ לִפְגֹּשׁ אוֹתָהּ וּלְבַשֵּׂם אוֹתָהּ בִּדְבָרִים כְּדֵי שֶׁלֹּא תִמָּצֵא אֶצְלוֹ כְּהֶפְקֵר, וְלֹא עוֹד, אֶלָּא שֶׁאֲפִלּוּ יֵשׁ לוֹ מִטָּה שֶׁל זָהָב וּכְסָתוֹת מְרֻקָּמוֹת מַעֲשֵׂה רוֹקֵם לִישֹׁן בָּהֶם, וְהִיא מְתַקֶּנֶת לוֹ מִטָּתוֹ מֵאֲבָנִים בָּאָרֶץ, וּבְחֶדֶר שֶׁל תֶּבֶן. יַעֲזֹב אֶת שֶׁלּוֹ וְיָלוּן בָּהֶם, לָתֵת לָהּ נַחַת, וּכְדֵי שֶׁיִּהְיֶה הָרָצוֹן שֶׁלָּהֶם יַחַד בְּלִי אֹנֶס. כְּמוֹ שֶׁלָּמַדְנוּ כָּאן, שֶׁכֵּיוָן שֶׁהָלַךְ אֵלֶיהָ, מַה כָּתוּב? (וילן שם כי בא השמש, להראות שאסור לו לאדם לשמש מטתו ביום) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם וַיָּשֶׂם מְרַאֲשּתָיו וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא, כְּדֵי לָתֵת לָהּ נַחַת שֶׁאֲפִלּוּ אַבְנֵי הַבַּיִת אֲהוּבִים לְפָנָיו לָלוּן בָּהֶם (שכתוב וישכב במקום ההוא)."],[15,"","בָּכָה רַבִּי יִצְחָק, (וחיך) וְשָׂמַח. אָמַר, אֵלּוּ הַמַּרְגָּלִיּוֹת תַּחַת יְדֵיכֶם, וְלֹא אֵלֵךְ אַחֲרֵיכֶם? אָמְרוּ לוֹ, אַתָּה תֵּלֵךְ לְדַרְכְּךְ, וְאָנוּ נִכָּנֵס לָעִיר לַהִלּוּלָא שֶׁל בְּנִי זֶה. אָמַר רַבִּי יִצְחָק, עַכְשָׁו יֵשׁ לִי לָלֶכֶת לְדַרְכִּי. הָלַךְ לוֹ וְסִדֵּר אֶת הַדְּבָרִים לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי יָפֶה אָמְרוּ, וְהַכֹּל נֶאֱמַר בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. אָמַר, הַדְּבָרִים הַלָּלוּ הֵם מִבְּנֵי בָנָיו שֶׁל רַבִּי צָדוֹק הַחַלָּשׁ הֵם. מָה הַטַּעַם נִקְרָא חַלָּשׁ? מִשּׁוּם שֶׁאַרְבָּעִים שָׁנָה הִתְעַנָּה עַל יְרוּשָׁלַיִם שֶׁלֹּא תֵחָרֵב בְּיָמָיו, וְהָיָה מְפָרֵשׁ עַל כָּל דָּבָר וְדָבָר שֶׁל הַתּוֹרָה סוֹדוֹת עֶלְיוֹנִים וְנוֹתֵן בָּהֶם דֶּרֶךְ לִבְנֵי הָעוֹלָם לְהִתְנַהֵג בָּהֶם."]]],[["אָמַר רִבִּי יִצְחָק, לָא הֲווּ (אלא) יוֹמִין זְעִירִין, עַד דְּאָעַרְעָנָא בְּהַהוּא בַּר נָשׁ וּבְרֵיהּ זְעֵירָא עִמֵּיהּ. אֲמִינָא לֵיהּ, אָן הוּא בְּרָךְ אָחֳרָא. אָמַר לִי, עֲבִידְנָא לֵיהּ הִלּוּלָא וְאִשְׁתָּאַר בִּדְבִיתְהוּ. כֵּיוָן דְּאִשְׁתְּמוֹדַע בִּי, אָמַר לֵיהּ חַיֶּיךָ, דְּלָא זְמִינְנָא לָךְ לְהִלּוּלָא דִבְרִי, בְּגִין תְּלַת מִלִּין. חַד, דְּלָא יְדַעְנָא בָּךְ וְלָא אִשְׁתְּמוֹדָעְנָא לָךְ, דְּהָכִי מְזַמְּנִין לֵיהּ לְבַר נָשׁ כְּפוּם יְקָרֵיהּ, וְדִילְמָא אַנְתְּ גַּבְרָא רַבָּא, וְאַפְגִים יְקָרָךְ. וְחַד, דִּילְמָא אַנְתְּ אָזִיל בְּאָרְחָךְ בִּבְהִילוּ, וְלָא אַטְרַח עֲלָךְ. וְחַד, דְּלָא תַכְסִיף קַמֵּי אֱנָשֵׁי דְּחֲבוּרָא. דְּאוֹרְחָא דִילָן, דְּכָל אִינוּן דְּאָכְלֵי לִפְתוֹרָא דְחָתָן וְכַלָּה, כֻּלְּהוּ יַהֲבֵי נְבַזְבְּזָן וּמַתְּנָן לוֹן. אֲמִינָא לֵיהּ, קוּדְשָׁא בְּרִיךְ הוּא יָדִין לָךְ לְטַב. אֲמִינָא לֵיהּ, מַה שְּׁמָךְ, אָמַר לֵיהּ צָדוֹק זוּטָא. בְּהַהוּא שַׁעְתָּא, אוֹלִיפְנָא מִנֵּיהּ, תְּלֵיסַר (נ\"א תריסר) רָזִין עִלָּאִין בְּאוֹרַיְיתָא, וּמִן בְּרֵיהּ תְּלַת, חַד בִּנְבוּאָה, וְחַד (נ\"א ותרין) בְּחֶלְמָא.","וְאָמַר מַה בֵּין נְבוּאָה לְחֶלְמָא. נְבוּאָה בְּעַלְמָא דִּדְכוּרָא אִיהוּ, וְחֶלְמָא בְּעַלְמָא דְנוּקְבָא, וּמֵהַאי לְהַאי, (עיין לקמן בסתרי תורה ומעבר לדף) כְּשִׁיתָּא דַרְגִּין נַחֲתָא. נְבוּאָה בִּימִינָא וּבִשְׂמָאלָא, וְחֶלְמָא בִּשְׂמָאלָא. וְחֶלְמָא מִתְפַּרְשָׁא לְכַמָּה דַרְגִּין לְתַתָּא, בְּגִין כָּךְ חֶלְמָא אִיהוּ בְּכָל עַלְמָא. אֲבָל כְּפוּם דַּרְגֵּיהּ, הָכִי חָמֵי, כְּפוּם בַּר נָשׁ, הָכִי דַּרְגֵּיהּ, דִּנְבוּאָה לָא אִתְפַּשְּׁטָא אֶלָּא בְּאַתְרֵיהּ.","תָּא חֲזֵי מַה כְּתִיב, (בראשית כ״ח:י״ב) וַיַּחֲלוֹם וְהִנֵּה סֻלָּם מוּצָב אַרְצָה וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמַיְמָה וְהִנֵּה מַלְאֲכֵי אֱלהִים עֹלִים וְירְדִים בּוֹ. פָּתַח וְאָמַר, (יחזקאל א׳:ג׳) הָיֹה הָיָה דְבַר ה' אֶל יְחֶזְקֵאל בֶּן בּוּזִי הַכֹּהֵן בְּאֶרֶץ כַּשְׂדִּים עַל נְהַר כְּבָר וַתְּהִי עָלָיו שָׁם יַד ה'. הָיֹה הָיָה, נְבוּאָה לְשַׁעֲתָא הָיְתָה (ס\"א הוות), דְּאִצְטְרִיךְ עַל גָּלוּתָא בְּגִין דִּשְׁכִינְתָּא נְחָתַת בְּהוּ בְּיִשְׂרָאֵל בְּגָלוּתָא, וְחָמָא יְחֶזְקֵאל מַה דְּחָמָא לְפוּם שַׁעְתָּא. וְאַף עַל גַּב דְּלָא אִתְחֲזֵי הַהוּא אֲתַר לְהַאי, בְּגִינֵי כָךְ הָיה הָיָה. מַאי הָיה הָיָה. אֶלָּא הָיֹה לְעֵילָא, הָיָה לְתַתָּא. דִּכְתִיב סֻלָּם מוּצָב אַרְצָה וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמַיְמָה, נָטִיל (ליה) לְעֵילָא וְנָטִיל (ליה) לְתַתָּא. הָיֹה הָיָה, חַד לְעֵילָא, וְחַד לְתַתָּא. (עיין בסוף הספר מה שחסר כאן סימן נ', (והוא ג\"כלקמודף ק\"וע\"א קחחו משם))","תָּא חֲזֵי, הַאי סֻלָּם בִּתְרֵי עַלְמִין אִתְתַּקַּף, בְּעֵילָא וְתַתָּא. בְּאֶרֶץ כַּשְׂדִּים עַל נְהַר כְּבָר. בְּאֶרֶץ כַּשְׂדִּים, בְּאֲתַר דְּגָלוּתָא שַׁרְיָא בֵּיהּ, וְעִם כָּל דָּא עַל נְהַר כְּבָר. מַאי נְהַר כְּבָר. אֶלָּא דְּהֲוָה כְּבָר, מִקַּדְמַת דְּנָא, דִּשְׁכִינְתָּא שַׁרְיָא עֲלוֹי, דִּכְתִיב (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגו'. וְדָא הוּא נַהֲרָא חַד מֵאִינוּן אַרְבַּע נַהֲרִין, וּבְגִין דְּשַׁרְיָא עֲלוֹי מִקַּדְמַת דְּנָא, וְהֲוָה עֲלוֹי כְּבָר, שַׁרְיָא בֵּיהּ הַשְׁתָּא, וְאִתְגְּלִי לֵיהּ לִיחֶזְקֵאל."],[[0,"אמר רבי יצחק וכו':","אר\"י, לא עברו ימים מועטים, עד שפגשתי באותו האיש, ובנו הקטן היה עמו. אמרתי לו, איפה הוא בנך האחר. אמר לי, עשיתי לו נשואים, ונשאר אצל אשתו. כיון שהכיר אותי, אמר לי, חייך, כי על כן לא הזמנתי אותך לשמחת נשואים של בני, משום שלשה דברים. אחד, שלא ידעתי אותך ולא הכרתי אותך, ומזמינים את האדם לפי כבודו, ואולי אתה אדם גדול ואחלל כבודך. ואחד, אולי אתה נחפז לדרכך ולא רציתי להכביד עליך. ואחד, שלא תבוש מפני אנשי החבורה, כי דרכנו, שכל האוכלים על שלחן חתן וכלה, נותנים להם כולם פזרונות ומתנות. אמרתי לו, הקב\"ה ידון אותך לטוב. אמרתי לו, מה שמך, אמר לי, צדוק זוטא. באותה שעה למדתי ממנו, י\"ג סודות עליונים בתורה. ומן בני למדתי ג' סודות, אחד, בנבואה ואחד בחלום. כלומר, שלמד ממנו ג' סודות בההפרש שבין נבואה לחלום."],[1,"ואמר מה בין נבואה וכו':","ואמר, מה ההפרש מנבואה לחלום. א) נבואה היא בעולם של הזכר שהוא ז\"א, וחלום הוא בעולם של הנקבה, שהיא הנוקבא דז\"א. ומזה לזה יורדות ששה מדרגות. כי הנבואה היא בנצח והוד דז\"א והחלום בהוד דנוקבא, ויש ביניהם, יסוד דז\"א, וחג\"ת נצח הוד דנוקבא, שהם שש מדרגות. ב) נבואה היא בימין ושמאל, דהיינו נצח והוד, והחלום הוא בשמאל, דהיינו בהוד. ג) החלום מתפשט לכמה מדרגות למטה, דהיינו עד המלאך גבריאל, שעל ידו מקבלים הארת החלום. ועל כן החלום הוא בכל העולם, אפילו בחוץ לארץ. אבל על פי מדרגתו רואה האדם, ולפי האדם כך מדרגתו. כלומר שלא כל אדם שוה בזה. אבל נבואה אינה מתפשטת למטה ממלכות דאצילות, אלא מאירה במקומה. דהיינו בנוקבא שהיא מקומו דז\"א, שה\"ס ארץ ישראל והנביאים מקבלים ממנה. באופן ששורש הנבואה הוא בנצח והוד דז\"א, שמתפשט עד הנוקבא, שעל ידה מקבלים הנביאים. ושורש החלום היא בנוקבא, בהוד שלה, ומתפשט עד המלאך גבריאל, שעל ידו מקבלים בני האדם."],[2,"ת\"ח כו' ויחלום וגו' עולים ויורדים בו:","פתח ואמר היה היה דבר ה' אל יחזקאל וגו', \u0003היה היה,\u0004 יורה, שנבואה לשעתה היתה, כי היתה נצרכת לחיזוק בני הגלות, להודיעם שהשכינה ירדה עמהם בגלות. (כמ\"ש בזהר שמות אות ו') ועל כן ראה יחזקאל, מה שראה, רק לפי שעתו, ואף על פי שאותו המקום לא היה ראוי לכך. כי אין חוץ לארץ ראוי לנבואה, משום זה אומר הכתוב, \u0003היה היה.\u0004 כלומר, שהיה כאן חידוש, ששרתה הנבואה בחוץ לארץ."],[2,"מאי היה היה וכו':","שואל למה אומר הכתוב היה היה ב' פעמים. ואומר, אלא \u0003היה\u0004 למעלה בז\"א \u0003היה\u0004 למטה בנוקבא, שכתוב סלם מוצב ארצה וראשו מגיע השמימה, שפירושו לוקח אור החסדים למעלה בשמים, שהוא ז\"א, ולוקח למטה בנוקבא הנקראת ארץ, את אור החכמה. כן \u0003היה היה,\u0004 היה אחד, פירושו הויות החסדים מלמעלה, והיה אחד, פירושו הויות החכמה מלמטה, וכבר נתבאר זה לעיל (ב\"ב דף קל\"ה ד\"ה מהכא) שהחסדים מקובלים מז\"א, והחכמה רק מן הנוקבא, וע\"כ נקראת הנוקבא חכמה תתאה. ע\"ש. ואין שלמות לחכמה בלי חסדים, וע\"כ לא נמשך אור שלם רק על ידי זווג ז\"א ונוקבא ביחד."],[3,"תא חזי האי סולם וכו':","בוא וראה, סולם זה נתחזק למעלה בז\"א, ונתחזק למטה בנוקבא. \u0003בארץ כשדים על נהר כבר. בארץ כשדים,\u0004 היינו המקום שהגלות שורה בו, דהיינו בחוץ לארץ. ועם כל זה, \u0003על נהר כבר.\u0004 מהו נהר כבר, אלא פירושו, שהיתה \u0003כבר,\u0004 שהשכינה שרתה עליו \u0003עוד מקודם לכן,\u0004 שכתוב ונהר יוצא מעדן להשקות את הגן, שהנהר ה\"ס בינה, (כנ\"ל ב\"א דף ר\"צ ד\"ה כתיב) ונהר כבר, הוא אחד מאלו ארבעה נהרות הנמשכים מנהר היוצא מעדן, דהיינו נהר פרת שבבבל. ומשום ששרה עליו מקודם לכן, והיה עליו \u0003כבר,\u0004 לכן שרה עליו גם עתה ונגלה לו ליחזקאל. כלומר, אע\"פ שהנבואה היתה צריכה לחזק את ישראל בגלות בבל שלא יבואו לידי יאוש, עם כל זה, אם לא היה נמשך הנהר הזה מנהר היוצא מעדן, שכבר שרתה עליו השכינה, לא היתה מתגלה עליו הנבואה בבבל."]],[[0,"","אָמַר רַבִּי יִצְחָק, לֹא הָיוּ (אלא) יָמִים מוּעָטִים עַד שֶׁפָּגַשְׁתִּי אוֹתוֹ הָאִישׁ, וּבְנוֹ הַקָּטָן עִמּוֹ. אָמַרְתִּי לוֹ, אֵיפֹה בִּנְךְ הָאַחֵר? אָמַר לִי, עָשִׂיתִי לוֹ הִלּוּלָא, וְנִשְׁאַר עִם אִשְׁתּוֹ. כֵּיוָן שֶׁהִכִּיר אוֹתִי, אָמַר לִי, חַיֶּיךְ שֶׁלֹּא הִזְמַנְתִּי אוֹתְךְ לַחֲתֻנַּת בְּנִי מִשּׁוּם שְׁלֹשָׁה דְבָרִים: אֶחָד - שֶׁלֹּא יָדַעְתִּי בְךְ וְלֹא הִכַּרְתִּי אוֹתְךְ, שֶׁכָּךְ מַזְמִינִים אֶת הָאָדָם - כְּפִי כְבוֹדוֹ, וְאוּלַי אַתָּה אִישׁ גָּדוֹל וְיִפָּגֵם כְּבוֹדְךְ. וְאֶחָד - אוּלַי אַתָּה הוֹלֵךְ לְדַרְכְּךְ בְּחִפָּזוֹן וְלֹא אַטְרִיחַ עָלֶיךְ. וְאֶחָד - שֶׁלֹּא תִתְבַּיֵּשׁ לִפְנֵי אַנְשֵׁי הַחֲבוּרָה, שֶׁדַּרְכֵּנוּ - שֶׁכָּל אוֹתָם שֶׁאוֹכְלִים עַל שֻׁלְחַן חָתָן וְכַלָּה, כֻּלָּם נוֹתְנִים לָהֶם אוֹצָרוֹת וּמַתָּנוֹת. אָמַרְתִּי לוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא יָדוּן אוֹתְךְ לְטוֹב. אָמַרְתִּי לוֹ, מַה שִּׁמְךְ? אָמַר לִי, צָדוֹק הַקָּטָן. בְּאוֹתָהּ שָׁעָה לָמַדְתִּי מִמֶּנּוּ שְׁלֹשָׁה עָשָׂר (תריסר) סוֹדוֹת עֶלְיוֹנִים בַּתּוֹרָה, וּמִבְּנוֹ שְׁלֹשָׁה, אֶחָד בִּנְבוּאָה, וְאֶחָד (ושנים) בַּחֲלוֹם."],[1,"","וְאָמַר, מַה בֵּין נְבוּאָה לַחֲלוֹם? נְבוּאָה בָּעוֹלָם הִיא שֶׁל זָכָר, וְהַחֲלוֹם בְּעוֹלַם הַנְּקֵבָה, וּמִזֶּה לָזֶה בְּשֵׁשׁ דְּרָגוֹת יוֹרֵד. הַנְּבוּאָה בְּיָמִין וּבִשְׂמֹאל, וְהַחֲלוֹם בִּשְׂמֹאל. וְהַחֲלוֹם נִפְרָד לְכַמָּה דְרָגוֹת לְמַטָּה, מִשּׁוּם כָּךְ הַחֲלוֹם הוּא בְּכָל הָעוֹלָם, אֲבָל כְּפִי דַרְגָּתוֹ. כָּךְ נִרְאֶה, כְּפִי הָאָדָם כָּךְ דַּרְגָּתוֹ, הַנְּבוּאָה אֵינָהּ מִתְפַּשֶּׁטֶת אֶלָּא בִּמְקוֹמָהּ."],[2,"","בֹּא רְאֵה מַה כָּתוּב, וַיַּחֲלֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ. פָּתַח וְאָמַר, (יחזקאל א) הָיֹה הָיָה דְבַר ה' אֶל יְחֶזְקֵאל בֶּן בּוּזִי הַכֹּהֵן בְּאֶרֶץ כַּשְׂדִּים עַל נְהַר כְּבָר וַתְּהִי עָלָיו שָׁם יַד ה'. הָיֹה הָיָה - נְבוּאָה לְשָׁעָה הָיְתָה, שֶׁהִצְטָרְכָה עַל הַגָּלוּת מִשּׁוּם שֶׁהַשְּׁכִינָה יָרְדָה עִם יִשְׂרָאֵל לַגָּלוּת, וְרָאָה יְחֶזְקֵאל מַה שֶּׁרָאָה לְפִי שָׁעָה. וְאַף עַל גַּב שֶׁאוֹתוֹ הַמָּקוֹם לֹא רָאוּי לָזֶה, מִשּׁוּם כָּךְ הָיֹה הָיָה. מַה זֶּה הָיֹה הָיָה? אֶלָּא הָיֹה לְמַעְלָה - הָיָה לְמַטָּה, שֶׁכָּתוּב סֻלָּם מֻצָּב אַרְצָה וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה. נוֹטֵל (אותו) לְמַעְלָה וְנוֹטֵל (אותו) לְמַטָּה. הָיֹה הָיָה - אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה."],[3,"","בֹּא רְאֵה, הַסֻּלָּם הַזֶּה מַחֲזִיק בִּשְׁנֵי עוֹלָמוֹת - בְּמַעְלָה וּמַטָּה. בְּאֶרֶץ כַּשְׂדִּים עַל נְהַר כְּבָר. בְּאֶרֶץ כַּשְׂדִּים - בְּמָקוֹם שֶׁהַגָּלוּת שׁוֹרָה בּוֹ, וְעִם כָּל זֶה, עַל נְהַר כְּבָר. מַה זֶּה נְהַר כְּבָר? אֶלָּא שֶׁהָיָה כְּבָר מִקֹּדֶם לָכֵן, שֶׁהַשְּׁכִינָה שׁוֹרָה עָלָיו, שֶׁכָּתוּב וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ'. וְזֶה הוּא נָהָר אֶחָד מֵאוֹתָם אַרְבָּעָה הַנְּהָרוֹת. וּמִשּׁוּם שֶׁשָּׁרָה עָלָיו מִקֹּדֶם לָכֵן וְהָיָה עָלָיו כְּבָר - שׁוֹרֶה בּוֹ עַכְשָׁו, וְהִתְגַּלָּה לִיחֶזְקֵאל."]]],[["תָּא חֲזֵי וַיַּחֲלוֹם, וְכִי יַעֲקֹב קַדִּישָׁא, דְּאִיהוּ שְׁלֵימָא דְּאֲבָהָן, בְּחֶלְמָא אִתְגְּלִי עֲלוֹי, וּבַאֲתַר דָּא קַדִּישָׁא לָא חָמָא (ליה) אֶלָּא (קס\"ה) בְּחֶלְמָא. אֶלָּא יַעֲקֹב בְּהַהוּא זִמְנָא לָא הֲוָה נָסִיב, וְיִצְחָק הֲוָה קַיָּים. וְאִי תֵימָא וְהָא לְבָתַר דְּאִתְנָסִיב כְּתִיב וָאֵרֶא בַּחֲלוֹם. תַּמָּן אֲתַר גָּרִים, וְיִצְחָק הֲוָה קַיָּים, וְעַל דָּא כְּתִיב בֵּיהּ חֲלוֹם.","וּלְבָתַר דְּאֲתָא לְאַרְעָא קַדִּישָׁא עִם שִׁבְטִין, וְאִשְׁתְּלִים (בהון) לְהוֹן עֲקֶרֶת הַבַּיִת, וְאֵם הַבָּנִים שְׂמֵחָה, כְּתִיב, (בראשית ל״ה:ט׳) וַיֵּרָא אֱלהִים אֶל יַעֲקֹב וְגו'. וּכְתִיב, (בראשית מ״ו:ב׳) וַיֹּאמֶר אֱלֹהִים לְיִשְׂרָאֵל בְּמַרְאוֹת הַלַּיְלָה, הָכָא לָא כְּתִיב בֵּיהּ חֲלוֹם דְּהָא מִדַּרְגָּא אָחֳרָא עִלָאָה הֲוָה.","תָּא חֲזֵי, (קצ\"ו ע\"א) חֶלְמָא אִיהוּ עַל יְדֵי דְּגַבְרִיאֵל דְּאִיהוּ לְתַתָּא, בְּדַרְגָּא שְׁתִיתָאָה מִנְּבוּאָה. מַרְאֶה, עַל יְדָא דְּהַהוּא דַרְגָּא דְּהַהִיא חַיָּה דְּשָׁלְטָא בְּלֵילְיָא. וְאִי תֵימָא, הָא כְּתִיב (דניאלח) גַּבְרִיאֵל הָבֵן לְהַלָּז אֶת הַמַּרְאֶה. הָכִי הוּא וַדַּאי, דְּמַרְאֶה מִלּוֹי סְתִימִין יַתִּיר, וּבְחֶלְמָא פָּרִישׁ יַתִּיר, וּפָרִישׁ סְתִימִין דְּמַרְאֶה, וְעַל דָּא אִתְפַּקַּד גַּבְרִיאֵל, דִּיְפָרֵשׁ מִלּוֹי דְמַרְאֶה דְּאִיהוּ סָתִים יַתִּיר.","וְעַל דָּא כְּתִיב בְּמַרְאֶה, וַיֵּרָא, וָאֵרָא, מַאי טַעְמָא, בְּגִין דְּמַרְאֶה אִיהוּ, כְּהַאי מַרְאֶה דְּאִתְחֲזֵי כָּל דִּיוּקְנִין בְּגַוֵּיהּ, בְּגִינֵי כָךְ וָאֵרָא, אַחְמִית דִּיוּקְנֵיהּ, בְּאֵל שַׁדַּי, דְּאִיהוּ מַרְאֶה, (צ\"א ע\"א) דְּאִתְחֲמֵי דִּיוּקְנָא אָחֳרָא בְּגַוֵּיהּ, וְכָל דִּיוּקְנִין עִלָּאִין בֵּיהּ אִתְחֲזוּן.","בְּגִינֵי כָךְ, יַעֲקֹב בְּהַהוּא זִמְנָא, כְּתִיב, (בראשית כ״ח:י״ב) וַיַּחֲלֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה (וראשו), מַהוּ סֻלָּם, דַּרְגָּא דִּשְׁאָר דַּרְגִּין בֵּיהּ תַּלְיָין וְהוּא יְסוֹד דְּעָלְמָא. וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמַיְמָה, הָכִי הוּא לְאִתְקַשְּׁרָא בַּהֲדֵיהּ. וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמַיְמָה, מַאן רֹאשׁוֹ. רֹאשׁוֹ דְּהַהוּא סֻלָּם. וּמַאן אִיהוּ, דָּא דִכְתִיב בֵּיהּ (בראשית מ״ז:ל״א) רֹאשׁ הַמִּטָּה, בְּגִין דְּאִיהוּ רֹאשׁ לְהַאי מִטָּה וּמִנָּהּ נָהִיר. מַגִּיעַ הַשָּׁמַיְמָה, בְּגִין דְּאִיהוּ סִיּוּמָא דְגוּפָא, וְקָאִים בֵּין עִלָּאָה וְתַתָּאָה, כְּמָה דִּבְרִית אִיהוּ סִיּוּמָא דְגוּפָא, וְקָאִים בֵּין יַרְיכִין וְגוּפָא, וְעַל דָּא מַגִּיעַ הַשָּׁמַיְמָה.","(בראשית כ״ח:י״ב) וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עוֹלִים וְיוֹרְדִים בּוֹ, אִלֵּין מְמַנָּן דְּכָל עַמִּין, דְּאִינוּן סָלְקִין וְנָחֲתִין בְּהַאי סֻלָּם. כַּד יִשְׂרָאֵל חָטָאן, מָאִיךְ הַאי סֻלָּם וְסָלְקִין אִינְהוּ מְמַנָּן, וְכַד יִשְׂרָאֵל מִתְכַּשְׁרָן עוֹבָדַיְיהוּ, אִסְתַּלַּק הַאי סֻלָּם וְכֻלְּהוּ מְמַנֵּי נָחֲתֵי לְתַתָּא, וְאִתְעֲבַר שׁוּלְטָנוּתָא דִלְהוֹן, כֻּלָּא בְּהַאי סֻלָּם קָיְימָא. הָכָא חָמָא יַעֲקֹב בְּחֶלְמֵיהּ, שָׁלְטָנוּתָא דְעֵשָׂו וְשָׁלְטָנוּתָא דִּשְׁאָר עַמִין.","דָבָר אַחֵר וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עוֹלִים וְיוֹרְדִּים בּוֹ. בְּמַאן, בְּהַהוּא רֹאשׁוֹ, דְּהַהוּא סֻלָּם. דְּכַד אִסְתַּלַּק רֹאשׁוֹ מִנֵּיהּ, סֻלָּם אִתְכַּפְיָא וְסָלְקִין כֻּלְּהוּ מְמַנָּן. וְכַד אִתְחַבַּר רֹאשׁוֹ בְּהַהוּא סֻלָּם, אִסְתַּלַק, וְכֻלְּהוּ מְמַנָּן נָחֲתִין. וְכֹלָּא חַד מִלָּה."],[[0,"תא חזי, ויחלום:","שואל, וכי יעקב הקדוש, בחיר שבאבות, נגלה עליו ה' בחלום ובמקום קדוש הזה, דהיינו בית לא שהוא בארץ ישראל, שראוי להשראת השכינה, לא ראה את ה' אלא בחלום. ומשיב, אלא יעקב, לא היה נשוי באותו זמן, והיה פלג גופא, ויצחק היה חי, ועוד לא הגיע זמן שליטתו, ועל כן כתוב בו חלום, ולא מראה בהקיץ."],[0,"ואי תימא והא לבתר וכו':","ואם תאמר, הרי לאחר שנשא אשה כתוב וארא בחלום, הנה שם המקום גרם, שהיה בחוץ לארץ בפדן ארם, ויצחק היה חי, ועל כן כתוב בו חלום."],[1,"ולבתר דאתא וכו':","ולאחר כך, שבא לארץ הקודש עם השבטים, ועקרת הבית נשלמה עמהם, ואם הבנים שמחה, שהיה שלם עם בת זוגו, והיה בארץ ישראל, כתוב, וירא אלקים אל יעקב וגו', וכתוב ויאמר אלקים לישראל במראות הלילה. כאן לא כתוב בו חלום, כי כבר היה במדרגה אחרת עליונה. והיה ראוי למראה בהקיץ."],[2,"ת\"ח, חלמא וכו':","בוא וראה, \u0003החלום\u0004 הוא, על ידי גבריאל, שהוא, דהיינו החלום, למטה במדרגה הששית מנבואה. כלומר, שגבריאל מקבל החלום מהוד הנוקבא, שהיא מדרגה הששית מנבואה (כנ\"ל דף כ\"ו ד\"ה ואמר) ועל ידי גבריאל מקבלים בני אדם. מראה הוא מקובלת על ידי מדרגה ההיא של אותה החיה השולטת בלילה, כי המראה היא הנוקבא דז\"א במקומה עצמה, שעליה נאמר, ותקם בעוד לילה. ועל כן היא מראה בהקיץ ולא בחלום."],[2,"ואי תימא הא כתיב וכו':","ואם תאמר הרי כתוב, גבריאל הבן להלז את המראה. הרי שגם \u0003המראה\u0004 מקובלת על ידי גבריאל. ומשיב, כן הוא ודאי, שמראה, דבריה סתומים ביותר, ובחלום, הדברים יותר מפורשים, והחלום מפרש דברים הסתומים אשר במראה, ועל כן גבריאל הממונה על החלום נתמנה לפרש דבריה של המראה הסתומים ביותר."],[3,"וע\"ד כתיב במראה וכו':","ועל כן כתוב לשון וירא וארא, \u0003במראה,\u0004 שהוא מטעם, כי \u0003מראה,\u0004 היא, כמראה הזו של זכוכית מלוטשת, שכל הצורות שממולה נראות בתוכה, משום זה כתוב בה \u0003וארא\u0004 אל אברהם וגו' באל שדי וגו', כי המראה, שהיא הנוקבא, אמרה, הראיתי צורתו של ה' באל שדי. להיותה \u0003מראה\u0004 שצורת האחר נראית בתוכה. וכל הצורות של מדרגות העליונות נראות בתוכה."],[3,"","ביאור הדברים. כי צורת הנוקבא ה\"ס חכמה, וצורת ז\"א ה\"ס חסדים. (כנ\"ל דף כ\"ז ד\"ה מאי) וע\"כ אין לך אור שלם אלא ע\"י זווג שניהם ומקבלים החסדים חכמה מן הנוקבא והחכמה של הנוקבא מתלבשת בחסדים, ונשלמים שניהם. ועם כל זה אין הארת חכמה שבנוקבא מושפעת ממנה ולמטה, אלא ממנה ולמעלה, דהיינו אל החסדים שבז\"א, שהם משתלמים בג\"ר ומושפעים ממעלה למטה. שז\"ס מה שאמרו בזהר על הכתוב, אשת חיל עטרת בעלה, אשר בעלה מתעטר בה, שהחסדים דז\"א מתעטרים בג\"ר על ידה ומושפעים למטה, אבל הנוקבא אינה מתעטרת בבעלה, כי צורתה, שהיא הארת החכמה אינה מושפעת ממנה ולמטה. וז\"ש \u0003דאיהי מראה, דאתחמי דיוקנא אחרא בגויה,\u0004 דהיינו צורת ז\"א, שהוא חסדים, נראית לתחתונים על ידה, דהיינו שמושפעים ממנה ולמטה, אבל צורתה עצמה אינה נראית לתחתונים, כי אינה משפיעה החכמה ממנה ולמטה. ונמצא, שהיא דומה למראה מלוטשת, שאין ענינה להראות צורתה עצמה, אלא רק צורתם של אחרים המסתכלים בה, או העומדים למולה. ועוד היא דומה למראה, כי כמו שכל סגולתה של מראה הזכוכית, היא בסבת צבע העכור שבעברה השני, המחזיר קרני האור לאחוריהם, ואם היתה שקופה, שום צורה לא היתה נראה בה, כך הנוקבא, כל כחה הוא בהמסך שבה, המעכב על האור להעיר ממנה ולמטה, ולולא המסך הזה לא היה בה שום אור, כנודע."],[4,"בגיני כך יעקב וכו':","משום זה, יעקב בזמן ההוא, דהיינו מטרם שנשא אשה, כתוב בו, ויחלום והנה סולם מוצב ארצה. מהו סולם. הוא מדרגה, שכל שאר המדרגות תלויות בו. דהיינו הנוקבא, שהיא השער לכל המדרגות. ולא גרסינן \u0003ואיהו יסוד דעלמא,\u0004 כי גליון היה, והכניסוהו המעתיקים בפנים הזהר. ובספרים ישנים אינו נמצא, זולת בדפוס מונטבא, שהמדפיסים נמשכו אחריו. ובע\"ח שכ\"ב שער מוחין דקטנות מביא שהסולם הוא יסוד. ולע\"ד אינו מהאריז\"ל."],[4,"וראשו מגיע השמימה:","בן הוא מגיע השמימה כדי להתקשר עם השמים. \u0003וראשו מגיע השמימה,\u0004 שואל, מי הוא ראשו. ואומר. הוא הראש של אותו הסולם, ומי הוא. הוא שכתוב בו ראש המטה, דהיינו יסוד, שהוא ראש הנוקבא הנקראת מטה, ונקרא היסוד ראש המטה, משום שהוא ראש למטה ההיא, שהיא הנוקבא, והיא מאירה ממנו, מן היסוד, וע\"כ נבחן שהוא ראש שלה, \u0003מגיע השמימה:\u0004 משום שהוא סיום הגוף, שהוא ת\"ת הנקרא שמים, כי היסוד דבוק תחת הת\"ת, ועומד בין העליון שהוא ז\"א, ובין התחתון שהוא הנוקבא, בדומה לברית שהוא סיום הגוף, ונמצא בין הירכים והגוף, ועל כן אומר הכתוב, מגיע השמימה. אשר הראש של הסולם, שהוא יסוד דז\"א מגיע השמימה, שהוא דבוק בז\"א הנקרא שמים."],[5,"והנה מלאכי אלקים עולים ויורדים בו:","אלו הם הממונים של כל העמים, העולים ויורדים בסולם הזה. וכאשר ישראל חוטאים, נשפל הסולם ואלו הממונים עולים. וכשישראל מטיבים מעשיהם מתעלה הסולם, וכל הממונים יורדים למטה, והממשלה שלהם מתבטלת. הכל תלוי בסולם הזה. כאן ראה יעקב בחלומו, הממשלה של עשו, והממשלה של שאר כל העמים."],[6,"דבר אחר, והנה מלאכי אלקים עולים ויורדים בו:","במה, הם עולים ויורדים היינו, בראש ההוא של הסולם. כי כשנסתלק ראשו, דהיינו יסוד, ממנו, הסולם נכנע וכל הממונים עולים בשליטתם. וכאשר מתחבר הראש באותו הסולם הוא מתעלה וכל הממונים יורדים משליטתם. והכל ענין אחד. כלומר ב' הפירושים אחד הם, ואין ביניהם אלא אופן הביאור בלבד."],[6,"","כי פירוש הא' הוא, \u0003כד ישראל חטאן מאיך האי סלם, וסלקין אינון ממנן, וכו'\u0004 כי ממשלת האומות נמשך מקו שמאל בלי ימין, וכשישראל חוטאים, מוסיפים, במעשיהם הרעים, כח לקו שמאל, ואז מושפל הסולם שהיא הנוקבא, מחמת חוסר חסדים, והממונים של האומות עולים ורודים את ישראל. \u0003וכד ישראל מתכשרן עובדייהו, אסתלק האי סלם, וכלהו ממני נחתי וכו':\u0004 כי במעשיהם הטובים הם מגבירים קו האמצעי, המשפיע חכמה וחסדים ביחד, ונחלש כח השמאל, ועל כן מתעלה הסולם ברוב שלמות, ומתבטל כח ממשלתם של הממונים על האומות. ופירוש הב' הוא ג\"כ אותו הדבר, אלא שאינו תולה בחטאים של ישראל, אלא שמדבר ממציאות ראש הסולם, שהוא יסוד דז\"א המשפיע חסדים, בסו\"ה וראשו מגיע השמימה. ואומר, כשנסתלק הראש מן הסולם, ונשאר הסולם בחכמה בלי חסדים, אז \u0003סלם אתכפיא וסלקין כלהו ממנן.\u0004 משום שכל שליטתם תלוי בהארת השמאל בלי ימין, דהיינו חכמה בלי חסדים. כנ\"ל, \u0003וכד אתחבר ראשו בההוא סולם,\u0004 דהיינו כשהחסדים מתחברים בחכמה, \u0003אסתלק וכלהו ממנן נחתין,\u0004 מתעלה הסולם וכל הממונים יורדים, הרי ששני הפירושים אחד הם."]],[[0,"","בֹּא רְאֵה, וַיַּחֲלֹם, וְכִי יַעֲקֹב הַקָּדוֹשׁ, שֶׁהוּא הַשָּׁלֵם שֶׁל הָאָבוֹת, הִתְגַּלָּה עָלָיו בַּחֲלוֹם, וּבַמָּקוֹם הַקָּדוֹשׁ הַזֶּה לֹא רָאָה (לו) אֶלָּא בַּחֲלוֹם? אֶלָּא יַעֲקֹב בַּזְּמַן הַהוּא לֹא הָיָה נָשׂוּי, וְיִצְחָק הָיָה קַיָּם. וְאִם תֹּאמַר שֶׁהִנֵּה אַחַר כָּךְ, כְּשֶׁנִּשָּׂא, כָּתוּב וָאֵרֶא בַּחֲלוֹם? שָׁם הַמָּקוֹם גָּרַם, וְיִצְחָק הָיָה קַיָּם, וְעַל כֵּן כָּתוּב בּוֹ חֲלוֹם."],[1,"","וְאַחַר שֶׁבָּא לָאָרֶץ הַקְּדוֹשָׁה עִם הַשְּׁבָטִים, וְנִשְׁלְמָה (בהם) לָהֶם עֲקֶרֶת הַבַּיִת וְאֵם הַבָּנִים שְׂמֵחָה, כָּתוּב וַיֵּרָא אֱלֹהִים אֶל יַעֲקֹב וְגוֹ', וְכָתוּב (בראשית מו) וַיֹּאמֶר אֱלֹהִים לְיִשְׂרָאֵל בְּמַרְאֹת הַלַּיְלָה. כָּאן לֹא כָתוּב בּוֹ חֲלוֹם, שֶׁהֲרֵי הָיָה מִדַּרְגָּה אַחֶרֶת עֶלְיוֹנָה."],[2,"","בֹּא רְאֵה, הַחֲלוֹם הוּא עַל יְדֵי גַבְרִיאֵל, שֶׁהוּא לְמַטָּה, בַּדַּרְגָּה הַשִּׁשִּׁית מִנְּבוּאָה. מַרְאֶה - עַל יְדֵי הַדַּרְגָּה הַהִיא שֶׁל הַחַיָּה הַהִיא שֶׁשּׁוֹלֶטֶת בַּלַּיְלָה. וְאִם תֹּאמַר, הִנֵּה כָּתוּב (דניאל ח) גַּבְרִיאֵל הָבֵן לְהַלָּז אֶת הַמַּרְאֶה - כָּךְ זֶה וַדַּאי, שֶׁמַּרְאֶה דְּבָרָיו יוֹתֵר סְתוּמִים, וּבַחֲלוֹם מְפֹרָשׁ יוֹתֵר, וּמְפָרֵשׁ אֶת הַסְּתוּמִים שֶׁל הַמַּרְאֶה. וְעַל כֵּן נִפְקָד גַּבְרִיאֵל, שֶׁיְּפָרֵשׁ אֶת דִּבְרֵי הַמַּרְאֶה, שֶׁהוּא יוֹתֵר סָתוּם."],[3,"","וְעַל כֵּן כָּתוּב בְּמַרְאֶה - וַיֵּרָא, וָאֵרָא. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא מַרְאֶה, כְּמוֹ הַמַּרְאֶה הַזֶּה שֶׁנִּרְאִים בְּתוֹכוֹ כָּל הַדְּמֻיּוֹת, וּמִשּׁוּם כָּךְ וָאֵרָא, רָאִיתִי דְמוּתוֹ. בְּאֵל שַׁדַּי, שֶׁהוּא הַמַּרְאֶה, שֶׁנִּרְאֵית בְּתוֹכוֹ דְּמוּת אַחֶרֶת, וְכָל הַדְּמֻיּוֹת הָעֶלְיוֹנוֹת נִרְאוֹת בּוֹ."],[4,"","מִשּׁוּם כָּךְ, יַעֲקֹב בְּאוֹתוֹ הַזְּמַן, כָּתוּב וַיַּחֲלֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה (וראשו). מַה זֶּה סֻלָּם? הַדַּרְגָּה שֶׁשְּׁאָר הַדְּרָגוֹת תְּלוּיוֹת בָּהּ, וְהוּא יְסוֹד הָעוֹלָם. וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה, כָּךְ הוּא לְהִתְקַשֵּׁר עִמּוֹ. וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה, מִי רֹאשׁוֹ? רֹאשׁוֹ שֶׁל אוֹתוֹ סֻלָּם. וּמִי הוּא? זֶה שֶׁכָּתוּב בּוֹ (בראשית מז) רֹאשׁ הַמִּטָּה. מִשּׁוּם שֶׁהוּא רֹאשׁ לַמִּטָּה הַזּוֹ וּמִמֶּנָּה מֵאִיר. מַגִּיעַ הַשָּׁמָיְמָה, מִשּׁוּם שֶׁהוּא סִיּוּם הַגּוּף, וְעוֹמֵד בֵּין עֶלְיוֹן וְתַחְתּוֹן, כְּמוֹ שֶׁהַבְּרִית הוּא סִיּוּם הַגּוּף וְעוֹמֵד בֵּין הַיְרֵכַיִם וְהַגּוּף, וְעַל זֶה מַגִּיעַ הַשָּׁמָיְמָה."],[5,"","וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ, אֵלּוּ הַמְמֻנִּים שֶׁל כָּל הָעַמִּים, שֶׁהֵם עוֹלִים וְיוֹרְדִים בַּסֻּלָּם הַזֶּה. כְּשֶׁיִּשְׂרָאֵל חוֹטְאִים, נִשְׁפָּל הַסֻּלָּם הַזֶּה, וְעוֹלִים אוֹתָם הַמְמֻנִּים. וּכְשֶׁיִּשְׂרָאֵל מַכְשִׁירִים אֶת מַעֲשֵׂיהֶם, מִתְעַלֶּה הַסֻּלָּם הַזֶּה, וְכָל הַמְמֻנִּים יוֹרְדִים לְמַטָּה וְעוֹבֵר שִׁלְטוֹנָם. הַכֹּל עוֹמֵד בַּסֻּלָּם הַזֶּה. כָּאן רָאָה יַעֲקֹב בַּחֲלוֹמוֹ אֶת שִׁלְטוֹנוֹ שֶׁל עֵשָׂו וְאֶת שִׁלְטוֹן שְׁאָר הָעַמִּים."],[6,"","דָּבָר אַחֵר וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ, בְּמִי? בְּאוֹתוֹ רֹאשׁוֹ שֶׁל אוֹתוֹ סֻלָּם. שֶׁכְּשֶׁמִּסְתַּלֵּק רֹאשׁוֹ מִמֶּנּוּ - הַסֻּלָּם נִכְנָע, וְעוֹלִים כָּל הַמְמֻנִּים. וּכְשֶׁמִּתְחַבֵּר רֹאשׁוֹ בְּאוֹתוֹ סֻלָּם - מִתְעַלֶּה, וְכָל הַמְמֻנִּים יוֹרְדִים. וְהַכֹּל דָּבָר אֶחָד."]]],[["כְּתִיב, (מלכים א ג׳:ה׳) נִרְאָה ה' אֶל שְׁלמֹה בַּחֲלוֹם הַלָּיְלָה וַיֹּאמֶר אֱלֹהִים שְׁאַל מָה אֶתֶּן לָךְ. וְאִי תֵימָא הָכָא בַּחֲלוֹם, וְכִי מָה רְשׁוּ אִית לֵיהּ לַחֲלוֹם בְּהַאי. אֶלָּא הָכָא אִתְכְּלִיל דַּרְגָּא בְּדַרְגָּא, דַּרְגָּא עִלָּאָה בְּדַרְגָּא תַּתָּאָה. בְּגִין דְּעַד כְּעָן, שְׁלמֹה לָא הֲוָה שְׁלִים, כֵּיוָן דְּאִשְׁתְּלִים, כְּתִיב, (מלכים א ה׳:כ״ו) וַה' נָתַן חָכְמָה לִשְׁלֹמֹה. וּכְתִיב, (מלכים א ה׳:כ״ו) וַתֵּרֶב חָכְמַת שְׁלֹמֹה. דְּקָיְימָא סִיהֲרָא בְּאַשְׁלָמוּתָא, וּבֵי מַקְדְּשָׁא אִתְבְּנֵי. וּכְדֵין, הֲוָה חָמֵי שְׁלֹמֹה, עֵינָא בְּעֵינָא חָכְמָתָא, וְלָא אִצְטְרִיךְ לְחֶלְמָא.","לְבָתַר דְּחָטָא, אִצְטְרִיךְ לֵיהּ לְחֶלְמָא כְּקַדְמִיתָא, וְעַל דָּא כְּתִיב, (מלכים א י״א:ט׳) הַנִּרְאֶה אֵלָיו פַּעֲמַיִם, וְכִי פַּעֲמַיִם הֲוָה וְלא יַתִּיר. אֶלָּא סִטְרָא דְחֶלְמָא הֲוָה לֵיהּ פַּעֲמַיִם, סִטְרָא דְחָכְמָתָא כָּל יוֹמָא הֲוָה.","וְעִם כָּל דָּא, סִטְרָא דְחֶלְמָא הֲוָה יַתִּיר עַל כָּל שְׁאָר בְּנִי נָשָׁא, בְּגִין דְּאִתְכְּלִיל דַּרְגָּא בְּדַרְגָּא, מַרְאֶ\"ה בְּמַרְאֶ\"ה. וְהָא הַשְׁתָּא בְּסוֹף יוֹמוֹי חָשִׁיךְ יַתִּיר, וְדָא בְּגִין דְּחָטָא, וְסִיהֲרָא קָיְימָא לְאִתְפָּגְמָא. מַאי טַעְמָא, בְּגִין דְּלָא נָטִיר בְּרִית קַדִּישָׁא, בְּאִשְׁתַּדְלוּתֵיהּ בְּנָשִׁים נָכְרִיּוֹת. וְדָא הוּא תְּנַאי דְּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא עִם דָּוִד, דִּכְתִיב, (תהילים קל״ב:י״ב) אִם יִשְׁמְרוּ בָנֶיךָ בְּרִיתִי וְגו'. גַּם בְּנֵיהֶם עֲדֵי עַד יֵשְׁבוּ לְכִסֵּא לָךְ.","מַאי עֲדֵי עַד. הַיְינוּ דִּכְתִיב (דברים י״א:כ״א) כִּימֵי הַשָּׁמַיִם עַל הָאָרֶץ. וּבְגִין דִּשְׁלֹמֹה לָא נָטַר הַאי בְּרִית כְּדְקָא יְאוּת, שַׁרְיָא סִיהֲרָא לְאִתְפָּגְמָא. וְעַל דָּא, בְּסוֹפָא אִצְטְרִיךְ חֶלְמָא, וְכֵן יַעֲקב אִצְטְרִיךְ לֵיהּ לְחֶלְמָא כִּדְאֲמָרָן.","(בראשית כ״ח:י״ג) וְהִנֵּה ה' נִצָּב עָלָיו וגו'. הכא חמא יעקב קשורא דִּמְהֵימְנוּתָא כְּחַד. נִצָּב עליו, וכתיב (מלכים א כ״ב:מ״ח) וּמֶלֶךְ אֵין בְּאֶדוֹם. נצב מלך. (נצב מלח) חמא, דכל דרגין קיימין כלהו כחד על ההוא סולם, לאתקשרא כלא בחד קשרא. בגין דאתיהיב ההוא סלם בין תרין סתרין, הדא הוא דכתיב אֲנִי ה' אֱלהֵי אַבְרָהָם אָבִיךָ וִאלהֵי יִצְחָק וגו'. אלֵּין אִנּוּן תְּרֵין סִטְרִין בְּיָמִינָא וּשְׂמָאלָא.","דבר אחר והנה ה' נצב עליו (ויאמר), עליה דיעקב, למהוי כלא רתיכא קדישא, ימינא ושמאלא, ויעקב בגוויהו, וכנסת ישראל לאתקשרא בנייהו, הדא הוא דכתיב אני ה' אלהי אברהם אביך ואלהי יצחק. מנלן דיעקב באמצעיתא, משמע דכתיב אלהי אלהי אברהם אביך ואלהי יצחק (הארץ), וְלָא כְּתִיב אֱלֹהֵי יִצְחָק אָבִיךָ. דְּכֵיוָן דְּאִתְקַשַּׁר בֵּיהּ בְּאַבְרָהָם, אִשְׁתַּכַּח דְּאִיהוּ בְּאֶמְצָעִיתָא. וּלְבָתַר הָאָרֶץ אֲשֶׁר אַתָּה שׁוֹכֵב עָלֶיהָ, הָא כֹּלָּא רְתִיכָא חָדָא קַדִּישָׁא. וְהָכָא חָמָא דְּיֶהוֵי שְׁלִימוּ דְּאֲבָהָן.","תָּא חֲזֵי, אֱלהֵי אַבְרָהָם אָבִיךָ, דְּכֵיוָן דְּאָמַר אַבְרָהָם אָבִיךָ, וַדַּאי אִיהוּ בְּאֶמְצָעִיתָא, וֵאלֹהֵי יִצְחָק, הָכָא אִתְרְמִיז דְּקָשִׁיר לִתְרֵין סִטְרִין וְאָחִיד לוֹן. קָשִׁיר לְסִטְרָא חָד, דִּכְתִיב אַבְרָהָם אָבִיךָ. וְקָשִׁיר לְסִטְרָא אָחֳרָא, דִּכְתִיב וִאלֹהֵי יִצְחָק, תּוֹסֶפֶת וא\"ו לְגַבֵּי יִצְחָק, לְאַחֲזָאָה דְיַעֲקֹב אָחִיד לִתְרֵין סִטְרִין.","וְעַד דְּיַעֲקֹב לָא אִתְנָסִיב, לָא אִתְּמָר בְּאִתְגַּלְּיָא יַתִּיר, וְאִתְּמָר בְּאִתְגַּלְּיָא, לְמַאן דְּיָדַע אוֹרְחוֹי דְאוֹרַיְיתָא. לְבָתַר דְּאִתְנָסִיב וְאוֹלִיד, אִתְּמָר לֵיהּ בְּאִתְגַּלְּיָא, הֲדָא הוּא דִכְתִיב, (בראשית ל״ג:כ׳) וַיַּצֶּב שָׁם מִזְבֵּחַ (בראשית יט) וַיִּקְרָא לוֹ אֵל אֱלהֵי יִשְׂרָאֵל. מֵהָכָא אוֹלִיפְנָא, מַאן דְּלָא אִשְׁתְּלִים לְתַתָּא, לָא אִשְׁתְּלִים לְעֵילָא. שָׁאנֵי יַעֲקֹב, דְּאִשְׁתְּלִים לְעֵילָא וְתַתָּא, אֲבָל לָא בְּאִתְגַּלְּיָא.","וְאִי תֵימָא דְּאִשְׁתְּלִים בְּהַהִיא שַׁעְתָּא, לָא. אֶלָּא חָמָא דְּיִשְׁתְּלִים לְבָתַר זִמְנָא. וְאִי תֵימָא הָא כְּתִיב, (בראשית כ״ח:ט״ו) וְהִנֵּה אָנֹכִי עִמָּךְ וּשְׁמַרְתִּיךָ בְּכָל אֲשֶׁר תֵּלֵךְ. אֶלָּא, אַשְׁגָּחוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּנְטִירוּ דִילֵיהּ, לָא אִשְׁתְּבִיק מִנֵּיהּ דְּיַעֲקֹב לְעָלְמִין, בְּכָל מַה דְּאִצְטְרִיךְ לֵיהּ בְּהַאי עַלְמָא, אֲבָל בְּעַלְמָא עִלָּאָה עַד דְּאִשְׁתְּלִים.","(שם) וַיִּיקַץ יַעֲקֹב מִשְּׁנָתוֹ וַיֹּאמֶר אָכֵן יֵשׁ ה' בַּמָּקוֹם הַזֶּה וְאָנֹכִי לא יָדַעְתִּי. וְכִי תְּוָוהָא הוּא דְּלָא יָדַע. אֶלָּא מַאי וְאָנֹכִי לא יָדָעְתִּי, כְּמָה דְאַתְּ אָמֵר, (שמואל א י״ג:י״ב) וּפְנִי ה' לא חִלִּיתִי. אָמַר, וְכִי כָּל הַאי אִתְגְּלִי לִי וְלָא אִסְתַּכַּלְנָא לְמִנְדַע אָנֹכִי, וּלְמֵיעַל תְּחוֹת גַּדְפֵי דִשְׁכִינְתָּא לְמֶהֱוֵי שְׁלִים."],[[0,"כתיב נראה ה' וגו' שאל מה אתן לך","ומקשה, ואם תאמר שזה היה בחלום דהיינו ע\"י גבריאל כנ\"ל, איזה רשות יש למדרגת החלום בזה, דהיינו, לומר לו, שאל מה אתן לך, כיון שאינו אלא מלאך. ומשיב. אלא כאן נכלל מדרגה במדרגה, שמדרגה העליונה, שהיא הנוקבא דז\"א, שהיא שורש החלום כנ\"ל, נכללה ונתלבשה במדרגה התחתונה, דהיינו במדרגת גבריאל. והנוקבא אמרה לו, שאל מה אתן לך כי כן נאמר, ויאמר אלקים שאל וגו' שהוא שם הנוקבא."],[0,"בגין דעד כען וכו':","וע\"כ נגלה לו רק בחלום, משום שעד עתה עוד לא היה שלמה שלם, כיון שנשלם, כתוב וה' נתן חכמה לשלמה, וכתיב ותרב חכמת שלמה, שהלבנה שהיא הנוקבא, עמדה במילואה, ובית המקדש נבנה, ואז ראה שלמה חכמה עין בעין, ולא היה נצרך עוד לחלום."],[1,"לבתר דחטא וכו':","אחר שחטא, חזר ונצרך אל החלום כבתחילה, ועל כן כתוב, הנראה אליו פעמים, שקשה, וכי רק פעמים היה נראה אליו, ולא יותר. אלא הפירוש הוא, שמצד מדרגת החלום נראה לו רק פעמים."],[2,"ועם כל דא סטרא וכו':","ועם כל זה, מדרגת החלום של שלמה, היתה גדולה יותר ממדרגת החלום של שאר בני אדם. משום שנכלל לו מדרגה במדרגה, \u0003מראה\u0004 בהקיץ שהיא הנוקבא, נכללה לו \u0003במראה\u0004 בחלום, שהיא מדרגת גבריאל. עתה בסוף ימיו, נחשכה, לו מדרגת החלום ביותר, ועל כן מזכיר לו הכתוב, ב' החלומות שהיו מאירים לו, שנאמר, לאל הנראה אליו פעמים."],[2,"ודא בגין דחטא וכו':","וזה היה לו בשביל שחטא, ועמדה הלבנה, שהיא הנוקבא, להתחסר. מהו הטעם שעמדה להתחסר, הוא משום שלא שמר ברית קדש, וחזר על נשים נכריות. וזהו תנאי שעשה הקב\"ה עם דוד, שכתוב, אם ישמרו בניך בריתי וגו', גם בניהם עדי עד ישבו לכסא לך."],[3,"מאי עדי עד:","הוא כמו שכתוב, כימי השמים על הארץ. ומשום ששלמה לא שמר ברית הזה כראוי, התחילה הלבנה להתחסר, ועל כן, היה נצרך לחלום בסופו. וכן יעקב, מחמת שלא היה שלם, היה נצרך לחלום, כמו שאמרנו לעיל."],[4,"והנה ה' נצב וגו':","כאן בסולם, ראה יעקב קשר האמונה, שהיא הנוקבא, המקשרת כל הספירות כאחד. \u0003נצב עליו,\u0004 הוא כמו שאתה אומר \u0003נציב מלח,\u0004 דהיינו \u0003תל,\u0004 כי כל המדרגות כולם כאחד נמצאות על אותו הסולם, שהוא הנוקבא, להתקשר הכל בקשר אחד, משום שאותו הסולם ניתן בין שני הצדדים, וזהו שכתוב אני הויה אלקי אברהם אביך ואלקי יצחק הארץ וגו', אלו הם שני הצדדים ימין ושמאל. כי אברהם הוא ימין ויצחק הוא שמאל. פירוש. כי הוקשה לו, שהמלה \u0003נצב,\u0004 היא מיותרת, שהיה די לומר והנה ה' עליו. ועל כן פירש, אשר \u0003נצב,\u0004 פירושו \u0003תל,\u0004 מלשון \u0003נציב\u0004 מלח. ומשמיענו הכתוב, אשר כל המדרגות נגלו לו על הסולם הזה, בקשר אחד, בדומה לתל. לכן אומר, והנה הויה \u0003נצב\u0004 עליו וגו', כי כל המדרגות נרמזות בכתוב הזה, כי \u0003הויה\u0004 הוא תפארת הכולל שש המדרגות חג\"ת נה\"י, \u0003אברהם\u0004 הוא חכמה, \u0003יצחק\u0004 הוא בינה \u0003הארץ\u0004 הוא מלכות, שד' ספירות הללו: חו\"ב תו\"מ, כוללות כל עשר הספירות. וז\"ש \u0003בגין דאתיהיב ההוא סולם בין תרין סטרין.\u0004 כי הסולם, שהוא הנוקבא עיקרה היא משמאל. אבל השמאל אינו מתקיים בלי ימין, לפיכך ניתנה הנוקבא בקו האמצעי, הכולל לימין ושמאל. ומקבלת חסדים מימין וחכמה משמאל כנודע. וע\"כ, כבר יש כאן בקשר הזה, כל הספירות, שהן: ימין ושמאל שהם אברהם ויצחק, וקו האמצעי שה\"ס הוי\"ה, והסולם עצמו שה\"ס המלכות."],[5,"דבר אחר והנה ה' נצב עליו:","אין פירושו שנצב על הסולם, אלא נצב על יעקב, כדי שיעשו כולם מרכבה קדושה: ימין ושמאל, וביניהם יעקב, שהם חג\"ת, וכנסת ישראל, שהיא הנוקבא, התקשר ביניהם. וזהו שכתוב אני ה' אלקי אברהם אביך ואלקי יצחק, מאין לנו שיעקב הוא באמצע אברהם ויצחק, זהו משמע, משכתוב אלקי אברהם אביך ואלקי יצחק, ולא כתוב, אלקי יצחק אביך שאז היה נבחן אל השלישי שבאבות, דהיינו בן יצחק, הוא ללמדנו, שכיון שנתקשר באברהם, שנתיחס להיות בנו, נמצא שהוא קודם ליצחק, והוא באמצע אברהם ויצחק. כי כן הוא בסוד המרכבה, שאברהם ויצחק הם ימין ושמאל, ויעקב הוא באמצע שניהם. ואחר כך כתוב. הארץ אשר אתה שוכב עליה, שהיא הנוקבא הרי שכולם יחד הם מרכבה קדושה אחת, דהיינו ג' הקוין עם הנוקבא. וכאן ראה יעקב שיהיה בחיר שבאבות. והיינו כמ\"ש בזהר (פנחס אות ל\"ה / ג) בביאור הכתוב, לא עתה יבוש יעקב וגו' ע\"ש."],[6,"תא חזי, אלקי אברהם אביך:","מכיון שאמר אברהם אביך, ודאי שהוא באמצע אברהם ויצחק כנ\"ל. \u0003ואלקי יצחק:\u0004 נרמז בזה, שיעקב קשור לב' הצדדים ימין ושמאל, וכולל אותם: הוא קשור לצד אחד לימין, שכתוב אברהם אביך, וקשור לצד האחר לשמאל, שכתוב ואלקי יצחק שיש תוספת \u0003ו'\u0004 דהיינו ואלקי, אצל יצחק, להורות שיעקב אוחז ב' הצדדים. כי \u0003ו'\u0004 רומז על ת\"ת שהוא יעקב, המחובר עם אלקי יצחק שה\"ס השמאל. באופן שהכתוב מחברו באברהם, בימין, שאומר בו, \u0003אביך,\u0004 ומחברו באלקי יצחק עם ה \u0003ו'.\u0004"],[7,"ועד דיעקב לא אתנסיב וכו':","וכל עוד שלא היה יעקב נשוי אשה לא נאמר בו יותר בגלוי משנאמר כאן, שלא כתוב בו במפורש אלקי יעקב, כמו באברהם ויצחק. ונאמר בגלוי רק למי שיודע דרכי התורה, כלומר, שיהיה מרכבה בב' הדרכים בימין ושמאל, וכל עוד שלא נשא אשה, הוא יכול להיות מרכבה לז\"א בלבד, שה\"ס ימין, ולא להנוקבא שה\"ס שמאל."],[7,"לבתר דאתנסיב וכו':","לאחר שנשא אשה, והוליד בנים, נאמר לו בגלוי, וז\"ש ויצב שם מזבח ויקרא לו אל אלקי ישראל. דהיינו בגלוי כי נתיחד שמו עליו. מכאן למדנו, שכל מי שלא נשלם למטה, בדכר ונוקבא, דהיינו שלא נשא אשה, אינו נשלם למעלה. ויעקב אינו דומה, כי הוא נשלם למעלה ולמטה, עוד מטרם שנשא אשה. אבל לא בגלוי, כי לא ייחד שמו עליו."],[8,"ואי תימא דאשתלים וכו':","ואם תאמר שנשלם לגמרי בשעה ההיא, אע\"פ שלא נשא אשה. אינו כן. אלא רק ראה שישתלם לאחר זמן. ואם תאמר, הרי כתוב, והנה אנכי עמך ושמרתיך בכל אשר תלך, שמשמע שנשלם לגמרי. אינו כן, אלא, דפירוש הוא, שהשגחתו של הקב\"ה והשמירה שלו לא תעזוב את יעקב לעולם, בכל מה שהוא צריך בעולם הזה, אבל בעולם העליון לא יוכל להשיג עד שיהיה נשלם, דהיינו שישא אשה."],[9,"ויקץ וגו' ואנכי לא ידעתי:","ושואל. וכי פליאה הוא שלא ידע השגה גדולה כזו. ומשיב, אלא מהו הפירוש של ואנכי לא ידעתי, הוא כמו שאתה אומר, ופני ה' לא חליתי. כלומר, לא ידעתי, פירושו לשון חיבור ודביקות, כמו, לא חליתי, אמר יעקב, וכי כל זה נתגלה לי ולא הסתכלתי לדעת את השם הקדוש \u0003אנכי,\u0004 שהוא השכינה, ולהכנס תחת כנפי השכינה להיות אדם שלם."]],[[0,"","כָּתוּב (מלכים א ג) נִרְאָה ה' אֶל שְׁלֹמֹה בַּחֲלוֹם הַלָּיְלָה וַיֹּאמֶר אֱלֹהִים שְׁאַל מָה אֶתֶּן לָךְ. וְאִם תֹּאמַר, כָּאן בַּחֲלוֹם, וְכִי אֵיזוֹ רְשׁוּת יֵשׁ לַחֲלוֹם בָּזֶה? אֶלָּא כָּאן נִכְלֶלֶת דַּרְגָּה בְּדַרְגָּה, הַדַּרְגָּה הָעֶלְיוֹנָה עִם הַדַּרְגָּה הַתַּחְתּוֹנָה. מִשּׁוּם שֶׁעַד עַכְשָׁו שְׁלֹמֹה לֹא הָיָה שָׁלֵם. כֵּיוָן שֶׁנִּשְׁלַם, כָּתוּב (שם ה) וַה' נָתַן חָכְמָה לִשְׁלֹמֹה, וְכָתוּב (שם) וַתֵּרֶב חָכְמַת שְׁלֹמֹה. שֶׁעָמְדָה הַלְּבָנָה בִּשְׁלֵמוּתָהּ, וּבֵית הַמִּקְדָּשׁ נִבְנָה, וְאָז הָיָה רוֹאֶה שְׁלֹמֹה אֶת הַחָכְמָה עַיִן בְּעַיִן, וְלֹא הִצְטָרֵךְ לַחֲלוֹם."],[1,"","אַחַר שֶׁחָטָא, הִצְטָרֵךְ לַחֲלוֹם כְּבָרִאשׁוֹנָה, וְעַל כֵּן כָּתוּב (שם יא) הַנִּרְאָה אֵלָיו פַּעֲמָיִם. וְכִי פַּעֲמַיִם הָיָה וְלֹא יוֹתֵר? אֶלָּא צַד הַחֲלוֹם הָיָה לוֹ פַּעֲמַיִם, וְצַד הַחָכְמָה הָיָה בְּכָל יוֹם."],[2,"","וְעִם כָּל זֶה הַצַּד שֶׁל הַחֲלוֹם הָיָה יוֹתֵר עַל כָּל שְׁאָר בְּנֵי הָאָדָם, מִשּׁוּם שֶׁנִּכְלְלָה דַּרְגָּה עִם דַּרְגָּה, מַרְאֶ\"ה בְּמַרְאֶ\"ה. וְהִנֵּה כָּאן בְּסוֹף יָמָיו יוֹתֵר חָשׁוּךְ, וְזֶה מִשּׁוּם שֶׁחָטָא, וְהַלְּבָנָה עָמְדָה לְהִפָּגֵם. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא שָׁמַר אֶת בְּרִית הַקֹּדֶשׁ בְּהִתְעַסְּקוּתוֹ עִם נָשִׁים נָכְרִיּוֹת, וְזֶה הַתְּנַאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה עִם דָּוִד, שֶׁכָּתוּב (תהלים קלב) אִם יִשְׁמְרוּ בָנֶיךְ בְּרִיתִי וְגוֹ', גַּם בְּנֵיהֶם עֲדֵי עַד יֵשְׁבוּ לְכִסֵּא לָךְ."],[3,"","מַה זֶּה עֲדֵי עַד? הַיְנוּ שֶׁכָּתוּב (דברים יא) כִּימֵי הַשָּׁמַיִם עַל הָאָרֶץ. וּמִשּׁוּם שֶׁשְּׁלֹמֹה לֹא שָׁמַר אֶת הַבְּרִית הַזּוֹ כָּרָאוּי, הִתְחִילָה הַלְּבָנָה לְהִפָּגֵם, וְעַל כֵּן בַּסּוֹף הִצְטָרֵךְ אֶת הַחֲלוֹם, וְכֵן יַעֲקֹב הִצְטָרֵךְ אֶת הַחֲלוֹם, כְּמוֹ שֶׁבִּאַרְנוּ. רַעְיָא מְהֵימְנָא"],[4,"","וְהִנֵּה ה' נִצָּב עָלָיו וְגוֹ'. כָּאן רָאָה יַעֲקֹב הַקֶּשֶׁר שֶׁל הָאֱמוּנָה כְּאֶחָד. נִצָּב עָלָיו, וְכָתוּב (מלכים א כב) וּמֶלֶךְ אֵין בֶּאֱדוֹם נִצָּב מֶלֶךְ. (נציב מלח) רָאָה, שֶׁכָּל הַדְּרָגוֹת עוֹמְדוֹת כֻּלָּן יַחַד עַל אוֹתוֹ הַסֻּלָּם לִקְשֹׁר הַכֹּל בְּקֶשֶׁר אֶחָד, מִשּׁוּם שֶׁאוֹתוֹ הַסֻּלָּם נִתָּן בֵּין שְׁנֵי צְדָדִים. זֶהוּ שֶׁכָּתוּב (בראשית כח) אֲנִי ה' אֱלֹהֵי אַבְרָהָם אָבִיךְ וֵאלֹהֵי יִצְחָק הָאָרֶץ וְגוֹ'. אֵלּוּ הֵם שְׁנֵי צְדָדִים, בְּיָמִין וּבִשְׂמֹאל."],[5,"","דָּבָר אַחֵר וְהִנֵּה ה' נִצָּב עָלָיו (ויאמר) - עַל יַעֲקֹב, שֶׁהַכֹּל יִהְיֶה מֶרְכָּבָה קְדוֹשָׁה, יָמִין וּשְׂמֹאל, וְיַעֲקֹב בְּתוֹכָם, וּכְנֶסֶת יִשְׂרָאֵל לְהִקָּשֵׁר בֵּינֵיהֶם. זֶהוּ שֶׁכָּתוּב אֲנִי ה' אֱלֹהֵי אַבְרָהָם אָבִיךְ וֵאלֹהֵי יִצְחָק. מִנַּיִן לָנוּ שֶׁיַּעֲקֹכ בָּאֶמְצַע? מַשְׁמָע שֶׁכָּתוּב אֱלֹהֵי אַבְרָהָם אָבִיךְ וֵאלֹהֵי יִצְחָק (הארץ), וְלֹא כָתוּב וֵאלֹהֵי יִצְחָק אָבִיךְ. שֶׁכֵּיוָן שֶׁנִּקְשָׁר עִם אַבְרָהָם, נִמְצָא שֶׁהוּא בָּאֶמְצַע. וְאַחַר כָּךְ, הָאָרֶץ אֲשֶׁר אַתָּה שֹׁכֵב עָלֶיהָ - הִנֵּה הַכֹּל מֶרְכָּבָה קְדוֹשָׁה אַחַת. וְכָאן הוּא רָאָה שֶׁיִּהְיֶה שְׁלֵמוּת הָאָבוֹת."],[6,"","בֹּא רְאֵה, אֱלֹהֵי אַבְרָהָם אָבִיךְ, שֶׁכֵּיוָן שֶׁאָמַר אַבְרָהָם אָבִיךְ, וַדַּאי שֶׁהוּא בָּאֶמְצַע. וֵאלֹהֵי יִצְחָק, כָּאן נִרְמָז שֶׁקָּשׁוּר לִשְׁנֵי צְדָדִים וְאוֹחֵז אוֹתָם. קָשׁוּר לְצַד אֶחָד - שֶׁכָּתוּב אַבְרָהָם אָבִיךְ. וְקָשׁוּר לְצַד אַחֵר - שֶׁכָּתוּב וֵאלֹהֵי יִצְחָק. תּוֹסֶפֶת וָא\"ו לְיִצְחָק, לְהַרְאוֹת שֶׁיַּעֲקֹב אָחוּז לִשְׁנֵי צְדָדִים."],[7,"","וְעַד שֶׁיַּעֲקֹב לֹא נִשָּׂא, לֹא נֶאֱמַר בְּגִלּוּי יוֹתֵר, וְנֶאֱמַר בְּגִלּוּי לְמִי שֶׁמַּכִּיר דַּרְכֵי הַתּוֹרָה. אַחַר שֶׁנִּשָּׂא וְהוֹלִיד, נֶאֱמַר לוֹ בְּגִלּוּי. זֶהוּ שֶׁכָּתוּב (בראשית לג) וַיַּצֶּב שָׁם מִזְבֵּחַ וַיִּקְרָא לוֹ אֵל אֱלֹהֵי יִשְׂרָאֵל. מִכָּאן לָמַדְנוּ, מִי שֶׁלֹּא נִשְׁלָם לְמַטָּה - לֹא נִשְׁלָם לְמַעְלָה. שׁוֹנֶה יַעֲקֹב, שֶׁנִּשְׁלַם לְמַעְלָה וּלְמַטָּה, אֲבָל לֹא בְּגִלּוּי."],[8,"","וְאִם תֹּאמַר שֶׁנִּשְׁלַם בְּאוֹתָהּ הַשָּׁעָה - לֹא. אֶלָּא רָאָה שֶׁיֻּשְׁלַם לְאַחַר זְמַן. וְאִם תֹּאמַר, הִנֵּה כָּתוּב וְהִנֵּה אָנֹכִי עִמָּךְ וּשְׁמַרְתִּיךְ בְּכֹל אֲשֶׁר תֵּלֵךְ? אֶלָּא הַשְׁגָּחַת הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁמִירָתוֹ לֹא נֶעֶזְבָה מִיַּעֲקֹב לְעוֹלָמִים בְּכָל מַה שֶּׁהִצְטָרֵךְ לוֹ בָּעוֹלָם הַזֶּה, אֲבָל בָּעוֹלָם הָעֶלְיוֹן עַד שֶׁנִּשְׁלַם."],[9,"","וַיִּיקַץ יַעֲקֹב מִשְּׁנָתוֹ וַיֹּאמֶר אָכֵן יֵשׁ ה' בַּמָּקוֹם הַזֶּה וְאָנֹכִי לֹא יָדָעְתִּי. וְכִי תְמִיהָה הוּא שֶׁלֹּא יָדַע? אֶלָּא מַה זֶּה וְאָנֹכִי לֹא יָדָעְתִּי? כְּמוֹ שֶׁנֶּאֱמַר (שמואל א יג) וּפְנֵי ה' לֹא חִלִּיתִי. אָמַר, וְכִי כָּל זֶה הִתְגַּלָּה לִי וְלֹא הִסְתַּכַּלְתִּי לָדַעַת אָנֹכִי, וּלְהִכָּנֵס תַּחַת כַּנְפֵי הַשְּׁכִינָה וְלִהְיוֹת שָׁלֵם?"]]],[["תָּא חֲזֵי, כְּתִיב, (בראשית כ״ה:כ״ב) וַתֹּאמֶר אִם כֵּן לָמָּה זֶה אָנֹכִי, כָּל יוֹמָא וְיוֹמָא חָמַאת רִבְקָה נְהוֹרָא דִשְׁכִינְתָּא, דְּהַוְיָא שְׁכִינְתָּא בְּמִשְׁכְּנָהָא וְצַלִּיאַת תַּמָּן. כֵּיוָן דְּחָמַאת עָאקוּ דִּילָהּ בִּמְעָהָא, מַה כְּתִיב וַתֵּלֶךְ לִדְרשׁ אֶת ה', נָפְקַת מִדַּרְגָּא דָא לְדַרְגָּא אָחֳרָא דְּאִיהוּ הוי\"ה. בְּגִינֵי כָךְ אָמַר יַעֲקֹב, וְכִי כָּל כָּךְ חָמֵינָא, וְאָנֹכִי לֹא יָדַעְתִּי, בְּגִין דְּהֲוָה בִּלְחוֹדוֹי וְלָא עָאל תְּחוֹת גַּדְפֵי דִשְׁכִינְתָּא.","מִיָּד (בראשית כ״ח:י״ז) וַיִּירָא וַיֹּאמַר מַה נּוֹרָא הַמָּקוֹם הַזֶּה. מִלָּה דָא לִתְרֵין סִטְרִין אִיהוּ. מַה נּוֹרָא הַמָּקוֹם הַזֶּה, חַד עַל הַהוּא מָקוֹם דְּקָאֲמַר בְּקַדְמִיתָא. וְחַד עַל אָת קַיָּימָא קַדִּישָׁא דְּלָא בַּעְיָא לְאִתְבַּטָּלָא.","וְאַף עַל גַּב דְּאִינְהוּ תְּרֵי סִטְרֵי, חַד הוּא. אָמַר (בראשית כח) אֵין זֶה כִּי אִם בֵּית אֱלֹהִים, אֵין זֶה, לְמֶהֱוֵי בָּטִיל. אֵין זֶה, לְאִשְׁתַּכְּחָא בִּלְחוֹדוֹי, קְיָימָא דִילֵיהּ לָאו אִיהוּ אֶלָּא בֵּית אֱלֹהִים, לְאִשְׁתַּמְּשָׁא בֵּיהּ וּלְמֶעְבַּד בֵּיהּ פֵּירִין, וְלַאֲרָקָא בֵּיהּ בִּרְכָאן מִכָּל שָׁיְיפֵי גוּפָא. דְּהַאי הוּא תַּרְעָא דְּכָל גּוּפָא, הֲדָא הוּא דִכְתִיב, (בראשית כ״ח:י״ז) וְזֶה שַׁעַר הַשָּׁמָיִם, דָּא תַּרְעָא דְגוּפָא וַדַּאי, תַּרְעָא אִיהוּ לַאֲרָקָא בִּרְכָאן לְתַתָּא, אָחִיד לְעֵילָא וְאָחִיד לְתַתָּא. אָחִיד לְעֵילָא, דִּכְתִיב וְזֶה שַׁעַר הַשָּׁמָיִם. (אחיד) לְתַתָּא, דִּכְתִיב אֵין זֶה כִּי אִם בֵּית אֱלֹהִים. וְעַל דָּא וַיִּירָא וַיֹּאמַר מַה נּוֹרָא הַמָּקוֹם הַזֶּה, וּבְנֵי נָשָׁא לָא מַשְׁגְּחָן בִּיקָרָא דְּבֵיהּ לְמֶהֱוֵי בֵּיהּ שְׁלִים, לְעֵילָא וְתַתָּא. אֲתָא אֲבוֹי וּנְשָׁקֵיהּ.","אָמַר רִבִּי יִצְחָק, כַּד מִלִּין אִינוּן שְׁמַעְנָא מִפּוּמֵיהּ בָּכֵינָא, וְאֲמֵינָא בְּרִיךְ רַחֲמָנָא דְּלָא בָּטִיל מֵעַלְמָא חָכְמְתָא עִלָּאָה. אָזְלִינָא עִמְּהוֹן עַד תְּלַת פַּרְסֵי, עַד דְּעָאֳלָנָא עִמְּהוֹן לְמָתָא. לָא סְפִיקוּ לְמֵיעַל, עַד דְּשִׁדֵּךְ הַהוּא בַּר נַשׁ לִבְרֵיהּ, וְאָמְרֵי לֵיהּ, מִלָּיךְ לָא יְהוֹן לְבַטָּלָה.","אֲמִינָא, הָא דְּאָמַר רִבִּי שִׁמְעוֹן, דְּמִלִּין אִלֵּין כֻּלְּהוּ בְּרָזָא דְחָכְמְתָא נִינְהוּ, וּלְאַחֲזָאָה מִלִּין אָחֳרָנִין. כַּד סַדַּרְנָא מִלִּין קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן. אָמַר לִי, לָא תֵימָא דְּמִלִּין אִלֵּין דִּינוּקָא נִינְהוּ, אֶלָּא מִלִּין דְּרָזִין עִלָּאִין נִינְהוּ, וְכֹלָּא בְּרָזָא דְּחָכְמְתָא רְשִׁימִין.","\u0003סתרי תורה\u0004 (בראשית כ״ח:י״ב) וַיַּחֲלם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָּה וְרֹאשׁוֹ מַגִּיעַ הַשָׁמַיְמָה. חֶלְמָא, מַדְרֵגָא שְׁתִּיתָּאָה מֵאִינוּן דַּרְגִּין תְּרֵין דִּנְבוּאָה, עַד הַהוּא דַרְגָּא, שִׁיתּ דַּרְגִּין אִינוּן, וְעַל דָּא, חֶלְמָא חַד מִשִׁתִּין דַּרְגִּין דִּנְבוּאָה. סֻלָּם, חָמָא בְּנוֹי דְּזַמִּינִין לְקַבְּלָא אוֹרַיְיתָּא, בְּטוּרָא דְסִינַי. סֻלָּם דָּא סִינַי. (ס\"א בגימטריא) בְּגִין דְּאִיהוּ נָעִיץ בְּאַרְעָא, וְחָשִׁיב בִּסְלִיקוּ לִשְׁמַיָא. וְכָל רְתִּיכִין (קדישין) וּמַשִׁרְיָין עִלָּאִין, כֻּלְּהוּ נָחֲתֵּי (נחתו) תַּמָּן בַּהֲדֵי קוּדְשָׁא בְּרִיךָ הוּא, כַּד יָהִיב לוֹן אוֹרַיְיתָּא.","וְכלָּא חָמָא. חָמָא מַטטרון, סָבָא דְבֵיתָּא, דְּשַׁלִּיט בְּכָל דִּילֵיהּ. דְּאִיהוּ קָאי בְּשָׁלְטָנוּ על (האי) עַלְמָא. בְּשָׁלְטָנוּ בְּשֵׁם שד\"י. וסָלִיק לְעֵילָא, בִּסְלִיקוּ דשמָא דְּמָרֵיהּ הוי\"ה, אֲתַּר דְּיַעֲקֹב אִשְׁתַּלִים בֵּיהּ לְבָתָּר. וְרֹאשׁוֹ, דּשם שַׁדַּי, אִיהוּ י', וְדָא מַגִּיעַ הַשָׁמַיְמָה. כֵּיוָן דְּמָטֵי וְסָלִיק אָתּ דָּא, לְהַהוּא אֲתַּר, אִשְׁתְּלִים וְאִתְּקְרֵי בְּהַהוּא שְׁמָא דְּמָארֵיהּ הוי\"ה.","(בראשית כ״ח:י״ב) והִנֵּה מַלְאֲכֵי אֱלהִים עֹלִים וְיֹרְדִים בּוֹ, אִינוּן מַלְאָכִין קַדִּישִׁין, דִּקְרֵבִין לְמַלְכוּתָּא סָלְקִין, וְאִינוּן אָחֳרָנִין דְּלָא קְרֵבִין הֵם נָחֲתֵּי.","וְתּוּ, בּוֹ סָלְקֵי ונָחֲתֵּי, כַּד אִיהוּ סָלִיק, סָלְקִין בַּהֲדֵיהּ, כַּד נָחִיתּ, נָחֲתִּין בַּהֲדֵיהּ. מַלְאֲכֵי אֱלהִים, תְּרֵיסַר מַרְגְּלִיטָאן טָבָאן, ואִינוּן, מִיכָאֵל, קדמיאל, פּדאל, גבריאל, צּדקיאל, חסדיאל, רפּאל, רזיאל, סטורי\"ה, נוריאל. יפּיאל, ענאל, אַלְפֵּי שִׁנְאָן, שִׁנְאָ\"ן, שׁוֹ\"ר, נְשֶׁ\"ר, אַרְיֵ\"ה, ן' אָדָם כָּלִיל דְּכַר וְנוּקְבָא. וְאִינוּן סָלְקֵי, כַּד אִיהוּ סָלִיק, וְאִלֵּין נַחֲתֵּי, כַּד אִיהוּ נָחִיתּ.","וְתּוּ, כָּל אִינוּן דְּשָׁלְטֵי בְּשָׁלְטָנוּ דְּהַאי עַלְמָא, עַל יְדֵיהּ סָלְקִין, וְכָל אִינוּן דְּנָחֲתֵּי עַל יְדֵיהּ נָחֲתֵּי, כֻּלְּהוּ בְּהַאי סֻלָּם. הוי\"ה שָׁלְטָא עַל כֹּלָּא, דִּכְתִּיב, (בראשית כ״ח:י״ג) וְהִנֵּה ה' נִצָּב עָלָיו. כַּד אִתְּעַר, כְּתִּיב, (בראשית כ״ח:י״ז) אֵין זֶה כִּי אִם בֵּיתּ אֱלהִים וזֶה שַׁעַר הַשָׁמָיִם. בֵּיתּ אֱלהִים וַדַּאי. וְאִיהוּ תַּרְעָא לְאָעֳלָא לְגוֹ, דִּכְתִּיב, (תהילים קי״ח:י״ט-כ׳) פִּתְּחוּ לִי שַׁעֲרֵי צֶּדֶק אָבֹא בָם אוֹדֶה יָהּ. זֶה הַשַׁעַר לַה'. זֶה שַׁעַר הַשָׁמַיִם כּלָּא חַד.","(בראשית כ״ח:כ׳) וַיִּדַּר יַעֲקֹב נְדֶר לֵאמֹר אִם יִהְיֶה אֱלהִים עִמָּדִי וְגו', אָמַר רִבִּי יְהוּדָה כֵּיוָן דְּכָל הַאי אַבְטַח לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אַמַּאי לָא הֶאֱמִין, דְּאָמַר (בראשית כ״ח:כ׳) אִם יִהְיֶה אֱלֹהִים עִמָּדִי וְגו'. אֶלָּא, אָמַר יַעֲקֹב, חֶלְמָא חָלַמְנָא, וְחֶלְמִין מִנַּיְיהוּ קְשׁוֹט וּמִנַּיְיהוּ לָא קְשׁוֹט, וְאִם יִתְקַיֵּים הָא יְדַעְנָא דְּחֶלְמָא קְשׁוֹט הוּא, וְעַל דָּא אָמַר אִם יִהְיֶה אֱלהִים וְגו', כְּמָה דְחָלַמְנָא, וְהָיָה יְיָ לִי לֵאלֹהִים, אֲנָא אֱהֵא מָשִׁיךְ בִּרְכָאן מִמַּבּוּעָא דְּנַחֲלָא דְּכֹלָּא, לְאֲתַר דָּא דְּאִקְרֵי אֱלהִים.","תָּא חֲזֵי יִשְׂרָאֵל דְּאִיהוּ בְּאֶמְצָעִיתָא, כֹּלָּא נָטִיל הוּא בְּקַדְמִיתָא מִמְּקוֹרָא דְּכֹלָּא, וּלְבָתַר דְּיִמְטֵי לֵיהּ, מִנֵּיהּ, נָגִיד וְאַמְשִׁיךְ לְהַאי אֲתַר, מַשְׁמַע דִּכְתִיב, וְהָיָה יְיָ לִי בְּקַדְמִיתָא, וּלְבָתַר כֹּלָּא לֵאלהִים. כְּמָה דְּאֱלֹהִים, יְהֵא נָטִיר וְעָבִיד לִי, כָּל אִלֵּין טָבָאן, אוּף אֲנָא אֱהֵא מָשִׁיךְ לֵיהּ מֵאֲתַר דִּילִי כָּל אִינוּן בִּרְכָאן, וְיִתְחַבַּר קִשְׁרָא דְּכֹלָּא בֵּיהּ. אֵימָתַי, (בראשית כ״ח:כ״א) וְשַׁבְתִּי בְּשָׁלוֹם אֶל בֵּית אָבִי, כַּד אֱהֵא יָתִיב בְּדַרְגָּא דִילִי, וְאֱהֵא יָתִיב בְּדַרְגָּא דְּשָׁלוֹם לְתַקְּנָא בֵּית אָבִי, וְשַׁבְתִּי בְשָׁלוֹם דַּיְיקָא, כְּדֵין וְהָיָה יְיָ לִי לֵאלהִים.","דָבָר אַחֵר וְשַׁבְתִּי בְשָׁלוֹם אֶל בֵּית אָבִי, דְּתַמָּן הוּא אַרְעָא קַדִּישָׁא, תַּמָּן אִשְׁתְּלִים. וְהָיָה יְיָ לִי לֵאלהִים. בְּאֲתַר דָּא, אֲסַלֵּק (אסתלק) מִדַּרְגָּא דָא לְדַרְגָּא אָחֳרָא כְּדְקָא יְאוּת, וְתַמָּן אֶפְלַח פּוּלְחָנֵיהּ.","רִבִּי חִיָּיא פָּתַח וְאָמַר, (תהילים ס״ה:ד׳) דִּבְרֵי עֲוֹנוֹת גָּבְרוּ מֶנִּי פְּשָׁעֵינוּ אַתָּה תְכַפְּרֵם. הַא קְרָא קַשְׁיָא, דְּלָאו סוֹפֵיהּ רֵישֵׁיהּ, וְלָאו רֵישֵׁיהּ סוֹפֵיהּ. אֶלָּא דָּוִד בָּעָא עַל גַּרְמֵיהּ, וּלְבָתַר בַּעְיָא עַל כֹּלָּא. דִּבְרֵי עֲוֹנוֹת גָּבְרוּ מֶנִּי. אָמַר דָּוִד, אֲנָא יַדָעְנָא בְּגַרְמַי דְּחַבְנָא, אֲבָל כַּמָּה חַיָּיבִין אִינוּן בְּעַלְמָא, דְּאִתְגַּבְּרוּ חוֹבַיְיהוּ עֲלַיְיהוּ יַתִּיר מִנִּי. הוֹאִיל וְכֵן, לִי וּלְהוֹן, פְּשָׁעֵינוּ אַתָּה תְכַפְּרֵם."],[[0,"ת\"ח כתיב ותאמר אם כן למה זה אנכי:","כל יום ויום ראתה רבקה אור השכינה, הנקראת \u0003אנכי,\u0004 כי השכינה היתה באהלה והתפללה שמה. כיון שראתה הצרה שלה במעיה, מה כתוב, ותלך לדרוש את הוי\"ה, כי יצאה ממדרגה זו ד \u0003אנכי,\u0004 אל מדרגה אחרת שהוא \u0003הוי\"ה.\u0004 הרי שאנכי הוא שם השכינה. משום זה אמר יעקב, וכי כל כך ראיתי \u0003ואנכי לא ידעתי,\u0004 כי היה לבדו ולא נכנס תחת כנפי השכינה, כנ\"ל."],[1,"מיד, ויירא ויאמר מה נורא המקום הזה:","דבר זה הוא לשני צדדים, כי מה נורא המקום הזה נאמר, אחד, על אותו המקום שאמר בתחילה, שהוא השכינה. ואחד, על אות ברית קודש, שלא צריך להתבטל."],[2,"ואע\"ג דאינהו תרי וכו':","ואף על פי שהם שתי בחינות, דהיינו יסוד ומלכות, אחת הן. אמר, אין זה כי אם בית אלקים, אין \u0003זה,\u0004 שהוא יסוד המכונה \u0003זה,\u0004 ראוי להיות בטל, אין \u0003זה,\u0004 ראוי להמצא בלבדו, קיום שלו, אינו, כי אם בית אלקים, שהיא הנוקבא, להשתמש בה ולעשות בה פירות, ולהשפיע לה ברכות מכל אברי הגוף, כי \u0003זה,\u0004 שהוא יסוד, הוא השער לכל הגוף, שהוא תפארת, וזהו שכתוב, \u0003וזה\u0004 שער השמים, דהיינו ת\"ת הנקרא גוף ונקרא ג\"כ שמים. \u0003זה\u0004 הוא ודאי שער הגוף, הוא שער להריק ברכות למטה, אל הנוקבא, נאחז למעלה, בשמים שהוא ת\"ת, ונאחז למטה, בהנוקבא הנקראת \u0003מקום\u0004 וכן בית אלקים. ומפרש, נאחז למעלה, כי כתוב, \u0003וזה\u0004 שער השמים, שהיסוד הוא שער הת\"ת הנקרא שמים, כנ\"ל. נאחז למטה, שכתוב אין \u0003זה,\u0004 כי אם בית אלקים, שפירושו, אין \u0003זה,\u0004 שהוא יסוד, נמצא, כי אם בבית אלקים שהיא הנוקבא, כנ\"ל. ועל כן ויירא ויאמר מה נורא המקום הזה, שה \u0003מקום\u0004 הוא הנוקבא ו \u0003זה\u0004 הוא היסוד. ובני אדם אין משגיחים ביקרו, של היסוד, להיות שלם בו. בא אביו ונשק אותו. המאמר הזה הוא המשך דברי בנו של אותו איש שפגש בו ר' יצחק, כמ\"ש לעיל (באות ל\"ב) וכשסיים דבריו, בא אביו ונשקו."],[3,"אמר רבי יצחק וכו':","אר\"י, כששמעתי דברים אלו מפיו בכיתי. ואמרתי, ברוך הרחמן שלא ביטל חכמה עליונה מן העולם. הלכתי עמהם שלש פרסאות עד שנכנסתי עמהם לעיר. לא הספיקו להכנס לעיר עד שאותו האיש שידך את בנו. ואמרתי לו, דבריך לא יהיו לבטלה. היינו מה שאמר לעיל (באות ס\"ב) שהשלמות באה אחר שנושאים אשה. וכיון שבא לישא אשה, א\"ל, שיקיים דבריו."],[4,"אמינא הא דאמר וכו':","אמרתי, היינו דאמר ר\"ש שדברים הללו, שבפרשה זו של הסלם, הם כולם בסוד החכמה, ומראים על דברים אחרים, מלבד פשטם. כשבאתי וסידרתי הדברים לפני רבי שמעון, אמר לי, אל תאמר, שדברים הללו של ילד הם, אלא הם דברי סודות עליונים, וכולם רשומים בסוד החכמה."],[5,"ויחלום והנה סלם וגו':","החלום הוא מדרגה ששית מאלו ב' המדרגות של הנבואה, שהם נצח והוד דז\"א, כי מכאן עד מדרגה ההיא של החלום, שהיא הוד דנוקבא, הן שש מדרגות, שהן: יסוד, דז\"א, וחסד, גבורה ת\"ת, נצח, והוד דנוקבא. ועל כן החלום הוא אחד מששים מנבואה. כי כל ספירה מאלו השש, כלולה מעשר ספירות, ועשר פעם שש הן ששים, והחלום שהוא התחתון מהן, נמצא שהוא אחד מששים."],[5,"סלם חמא וכו':","סלם, רומז, שראה בניו שעתידים לקבל התורה בהר סיני. כי סלם הוא סיני, משום, שהר סיני הוא כמו שאמר הכתוב, מוצב בארץ, וראשו, דהיינו מעלתו, מגיע השמימה, וכל המרכבות ומחנות מלאכים העליונים כולם ירדו שם ביחד עם הקב\"ה, בעת שנתן להם התורה. דהיינו כמש\"ה, ומלאכי אלקים עולים ויורדים בו."],[6,"וכלא חמא וכו':","והכל ראה יעקב בחלומו ראה את המלאך מטטרון, זקן ביתו, של הקב\"ה, המושל בכל אשר לו, שהוא עומד בשליטה על העולם בכח השליטה שלו בשם שדי, ועולה למעלה בעליה של שם רבונו, שהוא הויה, הוא המקום שיעקב נשלם בו. לאחר כך, והראש של השם שדי שהוא \u0003י',\u0004 זה מגיע השמימה. כיון שאות הזו עולה ומגעת לאותו המקום, דהיינו לשמים, המלאך מטטרון נשלם ונקרא בשם רבונו, הוי\"ה."],[6,"","פירוש הדברים. בתחילה צריכים לידע בחינת מטטרון מה הוא. וביאורו תמצא בתקונים (תק' ע' דף קי\"ט ע\"ב) שאומר בהכתוב, והחיות רצוא ושוב, \u0003רצוא דא נוריאל, ושוב דא מטטרון.\u0004 פירוש. כי מקרא זה נאמר, בעת שהחיות מקבלים מהארת הזווג של זו\"ן דאצילות, אז הכולל שלהם הוא בסוד רצוא ושוב. אשר הימין שה\"ס ו\"ק בלי ראש דהיינו חסדים בלי חכמה כמ\"ש לעיל (דף ט' ד\"ה ומטרם עש\"ה) הוא בסוד \u0003רצוא\u0004 אל השמאל לקבל ממנו בחינת ראש וחכמה, כמו שנתבאר שם. ואחר שקבל ממנו החכמה, הוא בסוד \u0003ושוב,\u0004 דהיינו ששב למקומו לימין לבחינת חסדים, ולפיכך, נבחן ב \u0003ושוב\u0004 ב' בחינות, א) ההתכללות בשמאל ובחינת הג\"ר שמקבל שם. ב) ששב למקומו לימין וחוזר לחסדים. שאז הוא בכל השלמות. והנה בחינת \u0003רצוא\u0004 שבחיות, ה\"ס המלאך \u0003נוריאל,\u0004 שהוא עוד בבחינת ו\"ק בלי ראש, והוא רץ לשמאל לקבל ראש. ובחינת \u0003ושוב\u0004 של החיות, ה\"ס המלאך מטטרון. שיש בו ב' הבחינות של \u0003ושוב.\u0004 וע\"כ נקרא מלאך הפנים להיותו הנושא של בחינת הג\"ר, הנקראים פנים. וע\"כ הוא \u0003שר העולם,\u0004 להיות בו השלמות להשלים התחתונים שבג' עולמות בריאה יצירה עשיה."],[6,"","וזה אמרו, \u0003חמא מטטרון, סבא דביתא, דשליט בכל דיליה,\u0004 דהיינו ב' הבחינות שבו, מבחינה הא' הוא נקרא \u0003זקן ביתו,\u0004 שנכלל בשמאל וקנה משם חכמה. כי איזה זקן, מי שקנה חכמה. ומבחינה הב', שהוא ושוב למקומו לחסדים, שאז יש לו חכמה וחסדים, הוא נבחן אז, למושל \u0003בכל\u0004 אשר לו, כי \u0003כל\u0004 יורה על השלמות מכל הצדדים, הן חכמה והן חסדים. \u0003ורב\u0004 יורה על השלמות מחכמה לבד, כמ\"ש לעיל, בסו\"ה יש לי רב, ובהכתוב יש לי כל. וז\"ש \u0003דאיהו קאי בשלטנו על עלמא בשולטנו בשם שדי.\u0004 אשר כח השליטה שלו על העולם דהיינו להיות \u0003שר העולם,\u0004 הוא בשליטה של השם \u0003שד\"י,\u0004 כי כח השליטה ה\"ס בחינה הא' של \u0003ושוב,\u0004 כי אין שליטה אלא באור החכמה, ואז הוא כלול בשמאל, וה\"ס השם \u0003שד\"י. וסליק לעילא בסליקו דשמא דמריה הויה,\u0004 ועולה למעלה, דהיינו בחינה הב' של \u0003ושוב,\u0004 שהוא חזרתו לימין לחסדים, הוא בעליה אל השם הויה. שהוא ז\"א שהוא חסדים. \u0003אתר דיעקב אשתלים ביה,\u0004 שהוא המקום, אשר יעקב נעשה מרכבה אליו להשתלם בו. כי יעקב נעשה מרכבה לז\"א כנודע."],[6,"","וז\"ש, \u0003לבתר, וראשו דשם שדי איהו י' ודא מגיע השמימה,\u0004 כי ה \u0003י'\u0004 דשד\"י הוא סיום הנוקבא הנקראת עולם. וה\"ס גבול הים. וביאורו תמצא בתקונים (תקון מ\"ה דף פ\"ב) שמפרש שם הכתוב, והחיות רצוא ושוב, על האורות של בחינת הנוקבא עצמה, הנקראת ים, ואומר, בשעה שגלי הים, שה\"ס הארת החכמה שבשמאל, \u0003רצים\u0004 והם רוצים להחריב העולם להחזירו לתוהו ובוהו, דהיינו שרוצים להאיר ממעלה למטה, הם מסתכלים בשכינה, שהיא גבול הים, ואז הם \u0003שבים\u0004 למקומם, דהיינו לחסדים. ע\"ש. וגבול הים ה\"ס ה \u0003י'\u0004 של השם \u0003שדי,\u0004 כמ\"ש חז\"ל ש \u0003שדי,\u0004 פירושו שאמר לעולמו די שלא יתפשטו יותר, וגבול הזה ה\"ס \u0003י',\u0004 כי \u0003י'\u0004 ה\"ס ראש בלי גוף, שיורה על כח סיום שבו, שאינו מתפשט ממעלה למטה. הרי כשגלי הים שבשם שדי, מגיעים ל \u0003י',\u0004 נפסקים להאיר עוד, והם שבים לחסדים, וז\"ש \u0003וראשו דשם שדי איהו י',\u0004 כי כשמגיע ל \u0003י'\u0004 שה\"ס הגבול הוא חוזר לראש, דהיינו \u0003ושוב\u0004 למקומו, \u0003ודא מגיע השמימה,\u0004 כלומר הכח שב \u0003י'\u0004 זו, שהיא מגביל הארת חכמה שלא תתפשט עוד, כנ\"ל, נמצא מחזיר האורות השמימה, שה\"ס ז\"א וה\"ס חסדים. \u0003כיון דמטי וסליק את דא לההוא אתר, אשתלים, ואתקרי בההוא שמא דמאריה הוי\"ה.\u0004 כיון שאות הזו, דהיינו ה \u0003י',\u0004 מחזיר האורות השמימה, דהיינו ש \u0003שוב\u0004 לבחינת חסדים לז\"א, אז נשלם המלאך מטטרון, כנ\"ל בסוד המושל \u0003בכל\u0004 אשר לו, ונקרא בשם רבונו ז\"א הויה, כי נעשה מרכבה אליו כמו יעקב, כנ\"ל."],[7,"והנה מלאכי אלקים עולים ויורדים בו:","אלו מלאכים הקדושים הקרובים למלכות, עולים על ידי מטטרון. והאחרים שאינם קרובים למלכות, דהיינו שהם מס\"א, יורדים, ואין להם תקומה."],[8,"ותו, בו סלקי ונחתי וכו':","ועוד, בו, במלאך מטטרון, הם עולים ויורדים. כשהוא עולה עולים עמו מלאכי אלקים, כשהוא יורד יורדים עמו מלאכי אלקים. שהם שתים עשרה מרגליות טובות, והם מיכאל קדמיאל וכו'. והם אלפי \u0003שנא\"ן,\u0004 שהוא ראשי תבות שור, נשר, אריה, ו \u0003ן'\u0004 דשנאן, זה אדם, שכלול דכר ונוקבא. והם עולים כשמטטרון עולה, והם יורדים כשהוא יורד. וביאור הדברים נמצא לעיל בראשית א', דף פ\"ו ד\"ה שנאן. ודף קכ\"ד שם, ד\"ה דההוא אופן ע\"ש."],[9,"ותו, כל אינון וכו':","ועוד, כל אלו השולטים בשליטה בעולם הזה, על ידו, ע\"י מטטרון, עולים לשלוט. וכל אלו היורדים, על ידו יורדים משליטתם. כולם תלוים בסולם הזה, שהוא מטטרון. הוי\"ה שולט על כולם, שכתוב, והנה ה' נצב עליו."],[9,"כד אתער כתיב וכו':","כשהקיץ, מה כתוב, אין זה כי אם בית אלקים וזה שער השמים. מטטרון הוא בית אלקים ודאי, והוא שער להכנס לפנים, שכתוב פתחו לי שערי צדק אבא בם אודה יה. זה השער להויה, זה שער השמים. והכל אחד, כלומר שערי צדק, ושער הויה, ושער השמים הם אחד, שהוא מטטרון. פירוש ב' בחינות הן במטטרון א) ממה שנכלל בחכמה בבחינה הא' של ושוב, ב) ממה שנכלל גם בחסדים מבחינה הב' של ושוב, (כנ\"ל דף ל\"ו ד\"ה פירוש) ומבחינה הא' נקרא בית אלקים. ומבחינה הב' נק' שער. (ע\"כ סתרי תורה)."],[10,"וידר יעקב נדר וגו':","אמר רבי יהודה כיון שהקב\"ה הבטיח לו כל זה, שאמר לו, והנה אנכי עמך ושמרתיך וגו', למה לא האמין, אלא אמר, אם יהיה אלקים עמדי וגו'. ומשיב, אלא אמר יעקב, חלום חלמתי, והחלומות מהם שהם אמיתים ומהם שאינם אמיתים, ואם יתקיים, אז אדע שחלום אמיתי הוא. וע\"כ אמר, אם יהיה אלקים עמדי וגו', כמו שחלמתי, והיה ה' לי לאלקים, אני אהיה מושך ברכות ממבוע הנחל של הכל, שהוא בינה, למקום הזה שנקרא אלקים."],[11,"תא חזי ישראל וכו':","בוא וראה. ישראל שהוא באמצע הכל, דהיינו קו האמצעי, הוא מקבל השפע תחילה ממקור הכל, שהוא בינה, ולאחר שהשפע יגיע אליו ממנו, הוא מעביר וממשיך אותו אל מקום הזה, שהוא הנוקבא. זה משמע, משכתוב מתחילה, \u0003והיה ה' לי,\u0004 דהיינו שהוא יקבל תחילה, ואחר כך כתוב \u0003לאלקים,\u0004 שהוא הנוקבא. דהיינו שישפיע אח\"כ אל הנוקבא. כמו שאלקים ישמרני ויעשה לי כל הטובות האלו, כן אני אמשיך לו ממקומי, דהיינו מז\"א, כל אלו הברכות, ויתחבר בו קשר הכל, דהיינו היסוד. מתי יהיה זה, ושבתי בשלום בית אבי שפירושו, כשאהיה שלם במדרגה שלי, שהוא ת\"ת, ואהיה שלם במדרגת שלום, שהוא יסוד, לתקן \u0003בית\u0004 אבי, שהוא הנוקבא המכונה בית, ושבתי \u0003בשלום,\u0004 הוא בדיוק, להיותו רומז על היסוד, אז והיה ה' לי לאלקים."],[12,"ד\"א ושבתי בשלום וגו':","כי שם בבית אבי הוא ארץ הקדושה, שם אשתלם, והיה ה' לי לאלקים, במקום הזה אעלה ממדרגה זו למדרגה אחרת כראוי, ושם אעבוד עבודתו."],[13,"רבי חייא פתח וכו':","ר\"ח פתח ואמר, דברי עונות גברו מני פשעינו אתה הכפרם. מקרא זה קשה, כי אין סופו ראשו ואין ראשו סופו. שמתחיל בלשון יחיד ומסיים בלשון רבים. אלא דוד בקש תחלה על עצמו, ואחר כך בקש על הכל. \u0003דברי עונות גברו מני,\u0004 אמר דוד אני יודע בעצמי שחטאתי, אבל כמה רשעים הם בעולם שנתגברו עליהם חטאים עוד יותר ממני, הואיל וכך, אני מפחד ומבקש לי ולהם, פשעינו אתה תכפרם. והטעם שהיה מתירא מפני ריבוי החטאים של רשעי עולם."]],[[0,"","בֹּא רְאֵה, כָּתוּב (בראשית כה) וַתֹּאמֶר אִם כֵּן לָמָּה זֶה אָנֹכִי. כָּל יוֹם וָיוֹם רָאֲתָה רִבְקָה אֶת אוֹר הַשְּׁכִינָה, שֶׁהַשְּׁכִינָה הָיְתָה בְּמִשְׁכָּנָהּ, וְהִתְפַּלְלָה שָׁם. כֵּיוָן שֶׁרָאֲתָה צָרָתָהּ בְּמֵעֶיהָ, מַה כָּתוּב? וַתֵּלֶךְ לִדְרשׁ אֶת ה'. יָצְאָה מֵהַדַּרְגָּה הַזּוֹ לְדַרְגָּה אַחֶרֶת, שֶׁהִיא הוי\"ה. מִשּׁוּם כָּךְ אָמַר יַעֲקֹב, וְכִי כָּל כָּךְ רָאִיתִי וְאָנֹכִי לֹא יָדָעְתִּי? מִשּׁוּם שֶׁהָיָה לְבַדּוֹ וְלֹא נִכְנַס תַּחַת כַּנְפֵי הַשְּׁכִינָה."],[1,"","מִיָּד - וַיִּירָא וַיֹּאמַר מַה נּוֹרָא הַמָּקוֹם הַזֶּה. הַדָּבָר הַזֶּה הוּא לִשְׁנֵי הַצְּדָדִים. מַה נּוֹרָא הַמָּקוֹם הַזֶּה - אֶחָד עַל אוֹתוֹ הַמָּקוֹם שֶׁאָמַר בָּרִאשׁוֹנָה, וְאֶחָד עַל אוֹת הַבְּרִית הַקָּדוֹשׁ, שֶׁלֹּא צָרִיךְ לְהִבָּטֵל."],[2,"","וְאַף עַל גַּב שֶׁהֵם לִשְׁנֵי צְדָדִים - הוּא אֶחָד. אָמַר, אֵין זֶה כִּי אִם בֵּית אֱלֹהִים. אֵין זֶה לִהְיוֹת בָּטֵל, אֵין זֶה לְהִמָּצֵא לְבַדּוֹ, זֶה לֹא הָעֲמִידָה שֶׁלּוֹ, אֶלָּא בֵּית אֱלֹהִים, לְהִשְׁתַּמֵּשׁ בּוֹ וְלַעֲשׂוֹת בּוֹ פֵּרוֹת וּלְהָרִיק לוֹ בְּרָכוֹת מִכָּל אֵיבְרֵי הַגּוּף, שֶׁזֶּהוּ הַשַּׁעַר שֶׁל כָּל הַגּוּף. זֶהוּ שֶׁכָּתוּב וְזֶה שַׁעַר הַשָּׁמָיִם. זֶה הַשַּׁעַר שֶׁל הַגּוּף וַדַּאי, שַׁעַר הוּא לְהָרִיק בְּרָכוֹת לְמַטָּה, אָחוּז לְמַעְלָה וְאָחוּז לְמַטָּה. אָחוּז לְמַעְלָה - שֶׁכָּתוּב וְזֶה שַׁעַר הַשָּׁמָיִם. (אחוז) לְמַטָּה - שֶׁכָּתוּב אֵין זֶה כִּי אִם בֵּית אֱלֹהִים. וְעַל זֶה, וַיִּירָא וַיֹּאמַר מַה נּוֹרָא הַמָּקוֹם הַזֶּה. וּבְנֵי אָדָם אֵינָם מַשְׁגִּיחִים בַּכָּבוֹד שֶׁבּוֹ לִהְיוֹת בּוֹ שָׁלֵם לְמַעְלָה וּלְמַטָּה. בָּא אָבִיו וּנְשָׁקוֹ."],[3,"","אָמַר רַבִּי יִצְחָק, כְּשֶׁשָּׁמַעְתִּי אוֹתָם הַדְּבָרִים מִפִּיו, בָּכִיתִי וְאָמַרְתִּי, בָּרוּךְ הָרַחֲמָן שֶׁלֹּא בִטֵּל מִן הָעוֹלָם הַחָכְמָה הָעֶלְיוֹנָה. הָלַכְתִּי עִמָּם עַד שָׁלֹשׁ פַּרְסָאוֹת עַד שֶׁנִּכְנַסְתִּי עִמָּהֶם לָעִיר. לֹא הִסְפִּיקוּ לְהִכָּנֵס, עַד שֶׁשִּׁדֵּךְ אוֹתוֹ הָאִישׁ אֶת בְּנוֹ, וְאָמְרוּ לוֹ, דְּבָרֶיךְ לֹא יִהְיוּ לְבַטָּלָה."],[4,"","אָמַרְתִּי, זֶה שֶׁאָמַר רַבִּי שִׁמְעוֹן, שֶׁהַדְּבָרִים הַלָּלוּ הֵם כֻּלָּם בְּסוֹד הַחָכְמָה וּלְהַרְאוֹת דְּבָרִים אֲחֵרִים. כְּשֶׁסִּדַּרְתִּי הַדְּבָרִים לִפְנֵי רַבִּי שִׁמְעוֹן, אָמַר לִי, אַל תֹּאמַר שֶׁהַדְּבָרִים הַלָּלוּ הֵם שֶׁל תִּינוֹק, אֶלָּא הֵם דְּבָרִים שֶׁל סוֹדוֹת עֶלְיוֹנִים, וְהַכֹּל רְשׁוּמִים בְּסוֹד הַחָכְמָה."],[5,"","וַיַּחֲלֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה. הַחֲלוֹם, הַמַּדְרֵגָה הַשִּׁשִּׁית מֵאוֹתָן שְׁתֵּי דַרְגוֹת הַנְּבוּאָה עַד אוֹתָהּ הַדַּרְגָּה, הֵן שֵׁשׁ דְּרָגוֹת, וְעַל כֵּן הַחֲלוֹם אֶחָד מִשִּׁשִּׁים דְּרָגוֹת שֶׁל נְבוּאָה. סֻלָּם, רָאָה אֶת בָּנָיו שֶׁעֲתִידִים לְקַבֵּל תּוֹרָה בְּהַר סִינַי. סֻלָּם זֶה סִינַי (בגימטריא), מִשּׁוּם שֶׁהוּא נָעוּץ בָּאָרֶץ וְחוֹשֵׁב בַּעֲלִיָּה לַשָּׁמַיִם, וְכָל הַמֶּרְכָּבוֹת (הקדושות) וְהַמַּחֲנוֹת הָעֶלְיוֹנִים, כֻּלָּם יוֹרְדִים (ירדו) לְשָׁם עִם הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁנָּתַן לָהֶם אֶת הַתּוֹרָה."],[6,"","וְהַסֹל רָאָה. רָאָה אֶת מטטרו\"ן זְקַן הַבַּיִת שֶׁשּׁוֹלֵט בְּכָל אֲשֶׁר לוֹ, שֶׁהוּא עוֹמֵד בְּשִׁלְטוֹן עַל הָעוֹלָם (הזה), בְּשִׁלְטוֹן שֶׁל שֵׁם שַׁדַּ\"י. וְעוֹלֶה לְמַעְלָה בַּעֲלִיַּת שֵׁם רִבּוֹנוֹ הוי\"ה, הַמָּקוֹם שֶׁיַּעֲקֹב הֻשְׁלַם בּוֹ לְאַחַר מִכֵּן. וְרֹאשׁוֹ שֶׁל שֵׁם שַׁדַּ\"י הוּא י', וְזֶה מַגִּיעַ הַשָּׁמָיְמָה. כֵּיוָן שֶׁהִגִּיעָה וְעָלְתָה הָאוֹת הַזּוֹ לַמָּקוֹם הַהוּא, הֻשְׁלַם וְנִקְרָא בְּאוֹתוֹ שֵׁם שֶׁל רִבּוֹנוֹ הוי\"ה."],[7,"","וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ. אוֹתָם הַמַּלְאָכִים הַקְּדוֹשִׁים שֶׁקְּרוֹבִים לַמַּלְכוּת עוֹלִים, וְאוֹתָם הָאֲחֵרִים שֶׁאֵינָם קְרוֹבִים יוֹרְדִים."],[8,"","וְעוֹד, בּוֹ הֵם עוֹלִים וְיוֹרְדִים. כְּשֶׁהוּא עוֹלֶה, עוֹלִים עִמּוֹ. כְּשֶׁהוּא יוֹרֵד, יוֹרְדִים עִמּוֹ. מַלְאֲכֵי אֱלֹהִים - שְׁתֵּים עֶשְׂרֵה מַרְגָּלִיּוֹת טוֹבוֹת, וְהֵן: מיכא\"ל, קדמיא\"ל, פדא\"ל, גבריא\"ל, צדקיא\"ל, חסדיא\"ל, רפא\"ל, רזיא\"ל, סטורי\"ה, נוריא\"ל, יפיא\"ל, ענא\"ל. אַלְפֵי שִׁנְאָן, שִׁנְאָ\"ן - שׁוֹ\"ר נֶשֶׁ\"ר אַרְיֵ\"ה. ן' אָדָם, כּוֹלֵל זָכָר וּנְקֵבָה. וְהֵם עוֹלִים כְּשֶׁהוּא עוֹלֶה, וְאֵלּוּ יוֹרְדִים כְּשֶׁהוּא יוֹרֵד."],[9,"","וְעוֹד, כָּל אוֹתָם שֶׁשּׁוֹלְטִים בְּשִׁלְטוֹן הָעוֹלָם הַזֶּה עוֹלִים עַל יָדוֹ, וְכָל אוֹתָם שֶׁיּוֹרְדִים יוֹרְדִים עַל יָדוֹ, כֻּלָּם בַּסֻּלָּם הַזֶּה. הוי\"ה שׁוֹלֵט עַל הַכֹּל, שֶׁכָּתוּב וְהִנֵּה ה' נִצָּב עָלָיו. כְּשֶׁהִתְעוֹרֵר, כָּתוּב אֵין זֶה כִּי אִם בֵּית אֱלֹהִים וְזֶה שַׁעַר הַשָּׁמָיִם. בֵּית אֱלֹהִים וַדַּאי, וְהוּא הַשַּׁעַר לְהִכָּנֵס פְּנִימָה, שֶׁכָּתוּב (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבוֹא בָם אוֹדֶה יָהּ זֶה הַשַּׁעַר לַה'. זֶה שַׁעַר הַשָּׁמַיִם הַכֹּל אֶחָד."],[10,"","וַיִּדַּר יַעֲקֹב נֶדֶר לֵאמֹר אִם יִהְיֶה אֱלֹהִים עִמָּדִי וְגוֹ'. אָמַר רַבִּי יְהוּדָה, כֵּיוָן שֶׁכָּל זֶה הִבְטִיחַ לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, לָמָּה לֹא הֶאֱמִין, שֶׁאָמַר אִם יִהְיֶה אֱלֹהִים עִמָּדִי וְגוֹ'? אֶלָּא, אָמַר יַעֲקֹב, חֲלוֹם חָלַמְתִּי, וְהַחֲלוֹמוֹת - מֵהֶם אֱמֶת וּמֵהֶם לֹא אֱמֶת, וְאִם יִתְקַיֵּם, הֲרֵי יָדַעְתִּי שֶׁהוּא חֲלוֹם אֱמֶת. וְעַל כֵּן אָמַר אִם יִהְיֶה אֱלֹהִים עִמָּדִי וְגוֹ', כְּמוֹ שֶׁחָלַמְתִּי, וְהָיָה ה' לִי לֵאלֹהִים. אֲנִי אֶהְיֶה מוֹשֵׁךְ בְּרָכוֹת מֵהַמַּעְיָן שֶׁל הַנַּחַל שֶׁל הַכֹּל לַמָּקוֹם הַזֶּה שֶׁנִּקְרָא אֱלֹהִים."],[11,"","בֹּא רְאֵה, יִשְׂרָאֵל שֶׁהוּא בָּאֶמְצַע, הַכֹּל הוּא נוֹטֵל בָּרִאשׁוֹנָה מֵהַמָּקוֹר שֶׁל הַכֹּל, וְאַחַר שֶׁיַּגִּיעַ אֵלָיו, מִמֶּנּוּ שׁוֹפֵעַ וּמַמְשִׁיךְ לַמָּקוֹם הַזֶּה, מַשְׁמָע שֶׁכָּתוּב וְהָיָה ה' לִי - בָּרִאשׁוֹנָה, וְאַחַר הַכֹּל - לֵאלֹהִים. כְּמוֹ שֶׁאֱלֹהִים יִהְיֶה שׁוֹמֵר וְעוֹשֶׂה לִי כָּל אוֹתָן הַטּוֹבוֹת, אַף אֲנִי אֶהְיֶה מוֹשֵׁךְ לוֹ מֵהַמָּקוֹם שֶׁלִּי כָּל אוֹתָן הַבְּרָכוֹת, וְיִתְחַבֵּר בּוֹ הַקֶּשֶׁר שֶׁל הַכֹּל. מָתַי? וְשַׁבְתִּי בְשָׁלוֹם אֶל בֵּית אָבִי, כְּשֶׁאֶהְיֶה יוֹשֵׁב בַּדַּרְגָּה שֶׁלִּי, וְאֶהְיֶה יוֹשֵׁב בַּדַּרְגָּה שֶׁל שָׁלוֹם לְתַקֵּן אֶת בֵּית אָבִי, וְשַׁבְתִּי בְשָׁלוֹם דַּוְקָא, אָז וְהָיָה ה' לִי לֵאלֹהִים."],[12,"","דָּבָר אַחֵר וְשַׁבְתִּי בְשָׁלוֹם אֶל בֵּית אָבִי, שֶׁשָּׁם הִיא הָאָרֶץ הַקְּדוֹשָׁה, שָׁם אֶשְׁתַּלֵּם. וְהָיָה ה' לִי לֵאלֹהִים. בַּמָּקוֹם הַזֶּה אֶעֱלֶה (נתעלה) מִדַּרְגָּה זוֹ לְדַרְגָּה אַחֶרֶת כָּרָאוּי, וְשָׁם אֶעֱבֹד עֲבוֹדָתוֹ."],[13,"","רַבִּי חִיָּיא פָּתַח וְאָמַר, דִּבְרֵי עֲונוֹת גָּבְרוּ מֶנִּי פְּשָׁעֵינוּ אַתָּה תְכַפְּרֵם. הַפָּסוּק הַזֶּה קָשֶׁה, שֶׁאֵין סוֹפוֹ רֹאשׁוֹ וְאֵין רֹאשׁוֹ סוֹפוֹ. אֶלָּא דָּוִד בִּקֵּשׁ עַל עַצְמוֹ, וְאַחַר כָּךְ בִּקֵּשׁ עַל הַכֹּל (תהלים סה) דִּבְרֵי עֲונוֹת גָּבְרוּ מֶנִּי. אָמַר דָּוִד, אֲנִי יָדַעְתִּי בְּעַצְמִי שֶׁחָטָאתִי, אֲבָל כַּמָּה רְשָׁעִים הֵם בָּעוֹלָם שֶׁהִתְגַּבְּרוּ חֲטָאֵיהֶם עֲלֵיהֶם יוֹתֵר מִמֶּנִּי. הוֹאִיל וְכֵן, לִי וְלָהֶם, פְּשָׁעֵינוּ אַתָּה תְכַפְּרֵם."]]],[["תָּא חֲזֵי, בְּשַׁעְתָּא דְּחַיָּיבִין סַגִּיאִין בְּעַלְמָא, אִינוּן סָלְקִין, עַד הַהוּא אֲתַר דְּסִפְרֵי דְּחַיָּיבַיָא אִתְפַּתְּחוּ, כְּמָה דְאַתְּ אָמֵר, (דניאל ז׳:י׳) דִּינָא יָתִיב וְסִפְרִין פְּתִיחוּ, וְהַהוּא סֵפֶר (דינא עלה קיימא), (נ\"א לעילא מרישיה דדוד איהו) בְּגִינֵי כָּךְ, דִּבְרֵי עֲוֹנוֹת גָּבְרוּ מֶנִּי, וְעַל דָּא פְּשָׁעֵינוּ אַתָּה תְכַפְּרֵם.","יַעֲקֹב, כְּגַוְונָא דָא בְּגִין כָּךְ לָא הֵימִין, אִי תֵימָא דְּלָא הֵימִין בְּקוּדְשָׁא בְּרִיךְ הוּא, לָא. אֶלָּא, דְּלָא הֵימִין בֵּיהּ בְּגַרְמֵיהּ, דִּילְמָא יֵחוּב, וְהַהוּא חוֹבָא, יִמְנַע לֵיהּ, דְּלָא יְתוּב בִּשְׁלָם וְיִסְתַּלַּק נְטִירוּ מִנֵּיהּ, וּבְגִין כָּךְ, לָא הֵימִין בְּגַרְמֵיהּ. וְהָיָה יְיָ לִי לֵאלהִים, אֲפִילּוּ רַחֲמֵי, כַּד אִיתוּב בִּשְׁלָם, אֲשַׁוֵּי לְקֳבְלִי לְדִינָא, בְּגִין (ס\"א דהא) דְּאֲנָא פָּלַח קַמֵּיהּ תָּדִיר.","אָמַר רִבִּי אַחָא, אָמַר יַעֲקֹב, הַשְׁתָּא לָא אִצְטְרִיכְנָא לְדִינָא, כַּד אִיתוּב לְבֵית אַבָּא, אִתְכְּלִילְנָא בְּדִינָא וְאֶתְקַשַּׁר בֵּיהּ. אָמַר רִבִּי יוֹסֵי, לָאו הָכִי, אֶלָּא אָמַר, הַשְׁתָּא אִם יִהְיֶה אֱלֹהִים עִמָּדִי, דִּינָא אִצְטְרִיכְנָא לְנַטְרָא לִי, עַד דְּאִיתוּב בִּשְׁלָם לְבֵית אַבָּא, אֲבָל כֵּיוָן דְּאִיתוּב בִּשְׁלָם, אִתְכְּלִילְנָא רַחֲמֵי בְּדִינָא, וְאֶתְקַשַּׁר בְּקִשּׁוּרָא מְהֵימְנָא, לְאַכְלָלָא כֹּלָּא כְּחַד. (בראשית כ״ח:כ״ב) וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלהִים. דְּהָא כְּדֵין יְהֵא כֹּלָּא קִשּׁוּרָא חָדָא, וְהַאי אֶבֶן אִתְבָּרְכָא מִימִינָא וּמִשְׂמָאלָא, אִתְבָּרְכָא מֵעֵילָא וּמִתַּתָּא, בְּגִין (דא) דְּאֶתֵּן מַעַשְׂרָא מִכֹּלָּא.","אָמַר רִבִּי אַבָּא, הָא כְּתִיב, (בראשית כ״ח:י״א) וַיִּקַּח מֵאַבְנִי הַמָּקוֹם. וְאִי תֵימָא דְאַבְנָא דָא, עִלָּאָה (על) כַּמָּה (קמ\"ז ע\"ב) אַבְנִין לְאֲתַר מוֹתָבֵיהּ, לְמִשְׁרֵי עֲלַיְיהוּ, (נ\"א האי דכתיב) וְהָא כְּתִיב וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה, (נ\"א עליונה מבעי ליה). בְּגִין (נ\"א כיון) דְּאָמַר (בראשית כ״ח:כ״ב) אֵין זֶה כִּי אִם בֵּית אֱלהִים, הָכָא אָרִים לָהּ קַמָּא עִלָּאָה, בְּגִין דְּתָלָא כָּל שְׁבָחָא דְּזֶה בָּהּ, דְּאֵין זֶה לְקַיָּימָא (לתתא) כִּי אִם בֵּית אֱלֹהִים. וְשַׁפִּיר. וְעַל דָּא אֲשֶׁר שַׂמְתִּי מַצֵּבָה כְּתִיב.","יִהְיֶה בֵּית אֱלֹהִים לְעָלְמִין, בֵּית אֱלֹהִים, בֵּית יְיָ מִיבָּעֵי לֵיהּ, כְּמָה דְאַתְּ אָמֵר, (עזרא א) לְכוֹנֵן אֶת בֵּית יְיָ. וְכֵן (תהילים קכ״ב:א׳) בֵּית יְיָ נֵלֵךְ. אֶלָּא, אֲתַר דְּבֵי דִינָא אִיהוּ מִתְּרֵין סִטְרִין עִלָּאִין, מִסִּטְרָא דְיוֹבְלָא, דְּאִיהוּ אֱלֹהִים חַיִּים. וּמִסִּטְרָא דְיִצְחָק אֱלהִים.","אָמַר רִבִּי אֶלְעָזָר, יוֹבְלָא, אַף עַל גַּב דְּדִינִין (נפקין) מִתְעָרִין מִינָהּ, וְכֻלְּהוּ רַחֲמֵי (ודינין), כָּל חֵידוּ מִינָהּ נָפְקִין, וְהוּא חֶדְוָותָא (ס\"א והוא חירותא) דְכֹלָּא. אֶלָּא בֵּית אֱלהִים, סִטְרָא דְדִינָא קַשְׁיָא, אִי לְטַב, בְּסִטְרָא (דיובלא) דִשְׂמָאלָא, אִתְעַר בֵּיהּ רְחִימוּתָא, כְּמָה דְאַתְּ אָמֵר, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. אִי לְבִישׁ, בְּסִטְרָא דִשְׂמָאלָא, אִתְעַר בֵּיהּ דִּינָא קַשְׁיָא, כְּמָה דְאַתְ אָמֵר, (ירמיהו א׳:י״ד) מִצָּפוֹן תִּפָּתַח הָרָעָה עַל כָּל יוֹשְׁבֵי הָאָרֶץ, וַדַּאי בֵּית אֱלהִים. רִבִּי שִׁמְעוֹן אָמַר, בֵּית אֱלהִים הַיְינוּ דִכְתִיב, (תהילים מ״ח:ג׳) קִרְיַת מֶלֶךְ רָב. אִית מֶלֶךְ סְתָם, וְאִית מֶלֶךְ רָב, וַדַּאי עַלְמָא עִלָּאָה, מֶלֶךְ רָב אִיהוּ, וְדָא הוּא (שם) קִרְיַת מֶלֶךְ רָב.","רִבִּי חִיָּיא וְרִבִּי חִזְקִיָּה, הֲווּ יַתְבֵי תְּחוֹת אִילָנֵי דַּחֲקַל אוֹנוֹ, אִדְמוּךְ רִבִּי חִיָּיא, חָמָא לֵיהּ לְאֵלִיָּהוּ, אָמַר מַקְסְטִיטוּרָא דְמַר, חַקְלָא נָהִיר. אָמַר, הַשְׁתָּא אָתֵינָא לְאוֹדָעָא, דִּיְרוּשָׁלַ ם קָרִיב אִיהוּ לְאִתְחָרְבָא, וְכָל אִינוּן קַרְתִּין דַּחֲכִימַיָא. בְּגִין דִּיְרוּשָׁלַ ם דִּינָא אִיהוּ, וְעַל דִּינָא קָיְימָא, וְעַל דִּינָא אִתְחָרַב, וְהָא אִתְיְהִיב רְשׁוּ לְסמא\"ל עֲלָהּ, וְעַל תַּקִּיפֵי עַלְמָא, וְאָתֵינָא לְאוֹדָעָא לַחֲכִימַיָא דִּילְמָא יוֹרְכוּן שְׁנִי דִּיְרוּשָׁלַ ם, דְּהָא כָּל זִמְנָא דְּאוֹרַיְיתָא אִשְׁתַּכַּח בָּהּ, הִיא קָיְימָא. בְּגִין דְּאוֹרַיְיתָא אִילָנָא דְחַיֵּי דְּקָיְימֵי עֲלָהּ, (תרי נוסחי אינון) כָּל זִמְנָא דְּאוֹרַיְיתָא אִתְעַר לְתַתָּא אִילָנָא דְחַיֵּי לָא אַעֲדֵי לְעֵילָא, פָּסַק אוֹרַיְיתָא לְתַתָּא אִילָנָא דְחַיֵּי אִסְתַּלַּק (מינה) מֵעָלְמָא.","וְעַל דָּא, כָּל זִמְנָא דְּחֲכִימַיָא יֶחדוּן בָּהּ בְּאוֹרַיְיתָא, לָא יָכִיל סמא\"ל בְּהוּ, דְּהָא כְּתִיב, (בראשית כ״ז:כ״ב) הַקּוֹל קוֹל יַעֲקֹב וְהַיָּדַיִם יְדֵי עֵשָׂו, דָּא הוּא אוֹרַיְיתָא עִלָּאָה, דְּאִקְרֵי קוֹל יַעֲקֹב, בְּעוֹד דְּהַהוּא קוֹל לָא פָּסַק, דִּבּוּר שָׁלְטָא וְיָכְלָא, וְעַל דָּא לָא אִצְטְרִיךְ אוֹרַיְיתָא לְמִפְסַק. (ל\"ג ע\"א) וְאִתְעַר רִבִּי חִיָּיא, וְאֲזְלוּ וְאָמְרוּ מִלָּה דָא לַחֲכִימַיָא."],[[0,"תא חזי, בשעתא דחייבין וכו':","בוא וראה, בשעה שיש הרבה רשעים בעולם, הם עולים עד אותו המקום שספרי רשעים נפתחים. שהוא הנוקבא דז\"א הנקראת ספר, כמו שאתה אומר, דינא יתיב וספרין פתיחו. ואז, וההוא ספר שהוא הנוקבא הדין עומד עליו. כלומר, שנפגמת בסבת הדינים, וע\"כ היה דוד מפחד שעונותינו לא יפגמו את הנוקבא. ובקש עליהם כפרה. ואמר לי ולהם אתה תכפרם. כנ\"ל."],[1,"יעקב כגוונא דא וכו':","יעקב כעין זה, היה ג\"כ מפחד, אולי יחטא, ובסבת ריבוי הרשעים בעולם, יגיע הפגם עד הנוקבא, ומשום זה לא האמין בהבטחת ה' שניתנה לו (כנ\"ל באות ע\"ה) ואל תאמרו שלא האמין בה', לא, אלא שלא האמין בעצמו, ופחד, אולי יחטא, ובצירוף החטאים שבעולם, יגרום החטא שלא ישוב לביתו בשלום, והשמירה תסור ממנו. וע\"כ לא האמין בעצמו."],[1,"והיה ה' לי לאלקים:","כאשר אשוב בשלום, אפילו רחמים אשית לפני לדין, כדי שאהיה עובד לפניו תמיד. פירוש. הוי\"ה הוא רחמים, דהיינו ז\"א שהוא באור החסדים, ונוטה לימין. והשם אלקים הוא דין, דהיינו הנוקבא, שהוא באור החכמה, ונוטה לשמאל. ונתבאר לעיל בדף י\"ז ד\"ה יעקב שמתחילה, לא היה אלא \u0003במדרגת יעקב,\u0004 שפירושו שהיה נוטה לימין יותר משמאל. ואחר כך כשחזר לארץ, השיג \u0003מדרגת ישראל,\u0004 שהימין נכלל משמאל, והשיג ראש. ע\"ש. וז\"ש כאן \u0003אפילו רחמי,\u0004 שהוא הויה, ונוטה לימין, \u0003כד איתוב בשלם אשוי לקבלי לדינא\u0004 דהיינו שהימין שהוא \u0003הויה,\u0004 יכלל אז בשמאל שהוא \u0003אלקים,\u0004 ואשיג ראש, ואז אכניע כל הקליפות ואוכל לעבדו תמיד בלי הפסק. וע\"כ אמר והיה \u0003הוי\"ה\u0004 לי \u0003לאלקים.\u0004"],[2,"אמר רבי אחא, אמר יעקב וכו':","ר\"א בא לבאר הדברים, ואומר שיעקב אמר, עתה איני צריך לדין. אלא רק לחסד, כמו מדרגת יעקב כנ\"ל, כשאשוב לבית אבי, אתכלל אז בדין, דהיינו שהימין יכלול בשמאל, כנ\"ל, ואתקשר בשמאל כמו בימין, דהיינו מדרגת ישראל, עמודא דאמצעיתא. כמ\"ש שם."],[2,"אמר ר' יוסי וכו':","אר\"י אינו כן. אלא שאמר, עתה, \u0003אם יהיה אלקים עמדי,\u0004 והשם אלקים הוא דין, כי עתה דין אני צריך, לשמור אותי עד שאשוב בשלום לבית אבי, כי להכניע הקליפות צריכים להארת השמאל, שהוא דין, אלא אחר שאשוב בשלום, אתכלל מרחמים בדין, דהיינו שימין יהיה כלול משמאל והשמאל מימין, ואתקשר בקשר הנאמן, להכליל כל הספירות כאחד. \u0003והאבן הזאת אשר שמתי מצבה יהיה בית אלקים,\u0004 כי אז אחר שהימין והשמאל יכללו זה בזה, יהיה הכל קשר אחד, ואבן הזה, דהיינו הנוקבא, תתברך מימין ומשמאל שהם חו\"ב, וממעלה וממטה, שהם תו\"מ, ומשום זה אתן \u0003מעשר מכל.\u0004 כלומר, המעשר, שהיא הנוקבא, שהיא אחת מעשר, תהיה כלולה מכל עשר הספירות: מדרום וצפון וממעלה וממטה, שהם חו\"ב תו\"מ."],[3,"אמר ר' אבא וכו':","אר\"א, והרי כתוב, ויקח מאבני המקום. שהם י\"ב אבנים שמתחת הנוקבא, ולא הנוקבא עצמה. ואם תאמר, שאבן הזאת שלקח, היא העליונה על כל האבנים שלקח למקום מושבו לשרות עליהן, שהוא הנוקבא שממעל לי\"ב האבנים, זה אינו, שהרי כתוב, והאבן הזאת אשר שמתי מצבה, עליונה היה צריך לומר, לדבריך. ומשיב, אלא משום שאמר, \u0003אין ז\"ה כי אם בית אלקים,\u0004 כאן, הרים אותה מצבה עליונה, משום שתלה כל השבח של \u0003זה\u0004 שהוא היסוד, בה באבן העליונה שאמר אין \u0003זה\u0004 עשוי לקיים, דהיינו להשפיע מוחין, \u0003כי אם, בית אלקים,\u0004 דהיינו לאבן הזאת העליונה, שהוא בית אלקים, שהיא הנוקבא, ויפה הוא. ועל כן, אשר שמתי מצבה כתוב, ולא כתוב עליונה."],[4,"יהיה בית אלקים:","היינו לעולם. כלומר, שלא יפסק השפע אליה מן היסוד לעולם. ושואל, הכתוב אומר בית אלקים, בית הויה, היה צריך לומר, כמו שאתה אומר, לבנות את בית ה', (כצ\"ל). וכן בית ה' נלך. ומשיב, אלא הנוקבא היא מקום לבית דין דהיינו לדינים, משני צדדים העליונים, מצד יובל, שהוא ישסו\"ת, הנקרא אלקים חיים, כי ז\"ת דבינה שהוא ישסו\"ת נקראים ג\"כ \u0003אלקים,\u0004 ועל שם חכמה שמשפעת נקראת \u0003חיים.\u0004 ומצד יצחק. שה\"ס גבורה דז\"א, נקראת ג\"כ \u0003אלקים.\u0004 וע\"כ אומר הכתוב על הנוקבא, בית אלקים, שהוא דין ולא בית ה'. שהוא רחמים."],[5,"אמר ר' אלעזר וכו':","אר\"א, \u0003יובל,\u0004 דהיינו ישסו\"ת, שהיא בינה, אע\"פ שדינים מתעוררים ממנה, כולה רחמים היא, כל חדוה ממנה יוצאת, והיא חדות כל. ולפיכך אין לומר כרבי אבא, אשר הנוקבא נקראת \u0003בית אלקים,\u0004 משום שמקבלת דינים מיובל. אלא \u0003בית אלקים,\u0004 שנקראת, יורה, שהיא צד הדין הקשה, דהיינו גבורה דז\"א, שהוא שמאל שלו, אם לטוב הרי מצד השמאל נתעורר האהבה לזווג, כמו שאתה אומר, שמאלו תחת לראשי. אם לרע, הרי מצד שמאל מתעורר דין הקשה. כמש\"א, מצפון תפתח הרעה וגו' ע\"כ נקראת ודאי בית אלקים."],[5,"ר' שמעון אמר וכו':","רש\"א, בית אלקים, היינו שכתוב קרית מלך רב, שהנוקבא הוא קריה לבינה, הנקראת מלך רב, אף כאן, הנוקבא היא בית לאלקים, שהוא בינה. כי יש מלך סתם, שהוא הנוקבא, ויש מלך רב. ודאי, עולם העליון, שהוא בינה נקרא מלך רב. וזה, המלך סתם, הוא קרית מלך רב, שהוא בינה."],[6,"רבי חייא ור' חזקיה וכו':","ר\"ח ור\"ח היו יושבים תחת האילנות של שדה אונו, נמנם רבי חייא, וראה את אליהו, אמר רבי חייא לאליהו מהוכחת הדרך של אדוני, השדה מאיר, שהוא הנוקבא. קסטיטורא, פירושו הוכחת הדרך אשר ילכו בה, כי המלה מורכבת מן \u0003כם\u0004 שפירושו הוכחה כי על הוכח מכם, מתרגמינן יכסן מנכון (איוב ו'). ומן המלה טרטר או מטטר, שפירושן הוראת הדרך כמ\"ש בתנחומא (כי תשא, ראש סימן ל\"ה) בהכתוב וה' הולך לפניהם יומם, אני הולך לפניהם, \u0003מטטר.\u0004 וכן (במדרש שו\"ט צ\"ג) קולו של הקב\"ה היה \u0003מטרטר\u0004 לפניהם שנאמר קול ה' על המים. שפירושן הוראת הדרך. וכונת ר' חייא היה למה שהוכיח את ישראל ואמר, (מלכים א' י\"ח) והיה האלקים אשר יענה באש הוא אלקים. ואח\"כ כתוב, ויאמרו ה' הוא האלקים ה' הוא האלקים. וקבלו הוראתו."],[6,"אמר השתא אתינא וכו':","אמר אליהו, עתה באתי אליך להודיע, שירושלים קרוב היא להחרב, וכל ערי החכמים עמה, משום שירושלים דהיינו הנוקבא, היא דין, ועומדת על דין, ונחרבת על הדין שבה. וכבר ניתן רשות לסמאל עליה ועל גבורי העולם, ובאתי להודיע לחכמים, אולי יאריכו השנים של ירושלים, שלא תחרב, שהרי כל זמן שהתורה נמצאת בה, היא עומדת, משום שהתורה היא עץ החיים העומד עליה, כל זמן שהתורה מתעוררת מלמטה, שבני אדם עוסקים בה, עץ החיים אינו מסתלק מירושלים שלמעלה, פסקה התורה למטה, שבני אדם הפסיקו מלעסוק בה, עץ החיים, שהוא ז\"א, מסתלק מן העולם, שהוא הנוקבא. שהיא נקראת עולם וכן נקראת ירושלים, כנודע. ואין לומר, שהכונה היא לירושלים של מטה, כי אלו החכמים כבר היו שנים רבות אחר חורבן ירושלם."],[7,"ועל דא כל זמנא וכו':","ועל כן כל זמן שהחכמים שמחים בעסק התורה, לא יוכל להם סמאל, כי כתוב הקול קול יעקב והידים ידי עשו. זהו התורה העליונה, דהיינו ז\"א, הנקרא קול יעקב, בעוד שהקול ההוא אינו נפסק הדבור שולט ומנצח, וע\"כ אין צריכים להפסיק מתורה. והקיץ רבי חייא. והלכו ואמרו דבר זה ששמעו מאליהו, אל החכמים."],[7,"","פנימיות הדברים. \u0003רבי חייא\u0004 הוא בחינת יסוד, מלשון \u0003חי\u0004 העולמים. \u0003ור' חזקיה\u0004 הוא בחינת הגבורה מלשון \u0003חזק י\"ה.\u0004 דהיינו קו שמאל. \u0003אלנות\u0004 הם מדרגות, \u0003שדה\u0004 הוא הנוקבא. \u0003אונו\u0004 ה\"ס גבורה מלשון הכתוב (איוב מ') ואונו בשרירי בטנו, וכן, ובאונו שרה את אלקים. (הושע י\"ב) וזה אמרו, \u0003רבי חייא ורבי חזקיה,\u0004 דהיינו שרבי חייא שהוא יסוד, נתדבק ברבי חזקיה, שה\"ס קו שמאל. \u0003הוו יתבי תחות אילני דחקל אונו,\u0004 שהיו יושבים תחת האלנות, שהם המדרגות, של שדה אונו, דהיינו הנוקבא הנקראת כן, בעת שדבוקה בקו שמאל, כלומר שהמשיכו אז את קו השמאל בלי ימין, אל הנוקבא, שה\"ס און וגבורה. וע\"כ נקראת אז \u0003שדה אונו.\u0004 ונודע, ששמאל בלי ימין, ה\"ס דינים המביאים להסתלקות המוחין ושינה, וז\"ש \u0003אדמוך רבי חייא,\u0004 שנסתלקו מוחותיו. \u0003חמא ליה לאליהו,\u0004 הוא בגימ' ב\"ן שהוא שם הנוקבא, בעת שמאירה בג' קוין שה\"ס יה\"ו, וז\"ס \u0003אל\u0004 שהוא שם הנוקבא \u0003יה\"ו\u0004 שג' הקוין יה\"ו מאירים בה. והוא הנושא למסך דחירק שעליו יוצא קומת קו אמצעי. וכיון שנגלה לו בחלומו, הכירו בו, שבהוראתו וכחו יזכה שוב אל המוחין שלו, וע\"כ אמר לו, \u0003מקסטיטורא דמר חקלא נהיר,\u0004 שמהוראתו יזכה להאיר שוב את \u0003חקלא אונו\u0004 הנ\"ל. ויטה אותה לרחמים. ותכף אמר לו, \u0003השתא אתינא לאודעא דירושלים קריב איהו לאתחרבא וכו'.\u0004 דהיינו אם לא יתדבק בקו אמצעי, \u0003כל זמנא דאורייתא\u0004 שהוא קו אמצעי, הנקרא תורה, \u0003אתער לתתא,\u0004 דהיינו שמעלים מ\"ן על מסך דחירק, \u0003אילנא דחיי\u0004 שה\"ס קומת קו אמצעי היוצא על מסך הזה, \u0003לא אעדי לעילא,\u0004 ויש לה כל השלמות, \u0003פסק אורייתא לתתא,\u0004 שאין מעלים מ\"ן לקו אמצעי, \u0003אילנא דחיי אסתלק,\u0004 והמיתה והחורבן שולט בעולם. וכו'. וכיון שקיבל דבריו, אז \u0003ואתער רבי חייא,\u0004 דהיינו שהשיג תכף את המוחין, השלמים, שה\"ס הקיצה."]],[[0,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁרַבִּים הָרְשָׁעִים בָּעוֹלָם, הֵם עוֹלִים עַד אוֹתוֹ מָקוֹם שֶׁסִּפְרֵי הָרְשָׁעִים נִפְתְּחוּ, כְּמוֹ שֶׁנֶּאֱמַר הַ (בית) דִּין יוֹשֵׁב וּסְפָרִים נִפְתָּחִים, וְאוֹתוֹ סֵפֶר (הדין עומד עליה), (למעלה מראשו של דוד הוא) משום כך דברי עונות גברו מני, ועל כן פשעינו אתה תכפרם."],[1,"","יַעָקֹב כְּמוֹ כֵן מִשּׁוּם כָּךְ לֹא הֶאֱמִין. אִם תֹּאמַר שֶׁלֹּא הֶאֱמִין בַּקָּדוֹשׁ-בָּרוּךְ-הוּא - לֹא. אֶלָּא שֶׁלֹּא הֶאֱמִין בְּעַצְמוֹ. אוּלַי יֶחֱטָא, וְאוֹתוֹ הַחֵטְא יִמְנַע אוֹתוֹ שֶׁלֹּא יָשׁוּב בְּשָׁלוֹם וְתִסְתַּלֵּק מִמֶּנּוּ הַשְּׁמִירָה, וּמִשּׁוּם כָּךְ לֹא הֶאֱמִין בְּעַצְמוֹ. וְהָיָה ה' לִי לֵאלֹהִים אֲפִלּוּ רַחֲמִים, כְּשֶׁאָשׁוּב בְּשָׁלוֹם, אָשִׂים כְּנֶגְדִּי אֶת הַדִּין, מִשּׁוּם (שהרי) שֶׁאֲנִי עוֹבֵד לְפָנָיו תָּמִיד."],[2,"","אָמַר רַבִּי אָחָא, אָמַר יַעֲקֹב, כָּעֵת אֵינִי צָרִיךְ אֶת הַדִּין. כְּשֶׁאָשׁוּב לְבֵית אָבִי אֶתְכַּלֵּל בַּדִּין וְאֶתְקַשֵּׁר בּוֹ. אָמַר רַבִּי יוֹסֵי, לֹא כָּךְ, אֶלָּא אָמַר, עַכְשָׁו אִם יִהְיֶה אֱלֹהִים עִמָּדִי, אֲנִי צָרִיךְ שֶׁהַדִּין יִשְׁמֹר אוֹתִי עַד שֶׁאָשׁוּב בְּשָׁלוֹם אֶל בֵּית אָבִי. אֲבָל כֵּיוָן שֶׁאָשׁוּב בְּשָׁלוֹם, אַכְלִיל אֶת הָרַחֲמִים בַּדִּין, וְאֶתְקַשֵּׁר בְּקֶשֶׁר נֶאֱמָן לְהַכְלִיל הַכֹּל יַחַד. וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלֹהִים, שֶׁהֲרֵי אָז הַכֹּל יִהְיֶה קֶשֶׁר אֶחָד, וְהָאֶבֶן הַזּוֹ מִתְבָּרֶכֶת מִיָּמִין וּמִשְּׂמֹאל, מִתְבָּרֶכֶת מִמַּעְלָה וּמִמַּטָּה, מִשּׁוּם (זה) שֶׁאֶתֵּן מַעֲשֵׂר מִכֹּל."],[3,"","אָמַר רַבִּי אַבָּא, הִנֵּה כָּתוּב וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם. וְאִם תֹּאמַר שֶׁהָאֶבֶן הַזּוֹ עֶלְיוֹנָה (על) כַּמָּה אֲבָנִים לִמְקוֹם מוֹשָׁבָהּ לִשְׁרוֹת עֲלֵיהֶם, (זהו שכתוב) וַהֲרֵי כָּתוּב וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה - (עליונה היה צריך להיות,) מִשּׁוּם (כיון) שֶׁאָמַר אֵין זֶה כִּי אִם בֵּית אֱלֹהִים, כָּאן הֵרִים אוֹתָהּ מַצֵּבָה עֶלְיוֹנָה, מִשּׁוּם שֶׁתָּלָה בָּהּ כָּל הַשֶּׁבַח שֶׁל זֶה, שֶׁאֵין זֶה לְקַיֵּם (למטה) כִּי אִם בֵּית אֱלֹהִים, וְיָפֶה. וְעַל כֵּן אֲשֶׁר שַׂמְתִּי מַצֵּבָה."],[4,"","יִהְיְהִ בֵּית אֱלֹהִים, לְעוֹלָמִים. בֵּית אֱלֹהִים? בֵּית ה' הָיָה צָרִיךְ לִהְיוֹת, כְּמוֹ שֶׁנֶּאֱמַר לְכוֹנֵן אֶת בֵּית ה', וְכֵן (תהלים קכב) בֵּית ה' נֵלֵךְ. אֶלָּא מְקוֹם בֵּית הַדִּין הוּא מִשְּׁנֵי צְדָדִים עֶלְיוֹנִים - מִצַּד הַיּוֹבֵל שֶׁהוּא אֱלֹהִים חַיִּים, וּמֵהַצַּד שֶׁל יִצְחָק אֱלֹהִים."],[5,"","אָמַר רַבִּי אֶלְעָזָר, הַיּוֹבֵל, אַף עַל גַּב שֶׁהַדִּינִים (יוצאים) מִתְעוֹרְרִים מִמֶּנָּה וְכֻלָּם רַחֲמִים (ודינים), כָּל הַשְּׂמָחוֹת יוֹצְאוֹת מִמֶּנָּה, וְהוּא שִׂמְחַת (והוא חרות) הַכֹּל. אֶלָּא בֵּית אֱלֹהִים - הַצַּד שֶׁל הַדִּין הַקָּשֶׁה. אִם לְטוֹב, בְּצַד (היובל) הַשְּׂמֹאל מִתְעוֹרֶרֶת בּוֹ אַהֲבָה, כְּמוֹ שֶׁנֶּאֱמַר שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. אִם לְרַע, בְּצַד הַשְּׂמֹאל מִתְעוֹרֵר בּוֹ דִּין קָשֶׁה, כְּמוֹ שֶׁנֶּאֱמַר מִצָּפוֹן תִּפָּתַח הָרָעָה עַל כָּל יֹשְׁבֵי הָאָרֶץ. וַדַּאי בֵּית אֱלֹהִים. רַבִּי שִׁמְעוֹן אָמַר, בֵּית אֱלֹהִים, הַיְנוּ שֶׁכָּתוּב קִרְיַת מֶלֶךְ רָב. יֵשׁ מֶלֶךְ סְתָם וְיֵשׁ מֶלֶךְ רַב. וַדַּאי שֶׁהָעוֹלָם הָעֶלְיוֹן הוּא מֶלֶךְ רַב, וְזוֹהִי קִרְיַת מֶלֶךְ רָב."],[6,"","רַבִּי חִיָּיא וְרַבִּי חִזְקִיָּה הָיוּ יוֹשְׁבִים תַּחַת הָאִילָנוֹת שֶׁל שְׂדֵה אוֹנוֹ. נִרְדַּם רַבִּי חִיָּיא, וְרָאָה אֶת אֵלִיָּהוּ. אָמַר, מֵהוֹכָחַת הַדֶּרֶךְ שֶׁל מַר מֵאִיר הַשָּׂדֶה. אָמַר, כָּעֵת בָּאתִי לְהוֹדִיעַ שֶׁקְּרוֹבָה יְרוּשָׁלַיִם לְהֵחָרֵב, וְכָל אוֹתָן קִרְיוֹת הַחֲכָמִים, מִשּׁוּם שֶׁיְּרוּשָׁלַיִם הִיא דִין, וְעַל דִּין עוֹמֶדֶת וְעַל דִּין תֵּחָרֵב, וְהִנֵּה נִתְּנָה רְשׁוּת לְסמא\"ל עָלֶיהָ וְעַל גִּבּוֹרֵי הָעוֹלָם, וּבָאתִי לְהוֹדִיעַ לַחֲכָמִים אוּלַי יַאֲרִיכוּ אֶת שְׁנוֹת יְרוּשָׁלַיִם, שֶׁהֲרֵי כָּל זְמַן שֶׁנִּמְצֵאת בָּהּ תּוֹרָה - הִיא עוֹמֶדֶת, מִשּׁוּם שֶׁהַתּוֹרָה עֵץ הַחַיִּים הָעוֹמֵד עָלֶיהָ. כָּל זְמַן שֶׁהַתּוֹרָה מִתְעוֹרֶרֶת לְמַטָּה - עֵץ הַחַיִּים לֹא זָז לְמַעְלָה. פָּסְקָה הַתּוֹרָה לְמַטָּה - עֵץ הַחַיִּים מִסְתַּלֵּק (ממנה) מִן הָעוֹלָם."],[7,"","וְעַל כֵּן, כָּל זְמַן שֶׁהַחֲכָמִים יִשְׂמְחוּ בַּתּוֹרָה, לֹא יוּכַל עֲלֵיהֶם סמא\"ל, שֶׁהֲרֵי כָּתוּב הַקֹּל קוֹל יַעֲקֹב וְהַיָּדַיִם יְדֵי עֵשָׂו. זוֹ הַתּוֹרָה הָעֶלְיוֹנָה שֶׁנִּקְרֵאת קוֹל יַעֲקֹב. בְּעוֹד שֶׁאוֹתוֹ קוֹל לֹא פוֹסֵק, הַדִּבּוּר שׁוֹלֵט וְיָכוֹל, וְעַל כֵּן לֹא צָרִיךְ לְהַפְסִיק בַּתּוֹרָה. וְהִתְעוֹרֵר רַבִּי חִיָּיא, וְהָלְכוּ וְאָמְרוּ אֶת הַדָּבָר הַזֶּה לַחֲכָמִים."]]],[["אָמַר רִבִּי יֵיסָא, כֹּלָּא יָדְעִין דָּא, וְהָכִי הוּא, דִּכְתִיב, (תהילים קכ״ז:א׳) אִם ה' לֹא יִשְׁמָר עִיר שָׁוְא שָׁקַד שׁוֹמֵר, אִלֵּין אִנּוּן דְּמִשְׁתַּדְּלִין בְּאוֹרַיְיתָא, קַרְתָּא קַדִּישָׁא קָיְימָא עֲלַיְיהוּ, וְלָא עַל גַּבְרִין תַּקִּיפִין דְּעָלְמָא, הַיְינוּ דִכְתִיב אִם ה' לא יִשְׁמָר עִיר וְגו'.","(בראשית כ״ט:ב׳) וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה וְגו'. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהילים ג׳:א׳) מִזְמוֹר לְדָוִד בְּבָרְחוֹ מִפְּנֵי אַבְשָׁלוֹם בְּנוֹ. הַאי קְרָא אִתְעָרוּ בֵּיהּ חַבְרַיָא. אֲבָל מִזְמוֹר לְדָוִד, אַמַּאי קָאֲמַר שִׁירָה, אִי בְּגִין דִּבְרֵיהּ אִיהוּ דְקָם עֲלֵיהּ, קִינָה יַתִּיר מִבָּעֵי לֵיהּ, דְּהָא אַבְאִישׁ עֲלוֹי דְּבַר נַשׁ זְעֵיר מִקְּרִיבוֹי, מִדְּאָחֳרָא סַגִּי. אֶלָּא, מִזְמוֹר לְדָוִד, אָמַר שִׁירָה, וְהָכִי בָעֵי דָוִד, דְּחֲשִׁיב דְּקוּדְשָׁא בְּרִיךְ הוּא סָלִיק לֵיהּ חוֹבוֹי לְהַהוּא עַלְמָא. כֵּיוָן דְּחָמָא, דְּהָכָא בְּהַאי עַלְמָא בָּעֵי לְמִגְבֵיהּ מִנֵּיהּ, חָדֵי.","תוּ, דְּחָמָא דְּעִלָּאֵי מִנֵּיהּ הֲווּ בְּעַלְמָא, דְּקָא בָּרְחוּ, וְכֻלְּהוּ בִּלְחוֹדַיְיהוּ. יַעֲקֹב עָרַק, דִּכְתִיב, (הושע י״ב:י״ג) וַיִּבְרַח יַעֲקֹב שְׂדֵה אֲרָם, וְעָרַק בִּלְחוֹדוֹי. משֶׁה עָרַק, דִּכְתִיב, (שמות ב׳:ט״ו) וַיִּבְרַח משֶׁה מִפְּנֵי פַרְעֹה, וְעָרַק בִּלְחוֹדוֹי. וְדָוִד בָּרַח, כָּל אִינוּן שׁוּלְטָנֵי אַרְעָא, וְכָל אִינוּן גִּיבָּרֵי אַרְעָא, וְרֵישֵׁיהוֹן דְּיִשְׂרָאֵל, כֻּלְּהוּ עָרְקִין עִמֵּיהּ וְסָחֲרִין לֵיהּ, מִימִינֵיהּ וּמִשְׂמָאלֵיהּ, לְנַטְרָא לֵיהּ מִכָּל סִטְרִין, כֵּיוָן דְּחָמָא שְׁבָחָא דָא, אָמַר שִׁירָתָא.","וְאָמַר רִבִּי יְהוּדָה, כֻּלְּהוּ אִעָרְעוּ בְּהַאי בְּאֵר. וְדָוִד אַמַּאי לָא אַעֲרַע בֵּיהּ. אֶלָּא, דָּוִד מָארֵי דְבָבוּ, הֲוָה לְקֳבְלֵיהּ, (דבירא) בְּהַהוּא זִמְנָא, וּבְגִין כָּךְ, לָא אַעֲרַע בֵּיהּ. לְיַעֲקֹב וּמשֶׁה, בְּחֶדְוָה קַבִּיל לוֹן הַאי בְּאֵר, וּבָעָא לְאִתְקָרְבָא בַּהֲדַיְיהוּ, וְעַל דָּא כֵּיוָן דְּחָמָא לוֹן הַאי בְּאֵר סְלִיקוּ מַיָא לְגַבַּיְיהוּ, כְּאִתְּתָא דְּחֲדִיאַת עִם בַּעֲלָהּ.","וְאִי תֵימָא הָא אֵלִיָּהוּ בָּרַח וְלָא אַעֲרַע בֵּיהּ, אַמַּאי. אֶלָּא, אֵלִיָּהוּ לְתַתָּא מִן בְּאֵר הוּא, וְלָא לְעֵילָא, כְּמָה דְּהֲווּ משֶׁה וְיַעֲקֹב, וּבְגִין כָּךְ (מ\"ז ע\"ב), מַלְאָךְ אִיהוּ, וְעֲבִיד שְׁלִיחוּתָא, וּבְגִין דְּיַעֲקֹב וּמשֶׁה, לְעֵילָא אִינוּן מִן הַבְּאֵר, בְּאֵר חָדֵי לְגַבַּיְיהוּ, וְסָלִיק לְקַבְּלָא לוֹן, כְּאִתְּתָא דְחָדַאת לְגַבֵּי בַּעֲלָהּ, וּמְקַבְּלָא לֵיהּ.","וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה, רָזָא אִיהוּ, דְּחָמָא הַאי בְּאֵר לְעֵילָא, דָּא כְּגַוְונָא דָא, כְּתִיב, (בראשית כ״ט:ב׳) שְׁלשָׁה עֶדְרִי צֹאן רוֹבְצִים עָלֶיהָ, אִי אִינוּן שְׁלשָׁה, אַמַּאי כְּתִיב, (בראשית כ״ט:ב׳) וְנֶאֶסְפוּ שָׁמָּה כָּל הָעֲדָרִים. אֶלָּא, אִינוּן שְׁלשָׁה, דָּרוֹם, מִזְרָח, צָפוֹן. דָּרוֹם מֵהַאי סִטְרָא, וְצָפוֹן מֵהַאי סִטְרָא, וּמִזְרָח בֵּינַיְיהוּ, וְאִלֵּין קָיְימִין עַל הַאי בְּאֵר וְאֲחִידָן לֵיהּ, וּמַלְיָין לֵיהּ. מַאי טַעְמָא, בְּגִין, (בראשית כ״ט:ב׳) כִּי מִן הַבְּאֵר הַהִיא יַשְׁקוּ הָעֲדָרִים. הַיְינוּ דִכְתִיב, (תהילים ק״ד:י״א) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי."],[[0,"אמר רבי ייסא וכו':","אר\"י, הכל יודעים זה, כלומר דברי אליהו הם גלוים לכל החכמים, שהנוטה לשמאל מחריב את הנוקבא. וכן הוא כי כתוב, אם ה' לא ישמר עיר שוא שקד שומר אלו שעוסקין בתורה דהיינו הדבקים בקו אמצעי, הנקרא תורה, עומד עליהם העיר הקדושה, שהיא הנוקבא, ואז הוי\"ה שה\"ס עמוד האמצעי, שומר העיר, ולא על אנשים חזקים של העולם, דהיינו הדבקים בשמאל, והיינו שכתוב, אם הוי\"ה, שהוא קו אמצעי לא ישמר עיר, שוא שקד שומר, כי סופה להחרב, כמבואר."],[1,"וירא והנה באר בשדה:","ר' יהודה פתח ואמר, מזמור לדוד בברחו וגו', מקרא זה, העירו בו החברים, כלומר כבר דברו בו ובארוהו. אבל קשה, מזמור לדוד, שפירושו, שאמר שירה, למה אמר שירה, אם משום שבנו הוא שקם עליו, ולא זר, כי בנו ירחם עליו וזר אינו מרחם, זה אינו, כי עוד היה צריך להיות לו קינה יותר גדולה, כי אדם מתמרמר יותר על רעה מועטת מידי קרוביו, משמתמרמר על רעה מרובה מידי אחרים. ומשיב, אלא מזמור לדוד, פירושו שאמר שירה, כי כן רצה דוד. שמקודם לכן חשב שהקב\"ה יענישו על חטאיו בעולם הבא, כיון שראה שכאן בעולם הזה רוצה להפרע ממנו, היה שמח ואמר שירה."],[2,"תו, דחמא דעילאי וכו':","עוד טעם, כי דוד ראה שחשובים ממנו שהיו בעולם, היו בורחים, וכולם לבדם, יעקב ברח, שכתוב ויברח יעקב שדה ארם. וברח בלבדו, משה ברח שכתוב, ויברח משה מפני פרעה, וברח בלבדו. ודוד כשברח, כל אלו שליטי הארץ, וכל אלו גבורי הארץ וראשי ישראל, כולם היו בורחים עמו ומסבבים אותו מימינו ומשמאלו לשמרו מכל הצדדים. כיון שראה עצמו בשבח הזה, אמר שירה."],[3,"ואמר רבי יהודה וכו':","ואר\"י, כולם פגשו בבאר הזה, בשעת הבריחה, שהיא הנוקבא, ושואל, ודוד למה לא פגש בה בעת שברח. ומשיב, אלא דוד היה נחשב אז כשונא לנגדה, כי היא היתה נפרעת ממנו אז בעד החטא של בת שבע, ועל כן לא פגש בה. אבל ליעקב ולמשה, הבאר קבלה אותם בשמחה, ורצתה להתקרב אליהם, ועל כן, כיון שראה אותם הבאר, עלו המים לנגדם, כאשה השמחה עם בעלה."],[4,"ואי תימא הא אליהו וכו':","ואם תאמר, הרי אליהו ברח ולא פגש בבאר. למה. ומשיב, אלא אליהו הוא למטה מן הבאר, שהוא מרכבה להנוקבא הנקראת באר. ולא למעלה מן הבאר, כמו שהיו משה ויעקב, כי בשביל זה היה אליהו מלאך, ועושה שליחות הנוקבא. ומשום שיעקב ומשה, היו למעלה מן הבאר, שהם היו מרכבה לז\"א, הבאר היתה שמחה אליהם, והמים עלו לקראתם לקבל אותם שה\"ס עלית מ\"ן לקראת מ\"ד, כמו אשה השמחה לבעלה ומקבלת אותו."],[5,"וירא והנה באר בשדה:","הוא סוד. כי ראה את הבאר של מעלה שהיא הנוקבא, זה כעין זה, כלומר שהבאר של מטה היתה מכוונת כנגד הבאר של מעלה."],[5,"","כתוב והנה שלשה עדרי צאן רובצים עליה: משמע שג' עדרי צאן הם בקביעות על פי באר. ושואל, אם הם שלשה למה כתוב אח\"כ ונאספו שמה כל העדרים. שמשמע שיש עוד עדרים. ומשיב, אלא הם שלשה ולא יותר. שהם דרום מזרח צפון, דהיינו חסד ת\"ת גבורה, דרום, מצד זה בימין, וצפון מצד זה בשמאל, ומזרח, שהוא קו אמצעי, מכריע ביניהם. ואלו עומדים על באר הזו, ומתאחדים בה, וממלאים אותה. מה הטעם שמשקים אותה, משום \u0003כי מן הבאר ההיא ישקו העדרים,\u0004 דהיינו נשמות התחתונים שבבי\"ע, היינו שכתוב, ישקו כל חיתו שדי, שהם הנשמות שבבי\"ע. ובזה מיושב משה\"כ, ונאספו שמה כל העדרים, שכונתו, על כל הנשמות שבבי\"ע. אבל המשקים את הבאר, הם רק שלשה בלבד. שהם ג' הקוין חג\"ת."]],[[0,"","אָמַר רַבִּי יֵיסָא, הַכֹּל יוֹדְעִים אֶת זֶה, וְכָךְ הוּא, שֶׁכָּתוּב אִם ה' לֹא יִשְׁמָר עִיר שָׁוְא שָׁקַד שׁוֹמֵר. אֵלּוּ הֵם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, הַקִּרְיָה הַקְּדוֹשָׁה עוֹמֶדֶת עֲלֵיהֶם, וְלֹא עַל הַגְּבָרִים הַגִּבּוֹרִים שֶׁל הָעוֹלָם, הַיְנוּ שֶׁכָּתוּב אִם ה' לֹא יִשְׁמָר עִיר וְגוֹ'."],[1,"","וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה וְגוֹ'. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים ג) מִזְמוֹר לְדָוִד בְּבָרְחוֹ מִפְּנֵי אַבְשָׁלוֹם בְּנוֹ. בַּפָּסוּק הַזֶּה הִתְעוֹרְרוּ הַחֲבֵרִים, אֲבָל מִזְמוֹר לְדָוִד, לָמָּה אָמַר שִׁירָה? אִם מִשּׁוּם שֶׁבְּנוֹ הוּא שֶׁקָּם עָלָיו, יוֹתֵר קִינָה הָיָה צָרִיךְ לִהְיוֹת, שֶׁהֲרֵי הֵרַע עָלָיו עַל הָאָדָם קְצָת מִקְּרוֹבָיו מִשֶּׁאַחֵר הַרְבֵּה. אֶלָּא מִזְמוֹר לְדָוִד, אָמַר שִׁירָה, וְכָךְ בִּקֵּשׁ דָּוִד, שֶׁחָשַׁב שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא סִלֵּק אֶת חֶטְאוֹ לָעוֹלָם הַהוּא. כֵּיוָן שֶׁרָאָה שֶׁכָּאן בָּעוֹלָם הַזֶּה רוֹצֶה לִגְבּוֹת מִמֶּנּוּ, שָׂמַח."],[2,"","עוֹד, שֶׁרָאָה שֶׁעֶלְיוֹנִים מִמֶּנּוּ הָיוּ בָּעוֹלָם שֶׁבָּרְחוּ, וְכֻלָּם לְבַדָּם. יַעֲקֹב בָּרַח, שֶׁכָּתוּב (הושע יב) וַיִּבְרַח יַעֲקֹב שְׂדֵה אֲרָם, וּבָרַח לְבַדּוֹ. מֹשֶׁה בָּרַח, שֶׁכָּתוּב (שמות כ) וַיִּבְרַח מֹשֶׁה מִפְּנֵי פַרְעֹה, וּבָרַח לְבַדּוֹ. וְדָוִד בָּרַח, כָּל אוֹתָם שַׁלִּיטֵי הָאָרֶץ וְכָל אוֹתָם גִּבּוֹרֵי הָאָרֶץ וְרָאשֵׁי יִשְׂרָאֵל, כֻּלָּם בָּרְחוּ עִמּוֹ, וְסוֹבְבִים מִימִינוֹ וּמִשְּׂמֹאלוֹ לִשְׁמֹר אוֹתוֹ מִכָּל הַצְּדָדִים. כֵּיוָן שֶׁרָאָה הַשֶּׁבַח הַזֶּה, אָמַר שִׁירָה."],[3,"","וְאָמַר רַבִּי יְהוּדָה, כֻּלָּם פָּגְשׁוּ אֶת הַבְּאֵר הַזּוֹ. וְלָמָּה דָּוִד לֹא פָגַשׁ בָּהּ? אֶלָּא דָּוִד בַּעַל שִׂנְאָה הָיָה כְּנֶגְדּוֹ (של הבאר) בְּאוֹתוֹ הַזְּמַן, וּמִשּׁוּם כָּךְ לֹא פָגַשׁ בָּהּ. אֶת יַעֲקֹב וּמֹשֶׁה קִבְּלָה אוֹתָם הַבְּאֵר בְּשִׂמְחָה וְרָצְתָה לְהִתְקָרֵב עִמָּם. וְעַל כֵּן, כֵּיוָן שֶׁרָאֲתָה אוֹתָם הַבְּאֵר הַזּוֹ, עָלוּ הַמַּיִם אֵלֶיהָ כְּאִשָּׁה שֶׁשְּׂמֵחָה עִם בַּעְלָהּ."],[4,"","וְאִם תֹּאמַר, הִנֵּה אֵלִיָּהוּ בָּרַח וְלֹא פָגַשׁ בָּהּ, לָמָּה? אֶלָּא אֵלִיָּהוּ הוּא לְמַטָּה מִן הַבְּאֵר, וְלֹא לְמַעְלָה, כְּמוֹ שֶׁהָיוּ מֹשֶׁה וְיַעֲקֹב, וּמִשּׁוּם כָּךְ הוּא מַלְאָךְ וְעוֹשֶׂה שְׁלִיחוּת. וּמִשּׁוּם שֶׁיַּעֲקֹב וּמֹשֶׁה הֵם לְמַעְלָה מִן הַבְּאֵר, הַבְּאֵר שְׂמֵחָה אֲלֵיהֶם וְעָלְתָה לְקַבֵּל אוֹתָם כְּאִשָּׁה שֶׁשְּׂמֵחָה לְבַעְלָהּ וּמְקַבֶּלֶת אוֹתוֹ."],[5,"","וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה. סוֹד הוּא שֶׁרָאָה אֶת הַבְּאֵר הַזּוֹ לְמַעְלָה, זֶה כְּמוֹ זֶה. כָּתוּב שְׁלֹשָׁה עֶדְרֵי צֹאן רֹבְצִים עָלֶיהָ. אִם הֵם שְׁלֹשָׁה, לָמָּה כָּתוּב וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים? אֶלָּא הֵם שְׁלֹשׁה: דָּרוֹם, מִזְרָח, צָפוֹן. דָּרוֹם מִן הַצַּד הַזֶּה, וְצָפוֹן מֵהַצַּד הַזֶּה, וּמִזְרָח בֵּינֵיהֶם. וְאֵלּוּ עוֹמְדִים עַל הַבְּאֵר הַזּוֹ וְאוֹחֲזִים אוֹתָהּ וּמְמַלְּאִים אוֹתָהּ. מָה הַטַּעַם מִשּׁוּם כִּי מִן הַבְּאֵר הַהִיא יַשְׁקוּ הָעֲדָרִים. הַיְנוּ שֶׁכָּתוּב יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי."]]],[["וְנֶאֶסְפוּ שָׁמָּה כָּל הָעֲדָרִים, הַיְינוּ דִכְתִיב, (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם. (בראשית כ״ט:ג׳) וְגָלֲלוּ אֶת הָאֶבֶן, מַעֲבִירִין מִינָהּ תְּקִיפוּ דְדִינָא קַשְׁיָא, הַהוּא דְּגָלִיד וְקָרִישׁ, (ס\"א מיין דיכרין) דִּכְדֵין אִקְרֵי אֶבֶן, וְלָא נָפְקֵי מִינָהּ מַיָיא לְבַר. וְכַד אִינוּן נַחֲלִין אַתְיָין, אִתְתַּקַּף דָּרוֹם דְּאִיהוּ יְמִינָא, וְלָא יָכְלָא צָפוֹן לְמִקְרַשׁ מַיִין, כְּהַאי נַהֲרָא, כַּד מֵימוֹי סַגִּיאִין, לָא גְלִידִין וְקָרֵשֵׁי מַיָא, כְּנַהֲרָא דְמֵימוֹי זְעִירִין.","וְעַל דָּא, כַּד אִינוּן נַחֲלִין אַתְיָין, אִתְתַּקַּף (כ\"ט ע\"ב) דָּרוֹם דְּאִיהוּ יְמִינָא, וּמַיִין אִשְׁתַּרְיָין, וְנָגְדִין וְאַשְׁקְיָין עֲדָרַיָיא, כְּמָה דְּאֲמְרָן דִּכְתִיב יַשְׁקוּ כָּל חַיְיתוֹ שָׂדָי. (בראשית כ״ט:ג׳) וְהֵשִׁיבוּ אֶת הָאֶבֶן עַל פִּי הַבְּאֵר, לִמְקוֹמָהּ, בְּגִין דְּעַלְמָא אִצְטְרִיךְ דִּינָא דִילָהּ, דְּתֶהֱוֵי בְּדִינָא לְאוֹכָחָא בֵּיהּ חַיָּיבַיָא.","תָּא חֲזֵי, יַעֲקֹב כַּד הֲוָה יָתִיב עַל בֵּירָא, וְחָמָא מַיָא דְסָלְקִין לְגַבֵּיהּ, יָדַע דְּתַמָּן תִּזְדַּמֵּן לֵיהּ אִתְּתֵיהּ. וְכֵן בְּמשֶׁה, כַּד יָתִיב עַל בֵּירָא, כֵּיוָן דְּחָמָא דְמַיָא סַלְקִין לְגַבֵּיהּ, יָדַע דְּאִתְּתֵיהּ אִזְדַּמְּנַת לֵיהּ תַּמָּן, וְהָכִי הֲוָה לֵיהּ לְיַעֲקֹב, דְּתַמָּן אִזְדַּמֵּינַת לֵיהּ אִתְּתֵיהּ, כְּמָה דִכְתִיב, (בראשית כ״ט:ט׳) עוֹדֶנוּ מְדַבֵּר עִמָּם וְרָחֵל בָּאָה עִם הַצֹּאן, וַיְהִי כַּאֲשֶׁר רָאָה יַעֲקֹב אֶת רָחֵל וְגו'. משֶׁה, דִּכְתִיב, (שמות ו) וַיָּבֹאוּ הָרוֹעִים וַיְגָרְשׁוּם וְגו', וְתַמָּן אִזְדַּמְּנַת לֵיהּ צִפּוֹרָה, בְּגִין דְּהַהוּא בְּאֵר גָּרְמָא לוֹן."],[[0,"ונאספו שמה כל העדרים:","היינו שכתוב כל הנחלים הולכים אל הים, שנחלים הם הנשמות כן כל העדרים פירושו הנשמות. \u0003וגללו את האבן:\u0004 פירושו, שמעבירים ממנה, מן הבאר, את תוקף דין הקשה, דהיינו אותו הנגלד וקרוש, שאז נקרא אבן, שהמים אינם יוצאים ממנה ולחוץ. וכאשר אלו הנחלים באים אל הים, שהיא הנוקבא, מתחזק הדרום, שהוא ימין, דהיינו חסד, והצפון שהוא גבורה, אינו יכול עוד להקפיא המים. כאותו הנהר, שמימיו מרובים אינם נגלדים ונקפאים כנהר שמימיו מועטים."],[0,"","פירוש. כי אמר לעיל (ב\"א דף רמ\"ח אות ש\"ב) מסטרא דצפון גלידי מיא ומסטרא דדרום משתרן ונגדן. ע\"ש בסולם. שהצפון, ה\"ס קו שמאל בלי ימין, שאז החכמה מחוסרת חסדים, וע\"כ נקפאים האורות של הנוקבא הנקראת ים, ואין הארתה יוצא לתחתונים, אלא ביציאת קומת חסדים על מסך דחירק, שה\"ס קו אמצעי, אז מחמת ריבוי החסדים הוא מכריע כח הימין על השמאל, ונכללים זה בזה, והחכמה מתלבשת בחסדים של הדרום, ואז נמס הקפאון והשפע נוזל לתחתונים. ע\"ש."],[0,"","וכמו כדי להכריע בין ב' קוין שבבינה עולה ז\"א למ\"ן, ונעשה שם קו אמצעי מכריע, כן להכריע בין ז\"א לנוקבא שה\"ס ימין ושמאל, עולים נשמות הצדיקים, ונעשים קו מכריע ביניהם, שמכריעים כח הדרום שהוא חסדים על הצפון והקפאון של הים נפתח ונמס. וה\"ס הכתוב, כל הנחלים הולכים אל הים. כי הנשמות נקראות נחלים, (כנ\"ל בראשית א' דף צ\"ד ד\"ה רבה אמונתך ע\"ש) והן הולכות אל הים ונפתח מקפאונו."],[0,"","וז\"ש, \u0003ונאספו שמה כל העדרים, היינו דכתיב כל הנחלים וגו',\u0004 כי העדרים פירושם נשמות הצדיקים כמו הנחלים ההולכים אל הים. \u0003וגללו את האבן, מעבירין מינה וכו' ההוא דגליד וקריש דכדין אקרי אבן,\u0004 כי הכתוב מדבר בעת שליטת הצפון על הנוקבא, שאז המים שלה נקפאים ואינם מושפעים לחוץ לתחתונים, וע\"כ נבחן, כמו שמונח אבן גדולה על פי הבאר, וע\"כ אין לדלות מים ממנה. \u0003וכד אינון נחלין אתיין,\u0004 שהם נשמות הצדיקים העולות למ\"ן ויוצא קומת חסדים על המסך שלהן, ומכריעים את הימין על השמאל כנ\"ל, \u0003אתתקף דרום, דאיהו ימינא,\u0004 הנה על ידי ריבוי החסדים שגרמו הנשמות, מתחזק הדרום על הצפון, \u0003ולא יכלא צפון למקרש מיין. כהאי נהרא וכו',\u0004 כי על ידי ריבוי החסדים אינו נקפא עוד, בדומה לנהר שמימיו מרובים שאינו נקפא משום זה."],[1,"ועל דא כד אינון וכו':","וע\"כ כאשר אלו הנחלים באים, מתחזק הדרום, שהוא קו ימין, והמים נפתחים מקפאונם ונוזלים ומשקים את העדרים, שהם הנשמות, כמו שאמרנו, לעיל, שכתוב ישקו כל חיתו שדי, שהם הנשמות. \u0003והשיבו את האבן על פי הבאר למקומה,\u0004 משום שהעולם צריך אל הדינים של הנוקבא, וע\"כ צריכה להמצא בדין להוכיח עמו את הרשעים. ולפיכך מחזירים את האבן למקומו, באופן שאין הנוקבא מאירה אלא בעת הזווג שהנשמות עולות אליה למ\"ן. ואחר הזווג חוזרת ונסתמת."],[2,"ת\"ח יעקב וכו':","בוא וראה, יעקב, כשישב על הבאר, כיון שראה שהמים עולים אליו, ידע שאשתו תזדמן לו שם. וכן במשה כשישב על הבאר, כיון שראה המים עולים אליו, ידע שאשתו תזדמן לו שם. וכן היה, שאשתו נזדמנה שם ליעקב כמו שכתוב, עודנו מדבר עמם ורחל באה עם הצאן, ויהי כאשר ראה וגו'. וכן היה במשה, שכתוב ויבואו הרועים ויגרשום וגו', ושם נזדמנה לו צפורה אשתו. כי הבאר גרמה להם את זה. כי הבאר ה\"ס הנוקבא העליונה, וכמו שנפגשו בנוקבא עליונה, כן נפגשו עם הנוקבא שבעולם הזה."]],[[0,"","וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים, הַיְנוּ שֶׁכָּתוּב (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶת הַיָּם. וְגָלֲלוּ אֶת הָאֶבֶן - מַעֲבִירִים מִמֶּנָּה אֶת תֹּקֶף הַדִּין הַקָּשֶׁה, אוֹתוֹ שֶׁקָּפָא וְנִקְרַשׁ, (מים זכרים) שֶׁאָז נִקְרָא אֶבֶן, וְלֹא יוֹצְאִים מִמֶּנָּה מַיִם הַחוּצָה. וּכְשֶׁאוֹתָם הַנְּחָלִים בָּאִים, מִתְחַזֵּק הַדָּרוֹם, שֶׁהוּא הַיָּמִין, וְלֹא יָכוֹל הַצָּפוֹן לְהַקְרִישׁ אֶת הַמַּיִם, כַּנָּהָר הַזֶּה, כְּשֶׁמֵּימָיו רַבִּים, לֹא קוֹפְאִים וְנִקְרָשִׁים הַמַּיִם, כְּמוֹ נָהָר שֶׁמֵּימָיו מוּעָטִים."],[1,"","וְעַל כֵּן, כְּשֶׁאוֹתָם נְחָלִים בָּאִים, מִתְחַזֵּק הַדָּרוֹם, שֶׁהוּא הַיָּמִין, וְהַמַּיִם מַפְשִׁירִים וְשׁוֹפְעִים וּמַשְׁקִים אֶת הָעֲדָרִים, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי. וְהֵשִׁיבוּ אֶת הָאֶבֶן עַל פִּי הַבְּאֵר, לִמְקוֹמָהּ, מִשּׁוּם שֶׁהָעוֹלָם צָרִיךְ אֶת הַדִּין שֶׁלָּהּ, שֶׁתִּהְיֶה בְּדִין, לְהוֹכִיחַ אֶת הָרְשָׁעִים בָּהּ."],[2,"","בֹּא רְאֵה, כְּשֶׁיַּעֲקֹב הָיָה יוֹשֵׁב עַל הַבְּאֵר וְרָאָה הַמַּיִם עוֹלִים אֵלָיו, יָדַע שֶׁשָּׁם תִּזְדַּמֵּן לוֹ אִשְׁתּוֹ. וְכֵן בְּמֹשֶׁה, כְּשֶׁיָּשַׁב עַל הַבְּאֵר, כֵּיוָן שֶׁרָאָה שֶׁהַמַּיִם עוֹלִים אֵלָיו, יָדַע שֶׁאִשְׁתּוֹ תִּזְדַּמֵּן לוֹ לְשָׁם. וְכָךְ הָיָה לְיַעֲקֹב, שֶׁשָּׁם הִזְדַּמְּנָה לוֹ אִשְׁתּוֹ, כְּמוֹ שֶׁכָּתוּב עוֹדֶנּוּ מְדַבֵּר עִמָּם וְרָחֵל בָּאָה עִם הַצֹּאן. וַיְהִי כַּאֲשֶׁר רָאָה יַעֲקֹב אֶת רָחֵל וְגוֹ'. מֹשֶׁה, שֶׁכָּתוּב (שמות ב) וַיָּבֹאוּ הָרֹעִים וַיְגָרֲשׁוּם וְגוֹ', וְשָׁם הִזְדַּמְּנָה לוֹ צִפּוֹרָה, מִשּׁוּם שֶׁאוֹתָהּ הַבְּאֵר גָּרְמָה לָהֶם."]]],[["תָּא חֲזֵי הַאי בְּאֵר, שֶׁבַע זִמְנִין כְּתִיב בְּפָרְשָׁתָא דָא, בְּגִין דְּאִיהוּ רֶמֶז לְשֶׁבַע. וְהָכִי אִקְרֵי בְּאֵר שֶׁבַע, (ובגין) בְּאֵר דָּא, אִדְכַּר שֶׁבַע זִמְנִין בְּפָרְשָׁתָא דָא. דִּכְתִיב, (בראשית כ״ט:ב׳) וַיַּרְא וְהִנִּה בְּאֵר בַּשָּׂדֶה. כִּי מִן הַבְּאֵר הַהִיא. וְהָאֶבֶן גְּדוֹלָה עַל פִּי הַבְּאֵר. וְנֶאֶסְפוּ שָׁמָּה כָּל הָעֲדָרִים וְגו' מֵעַל פִּי הַבְּאֵר. וְהִשְׁקוּ אֶת הַצֹּאן וְהֵשִׁיבוּ אֶת הָאֶבֶן עַל פִּי הַבְּאֵר. וְגָלֲלוּ אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר. וַיְגַל אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר. הָא שִׁבְעָה. וּבְוַדַּאי דְּהָכִי הוּא.","בְּמשֶׁה לָא כְּתִיב אֶלָּא זִמְנָא חָדָא, דִּכְתִיב, (שמות ב׳:ט״ו) וַיֵּשֶׁב בְּאֶרֶץ מִדְיָן וַיֵּשֶׁב עַל הַבְּאֵר. בְּגִין דְּמשֶׁה, (כ\"ד ע\"א) אִתְפָּרַשׁ מִכֹּל וָכֹל מִבֵּיתָא דִלְתַתָּא, וְיַעֲקֹב לָא אִתְפָּרַשׁ כְּלָל. בְּמשֶׁה חַד, כְּמָה דִכְתִיב, (שיר השירים ו׳:ט׳) אַחַת הִיא יוֹנָתִי תַמָּתִי. אַחַת הִיא לְאִמָּהּ. וּבְגִין כָּךְ משֶׁה מָארֵיהּ דְּבֵיתָא הֲוָה, וְאִסְתַּלַּק לְעֵילָא, בְּמשֶׁה כְּתִיב, (שמות ב׳:ט״ו) וַיֵּשֶׁב עַל הַבְּאֵר, בְּיַעֲקֹב וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה, וְלָא כְּתִיב וַיֵּשֶׁב עַל הַבְּאֵר.","\u0003סתרי תורה\u0004 וירא והנה באר בשדה והנה שם שלשה עדרי צאן רובצים עליה. (בראשית כ״ט:ב׳) באר, דרגא דאדון כל הארץ. בשדה, חקל תפוחין קדישין. שלשה עדרי צאן, תלת דרגין עלאין קדישין, מתתקנן על ההוא בירא, ואינון, נצ\"ח והו\"ד ויסודא דעלמא. ואלין משכין מיא מלעילא, ומליין להאי בירא.","בגין דההוא מקורא, יסודא דעלמא, כד שארי בגו ההוא בירא, עביד פירי ונביע תדיר, ואתמליא ההוא בירא מניה. כיון דאתמליא, ודאי (בראשית כ״ט:ב׳) כי מן הבאר ההיא ישקו העדרים, אלין אינון כל אוכלוסין ומשריין קדישין, דכלהו שקיין ושתאן מההוא בירא, וכל חד וחד כמה דאתחזי ליה.","והאבן גדולה על פי הבאר. דא אבן, דמינה כשלי בני עלמא, אבן נגף וצור מכשול, דקיימא תדיר על פי האי באר, על מימריה, למתבע דינא דכל עלמא, דלא יחות מזונא וטב לעלמא.","וְנְאֶסְפּוּ שָׁמָּה כָּל הָעֲדָרִים, וְנֶאֶסְפּוּ שָׁמָּה הָעֲדָרִים, לָא כְּתִּיב, אֶלָּא כָּל הָעֲדָרִים, מַשִׁרְיָין קַדִּישִׁין לְעֵילָא, וּמַשִׁרְיָין קַדִּישִׁין לְתַּתָּא, אִלֵּין בְּשִׁירִין וְתּוּשְׁבְּחָן לְעֵילָא, ואִלֵּין בִּצְּלוֹתִּין וּבָעוּתִּין לְתַּתָּא, אִלֵּין וְאִלֵּין מִיָּד (בראשית כ״ט:ג׳) וְגָלֲלוּ אֶתּ הָאֶבֶן מֵעַל פִּי הַבְּאֵר, מְגַנְדְּרִין לָהּ, וּמַעַבְרִין לָהּ מִן קוּדְשָׁא וְאִסְתַּלִּיק מִן דִּינָא. מִיָּד וְהִשְׁקוּ אֶתּ הַצֹּאן, נָטְלוּ מַלְאֲכֵי עִלָּאֵי לְעֵילָא, וְנָטְלֵי יִשְׂרָאֵל לְתַּתָּא.","לְבָתַּר וְהֵשִׁיבוּ אֶתּ הָאֶבֶן, על מֵימְרָא, דְּהַאי בְּאר, לְאִתְּעַטְרָא (ס\"א לאתעתדא) קַמֵּיהּ, וּלְמִתְּבַּע דִּינָא דְעַלְמָא, לְאִתְּנַהֲגָא עַלְמָא בְּדִינָא, וְהָכִי אִצְּטְרִיךָ דְּהָא לָא יָכִיל עַלְמָא לְמֵיקַם אֶלָּא עַל דִּינָא, לְמֶהֱוֵי כֹּלָּא בִּקְשׁוֹט וּזְכוּ.","כֵּיוָן דְּאִשְׁתְּלִים יַעֲקֹב, לָא אִצְּטְרִיךָ לְהַאי אֶבֶן סִיּוּעָא אָחֳרָא, מַה כְּתִּיב (בראשית כ״ט:י׳) וַיִּגַשׁ יַעֲקֹב וַיְגַל אֶתּ הָאֶבֶן. וַיְגַל וְגָלֲלוּ, ולא כְּתִּיב וַיָּסַר וְהֵסִירוּ. אלּא וְגָלֲלוּ, הַיְינוּ עִרְבּוּבָא דְשָׂטָן, דִּמְעַרְבְּבִין לֵיהּ, דְּלָא יָכִיל לְקַטְרְגָא.","וְיַעֲקֹב בִּלְחוֹדֵיהּ, לָא אִצְּטְרִיךָ לְסִיּוּעָא אָחֳרָא, אלּא אִיהוּ בִלְחוֹדֵיהּ, דְּהָא שְׁלִימוּ דְּאֲבָהָתָּא הֲוָה יַעֲקֹב, דְּכֵיוָן דְּיָכִיל בֵּיהּ בְּעֵשָׂו בְּהַאי עַלְמָא יָכִיל לְעֵילָא. וּבְכלָּא אִצְּטְרִיךָ עוֹבָדָא.","תְּרֵין עַלְמִין אַחְסִין יַעֲקֹב, חַד עַלְמָא דְאִתְּגַּלְּיָא, וְחַד עַלְמָא דְאִתְּכַּסְּיָא כְּגַוְונָא דִלְהוֹן מַמָּשׁ, מֵחַד נָפְּקוּ שִׁיתּ שִׁבְטִין, וּמֵחָד נָפְּקוּ תְּרֵין שִׁבְטִין. עַלְמָא דְאִתְּכַּסְּיָא אַפִּיק שִׁיתּ סִטְרִין, עַלְמָא דְאִתְּגַּלְּיָא אַפִּיק תְּרֵין, וְאִינוּן תְּרֵין כְּרוּבִין דִּתְּחוֹתָּהּ, ויַעֲקֹב בֵּין תְּרֵין עָלְמִין אִשְׁתַּכַּח, בְּדִיוּקְנא דִּלְּהוֹן מַמָּשׁ, וּבְגִין כָּךָ כָּל מִלּוֹי דְּלֵאָה הֲווּ בְּאִתְּכַּסְּיָא, וּדְרָחֵל בְּאִתְּגַּלְּיָא.","\u0003תוספתא\u0004 (בראשית כ״ט:ב׳) וַיַּרְא והִנֵּה בְאֵר בַּשָׂדֶה. רִבִּי אֶלְעָזָר אָמַר, כְּתִּיב (ישעיהו נ״א:א׳) שִׁמְעוּ אֵלַי רוֹדְפֵּי צֶּדֶק, אִינוּן דְּתָּבְעֵי רָזָא דִּמְהֵימְנוּתָּא, אִינוּן דְּאִתְּדַּבְּקוּ בְּקִשׁוּרָא דִּמְהֵימְנוּתָּא, אִינוּן דְּיָדְעִין אָרְחוֹי דְמַלְכָּא עִלָּאָה.","כַּד סְלִיקוּ תְּרֵין, ונָפְּקוּ לָקֳדָמוּתּ חַד, מְקַבְּלִין לֵיהּ בֵּין תְּרֵין דְּרוֹעִין. תְּרֵי נָחֲתֵּי לְתַּתָּא, תְּרֵין אִינוּן, חַד בֵּינַיְיהוּ. תְּרֵין אִלֵּין מוֹתָּבָא דִנְבִיאֵי, אֲתַּר דְּיַנְקֵי בֵּיהּ, חַד בֵּינַיְיהוּ, דְּאִיהוּ אִתְּחַבַּר בְּכֹלָּא, הוּא נָטִיל כֹּלָּא.","הַהוּא בֵּירָא קַדִּישָׁא קָאִים תְּחוֹתַּיְיהוּ, חַקְלָא דְתַּפּוּחִין קַדִּישִׁין אִיהוּ. מֵהַאי בֵּירָא מִתְּשַׁקְיָין עֲדָרַיָא, כָּל אִינוּן רְתִּיכִין, כָּל אִינוּן מָארֵי גַדְפִּין. ג' קָיְימִין רְבִיעִין (קיימין) עַל הַאי בֵּירָא, הַאי בֵּירָא מִנַּיְיהוּ אִתְּמְלֵי, הֲדָא הוּא דִכְתִּיב, (בראשית כ״ט:ב׳) כִּי מִן הַבְּאֵר הַהִיא יַשְׁקוּ הָעֲדָרִים וְגו'. דָּא אדנ\"י אִתְּקְרֵי, עַל דָּא כְּתִּיב, (דברים ג׳:כ״ד) אֲדֹנָי אֱלהִים אַתָּה הַחִילוֹתָּ, וּכְתִּיב, (דניאל ז) והָאֵר פָּנְיךָ עַל מִקְדָּשְׁךָ הַשָׁמֵם לְמַעַן אֲדֹנָי. אֲדוֹן כָּל הָאָרֶץ, הֲדָא הוּא דִכְתִּיב, (יהושע ג׳:י״א) הִנִּה אֲרוֹן הַבְּרִיתּ אֲדוֹן כָּל הָאָרֶץ. (ע\"כ תוספתא)","דָּבָר אַחֵר (בראשית כ״ח:י׳) וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה, רִבִּי אַבָּא פָּתַח וְאָמַר, (תהילים ק״ו:ג׳) אַשְׁרֵי שֹׁמְרֵי מִשְׁפָּט (שם) עֹשֵׂה צְדָקָה בְּכָל עֵת. אַשְׁרֵי שׁוֹמְרֵי מִשְׁפָּט, זַכָּאִין אִינוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב לוֹן אוֹרַיְיתָא דִקְשׁוֹט לְאִשְׁתַּדָּלָא בָהּ יְמָמָא וְלֵילֵי. דְּהָא כָּל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, אִית לֵיהּ חֵירוּ מִכֹּלָּא, חֵירוּ מִן מוֹתָא דְּלָא יָכְלָא לְשַׁלְּטָאָה עֲלֵיהּ, וְהָא אוּקְמוּהָ. בְּגִין דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא וְאִתְאֲחִיד בָּהּ, אִתְאֲחִיד בְּאִילָנָא דְחַיֵּי. וְאִי אַרְפֵּי גַרְמֵיהּ מֵאִילָנָא דְחַיֵּי, הָא אִילָנָא דְמוֹתָא שַׁרְיָא עֲלוֹי, וְאִתְאֲחִיד בֵּיהּ. הֲדָא הוּא דִכְתִיב, (משלי כ״ד:י׳) הִתְרַפִּיתָ בְּיוֹם צָרָה צַר כֹּחֶכָה. הִתְרַפִּיתָ, אִי אַרְפֵּי יְדוֹי מֵאוֹרַיְיתָא.","בְּיוֹם צָרָה צַר כֹּחֶכָה, מַאי צַר כֹּחֶכָה. צַר כֹּחַ כֹּה, דְּהָא אִיהִי תָּדִיר לִימִינָא. וּנְטִירוּ דִילָהּ תָּדִיר עַל בַּר נָשׁ כַּד אָזִיל בְּאוֹרְחוֹי דְאוֹרַיְיתָא, וּכְדֵין דָּחֵי לֵיהּ לָרַע לְבַר דְּלָא יִקְרַב לְגַבֵּיהּ דְּבַּר נָשׁ, וְלָא יָכִיל לְקַטְרְגָא לֵיהּ. וְכַד בַּר נָשׁ אַסְטֵי מֵאָרְחוֹי דְאוֹרַיְיתָא וְאִתְרַפֵּי מִנָּהּ, כְּדֵין צַר כֹּחַ כֹּה, בְּגִין דְּהַהוּא רַע, דְּאִיהוּ שְׂמָאלָא שַׁלִּיט עֲלֵיהּ דְּבַר נָשׁ, וְדָחֵי לֵיהּ לְהַאי כֹּה לְבַר, עַד דְּדָחִיק לֵיהּ אֲתַר בְּעָקוּ.","דָבָר אַחֵר צַר כֹּחֶכָה, דְּכַד בַּר נָשׁ אָחִיד בְּאָרְחֵי דְאוֹרַיְיתָא, אִתְרָחִים לְעֵילָא וְאִתְרָחִים לְתַתָּא, וּרְחִימָא דְקוּדְשָׁא בְּרִיךְ הוּא הֲוִי, כְּמָה דְאַתְּ אָמֵר, (שמואל ב י״ב:כ״ד) וַיְיָ אַהֲבוֹ, דְּהֲוָה רְחִימוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, וְרָחִים לֵיהּ. וְכַד בַּר נָשׁ אַסְטֵי מֵאָרְחֵי דְאוֹרַיְיתָא, כְּדֵין צַר כֹּחַ כֹּה, צַר דִּילֵיהּ, וּמָארֵי דְבָבוּ אִיהוּ לְגַבֵּיהּ, וְשַׁלִּיט עֲלוֹי הַהוּא דְאִקְרֵי רַע. עַד דִּמְקַטְרֵג בֵּיהּ בְּהַאי עַלְמָא, וּבְעַלְמָא דְאָתֵי.","תָּא חֲזֵי, הַאי רַע דְּאִיהוּ יֵצֶר הָרָע, שַׁלִּיט עַל עַלְמָא בְּכַמָּה סִטְרִין. וְכַמָּה שָׁלְטָנוּ אִית לֵיהּ בְּעַלְמָא, וְאִיהוּ חִוְיָא תַּקִּיפָא דְּחָב בֵּיהּ אָדָם, וְכָשְׁלִין בֵּיהּ בְּנֵי עַלְמָא, וּמָשְׁכֵי לֵיהּ עֲלַיְיהוּ, עַד דְּאַפִּיק לוֹן נִשְׁמָתַיְיהוּ.","וְתָּא חֲזֵי, כַּד אִיהוּ שַׁלִּיט, שַׁלִּיט עַל גּוּפָא. (שלח לך קע\"ב ע\"ב) וְכֵיוָן דְּעַל גּוּפָא שַׁלִּיט, נִשְׁמָתָא נָפְקָא מִנֵּיהּ, בְּגִין דְּגוּפָא אִסְתָּאַב, וְנִשְׁמָתָא סָלְקָא. וְלָא שַׁלִּיט עֲלֵיהּ עַד דְּנָטִיל רְשׁוּ. וְכַמָּה אִינוּן דְּאַתְיָין מִסִּטְרֵיהּ, וְשָׁלְטִין עַל עָלְמָא. וְהָא תָּנִינָן דְּכָל עוֹבָדִין דְּעַלְמָא דְּאִתְעֲבִידוּ, וְשָׁלְטֵי בְּהוּ, וְאִית לֵיהּ מְמַנָּן וְשַׁמָּשִׁין, כֻּלְּהוּ שַׁמָּשִׁין בְּעוֹבָדִין דְּעָלְמָא.","וְעַל דָּא אִיהוּ קֵץ דִּשְׂמָאלָא, וְהָא (ס\"ב ע\"ב) אוּקְמוּהָ, דְּאִית קֵץ לִימִינָא, וְאִית קֵץ לִשְׂמָאלָא, וְהַאי קֵץ דִּשְׂמָאלָא, אִיהוּ קֵץ כָּל בָּשָׂר. קֵץ כָּל בָּשָׂר אִקְרֵי, קֵץ כָּל רוּחָא לָא אִקְרֵי, וְרָזָא דְמִלָּה, דָּא אִיהוּ קֵץ (כל בשר) וְדָא אִיהוּ קֵץ, דָּא קֵץ עַל (ס\"ב ע\"ב) בִּשְׂרָא וְדָא עַל רוּחָא. בְּגִין כָּךְ, דָּא פְּנִימִי וְדָא חִיצוֹן. דָּא יְמִינָא, וְדָא שְׂמָאלָא. דָּא קַדִּישָׁא, וְדָא מְסָאֲבָא. וְהָא אוּקְמוּהָ.","וְתָּא חֲזֵי, רָזָא עִלָּאָה קַדִּישָׁא דִּמְהֵימְנוּתָא, רָזָא דְעַלְמָא דִדְכוּרָא וְעַלְמָא דְנוּקְבָא, וְכָל קִדּוּשָׁא דְקַדִּישִׁין בֵּיהּ, וְכָל רָזֵי דִמְהֵימְנוּתָא מֵהָכָא נָפְקוּ. וְכָל חַיִּין וְכָל חֵירוּ וְכָל טָבִין וְכָל נְהוֹרִין מֵהָכָא אִינוּן, וְכָל בִּרְכָאן וְטַלֵּי נִדְבָאן וְכָל רְחִימוּ דִרְחִימוּתָא כֹּלָּא מִסִּטְרָא דָא, רָזָא דְּדָרוֹם."],[[0,"ת\"ח האי באר וכו':","בוא וראה באר זו כתובה בפרשה זו שבע פעמים. משום שהיא רמז לשבע, דהיינו לנוקבא דז\"א, שה\"ס שביעי, וכוללת שבע ספירות. וכן היא נקראת באר שבע. ומפרש באר זו נזכרה שבע פעמים בפרשה זו, שכתוב וירא והנה באר בשדה, כי מן הבאר וכו', הרי שבע, ובודאי כן הוא. כי כוללת שבע מדרגות."],[1,"במשה לא כתיב וכו':","במשה לא כתוב באר אלא פעם אחת. שכתוב, וישב בארץ מדין וישב על הבאר. והוא משום שמשה נפרש מכל וכל מן הבית שלמטה, דהיינו הנוקבא שמחזה ולמטה דז\"א שהוא רחל, הנקראת שבע, והיה דבוק בעלמא דאתכסיא, שה\"ס הנוקבא שמחזה ולמעלה. ויעקב, לא נפרש כלל מהנוקבא שמחזה ולמטה שה\"ס רחל. שהיא בחינת עלמא דאתגליא הנקראת שבע. וע\"כ במשה כתוב באר, פעם אחת, שכתוב, אחת היא יונתי תמתי אחת היא לאמה, כי עלמא דאתכסיא נמשכת מאמא, והיא אחת לאמא, ומשום זה היה משה, בעל הבית, כלומר שהיה שורשו למעלה מן הנוקבא של מטה הנקראת בית. ונתעלה למעלה ממנה. וע\"כ כתוב במשה וישב על הבאר, דהיינו למעלה מבאר, וביעקב כתוב, וירא והנה באר בשדה, ולא כתוב וישב על הבאר."],[2,"וירא והנה באר בשדה וגו':","באר, היא המדרגה שנקראת אדון כל הארץ, דהיינו הנוקבא, בעת שמקבלת חכמה, אשר אז בדכורא אסתיימת, ונקראת בשם זכר, אדון. ומפרש. \u0003בשדה\u0004 פירושו חקל תפוחין קדישין דהיינו הנוקבא שמחזה ולמטה, \u0003שלשה עדרי צאן\u0004 פירושו ג' מדרגות עליונות, קדושות, המתתקנים על אותה הבאר, והם נצח, הוד, ויסוד העולם. ונה\"י אלו, מושכים מים, דהיינו שפע, מלמעלה מז\"א, וממלאים את הבאר."],[3,"בגין דההוא מקורא:","משום שמקור הזה, שהיא יסוד העולם הנ\"ל, כשהוא שורה בתוך באר ההוא, הוא עושה שם פירות ונובע תמיד, והבאר מתפלאת ממנו. כלומר, שהיסוד משפיע אל הבאר שהיא הנוקבא, ב' מיני שפע א) להולדות נשמות שהם פירות. ב) לזון את התחתונים. כיון שהבאר נתמלא עם השפע, ודאי, כי מן הבאר ההוא ישקו העדרים, הם כל המוני נשמות וצבאות הקדושים, שכולם שותים מאותה הבאר, וכל אחד ואחד כפי הראוי לו."],[4,"והאבן גדולה על פי הבאר:","זהו אבן, שממנה נכשלים בני העולם, שהוא, אבן נגף וצור מכשול, שהוא הס\"א, העומדת תמיד על פי הבאר, דהיינו על פי פקודתה, לתבוע דין של כל העולם, שלא ירד מזון וטוב לעולם. דהיינו בעת שהנוקבא מקבלת משמאל בלי ימין, שאז היא מענישה ותובעת דין כנ\"ל."],[5,"ונאספו שמה כל העדרים:","שואל, ונאספו שמה העדרים לא כתוב, אלא שכתוב כל העדרים. מהו \u0003כל.\u0004 ומשיב, אלא כל העדרים היינו מחנות הקדושות למעלה, שהם המלאכים, ומחנות הקדושות למטה, שהם הצדיקים. אלו בשירות ותשבחות למעלה. ואלו בתפלות ובקשות למטה. אלו ואלו ביחד, מיד, וגללו את האבן מעל פי הבאר, מגללים אותה ומעברים אותה מן הקדש. והבאר מסתלקת מן הדין, המכונה אבן."],[6,"לבתר, והשיבו את האבן על מימרא וכו':","היינו על פי צוויה של הבאר, משיבים האבן למקומה, שתהיה מזומנת לפניה לתבוע דין על העולם, כדי שיתנהג העולם בדין. וכן צריך להיות, כי אין העולם יכול להתקיים אלא על דין, שיהיה הכל באמת וצדקה."],[7,"כיון דאשתלים יעקב:","כיון שנשלם יעקב, כי מצא את בת זוגו, רחל, לא היה צריך עזרה אחרת לאבן ההוא. מה כתוב, ויגש יעקב ויגל את האבן, ושואל, כתוב \u0003ויגל, וגללו\u0004, ולא כתוב ויסר, והסירו. ומשיב, אלא \u0003וגללו\u0004, היינו ערבוב השטן, מלשון מגלגלין עליו את הכל, (ב\"ב ד.) שמערבבים אותו ואינו יכול לקטרג. כמו שנתבאר ענין זה לעיל (פרשת וירא דף קי\"ג אות שפ\"ג ע\"ש)."],[8,"ויעקב בלחודיה וכו':","ויעקב בלבדו גלל את האבן ולא נצרך לעזרה מאחר, אלא הוא בלבדו. כי יעקב היה בחיר האבות, דהיינו קו האמצעי, וע\"כ ע\"י המשכת החסדים על מסך דחירק, גלל האבן מעל פי הבאר. שהשמאל נכלל בימין, כנ\"ל. וכיון שהיה יכול אל עשו בעולם הזה, היה יכול לו למעלה. ובכל דבר צריכים מקודם פעולה למטה. כלומר כיון שיעקב עשה מקודם פעולה למטה בעולם הזה לנצח את עשו, זכה ג\"כ לנצח אותו למעלה, שה\"ס גלילת האבן שעל פי הבאר, שהוא הבטול של כחו של עשו למעלה, המקטרג על ישראל, כנ\"ל."],[9,"תרין עלמין וכו':","שני עולמות ירש יעקב אחד עולם הנגלה, ואחד עולם הנסתר, שהם ב' נוקבין דז\"א, אחת למעלה מחזה, לאה. ואחת למטה מחזה, רחל. שלאה ורחל נשי יעקב היו, בדומה אליהן ממש. כי להיותו קו אמצעי כנ\"ל, היה לו להכריע בסוד יחודא עלאה ויחודא תתאה כמו ז\"א. (כנ\"ל דף כ\"א ד\"ה א\"ל) מאחת יצאו ששה שבטים, דהיינו מלאה, שהיא עולם הנסתר, ומאחת יצאו ב' שבטים דהיינו מרחל שהיא כנגד עולם הנגלה. וכמו כן עולם הנסתר שהיא לאה נוקבא דז\"א, הוציאה שש קצוות, ממה שיונקת מחב\"ד חג\"ת דכלים, וחג\"ת נה\"י דאורות, שמחזה ולמעלה דז\"א, ועולם הנגלה, שהיא רחל, הנוקבא דז\"א שמחזה ולמטה, הוציאה שנים, ממה שיונקת מנה\"י דז\"א. שהם יסוד הכולל נצח והוד, והמלכות, והם ב' כרובין: הנקראים מטטרון וסנדלפון, שמטטרון נמשך ממה שיונקת מיסוד דז\"א, וסנדלפון נמשך ממה שיונקת ממלכות דז\"א. שהם כנגד יוסף ובנימין בני רחל אשת יעקב, ויעקב היה נמצא בין שני העולמות הנגלה והנסתר בצורתם ממש. כלומר, בצורת יחודא עלאה ויחודא תתאה הנוהג בז\"א, בסוד שמע ישראל, ובשכמל\"ו (כנ\"ל בהקסה\"ז דף קצ\"ד אות ר\"ד ע\"ש) ומשום זה כל דבריה של לאה היו במכוסה ובהעלם, וכל דבריה של רחל היו בהתגלות."],[10,"וירא והנה באר בשדה:","רבי אלעזר אמר כתיב, שמעו אלי רודפי צדק. שפירושו הרודפים לתקן את הנוקבא הנקראת צדק. הם התובעים סוד האמונה, היינו התובעים דין לתיקון הנוקבא המכונה אמונה, שה\"ס קו שמאל. הם שנתדבקו בקשר האמונה, שה\"ס הקשר בקו ימין, הם היודעים דרכיו של מלך העליון, שה\"ס \u0003קו אמצעי,\u0004 והתוספתא הזמינה בזה, לאותם שזכו לג' קוין, ורודפים לתקן הנוקבא, שהמה ישמעו הדברים. וע\"כ פתחה בהכתוב שמעו אלי וגו'."],[11,"כד סליקו תרין וכו':","בעת שעולים שנים הקוין, ויוצאים לקראת האחד, שהוא קו אמצעי, הם מקבלים אותו בין שתי הזרועות, שנים הקוין יורדים למטה, שנים הם ואחד ביניהם. אלו שנים הם המושב של הנביאים המקום שיונקים שמה. אחד ביניהם, שהוא מתחבר בכולם, והוא לוקח וכולל את כולם."],[11,"","ביאור הדברים. התוספתא באה לבאר בעיקר, ב' דברים: א) באר מה היא. ב) למה כתוב ג' עדרי צאן רובצים עליה, שהם נה\"י בלבד, ולא יותר. והנה נודע שמסבת הכרעת הת\"ת, אין השמאל יכול להאיר עוד ממעלה למטה, כמו הימין, אלא ממטה למעלה בלבד. (כנ\"ל לך דף ט' ד\"ה וז\"ש) והתוספתא מדברת כאן, מיציאת ג' הקוין בשורשם דהיינו בבינה. אשר קו הימין ה\"ס החכמה שבה, וקו שמאל ה\"ס הבינה שבה. וז\"ש, \u0003כד סליקו תרין ונפקו לקדמות חד\u0004 בעת ששני הקוין מאירים בדרך עליה דהיינו בהארת החכמה, המאירה רק ממטה למעלה שהוא בעת שיוצאים לקראת קו האמצעי, שהוא ממעט הארת השמאל לבחינת ממטה למעלה, שהוא ו\"ק, נבחן אז אשר, \u0003מקבלין ליה בין תרין דרועין,\u0004 שב' הקוין מקבלים הכרעת קו האמצעי, בהיותם ב' זרועות, שהם חסד וגבורה. כלומר שירדו מבחינת חכמה ובינה ונעשו לחסד וגבורה, דהיינו מג\"ר לו\"ק, כי אינם יכולים יותר להאיר ממעלה למטה, ועוד נבחן, \u0003תרי נחתי לתתא,\u0004 שאלו שני הקוין שנעשו לחסד וגבורה ירדו עוד למטה, דהיינו שנעשו לנצח והוד שלמטה מטבור. והוא מטעם תקון ההתהפכות עליונים למטה, שנעשה בהארת השמאל, שהעלה סוד גזרת דינא למעלה, שה\"ס נה\"י, ואחריה חג\"ת, ולבסוף הג\"ר, למטה מכולם. (כנ\"ל בפ' וירא דף פ\"ג ד\"ה פנימיות עש\"ה) ומטעם זה שוב ירדו ב' הקוין ירידה שניה, שנעשו לנצח והוד של מטה מטבור, ששם נמצאת הגזרא דדינא."],[11,"","ולפי שחו\"ג ירדו לנצח והוד, ירד גם קו אמצעי עמהם, והת\"ת נעשה ליסוד. וז\"ש \u0003תרין אנון חד בינייהו,\u0004 שהם שנים ואחד ביניהם, כלומר שגם האחד, שהוא קו אמצעי ירד עמהם. וכדי שלא נטעה, ונדע שכוונתו היא לנצח והוד, הוא מציין אותם, ואומר, \u0003תרין אלין מותבא דנביאי, אתר דינקי ביה.\u0004 ששנים אלו שאומר, הם מושב הנביאים, המקום שיונקים משם, שהוא נצח והוד, כנודע. ומפרש, \u0003חד בינייהו,\u0004 ועל כן ירד גם קו אמצעי ביניהם, משום \u0003דאיהו אתחבר בכלא, הוא נטיל כלא,\u0004 כי שני הקוין אינם יכולים להאיר זולת חיבורו עמהם, והוא כולל הארת שניהם. ולפיכך הכרח הוא שירד גם קו אמצעי עמהם, שהוא יסוד."],[11,"","והנך רואה שבעת שג' הקוין מאירים בשליטת קו השמאל, דהיינו במוחין דחכמה, אינם מאירים רק בבחינת נה\"י שבהם. כי החב\"ד ירדו לחג\"ת ושניהם לנה\"י, כמבואר. אבל בעת שג' הקוין מאירים בשליטת קו הימין, דהיינו במוחין דחסדים הכלולים מהארת חכמה, מאירים אז כל הט' ספירות שבהם, כי החב\"ד שבהם לא ירדו לחג\"ת לבחינת ו\"ק, אלא שמאירים ממעלה למטה כדרכם. ואין צריך לומר שהחג\"ת לא ירדו לנה\"י, כי תקון ההתפכות לא נעשה אלא בקו שמאל."],[12,"ההוא בירא קדישא וכו':","באר הקדושה ההוא, שה\"ס הנוקבא, בעת שמאירה מסוד החכמה, שבמוחין דג' קוין, עומדת תחתיהם, דהיינו, תחת נצח הוד יסוד הנ\"ל, שחב\"ד חג\"ת ירדו ונכללו בהם. הוא נקראת אז, שדה של תפוחים הקדושים. מבאר ההוא ישקו העדרים, שהם, כל אלו המרכבות של המלאכים, וכל אלו המלאכים בעלי הכנפים. ג' נמצאים רובצים על באר הזו, שהם ג' ספירות נצח הוד יסוד, ולא יותר, כי כל הט' ספירות נכללות בג' הללו, כנ\"ל. ובאר הזו מתמלאת מהם. וז\"ש, כי מן הבאר ההוא ישקו העדרים. והיא נקראת בשם \u0003אדנ\"י,\u0004 והוא שכתוב, אדנ\"י אלקים אתה החילות. וכתוב והאר פניך על מקדשך השמם למען אדנ\"י. והיא נקראת אדון כל הארץ, וזהו שכתוב, הנה ארון הברית אדון כל הארץ. (ע\"כ תוספתא)"],[13,"דבר אחר ויצא יעקב וגו':","רבי אבא פתח ואמר, אשרי שומרי משפט עושה צדקה בכל עת. \u0003אשרי שומרי משפט,\u0004 אשרי הם ישראל, שהקב\"ה נתן להם תורת אמת לעסוק בה יום ולילה, כי כל מי שעוסק בתורה יש לו חירות מכל דבר, חירות מן המות, שאינו יכול לשלוט עליו, ובארוהו, כי כל מי שעוסק בתורה ונתאחז בה, נתאחז בעץ החיים. ואם מרפה את עצמו מעץ החיים, הרי עץ המות שורה עליו ומתאחז בו. וזהו שכתוב, התרפית ביום צרה צר כחכה. \u0003התרפית,\u0004 פירושו, אם הרפה ידיו מתורה."],[14,"ביום צרה צר כחכה:","שואל מהו צר כחכה. ומשיב, \u0003צר כח כה.\u0004 דהיינו נוטריקון של \u0003כחכה.\u0004 ושיעור הכתוב, הוא כי המתרפה מתורה אז \u0003צר כח\u0004 השכינה הנקראת \u0003כה.\u0004 ואינה מגינה עליו. כי השכינה היא תמיד בימין, ומשמרת את האדם תמיד, כשהולך בדרכי התורה, ואז היא דוחה את הרע לחוץ, שלא יקרב אל האדם, ולא יוכל לקטרג עליו. וכשהאדם נוטה מדרכי התורה, ומתרפה ממנה, אז \u0003צר כח כ\"ה,\u0004 שהיא השכינה, משום שאותו הרע, שהוא שמאל, שולט על האדם, והוא דוחה את \u0003כה\u0004 הזו, שהיא השכינה, לחוץ, עד שנעשה צר לו המקום במצור ובמצוק."],[15,"ד\"א צר כחכה:","פירוש אחר על הכתוב \u0003צר כחכה,\u0004 כי כשהאדם אוחז בדרכי התורה, הוא אהוב למעלה ואהוב למטה, ונעשה אהובו של הקב\"ה. כמו שאתה אומר, \u0003וה' אהבו,\u0004 שהיה אהובו של הקב\"ה ואהב אותו. וכאשר האדם נוטה מדרכי התורה, אז \u0003צר כח, כ\"ה,\u0004 שהיא השכינה, שנעשתה צר ואויב שלו, והוא נעשה שונא שלה. ורע ההוא שהוא יצר הרע, שולט עליו, עד שהוא מקטרג עליו בעולם הזה ובעולם הבא."],[16,"ת\"ח האי רע וכו':","בוא וראה, רע הזה שהוא יצר הרע, שולט על העולם בהרבה אפנים, והרבה ממשלה יש לו בעולם, והוא נחש העריץ, שחטא בו אדם הראשון, ובני העולם נכשלים בו, וממשיכים אותו עליהם עד שמוציא נשמתם מהם."],[17,"ות\"ח כד איהו וכו':","ובוא וראה, כאשר הוא, היצר הרע, שולט, שולט על הגוף, וכיון ששולט על הגוף, יוצאת ממנו הנשמה, כי מכיון שהגוף נטמא הנשמה עולה ממנו. ואינו שולט, להוציא נשמתו של אדם, עד שמקבל רשות (כנ\"ל פ' נח דף כ\"ט אות ע\"ח). והרבה הם הבאים מצד היצר הרע ושולטים בעולם. ולמדנו, שכל המעשים שנעשו בעולם הם שולטים בהם, שעל ידי פיתוים נעשו, ויש לו ממונים ומשרתים, כולם משרתים במעשי העולם כלומר, שמפתים בני אדם לעשות מעשים רעים."],[18,"ועל דא איהו קץ וכו':","ועל כן הוא קץ של השמאל. ובארוהו, שיש קץ לימין ויש קץ לשמאל, וזה הקץ של השמאל, הוא קץ כל בשר. (כמ\"ש לעיל פ' נח דף כ\"ה אות ע\"ה ד\"ה קץ ע\"ש) קץ כל בשר נקרא, ואינו נקרא קץ כל רוח. וסוד הדבר הוא שיש ב' קצים, זה הוא קץ, וזה הוא קץ, זה הוא קץ על בשר, דהיינו הממונה על הגוף, וזה הוא קץ על רוח, שהוא הממונה על רוח האדם. משום זה, זה פנימי, דהיינו הקץ על רוח, וזה חיצון, דהיינו הקץ על בשר. זה הפנימי קדוש, וזה החיצין הוא טמא. וכבר בארוהו."],[19,"ות\"ח רזא עלאה וכו':","בוא וראה. בצד ימין שהוא דרום, בו הוא, סוד העליון הקדוש של האמונה, סוד עולם הזכר שהוא ז\"א, וסוד עולם הנקבה, שהוא הנוקבא דז\"א. וכל קודש הקדשים, וכל סודות האמונה, שהיא הנוקבא. מכאן הם יוצאים. וכל החיים וכל החירות וכל הטוב וכל האורות מכאן הם. וכל הברכות, וטלי נדבה, וכל האהבה שבאהבות, הכל מצד הזה, דהיינו צד ימין, סוד הדרום."]],[[0,"","בֹּא רְאֵה, הַבְּאֵר הַזוֹ כְּתוּבָה שֶׁבַע פְּעָמִים בַּפָּרָשָׁה הַזּוֹ, מִשּׁוּם שֶׁהִיא רֶמֶז לְשֶׁבַע. וְכָךְ נִקְרֵאת בְּאֵר שֶׁבַע. (ומשום) הַבְּאֵר הַזּוֹ נִזְכֶּרֶת שֶׁבַע פְּעָמִים בַּפָּרָשָׁה הַזּוֹ, שֶׁכָּתוּב וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה. כִּי מִן הַבְּאֵר הַהִיא. וְהָאֶבֶן גְּדֹלָה עַל פִּי הַבְּאֵר. וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים וְגוֹ' מֵעַל פִּי הַבְּאֵר. וְהִשְׁקוּ אֶת הַצּאן וְהֵשִׁיבוּ אֶת הָאֶבֶן עַל פִּי הַבְּאֵר. וְגָלֲלוּ אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר. וַיָּגֶל אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר. הֲרֵי שִׁבְעָה, וּבְוַדַּאי שֶׁכָּךְ זֶה."],[1,"","בְּמֹשֶׁה לֹא כָתוּב אֶלָּא פַּעַם אַחַת, שֶׁכָּתוּב וַיֵּשֶׁב בְּאֶרֶץ מִדְיָן וַיֵּשֶׁב עַל הַבְּאֵר. מִשּׁוּם שֶׁמֹּשֶׁה נִפְרַד מִכֹּל וָכֹל מֵהַבַּיִת שֶׁלְּמַטָּה, וְיַעֲקֹב לֹא נִפְרַד כְּלָל. בְּמֹשֶׁה אֶחָד, כַּכָּתוּב (שיר ו) אַחַת הִיא יוֹנָתִי תַמָּתִי. אַחַת הִיא לְאִמָּהּ. וּמִשּׁוּם כָּךְ מֹשֶׁה הָיָה בַּעַל הַבַּיִת וְהִתְעַלָּה לְמַעְלָה. בְּמֹשֶׁה כָּתוּב וַיֵּשֶׁב עַל הַבְּאֵר. בְּיַעֲקֹב - וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה, וְלֹא כָתוּב וַיֵּשֶׁב עַל הַבְּאֵר."],[2,"","וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה וְהִנֵּה שָׁם שְׁלֹשָׁה עֶדְרֵי צֹאן רֹבְצִים עָלֶיהָ. בְּאֵר - הַדַּרְגָּה שֶׁל אֲדוֹן כָּל הָאָרֶץ. בַּשָּׂדֶה - שְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים. שְׁלֹשָׁה עֶדְרֵי צֹאן - שָׁלֹשׁ דְּרָגוֹת עֶלְיוֹנוֹת קְדוֹשׁוֹת מְתֻקָּנוֹת עַל אוֹתָהּ הַבְּאֵר, וְהֵן נֶצַ\"ח וְהוֹ\"ד וְהַיְסוֹד שֶׁל הָעוֹלָם. וְאֵלּוּ מוֹשְׁכוֹת מַיִם מִלְמַעְלָה וּמְמַלְּאִים אֶת הַבְּאֵר הַ את."],[3,"","מִשּׁוּם שֶׁהַמָּקוֹר הַהוּא, יְסוֹד הָעוֹלָם, כְּשֶׁשּׁוֹרֶה בַּבְּאֵר הַזּוֹ, הוּא עוֹשֶׂה פֵּרוֹת וְנוֹבֵעַ תָּמִיד, וְאוֹתָהּ הַבְּאֵר מִתְמַלֵּאת מִמֶּנּוּ. כֵּיוָן שֶׁהִתְמַלְּאָה, וַדַּאי כִּי מִן הַבְּאֵר הַהִיא יַשְׁקוּ הָעֲדָרִים, אֵלּוּ הֵם כָּל הָאוּכְלוּסִים וְהַמַּחֲנוֹת הַקְּדוֹשִׁים, שֶׁכֻּלָּם מֻשְׁקִים וְשׁוֹתִים מֵהַבְּאֵר הַהִיא, וְכָל אֶחָד וְאֶחָד כָּרָאוּי לוֹ."],[4,"","וְהָאֶבֶן גְּדֹלָה עַל פִּי הַבְּאֵר - זוֹ הָאֶבֶן שֶׁמִּמֶּנָּה כּוֹשְׁלִים בְּנֵי הָעוֹלָם, אֶבֶן נֶגֶף וְצוּר מִכְשׁוֹל, שֶׁעוֹמֶדֶת תָּמִיד עַל פִּי הַבְּאֵר הַזּוֹ, עַל פְּקֻדָּתָהּ לִתְבֹּעַ הַדִּין שֶׁל כָּל הָעוֹלָם שֶׁלֹּא יֵרֵד מָזוֹן וְטוֹב לָעוֹלָם."],[5,"","וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים. לֹא כָתוּב וְנֶאֶסְפוּ שָׁמָּה הָעֲדָרִים, אֶלָּא כָּל הָעֲדָרִים. הַמַּחֲנוֹת הַקְּדוֹשִׁים לְמַעְלָה וְהַמַּחֲנוֹת הַקְּדוֹשִׁים לְמַטָּה. אֵלּוּ בְּשִׁירִים וְתִשְׁבָּחוֹת לְמַעְלָה, וְאֵלּוּ בִּתְפִלּוֹת וּבַקָּשׁוֹת לְמַטָּה. אֵלּוּ וְאֵלּוּ מִיָּד וְגָלֲלוּ אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר. מְגַלְגְּלִים אוֹתָהּ וּמַעֲבִירִים אוֹתָהּ מִן הַקֹּדֶשׁ וּמִסְתַּלֶּקֶת מִן הַדִּין. מִיָּד וְהִשְׁקוּ אֶת הַצּאן. נוֹסְעִים מַלְאָכִים עֶלְיוֹנִים לְמַעְלָה, וְנוֹסְעִים יִשְׂרָאֵל לְמַטָּה."],[6,"","אַחַר כָּךְ וְהֵשִׁיבוּ אֶת הָאֶבֶן, עַל פְּקֻדַּת הַבְּאֵר הַזּוֹ, שֶׁתִּהְיֶה מְעֻטֶּרֶת (מזמנת) לְפָנָיו וְלִתְבֹּעַ הַדִּין שֶׁל הָעוֹלָם, לְהַנְהִיג הָעוֹלָם בְּדִין, וְכָךְ צָרִיךְ, שֶׁהֲרֵי אֵין הָעוֹלָם יָכוֹל לַעֲמֹד אֶלָּא עַל דִּין, שֶׁהַכֹּל יִהְיֶה בֶּאֱמֶת וּזְכוּת."],[7,"","כֵּיוָן שֶׁנִּשְׁלַם יַעֲקֹב, לֹא הִצְטָרֵךְ לָאֶבֶן הַזּוֹ סִיּוּעַ אַחֵר. מַה כָּתוּב? וַיִּגַּשׁ יַעֲקֹב וַיָּגֶל אֶת הָאֶבֶן. וַיָּגֶל וְגָלֲלוּ, וְלֹא כָתוּב וַיָּסֵר וְהֵסִירוּ, אֶלָּא (ויגל) וְגָלֲלוּ, הַיְנוּ הָעִרְבּוּב שֶׁל הַשָּׂטָן שֶׁמְּעַרְבְּבִים אוֹתוֹ שֶׁלֹּא יוּכַל לְקַטְרֵג."],[8,"","וְיַעֲקֹב לְבַדּוֹ, לֹא הִצְטָרֵךְ לְסִיּוּעַ אַחֵר, אֶלָּא הוּא לְבַדּוֹ. שֶׁהֲרֵי יַעֲקֹב הָיָה בְּחִיר הָאָבוֹת. שֶׁכֵּיוָן שֶׁיָּכֹל לְעֵשָׂו בָּעוֹלָם הַזֶּה, יָכוֹל לְמַעְלָה, וּבַכֹּל צָרִיךְ מַעֲשֶׂה."],[9,"","שְׁנֵי עוֹלָמוֹת יָרַשׁ יַעֲקֹב - אֶחָד הָעוֹלָם שֶׁנִּגְלָה, וְאֶחָד הָעוֹלָם שֶׁהִתְכַּסָּה, כְּמוֹ שֶׁהֵם מַמָּשׁ. מֵאֶחָד יָצְאוּ שִׁשָּׁה שְׁבָטִים, וּמֵאֶחָד יָצְאוּ שְׁנֵי שְׁבָטִים. הָעוֹלָם הַמְכֻסֶּה הוֹצִיא שִׁשָּׁה צְדָדִים, וְהָעוֹלָם הַמְגֻלֶּה הוֹצִיא שְׁנַיִם, וְאוֹתָם שְׁנֵי הַכְּרוּבִים שֶׁתַּחְתֶּיהָ. וְיַעֲקֹב נִמְצָא בֵּין שְׁנֵי עוֹלָמוֹת, בִּדְמוּתָם מַמָּשׁ, וּמִשּׁוּם כָּךְ כָּל דִּבְרֵי לֵאָה הָיוּ בְּנִכְסֶה, וְשֶׁל רָחֵל בְּהִתְגַּלּוּת."],[10,"","וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה. רַבִּי אֶלְעָזָר אָמַר, כָּתוּב (ישעיה נא) שִׁמְעוּ אֵלַי רֹדְפֵי צֶדֶק. אוֹתָם הַמְבַקְשִׁים סוֹד הָאֱמוּנָה, אוֹתָם שֶׁנִּדְבְּקוּ בְּקֶשֶׁר הָאֱמוּנָה, אוֹתָם שֶׁיּוֹדְעִים דַּרְכֵי הַמֶּלֶךְ הָעֶלְיוֹן (קרבו שמעו)."],[11,"","כְּשֶׁעוֹלִים שְׁנַיִם וְיָצְאוּ לִקְרַאת אֶחָד - מְקַבְּלִים אוֹתוֹ בֵּין שְׁתֵּי זְרוֹעוֹת. שְׁנַיִם יוֹרְדִים לְמַטָּה, שְׁנַיִם הֵם, אֶחָד בֵּינֵיהֶם. שְׁנֵי אֵלֶּה מוֹשַׁב הַנְּבִיאִים, הַמָּקוֹם שֶׁיּוֹנְקִים בּוֹ, אֶחָד בֵּינֵיהֶם, שֶׁהוּא מִתְחַבֵּר בַּכֹּל, הוּא נוֹטֵל הַכֹּל."],[12,"","אוֹתָהּ בְּאֵר קְדוֹשָׁה עוֹמֶדֶת תַּחְתֵּיהֶם, הִיא שְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים. מֵהַבְּאֵר הַזּוֹ מֻשְׁקִים הָעֲדָרִים, כָּל אוֹתָן הַמֶּרְכָּבוֹת, כָּל אוֹתָם בַּעֲלֵי כְנָפַיִם. שְׁלֹשָׁה קַיָּמִים רוֹבְצִים (עומדים) עַל הַבְּאֵר הַזּוֹ. הַבְּאֵר הַזּוֹ מִתְמַלֵּאת מֵהֶם. זֶהוּ שֶׁכָּתוּב כִּי מִן הַבְּאֵר הַהִיא יַשְׁקוּ הָעֲדָרִים וְגוֹ'. זֶה נִקְרָא אדנ\"י, וְעַל זֶה כָּתוּב אֲדֹנָי אֱלֹהִים אַתָּה הַחִלּוֹתָ, וְכָתוּב וְהָאֵר פָּנֶיךְ עַל מִקְדָּשְׁךְ הַשָּׁמֵם לְמַעַן אֲדנָ\"י. אֲדוֹן כָּל הָאָרֶץ. זֶהוּ שֶׁכָּתוּב הִנֵּה אֲרוֹן הַבְּרִית אֲדוֹן כָּל הָאָרֶץ. ע\"כ התוספתא."],[13,"","דָּבָר אַחֵר וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה - רַבִּי אַבָּא פָּתַח וְאָמַר, (תהלים קו) אַשְׁרֵי שֹׁמְרֵי מִשְׁפָּט עֹשֵׂה צְדָקָה בְכָל עֵת. אַשְׁרֵי שֹׁמְרֵי מִשְׁפָּט, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרַת אֱמֶת לְהִשְׁתַּדֵּל בָּהּ יָמִים וְלֵילוֹת, שֶׁהֲרֵי כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, יֵשׁ לוֹ חֵרוּת מֵהַכֹּל, חֵרוּת מִן הַמָּוֶת, שֶׁלֹּא יָכוֹל לִשְׁלֹט עָלָיו, וַהֲרֵי פֵּרְשׁוּהָ, מִשּׁוּם שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וְנֶאֱחָז בָּהּ, נֶאֱחָז בְּעֵץ הַחַיִּים. וְאִם מַרְפֶּה אֶת עַצְמוֹ מֵעֵץ הַחַיִּים, הִנֵּה עֵץ הַמָּוֶת שׁוֹרֶה עָלָיו וְנֶאֱחָז בּוֹ. זֶהוּ שֶׁכָּתוּב (משלי כד) הִתְרַפִּיתָ בְּיוֹם צָרָה צַר כֹּחֶכָה. הִתְרַפִּיתָ - אִם מַרְפֶּה יָדָיו מִן הַתּוֹרָה."],[14,"","בְּיוֹם צָרָה צַר כֹּחֶכָה, מַה זֶּה צַר כֹּחֶכָה? צַר כֹּחַ כֹּה. שֶׁהֲרֵי הִיא תָּמִיד לְיָמִין, וּשְׁמִירָתָהּ תָּמִיד עַל בֶּן אָדָם כַּאֲשֶׁר הוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה, וְאָז דּוֹחֶה אֶת הָרַע הַחוּצָה שֶׁלֹּא יִקְרַב לְבֶן הָאָדָם וְלֹא יוּכַל לְקַטְרֵג לוֹ. וּכְשֶׁאָדָם סוֹטֶה מִדַּרְכֵי הַתּוֹרָה וּמִתְרַפֶּה מִמֶּנָּה, אֲזַי צַר כֹּחַ כֹּה, מִשּׁוּם שֶׁאוֹתוֹ הָרָע, שֶׁהוּא הַשְּׂמֹאל, שׁוֹלֵט עַל הָאָדָם, וְדוֹחֶה אֶת הַ\"כֹּה\" הַזּוֹ הַחוּצָה, עַד שֶׁדּוֹחֵק אוֹתוֹ מָקוֹם בְּצָרָה."],[15,"","דָּבָר אַחֵר צַר כֹּחֶכָה - שֶׁכַּאֲשֶׁר בֶּן אָדָם אוֹחֵז בְּדַרְכֵי הַתּוֹרָה, נֶאֱהָב לְמַעְלָה וְנֶאֱהָב לְמַטָּה, וְהוּא אָהוּב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (שמואל ב יב) וַה' אֲהֵבוֹ, שֶׁהָיָה אָהוּב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאוֹהֵב אוֹתוֹ. וּכְשֶׁאָדָם סוֹטֶה מִדַּרְכֵי הַתּוֹרָה, אֲזַי צַר כֹּחַ כֹּה, צַר שֶׁלּוֹ וּבַעַל שִׂנְאָה הוּא אֵלָיו, וְשׁוֹלֵט עָלָיו אוֹתוֹ שֶׁנִּקְרָא רַע, עַד שֶׁמְּקַטְרֵג בּוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[16,"","בֹּא רְאֵה, הָרָע הַזֶּה, שֶׁהוּא יֵצֶר הָרָע, שׁוֹלֵט עַל הָעוֹלָם בְּכַמָּה צְדָדִים, וְכַמָּה שִׁלְטוֹן יֵשׁ לוֹ בָּעוֹלָם, וְהוּא נָחָשׁ תַּקִּיף שֶׁחָטָא בּוֹ אָדָם, וְנִכְשָׁלִים בּוֹ בְּנֵי הָעוֹלָם וּמוֹשְׁכִים אוֹתוֹ עֲלֵיהֶם, עַד שֶׁמּוֹצִיא לָהֶם אֶת נִשְׁמוֹתֵיהֶם."],[17,"","וּבֹא וּרְאֵה, כְּשֶׁהוּא שׁוֹלֵט, שׁוֹלֵט עַל הַגּוּף. וְכֵיוָן שֶׁשּׁוֹלֵט עַל הַגּוּף, יוֹצֵאת מִמֶּנּוּ הַנְּשָׁמָה, מִשּׁוּם שֶׁהַגּוּף נִטְמָא, וְהַנְּשָׁמָה עוֹלָה, וְאֵין שׁוֹלֵט עָלָיו עַד שֶׁנּוֹטֵל רְשׁוּת. וְכַמָּה הֵם שֶׁבָּאִים מִצִּדּוֹ וְשׁוֹלְטִים עַל הָעוֹלָם, וַהֲרֵי שָׁנִינוּ שֶׁכָּל מַעֲשֵׂי הָעוֹלָם שֶׁנַּעֲשִׂים וְשׁוֹלְטִים בָּהֶם, וְיֵשׁ לוֹ מְמֻנִּים וְשַׁמָּשִׁים, כֻּלָּם שַׁמָּשִׁים בְּמַעֲשֵׂי הָעוֹלָם."],[18,"","וְעַל כֵּן הוּא קֵץ שֶׁל הַשְּׂמֹאל, וַהֲרֵי פֵּרְשׁוּהָ שֶׁיֵּשׁ קֵץ לְיָמִין וְיֵשׁ קֵץ לִשְׂמֹאל, וְהַקֵּץ שֶׁל הַשְּׂמֹאל הַזֶּה הוּא קֵץ כָּל בָּשָׂר. נִקְרָא קֵץ כָּל בָּשָׂר, לֹא נִקְרָא קֵץ כָּל רוּחַ, וְסוֹד הַדָּבָר - זֶהוּ קֵץ (כל בשר) וְזֶהוּ קֵץ. זֶה קֵץ עַל בָּשָׂר, וְזֶה עַל רוּחַ. מִשּׁוּם כָּךְ זֶה פְּנִימִי וְזֶה חִיצוֹנִי, זֶה יָמִין וְזֶה שְׂמֹאל, זֶה קָדוֹשׁ וְזֶה טָמֵא, וְהִנֵּה פֵּרְשׁוּהָ."],[19,"","וּבֹא וּרְאֵה סוֹד עֶלְיוֹן קָדוֹשׁ שֶׁל הָאֱמוּנָה, הַסּוֹד שֶׁל עוֹלַם הַזָּכָר וְעוֹלַם הַנְּקֵבָה, וְכָל קֹדֶשׁ הַקְּדָשִׁים בּוֹ, וְכָל סוֹדוֹת הָאֱמוּנָה מִכָּאן יָצְאוּ, וְכָל הַחַיִּים וְכָל הַחֵרוּת, וְכָל הַטּוֹבוֹת וְכָל הָאוֹרוֹת הֵם מִכָּאן, וְכָל הַבְּרָכוֹת וְטַלְלֵי נְדָבוֹת, וְכָל הָאַהֲבָה שֶׁל הָאֲהָבוֹת הַכֹּל מֵהַצַּד הַזֶּה, סוֹד הַדָּרוֹם."]]],[["מִסִּטְרָא דְצָפוֹן מִתְפַּשְׁטֵי דַרְגִּין, עַד דְּמָטָא לְתַתָּא קַסְטוּפָא דְּדַהֲבָא, בְּסִטְרָא מְסָאֲבָא, לִכְלוּכָא דִמְסָאַב, וְאָחִיד לְהַאי לְעֵילָא וְאָחִיד לְהַאי לְתַתָּא, וְהָכָא מִזְדַּוְוגֵי דְּכַר וְנוּקְבָא כְּחֲדָא, וְאִינוּן רוֹכֵב נָחָשׁ, רָזָא דִּדְכַר וְנוּקְבָא, וְרָזָא דָא עֲזָאזֵ\"ל.","וּמֵהָכָא מִתְפָּרְשִׁין דַּרְגִּין, וְנָפְקִין כַּמָּה סִטְרִין לְעַלְמָא, דְּמִתְפַּשְׁטִין מֵהָכָא, וְשָׁלְטִין עַל עַלְמָא, וְכֻלְּהוּ סִטְרֵי מְסָאֲבָא, וְרַבְרְבִין מְמַנָּן גּוֹ עַלְמָא. תָּא חֲזֵי, עֵשָׂו כַּד נָפַק לְעַלְמָא, כּוּלֵיהּ סוּמְקָא כְּוַרְדָא, בְּשַׂעֲרָא כְּגַוְונָא דְּשָׂעִיר, וּמִתַּמָּן אַלּוּפִין מְמַנָּן תְּרֵיסִין (ס\"א תריסר) דְּשָׁלְטִין בְּעַלְמָא, וְהָא אוּקְמוּהָ.","תָּא חֲזֵי, (תהילים ק״ו:ג׳) אַשְׁרֵי שֹׁמְרֵי מִשְׁפָּט, דְּנָטְרֵי מְהֵימְנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא, אִיהוּ מִשְׁפָּט. וּבָעֵי לֵיהּ לְבַר נָשׁ לְנַטְרָא דְּלָא יִסְטֵי לְאוֹרְחָא אָחֳרָא, אֶלָּא דִּיהֵא נָטִיר מִשְׁפָּט, בְּגִין דְקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ מִשְׁפָּט, דְּכָל אָרְחוֹי מִשְׁפָּט.","(תהילים ק״ו:ג׳) עוֹשֵׂה צְדָקָה בְּכָל עֵת, וְכִי בְּכָל עֵת יָכִיל בַּר נָשׁ לְמֶעְבַּד צְדָקָה. אֶלָּא, מַאן דְּיִשְׁתָּדַּל בְּאוֹרְחוֹי דְאוֹרַיְיתָא, וְעָבִיד צְדָקָה עִם אִינוּן דְּאִצְטְרִיכוּ לָהּ, דְּכָל מַאן דְּעָבִיד צְדָקָה עִם מִסְכֵּנָא, אַסְגֵי הַהִיא צְדָקָה לְעֵילָא וְתַתָּא.","תָּא חֲזֵי, מַאן דְּאִשְׁתַּדַּל בִּצְדָקָה, הַהִיא צְדָקָה דְּעָבִיד, סָלִיק לְעֵילָא, וּמָטָא לְעֵילָא לְהַהוּא אַתְרָא דְיַעֲקֹב, דְּאִיהוּ רְתִיכָא עִלָּאָה. וְאַמְשִׁיךְ בִּרְכָאן לְהַהוּא אֲתַר, מִמַּבּוּעָא דְכָל מַבּוּעִין. וּמֵהַהִיא צְדָקָה, אַמְשִׁיךְ וְאַרְבֵּי בִּרְכָאן לְכָל אִינוּן תַּתָּאֵי, וּלְכָל רְתִיכִין וּלְכָל חֵילִין, וְכֻלְּהוּ אִתְבָּרְכָאן וְאִתּוֹסְפָן נְהוֹרִין, כְּדְקָא יְאוּת. בְּגִין דְּכֻלְּהוּ אִקְרוּ עֵת, וְדָא הוּא דִכְתִיב, עוֹשֵׂה צְדָקָה בְּכָל עֵת.","תָּא חֲזֵי, בְּזִמְנָא דְּהֲווּ יִשְׂרָאֵל בְּאַרְעָא קַדִּישָׁא, אִינוּן הֲווּ מָשְׁכֵי בִּרְכָאן מִלְּעֵילָא לְתַתָּא, וְכַד נָפְקוּ יִשְׂרָאֵל מֵאַרְעָא קַדִּישָׁא, עָאלוּ תְּחוֹת רְשׁוּ אָחֳרָא, וּבִרְכָאן אִתְמְנָעוּ מֵעָלְמָא.","תָּא חֲזֵי, יַעֲקֹב הֲוָה תְּחוֹת רְשׁוּ קַדִּישָׁא, כֵּיוָן דְנָפַק מֵאַרְעָא, עָאל בִּרְשׁוּ אָחֳרָא, וְעַד לָא עָאל תְּחוֹת רְשׁוּ אָחֳרָא, אִתְגְּלִי עֲלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּחֶלְמָא, וְחָמָא כָּל מַה דְּחָמָא, וְאֲזְלוּ עִמֵּיהּ מַלְאָכִין קַדִּישִׁין, עַד דְּיָתִיב עַל בֵּירָא. וְכֵיוָן דְּיָתִיב עַל בֵּירָא, סְלִיקוּ מַיָא לְגַבֵּיהּ, וְכֵן הֲוָה משֶׁה, דְּמִתַּמָּן אִזְדַּמְּנַת לֵיהּ אִתְּתֵיהּ. רָזָא דְמִלָּה, בֵּירָא לָא סָלְקָא, אֶלָּא כַּד חָמָא קִשְׁרָא דִילֵיהּ לְאִתְחַבְּרָא בַּהֲדֵיהּ.","וְאָמַר רִבִּי אַבָּא, כָּל הָנֵי קְרָאֵי קַשְׁיָין אַהֲדָדֵי, בְּקַדְמִיתָא כְּתִיב, (בראשית כ״ח:י׳) וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה, וְלָבָן בְּחָרָן הֲוָה יָתִיב, אַמַּאי נָטִיל מִתַּמָּן, דִּכְתִיב (בראשית כ״ט:א׳) וַיִּשָּׂא יַעֲקֹב רַגְלָיו וַיֵּלֶךְ אַרְצָה בְּנֵי קֶדֶם. וּמִנָּלָן דִּבְחָרָן הֲוָה דִיּוּרֵיהּ דְּלָבָן, דִּכְתִיב, (בראשית כ״ט:ד׳-ה׳) וַיֹּאמֶר לָהֶם יַעֲקֹב אַחַי מֵאַיִן אַתֶּם וַיֹּאמְרוּ מֵחָרָן אֲנָחְנוּ. וַיֹּאמֶר הַיְדַעְתֶּם אֶת לָבָן בֶּן נָחוֹר וַיֹּאמְרוּ יָדָעְנוּ. מַשְׁמַע דְּדִיּוּרֵיהּ דְּלָבָן, בְּחָרָן הֲוָה.","אֶלָּא, יַעֲקֹב אָמַר, אֲנָא בָּעִינָא לְמֵיעַל בִּשְׁכִינְתָּא, בְּגִין דִּבְעִינָא לְאִזְדַּוְּוגָא. אַבָּא כַּד אִתְנָסִיב וְשָׁדַר לְעַבְדָא, אַשְׁכַּח עֵינָא דְמַיָא, וּכְדֵין אִזְדַּמְּנַת לֵיהּ לְאַבָּא אִתְּתָא. וְהָא בְּאֲתַר דָּא, לָא אַשְׁכַּחְנָא לָא עֵינָא וְלָא בֵּירָא וְלָא מַיָּא, וּמִיָּד וַיִּשָּׂא יַעֲקֹב רַגְלָיו וַיֵּלֶךְ אַרְצָה בְּנִי קֶדֶם, וְתַמָּן אִזְדַּמְּנַת לֵיהּ בֵּירָא, כִּדְקָאֲמָרָן, וְאִזְדַּמְּנַת לֵיהּ אִתְּתֵיהּ.","רִבִּי אֶלְעָזָר אָמַר, חָרָן תַּמָּן הֲוָה וַדַּאי, וְהַאי בֵּירָא בְּחַקְלָא הֲוָה. דְּאִי לָאו הָכִי, אַמַּאי כְּתִיב, (בראשית כ״ט:י״ב) וַתָּרָץ וַתַּגֵּד לְאָבִיהָ, אֶלָּא בְּגִין דְּהֲוָה סָמִיךְ לְמָתָא.","וְאָמַר רִבִּי אֶלְעָזָר, יַעֲקֹב דְּאִזְדַּמְּנַת לֵיהּ עַל בֵּירָא אִתְּתָא, אַמַּאי לָא אִזְדַּמְּנַת לֵיהּ לֵאָה, דְּהָא קָיְימָא לֵיהּ לְיַעֲקֹב כָּל אִינוּן שִׁבְטִין. אֶלָּא לֵאָה, לָא בָעָא קוּדְשָׁא בְּרִיךְ הוּא לְזַוְוגָא לֵיהּ לְיַעֲקֹב בְּאִתְגַּלְּיָא, דִּכְתִיב, (בראשית כ״ט:כ״ה) וַיְהִי בַבֹּקֶר וְהִנֵּה הִיא לֵאָה, (מכלל) דְּהָא קוֹדֶם לָכֵן לָא אִתְגַּלְּיָא מִלָּה.","וְתוּ, בְּגִין לְאַמְשָׁכָא עֵינָא וְלִבָּא דְיַעֲקֹב בְּשַׁפִּירוּ דְּרָחֵל, לְמֶעְבַּד דִּיּוּרֵיהּ תַּמָּן, וּבְגִינָהּ אִזְדַּוְּוגַת לֵיהּ לֵאָה, וְאוֹקִימַת כָּל אִינוּן שִׁבְטִין. בַּמֶּה יָדַע יַעֲקֹב מַאן הִיא רָחֵל. אֶלָּא דְּאִינוּן רַעְיָין אָמְרוּ לֵיהּ, דִּכְתִיב, (בראשית כ״ט:ו׳) וְהִנֵּה רָחֵל בִּתּוֹ בָּאָה עִם הַצֹּאן."],[[0,"מסטרא דצפון וכו':","מצד צפון מתפשטות המדרגות עד שמגיעה למטה, לבי\"ע, פסולת הזהב, (כמו שנתבאר לעיל וירא דף צ\"ז אות שכ\"ט בהסולם) בצד הטמא, טנופת הטמאה, אוחזת לזה של מעלה, שהוא הזכר, אוחזת לזה שלמטה שהיא הנקבה, וכאן מזדווגים זכר ונקבה יחד. והם, רוכב על נחש, ונחש, שה\"ס דכר ונוקבא, (כנ\"ל אות כ\"ג) וזה סוד עזאזל, שהוא כולל דכר ונוקבא דטומאה."],[1,"ומהכא מתפרשין וכו':","ומכאן המדרגות מתחלקות, וכמה בחינות יוצאות לעולם, המתפשטות מכאן ושולטות על העולם, והן כולן בחינות הטומאה, ושרים הממונים על העולם. בוא וראה. עשו כשיצא לעולם, היה כולו אדום כמו ורד שצבע אדום רומז על השמאל, ובשערות כמו שעיר, שהוא מטומאה, כמ\"ש ושעירים ירקדו שם, ומשם אלופים ממונים התקיפים, השולטים בעולם. וכבר בארוהו."],[2,"תא חזי. אשרי שומרי משפט:","היינו השומרים אמונתו של הקב\"ה, כי הקב\"ה נקרא משפט, וצריך האדם לשמור עצמו שלא יסור לדרך אחר אלא שיהיה שומר משפט משום שהקב\"ה הוא משפט, שכל דרכיו משפט."],[2,"","פירוש. השם \u0003משפט,\u0004 יורה, על הכרעת דברים, הבאה אחר שמיעת ב' צדדים ההפכים זה לזה. כמו שופט, אחר ששמע היטב כל הטענות של שני הצדדים המריבים, הוא נותן את הכרעתו, ואומר פלוני אתה זכאי, ופלוני אתה חייב. והכרעה זו נקרא \u0003משפט.\u0004 וז\"ס \u0003קו האמצעי,\u0004 שהוא מכריע בין שני הקוין ימין ושמאל, ההפכים זה לזה, באופן, שיאירו שניהם לצד הקדושה. ועל שם הכרעתו זו, הוא נקרא, משפט."],[2,"","ולפיכך, כדי לבאר לנו היטב סו\"ה אשרי שומרי משפט, מאריך הזהר ומביא בקצור, את הדרכים והתוצאות מב' הצדדים ההפכים זה לזה, שהם, צד הימין, וצד השמאל, דהיינו מעלת העוסק בתורה מבחינת עץ החיים שבה, שהוא כולו ימין, (באות ק\"ט) ולעומתו המתרפה בתורה ונופל לאילנא דמותא שהוא כולו שמאל. וכן ענין קץ לימינא ולעומתו קץ דשמאלא (באות קי\"ד) וכן התוצאות מסטרא דדרום (באות קט\"ו) ולעומתם מסטרא דצפון, (באות קט\"ז) ואחר שידענו כל זה, מבאר הכתוב ואומר ת\"ח \u0003אשרי שומרי משפט דנטרי מהימנותא דקב\"ה.\u0004 הנוקבא נקראת מהימנותא. מהימנותא דקב\"ה, פירושו, יחוד קב\"ה ושכינתיה, שאז בשעת היחוד נקרא הקב\"ה \u0003משפט.\u0004 וז\"ש \u0003דנטרי מהימנותא דקב\"ה בגין דקב\"ה איהו משפט,\u0004 דהיינו בעת היחוד עם השכינה. כי הקב\"ה הוא ימין, והשכינה ה\"ס שמאל, וזווגם יחד ה\"ס \u0003משפט.\u0004 ושלא בשעת היחוד, אע\"פ שהוא סוד \u0003עץ החיים,\u0004 עכ\"ז אינו עוד שלמות הנרצה, ואינו נקרא אז משפט, להיותו נוטה לימין. שע\"כ נגרש אדם מג\"ע, כמ\"ש, פן ישלח ידו ולקח מעץ החיים ואכל וחי לעולם. והרצון היה שיעלה מ\"ן ליחד קב\"ה ושכינתיה, בסוד \u0003שומר משפט,\u0004 שהוא הכרעה ותוצאה מב' הקוין ביחד, ואינו נוטה לא לימין ולא לשמאל. וז\"ש, \u0003אלא דיהא נטיר משפט, בגין דקב\"ה איהו משפט, דכל אורחוי משפט.\u0004 שהקב\"ה בזווג עם השכינה נק' משפט, כי אז כל דרכיו משפט, דהיינו בדרך אמצעי הכולל בתוכו את הימין והשמאל ביחד, ואינו נוטה לא לימין ולא לשמאל."],[3,"עושה צדקה בכל עת:","שואל, וכי בכל עת יכול האדם לעשות צדקה. ומשיב, אלא מי שהולך בדרכי התורה ועושה צדקה עם אלו הצריכים צדקה, נבחן לעושה צדקה בכל עת, כי כל מי שעושה צדקה עם העני, הוא מרבה צדקה ההיא, דהיינו הנוקבא, הנק' צדקה, למעלה ולמטה. שגורם זווג זו\"ן למעלה, ושפע ברכות למטה. (עי' לעיל פרשת לך דף א' ד\"ה פירוש)."],[4,"ת\"ח מאן וכו':","בוא וראה. מי שמשתדל בצדקה, אותה צדקה שעושה, עולה למעלה, ומגעת למעלה לאותו המקום של יעקב, שהוא מרכבה עליונה, דהיינו הנוקבא הנקראת מקום, וממשיך ברכות למקום ההוא, מן המעיין של כל המעיינות, דהיינו מבינה שכל המוחין ממנה הם. ומההוא צדקה, דהיינו הנוקבא אחר שקבלה הברכות מבינה, ממשיך ומרבה הברכות לכל התחתונים ולכל המרכבות של המלאכים, ולכל צבאות העליונים. וכולם מתברכים, והאורות נתוספים כראוי. ומשום שכולם דהיינו כל התחתונים והמלאכים הנ\"ל, נקראים \u0003עת,\u0004 להיותם נמשכים מן הנוקבא שנקראת \u0003עת,\u0004 על כן כתוב, \u0003עושה צדקה בכל עת.\u0004 שפירושו, שמרבה השפע בכל דרי ג' עולמות בי\"ע, המתפשטים מן הנוקבא, ונקראים \u0003עת\u0004 כמו הנוקבא."],[5,"ת\"ח בזמנא וכו':","בוא וראה. בזמן שהיו ישראל בארץ הקדושה, היו מושכים ברכות ממעלה למטה. וכשיצאו ישראל מארץ הקדושה, באו תחת רשות אחר, ונמנעו הברכות מן העולם."],[6,"ת\"ח, יעקב וכו':","בוא וראה, יעקב היה תחת רשות הקדושה, בארץ ישראל, כיון שיצא מן הארץ, בא ברשות אחר, שאינו קדוש."],[6,"ועד לא עאל וכו':","ומטרם שבא תחת רשות אחר, נגלה עליו הקב\"ה בחלום. וראה כל מה שראה, והלכו עמו מלאכים הקדושים, עד שישב על הבאר. וכיון שישב על הבאר, עלו המים לקראתו, וכן היה אצל משה, כי משם נזדמנה לו אשתו. סוד הדבר של עלית המים, הוא, הבאר, אינה עולה, אלא בעת שרואה את הקשר שלה, דהיינו בן זוג, להתחבר עמו. פירוש. הבאר רומזת על הנוקבא דז\"א, ומשה וכן יעקב היו מרכבה לז\"א, וע\"כ עלו המים לקראתם, כמו נוקבא לקראת בן זוגה."],[7,"ואמר רבי אבא וכו':","ואר\"א, כל אלו המקראות סותרים זה את זה. בתחילה כתוב, ויצא יעקב מבאר שבע וילך חרנה, ולבן בחרן היה יושב, ואם כן, למה נסע משם, שכתוב, וישא יעקב רגליו וילך ארצה בני קדם. ומאין לנו, שמושבו של לבן בחרן היה, כי כתוב, ויאמר להם יעקב אחי מאין אתם ויאמרו מחרן אנחנו, ויאמר הידעתם את לבן בן נחור ויאמרו ידענו. ומשמע שמושבו של לבן היה בחרן, וא\"כ למה הלך ארצה בני קדם."],[8,"אלא יעקב אמר וכו':","אלא יעקב אמר אני רוצה להתחבר עם השכינה, שה\"ס הבאר, משום שאני רוצה לישא אשה. אבי, כשעמד לישא אשה, ושלח את העבד, מצא העבד מעין המים, ואז נזדמנה אשה לאבי, והרי במקום הזה, בחרן, לא מצאתי, לא מעין, לא בור, לא מים. ומיד, וישא יעקב רגליו וילך ארצה בני קדם, ושם נזדמן לו הבאר, ונזדמן לו אשה, כמו שאמרנו."],[9,"רבי אלעזר אמר וכו':","רא\"א, חרן, שם היה יעקב ודאי, כי הוא ארץ הקדם, ובאר זו בשדה של חרן היתה, ואם אינו כן, למה כתוב ותרץ ותגד לאביה. אלא, משום שהיה סמוך לעיר."],[10,"ואמר רבי אלעזר וכו':","ואר\"א, יעקב, שאשה נזדמנה לו על הבאר. למה לא נזדמנה לו לאה, הרי היא העמידה ליעקב כל אלו השבטים. ומשיב, אלא, לאה, לא רצה הקב\"ה לזווג אותה עם יעקב בגלוי, שכתוב, ויהי בבקר והנה היא לאה, אבל מקודם לכן לא נגלה דבר. שזה היה רצון הקב\"ה."],[11,"ותו, בגין לאמשכא עינא ולבא וכו':","ועוד, משום זה, לא נגלה לאה אלא רחל, כדי להמשיך עינו ולבו של יעקב ביפיה של רחל, ויקבע דירתו שם, ובשבילה נזדווגה לו גם לאה והעמידה כל אלו השבטים. ושואל, במה ידע יעקב מי היא רחל, הלא לא הכירה. ומשיב, אלא שהרועים אמרו לו, שכתוב, והנה רחל בתו באה עם הצאן."]],[[0,"","מִצַד הַצָּפוֹן מִתְפַּשְּׁטוֹת דְּרָגוֹת עַד שֶׁמַּגִּיעָה לְמַטָּה פְּסֹלֶת הַזָּהָב, בְּצַד הַטֻּמְאָה, לִכְלוּךְ טָמֵא, וְאוֹחֵז אֶת זֶה לְמַעְלָה, וְאוֹחֵז אֶת זֶה לְמַטָּה. וְכָאן מִזְדַּוְּגִים זָכָר וּנְקֵבָה יַחַד, וְהֵם רוֹכֵב נָחָשׁ, הַסּוֹד שֶׁל זָכָר וּנְקֵבָה, וְזֶה סוֹד עֲזָאזֵ \"ל."],[1,"","וּמִכָּאן נִפְרָדוֹת הַדְּרָגוֹת וְיוֹצְאִים כַּמָּה צְדָדִים לָעוֹלָם, שֶׁמִּתְפַּשְּׁטִים מִכָּאן וְשׁוֹלְטִים עַל הָעוֹלָם, וְכֻלָּם צִדְדֵי הַטֻּמְאָה, וּמְמֻנִּים שָׂרִים לְתוֹךְ הָעוֹלָם. בֹּא רְאֵה, כְּשֶׁיָּצָא עֵשָׂו לָעוֹלָם, כֻּלּוֹ אָדם כַּשּׁוֹשַׁנָּה בַּשֵּׂעָר כְּמוֹ הַשָּׂעִיר, וּמִשָּׁם אַלּוּפִים, מָגִנִּים מְמֻנִּים (שנים עשר) שֶׁשּׁוֹלְטִים בָּעוֹלָם, וְהִנֵּה פֵּרְשׁוּהָ."],[2,"","בֹּא רְאֵה, אַשְׁרֵי שֹׁמְרֵי מִשְׁפָּט - שֶׁשּׁוֹמְרִים הָאֱמוּנָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוּא מִשְׁפָּט, וְצָרִיךְ לָאָדָם לִשְׁמֹר שֶׁלֹּא יִסְטֶה לְדֶרֶךְ אַחֶרֶת, אֶלָּא שֶׁיִּהְיֶה שׁוֹמֵר מִשְׁפָּט, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוּא מִשְׁפָּט, שֶׁכָּל דְּרָכָיו מִשְׁפָּט."],[3,"","עֹשֵׂה צְדָקָה בְכָל עֵת - וְכִי בְכָל עֵת יָכוֹל אָדָם לַעֲשׂוֹת צְדָקָה? אֶלָּא מִי שֶׁמִּשְׁתַּדֵּל בְּדַרְכֵי הַתּוֹרָה וְעוֹשֶׂה צְדָקָה עִם אוֹתָם שֶׁצְּרִיכִים אוֹתָהּ. שֶׁכָּל מִי שֶׁעוֹשֶׂה צְדָקָה עִם הֶעָנִי, מַרְבֶּה אוֹתָהּ צְדָקָה לְמַעְלָה וּלְמַטָּה."],[4,"","בֹּא רְאֵה, מִי שֶׁמִּשְׁתַּדֵּל בִּצְדָקָה, אוֹתָהּ צְדָקָה שֶׁעוֹשֶׂה עוֹלָה לְמַעְלָה וּמַגִּיעָה לְמַעְלָה לְאוֹתוֹ הַמָּקוֹם שֶׁל יַעֲקֹב, שֶׁהוּא מֶרְכָּבָה עֶלְיוֹנָה, וּמַמְשִׁיךְ בְּרָכוֹת לַמָּקוֹם הַהוּא מִן הַמַּעְיָן שֶׁל כָּל הַמַּעְיָנוֹת. וּמֵאוֹתָהּ הַצְּדָקָה מַמְשִׁיךְ וּמַרְבֶּה בְּרָכוֹת לְכָל אוֹתָם הַתַּחְתּוֹנִים וּלְכָל הַמֶּרְכָּבוֹת וּלְכָל הַחֲיָלוֹת, וְכֻלָּם מִתְבָּרְכִים, וְנוֹסָפִים אוֹרוֹת כָּרָאוּי, מִשּׁוּם שֶׁכֻּלָּם נִקְרְאוּ עֵת, וְזֶהוּ שֶׁכָּתוּב עֹשֵׂה צְדָקָה בְכָל עֵת."],[5,"","בֹּא רְאֵה, בִּזְמַן שֶׁהָיוּ יִשְׂרָאֵל בָּאָרֶץ הַקְּדוֹשָׁה, הֵם הָיוּ מוֹשְׁכִים בְּרָכוֹת מִמַּעְלָה לְמַטָּה. וּכְשֶׁיָּצְאוּ יִשְׂרָאֵל מִן הָאָרֶץ הַקְּדוֹשָׁה, נִכְנְסוּ תַּחַת רְשׁוּת אַחֶרֶת, וְנִמְנְעוּ הַבְּרָכוֹת מִן הָעוֹלָם."],[6,"","בֹּא רְאֵה, יַעֲקֹב הָיָה תַּחַת רְשׁוּת קְדוֹשָׁה. כֵּיוָן שֶׁיָּצָא מִן הָאָרֶץ, נִכְנַס לִרְשׁוּת אַחֶרֶת. וְטֶרֶם שֶׁנִּכְנַס תַּחַת רְשׁוּת אַחֶרֶת, הִתְגַּלָּה עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא בַּחֲלוֹם וְרָאָה כָּל מַה שֶּׁרָאָה, וְהָלְכוּ עִמּוֹ מַלְאָכִים קְדוֹשִׁים, עַד שֶׁיָּשַׁב עַל הַבְּאֵר. וְכֵיוָן שֶׁיָּשַׁב עַל הַבְּאֵר עָלוּ אֵלָיו הַמַּיִם, וְכֵן הָיָה מֹשֶׁה, שֶׁמִּשָּׁם הִזְדַּמְּנָה לוֹ אִשְׁתּוֹ. סוֹד הַדָּבָר - הַבְּאֵר לֹא עוֹלָה אֶלָּא כְּשֶׁרוֹאָה אֶת הַקֶּשֶׁר שֶׁלָּהּ לְהִתְחַבֵּר עִמּוֹ."],[7,"","וְאָמַר רַבִּי אַבָּא, כָּל הַפְּסוּקִים הַלָּלוּ קָשִׁים זֶה עַל זֶה. בָּרִאשׁוֹנָה כָּתוּב וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה. וְלָבָן הָיָה יוֹשֵׁב בְּחָרָן. לָמָּה נָסַע מִשָּׁם? שֶׁכָּתוּב וַיִּשָּׂא יַעֲקֹב רַגְלָיו וַיֵּלֶךְ אַרְצָה בְּנֵי קֶדֶם. וּמִנַּיִן לָנוּ שֶׁבְּחָרָן הָיָה דִיּוּרוֹ שֶׁל לָבָן? שֶׁכָּתוּב וַיֹּאמֶר לָהֶם יַעֲקֹב אַחַי מֵאַיִן אַתֶּם וַיֹּאמְרוּ מֵחָרָן אֲנָחְנוּ. וַיֹּאמֶר הַיְדַעְתֶּם אֶת לָבָן בֶּן נָחוֹר וַיֹּאמְרוּ יָדָעְנוּ. מַשְׁמָע שֶׁדִּיּוּרוֹ שֶׁל לָבָן הָיָה בְחָרָן."],[8,"","אֶלָּא יַעֲקֹב אָמַר, אֲנִי רוֹצֶה לְהִכָּנֵס בַּשְּׁכִינָה מִשּׁוּם שֶׁאֲנִי רוֹצֶה לְהִתְחַתֵּן. כְּשֶׁאַבָּא נִשָּׂא וְשָׁלַח אֶת הָעֶבֶד, מָצָא עֵין הַמַּיִם, וְאָז הִזְדַּמְּנָה לְאַבָּא אִשָּׁה, וְהִנֵּה בַּמָּקוֹם הַזֶּה לֹא מָצָאתִי לֹא עַיִן וְלֹא בְּאֵר וְלֹא מַיִם, וּמִיָּד - וַיִּשָּׂא יַעֲקֹב רַגְלָיו וַיֵּלֶךְ אַרְצָה בְּנֵי קֶדֶם, וְשָׁם הִזְדַּמְּנָה לוֹ בְּאֵר, כְּמוֹ שֶׁאָמַרְנוּ, וְהִזְדַּמְּנָה לוֹ אִשְׁתּוֹ."],[9,"","רַבִּי אֶלְעָזָר אָמַר, חָרָן, שָׁם הָיָה וַדַּאי, וְהַבְּאֵר הַזּוֹ הָיְתָה בַּשָּׂדֶה. שֶׁאִם לֹא כָּךְ, לָמָּה כָּתוּב וַתָּרָץ וַתַּגֵּד לְאָבִיהָ? אֶלָּא מִשּׁוּם שֶׁהָיָה סָמוּךְ לָעִיר."],[10,"","וְאָמַר רַבִּי אֶלְעָזָר, יַעֲקֹב שֶׁהִזְדַּמְּנָה לוֹ אִשָּׁה עַל הַבְּאֵר, לָמָּה לֹא הִזְדַּמְּנָה לוֹ לֵאָה, שֶׁהֲרֵי הֶעֱמִידָה לוֹ לְיַעֲקֹב כָּל אוֹתָם הַשְּׁבָטִים? אֶלָּא שֶׁאֶת לֵאָה לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְזַוְּגָהּ עִם יַעֲקֹב בְּגָלוּי, שֶׁכָּתוּב וַיְהִי בַבֹּקֶר וְהִנֵּה הִיא לֵאָה. (מכלל) שֶׁהֲרֵי קֹדֶם לֹא הִתְגַּלָּה הַדָּבָר."],[11,"","וְעוֹד, כְּדֵי לִמְשֹׁךְ אֶת עֵינוֹ וְלִבּוֹ שֶׁל יַעֲקֹב בַּיֹּפִי שֶׁל רָחֵל, לַעֲשׂוֹת שָׁם אֶת דִּיּוּרוֹ, וּבִשְׁבִילָהּ הִזְדַּוְּגָה לוֹ לֵאָה וְהֵקִימָה אֶת כָּל אוֹתָם הַשְּׁבָטִים. בַּמֶּה יָדַע יַעֲקֹב מִי הִיא רָחֵל? אֶלָּא שֶׁאוֹתָם הָרוֹעִים אָמְרוּ לוֹ, שֶׁכָּתוּב וְהִנֵּה רָחֵל בִּתּוֹ בָּאָה עִם הַצֹּאן."]]],[["תָּא חֲזֵי מַה כְּתִיב, וַיֹּאמֶר (בראשית כ״ט:י״ח) אֶעֱבָדְךָ שֶׁבַע שָׁנִים בְּרָחֵל בִּתְּךָ הַקְּטַנָּה, וְכִי מַה דַּעְתֵּיהּ דְּיַעֲקֹב דְּלָא קָאֲמַר עֶשֶׂר יַרְחִין אוֹ שַׁתָּא חָדָא, אֶלָּא שֶׁבַע שָׁנִים אַמַּאי. אֶלָּא יַעֲקֹב בְּחָכְמָתָא עֲבַד. בְּגִין דְּלָא יֵימְרוּן, דִּבְגִין תִּיאוּבְתָּא דְּשַׁפִּירוּ דְרָחֵל עֲבַד, אֶלָּא בְּגִין חָכְמְתָא, דְּסִיהֲרָא בַּת שֶׁבַע שְׁנִין הִיא. וְכֻלְּהוּ שֶׁבַע שְׁנִין עִלָּאִין, שָׁרוּ עֲלֵיהּ דְּיַעֲקֹב עַד לָא נָסִיב לָהּ לְרָחֵל לְמֵיתַב גַּבָּהּ כְּדְקָא יְאוּת. דְּהָא יַעֲקֹב נָטַל כֻּלְּהוּ בְּקַדְמִיתָא, וּלְבָתַר אֲתָא לְגַבָּהּ, בְּגִין לְאִשְׁתַּכָּחָא אִיהוּ שָׁמַיִם, וְאִיהִי אָרֶץ.","וְרָזָא דְמִלָּה, וַיִּהְיוּ בְּעֵינָיו כְּיָמִים אֲחָדִים, מַאי כְּיָמִים אֲחָדִים, אֶלָּא, כֻּלְּהוּ שֶׁבַע שְׁנִין שָׁקִיל לוֹן בְּעֵינוֹי, כְּאִינוּן עִלָּאִין. דְּאִינוּן אֲחָדִין דְּלָא מִתְפָּרְשָׁאן, (צ\"ה ע\"ב) וְכֻלְּהוּ חַד, דְּמִתְקַשְּׁרָן דָּא בְּדָא. בְּאַהֲבָתוֹ אוֹתָהּ, לְאִשְׁתַּכָּחָא כְּגַוְונָא עִלָּאָה.","תָּא חֲזֵי, דְּאָפִילּוּ לָבָן רָמַז לֵיהּ בְּאִינוּן שֶׁבַע, וְלָא יָדַע מַאי קָאֲמַר, דְּפָתַח וְאָמַר טוֹב, דִּכְתִיב, (בראשית כ״ט:י״ט) טוֹב תִּתִּי וְגו'. אָמַר רִבִּי אַבָּא, הָכִי הוּא וַדַּאי, פָּלַח שֶׁבַע שְׁנִין, לְאִזְדַּוְּוגָא בִּשְׁמִטָּה. אָמַר רִבִּי אֶלְעָזָר, תָּא חֲזֵי, בְּכָל אֲתַר יוֹבְלָא סָתִים דְּלָא אִתְגַּלְּיָא וּשְׁמִטָּה אִתְגַּלְּיָא.","תָּא חֲזֵי, בְּשַׁעְתָּא דְּיַעֲקֹב פָּלַח שֶׁבַע שְׁנִין קַדְמָאִין, נָפְקָא קָלָא וְאָמַר, יַעֲקֹב, (תהילים ק״ו:מ״ח) מִן הָעוֹלָם וְעַד הָעוֹלָם כְּתִיב, עוֹלָם סָתִים דִּלְעֵילָא יוֹבְלָא מִתַּמָּן שֵׁירוּתָא. דְּאִלֵּין דְּאִינוּן סְתִימִין, דְּלָא אִתְגַּלְּיָא לוֹן מִן יוֹבְלָא אִינוּן. בְּגִין כָּךְ אִסְתִּימוּ מִיַּעֲקֹב, דְּלָא יָדַע, דְּחָשַׁב דְּהָא מִן שְׁמִטָּה אִינוּן. וּבְגִין דְּיַעֲבִיד שֵׁירוּתָא מֵעוֹלָם דִּלְעֵילָא, אִתְכַּסְיָין מִנֵּיהּ, בְּגִין דְּיוֹבְלָא אִיהוּ סָתִים, וּלְבָתַר דַּעֲבָרוּ שְׁנֵי יוֹבְלָא דְּאִתְכַּסְיָיא, עֲבַד שְׁנֵי שְׁמִטָּה דְאִתְגַּלְיָין, (פקודי רנ\"ו ע\"ב) וְאִתְעַטַּר בִּתְרֵין עָלְמִין וְאָחִיד לוֹן.","תָּא חֲזֵי, לֵאָה אוֹלִידַת שִׁית בְּנִין וּבְרַתָּא חָדָא. וְהָכִי אִתְחֲזֵי, דְּהָא שִׁית סִטְרִין קָיְימִין עֲלָהּ וְאִלֵּין שִׁית, וּבְרַתָּא חָדָא, בְּרָזָא עִלָּאָה נָפְקָא.","רָחֵל אוֹלִידַת תְּרֵין צַדִּיקִים. וְהָכִי אִתְחֲזֵי, הָא שְׁמִטָּה, דְּבֵין תְּרֵי צַדִּיקֵי יָתְבָא לְעָלְמִין, דִּכְתִיב, (תהילים ל״ז:כ״ט) צַדִּיקִים יִירְשׁוּ אָרֶץ, צַדִּיק לְעֵילָא וְצַדִּיק לְתַתָּא. צַדִּיק לְעֵילָא, מִנֵּיהּ נָגְדָן מַיִין עִלָּאִין. צַדִּיק לְתַתָּא, מִנֵּיהּ נָבְעָא נוּקְבָא מַיָא לְגַבֵּי דְכוּרָא, בְּתִיאוּבְתָּא שְׁלִים. צַדִּיק מִסִּטְרָא דָא, וְצַדִּיק מִסִּטְרָא דָא, כְּמָא דִּדְכוּרָא לְעֵילָא יָתִיב בֵּין תְּרֵי נוּקְבֵי, הָכִי נָמֵי נוּקְבָא לְתַתָּא יָתְבָא בֵּין תְּרֵי צַדִּיקִי.","וְעַל דָּא, יוֹסֵף וּבִנְיָמִין תְּרֵין צַדִּיקִין נִינְהוּ. יוֹסֵף זָכָה לְמֶהוֵי צַדִּיק לְעֵילָא, בְּגִין דְּנָטַר אָת קַיָּימָא. בִּנְיָמִין אִיהוּ צַדִּיק לְתַתָּא, לְאִתְעַטְּרָא שְׁמִטָּה בֵּין תְּרֵי צַדִּיקֵי, יוֹסֵף הַצַּדִּיק, וּבִנְיָמִין הַצַּדִּיק.","וְכִי בִּנְיָמִין צַדִּיק הֲוָה, אִין. דְּכָל יוֹמוֹי לָא חָטָא בְּהַאי אָת קַיָּימָא, וְאַף עַל גַּב דְּלָא אִזְדַּמַּן לֵיהּ עוֹבָדָא כְּיוֹסֵף. אִי הָכִי, אַמַּאי אִקְרֵי צַדִּיק. אֶלָּא כָּל יוֹמוֹי דְיַעֲקֹב הֲוָה בְּאֶבְלָא דְיוֹסֵף, לָא שִׁמֵּשׁ עַרְסֵיהּ. וְאִי תֵימָא דְּכַד אִתְנְטִיל יוֹסֵף מִיַּעֲקֹב, רַבְיָא הֲוָה וְלָא נְסִיב. וְאַתְּ אֲמַרְתְּ דְּלָא שִׁמֵּשׁ עַרְסֵיהּ, אֶלָּא אַף עַל גַּב דְּאִזְדַּוַּוג לְבָתַר לָא בָעָא לְשַׁמְּשָׁא עַרְסֵיהּ.","וְאֲנַן הָכִי תְּנַן, בְּשָׁעָה דְּשָׁאִיל יוֹסֵף לְבִנְיָמִין, אָמַר לֵיהּ אִית לָךְ אִינְתּוּ. אָמַר לֵיהּ, אִין. אָמַר לֵיהּ אִית לָךְ בְּנִין, אָמַר לֵיהּ אִין. וְהֵיךְ אִקְרוּן, אָמַר לֵיהּ עַל שׁוּם אָחִי וְכוּ' (נ\"א אמר ליה אית לך בנין, אמר ליה זמינין לי. ואיך יתקרון לך, אמר ליה על שום אחי וגו') גֵרָא וְנַעֲמָן וְגו' דִּכְתִיב (בראשית מ״ו:כ״א) וּבְנֵי בִנְיָמִין בֶּלַע וָבֶכֶר וְגו', וְאַתְּ אֲמַרְתְּ דְּלָא שִׁמֵּשׁ. (ס\"א אלא בההיא שעתא).","אָמַר לֵיהּ אִין, דְּהָא בְּהַהִיא שַׁעְתָּא לָא הֲווּ לֵיהּ. (ס\"א לבתר דיצא מבית האסורין הוו ליה) וְאִי תֵימָא וּבְנֵי בִנְיָמִן בֶּלַע וָבֶכֶר. כַּד עָאלוּ לְמִצְרַיִם, הָכִי הוּא וַדַּאי, דְּכָל זִמְנָא דְאִתְאַבַּל יַעֲקֹב עַל יוֹסֵף לָא שִׁמֵּשׁ עַרְסֵיהּ וְאוֹלִיד בְּנִין. וְאָמַר בִּנְיָמִן, הָא יוֹסֵף אָחִי, אַתְּ קְיָימָא דְּאַבָּא הֲוָה. דְּהָא בְּרִית סִיּוּמָא דְגוּפָא אִיהוּ, כֵּיוָן דְּאִיהוּ אִתְאֲבִיד, אֲנָא אֱהֵא נָטִיר אַתְרֵיהּ דְּאָחִי."],[[0,"תא חזי מה כתיב וכו':","בוא וראה, מה שכתוב, ויאמר אעבדך שבע שנים ברחל בתך הקטנה. ושואל. מה היה דעתו של יעקב, שלא אמר עשרה חדשים או שנה אחת, אלא שבע שנים למה. ומשיב, אלא יעקב עשה בחכמה, כדי שלא יאמרו הבריות, שבשביל התשוקה ביפיה של רחל עשה זה, אלא שידעו שעשה בחכמה, כי הלבנה, שהיא הנוקבא דז\"א, בת שבע שנים היא, כלומר, שצריכה להבנות בשבע ספירות חג\"ת נהי\"מ, וכל שבע שנים העליונים, דהיינו חג\"ת נהי\"מ מבינה, נחו על יעקב, מטרם שנשא את רחל, כדי לשבת אצלה כראוי. דהיינו להשפיע לה מז\"ס דבינה לז\"ס שלה. כי יעקב לקח כולם מתחילה, מבינה, ואח\"כ בא אליה, כדי להמצא, הוא בבחינת ז\"א שהוא שמים, והיא בבחינת נוקבא דז\"א, שהיא ארץ."],[1,"ורזא דמלה וכו':","וסוד הדבר. שכתוב, ויהיו בעיניו כימים אחדים. ושואל, מהו כימים אחדים. ומשיב, אלא כל שבע השנים היו שקולים בעיניו, כמו ז' שנים העליונות מבינה שהן \u0003אחדות\u0004 ביחוד אחד, ואינן נפרדות, וכולן אחד, שהן מתקשרות זו בזו. \u0003באהבתו אותה,\u0004 פירושו, שאהב אותה. להיותה נמצאת לו, כעין יחוד העליון שבבינה."],[2,"ת\"ח דאפילו לבן וכו':","בוא וראה, שאפילו לבן רמז לו באלו שבע ספירות הנ\"ל, והוא עצמו לא ידע מה שאומר, כי פתח ואמר \u0003טוב,\u0004 שכתוב טוב תתי אותה לך וגו' אמר רבי אבא, כן הוא ודאי, שעבד שבע שנים, שהן ז\"ס, כדי להזדווג בשמטה. דהיינו כדי להשפיע אותן ז\"ס להנוקבא תתאה, רחל, שנקראת שמטה. \u0003טוב\u0004 ה\"ס ז' ספירות עליונות הנמשכות מבינה, להיותן מנקודה דמפתחא: אשר \u0003ט'\u0004 ה\"ס יסוד, \u0003ו'\u0004 ה\"ס ת\"ת הכולל שש ספירות, \u0003ב'\u0004 ה\"ס ב' ההין, כמ\"ש כל זה באורך לעיל (בראשית א' דף רס\"ז אות שכ\"ו ע\"ש, ובהסולם)."],[2,"אמר רבי אלעזר ת\"ח וכו':","אר\"א, בוא וראה. בכל מקום, \u0003יובל\u0004 שהוא בינה, הוא סתום, שאינו מתגלה, היינו חסדים מכוסים ונעלמים מחכמה, ושמטה מתגלה. כלומר, שהחסדים שבה מתגלים בהארת החכמה. וכן לאה ורחל הן כנגד יובל ושמטה, כי לאה היא בחינת הנוקבא דז\"א שמחזה ולמעלה, שהיא כנגד בינה, שהיא \u0003יובל,\u0004 והיא בחינת עלמא דאתכסיא. ורחל היא בחינת הנוקבא דז\"א שמחזה ולמטה, שהיא שמטה, והיא בחינת עלמא דאתגליא."],[3,"ת\"ח בשעתא וכו':","בוא וראה, בשעה שיעקב עבד שבע שנים הראשונות, יצא קול ואמר, מן העולם ועד העולם כתוב, שפירושו שממשיכים מעולם הנסתר, לאה, עד עולם הנגלה שהוא רחל, עולם הסתום שלמעלה שהוא \u0003יובל,\u0004 דהיינו לאה, משם ההתחלה ולא מעולם הנגלה, שהוא רחל, ואלו המדרגות שהן סתומות ואינן מתגלות לנו, הן מיובל, ומשום זה נסתמו מיעקב, שלא ידע אפילו, שהן בשביל לאה, שהיא יובל, אלא שחשב אשר מן שמטה הן דהיינו בשביל רחל. ועוד טעם, כדי שיעשה התחלה מעולם העליון שהוא לאה, ע\"כ נתכסו ממנו ששייכים ללאה, משום שיובל הוא סתום. ולהיותו סתום ומכוסה מחכמה, לא היה רוצה להתחיל ולהמשיך ממנו, אם לא היה חושב, ששייכים לעולם הנגלה. ואחר שעברו ז' שני יובל המכוסים, עבד ז' שני שמטה הנגלים בשביל רחל, ונתעטר יעקב בשני עולמות, בעולם הנסתר ובעולם הנגלה. ונתאחד בהם."],[4,"ת\"ח לאה אולידת וכו':","בוא וראה, לאה ילדה ששה בנים ובת אחת. וכן ראוי להיות, כי ששה קצוות עומדים עליה, דהיינו יעקב, שהוא ת\"ת הכולל חג\"ת נה\"י, ואלו הששה ובת אחת יצאו בסוד עליון. דהיינו ששה בנים כנגד ו\"ק חג\"ת נה\"י, של יעקב. ובת אחת כנגד המלכות."],[5,"רחל אולידת וכו':","רחל הולידה שני צדיקים. וכן ראוי להיות, כי רחל ה\"ס שמטה, היושבת לעולם בין שני צדיקים. שכתוב צדיקים ירשו ארץ, והם צדיק למעלה בז\"א, וצדיק למטה בנוקבא, צדיק למעלה, ממנו נמשכים מים עליונים, שה\"ס אור ישר שממעלה למטה. צדיק למטה, ממנו הנוקבא נובעת מים, אל הזכר, שה\"ס אור חוזר, שממטה למעלה, בתשוקה שלמה. ונמצא שיש לה, צדיק מצד זה וצדיק מצד זה. כמו שהזכר העליון, שהוא ז\"א, יושב בין שתי נוקבין, שהן בינה ונוקבא, כן הנוקבא של מטה דהיינו הנוקבא שמחזה ולמטה דז\"א, יושבת בין שני צדיקים, שהם יוסף ובנימין."],[5,"","פירוש. כי נודע סוד הרקיע והפרסא שיש באמצע כל פרצוף במקום החזה, \u0003דשאיב מלעילא ויהיב לתתא,\u0004 (כנ\"ל ב\"א דף רצ\"ב אות שס\"ט) שה\"ס מלכות המסיימת העולה לת\"ת של כל פרצוף, שה\"ס בינה דגוף, ומורידה חצי בינה ותו\"מ דגוף, הנקראים נה\"י, למדרגה תחתונה ממנו, וכיון שנה\"י הללו מתחברים בתחתון בעת קטנות, הנה אח\"כ לעת גדלות שהעליון מחזיר אל מדרגתו את נה\"י שלו ממקום התחתון, עולה עמהם למקום העליון, גם התחתון הדבוק בהם, ועל ידי זה מקבל התחתון את האורות שבעליון. ונמצא עתה שהפרסא שואבת מעליון ומשפעת לתחתון. כי לולא הפרסא שהורידה והדביקה נה\"י דעליון בתחתון. לא היה יכול שום תחתון לעלות ולקבל משהו מן העליון שלו, להיותם בב' מקומות נפרדים. באופן, שנה\"י דבינה, שנדבקו בז\"א משפיעים לז\"א, אחר שיחזרו לבינה, את האורות דבינה. ונה\"י דז\"א שנדבקו בנוקבא, משפיעים לנוקבא, אחר שחזרו לז\"א, את האורות דז\"א. ונה\"י דנוקבא שנדבקו לנשמות הצדיקים, משפיעים להם, אחר שחזרו לנוקבא, את האורות דנוקבא. ולפיכך נבחן שז\"א יושב בין שתי נוקבין, כי נה\"י דבינה שירדו לז\"א, מדביקים ומעלים אותו לבינה, שהיא נוקבא עלאה, ונה\"י של עצמו שירדו לנוקבא תתאה, מדביקים ומעלים אליו את הנוקבא תתאה. וכן נבחנת הנוקבא תתאה שהיא יושבת בין שני צדיקים, כי נה\"י דז\"א, שעיקרם הוא קו אמצעי שבהם, שהוא יסוד, ירדו ונדבקו בנוקבא, וה\"ס \u0003צדיק העליון,\u0004 כי נה\"י דז\"א הם, והוא סוד \u0003יוסף.\u0004 ונה\"י של עצמה, שעיקרם הוא יסוד, ירדו ונדבקו בנשמות הצדיקים, וה\"ס \u0003צדיק תחתון,\u0004 כי נה\"י דנוקבא תתאה הם, וה\"ס בנימין."],[5,"","וזה אמרו \u0003כמה דדכורא לעילא יתיב בין תרי נוקבי\u0004 כי יש לו בהכרח ב' בחינות נה\"י, שנה\"י דעליון שלו מדביקים אותו לנוקבא עלאה בינה, כדי לקבל אורותיה, ונה\"י של עצמו מדביקים אותו אל הנוקבא תתאה, להשפיע לה אורותיו, כמו שנתבאר, \u0003הכי נמי נוקבא לתתא יתבא בין תרי צדיקי,\u0004 כן יש לה גם כן ב' בחינות נה\"י בהכרח, שעיקרם הוא יסוד, המכונה צדיק, א') הוא נה\"י דעליון שלה שהוא ז\"א, שמקבלת אורותיה מנה\"י הללו, שה\"ס צדיק עליון יוסף, ב) הוא נה\"י דעצמה המדביקים אותה אל נשמות הצדיקים להשפיע אליהם, שעיקרה הוא יסוד, והוא נק' צדיק תחתון בנימין."],[6,"ועל דא יוסף וכו':","ועל כן יוסף ובנימין שני צדיקים הם, יוסף זכה להיות צדיק למעלה, בז\"א, משום ששמר אות ברית. בנימין הוא צדיק למטה בנוקבא עצמה, כנ\"ל בדבור הסמוך, כדי שהשמטה שהיא הנוקבא תתעטר בין שני צדיקים, יוסף הצדיק ובנימין הצדיק. כמ\"ש לעיל."],[7,"וכי בנימין וכו':","ושואל, וכי בנימין היה צדיק. ומשיב, הן, משום שלא חטא כל ימיו באות הברית, ואע\"פ שלא קרה לו נסיון של מעשה כמו ליוסף, ושואל, אם כן, למה נקרא צדיק. כיון שלא קרה לו שום נסיון. הלא הרבה אנשים שומרי ברית היו כל ימיהם, ולא נקרא בשם צדיק, זולת, אם באו לידי נסיון."],[7,"אלא כל יומא דיעקב וכו':","ומשיב, אלא כל הימים שיעקב היה באבלו של יוסף, לא שמש מטתו. ובשביל זה זכה לשם צדיק. ואם תאמר, הרי כשנלקח יוסף מיעקב היה עוד בנימין ילד, ולא היה נשוי, ואתה אומר שלא שמש מטתו. ומשיב, אע\"פ שאחר כך נשא אשה לא רצה לשמש מטתו."],[8,"ואנן הכי תנן וכו':","ומקשה שוב, והרי כך למדנו אנחנו, בשעה שיוסף שאל לבנימין, ואמר לו, יש לך אשה. אמר לו הן. אמר לו יש לך בנים. והשיב הן. א\"ל ואיך נקראים. והשיב לו על שם אחי וכו' גרא ונעמן וגו' שכתוב ובני בנימין בלע ובכר וגו'. ואתה תאמר שלא שמש."],[9,"א\"ל אין וכו':","א\"ל הן, בשעה ההיא עוד לא היה לו בנים. דהיינו שחולק על אותה האגדה. ואם תאמר, הלא מקרא מפורש הוא, ובני בנימין בלע ובכר, כשבאו למצרים. כן הוא ודאי, שאז כבר היה לו בנים, כי כל זמן שיעקב התאבל על יוסף, לא שמש בנימין מטתו ולא הוליד בנים, אמר בנימין, הרי אחי יוסף אות ברית של אבי היה, כי יעקב הוא ת\"ת הכולל חג\"ת נה\"י, ויוסף הוא יסוד של יעקב, כי ברית, דהיינו יסוד, סיומו של הגוף הוא, שהוא ת\"ת, וכיון שהוא נאבד, אני אהיה שומר את מקומו של אחי. דהיינו להיות לבחינת יסוד צדיק, וסיום הת\"ת, כמו יוסף."]],[[0,"","בֹּא רְאֵה מַה כָּתוּב, וַיֹּאמֶר אֶעֱבָדְךְ שֶׁבַע שָׁנִים בְּרָחֵל בִּתְּךְ הַקְּטַנָּה. וְכִי מַה דַּעְתּוֹ שֶׁל יַעֲקֹב שֶׁלֹּא אָמַר עֲשָׂרָה יְרָחִים אוֹ שָׁנָה אַחַת, אֶלָּא שֶׁבַע שָׁנִים לָמָּה? אֶלָּא יַעֲקֹב עָשָׂה בְּחָכְמָה, כְּדֵי שֶׁלֹּא יֹאמְרוּ שֶׁבִּשְׁבִיל הַתְּשׁוּקָה שֶׁל יָפְיָהּ שֶׁל רָחֵל עָשָׂה, אֶלָּא בִּשְׁבִיל הַחָכְמָה, שֶׁהַלְּבָנָה בַּת שֶׁבַע שָׁנִים הִיא, וְכָל שֶׁבַע הַשָּׁנִים הָעֶלְיוֹנוֹת שׁוֹרוֹת הָיוּ עַל יַעֲקֹב טֶרֶם נָשָׂא אֶת רָחֵל לָשֶׁבֶת עִמָּהּ כָּרָאוּי, שֶׁהֲרֵי יַעֲקֹב נָטַל אֶת כֻּלָּם בָּרִאשׁוֹנָה, וְאַחַר כָּךְ בָּא אֵלֶיהָ, כְּדֵי לְהִמָּצֵא הוּא שָׁמַיִם וְהִיא אֶרֶץ."],[1,"","וְסוֹד הַדָּבָר - וַיִּהְיוּ בְעֵינָיו כְּיָמִים אֲחָדִים. מַה זֶה כְּיָמִים אֲחָדִים? אֶלָּא כָּל שֶׁבַע הַשָּׁנִים שָׁקַל אוֹתָם בְּעֵינָיו כְּאוֹתָם עֶלְיוֹנִים, שֶׁהֵם אֲחָדִים וְלֹא נִפְרָדִים, וְכֻלָּם אֶחָד, שֶׁנִּקְשָׁרִים זֶה עִם זֶה. בְּאַהֲבָתוֹ אֹתָהּ, לִהְיוֹת כַּדֻּגְמָה הָעֶלְיוֹנָה."],[2,"","בֹּא רְאֵה שֶׁאֲפִלּוּ לָבָן רָמַז לוֹ בְּאוֹתָם הַשֶּׁבַע וְלֹא יָדַע מָה אָמַר. שֶׁפָּתַח וְאָמַר טוֹב, שֶׁכָּתוּב טוֹב תִּתִּי וְגוֹ'. אָמַר רַבִּי אַבָּא, כָּךְ זֶה וַדַּאי, עָבַד שֶׁבַע שָׁנִים לְהִזְדַּוֵּג עִם שְׁמִטָּה. אָמַר רַבִּי אֶלְעָזָר, בֹּא רְאֵה, בְּכָל מָקוֹם הַיּוֹבֵל סָתוּם, שֶׁלֹּא הִתְגַּלָּה, וְהַשְּׁמִטָּה הִתְגַּלְּתָה."],[3,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁיַּעֲקֹב עָבַד שֶׁבַע שָׁנִים רִאשׁוֹנוֹת, יָצָא קוֹל וְאָמַר: יַעֲקֹב, כָּתוּב מִן הָעוֹלָם וְעַד הָעוֹלָם. הָעוֹלָם הַנִּסְתָּר שֶׁלְּמַעְלָה הַיּוֹבֵל, מִשָּׁם הָרֵאשִׁית. שֶׁאֵלּוּ שֶׁהֵם נִסְתָּרִים, שֶׁלֹּא הִתְגַּלָּה לָהֶם, הֵם מִן הַיּוֹבֵל. מִשּׁוּם כָּךְ נִסְתְּמוּ מִיַּעֲקֹב שֶׁלֹּא יָדַע, שֶׁחָשַׁב שֶׁהֲרֵי הֵם מִן הַשְּׁמִטָּה, וּכְדֵי שֶׁיַּעֲשֶׂה רֵאשִׁית מִן הָעוֹלָם שֶׁלְּמַעְלָה הִתְכַּסּוּ מִמֶּנּוּ, מִשּׁוּם שֶׁהַיּוֹבֵל הוּא נִסְתָּר. וְאַחַר שֶׁעָבְרוּ שְׁנֵי הַיּוֹבֵל הַמְכֻסִּים, עָשָׂה שְׁנֵי שְׁמִטָּה הַנִּגְלִים, וְהִתְעַטֵּר בִּשְׁנֵי עוֹלָמוֹת וְאָחַז אוֹתָם."],[4,"","בֹּא רְאֵה, לֵאָה הוֹלִידָה שִׁשָּׁה בָנִים וּבַת אַחַת, וְכָךְ רָאוּי, שֶׁהֲרֵי שִׁשָּׁה צְדָדִים עוֹמְדִים עָלֶיהָ, וְאֵלּוּ שִׁשָּׁה וּבַת אַחַת בְּסוֹד עֶלְיוֹן יָצְאָה."],[5,"","רָחֵל הוֹלִידָה שְׁנֵי צַדִּיקִים, וְכָךְ רָאוּי, הִנֵּה שְׁמִטָּה, שֶׁבֵּין שְׁנֵי צַדִּיקִים יוֹשֶׁבֶת לְעוֹלָמִים, שֶׁכָּתוּב צַדִּיקִים יִירְשׁוּ אָרֶץ. צַדִּיק לְמַעְלָה וְצַדִּיק לְמַטָּה. הַצַּדִּיק לְמַעְלָה, מִמֶּנּוּ שׁוֹפְעִים מַיִם עֶלְיוֹנִים. הַצַּדִּיק לְמַטָּה, מִמֶּנּוּ נוֹבַעַת הַנְּקֵבָה מַיִם לַזָּכָר בִּתְשׁוּקָה שְׁלֵמָה. צַדִּיק מִצַּד זֶה, וְצַדִּיק מִצַּד זֶה. כְּמוֹ שֶׁהַזָּכָר לְמַעְלָה יוֹשֵׁב בֵּין שְׁתֵּי נְקֵבוֹת, כָּךְ גַּם הַנְּקֵבָה לְמַטָּה יוֹשֶׁבֶת בֵּין שְׁנֵי צַדִּיקִים."],[6,"","וְעַל כֵּן יוֹסֵף וּבִנְיָמִין הֵם שְׁנֵי צַדִּיקִים. יוֹסֵף זָכָה לִהְיוֹת צַדִּיק לְמַעְלָה, מִשּׁוּם שֶׁשָּׁמַר אֶת הַבְּרִית, וּבִנְיָמִין הוּא צַדִּיק לְמַטָּה, לְעַטֵּר אֶת הַשְּׁמִטָּה בֵּין שְׁנֵי צַדִּיקִים - יוֹסֵף הַצַּדִּיק וּבִנְיָמִין הַצַּדִּיק."],[7,"","וְכִי בִּנְיָמִין הָיָה צַדִּיק? כֵּן, שֶׁכָּל יָמָיו לֹא חָטָא בְּאוֹת הַבְּרִית הַזּוֹ. וְאַף עַל גַּב שֶׁלֹּא הִזְדַּמֵּן לוֹ מַעֲשֶׂה כְּמוֹ יוֹסֵף, אִם כֵּן לָמָּה נִקְרָא צַדִּיק? אֶלָּא כָּל יְמֵי יַעֲקֹב, כְּשֶׁהָיָה בְּאֵבֶל שֶׁל יוֹסֵף, לֹא שִׁמֵּשׁ מִטָּתוֹ. וְאִם תֹּאמַר, שֶׁכְּשֶׁנִּטַּל יוֹסֵף מִיַּעֲקֹב, עֶלֶם הָיָה וְלֹא נָשׂוּי, וְאַתָּה אוֹמֵר שֶׁלֹּא שִׁמֵּשׁ מִטָּתוֹ? אֶלָּא אַף עַל גַּב שֶׁהִתְחַתֵּן לְאַחַר מִכֵּן, לֹא רָצָה לְשַׁמֵּשׁ מִטָּתוֹ."],[8,"","וְאָנוּ כָּךְ שָׁנִינוּ, בְּשָׁעָה שֶׁשָּׁאַל יוֹסֵף אֶת בִּנְיָמִין, אָמַר לוֹ: יֵשׁ לְךְ אִשָּׁה? אָמַר לוֹ: כֵּן. אָמַר לוֹ: יֵשׁ לְךְ בָּנִים? אָמַר לוֹ: כֵּן. וְאֵיךְ נִקְרָאִים? אָמַר לוֹ: עַל שֵׁם אָחִי וְכוּ', (אמר לו, יש לך בנים? אמר לו, עתידים לי, והיאך תקראם? אמר לו, על שם אחי וגו') גֵּרָא וְנַעֲמָן וְגוֹ', שֶׁכָּתוּב וּבְנֵי בִנְיָמִין בֶּלַע וָבֶכֶר וְגוֹ', וְאַתָּה אָמַרְתָּ שֶׁלֹּא שִׁמֵּשׁ? (אלא באותה שעה)."],[9,"","אָמַר לוֹ, כֵּן, שֶׁהֲרֵי בְּאוֹתָהּ שָׁעָה לֹא הָיוּ לוֹ. (לאחר שיצא מבית האסורים היו לו) וְאִם תֹּאמַר, וּבְנֵי בִנְיָמִין בֶּלַע וָבֶכֶר, כְּשֶׁנִּכְנְסוּ לְמִצְרַיִם, כָּךְ זֶה וַדַּאי. שֶׁכָּל זְמַן שֶׁהִתְאַבֵּל יַעֲקֹב עַל יוֹסֵף, לֹא שִׁמֵּשׁ מִטָּתוֹ וְהוֹלִיד בָּנִים. וְאָמַר בִּנְיָמִין: הִנֵּה יוֹסֵף אָחִי, אוֹת הַבְּרִית שֶׁל אַבָּא הָיָה, שֶׁהֲרֵי הַבְּרִית הִיא סִיּוּם הַגּוּף. כֵּיוָן שֶׁהוּא נֶאֱבָד, אֲנִי אֶהְיֶה שׁוֹמֵר מְקוֹמוֹ שֶׁל אָחִי."]]],[["וְאִי תֵימָא, הָא בְּהַהוּא זִמְנָא דְּאִתְאֲבִיד, לָא הֲוָה צַדִּיק. דְּצַדִּיק לָא הֲוָה עַד דְּאָעֲרַע עוֹבָדָא בֵּיהּ. אֶלָּא, כֻּלְּהוּ הֲווּ יָדְעֵי מִיַּעֲקֹב. דְּיַעֲקֹב הֲוָה יְדַע דְּאֲתַר דָּא יָרִית יוֹסֵף, וּבְגִינֵי כָךְ אוֹרִיךְ בְּלָבָן כָּל כָּךְ עַד דְּיִסְתַּיֵּים גּוּפָא, וּמַאן הוּא סִיּוּמָא דְגוּפָא, בְּרִית. וְעַל דָּא כְּתִיב, (בראשית ל׳:כ״ה) וַיְהִי כַּאֲשֶׁר יָלְדָה רָחֵל אֶת יוֹסֵף וְגו', דְּהָא וַדַּאי הַשְׁתָּא אִשְׁתְּלִים גּוּפָא, כֵּיוָן דְּגוּפָא אִשְׁתְּלִים, בְּעִינָא לְמֵיזַל. וּבְגִינֵי כָּךְ בִּנְיָמִן יָדַע וְנָטַר אוֹרְחֵיהּ דַּאֲחוּי.","כֵּיוָן דְּאֲתָא לְיוֹסֵף, וְאִשְׁתַּכַּח. בִּנְיָמִין הָדַר לְבֵיתֵיהּ, וְשִׁמֵּשׁ עַרְסֵיהּ (אזלי ועאלו) וְאוֹלִיד בְּנִין. וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא עָבִיד לֵיהּ צַדִּיק לְתַתָּא, וְיוֹסֵף צַדִּיק לְעֵילָא. וּבְגִינֵי כָּךְ, רָחֵל תְּרֵין בְּנִין אוֹלִידַת, וְלֵאָה שִׁית בְּנִין וּבְרַתָּא.","וְעַל דָּא, אִינוּן שֶׁבַע שְׁנִין קַדְמָאֵי אִתְכַּסְּיָין, דְּלָא יָדַע בְּהוּ יַעֲקֹב בְּגִין דְּהֲווּ דְּיוֹבְלָא, וְאִינוּן דִּשְׁמִטָּה אִתְגַּלְיָין, וּבִשְׁמִטָּה דְּאִתְגַּלְּיָא פָּלַח לְיוֹבְלָא דְּאִתְכַּסְיָא, דִּכְתִיב (בראשית כ״ט:כ׳) וַיַּעֲבֹד יַעֲקֹב בְּרָחֵל שֶׁבַע שָׁנִים. שֶׁבַע שָׁנִים סְתָם. בְּרָחֵל פָּלַח שֶׁבַע שְׁנִין עִלָּאִין, וְאִתְאֲחִיד בְּהוּ בִּתְרֵי עָלְמִין. מִכָּאן אוֹלִיפְנָא, מִגּוֹ דְּאִתְגַּלְּיָא, אָתֵי בַּר נָשׁ לִסְתִימָאָה.","וְאִי תֵימָא, אִי הָכִי דִּשְׁנִין קַדְמָאֵי מִיּוֹבְלָא אִינוּן, הָא בְּיוֹבְלָא כְּתִיב (ויקרא כ״ה:ח׳) שֶׁבַע שָׁנִים, שֶׁבַע פְּעָמִים. שֶׁבַע שָׁנִים שְׁכִיחֵי, שֶׁבַע פְּעָמִים (לא שכיחי) אָן אִינוּן. אֶלָּא, אִינוּן שִׁבְעָה יוֹמִין דְּנָטַר בְּהִלּוּלָא דְלֵאָה אַשְׁלִימוּ חוּשְׁבְּנָא, דְּהָא כָּל יוֹמָא (ס\"א פעם אחת ושבע אחת) (שבע) אַחַת אִקְרֵי, דִּכְתִיב, (תהילים קי״ט:קס״ד) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךָ עַל מִשְׁפְּטֵי צִדְקֶךָ. וְכָל שִׁבְעָה אִשְׁתְּלִים בְּשִׁבְעָה יוֹמִין, ז' בְּכָל יוֹמָא, דְּאִקְרֵי פַּעַם אַחַת.","וּבְרָחֵל לָא הֲוָה כֵן, דְּלָא נָטַר ז' יוֹמִין, אֶלָּא שֶׁבַע שְׁנִין דְּפָלַח לְבָתַר. וְאִי תֵימָא, אִי הָכִי, שְׁנִין דִּשְׁמִטָּה הֲוָה לֵיהּ לְמִפְלַח קוֹדֶם, וּלְבָתַר לְאִזְדַּוְּוגָא בִּשְׁמִטָּה. אֶלָּא כֵּיוָן דְּקַבִּיל עֲלֵיהּ לְמִפְלַח, כְּאִילּוּ פָּלַח לוֹן. אֲתָא רִבִּי אַבָּא וּנְשָׁקֵיהּ. אָמַר בְּרִיךְ רַחֲמָנָא דְּזָכִינָא לְהַאי קְרָא, עַל הַהוּא אֲתַר כְּתִיב (ישעיהו מ״ב:כ״א) ה' חָפֵץ לְמַעַן צִדְקוֹ יַגְדִּיל תּוֹרָה וְיַאְדִּיר.","תוּ אָמַר רִבִּי אֶלְעָזָר, הָא דְּאִתְּמָר לֵאָה אוֹלִידַת שִׁית בְּנִין וּבְרַתָּא חָדָא, הָכִי הוּא וַדַּאי, רָחֵל תְּרֵי בְּנִין וַדַּאי, בְּנִי שְׁפָחוֹת אַרְבָּעָה, תִּקּוּנָא דִלְהוֹן הֵיךְ קָיְימֵי. אֶלָּא אִינוּן אַרְבַּע (קנ\"ח ע\"א) קְשָׁרִים דְּאִקְרוּן אֲחוֹרַיִם, דִּכְתִיב (מלכים א ז׳:כ״ה) וְכָל אֲחוֹרֵיהֶם בָּיְתָה.","דְּהָא בִּדְרוֹעָא יְמִינָא תְּלַת (רמ\"א ע\"א) קִשְׁרִין. אֲבָל קִשְׁרָא חַד בְּאֶמְצָעִיתָא דְּאִיהוּ רַב וְאִיהוּ אָחוֹר, דְּאִשְׁתָּאַר לְבַר. וְכֵן חַד בִּדְרוֹעָא שְׂמָאלָא, וְכֵן חַד בְּיַרְכָא יְמִינָא, וְכֵן חַד בְּיַרְכָא שְׂמָאלָא. וְכַד אִתְתַּקַּן כֹּלָּא, אִשְׁתַּכָּחוּ כֻּלְּהוּ בָּיְתָה, לְקַיְימָא קְרָא דִּכְתִיב וְכָל אֲחוֹרֵיהֶם בָּיְתָה.","כָּל שְׁאָר קִשּׁוּרִין, כֻּלְּהוּ אִתְחַזְּיָין בְּמֵישַׁר וְאִלֵּין נָפְקִין, לְבַר מִדְּרוֹעִין וּלְבַר מִיַּרְכִין, לְאִתְחֲזָאָה בִּבְנִי הַשְּׁפָחוֹת, דְּאַף עַל גַּב דְּאִינוּן בְּמִנְיָינָא, לָא חֲשִׁיבֵי כִּבְנִי רָחֵל וְלֵאָה. וּבְגִינֵי כָךְ נָפְקֵי לְבַר.","דָבָר אַחֵר אִלֵּין אִינוּן אַרְבַּע, דְּכָל שְׁאָר קִשְׁרִין נָטְלֵי בְּגִינַיְיהוּ, וְאִלֵּין נָטְלֵי לוֹן. אָמַר רִבִּי אַבָּא, הָכִי הוּא וַדַּאי, (נ\"א אמר רבי אבא דא לאו דא) וְעַל דָּא כֹּלָּא מִתְתַּקַּן כְּחֲדָא.","(בראשית כ״ט:ל״א) וַיַּרְא ה' כִּי שְׂנוּאָה לֵאָה וְגו'. רַבִּי אֶלְעָזָר פָּתַח, מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת (תהילים קי״ג:ט׳) אֵם הַבָּנִים שְׂמֵחָה הַלְלוּיָה. מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת, דָּא רָחֵל דְּאִיהִי עִקְרָא דְבֵיתָא. אֵם הַבָּנִים שְׂמֵחָה, דָּא לֵאָה.","דָּבָר אַחֵר, מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת דָּא שְׁמִטָּה, דְּאִיהִי עִקָּרָא, דְּהַאי עַלְמָא, עֲלֵיהּ אִתְדַּבַּר. אֵם הַבָּנִים שְׂמֵחָה, דָּא יוֹבְלָא. דְּכָל חֵידוּ וְכָל חֶדְוָה דְּכֻלְּהוּ עַלְמִין בֵּיהּ תַּלְיָין. וְהַאי קְרָא, כְּלָלָא דְכֹלָּא הוּא. בְּגִין דְּהַאי כָּלִיל כֹּלָּא, בְּרָזָא קַדִּישָׁא, וְעַל דָּא סִיּוּמָא דִקְרָא, הַלְלוּיָה.","וַיַּרְא ה' כִּי שְׂנוּאָה לֵאָה, וְכִי אַמַּאי הִיא שְׂנוּאָה, וְהָא בְּנֵי שְׂנוּאָה לָאו בְּנִי מַעַלְיָא נִינְהוּ. וַחֲזִינָן דְּכָל אִינוּן בְּנִי מַעֲלֵי מִלֵּאָה נָפְקוּ, וְאַתְּ אֲמַרְתְּ כִּי שְׂנוּאָה לֵאָה. אֶלָּא, וַדַּאי יוֹבְלָא אִיהוּ תָּדִיר עַלְמָא דְאִתְכַּסְּיָא, וְכָל מִילּוֹי לָאו (בני) בְּאִתְגַּלְּיָא נִינְהוּ, וּבְגִין כָּךְ, יַעֲקֹב אִתְכַּסְּיָין מִנֵּיהּ כָּל עוֹבָדוֹי."],[[0,"ואי תימא וכו':","ואם תאמר, הרי באותו זמן שנאבד יוסף, עוד לא היה יוסף בבחינת צדיק, כי אין מי שיזכה לבחינת צדיק, זולת אם יקרה לו מעשה נסיון, ואז עוד לא בא לידו שום נסיון. ומשיב, אלא כולם היו יודעים זאת מיעקב, שהוא היה יודע, שמקום זה יירש יוסף, כלומר, שהיה יודע ברוח הקודש, שיתנסה במעשה דאשת פוטיפר, ויזכה לבחינת יסוד צדיק. כי משום זה המתין כל כך בבית לבן, ולא חזר לביתו, עד שיושלם הגוף ומי הוא סיום הגוף, הוא ברית, דהיינו יוסף. וע\"כ כתוב, ויהי כאשר ילדה רחל את יוסף ויאמר יעקב אל לבן שלחני וגו', כי אמר, עתה שנולד יוסף שהוא יסוד, ודאי נשלם הגוף, שהוא ת\"ת, וכיון שהגוף נשלם, אני רוצה ללכת. למקומי וארצי. הרי, שיעקב היה יודע ברוח הקודש, שיוסף הוא בחינת יסוד, וממנו ידעו כולם. ועל כן ידע בנימין, ושמר דרכו של אחיו, דהיינו שנעשה יסוד צדיק לאביו במקום יוסף, אחר שנאבד."],[1,"כיון דאתא ליוסף וכו':","אחר שבא אל יוסף, והוא נמצא, דהיינו שנתודע אל אחיו, חזר לביתו ושמש מטתו והוליד בנים, ועל כן עשה אותו הקב\"ה צדיק למטה, בהנוקבא, ויוסף היה צדיק למעלה, בז\"א, ומשום זה הולידה רחל שני בנים. ולאה, ששה בנים ובת."],[1,"","ואין להקשות איך אפשר שבזמן קצר כזה, מעת שחזרו השבטים עם עגלות פרעה לאביהם, עד חזרתם למצרים, יוליד עשרה בנים. כי האמת הוא, שאין הזהר מדבר במקרים גשמיים כלל, אלא בעולמות עליונים, שאין שם סדר זמנים כמו בגשמיות. וזמנים הרוחניים מתבארים בשינוי צורות ומדרגות שהם למעלה ממקום וזמן, כמו שבארתי בספרי תלמוד עשר ספירות (חלק א' דף כ\"ו ד\"ה עוד נשאר ע\"ש). ואין כאן המקום להאריך בזה."],[2,"ועל דא אינון שבע וכו':","ועל כן אלו שבע שנים הראשונות נתכסו, שיעקב לא ידע, שהן בשביל לאה, משום שהיו מיובל, מבינה שה\"ס עולם הנסתר. ואלו ז' שנים של שמטה, דהיינו עולם הנגלה, היו מגולים, שידע שעובד בשביל רחל. ובשביל שמטה שהיא עולם הנגלה, עבד באמת בשביל יובל שהיא עולם הנסתר, כלומר שחשב שעובד בשביל רחל שה\"ס שמטה, ולבסוף בשביל לאה היו. שה\"ס יובל. שכתוב, ויעבוד יעקב ברחל שבע שנים. שבע שנים סתומים, דהיינו מבחינת עולם הסתום לאה, עבד ברחל, ועבד שבע שנים עליונים, שהם ז' ספירות דלאה, ונמצא נאחז על ידיהן בשני העולמות, שחשב בשביל עולם הנגלה, והמשיך בשביל עולם הנסתר. מכאן למדנו שמתוך נגלה, בא האדם לנסתר."],[3,"ואי תימא אי הכי וכו':","ואם תאמר, אם כן, ששנים הראשונות שעבד, היו בשביל יובל, שהיא לאה, הרי ביובל כתוב, שבע שנים שבע פעמים, שבע שנים נמצאות, שכתוב ויעבוד וגו' שבע שנים, אבל שבע פעמים שבע, איפה הן, והיה לו לעבוד מ\"ט שנים, כמספר שני יובל. ומשיב אלא אלו הם שבעת הימים ששמר במשתה של לאה, כמ\"ש מלא שבוע זאת, השלימו המספר של מ\"ט. כי כל יום נקרא שבע אחת, כמ\"ש שבע ביום הללתיך וגו', וכל אחד משבעת ימי המשתה, נשלם ונכלל מכל שבעת הימים, ונמצא ז' בכל יום שנקראים פעם אחת. והם שבעה פעם שבעה, העולים מ\"ט כמספר שני היובל."],[4,"וברחל וכו':","וברחל לא היה כן, שלא שמר בה ז' ימי המשתה, אלא שבע שנים בלבד, בשבילה אחר נשואיה. ואם תאמר, אם כן, שני שמטה היה צריך לעבוד מקודם ואחר כך להזדווג בשמטה שהיא רחל. שהיה צריך מקודם להמשיך בשבילה ז' ספירות כמו שעשה בשביל יובל שהיא לאה. ומשיב, אלא כיון שקבל על עצמו לעבוד, נחשב לו כאלו כבר עבד, ונמשכו לו תכף ז' הספירות בשביל רחל. בא רבי אבא ונשק אותו. אמר, ברוך הרחמן שזכיתי להבין את מקרא הזה. על מקום הזה, שמחזה ולמטה דז\"א דהיינו על עולם הנגלה שהוא רחל העומדת שמה כתוב, ה' חפץ למען צדקו יגדיל תורה ויאדיר. שפירושו, ה' חפץ למען צדקו שיתגלה ויתאדר גדלות התורה, כי על ידי עולם הנגלה שהוא רחל, מתגלים החסדים של ז\"א, הנקרא תורה, ולפיכך נקראת רחל תורה שבעל פה. להיותה מגלה הסודות של תורה שבכתב, שהוא ז\"א. אמנם המקום שמחזה ולמעלה דז\"א, ששם עומדת עולם הנסתר שהיא לאה, אין שם גילוי התורה, שהוא ז\"א, אלא היא מכוסה ועטופה בסודות התורה. וע\"כ היא נקראת עולם הנסתר."],[5,"תו אמר רבי אלעזר וכו':","עוד אר\"א, מה שלמדנו שלאה הולידה ששה בנים ובת אחת שהם חג\"ת נהי\"מ, כן הוא ודאי. ורחל הולידה שני בנים, שהם שני צדיקים עליון ותחתון, כן הוא ודאי. אבל בני השפחות שהם ארבעה, אני שואל, התקון שלהם איפה הוא נמצא. הרי בבני רחל ולאה כבר יש כל הספירות. ומשיב, אלא הם ארבע קשרים הנקראים אחורים, שכתוב עליהם, וכל אחוריהם ביתה."],[6,"דהא בדרועא וכו':","כי בזרוע ימין שהוא חסד, יש שלשה קשרים, כי היד נחלקת לג' פרקים, שהם הקבורת והזרוע וכף היד, ומתחברים על ידי ג' קשרים. אבל יש קשר אחד באמצע שהוא גדול מכולם, והוא נבחן לאחור, להיותו בולט לחוץ מן הגוף. וכמוהו יש קשר אחד אמצעי, בשלשה קשרים שבזרוע השמאלי, וכמוהו אחד בשלשה קשרים שבירך הימיני, וכן אחד בשלשה קשרים שבירך השמאלי. ובשעה שהכל מתוקן, נמצאים כל אלו ד' הקשרים האחורים, נכנסים בפנימיות הגוף, לקיים הכתוב, וכל אחוריהם ביתה. ביתה פירושו לפנימיות."],[7,"כל שאר קשורין וכו':","כל שאר הקשרים, חוץ מן הד', כולם נראים במישור עם אברי הגוף, ואלו הד' בולטים לחוץ מן הזרועות, ולחוץ מן הירכים, להראות על בני השפחות, כי אף על פי שהם במנין י\"ב השבטים מכל מקום אינם חשובים כמו בני לאה ובני רחל, ומשום זה, המה בולטים לחוץ מן הזרועות והירכים."],[8,"ד\"א, אלין אינון ארבע וכו':","פירוש אחר. אלו בני השפחות, הס ד' קשרים, שכל שאר הקשרים נוסעים מכחם, ואלו הד' נושאים אותם. אר\"א, כן הוא ודאי, וע\"כ כולם מתתקנים כאחד."],[8,"","ביאור הדברים. כבר ידעת שמספר י\"ב, ה\"ס המרכבה להמשיך הארת החכמה, וביאורם הוא, הארת ג' קוין בכל אחד מד' בחינות חו\"ב תו\"מ, שהם בז\"א חו\"ג נו\"ה, וד' פעמים ג' הם י\"ב. וע\"כ נבחן שיש ג' פרקין בכל אחד מהזרועות שהם חו\"ג, ובכל אחד מירכים שהם נו\"ה."],[8,"","גם ידעת, שג' קוין משורשם, הם נמשכים מג' נקודות, חולם שורק וחירק, הנבחנים לג' זריעות. שה \u0003חולם\u0004 ה\"ס עלית המלכות לבינה דהיינו ה\"ת לנקבי עינים, שהמדרגה נשארת בסוד \u0003מ\"י\u0004 דאלקים ואותיות \u0003אל\"ה\u0004 נופלות למדרגה שמתחתיה. וה\"ס ש \u0003י'\u0004 נכנסה \u0003באור\u0004 המדרגה ונעשה \u0003אויר.\u0004 וה\"ס קו ימין. וה \u0003שורק\u0004 ה\"ס ירידת ה\"ת מעינים, ואותיות \u0003אל\"ה\u0004 חוזרות לאותיות מ\"י, ונגלה השם \u0003אלקים,\u0004 אמנם סתימא בשמא, שאז נמצא אור החכמה בלי חסד ואינו יכול להאיר. וה\"ס קו שמאל. וה \u0003חירק,\u0004 ה\"ס המסך דבחי\"א, המוציא ו\"ק בלי ראש, והוא בכל מקום בחינת ז\"א של אותה המדרגה, ובחינת קו אמצעי. הרי שיש בכל אחד מיעוט מיוחד, המכונה זריעה, ונבחנים לג' זריעות, (כמו שנתבאר לעיל ב\"א דף ט\"ו ד\"ה ההיא נקודה בארוכה ע\"ש)."],[8,"","אמנם כשמתחברים זה בזה, על ידי קו אמצעי, שה\"ס החירק, המייחד השורק והחולם, שהן קו ימין וקו שמאל, זה בזה, נמצאים כולם נשלמים זה מזה, ומאירים כאחד. ואז נבחנים ג' מיעוטים שבהם לבחינת \u0003קשרים,\u0004 שעל ידיהם מתקשרים ג' הקוין זה בזה. כי לולא השורק לא יצאה ה \u0003י'\u0004 מאויר, מנקודת החולם שהוא קו ימין, והיה נשאר בחסדים בלי חכמה. ולולא נקודת החירק, המיחד השורק והחולם זה בזה לא היה יכול השורק להאיר מטעם חוסר חסדים. ועל ידי הכרעת המסך דחירק את היחוד של החולם והשורק זב\"ז, השיג גם הוא בחינת ראש בכל אותו השיעור שגרם להאיר את החולם והשורק. הרי שכולם נקשרים זה בזה, ואם היה נפרד איזה קשר, היה מסתלק הארת כולם. ולפיכך נבחנים לג' קשרים. באופן שג' בחינות קומות של האור שבהם, נבחנות לג' פרקים שבכל אחד מן הזרועות והירכים, וג' בחינת מסכים שבהם, שהם מקשרים האורות זה בזה ומשלימים אותם להאיר כאחד, כנ\"ל, הן נבחנות לג' קשרים: אשר הראשון ה\"ס חולם. והאמצעי ה\"ס שורק. והתחתון ה\"ס חירק. כמבואר."],[8,"","וזה אמרו, \u0003דהא בדרועא ימינא תלת קשרין, אבל קשרא חד באמצעיתא, דאיהו רב ואיהו אחור,\u0004 כי ג' קשרים הם חולם שורק חירק, והאמצעי הוא השורק שהוא \u0003רב,\u0004 דהיינו שיש בו הארת חכמה הנק' \u0003רב,\u0004 גדול, אמנם \u0003איהו אחור,\u0004 שאינו מאיר כלום, כי כל עוד שהוא בלי חסדים אינו יכול להאיר. וז\"ש, \u0003וכד אתתקן כלא, אשתכחו כלהו ביתה, לקיימא קרא דכתיב וכל אחוריהם ביתה,\u0004 דהיינו בשעה שכל ג' הנקודות חולם שורק חירק מתחברים יחד, שעל ידי הקומה היוצאת על מסך דחירק מתחברים החולם והשורק יחדיו, וכל הג' מאירים כאחד, כי גם השורק שה\"ס קשר האמצעי שהיה באחור, ולא היה מאיר, נמצא עתה ששב להיות בחינת פנים, כלומר שחוזר להאיר, מחמת שנכלל בחסדים שבחולם. וזסו\"ה וכל אחוריהם ביתה, שסובב על קשר האמצעי, שבכל אחד מן הזרועות והירכים, שהיו בבחינת אחורים, שפירושו, בלתי מאירים, חזרו ע\"י יחוד קו אמצעי להיות פנים, ולהאיר."],[8,"","וז\"ש \u0003כל שאר קשורין כלהו אתחזיין במישר, ואלין נפקין לבר וכו' לא חשיבי כבני רחל ולאה\u0004. כי ב' הקשרים \u0003חולם וחירק,\u0004 שמהם נמשכים בני רחל ולאה, אפילו בטרם יחודם זה בזה היו גם כן מאירים, אלא בבחינת ו\"ק, ולפיכך, אחר יחודם זב\"ז, הם שוים עם אברי הגוף. אבל קשרים האמצעים, שמטרם היחוד היו חשכים לגמרי בלי אור, לכן גם אחר יחודם זב\"ז, שחזרו לבחינת פנים, מכל מקום נשארו בולטים לחוץ מאברי הגוף, שעוד ניכר בהם שהם אחורים, להורות, שהם בחינת \u0003בני השפחות,\u0004 שאע\"פ שהם במנין י\"ב, כלומר, שזולתם לא היה ג\"ר בב' הקוין הנמשכים מחולם וחירק, עכ\"ז אינם כל כך חשובים כמו החולם והחירק שבזרועות וירכים, שהם בני רחל ולאה, מטעם שהם היו מטרם היחוד חשכים לגמרי, והדין היה רובץ עליהם."],[8,"","וז\"ש \u0003ד\"א, אלין אינון ארבע, דכל שאר קשרין נטלי בגינייהו,\u0004 כי זולתם לא היה ג\"ר בב' הקשרים חולם ושורק, שבכל אחד מהזרועות והירכים, הרי שכל שאר הקשרים נוסעים ומאירים בכח אלו הד' קשרי האחורים. וז\"ש \u0003ואלין נטלי לון.\u0004 שד' קשרי האחורים נושאים את שאר הקשרים, כלומר, שמאירים בהם בחינת ג\"ר, וזולתם, היו כולם נופלים לבחינת ו\"ק. הרי שנושאים את כולם."],[9,"וירא ה' כי שנואה לאה וגו':","רבי אלעזר פתח, מושיבי עקרת הבית אם הבנים שמחה הללויה. \u0003מושיבי עקרת הבית,\u0004 זו היא רחל, שהיא העיקר שבבית. \u0003אם הבנים שמחה.\u0004 זו היא לאה. שהולידה ששה בנים ובת אחת."],[10,"ד\"א מושיבי עקרת הבית:","זו היא שמטה, שהיא נוקבא דז\"א, שהיא העיקר, כי עולם הזה מתנהג על ידה. \u0003אם הבנים שמחה:\u0004 זהו יובל, שהוא בינה, שכל שמחה וכל חדוה שבכל העולמות בי\"ע, בה תלויה, כי הנוקבא דז\"א אין לה מעצמה כלום, אלא מה שז\"א מקבל מבינה, ומשפיע אליה, ואז היא משפעת לכל העולמות, הרי שכל השמחה שבכל העולמות דהיינו בבי\"ע, מן בינה באה."],[10,"והאי קרא וכו':","ומקרא זה הוא כלל הכל, משום שזה כולל הכל בסוד הקדושה, דהיינו עולם הנסתר ועולם הנגלה, ועל כן סיומו של הכתוב הוא \u0003הללויה,\u0004 שהוא למעלה מכל השבחים שבתהלים כמ\"ש להלן (וישלח דף פ\"ג אות ר\"ע) ע\"ש."],[11,"וירא ה' כי שנואה לאה:","שואל, למה היתה שנואה, הרי בני שנואה אינם בנים הגונים, ואנו רואים, שכל בנים הטובים מלאה יצאו, ואתה אומר כי שנואה לאה. ומשיב, אלא ודאי, יובל הוא תמיד עולם הנסתר וכל דבריו אינם בגלוי, ומשום זה נסתרו כל מעשיו מן יעקב. כלומר, שהיתה אליו באהבה נסתרת, שבגלוי היתה נראה כשנואה, מטעם ש \u0003לאה,\u0004 היא בחינת מחזה ולמעלה דז\"א, ששם בחינת אמא, הנקראת יובל, שהיא עולם הנסתר, וע\"כ כל עניניו היו בסתר."]],[[0,"","וְאִם תֹּאמַר, הֲרֵי בְּאוֹתוֹ זְמַן שֶׁנֶּאֱבַד לֹא הָיָה צַדִּיק, שֶׁצַּדִּיק הוּא לֹא הָיָה עַד שֶׁקָּרָה הַמַּעֲשֶׂה הַזֶּה בּוֹ - אֶלָּא כֻּלָּם הָיוּ יוֹדְעִים מִיַּעֲקֹב, שֶׁיַּעֲקֹב הָיָה יוֹדֵעַ שֶׁהַמָּקוֹם הַזֶּה יָרַשׁ יוֹסֵף, וּמִשּׁוּם כָּךְ הֶאֱרִיךְ אֵצֶל לָבָן כָּל כָּךְ, עַד שֶׁיִּסְתַּיֵּם הַגּוּף, וּמִי הוּא סִיּוּם הַגּוּף? הַבְּרִית, וְעַל כֵּן כָּתוּב וַיְהִי כַּאֲשֶׁר יָלְדָה רָחֵל אֶת יוֹסֵף וְגוֹ'. שֶׁהֲרֵי וַדַּאי כָּעֵת הִשְׁתַּלֵּם הַגּוּף. כֵּיוָן שֶׁהִשְׁתַּלֵּם הַגּוּף, אֲנִי רוֹצֶה לָלֶכֶת. וּמִשּׁוּם כָּךְ בִּנְיָמִין יָדַע וְשָׁמַר אֶת דֶּרֶךְ אָחִיו."],[1,"","כֵּיוָן שֶׁבָּא לְיוֹסֵף וְנִמְצָא, בִּנְיָמִין חָזַר לְבֵיתוֹ וְשִׁמֵּשׁ מִטָּתוֹ (והלכו ונכנסו) וְהוֹלִיד בָּנִים. וְעַל כֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אוֹתוֹ צַדִּיק לְמַטָּה, וְיוֹסֵף צַדִּיק לְמַעְלָה, וּמִשּׁוּם כָּךְ רָחֵל הוֹלִידָה שְׁנֵי בָנִים, וְלֵאָה שִׁשָּׁה בָנִים וּבַת."],[2,"","וְעַל זֶה אוֹתָן שֶׁבַע הַשָּׁנִים הָרִאשׁוֹנוֹת מְכֻסּוֹת, שֶׁלֹּא יָדַע בָּהֶן יַעֲקֹב, מִשּׁוּם שֶׁהָיוּ שֶׁל הַיּוֹבֵל. וְאוֹתָן שֶׁל שְׁמִטָּה הִתְגַּלּוּ, וּבַשְּׁמִטָּה הַגְּלוּיָה עָבַד אֶת הַיּוֹבֵל שֶׁהִתְכַּסָּה, שֶׁכָּתוּב וַיַּעֲבֹד יַעֲקֹב בְּרָחֵל שֶׁבַע שָׁנִים. שֶׁבַע שָׁנִים סְתָם. בְּרָחֵל עָבַד שֶׁבַע שָׁנִים עֶלְיוֹנוֹת, וְנֶאֱחַז בָּהֶן בִּשְׁנֵי עוֹלָמוֹת. מִכָּאן לָמַדְנוּ, מִתּוֹךְ הַנִּגְלֶה בָּא הָאָדָם לַנִּסְתָּר."],[3,"","וְאִם תֹּאמַר, אִם כָּךְ שֶׁהַשָּׁנִים הָרִאשׁוֹנוֹת הֵן מֵהַיּוֹבֵל, הֲרֵי בַּיּוֹבֵל כָּתוּב שֶׁבַע שָׁנִים שֶׁבַע פְּעָמִים. שֶׁבַע שָׁנִים מְצוּיוֹת, שֶׁבַע פְּעָמִים (לא מצויות) אֵיפֹה הֵן? אֶלָּא אוֹתָם שִׁבְעָה יָמִים שֶׁשָּׁמַר בַּחֲתֻנָּה שֶׁל לֵאָה הִשְׁלִימוּ אֶת הַחֶשְׁבּוֹן, שֶׁהֲרֵי כָּל יוֹם (פעם אחת ושבע אחת) (שבע) נִקְרָא פַּעַם אַחַת, שֶׁכָּתוּב (תהלים קיט) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךְ עַל מִשְׁפְּטֵי צִדְקֶךְ. וְכָל שִׁבְעָה מִשְׁתַּלֵּם בְּשִׁבְעָה יָמִים, ז' בְּכָל יוֹם, שֶׁנִּקְרָא פַּעַם אַחַת."],[4,"","וּבְרָחֵל לֹא הָיָה כֵן, שֶׁלֹּא שָׁמַר שִׁבְעָה יָמִים, אֶלָּא שֶׁבַע שָׁנִים שֶׁעָבַד אַחַר כָּךְ. וְאִם תֹּאמַר, אִם כָּךְ, שָׁנִים שֶׁל שְׁמִטָּה הָיָה לוֹ לַעֲבֹד קֹדֶם וְאַחַר כָּךְ לְהִזְדַּוֵּג עִם הַשְּׁמִטָּה? אֶלָּא כֵּיוָן שֶׁקִּבֵּל עָלָיו לַעֲבֹד, כְּאִלּוּ עָבַד אוֹתָם. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ. אָמַר, בָּרוּךְ הָרַחֲמָן שֶׁזָּכִיתִי לַפָּסוּק הַזֶּה, עַל אוֹתוֹ הַמָּקוֹם כָּתוּב (ישעיה מט) ה' חָפֵץ לְמַעַן צִדְקוֹ יַגְדִּיל תּוֹרָה וְיַאְדִּיר."],[5,"","עוֹד אָמַר רַבִּי אֶלְעָזָר, זֶה שֶׁנֶּאֱמַר לֵאָה הוֹלִידָה שִׁשָּׁה בָנִים וּבַת אַחַת - כָּךְ זֶה וַדַּאי. רָחֵל שְׁנֵי בָנִים וַדַּאי, בְּנֵי הַשְּׁפָחוֹת אַרְבָּעָה. תִּקּוּנָם אֵיךְ עוֹמְדִים? אֶלָּא אוֹתָם אַרְבָּעָה קְשָׁרִים שֶׁנִּקְרָאִים אֲחוֹרַיִם, שֶׁכָּתוּב וְכָל אֲחֹרֵיהֶם בָּיְתָה."],[6,"","שֶׁהֲרֵי בִּזְרוֹעַ יָמִין שְׁלֹשָׁה קְשָׁרִים, אֲבָל קֶשֶׁר אֶחָד בָּאֶמְצַע שֶׁהוּא גָדוֹל וְהוּא אָחוֹר, שֶׁנִּשְׁאַר בַּחוּץ. וְכֵן אֶחָד בִּזְרוֹעַ שְׂמֹאל, וְכֵן אֶחָד בְּיֶרֶךְ יָמִין, וְכֵן אֶחָד בְּיֶרֶךְ שְׂמֹאל. וּכְשֶׁהַכֹּל נִתְקַן, נִמְצְאוּ כֻלָּם בַּיְתָה, לְקַיֵּם אֶת הַפָּסוּק שֶׁכָּתוּב וְכָל אֲחֹרֵיהֶם בָּיְתָה."],[7,"","כָּל שְׁאָר הַקְּשָׁרִים, כֻּלָּם נִרְאִים בְּיֹשֶׁר, וְאֵלּוּ יוֹצְאִים מִחוּץ לַזְּרוֹעוֹת וּמִחוּץ לַיְרֵכַיִם לְהֵרָאוֹת בִּפְנֵי הַשְּׁפָחוֹת. שֶׁאַף עַל גַּב שֶׁהֵם בַּמִּנְיָן, אֵינָם חֲשׁוּבִים כִּבְנֵי רָחֵל וְלֵאָה, וּמִשּׁוּם כָּךְ יָצְאוּ בַּחוּץ."],[8,"","דָּבָר אַחֵר, אֵלּוּ הֵם הָאַרְבָּעָה שֶׁכָּל שְׁאָר הַקְּשָׁרִים נוֹטְלִים בִּשְׁבִילָם, וְאֵלּוּ נוֹטְלִים אוֹתָם. אָמַר רַבִּי אַבָּא, כָּךְ זֶה וַדַּאי, (אמר רבי אבא, זה לא זה) וְעַל כֵּן הַכֹּל נִתְקָן יַחַד."],[9,"","וַיַּרְא ה' כִּי שְׂנוּאָה לֵאָה וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח, (תהלים קיג) מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת אֵם הַבָּנִים שְׂמֵחָה הַלְלוּיָהּ. מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת - זוֹ רָחֵל, שֶׁהִיא עִקַּר הַבַּיִת. אֵם הַבָּנִים שְׂמֵחָה - זוֹ לֵאָה."],[10,"","דָּבָר אַחֵר מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת - זוֹ שְׁמִטָּה, שֶׁהִיא עִקַּר הָעוֹלָם הַזֶּה, עָלָיו הוּא מֻנְהָג. אֵם הַבָּנִים שְׂמֵחָה - זֶה הַיּוֹבֵל, שֶׁכָּל שִׂמְחָה וְכָל חֶדְוָה שֶׁל כָּל הָעוֹלָמוֹת תְּלוּיִים בּוֹ, וְהַפָּסוּק הַזֶּה הוּא הַכְּלָל שֶׁל הַכֹּל, מִשּׁוּם שֶׁזֶּה כּוֹלֵל הַכֹּל בְּסוֹד קָדוֹשׁ, וְעַל זֶה סִיּוּם הַפָּסוּק הַלְלוּיָהּ."],[11,"","וַיַּרְא ה' כִּי שְׂנוּאָה לֵאָה. וְכִי לָמָּה הִיא שְׂנוּאָה, וַהֲרֵי בְּנֵי הַשְּׂנוּאָה אֵינָם בָּנִים מְעֻלִּים, וְרָאִינוּ שֶׁכָּל אוֹתָם בָּנִים מְעֻלִּים יָצְאוּ מִלֵּאָה, וְאַתָּה אוֹמֵר שֶׁלֵּאָה שְׂנוּאָה? אֶלָּא וַדַּאי הַיּוֹבֵל הוּא תָּמִיד עוֹלָם הַנִּסְתָּר, וְכָל דְּבָרָיו אֵינָם (בני) בְּנִגְלֶה, וּמִשּׁוּם כָּךְ נִסְתְּרוּ מִיַּעֲקֹב כָּל מַעֲשָׂיו."]]],[["תָּא חֲזֵי, עַלְמָא תַּתָּאָה בְּאִתְגַּלְּיָא אִיהוּ, וְהוּא שֵׁירוּתָא דְּכֹלָּא, לְסַלְּקָא בְּדַרְגּוֹי. כְּמָה דְחָכְמָה עִלָּאָה הוּא שֵׁירוּתָא דְּכֹלָּא, הָכִי נָמֵי עַלְמָא תַּתָּאָה, חָכְמָה אִיהוּ, וְהִיא שֵׁירוּתָא דְכֹלָּא. וּבְגִין כָּךְ, קָרֵינָן אַתָּה, (שמות קל\"ח ע\"ב) בְּגִין דְּאִיהוּ שְׁמִטָּה, וְאִתְגַּלְּיָא.","וְעַלְמָא עִלָּאָה דְּאִיהוּ יוֹבְלָא, קָרֵינָא הוּא, דְּכָל מִלּוֹי בְּאִתְכַּסְּיָא אִינוּן. וְרָזָא דְמִלָּה דְלֵאָה, דִּכְתִיב, (בראשית ל׳:ט״ז) וַיִּשְׁכַּב עִמָּהּ בַּלַּיְלָה הוּא. וְעַל דָּא כְּתִיב, (במדבר י״ח:כ״ג) וְעָבַד הַלֵּוִי הוּא. בְּגִין לְאַמְשָׁכָא מִנֵּיהּ בִּרְכָאן לְכֹלָּא. הוּא, עַלְמָא עִלָּאָה דְּאִתְכַּסְּיָא תָּדִיר, וְיַעֲקֹב בְּמָּה דְּאִתְכַּסְּיָא לָא אִתְדָּבַּק בִּרְעוּתֵיהּ, אֶלָּא בְּמָּה דְּאִתְגַּלְּיָא, וְרָזָא דָא דִּכְתִיב, (בראשית ב׳:כ״ד) וְדָבַק בְּאִשְׁתּוֹ.","(בראשית כ״ט:ל״א) וַיַּרְא ה' כִּי שְׂנוּאָה לֵאָה. מֵהָכָא, דְּסָאנֵי בַּר נָשׁ עֶרְיָין דְּאִמֵּיהּ, (ואחותיה) וְיִתְיַחֵד בַּר נָשׁ עִם אִמֵּיהּ בְּכָל אֲתַר וְלָא יִתְחֲשָׁשׁ. וְהָא אִתְעָרוּ, בֵּן מִתְיַחֵד עִם אִמּוֹ. וְכֹלָּא אִתְכַּסֵּי מִיַּעֲקֹב, דְּעַלְמָא עִלָּאָה לָא אִתְגַּלְּיָא כְּלָל.","תָּא חֲזֵי, בְּגִינֵיהּ דְּיַעֲקֹב אִתְקְיַּים עַלְמָא, וְאִי תֵימָא הָא בְגִינֵיהּ דְּאַבְרָהָם, כְּמָה דְאַתְּ אָמֵר, (בראשית ב) בְּהִבָּרְאָם, אַל תִּקְרֵי בְּהִבָּרְאָם אֶלָּא בְּאַבְרָהָם. אֶלָּא בְּגִינֵיהּ דְּיַעֲקֹב אִתְקְיַּים אַבְרָהָם, דִּכְתִיב, (ישעיהו כ״ט:כ״ב) כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם. וּמִקַּדְּמַת דְּנָא הֲוָה קוּדְשָׁא בְּרִיךְ הוּא בָּנֵי עָלְמִין וְחָרִיב לוֹן, כֵּיוָן דְּאֲתָא יַעֲקֹב מִנֵּיהּ אִשְׁתַּכְלָלוּ עָלְמִין, וְלָא אִתְחָרָבוּ כְּקַדְמִיתָא, הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ג:א׳) כֹּה אָמַר ה' בֹּרַאֲךָ יַעֲקֹב וְיֹצֶרְךָ יִשְׂרָאֵל וְגו'.","תָּא חֲזֵי מַה כְּתִיב, (שמות ד׳:כ״ג) בְּנִי בְּכוֹרִי יִשְׂרָאֵל, וּכְתִיב (שם) שַׁלַּח אֶת בְּנִי וְיַעַבְדֵנִי, יִשְׂרָאֵל אִקְרֵי בֵּן לְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּאִתְדָּבַּק בֵּיהּ, כְּמָה דְאַתְּ אָמֵר, (משלי ל׳:ד׳) מַה שְּׁמוֹ וּמַה שֵּׁם בְּנוֹ כִּי תֵדָע.","לֵאָה, כַּד אוֹלִידַת לִרְאוּבֵן מַה כְּתִיב, (בראשית כ״ט:ל״ב) וַתִּקְרָא אֶת שְׁמוֹ רְאוּבֵן. רְאוּבֵן סְתָם, בְּגִין דְּאִתְכְּלִיל בִּתְלַת סִטְרִין מִתְחַבְּרָן כְּחֲדָא, שִׁמְעוֹן וְלֵוִי. מַאי טַעְמָא לֵוִי, כְּמָה דְאַתְּ אָמֵר, (מלכים א ז) לֹיוֹת, חִבּוּרָא דְכָל סִטְרִין.","אָמַר רִבִּי יְהוּדָה, מֵהָכָא, דִּכְתִיב, (בראשית מ״ט:ג׳) יֶתֶר שְׂאֵת וְיֶתֶר עָז, כְּתַרְגּוּמוֹ בְּכֵירוּתָא, כְּהוּנְתָּא, וּמַלְכוּתָא. וּמַלְכוּ בְּסִטְרָא דִגְבוּרָה אִיהוּ, וְעַל דָּא רְאוּבֵן סְתָם.","אָמַר רִבִּי אַבָּא רְאוּ בֵן סְתָם, דְּאִתְכְּלִיל בְּשִׁמְעוֹן וְלֵוִי. לֵאָה הָכִי הֲוָה דַעְתָּהּ. (ס\"א רעותא) דִּכְתִיב, (בראשית כ״ט:ל״ד) הַפַּעַם יִלָּוֶה אִישִׁי אֵלַי כִּי יָלַדְתִּי לוֹ שְׁלשָׁה בָנִים. בְּגִין דְּהֲוָה תְּלָתָא דְּמִתְחַבְּרָן כְּחֲדָא.","וְתָא חֲזֵי, דְּהָכָא הוּא. דְּהָא רְתִיכָא עִלָּאָה, אֲבָהָן וְדָוִד מַלְכָּא דְּאִתְחַבַּר בְּהוּ, וְכֻלְּהוּ אַרְבַּע אִינוּן רְתִיכִין עִלָּאִין, רָזָא דִשְׁמָא קַדִּישָׁא. וְעַל דָּא, רְאוּבֵן שִׁמְעוֹן לֵוִי, לְבָתַר יְהוּדָה דְּיָרִית מַלְכוּ, וְעַל דָּא, כֻּלְּהוּ בְּאֲתַר דָּא.","וּכְתִיב (ס\"א דא בתר דא דכתיב) (בראשית כ״ט:ל״ה) הַפַּעַם אוֹדֶה אֶת ה' וְגו' (בראשית כ״ט:ל״ה) וַתַּעֲמֹד מִלֶּדֶת, בְּגִין דְּהָכָא אִשְׁתַּכְלָלוּ אַרְבַּע סָמְכִין. הַפַּעַם אוֹדֶה אֶת ה', מַאי טַעֲמָא אָמְרָה אוֹדֶה אֶת ה' בְּהַאי, וְלָאו בְּכֻלְּהוּ. אֶלָּא מֵהָכָא, כָּל זִמְנָא דִּכְנֶסֶת יִשְׂרָאֵל בְּגָלוּתָא, שְׁמָא קַדִּישָׁא לָאו שְׁלִים הוּא. תָּא חֲזֵי, אַף עַל גַּב דִּתְלַת בְּנִין הֲווּ עַד דְּאוֹלִידַת לִיהוּדָה, לָא שְׁלִים כֻּרְסְיָיא. וּבְגִינֵי כָּךְ הַפַּעַם אוֹדֶה אֶת ה', וְלָא בְּכֻלְּהוּ, וְעַל דָּא וַתַּעֲמֹד מִלֶּדֶת. מַאי (קפ\"ו ע\"א) וַתַּעֲמֹד, דְּקָיְימָא כֻּרְסְיָיא עַל סַמְכוֹהִי."],[[0,"ת\"ח עלמא תתאה וכו':","בוא וראה עולם התחתון שהיא רחל, נוקבא דז\"א, הוא בגלוי, והוא התחלת הכל לעלות במדרגות. כמו שחכמה עלאה, דהיינו חכמה דא\"א, הוא התחלת הכל ממעלה למטה, (כנ\"ל ב\"א דף ו' ד\"ה אחר ע\"ש.) כן עולם התחתון הוא חכמה, והוא התחלת הכל ממטה למעלה. ומשום זה קוראים לה \u0003אתה,\u0004 משום שהיא שמטה, והיא בגלוי. \u0003בגלוי,\u0004 פירושו, שהחסדים שבה מתגלים בהארת החכמה, בסוד ה \u0003י'\u0004 היוצא מ \u0003אויר\u0004 ואשתאר \u0003אור.\u0004 ואז נקראת הנוקבא דז\"א בשם \u0003שמטה.\u0004 וז\"ש \u0003בגין דאיהו שמטה ואתגליא.\u0004"],[1,"ועלמא עלאה וכו':","ועולם העליון שהוא יובל, דהיינו לאה הנמשכת מאמא, אנו קוראים, \u0003הוא,\u0004 שכל דבריו בהסתר הם. כי המלה \u0003הוא\u0004 רומזת על עולם הנסתר (כמ\"ש בזהר ספרא דצניעותא אות ל') וסוד הדבר, כי בלאה כתוב, וישכב עמה בלילה \u0003הוא,\u0004 ועל כן כתוב ועבד הלוי \u0003הוא,\u0004 שהלוי עובד כדי להמשיך ברכות ממנו מן \u0003הוא\u0004 לכל העולמות. \u0003הוא,\u0004 הוא עולם העליון הנעלם תמיד, ויעקב, לא נתדבק ברצון אלא במה שמגולה. והוא סוד, שכתוב ודבק באשתו. פירוש. שהוא הטעם שהכתוב אומר, על כן יעזוב איש את \u0003אביו ואת אמו,\u0004 מטעם שהם בחינת עולם הנסתר, \u0003ודבק באשתו\u0004 שהוא עולם הנגלה."],[2,"וירא ה' כי שנואה לאה:","מטעם שנמשכת מאמא כנ\"ל. מכאן נשמע, שהאדם שונא את העריות מצד אמו. משום שאמו ה\"ס עולם הנסתר, שנאמר עליו, ע\"כ יעזוב איש את אביו ואת אמו. כנ\"ל ומתיחד האדם בכל מקום עם אמו, ואינו חושש לאיסור יחוד. וכן אמרו, הבן מתיחד עם אמו. וע\"כ הכל נעלם מיעקב, כי עולם העליון, שהוא לאה, הנמשך מאמא, לא נגלה כלל."],[3,"ת\"ח בגיניה דיעקב וכו':","בוא וראה, בשביל יעקב נתקיים העולם. ואם תאמר הרי בשביל אברהם נתקיים העולם כמש\"א, \u0003בהבראם\u0004 אל תקרא בהבראם אלא \u0003באברהם,\u0004 כלומר מ\"ש אלה תולדות השמים והארץ \u0003בהבראם,\u0004 יש לקרות אלה תולדות השמים והארץ \u0003באברהם,\u0004 כי האותיות שוות, שפירושו שתולדות שמים וארץ בשביל אברהם היו. ומשיב, אלא בשביל יעקב נתקיים אברהם, שכתוב, כה אמר ה' אל בית יעקב אשר פדה את אברהם. כי מקודם לכן, היה הקב\"ה בונה עולמות ומחריב אותם, כיון שבא יעקב, נשתכללו ממנו העולמות, ולא נחרבו כמקודם, וזה הוא שכתוב, כה אמר ה' בוראך יעקב ויצרך ישראל וגו'."],[3,"","ביאור הדברים. אברהם ה\"ס קו ימין דז\"א, שה\"ס חסד. וע\"כ אומר שבשביל אברהם נברא העולם, דהיינו בשביל החסד כמ\"ש עולם חסד יבנה, אמנם בעת יציאת קו השמאל. נעשה מחלוקת בין ב' הקוין, (כנ\"ל ב\"א דף נ\"ו ד\"ה כד) ועל מצב הזה, אמרו, שהקב\"ה בנה עולמות והחריבם, כי מחמת רוב הדינים שבשמאל, כל מה שנבנה מצד הימין חזר ונחרב מכח השמאל, עד שבא קו אמצעי, שה\"ס יעקב, והכריע בין ימין לשמאל ועשה שלום ביניהם, ואז נתקיים העולם ולא נחרב יותר. וזסו\"ה יעקב אשר פדה את אברהם, כי האמת הוא, עולם חסד יבנה, שה\"ס אברהם, אבל לולא קו אמצעי, שהוא יעקב, לא היה קיום לקו ימין שה\"ס אברהם."],[4,"ת\"ח מה כתיב בני וכו':","בוא וראה, מה כתוב, בני בכורי ישראל, וכתוב, שלח את בני ויעבדני. כי ישראל נקרא בן אל הקב\"ה, משום שנתדבק בו. כמש\"א, מה שמו ומה שם בנו כי תדע."],[4,"","ביאור הדברים. כי הספירות נמשכות זו מזו בדרך השתלשלות, בסוד סבה ומסובב, ומבחינה זו אינם נקראות אב ובן, כי השם בן פירושו אור של תולדה, אשר מבחינת השתלשלות אין בו שום אור, אלא מבחינת חידוש. וז\"ס שחכמה ובינה מכונים אבא ואמא, וז\"א מכונה בן אליהם. כי בדרך השתלשלות הספירות נמצא ז\"א בבחינת ו\"ק חסר ראש, ומבחינה זו אינו נקרא בן. אמנם בסוד עלית מ\"ן להכריע בין ב' הקוין ימין ושמאל של הבינה, שנעשה שם קו אמצעי ומיחד ב' הקוים זה בזה, הוא משיג ממנה בחינת ג\"ר, כנ\"ל (ב\"א דף רפ\"ז ד\"ה תלת) דכיון ד \u0003תלת נפקי, מחד חד בתלת קיימא\u0004 ע\"ש. שהוא מטעם שכל שיעור האור שהתחתון גורם לצאת בעליון זוכה בו גם התחתון."],[4,"","והנה ג\"ר הללו שז\"א זכה בהם, נבחנות לאור של תולדה. שהרי מבחינת השתלשלות הספירות זו מזו אין בו משהו מאור ג\"ר, אלא הוא ו\"ק בלי ראש, ונמצא שאור ג\"ר הללו הן כולן חידוש, שזכה בהן מטעם שגרם הארת ג\"ר בימין ושמאל שבבינה. כמבואר. ומבחינה זו, נבחנים ב' הקוין ימין ושמאל דבינה, בשם אבא ואמא, וז\"א נקרא בשם בן. כי נקראים או\"א מטעם שהם חידשו אור הזה אף על פי שאינו נמצא כלל בהשתלשלות סבה ומסובב. וז\"א נקרא בן, להיותו אור של חידוש שנתחדש על ידי ימין ושמאל דבינה המולידים."],[4,"","ועל סוד הזה אומר הכתוב, \u0003מה שמו ומה שם בנו כי תדע.\u0004 שסובב על בינה וז\"א, אשר ב' קוי הבינה שהיו נקראים חכמה ובינה, השיגו השם אבא ואמא. וז\"א השיג השם בן אליהם, שנתחדש ויצא מהם, וז\"ש בתקונים תקון ס\"ט ק\"י ע\"א, \u0003מה שמו, חכמה עלאה דתמן חכמה.\u0004 כלומר שהכתוב \u0003מה שמו,\u0004 סובב על אמא עלאה שה\"ס בינה, וקו ימין שבה ה\"ס חכמה, ושניהם השיגו השם או\"א, דהיינו מולידים. וז\"א בן הנולד מהם. כמבואר."],[4,"","וזה אמרו כאן, \u0003ישראל אקרי בן לקב\"ה בגין דאתדבק ביה,\u0004 כי נשמות הצדיקים מתדבקים בהקב\"ה, על ידי שעולים למ\"ן לזווג קב\"ה ושכינתיה, ונעשים שם לבחינת קו אמצעי, בין הקב\"ה שה\"ס ימין ובין השכינה שה\"ס שמאל, דהיינו ממש על דרך שז\"א עלה למ\"ן לבינה, ונעשה קו אמצעי בין ימין ושמאל דבינה כנ\"ל, ואז כל אותו השיעור שנשמות הצדיקים גרמו לצאת בקב\"ה ושכינתיה על ידי זווגם יחד, זוכות בו גם הן, כנ\"ל (לך דף פ\"ה ד\"ה ברוך ע\"ש) ומבחינת אור הזה, שהשיגו מזווג זו\"ן, הם נבחנים לבנים אל זו\"ן, כי הוא אור של תולדה שנתחדש מן המולידים שהם זו\"ן."],[4,"","וזהו שמביא ראיה מן הכתוב, \u0003מה שמו ומה שם בנו כי תדע.\u0004 ללמדנו, כמו ז\"א שנבחן לבן לאו\"א מטעם היותו קו אמצעי המכריע בין ב' קוין שבבינה, מאותו הטעם ממש נבחנים נשמות הצדיקים שהן בנים אל זו\"ן. כמבואר. כי גם הם בחינת קו אמצעי בסוד זווג זו\"ן."],[5,"לאה, כד אולידת וכו'","לאה כשהולידה את ראובן, מה כתוב, ותקרא את שמו ראובן, \u0003ראו בן\u0004 סתם, בלי שום טעם נוסף, כמו בשמעון, שאמרה כי שמע וגו', וכן בשאר בניה וכיון שהוא בחינת חסד, למה לא קראה אותו בן ימין. ומשיב, שהוא משום שנכלל בג' קוין המתחברים כאחד, דהיינו עם שמעון ולוי, שהם קו שמאל וקו אמצעי."],[5,"","ביאור הדברים. כי נשמות השבטים יצאו מזו\"ן, אשר מז\"א ולאה יצאו ששה בנים ובת אחת, ומז\"א ורחל ב' צדיקים (כנ\"ל דף נ\"ט ד\"ה רחל) וכבר נתבאר בדבור הסמוך שסוד \u0003בן,\u0004 ה\"ס אור של תולדה, שזוכה בו קו האמצעי להיותו המכריע ומיחד הימין והשמאל. ולפיכך קראה לאה את בנה הראשון בשם ראו בן סתם, ולא בן ימין. משום שהשם \u0003בן,\u0004 יורה על קו האמצעי הזוכה את השיעור שגרם בעליון, בסוד \u0003תלת נפקי מחד חד בתלת קיימא,\u0004 ולפיכך רמזה את זה בבנה הראשון. וז\"ש, \u0003ראובן סתם, בגין דאתכליל בתלת סטרין מתחברן כחדא.\u0004 כי השם בן יורה על אור הנולד מכח התכללות ג' קוין, שגרם בעליון, שמשום זה זכה בהם גם התחתון בתלת. וע\"כ רמזה זה בבנה הראשון."],[5,"מאי טעמא לוי:","מהו הטעם שקראה את בן הג' בשם לוי. פירוש. כיון שראובן נקרא \u0003בן\u0004, על שם היותו קו אמצעי הכולל ג' הקוין, ואע\"פ שהוא עצמו הוא בחינת קו ימין בלבד, נק' \u0003בן\u0004 על שם ההתכללות. לפי\"ז מכל שכן לוי, שהוא קו אמצעי עצמו מבחינת הנשמות היה צריך לקראו \u0003בן,\u0004 ולמה נקרא לוי. ומשיב. שהשם לוי פירושו, כמו שאתה אומר, \u0003לויות,\u0004 שזה יורה שהיא החבור של כל הצדדים, דהיינו קו אמצעי המחבר יחד צד הימין וצד השמאל. הרי שהשם לוי יורה על קו אמצעי. ולפי\"ז נמצא, שהשם \u0003בן\u0004 יורה שאורו מחודש בסוד קו אמצעי המיחד לימין ושמאל, וכולל משום זה גם הוא עצמו את ג' הקוין. אמנם להורות על בחינת קו אמצעי של \u0003הבן\u0004 ביחוד, יורה רק השם \u0003לוי.\u0004"],[6,"אמר רבי יהודה:","מכאן, נשמע שכולל ג' הקוין, שכתוב, יתר שאת ויתר עז, ותרגומו הוא, \u0003בכירותא\u0004 שהוא קו אמצעי, \u0003כהונתא\u0004 שהוא קו ימין, \u0003מלכותא\u0004 שהוא קו שמאל, כי \u0003מלכות\u0004 בצד גבורה היא, ועל כן קראה אותו \u0003ראו בן\u0004 סתם. להורות שהוא כולל ג' קוין בסוד אור של תולדה כנ\"ל בדבור הסמוך."],[7,"אמר רבי אבא וכו':","אר\"א, ע\"כ אמרה ראו בן סתם, ולא בן ימין, משום שנכלל בשמעון ולוי, כי כן היה דעת לאה לכללו בב' בנים האחרים, שכתוב הפעם ילוה אישי אלי כי ילדתי לו שלשה בנים, שזה יורה שהם שלשה המתחברים כאחד. כלומר שכל אחד מהם כלול מכל השלשה, שראובן כלול מכולם וכן שמעון וכן לוי. וע\"כ לא יכלה לקרא אותו בן ימין. כי כלול ג\"כ משמאל."],[8,"ות\"ח דהכי הוא וכו':","ובוא וראה, שכן הוא, כי מרכבה העליונה היא האבות, אברהם יצחק ויעקב, ודוד המלך שנתחבר בהם. וכל הארבעה הללו, שהם מרכבות עליונות, הם סוד השם הקדוש הוי\"ה אשר יה\"ו ה\"ס האבות, דהיינו ג' הקוין, וה' אחרונה ה\"ס דוד המלך, דהיינו הנוקבא. ועל סוד הזה הם, ראובן, שמעון, לוי, שהם ג' קוין יה\"ו ואחר כך יהודה, שורש המלכות שה\"ס ה' אחרונה דשם הוי\"ה. ועל כן כולם הם במקום הזה, דהיינו בסוד המרכבה. וכמו שבמרכבה כלולים כל אחד מהם מג' הקוין, כן בשבטים כלול כל אחד מהם מג' הקוין."],[9,"וכתיב, הפעם אודה את ה' וגו', ותעמוד מלדת וגו':","הוא משום שכאן ביהודה נשתכללו ארבע עמודים של הכסא, שהם חסד וגבורה ות\"ת ומלכות, אשר ראובן ה\"ס חסד, ושמעון גבורה, ולוי ת\"ת, ויהודה מלכות. \u0003הפעם אודה את ה',\u0004 ושואל, מהו הטעם שאמרה בבן הזה אודה את ה' ולא בכל הבנים. ומשיב, אלא מכאן נשמע, שכל זמן שכנסת ישראל, דהיינו מלכות, היא בגלות, השם הקדוש אינו שלם, בוא וראה אע\"פ שג' בנים היו מטרם שהולידה ליהודה, שהם חג\"ת, לא נשלם הכסא, אלא עם יהודה שהוא מלכות נשלם הכסא. ומשום זה אמרה הפעם אודה את ה', ביהודה, ולא בכולם. ועל כן \u0003ותעמוד מלדת,\u0004 מהו פירושו של \u0003ותעמוד,\u0004 הוא, שהכסא \u0003עמד\u0004 על עמודיו כי עם יהודה נשלמו ד' עמודי הכסא שהם חגת\"מ. (ועי' לעיל פרשת וירא דף ה' ד\"ה פירוש)."]],[[0,"","בֹּא רְאֵה, הָעוֹלָם הַתַּחְתּוֹן הוּא בְּנִגְלֶה, וְהוּא רֵאשִׁית הַכֹּל לַעֲלוֹת בְּדַרְגוֹתָיו. כְּמוֹ שֶׁהַחָכְמָה הָעֶלְיוֹנָה הִיא רֵאשִׁית הַכֹּל, כָּךְ גַּם הָעוֹלָם הַתַּחְתּוֹן הוּא חָכְמָה, וְהִיא רֵאשִׁית הַכֹּל, וּמִשּׁוּם כָּךְ קוֹרְאִים אַתָּה, מִשּׁוּם שֶׁהוּא שְׁמִטָּה, וּבְגָלוּי."],[1,"","וְהָעוֹלָם הָעֶלְיוֹן, שֶׁהוּא הַיּוֹבֵל, קוֹרְאִים הוּא, שֶׁכָּל דְּבָרָיו הֵם בְּנִסְתָּר, וְסוֹד הַדָּבָר שֶׁל לֵאָה, שֶׁכָּתוּב וַיִּשְׁכַּב עִמָּהּ בַּלַּיְלָה הוּא, וְעַל זֶה כָּתוּב (במדבר יח) וְעָבַד הַלֵּוִי הוּא, כְּדֵי לִמְשֹׁךְ מִמֶּנּוּ בְּרָכוֹת לַכֹּל. הוּא - הָעוֹלָם הָעֶלְיוֹן שֶׁנִּסְתָּר תָּמִיד. וְיַעֲקֹב בְּמַה שֶּׁנִּסְתָּר לֹא נִדְבַּק בִּרְצוֹנוֹ, אֶלָּא בְּמַה שֶּׁנִּגְלֶה, וְזֶה סוֹד הַכָּתוּב וְדָבַק בְּאִשְׁתּוֹ."],[2,"","וַיַּרְא ה' כִּי שְׂנוּאָה לֵאָה. מִכָּאן שֶׁשּׂוֹנֵא אָדָם עֶרְוַת אִמּוֹ (ואחותו), וְיִתְיַחֵד אָדָם עִם אִמּוֹ בְּכָל מָקוֹם וְלֹא יַחְשֹׁשׁ, וַהֲרֵי הֵעִירוּ, בֵּן מִתְיַחֵד עִם אִמּוֹ. וְהַכֹּל הִתְכַּסָּה מִיַּעֲקֹב, שֶׁהָעוֹלָם הָעֶלְיוֹן לֹא הִתְגַּלָּה כְּלָל."],[3,"","בֹּא רְאֵה, בִּשְׁבִיל יַעֲקֹב הִתְקַיֵּם הָעוֹלָם. וְאִם תֹּאמַר, הִנֵּה בִּשְׁבִילוֹ שֶׁל אַבְרָהָם, כְּמוֹ שֶׁנֶּאֱמַר בְּהִבָּרְאָם, אַל תִּקְרֵי בְּהִבָּרְאָם אֶלָּא בְּאַבְרָהָם - אֶלָּא מִשּׁוּם יַעֲקֹב הִתְקַיֵּם אַבְרָהָם, שֶׁכָּתוּב (ישעיה כט) כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם. וּמִקֹּדֶם לָכֵן הָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹנֶה עוֹלָמוֹת וּמַחֲרִיבָם. כֵּיוָן שֶׁבָּא יַעֲקֹב, הִשְׁתַּכְלְלוּ מִמֶּנּוּ הָעוֹלָמוֹת וְלֹא נֶחְרְבוּ כְּבָרִאשׁוֹנָה. זֶהוּ שֶׁכָּתוּב כֹּה אָמַר ה' בֹּרַאֲךְ יַעֲקֹב וְיֹצֶרְךְ יִשְׂרָאֵל וְגוֹ'."],[4,"","בֹּא רְאֵה מַה כָּתוּב, (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל, וְכָתוּב שַׁלַּח אֶת בְּנִי וְיַעַבְדֵנִי. יִשְׂרָאֵל נִקְרָא בֵּן לַקָּדוֹשׁ-בָּרוּךְ-הוּא מִשּׁוּם שֶׁנִּדְבָּק בּוֹ, כְּמוֹ שֶׁנֶּאֱמַר מַה שְּׁמוֹ וּמַה שֵּׁם בְּנוֹ כִּי תֵדָע."],[5,"","כְּשֶׁלֵּאָה הוֹלִידָה אֶת רְאוּבֵן, מַה כָּתוּב? וַתִּקְרָא אֶת שְׁמוֹ רְאוּבֵן. רְאוּבֵן סְתָם, מִשּׁוּם שֶׁנִּכְלָל בִּשְׁלֹשָׁה צְדָדִים מְחֻבָּרִים יַחַד - שִׁמְעוֹן וְלֵוִי. מָה הַטַּעַם לֵוִי? כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ז) לֹיוֹת, הַחִבּוּר שֶׁל כָּל הַצְּדָדִים."],[6,"","אָמַר רַבִּי יְהוּדָה, מִכָּאן שֶׁכָּתוּב יֶתֶר שְׂאֵת וְיֶתֶר עָז, כְּתַרְגּוּמוֹ בְּכוֹרָה, כְּהֻנָּה וּמַלְכוּת. וְהַמַּלְכוּת הִיא בְּצַד הַגְּבוּרָה, וְעַל כֵּן רְאוּבֵן סְתָם."],[7,"","אָמַר רַבִּי אַבָּא, רְאוּ בֵן סְתָם, שֶׁנִּכְלָל בְּשִׁמְעוֹן וְלֵוִי. כָּךְ הָיְתָה דַעְתָּהּ (רצונה) שֶׁל לֵאָה, שֶׁכָּתוּב הַפַּעַם יִלָּוֶה אִישִׁי אֵלַי כִּי יָלַדְתִּי לוֹ שְׁלֹשָׁה בָנִים. מִשּׁוּם שֶׁהָיוּ שְׁלֹשָׁה שֶׁמִּתְחַבְּרִים יַחַד."],[8,"","וּבֹא וּרְאֵה שֶׁכָּאן הוּא, שֶׁהֲרֵי הַמֶּרְכָּבָה הָעֶלְיוֹנָה - הָאָבוֹת, וְדָוִד הַמֶּלֶךְ שֶׁהִתְחַבֵּר עִמָּם, וְכָל הָאַרְבַּע הֵם מֶרְכָּבוֹת עֶלְיוֹנוֹת, הַסּוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ. וְעַל כֵּן רְאוּבֵן שִׁמְעוֹן וְלֵוִי, אַחַר כָּךְ יְהוּדָה שֶׁיָּרַשׁ מַלְכוּת, וְעַל כֵּן כֻּלָּם בַּמָּקוֹם הַזֶּה."],[9,"","וְכָתוּב (זה אחר זה שכתוב) (בראשית כט) הַפַּעַם אוֹדֶה אֶת ה' וְגוֹ' וַתַּעֲמֹד מִלֶּדֶת. מִשּׁוּם שֶׁכָּאן נִשְׁלְמוּ אַרְבָּעָה עַמּוּדִים. הַפַּעַם אוֹדֶה אֶת ה', מָה הַטַּעַם אָמְרָה בְּזֶה אוֹדֶה אֶת ה', וְלֹא בְכֻלָּם? אֶלָּא מִכָּאן, שֶׁכָּל זְמַן שֶׁכְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת, הַשֵּׁם הַקָּדוֹשׁ אֵינוֹ שָׁלֵם. בֹּא רְאֵה, אַף עַל גַּב שֶׁשְּׁלֹשָׁה בָנִים הָיוּ עַד שֶׁהוֹלִידָה אֶת יְהוּדָה, הַכִּסֵּא לֹא הַשָּׁלֵם, וּמִשּׁוּם כָּךְ הַפַּעַם אוֹדֶה אֶת ה', וְלֹא בְכֻלָּם. וְעַל כֵּן וַתַּעֲמֹד מִלֶּדֶת. מַה זֶּה וַתַּעֲמֹד? שֶׁעָמַד הַכִּסֵּא עַל תּוֹמְכָיו."]]],[["(ותעמד עד הכא) וַתַּעֲמֹד, דְּהָא עַד הָכָא, וַתַּעֲמֹד בְּיִחוּדָא חַד, מִכָּאן וּלְתַתָּא עַלְמָא דְפִירוּדָא אִיהוּ. וְאִי תֵימָא אִינוּן תְּרֵין בְּנִין דְּאוֹלִידַת לְבָתַר, כְּגַוְונָא דָּא. לָא, דְּהָא אִינוּן תְּרִין בְּאִלֵּין אִתְחַבְּרוּ, בְּגִין דְּשִׁית סִטְרִין דְּעָלְמָא כְּחֲדָא אִינוּן.","וְתָא חֲזֵי, כֻּלְּהוּ תְּרֵיסַר שִׁבְטִין, תִּקּוּנֵי דִכְנֶסֶת יִשְׂרָאֵל בְּהַאי עַלְמָא נִינְהוּ, לְאִתְתַּקְּנָא נְהוֹרָא עִלָּאָה (ע\"ז ע\"א) אוּכְמָא כְּמָה דְאִתְחֲזֵי, וְלְאֲתָבָא עִקְּרָא דְכֹלָּא לְאַתְרֵיהּ. כֻּלְּהוּ עָלְמִין כְּגַוְונָא חַד קָיְימֵי, וּבְהַאי אִשְׁתַּכְלַל עַלְמָא תַּתָּאָה כְּגַוְונָא דְּעַלְמָא דִלְעֵילָא.","יִשָּׂשׂכָר זְבוּלוּן, הָכָא אִשְׁתַּכְלָלוּ שִׁית בְּנִין, שִׁית סִטְרִין דְּעַלְמָא. כְּגַוְונָא דָא, בְּנֵי הַשְּׁפָחוֹת אִינוּן אַרְבַּע, וְאִתְחַבְּרוּ בְּאִלֵּין. וְאִלֵּין אַרְבַּע קִשְׁרִין דְּמִתְחַבְּרָן בְּהוּ, וְאוּקְמוּהָ, וְעַל דָּא כְּתִיב, (מלכים א ז׳:כ״ה) וְכָל אֲחֹרִיהֶם בָּיְתָה, אַף עַל גַּב דִּבְנֵי שְׁפָחוֹת נִינְהוּ, בָּיְתָה.","רִבִּי חִזְקִיָה אָמַר, אִי הָכִי, הָא אִתְּמָר כָּל מַה דְּאוֹלִיד עַלְמָא תַּתָּאָה, פִּירוּדָא אִיהוּ, דְּהָא כְּתִיב, (בראשית ב׳:י׳) וּמִשָּׁם יִפָּרֶד, מַה תֵּימָא בְּיוֹסֵף וּבִנְיָמִין, אִי תֵימָא דְּעַלְמָא חַד בְּהַנֵּי, לָאו אִיהוּ. דְּהָא לָא נָפְקוּ מֵעַלְמָא עִלָּאָה, וְעַלְמָא תַּתָּאָה מַה דְּאוֹלִידַת אוֹלִידַת לְתַתָּא וְלָא לְעֵילָא, וְאִי הָכִי פִּירוּדָא אִיהוּ.","אֲתָא רִבִּי אַבָּא וּנְשָׁקֵיהּ. אָמַר לֵיהּ מִלָּה דָא סָתִים אִיהוּ, דְּהָא עַלְמָא עִלָּאָה אִתְתַּקַּן בִּתְרֵיסַר דְּאִינוּן מִדִּילֵיהּ. אֲבָל תָּא חֲזֵי, רָזָא דְמִלָּה, בְּכָל זִמְנָא צַדִּיק מֵעַלְמָא תַּתָּאָה נָפִיק וְעָיִיל, בֵּיהּ עָיִיל וּמִנֵּיהּ נָפִיק. וּבְגִין כָּךְ, אִתְבְּנֵי בְּאֲתַר דָּא, וְעִקָּרָא הוּא לְעֵילָא וְעִקָּרָא הוּא לְתַתָּא, (ס\"א צדיק ביה עייל ביה נפיק) וּבְעַלְמָא תַּתָּאָה אִיהוּ תָּדִיר לְעוֹלָם, כְּתִיב, (בראשית ל״ה:י״ח) וַיְהִי בְּצֵאת נַפְשָׁהּ כִּי מֵתָה."],[[0,"ותעמוד",": עוד יש לפרשו, כי עד עתה, דהיינו עד יהודה שהוא מלכות, \u0003ותעמוד\u0004 ביחוד אחד, מכאן ולמטה, דהיינו למטה ממלכות דאצילות, הוא עולם הפירוד. דהיינו ג' עולמות בי\"ע דפרודא. ואם תאמר, אלו ב' בנים שילדה אחר יהודה שהם יששכר וזבולון, הם כעין זה, דהיינו בחינת פירוד, כי נולדו אחר המלכות שהוא יהודה ומשיב, לא, כי אלו השנים יששכר זבולון נתחברו באלו בראובן שמעון לוי, כי שש קצוות העולם כאחד הם."],[0,"","פירוש. יששכר זבולון הם בחינת נצח והוד, והם אחד עם הגוף שהוא חג\"ת, כי ו\"ק של הגוף הם חג\"ת נה\"י, ולפי\"ז נמצא שיששכר זבולון, הם קודם המלכות, שהוא יהודה, כי הם דבוקים בחג\"ת, וע\"כ אינם בחינת פירוד. ויהודה שהיא מלכות כולל בתוכו גם יסוד."],[1,"ות\"ח כלהו תריסר וכו':","ובוא וראה, כל י\"ב השבטים הם תקונים דכנסת ישראל, שהיא פנימיות הנוקבא שמחזה ולמעלה דז\"א הנמשכת מבינה, בעולם הזה, שהיא הנוקבא שמחזה ולמטה דז\"א, כלומר להמשיך י\"ב התיקונים מעולם העליון שהיא בינה, לעולם התחתון שהיא הנוקבא. ובכללם הם ב' תקונים, א) לתקן אור העליון השחור כראוי. שה\"ס תקון השמאל, שבהיות החכמה בלי חסדים, היא אור שחור, שהוא סוד חשך דאמא, ב) ולהשיב עיקר הכל למקומו, שה\"ס תקון הימין, להשליט את החסדים, שהם בחינת עיקר, שזולתם אין שום הארה בעולמות, כי אפילו הארת השמאל הוא חשך ושחור זולתו כנ\"ל."],[1,"כלהו עלמין כגוונא וכו':","כל העולמות נמצאים באופן אחד, שכל מה שבעליון נמצא גם כן בתחתון, ובזה, דהיינו בי\"ב, נשתכלל עולם התחתון שהוא הנוקבא, כמו עולם העליון, שהוא בינה."],[2,"יששכר זבולון","הם נצח והוד, כאן נשתכללו ששה בנים, שהם שש קצוות העולם, כי ראובן שמעון לוי יהודה הם חגת\"מ, ויששכר זבולון הם נו\"ה. וה\"ס תקון הימין שהם ו\"ק דחסדים. כעין זה בני השפחות הם ארבעה, ונתחברו באלו הששה שהם ו\"ק והם ארבעה קשרים המתחברים בהם, ב' קשרים בחסד וגבורה, וב' קשרים בנצח והוד, כמ\"ש ענינם לעיל (בדף ס\"ג ד\"ה דהא ע\"ש) והם תקון השמאל, וכיון שנתחברו בימין, על כן כתוב, וכל אחוריהם ביתה, שהאחורים נעשה פנימיות (כמ\"ש שם) שאף על פי שהם בני השפחות, דהיינו בחינת חשך ואחורים, מכל מקום הם \u0003ביתה,\u0004 דהיינו פנימיות. ונתבאר סוד עשרת השבטים בסוד תיקון י\"ב, שהם תקון הימין ותקון השמאל, בסו\"ה ושמת אותם שתים מערכות וגו'. ששה בני לאה הם תקון הימין, וארבעה בני השפחות הם תקון השמאל. וב' בני רחל יתבארו לפנינו."],[3,"רבי חזקיה אמר וכו':","רח\"א, אם כן, הרי למדנו, כל מה שעולם התחתון שהיא הנוקבא שבסיום האצילות, מוליד, הוא בפירוד (כנ\"ל באות ק\"ס) כי כתוב, ומשם יפרד, ומה תאמר ביוסף ובנימין, אם תאמר, שעולם האחד באלו, דהיינו שהם בחינת יחוד מעולם האצילות, אינו כן, שהרי לא יצאו מעולם העליון, דהיינו מהנוקבא שמחזה ולמעלה, שהיא לאה, אלא שנולדו מעולם התחתון, שהיא רחל, שלמטה מחזה דז\"א, הנמצאת בסיום עולם האצילות. ולידה, פירושה, שהנשמה נמשכת ממעלה למטה, ונמצא שעולם התחתון מה שמוליד הוא מוליד למטה, דהיינו שתולדותיה הם למטה מסיום אצילות, ולא למעלה, ואם כן הם בפרוד דהיינו בעולם הבריאה דפרודא."],[4,"אתא רבי אבא וכו':","בא רבי אבא ונשקו. אמר לו, דבר זה הוא סתום, כי עולם העליון נתתקן בי\"ב שהם משלו. פירוש אף על פי שכבר נתקנו ב' מיני התקונים תקון הימין ותקון השמאל בבני לאה ובבני השפחות, שה\"ס תקון י\"ב כנ\"ל, אמנם תקון י\"ב הזה הוא סתום, כלומר, שנמצאים תחת שליטת חסדים מכוסים, \u0003דהא עלמא עלאה, אתתקן בתריסר דאנון מדיליה,\u0004 שתקון י\"ב של עולם העליון הם מבחינתו, דהיינו חסדים מכוסים. וכדי לגלות החסדים בהארת החכמה צריכים לתקון ב' עקרים, שה\"ס ב' צדיקים, בעולם התחתון שהוא רחל, שה\"ס חכמה תתאה. מטעם שמחכמה דא\"א עד מדרגת רחל נמצאת החכמה, בהעלם. (כנ\"ל בראשית א' דף רפ\"ב אות שנ\"ד ע\"ש)."],[4,"אבל ת\"ח רזא וכו':","אבל בוא וראה סוד הדבר. בכל פעם צדיק יוצא מעולם התחתון ונכנס, בו נכנס וממנו יוצא, ומשום זה הוא נבנה במקום הזה, ועיקר הוא למעלה ועיקר הוא למטה. ובעולם התחתון הוא תמיד, לעולם. שכתוב ויהי בצאת נפשה כי מתה."],[4,"","ביאור הדברים. כי ב' עקרים הם באור הזווג, שה\"ס רצוא ושוב, כמ\"ש לעיל (באות י\"ז) \u0003רצוא ושוב אינון נהורין, לא מתעכבן למחמי.\u0004 אשר \u0003רצוא\u0004 ה\"ס גלוי החכמה, והוא עיקר העליון, כלומר, המתגלה על ידי נה\"י דעליון שבנוקבא, שה\"ס יוסף (כנ\"ל דף ס' ד\"ה וזה). \u0003ושוב,\u0004 ה\"ס השפעת החסדים, (כנ\"ל באות י\"ז ע\"ש) והוא עיקר התחתון, דהיינו המתגלה על ידי נה\"י של הנוקבא עצמה, (כנ\"ל דף ס' ד\"ה וזה) שה\"ס בנימין, ע\"ש."],[4,"","וזה אמרו \u0003בכל זמנא צדיק מעלמא תתאה נפיק ועייל,\u0004 דהיינו שיש ב' ענינים בזווג, שהוא רצוא ושוב, \u0003ביה עייל ומניה נפיק,\u0004 שב' פעולות עושה בנוקבא, שבה נכנס לגלות החכמה, וממנה יוצא ומגלה החסדים. \u0003ובגין כך אתבני באתר דא,\u0004 ומשום זה נבנה במקום הזה, דהיינו בהנוקבא, ב' עקרים: \u0003ועקרא הוא לעילא,\u0004 דהיינו נה\"י שיש לה מהעליון, שה\"ס יוסף. \u0003ועקרא הוא לתתא,\u0004 דהיינו נה\"י מעצמות הנוקבא, שה\"ס בנימין. \u0003ובעלמא תתאה איהו תדיר, לעולם,\u0004 ועיקר התחתון שה\"ס בנימין נמצא תמיד בעולם התחתון, שכתוב \u0003ויהי בצאת נפשה כי מתה,\u0004 כי \u0003בנימין הצדיק,\u0004 היא נפשה עצמה של הנוקבא, דהיינו נה\"י דעצמותה, וע\"כ הוא תמיד בה, משא\"כ \u0003יוסף הצדיק,\u0004 שהוא נה\"י דעליון, המגלה בה החכמה, אינו בה תמיד כמ\"ש לעיל (באות י\"ז) \u0003לא מתעכבן למהמי,\u0004 אלא הוא \u0003ושוב\u0004 תכף. ע\"ש, ועיין להלן בדבור הסמוך, שהזהר בעצמו מרחיב הביאור."]],[[0,"","(ותעמד עד כאן) וַתַּעֲמֹד, שֶׁהִנֵּה עַד כָּאן וַתַּעֲמֹד, בְּיִחוּד אֶחָד. מִכָּאן וּלְמַטָּה הוּא עוֹלַם הַפֵּרוּד. וְאִם תֹּאמַר, אוֹתָם שְׁנֵי הַבָּנִים שֶׁהוֹלִידָה אַחַר כָּךְ כְּמוֹ זֶה? לֹא שֶׁהֲרֵי אוֹתָם הַשְּׁנַיִם הִתְחַבְּרוּ עִם אֵלּוּ, מִשּׁוּם שֶׁשֵּׁשֶׁת הַצְּדָדִים שֶׁל הָעוֹלָם הֵם יַחַד."],[1,"","וּבֹא וּרְאֵה, כָּל שְׁנֵים עָשָׂר הַשְּׁבָטִים הֵם תִּקּוּנֶיהָ שֶׁל כְּנֶסֶת יִשְׂרָאֵל בָּעוֹלָם הַזֶּה, לְתַקֵּן הָאוֹר הָעֶלְיוֹן הַשָּׁחֹר כְּמוֹ שֶׁרָאוּי, וּלְהָשִׁיב אֶת עִקַּר הַכֹּל לִמְקוֹמוֹ. כָּל הָעוֹלָמוֹת כְּמוֹ אֶחָד עוֹמְדִים, וּבָזֶה נִשְׁלָם הָעוֹלָם הַתַּחְתּוֹן כְּמוֹ שֶׁהָעוֹלָם שֶׁלְּמַעְלָה."],[2,"","יִשָּׂשכָר זְבֻלוּן, כָּאן נִשְׁלְמוּ שִׁשָּׁה בָנִים, שֵׁשֶׁת הַצְּדָדִים שֶׁל הָעוֹלָם. כְּמוֹ כֵן בְּנֵי הַשְּׁפָחוֹת הֵם אַרְבַּע, וְהִתְחַבְּרוּ עִם אֵלּוּ, וְאֵלּוּ אַרְבַּעַת הַקְּשָׁרִים שֶׁמִּתְחַבְּרִים בָּהֶם, וּבֵאֲרוּהָ. וְעַל כֵּן כָּתוּב (מלכים א ז) וְכָל אֲחֹרֵיהֶם בָּיְתָה. אַף עַל גַּב שֶׁבְּנֵי שְׁפָחוֹת הֵם - בָּיְתָה."],[3,"","רַבִּי חִזְקִיָּה אָמַר, אִם כָּךְ, הֲרֵי נֶאֱמַר, כָּל מַה שֶּׁהוֹלִיד הָעוֹלָם הַתַּחְתּוֹן הוּא פֵּרוּד, שֶׁהֲרֵי כָּתוּב וּמִשָּׁם יִפָּרֵד. מַה תֹּאמַר בְּיוֹסֵף וּבִנְיָמִין? אִם תֹּאמַר שֶׁעוֹלָם אֶחָד בְּאֵלֶּה - זֶה אֵינוֹ, שֶׁהֲרֵי לֹא יָצְאוּ מִן הָעוֹלָם הָעֶלְיוֹן, וְהָעוֹלָם הַתַּחְתּוֹן - מַה שֶּׁהוֹלִיד, הוֹלִיד לְמַטָּה וְלֹא לְמַעְלָה, וְאִם כָּךְ הוּא פֵּרוּד."],[4,"","בָּא רַבִּי אַבָּא וּנְשָׁקוֹ. אָמַר לוֹ, דָּבָר זֶה הוּא נִסְתָּר, שֶׁהֲרֵי הָעוֹלָם הָעֶלְיוֹן הִתְתַּקֵּן בִּשְׁנֵים עָשָׂר שֶׁל אוֹתָם מִשֶּׁלּוֹ. אֲבָל בֹּא רְאֵה סוֹד הַדָּבָר, בְּכָל זְמַן הַצַּדִּיק מֵהָעוֹלָם הַתַּחְתּוֹן יוֹצֵא וְנִכְנָס, בּוֹ נִכְנָס וּמִמֶּנּוּ יוֹצֵא, וּמִשּׁוּם כָּךְ נִבְנֶה בַּמָּקוֹם הַזֶּה, וְהָעִקָּר הוּא לְמַעְלָה, וְהָעִקָּר הוּא לְמַטָּה, (צדיק, בו נכנס בו יוצא) וְהוּא תָּמִיד בָּעוֹלָם הַתַּחְתּוֹן לְעוֹלָם, כָּתוּב וַיְהִי בְּצֵאת נַפְשָׁהּ כִּי מֵתָה."]]],[["תָּא חֲזֵי בְּהַאי עַלְמָא תַּתָּאָה, צַדִּיק (שמות רנ\"ט ע\"א) בֵּיהּ עָיִיל וּמִנֵּיהּ נָפִיק, כַּד עֲיִּיל, אִיהוּ בְּרָזָא דְיוֹסֵף הַצַּדִּיק, כַּד נָפִיק בְּרָזָא דְּבִנְיָמִין הֲדָא הוּא דִכְתִיב, (בראשית ל״ה:י״ח) וַיְהִי בְּצֵאת נַפְשָׁהּ כִּי מֵתָה, מַאן נַפְשָׁהּ, דָּא צַדִּיק דְּנָפִיק מִנָּהּ.","וְדָא בִּנְיָמִין, נִקְרָא בֶּן אוֹנִי, דְּחֲשִׁיבַת דְּאוֹלִידַת לְתַתָּא בְּעַלְמָא דְּפִירוּדָא, וְאִשְׁתָּאֲרוּ חַד סָרֵי בְּאִינוּן לְעֵילָא. מַה כְּתִיב וְאָבִיו קָרָא לוֹ בִּנְיָמִין בֶּן יָמִין, דְּהָא אִסְתַּלַּק לְעֵילָא בְּעַלְמָא עִלָּאָה. דְּכַד אִתְאֲבִיד יוֹסֵף, בִּנְיָמִין (קנ\"ג ע\"ב) אַשְׁלִים אַתְרִיהּ. וְעַל דָּא צַדִּיק בְּעַלְמָא תַּתָּאָה עָיִיל וְנָפַק, בְּגִין כָּךְ יוֹסֵף וּבִנְיָמִין וְכֻלְּהוּ תְּרִיסַר, כְּגַוְונָא דִלְעֵילָא בְּיִחוּדָא חַד.","(בראשית כ״ט:ל״ה) הַפַּעַם (קע\"ח ע\"ב) אוֹדֶה אֶת ה', רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (תהילים קי״א:א׳) אוֹדֶה ה' בְּכָל לֵבָב בְּסוֹד יְשָׁרִים וְעֵדָה, בְּכָל לֵבָב, בְּכָל לֵב מִבָּעֵי לֵיהּ. אֶלָּא, דָּוִד בְּרָזָא עִלָּאָה דִשְׁמָא קַדִּישָׁא, קָא בָּעֵי לֵיהּ לְאוֹדָאָה לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, אוֹדֶה ה' בְּכָל לֵבָב בְּיֵצֶר טוֹב וּבְיֵצֶר רָע, וְאִלֵּין תְּרֵין סִטְרִין, חַד יָמִינָא וְחַד שְׂמָאלָא.","בְּסוֹד יְשָׁרִים וְעֵדָה, אִלֵּין אִינוּן שְׁאָר סִטְרִין דְּהַאי עַלְמָא, דְּהָא לֵבָב, כְּגַוְונָא דְדָרוֹם וְצָפוֹן. בְּסוֹד יְשָׁרִים, אִלֵּין אִינוּן שְׁאָר סִטְרֵי עַלְמָא, דְּאִינוּן שִׁית כְּגַוְונָא דִלְעֵילָא. וְעֵדָה, דָּא הוּא אֲתַר דִּיהוּדָה, וּכְתִיב, (תהילים קל״ב:י״ב) וְעֵדוֹתִי זוֹ אֲלַמְּדֵם.","וּכְתִיב, (הושע י״ב:א׳) וִיהוּדָה עוֹד רָד עִם אֵל וְגו'. כְּתִיב (תהילים קל״ח:א׳) אוֹדְךָ בְּכָל לִבִּי נֶגֶד אֱלהִים אֲזַמְּרֶךָּ, הָכָא בְּאֲתַר חַד קָאֲמַר, דִּכְתִיב נֶגֶד אֱלהִים אֲזַמְּרֶךָּ. דְּהָא לְגַבֵּי הַאי דַרְגָּא קָאֲמַר שִׁירָתָא, לְחַבְּרָא לֵיהּ בִּימִינָא.","תָּא חֲזֵי, יְהוּדָה אָחִיד בְּכָל סִטְרִין, אָחִיד בְּדָרוֹם וְאָחִיד בְּמִזְרָח. דְּהָא אִיהוּ מִסְּטַר שְׂמָאלָא קָא אַתְיָא, (שמות רכ\"ג ע\"א) וְשֵׁירוּתֵיהּ בַּצָּפוֹן וְאָחִיד בְּדָרוֹם, בְּגִין דְּאִיהוּ אָזִיל לִימִינָא וְאִתְאֲחִיד בְּגוּפָא, בְּגִין כָּךְ (בראשית כ״ט:ל״ה) הַפַּעַם אוֹדֶה אֶת ה'. וַתַּעֲמֹד מִלֶּדֶת, וַתַּעֲמֹד, דְּקָיְימָא בְּקִיּוּמָא דְּקָיְימָא כְּדְקָא יָאוֹת, דְּהָא אִתְתַּקַּן כֹּלָּא רְתִיכָא קַדִּישָׁא.","רַבִּי שִׁמְעוֹן נָפַק לְקִרְיָיתָא, אִזְדַּמַּן לֵיהּ רַבִּי אַבָּא וְרַבִּי חִיָּיא וְרַבִּי יוֹסֵי, כֵּיוָן דְּחָמָא לוֹן, אָמַר חַדְּתוּתֵי דְאוֹרַיְיתָא אִצְטְרִיךְ הָכָא, יָתְבוּ תְּלָתָא אִלֵּין, (ס\"א יומין) כַּד בָּעָא לְמֵיזַל, פָּתַח כָּל חַד וְחַד קְרָא.","רִבִּי אַבָּא פָּתַח וְאָמַר, (בראשיתיג) וַה' אָמַר אֶל אַבְרָם אַחֲרֵי הִפָּרֶד לוֹט מֵעִמּוֹ וְגו', שָׂא נָא עֵינֶיךָ וּרְאֵה וְגו'. וְכִי לְפוּם חֵיזוּ דְאַבְרָהָם יָרִית אַרְעָא וְלָא יַתִּיר. עַד כַּמָּה חָמֵי בַּר נָשׁ, תְּלַת פַּרְסֵי אוֹ אַרְבַּע אוֹ חָמֵשׁ פַּרְסֵי, וְאִיהוּ אָמַר (בראשית י״ג:ט״ו) כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רוֹאֶה וְגו'.","אֶלָּא, כֵּיוָן דְּאַרְבַּע סִטְרִין דְּעַלְמָא חָמֵי, כָּל אַרְעָא חָמֵי. דְּהָא אַרְבַּע סִטְרֵי דְעָלְמָא, כְּלָלָא דְכָל עָלְמָא. תוּ, זְקַף לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא עַל אַרְעָא דְיִשְׂרָאֵל, וְאַחְמֵי לֵיהּ דְּאִיהִי קְשִׁירָא בְּסִטְרֵי דְעַלְמָא, וְהֲוָה חָמֵי כֹּלָּא. כְּגַוְונָא דָא, מַאן דְּחָמֵי לֵיהּ לְרַבִּי שִׁמְעוֹן, כָּל עַלְמָא חָמֵי, חֶדְוָותָא דְּעֵילָא וְתַתָּא."],[[0,"ת\"ח בהאי עלמא תתאה וכו':","בוא וראה, בעולם הזה התחתון, שהוא הנוקבא, הצדיק, בו נכנס וממנה יוצא. כשהוא נכנס הוא בסוד יוסף הצדיק, כשיוצא הוא בסוד בנימין הצדיק, וז\"ש, ויהי בצאת נפשה כי מתה, ושואל מי הוא נפשה, ומשיב, זהו הצדיק שיוצא ממנה. ופירוש הדברים כבר נתבאר היטב לעיל בדבור הסמוך."],[1,"ודא בנימין נקרא בו':","ועל כן נקרא בנימין בן אוני, משום שחשבה, שהולידה אותו למטה מאצילות, בעולם הפירוד, ונשארו עשתי עשרה באלו השבטים של מעלה, דהיינו שבאצילות, מה כתוב, ואביו קרא לו בנימין, שפירושו בן ימין, כי נסתלק למעלה בעולם העליון, כי כשנאבד יוסף, בנימין מלא את מקומו."],[1,"","פירוש. כי מסיים כאן את התירוץ על הקושיא הנ\"ל (שבאות קס\"ג) שהקשה רבי חזקיה, \u0003מה תימא ביוסף ובנימין וכו':\u0004 שהקשה, כיון שיוסף ובנימין נולדו מן הנוקבא המסיימת את האצילות, וכל לידה בהכרח הוא ממעלה למטה והתולדה הוא למטה מהמולידים ונמצא בהכרח שיוסף ובנימין כבר הם נמצאים למטה מהנוקבא, שהוא למטה מסיום אצילות. דהיינו בעולם הפירוד. וזהו שהשיב לו רבי אבא. ומתחילה ביאר סוד ב' צדיקים עליון ותחתון הנמצאים בנוקבא, שפירושם ב' בחינות נה\"י, א) הם נה\"י דעליון דז\"א, שנתדבקו בהנוקבא, שהם בחינת יוסף הצדיק, ב) נה\"י דנוקבא עצמה, שהם בחינת בנימין הצדיק. ולפ\"ז, כבר נדחה הקושיא מיוסף, כי יוסף הצדיק, אע\"פ שנולד מן הנוקבא, מ\"מ הוא מן נה\"י דז\"א שנדבקו בנוקבא, ולא מנה\"י דנוקבא המסיימים האצילות, וע\"כ עוד הוא נמצא בעולם אצילות. ונמצא שהקושיא הוא רק על בנימין לבד, להיותו נמשך מנה\"י דעצמות הנוקבא המסיימים האצילות. וזהו שמתרץ כאן, ואומר, \u0003ודא בנימין נקרא בן אוני דחשיבת דאולידת לתתא בעלמא דפרודא וכו':\u0004 כי ע\"כ, משום שנמשך מנה\"י דנוקבא המסיימים האצילות, קראה אותו אמו \u0003בן אוני,\u0004 כי חשבה שהוא בעולם הפירוד. אבל \u0003מה כתיב ואביו קרא לו בן ימין, דהא אסתלק לעילא בעלמא עלאה\u0004 כי אחר לידתו מנה\"י דנוקבא, עלה ונמתק למעלה בעולם העליון שהוא בינה, דהיינו שעלה ונכלל בנה\"י דעליון ונעשה בחינת נה\"י דעליון, דז\"א, כמו יוסף, וע\"כ \u0003דכד אתאביד יוסף בנימין אשלים אתריה,\u0004 דהיינו שנעשה בחינת יסוד דז\"א כמו יוסף. פירוש. כי מסכת מכירת יוסף, אבד צדיק העליון, כלומר, שנעלמו המוחין דגדלות, המושפעים על ידי הצדיק העליון שהוא יוסף, ואז לא השפיע ז\"א אל דנוקבא רק בחי' מוחין דחסדים, שה\"ס ו\"ק, להחיות העולמות, שהם מושפעים ע\"י בנימין, כנ\"ל וז\"ס דכד אתאביד יוסף, בנימין אשלים אתריה וע\"כ קראו אביו בן ימין, שפירושו חסדים הבאים מימין. ומתורץ קושית רבי חזקיה, שהרי גם בנימין חזר ונקשר בנה\"י דעליון דז\"א, וע\"כ נמצא גם הוא בעולם האצילות ולא בפרודא."],[1,"ועל דא צדיק וכו':","וע\"כ בעולם התחתון, הצדיק נכנס ויוצא, וע\"כ יוסף ובנימין וכל י\"ב השבטים הם כמו הי\"ב של מעלה, ביחוד אחד. אשר ששה בני לאה ה\"ס חג\"ת נה\"י. וד' בני השפחות ה\"ס ד' קשרים דהיינו קשר האמצעי מסוד השורק שבכל אחד מחו\"ג ונו\"ה. וב' בני רחל ה\"ס ב' צדיקים, שה\"ס המשפיעים במוחין דגדלות בזווג ישראל ורחל."],[2,"הפעם אודה את ה' וכו':","ר\"ש פתח ואמר. אודה את ה' בכל לבב וגו'. ושואל, כתוב, \u0003בכל לבב,\u0004 בכל לב, היה צריך לומר, ומשיב, אלא דוד, בסוד העליון של השם הקדוש \u0003הויה,\u0004 רצה להודות אל הקב\"ה. \u0003אודה ה' בכל לבב,\u0004 פירושו ביצר הטוב וביצר הרע, שהם ב' לבבות, דהיינו בב' היצרים השוכנים בלב, ואלו הם ב' צדדים, ימין ושמאל."],[3,"בסוד ישרים ועדה:","אלו הם שאר הצדדים שבעולם הזה, שהוא הנוקבא, כי \u0003לבב\u0004 פירושו כמו דרום וצפון, שהם חסד וגבורה, \u0003בסוד ישרים,\u0004 אלו הם שאר הצדדים שבעולם, שהם שש קצוות, כעין של מעלה, דהיינו חג\"ת נה\"י, ונמצא \u0003בסוד ישרים\u0004 היינו תנה\"י. \u0003ועדה,\u0004 זה הוא המקום של יהודה, דהיינו מלכות, וכתוב ועדותי זו אלמדם, שפירושו תורה שבעל פה, שהיא המלכות."],[4,"וכתיב ויהודה עוד רד עם אל:","שפירושו יהודה שהיא המלכות המחוברת בהוי\"ה, ירד משם \u0003הוי\"ה\u0004 הכולל שית סטרין, אל שם \u0003אל\u0004 דהיינו שם המלכות. בסו\"ה ואל זועם בכל יום. וכתוב אודך בכל לבי נגד אלקים אזמרך, וכאן במקום אחד אמר, שכתוב, נגד אלקים אזמרך. דהיינו לשם אלקים ולא לשם הוי\"ה, כי אמר שירה למדרגה הזו למדרגת המלכות הנקראת אלקים, כדי לחבר אותה בצד ימין בחסדים. ולפיכך כתוב כאן אודך בכל לבי, ולא בכל לבבי, כי רק במקום אחד אמר שירה דהיינו בעת שהמלכות בשמאל, ואינה דבוקה בשם הויה."],[5,"ת\"ח יהודה וכו':","בוא וראה, השם יהודה אוחז בכל הצדדים, אוחז בדרום, ואוחז במזרח. פירוש. כי ביהודה יש השם הוי\"ה, ופירושו הודאה, והוא כמו הכתוב הנ\"ל, אודה הוי\"ה בכל לבב. ששם הויה כולל לכל הצדדים כנ\"ל. כי הוא יהודה, בא מצד שמאל, כי יהודה הוא הנוקבא הנבנית מצד שמאל, (כנ\"ל ב\"א דף נ\"ד ד\"ה לילה) ונמצא התחלתו הוא בצפון, ואוחז בדרום, משום שהולך לצד ימין, שהוא חסד, ונאחז בגוף, שהוא ת\"ת. הרי שאוחז בכל הצדדים. משום זה כתוב, הפעם אודה את הוי\"ה, שזה יורה שכולל לכל הצדדים. \u0003ותעמוד מלדת,\u0004 ותעמוד, פירושו, שעמדה בקיומה, שעמדה כראוי, כי עתה, שהולידה ד' בנים, שהם ראובן שמעון לוי ויהודה, שהם חגת\"מ נתתקנה כל המרכבה הקדושה. שהיא חסד גבורה ת\"ת מלכות."],[6,"רבי שמעון נפק וכו':","רבי שמעון יצא אל הכפר. נזדמן לו ר' אבא, ור' חייא, ור' יוסי, כיון שראה אותם, אמר, חידושי תורה צריכים לשמוע כאן. ישבו עמו אלו שלשה, כשרצה ר' שמעון ללכת מהם, פתח כל אחד ואחד מקרא, לכבוד ר' שמעון."],[7,"ר' אבא פתח וכו':","ר\"א פתח ואמר. וה' אמר אל אברם אחר הפרד לוט מעמו וגו' שא נא עיניך וראה וגו', ושואל, וכי לפי שיעור הראיה של אברהם, ירש הארץ הלא עד כמה רואה האדם, עד שלש פרסאות או ארבע או חמש פרסאות, והכתוב אומר, כי את כל הארץ אשר אתה רואה וגו'."],[8,"","ומשיב, \u0003אלא כיון\u0004 שראה ארבע רוחות העולם, כמ\"ש צפונה ונגבה וקדמה וימה, ראה את כל הארץ. כי ארבע רוחות העולם הן כלל כל העולם, עוד פירוש. כי זקף אותו הקב\"ה על ארץ ישראל. שה\"ס הנוקבא, והראה אותו שהיא קשורה ברוחות העולם שה\"ס חו\"ב תו\"מ דז\"א, שה\"ס המרכבה, ואז ראה הכל. כמו זה, מי שרואה את ר' שמעון, רואה את כל העולם. כי גם הוא כולל את כל העולם, הוא השמחה של מעלה ושל מטה."]],[[0,"","בֹּא רְאֵה, בָּעוֹלָם הַתַּחְתּוֹן הַזֶּה, הַצַּדִּיק נִכְנָס בּוֹ וּמִמֶּנּוּ יוֹצֵא. כְּשֶׁנִּכְנָס הוּא בְּסוֹד שֶׁל יוֹסֵף הַצַּדִּיק, וּכְשֶׁיּוֹצֵא הוּא בְּסוֹד שֶׁל בִּנְיָמִין. זֶהוּ שֶׁכָּתוּב וַיְהִי בְּצֵאת נַפְשָׁהּ כִּי מֵתָה. מִי נַפְשָׁהּ? זֶה הַצַּדִּיק שֶׁיּוֹצֵא מִמֶּנָּה."],[1,"","וְזְהִ בִּנְיָמִין, נִקְרָא בֶּן אוֹנִי, שֶׁחָשְׁבָה שֶׁהוֹלִידָה לְמַטָּה בְּעוֹלַם הַפֵּרוּד, וְנִשְׁאֲרוּ אַחַד עָשָׂר בְּאוֹתָם לְמַעְלָה. מַה כָּתוּב? וְאָבִיו קָרָא לוֹ בִּנְיָמִין, בֶּן יָמִין. שֶׁהֲרֵי הִתְעַלָּה לְמַעְלָה בָּעוֹלָם הָעֶלְיוֹן. שֶׁכַּאֲשֶׁר נֶאֱבַד יוֹסֵף, בִּנְיָמִין הִשְׁלִים אֶת מְקוֹמוֹ. וְעַל כֵּן הַצַּדִּיק נִכְנָס וְיוֹצֵא בָּעוֹלָם הַתַּחְתּוֹן. מִשּׁוּם כָּךְ יוֹסֵף וּבִנְיָמִין וְכָל הַשְּׁנֵים עָשָׂר, כְּמוֹ שֶׁלְּמַעְלָה בְּיִחוּד אֶחָד."],[2,"","הַפַּעַם אוֹדֶה אֶת ה'. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (תהלים קיא) אוֹדֶה ה' בְּכָל לֵבָב בְּסוֹד יְשָׁרִים וְעֵדָה. בְּכָל לֵבָב? בְּכָל לֵב הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא דָּוִד בְּסוֹד עֶלְיוֹן שֶׁל הַשֵּׁם הַקָּדוֹשׁ רָצָה לְהוֹדוֹת לַקָּדוֹשׁ-בָּרוּךְ-הוּא. אוֹדֶה ה' בְּכָל לֵבָב - בְּיֵצֶר טוֹב וּבְיֵצֶר רַע, וְאֵלּוּ שְׁנֵי הַצְּדָדִים, אֶחָד יָמִין וְאֶחָד שְׂמֹאל."],[3,"","בְּסוֹד יְשָׁרִים וְעֵדָה - אֵלּוּ הֵם שְׁאָר הַצְּדָדִים שֶׁל הָעוֹלָם הַזֶּה, שֶׁהֲרֵי לֵבָב כְּמוֹ צָפוֹן וְדָרוֹם. בְּסוֹד יְשָׁרִים - אֵלּוּ הֵם שְׁאָר צִדְדֵי הָעוֹלָם, שֶׁהֵם שִׁשָּׁה כְּמוֹ שֶׁלְּמַעְלָה. וְעֵדָה - זֶהוּ הַמָּקוֹם שֶׁל יְהוּדָה, וְכָתוּב (תהלים קלב) וְעֵדתִי זוֹ אֲלַמְּדֵם."],[4,"","וְכָתוּב (הושע יב) וִיהוּדָה עֹד רָד עִם אֵל וְגוֹ'. כְּתִיב (תהלים קלח) אוֹדְךְ בְכָל לִבִּי נֶגֶד אֱלֹהִים אֲזַמְּרֶךָּ. כָּאן בְּמָקוֹם אֶחָד נֶאֱמַר, שֶׁכָּתוּב נֶגֶד אֱלֹהִים אֲזַמְּרֶךָּ, שֶׁהֲרֵי לַדַּרְגָּה הַזּוֹ אָמַר שִׁירָה, לְחַבֵּר אוֹתָהּ לְיָמִין."],[5,"","בֹּא רְאֵה, יְהוּדָה אָחוּז בְּכָל הַצְּדָדִים. אָחוּז בַּדָּרוֹם, אָחוּז בַּמִּזְרָח. שֶׁהֲרֵי הוּא בָּא מִצַּד הַשְּׂמֹאל, וְרֵאשִׁיתוֹ בַּצָּפוֹן, וְאָחוּז בַּדָּרוֹם, מִשּׁוּם שֶׁהוּא הוֹלֵךְ לְיָמִין וְנֶאֱחָז בַּגּוּף. מִשּׁוּם כָּךְ, הַפַּעַם אוֹדֶה אֶת ה'. וַתַּעֲמֹד מִלֶּדֶת. וַתַּעֲמֹד, שֶׁעָמְדָה בַּקִּיּוּם שֶׁל הַבְּרִית כָּרָאוּי, שֶׁהֲרֵי הַכֹּל נִתְקַן מֶרְכָּבָה קְדוֹשָׁה."],[6,"","רַבִּי שִׁמְעוֹן יָצָא לַקִּרְיָה. הִזְדַּמֵּן לוֹ רַבִּי אַבָּא וְרַבִּי חִיָּיא וְרַבִּי יוֹסֵי. כֵּיוָן שֶׁרָאָה אוֹתָם, אָמַר, הִתְחַדְּשׁוּת שֶׁל הַתּוֹרָה צָרִיךְ כָּאן. יָשְׁבוּ שְׁלֹשֶׁת אֵלֶּה (ימים). כְּשֶׁרָצָה לָלֶכֶת, פָּתַח כָּל אֶחָד מֵהֶם בְּפָסוּק."],[7,"","רַבִּי אַבָּא פָּתַח וְאָמַר, וַה' אָמַר אֶל אַבְרָם אַחֲרֵי הִפָּרֶד לוֹט מֵעִמּוֹ, שָׂא נָא עֵינֶיךְ וּרְאֵה וְגוֹ'. וְכִי לְפִי הָרְאִיָּה שֶׁל אַבְרָהָם יוֹרֵשׁ אֶת הָאָרֶץ, וְלֹא יוֹתֵר? עַד כַּמָּה רוֹאֶה בֶּן אָדָם? שָׁלֹשׁ פַּרְסָאוֹת, אוֹ אַרְבַּע אוֹ חָמֵשׁ פַּרְסָאוֹת, וְהוּא אוֹמֵר כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רֹאֶה וְגוֹ'?!"],[8,"","אֶלָּא, כֵּיון שֶׁאַרְבַּעַת הַצְּדָדִים שֶׁל הָעוֹלָם רוֹאֶה, אֶת כָּל הָאָרֶץ רוֹאֶה. שֶׁהֲרֵי אַרְבַּעַת הַצְּדָדִים שֶׁל הָעוֹלָם הֵם כְּלָלוֹ שֶׁל כָּל הָעלָם. עוֹד, הֵרִים אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אֶרֶץ יִשְׂרָאֵל וְהֶרְאָה לוֹ שֶׁהִיא קְשׁוּרָה בִּצִדְדֵי הָעוֹלָם, וְהָיָה רוֹאֶה אֶת הַכֹּל. כְּמוֹ כֵן, מִי שֶׁרוֹאֶה אֶת רַבִּי שִׁמְעוֹן, רוֹאֶה אֶת כָּל הָעוֹלָם, הַשִּׂמְחָה שֶׁל מַעְלָה וּמַטָּה."]]],[["פָּתַח רִבִּי חִיָּיא וְאָמַר (בראשית כ״ח:י״ג-י״ד) הָאָרֶץ אֲשֶׁר אַתָּה שׁוֹכֵב עָלֶיהָ לְךָ אֶתְּנְנָּה וּלְזַרְעֶךָ, וְכִי הַהוּא אֲתַר בִּלְחוֹדוֹי אַבְטַח לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, דְּהָא אַרְבַּע אַמִּין אוֹ חַמְשָׁא הֲווּ וְלָא יַתִּיר. אֶלָּא, בְּזִמְנָא הַהוּא, בְּאִינוּן אַרְבַּע אַמִּין, כָּפִיל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא כָּל אַרְעָא דְיִשְׂרָאֵל. אִשְׁתַּכַּח הַהוּא אֲתַר כְּלָלָא דְכָל אַרְעָא, וּמַה הַהוּא אֲתַר אִיהוּ כְּלָלָא דְכָל אַרְעָא, רִבִּי שִׁמְעוֹן דְּאִיהוּ בּוּצִינָא דְכָל אַרְעָא, עַל אַחַת כַּמָּה וְכַמָּה דְּשָׁקִיל כְּכָל עַלְמָא.","פָּתַח רִבִּי יוֹסֵי וְאָמַר, הַפַּעַם אוֹדֶה אֶת ה', וְכִי בְּכֻלְּהוּ דְּאוֹלִידַת, לָא אִתְחֲזֵי לְאוֹדָאָה לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא אֶלָּא בְּהַאי. אֶלָּא יְהוּדָה אִיהוּ בְּרָא רְבִיעָאָה לְכֻּרְסְיָיא, וְאִיהוּ אַשְׁלִים לְכֻּרְסְיָיא. וּבְגִין כָּךְ, יְהוּדָה בִּלְחוֹדוֹי, תִּקּוּנָא דְכֻּרְסְיָיא וּסְמָכָא דְּכֻלְּהוּ סְמָכִין. (נ\"א דהוו תלת, אברהם ויצחק ויעקב וכדין אתא דוד מיהודה ואשלים לכרסייא, ועל כך אקרי יהודה דאיהו שמא קדישא והדל\"ת (ס\"א ד' רגלוהי) מרגלוהי דכורסייא) רִבִּי שִׁמְעוֹן דְּנָהִיר כָּל עַלְמָא בְּאוֹרַיְיתָא וְכַמָּה בּוּצִינִין נָהֲרִין בְּגִינֵיהּ, עַל אַחַת כַּמָּה וְכַמָּה.","מַתְּנִיתִּין. בְּנֵי עֶלְיוֹן, קַדִּישֵׁי עֶלְיוֹנִין, בְּרִיכָן (ס\"א ברירן) דְּעָלְמָא, מוֹחָא דֶּאֱגוֹזָא. כְּנָשׁוּ לְמִנְדַע, הָא צִּפֳּרָא נָחִיתּ בְּכָל יוֹמָא, אִתְּעַר בְּגִנְתָּא. שַׁלְהוֹבָא דְּנוּרָא בְּגַדְפָּהָא. בִּידָהָא תְּלָתָּא מַגְרוֹפְּיָין שְׁנִינָן כְּחַרְבָּא. מַפְּתְּחָן גְּנִיזִין בִּידָא יְמִינָא.","קָרֵי בְחָיִל וְאָמַר, מַאן מִנְּכוֹן דִּי נְהִירוּ אַנְפּוֹי, דִּי עָאל וְנָפַּק וְאִתְּתַּקִּיף בְּאִילָנָא דְחַיֵּי, מָטָא בְּעַנְפּוֹי, אָחִיד בְּשָׁרְשׁוֹי, אָכִיל מֵאִיבֵּיהּ מָתִּיק מִדּוּבְשָׁא, יָהִיב חַיִּין לְנַפְּשָׁא, אַסְוָותָּא לְגַרְמֵיהּ.","אִסְתַּמַּר מֵהִרְהוּרָא בִּישָׁא, מֵהִרְהוּרָא דִּמְשַׁקֵּר בְּאִילָנָא דְחַיֵּי, מַסְאִיב נַהֲרָא וְנַחֲלָא מְקוֹרָא דְיִשְׂרָאֵל, דִּיהֵיב מוֹתָּא לְנַפְּשָׁא, וּתְּבִירוּ לְגַרְמֵיהּ לֵיתּ לֵיהּ קִיּוּמָא כְּלָל.","הִרְהוּרָא דְּמַסְאִיב הַהוּא מְקוֹרָא דִילֵיהּ, עָבִיד אִילָנָא דְשִׁקְרָא, בְּגִין דְּהַהוּא הִרְהוּרָא סָלְקָא, וְאַחְלַף נַפְּשָׁא תְּחוֹתּ נַפְּשָׁא. אִילָנָא דְחַיֵּי אִסְתַּלַּק, וְאִילָנָא דְמוֹתָּא אִתְּתַּקִּיף בֵּיהּ, נַפְּשָׁא מִתַּמָּן מָשִׁיךָ.","וַוי לֵיהּ, דְּאִתְּעַקַּר בְּהַהוּא הִרְהוּרָא, מִגּוֹ אִילָנָא דְחַיֵּי, וְאִתְּדָּבַּק בְּאִילָנָא דְמוֹתָּא. עַנְפִּין לֵיתּ בֵּיהּ, לָא חָמָא טָבָא לְעָלְמִין, יְבֵשָׁא אִיהוּ בְּלָא לַחוּתָּא כְּלָל. אִנְבֵּיהּ מָרִיר כְּלַעֲנָה, עֲלֵיהּ אִתְּמָר (ירמיהו י״ז:ו׳) וְהָיָה כְּעַרְעָר בָּעֲרָבָה ולא יִרְאֶה כִי יָבֹא טוֹב וְגו'.","בְּגִין דְּהִרְהוּרָא טָבָא סָלִיק לְעֵילָא, אָחִיד בְּאִילָנָא דְחַיֵּי, אַתְּקִיף בְּעַנְפּוֹי, אָכִיל מֵאִנְבֵּיהּ, כּל קִדּוּשִׁין וְכָל בִּרְכָאן נָפְּקִין מִנֵּיהּ. אַחְסִין חַיִּין לְנַפְּשֵׁיהּ וְאַסְוָותָּא לְגַרְמֵיהּ, עֲלֵיהּ אִתְּמָר (ירמיהו י״ז:ח׳) וְהָיָה כְּעֵץ שָׁתּוּל עַל מַיִם וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו וְלא יִרְאֶה כִּי יָבֹא חוֹם וגו'.","כָּל מִלִּין דְּעַלְמָא, אָזְלִין בָּתַּר מַחְשָׁבָה וְהִרְהוּרָא, וְעַל דָּא (ויקרא י״א:מ״ד) וְהִתְּקַדִּשְׁתֶּם וִהְיִיתֶּם קְדוֹשִׁים, בְּגִין דְּכָל קִדּוּשִׁין דְּעַלְמָא אַפִּיק וּמָשִׁיךָ בְּהִרְהוּרָא טָבָא.","מַאן דְּאִסְתָּאַב בְּהִרְהוּרָא (ויקרא פ\"ד ע\"א, שם נ\"ו ע\"א) בִּישָׁא, כַּד אָתֵּי לְאִזְדַּוְּוגָא בְּאִתְּתֵּיהּ ושוִֹּי רְעוּתֵּיהּ וְהִרְהוּרֵיהּ בְּאִתְּתָּא אָחֳרָא, וזָרַע זַרְעָא בְּהִרְהוּרָא אָחֳרָא, דָּא הוּא דְּאַחְלַף דַּרְגִּין עִלָּאִין דִּלְעֵילָא, דַּרְגָּא דְקוּדְשָׁא בְּגִין דַּרְגָּא דִּמְסָאֲבָא. כְּמָה דְּהִרְהוּרָא דִילֵיהּ עָבִיד חִלּוּפִּין לְתַּתָּא, אוּף הָכִי עֲבַד חִלּוּפִּין לְעֵילָא.","כְּמָה דְגוּפָּא דְּהַהוּא בְּרָא דְּיוֹלִיד, אִקְרֵי בֶּן תְּמוּרָה. אוּף הָכִי בְּנַפְּשָׁא בֶּן תְּמוּרָה אִקְרֵי. דְּהָא לָא מָשִׁיךָ מְשִׁיכוּ קַדִּישָׁא בְּהַהוּא הִרְהוּרָא, וְנַפְּשָׁא דִילֵיהּ אִתְּחַלַּף בְּדַרְגָּא אָחֳרָא.","יַעֲקֹב שְׁלֵימָא דְכלָּא, גַּלֵּי קַמֵּי קוּדְשָׁא בְּרִיךָ הוּא דְּכָל אָרְחוֹי בִּקְשׁוֹט הֲווּ, וְהִרְהוּרָא דִקְשׁוֹט הִרְהֵר תָּדִיר בְּכלָּא. בְּהַהוּא לֵילְיָא דִּמְשַׁמֵּשׁ בְּאִתְּתֵּיהּ בְּלֵאָה, הִרְהוּרָא (קע\"ו ע\"ב, ויקרא רצ\"ב ע\"א) דִילֵיהּ בְּרָחֵל הֲוַתּ. משמֵּשׁ בְּלֵאָה וְחָשִׁיב בְּרָחֵל, וּמְקוֹרָא דִילֵיהּ בְּהַהוּא הִרְהוּרָא דִילֵיהּ אָזְלָא.","וְלָאו לְדַעְתָּא, דְּהָא לָא הֲוָה יָדַע. בְּגִין כָּךָ, לָא סָלִיק רְאוּבֵן בִּשְׁמָא. קוּדְשָׁא בְּרִיךָ הוּא דְּהֲוָה יָדַע, אַחְמֵי לֵיהּ וְאָמַר, רְאוּ בֵן דְּאִתְּיְלִיד בְּעַלְמָא. ועַל דָּא כְּתִּיב, (ירמיהו כ״ג:כ״ד) אִם יִסָּתֵּר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ, אַל תִּקְרֵי אֶרְאֶנּוּ אֶלָּא אַרְאֶנּוּ, דְּיִסְתַּכְּלוּן בֵּיהּ. וּבְגִין דְּאִתְּגְּלֵי קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךָ הוּא, דְּהָא לָאו לְדַעְתָּא הֲוָה וּבְאֹרַח קְשׁוֹט הִרְהֵר בִּרְעוּתֵּיהּ יַעֲקֹב, לָא אִיפְּסַל מִגּוֹ שִׁבְטִין קַדִּישִׁין, דְּאִי לָאו הָכִי הֲוה אִיפְּסַל.","וּבְגִין דְּהִרְהוּרָא עִקָּרָא אִיהוּ וְעָבִיד עוֹבָדָא, קוּדְשָׁא בְּרִיךָ הוּא דְּהֲוָה יָדַע הַהוּא הִרְהוּרָא, בְּאֲתַּר דְּאִתְּדַּבְּקָא. בְּהַהִיא טִפָּה קַדְמָאָה, אִסְתַּמַּר לֵיהּ בְּכִירוּתָּא, דִּכְתִּיב, (דברי הימים א ה׳:א׳) כִּי הוּא הַבְּכוֹר וְגו', נִתְּנָה בְּכוֹרָתּוֹ לְיוֹסֵף. בְּהַהוּא אֲתַּר דְּהִרְהוּרָא אָזְלָא וְאִתְּדָּבַּק בְּהַהִיא טִפָּה, תַּמָּן אִתְּדָּבַּק וְאִתְּמָסַר הַהוּא בְּכוֹרָה. וְאִתְּנְטִילַתּ בְּכוֹרָה מֵרְאוּבֵן, וְאִתְּמָסַר בְּאֲתַּר דְּהִרְהוּרָא אִתְּדָּבַּק בָּהּ. בְּרָחֵל הִרְהֵר וְאִתְּדָּבַּק רְעוּתָּא, בְּרָחֵל אִתְּדָּבַּק בְּכִירוּתָּא, וְכלָּא אִתְּהַדַּר בָּתַּר הִרְהוּרָא וּמַחֲשָׁבָה.","כְּגַוְונָא דָא, הִרְהוּרָא וּמַחֲשָׁבָה, עָבִיד עוֹבָדָא וְאִתְּמְשַׁךָ מְשִׁיכוּ, בְּכָל מַה דְּאִתְּדָּבַּק בַּר נָשׁ בְּסִתְּרָא, דִּכְתִּיב, (דברים כ״ה:ה׳) לֹא תִּהְיֶה אשתּ הַמֵּתּ הַחוּצָּה לְאִישׁ זָר, יְבָמָהּ יָבֹא עָלֶיהָ, וְהָכָא אִצְּטְרִיךָ הִרְהוּרָא וּרְעוּתָּא לְאִתְּדַּבְּקָא. וּבְהַהוּא רְעוּתָּא וּמַחֲשָׁבָה, מָשִׁיךָ מְשִׁיכוּ וְעָבִיד עוֹבָדָא דְאִצְּטְרִיךָ, וְלָא יִשְׁתְּצֵּי שְׁמָא דְמִיתָּא מֵעָלְמָא.","וְסִתְּרָא דָא (איוב לה) אִם יָשִׂים אֵלָיו לִבּוֹ רוּחוֹ וְנִשְׁמָתּוֹ אֵלָיו יֶאֱסֹף, דְּהָא וַדַּאי רְעוּתָּא וּמַחֲשָׁבָה, מָשִׁיךָ מְשִׁיכוּ, וְעָבִיד עוֹבָדָא בְּכָל מַה דְּאִצְּטְרִיךָ. וְעַל דָּא, בִּצְּלוֹתָּא אִצְּטְרִיךָ רְעוּתָּא וְהִרְהוּרָא לְכַוְּונָא, וכֵן בְּכָל אִינוּן פּוּלְחָנִין דְּקוּדְשָׁא בְּרִיךָ הוּא, הִרְהוּרָא וּמַחֲשָׁבָה עָבִיד עוֹבָדָא, וּמָשִׁיךָ מְשִׁיכוּ בְּכָל מַה דְּאִצְּטְרִיךָ.","(בראשית ל׳:י״ד) וַיֵּלֶךְ רְאוּבֵן בִּימֵי קְצִיר חִטִּים וַיִּמְצָא דוּדָאִים בַּשָּׂדֶה. רִבִּי יִצְחָק פָּתַח וְאָמַר, (תהילים ק״ד:כ״ד) מָה רַבּוּ מַעֲשֶׂיךָ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ מָלְאָה הָאָרֶץ קִנְיָנֶךָ. הַאי קְרָא אוּקְמוּהָ, בְּכַמָּה אֲתַר. אֶלָּא, מַאן יָכִיל לְמִמְנֵי עוֹבָדוֹי דְקוּדְשָׁא בְּרִיךְ הוּא. דְּהָא כַּמָּה חֵילִין וּמַשִּׁרְיָין, מְשַׁנְיָין דָּא מִן דָּא, דְּלֵית לוֹן חוּשְׁבְּנָא. וְכֻלְּהוּ בְּזִמְנָא חָדָא, כְּמַרְזְפָא דְּאַפִּיק זִיקִין לְכָל סִטְרִין בְּזִמְנָא חָדָא. כָּךְ קוּדְשָׁא בְּרִיךְ הוּא, אַפִּיק כַּמָּה זִינִין וּמַשִּׁרְיָין מְשַׁנְיָין דָּא מִן דָּא, דְּלֵית לוֹן חוּשְׁבְּנָא וְכֻלְּהוּ בְּזִמְנָא חָדָא.","תָּא חֲזֵי, בְּדִבּוּרָא וּבְרוּחָא כְּחֲדָא, אִתְעֲבִיד עַלְמָא, דִּכְתִיב (תהילים ל״ג:ו׳) בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ וּבְרוּחַ פִּיו כָּל צְבָאָם. בִּדְבַר ה', דָּא דִבּוּרָא. וּבְרוּחַ פִּיו, דָּא רוּחָא. דָּא בְלָא דָא לָא אָזִיל, וְאִתְכְּלִיל דָּא בְּדָא, וְנָפִיק מִנַיְיהוּ כַּמָּה חֵילִין לְחֵילִין, וּמַשִּׁרְיָין לְמַשִּׁרְיָין, וְכֹלָּא בְּזִמְנָא חָדָא.","תָּא חֲזֵי כַּד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמִבְרֵי עָלְמִין, אַפִּיק חַד נְהוֹרָא סְתִימָאָה. דְּמִן הַהוּא נְהוֹרָא, נָפְקִין וְנָהֲרִין כָּל אִינוּן נְהוֹרִין דְּאִתְגַּלְּיָין. וּמֵהַהוּא נְהוֹרָא, נָפְקִין וְאִתְפַּשְּׁטוּ וְאִתְעֲבִידוּ שְׁאָר נְהוֹרִין וְאִיהוּ עַלְמָא עִלָּאָה.","תוּ, אִתְפַּשַּׁט הַאי נְהוֹרָא עִלָּאָה, וְעָבִיד אוּמָנָא, נְהוֹרָא דְּלָא נָהִיר, וְעָבִיד עַלְמָא תַּתָּאָה. וּבְגִין דְּאִיהוּ נְהוֹרָא דְּלָא נָהִיר, בָּעֵי לְאִתְקַשְּׁרָא לְעֵילָא, בָּעֵי לְאִתְקַשְּׁרָא לְתַתָּא, וּבְקִשּׁוּרָא דִלְתַתָּא, אִתְקַשַּׁר לְאִתְנְהָרָא בְּקִשּׁוּרָא דִלְעֵילָא."],[[0,"פתח רבי חייא וכו':","פתח ר\"ח ואמר. הארץ אשר אתה שוכב עליה לך אתננה ולזרעך. ושואל, וכי אותו המקום בלבד הבטיחו הקב\"ה, שהיה רק ארבע או חמש אמות ולא יותר. ומשיב, אלא בעת ההיא כפל הקב\"ה תחתיו את כל ארץ ישראל, ונמצא אז אותו המקום, שכלל את כל הארץ. ומה מקום ההוא, נעשה הכלל של כל הארץ, רבי שמעון, שהוא המאור של כל הארץ, על אחת כמה וכמה. שהוא שקול ככל העולם."],[1,"פתח רבי יוסי וכו':","פתח ר\"י ואמר. הפעם אודה את ה'. ושואל, וכי בכל הבנים שהולידה לא היה ראוי להודות להקב\"ה, אלא בבן הזה. ומשיב, אלא יהודה הוא בן רביעי אל הכסא, שהוא המלכות שהיא רגל רביעי, (כנ\"ל ב\"א דף ק\"י ד\"ה מלכותא) והוא השלים את הכסא, וע\"כ יהודה לבדו הוא תקון הכסא, והוא עמוד שכל העמודים נסמכים עליו. להיותו המשלים את הכסא, ר\"ש, המאיר בכל העולם בתורה, וכמה מאורות מאירים על ידו, על אחת כמה וכמה. שהוא עמוד כל העמודים."],[2,"מתניתין בני עליון וכו':","בני עליון, קדושים עליונים, ברוכי העולם בעלי מוח האגוז, האספו לדעת: כי צפור יורדת בכל יום, מתעוררת בגן, שלהבת אש בכנפיה. בידה ג' מגרפות, דהיינו יעים, חדות כחרב, מפתחות האוצרות ביד ימינה."],[2,"","פירוש. הסתרי תורה, מזמין רק אותם האנשים שזכו אל אותן המדרגות שחושב, שהם חו\"ב תו\"מ: בני עליון, בינה. קדישי עליונין, חכמה. בריכן דעלמא, ת\"ת. מוחא דאגוזא, מלכות. ואומר להם האספו לדעת ולהשכיל בכרוזה של הצפור, שמכרזת בכל יום בגן עדן, כמ\"ש לפנינו. כי הם ראוים להבין דבריה, ולא אחרים שעוד לא זכו לאלו המדרגות. וענין מוח האגוז, מתבאר בזהר (בזהר חדש בראשית אות ט\"ז) ע\"ש. \u0003צפור.\u0004 פירושו הנוקבא דז\"א. \u0003גן\u0004 היינו גן העדן, שהוא שם מקום הנוקבא, אחר שהשיגה צורת אמא לגמרי, בלי שום הכר מצורתה עצמה. כמ\"ש לעיל (בראשית ב' דף ד' אות ו') \u0003נמוסי דגנתא דעדן כמה דאיהו ברזא עלאה.\u0004 ע\"ש בהסולם. וזה אמרו כאן. \u0003הא צפרא נחית בכל יומא,\u0004 שצפור שהיא הנוקבא, יורדת ממקום אמא, אחרי שקבלה צורתה, \u0003אתער בגנתא,\u0004 ומתעוררת בכל יום, בגן עדן להכריז משם, להיותה שם שוה לגמרי לאמא, והשואה זו לצורת אמא, הוא בעיקר ג' צורות אלו, א) צורת הקטנות שה\"ס ו\"ק, המכונה \u0003כנפים,\u0004 שצריכה להיות דומה לכנפי אמא. ב) ה\"ס הארת החכמה בעודה סתומה, שמקומה ביד שמאל, והיא בחינת ג\"ר דו\"ק. ג) ה\"ס החסדים המלבישים החכמה, ופותחים אותה להאיר בכל השלמות. ומכונים משום זה, \u0003מפתחות האוצרות.\u0004 שזולתם, כל אוצרות החכמה נשארים סתומים."],[2,"","וזה אמרו, \u0003שלהובא דנורא בגדפהא,\u0004 שהנוקבא ירדה לגן עדן מאמא, וקבלה ממנה, שלהבת אש בכנפיה, כלומר, שהורידה עמה מאמא את הדינין המכונים שלהבת אש, ומקומם מכונה \u0003כנפים,\u0004 דהיינו שהשיגה בחינת הקטנות מאמא. וכמו כן הורידה עמה, \u0003בידהא, תלתא מגרופיין שנינן כחרבא,\u0004 ביד שמאל שלה, הורידה הארת החכמה, ואף על פי שעדיין סתומה, מ\"מ היא מבריחה כל הקליפות, שהם בחינת הלכלוך וטנופת, הסותמות את צנורות השפע מלהשפיע לתחתונים, ולפיכך מכונה בשם מגרופית חדה כחרב, שהוא מנקה כל לכלוך, עד שלא נכר עוד מקומו, ולפי שבסוד התכללות יש י\"ב בחינות דהיינו ג' פרקין בכל אחת מחו\"ג ונו\"ה, המכונים זרועות וירכין, כנ\"ל (דף ס\"ג ד\"ה דהא) ע\"ש, לפיכך חושב כאן \u0003ג' מגרופיות,\u0004 ביד שמאל שלה, דהיינו בסוד ג' פרקי היד, ונתבאר בחינה השניה שקבלה מאמא."],[2,"","וז\"ש, \u0003מפתחן גניזין בידא ימינא,\u0004 שהיא בחינה השלישית שהורידה עמה מאמא לגן עדן, שהוא אור החסדים שמקומם ביד ימין, המלבישים את החכמה, המכונים \u0003מפתחות האוצרות,\u0004 להיותם פותחים אוצרות החכמה. וזולתם נשארים כל אוצרות החכמה סתומות כמו במנעול ובריח."],[3,"קרי בחיל ואמר וכו':","קוראת בכח ואומרת לצדיקים שהם בגן עדן, מי מכם שפניו מאירים, דהיינו שזכה לחכמה שנאמר, חכמת אדם תאיר פניו, שנכנס ויצא ונתחזק בעץ החיים, דהיינו שזכה לג' קוין: \u0003שנכנס\u0004 בקו ימין, \u0003ויצא\u0004 בקו שמאל, \u0003ונתחזק בעץ החיים\u0004 שהוא קו אמצעי, הגיע בענפיו, היינו חג\"ת נה\"י הכלולים בז\"א, שה\"ס עץ החיים, והם ענפיו. ונאחז בשרשיו, דהיינו ג\"ר דז\"א. אוכל מפירותיו המתוקים מדבש, ה\"ס הארת החכמה שבנוקבא דז\"א שה\"ס פירי שלו. והוא מתוק, בסו\"ה, מה מתוק האור לעין, ועינים ה\"ס החכמה. הנותן חיים לנפש ורפואה לעצמו, דהיינו הגוף שלו."],[4,"אסתמר, מהרהורא בישא וכו':","ומכרזת ואומרת, מי הוא הזוכה לכל זה, הוא מי שנשמר מהרהור רע, מהרהור המשקר בעץ החיים, מהרהור המטמא את הנהר והנחל, שהוא מקורו של ישראל, מהרהור הנותן מות לנפש ושבירה לעצמו, אין לו קיום כלל."],[4,"","ביאור הדברים. נודע, שהנוקבא מצד עצמותה אינה ראויה לקבל שום מוחין, כי הצמצום א' רוכב עליה, (כנ\"ל ב\"א דף ז' ד\"ה וכבר) עש\"ה. וכל המוחין שמקבלת הוא מכח עליתה והתכללותה בכלים דאמא כמ\"ש שם. ולפיכך נקודת עצמותה צריכה להיות גנוזה בה בהעלם גמור, ואם היא מתגלית תכף מסתלקים ממנה כל האורות, כי נגלה, שאינה בחינת אמא, אלא בחינת המלכות, שהצמצום רוכב עליה, ואינה ראויה לקבל אורות דאמא. ומשום זה ה\"ס עצה\"ד טו\"ר. כנ\"ל בהקדמת ספר הזהר דף קכ\"ב אות קכ\"ג \u0003זכי ב\"נ הא טוב, אי לא זכי הא רע.\u0004 שפירושו אם נזהר האדם להדבק בקו אמצעי המכריע בין הקוין, שקו ימין יאיר ממעלה למטה, וקו שמאל ממטה למעלה, וגם האדם אינו ממשיך הארת חכמה שבקו שמאל ממעלה למעלה, אז נבחן ש \u0003זכי, והא טוב,\u0004 דהיינו שנקודת עצמותה של הנוקבא, נגנזת ואינה נודעת. אמנם אם ממשיך הארת השמאל ממעלה למטה, ופוגם בקו אמצעי, נבחן שהוא \u0003לא זכי והא רע,\u0004 ותכף נגלה עליו נקודת עצמותה של הנוקבא, ואורות החיים פורחים ומסתלקים תכף ממנו."],[4,"","וענין \u0003לא זכי,\u0004 אינו צריך מעשה ממש, שימשיך בפועל ממעלה למטה, אלא בהרהור לחטוא אע\"פ שעוד לא חטא בפועל, כבר הוא נבחן ל \u0003לא זכה והא רע,\u0004 ואורות הקדושה מסתלקים ממנו והרוח שטות, שה\"ס המות והרע, מתלבש בו, שהוא המחטיא בפועל, כמ\"ש ז\"ל, אין אדם חוטא אלא אם כן נכנס בו רוח שטות. (כנ\"ל דף ט\"ז ד\"ה וזה ע\"ש)."],[4,"","וזה אמרו \u0003אסתמר מהרהורא בישא,\u0004 שאינו זוכה לאורות העליונים אלא מי שנשמר \u0003מהרהור רע,\u0004 דהיינו מן ההרהור להטוא ולהמשיך הארת השמאל ממעלה למטה, \u0003מהרהורא דמשקר באילנא דחיי\u0004 מאותו הרהור המשקר ופוגם בעץ החיים, כי עץ החיים ה\"ס קו אמצעי, המכריע שקו ימין בלבדו יאיר ממעלה למטה, והקו שמאל רק ממטה למעלה, וכיון שהאדם הרהר להמשיך ממעלה למטה נמצא משקר ופוגם בתקון עץ החיים. \u0003מסאיב נהרא ונחלא מקורא דישראל,\u0004 ולא עוד, אלא שהוא מטמא \u0003הנהר\u0004 שה\"ס אמא. \u0003והנחל\u0004 שה\"ס יסוד דאמא, שהיא \u0003המקור של\u0004 ז\"א הנקרא \u0003ישראל.\u0004 פירוש. כי אחר שהאורות מסתלקים מן הנוקבא, משום שנגלה בה כח הצמצום, מגיע פגם הזה גם לאמא, מטעם שהנוקבא כבר נכללה באמא. וזה נבחן כמו שהיא נטמאת ממגעה באחרים. כי אמא מצד עצמותה, אין בה שום פגם מצמצום א', אלא מכח שנתכללה עם הנוקבא, נפגמה על ידה. ואמא נקראת נהר, בסוד ונהר יוצא מעדן, ומצד יסודה, נקראת \u0003נחל.\u0004 בסו\"ה \u0003מנחל בדרך ישתה\u0004 ז\"א, \u0003על כן ירים ראש,\u0004 שז\"א משיג בחינת ג\"ר וראש, מן הנחל. שהוא יסוד אמא."],[4,"","וז\"ש \u0003דיהיב מותא לנפשא ותבירו לגרמיה,\u0004 כי אחר שמסתלקים האורות מן הנוקבא, מסתלק גם אור האדם הנקרא \u0003נפש,\u0004 והכלי שלו שנקרא גוף, נשבר, כי \u0003לית ליה קיומא כלל,\u0004 כי אין לו ממי לקבל אורות החיים וע\"כ נשבר ומת."],[5,"הרהורא דמסאיב וכו':","ההרהור שטימא את המקור שלו, של עץ החיים שהוא ז\"א, כי העלה הפגם דנוקבא לאמא כנ\"ל בסמוך, עושה אילן השקר, כי הפגם והחורבן דאורות המקור של עץ החיים, הולך ובונה את אילן השקר של הס\"א, כי לא נבנה צור אלא מחורבנה של ירושלים. והוא, משום שאותו ההרהור עולה ומחליף נפש תחת נפש. דהיינו נפש מאורות דס\"א תחת נפש מאורות הקדושה, כי מחמת ההרהור, עץ החיים מסתלק, ועץ המות מתדבק בו, שממנו מושך את הנפש. פירוש, כמו שנתבאר לעיל בדבור הסמוך, שתכף כשמהרהר בעבירה מסתלקים ממנו אורות דקדושה, שה\"ס עץ החיים, בסוד \u0003לא זכי הא רע,\u0004 ומתלבשים בו אורות דסטרא אחרא, שהוא עץ המות. ונמצא בהכרח, שנפשו נמשכת עתה מעץ המות, ונחלף לו נפש דס\"א במקום הנפש דקדושה שהיתה לו."],[6,"ווי ליה דאתעקר וכו':","אוי לו שבסבת אותו ההרהור נעקר מעץ החיים, ונתדבק בעץ המות, אשר אין לו ענפין, כלומר שאורו נפסק ואינו מתפשט, והדבק בו אינו רואה טוב לעולם. הוא יבש בלי שום לחלוחית, של אור, פירותיו מרים כלענה. ועליו נאמר והיה כערער בערבה ולא יראה כי יבוא טוב וגו'."],[7,"בגין דהרהורא טבא וכו':","כי הרהור טוב העולה למעלה, נאחז בעץ החיים, שהוא קו אמצעי, ומחזיק בענפיו ואוכל מפירותיו, כל הקדושות וכל הברכות יוצאות ממנו, ונוחל חיים לנפשו, ורפואה לעצמו, עליו נאמר, והיה כעץ שתול על מים ועל יובל וגו'."],[8,"כל מלין דעלמא וכו':","כל דברי העולם הולכים אחר המחשבה וההרהור. ועל זה כתוב, והתקדשתם והייתם קדושים, משום שכל הקדושות שבעולם הוא מוציא וממשיך עם הרהור טוב. (ועי' לעיל דף ע\"ו ד\"ה קרי בחיל)."],[9,"מאן דאסתאב וכו':","מי שנטמא בהרהור רע כשבא להזדווג באשתו, כי שם רצונו והרהורו באשה אחרת, והזריע זרע בהרהור זה, זה הוא שהחליף מדרגות העליונות של מעלה, שהחליף מדרגת הקודש על מדרגת הטומאה. כמו שההרהור שלו עושה חליפין למטה שמחליף אשתו באחרת, כן עושה חליפין למעלה."],[10,"כמה דגופא וכו':","וכמו הגוף של הבן שמוליד נקרא בן תמורה, כך מבחינת הנפש שלו נקרא ג\"כ בן תמורה, כי לא משך המשכה קדושה באותו ההרהור, והנפש שלו נתחלף במדרגה אחרת, דהיינו מס\"א."],[10,"","ביאור הדברים. אחר שהסתרי תורה ביאר היטב את הפגם הגדול שעושה, אם הדבק בקדושה, בעץ החיים, מהרהר להמשיך מהשמאל ממעלה למטה, שתכף עם הרהורו הרע מסתלקים ממנו כל אורות החיים וכל הטוב, ונחלף לו נפש דטומאה במקום נפש דקדושה, בסוד, \u0003לא זכי הא רע,\u0004 כמ\"ש לעיל באורך, הוא משוה לזה גם ענין המזדווג באשתו וחושב באחרת, כי המזדווגים בקדושה, הם מרכבה לז\"א ונוקבא העליונים, וכשהוא מהרהר באחרת, נמצא מעורר בזה את הנוקבא דס\"א, אשת זנונים, שהיא הלעומת של הנוקבא דז\"א, וגורם שהארת השמאל מן הנוקבא, תמשך ממעלה למטה, אל הקליפות, אשר אז היא נבחנת לעץ הדעת טו\"ר, בסוד \u0003לא זכי הא רע,\u0004 כי נגלה עליה הנקודה דצמצום א', וכל האורות דקדושה מסתלקים, ותחתיהם באים האורות דס\"א. ונמצא שהמזדווגים נעשו אז מרכבה לזו\"ן דקליפות, ולפיכך בן הנולד מזווג זה נמשך מס\"א, ונעשה \u0003בן תמורה,\u0004 כלומר, שיש בו נפש רעה מס\"א, מכחות צמצום הא', ואינו ראוי עוד לקבל אור החיים דקדושה."],[10,"","וזה אמרו, \u0003וזרע זרעא בהרהורא אחרא דא הוא דאחלף דרגין עלאין וכו' בגין דרגא דמסאבא,\u0004 כי אז \u0003לא זכי הא רע,\u0004 שנגלה נקודת הצמצום א' עליה, ונחלפו אורות החיים, על אורות אילן המות, כנ\"ל. \u0003כמה דהרהורא דיליה עביד חליפין לתתא אוף הכי עבד חליפין לעילא\u0004 וכמו שנגלה הרע למטה, דהיינו בהנוקבא, במקום הטוב שהיה בה, כך נעשה חליפין למעלה באמא, כלומר, שהפגם עלה גם לז\"ת דאמא, שהוא מחמת שהיו מחוברים זב\"ז בעת התקון נפגמים זה מזה בעת הפגם. (כנ\"ל דף ע\"ז ד\"ה וזה). ולפיכך \u0003כמה דגופא דההוא ברא דיוליד, אקרי בן תמורה, אוף הכי בנפשא בן תמורה אקרי\u0004 הגוף נמשך מנוקבא והנפש נמשך מאורות דאמא, ולפי שגם אמא נפגמה, נמצא שלא לבד, שהגוף נעשה פגום אלא גם הנפש, שהיא מאמא, נפגמה, וגם הנפש נבחן לתמורה. כלומר שנחלפה ונעשתה לנפש טמאה."],[11,"יעקב שלימא וכו':","יעקב השלם, שהכל גלוי לפני הקב\"ה, שכל דרכיו של יעקב היו באמת, והרהורי אמת היה מהרהר תמיד בכל דבר, באותו הלילה ששימש באשתו בלאה, ההרהור שלו ברחל היה, היה משמש בלאה וחושב ברחל, והמקור שלו, הלך באותו ההרהור שלו."],[11,"","ביאור הדברים. אחר שהסתרי תורה ביאר ב' ההקדמות בענין הפגם הגדול של המהרהר באשת זנונים, שמחליף מדרגות עליונות דקדושה במדרגות הטומאה, וכמ\"ש בסוד, לא זכי הא רע, בא עתה אל מטרתו הרצויה, לבאר סוד ההרהור שחשב יעקב ברחל ושמש בלאה. וכבר ידעת שלאה ה\"ס בינה, ורחל ה\"ס מלכות, דהיינו הנוקבא שמחזה ולמטה דז\"א. גם ידעת שהנוקבא דז\"א מצד עצמה אינה יכולה לקבל אור להיותה בצמצום א', אלא שממשכת מקודם כלים מאמא, בסוד מלכות הממותקת במדת הרחמים ואז ראויה לקבל האורות. (כנ\"ל ב\"א דף ז' ד\"ה וכבר ע\"ש) ונמצא שרחל מצד עצמה אינה ראויה לשום אור אלא אחר שמקבלת הכלים מלאה, דהיינו מאמא. וז\"ס שאומר הזהר לעיל (דף נ\"ח אות קל\"א) \u0003בשעתא דיעקב פלח שבע שנין קדמאין,\u0004 שרצה להמשיך ז' אורות חג\"ת נהי\"מ לרחל, \u0003נפקא קלא ואמר, יעקב, מן העולם ועד העולם כתיב,\u0004 דהיינו שצריכים להמשיך מקודם כלים מתוקנים מן עולם העליון שהוא בינה לאה, אל עולם התחתון, שהיא הנוקבא רחל. ע\"ש. גם זסו\"ה לא יעשה כן במקומנו וגו'. ונמצא שבשעה שבא אל לאה, וחשיב ברחל, דהיינו להמשיך האורות אל רחל, שלא ידע שהיא לאה, הנה אז חשב להמשיך האורות בכלים דצמצום א' מטרם שנמתקו, שהם נקראים רע, בסוד לא זכי הא רע. כי מטרם שנשא את לאה לא היה יכול להמשיך כלים מתוקנים לרחל. כנ\"ל \u0003נפקא קלא ואמר מן העולם ועד העולם\u0004 כתיב, ולפיכך נחלפו לו כלים דלאה לבחינת כלים דרחל, שכח הצמצום שהיה ברחל, נתדבק בכלים דלאה, ולא יכול להמשיך בזווגו אלא בחינת ו\"ק בלי ראש. ובזה תבין דברי הזהר בדבור הסמוך."],[12,"ולאו לדעתא, וכו':","ושלא לדעת עשה זה, כי לא היה יודע שהיא לאה. משום זה לא עלה ראובן בשם, כלומר שלא היה לו אלא ו\"ק חסר ראש, (כנ\"ל בדבור הסמוך עש\"ה.) כי \u0003שם\u0004 פירושו השגה. אלא הקב\"ה שהיה יודע שהיא לאה, דהיינו בינה ואינה צריכה להפגם מכח הצמצום של רחל, הראה אותו, דהיינו שהשפיע לו ראש וג\"ר, ואמר, ראו \u0003בן\u0004 שנולד בעולם. דהיינו שהשפיע לו ג\"ר. ועל דא כתיב אם יסתר וגו' אל תקרא אראנו, באלף סגולה, אלא אראנו, באלף פתוחה. ומשום שנגלה לפני הקב\"ה, כי שלא לדעת היה, ובדרך אמת הרהר יעקב ברצונו, לא נפסל ראובן מתוך השבטים הקדושים, כלומר, שלא היה נחשב לבן תמורה, כי אם לא היה כך, היה נפסל."],[13,"ובגין דהרהורא וכו':","ומשום שההרהור הוא העיקר, והוא עושה מעשה, הקב\"ה, שהיה יודע המקום, שאותו ההרהור היה דבוק בעת זריעת טפה הראשונה, שמר לו לאותו המקום, את הבכורה, שכתוב, כי הוא הבכור ובחללו יצועי אביו נתנה בכורתו ליוסף, כי במקום שההרהור הלך ונתדבק בזריעת הטפה, שם נתדבקה ונמסרה הבכרה, ונלקחה הבכרה מראובן, ונמסרה אל המקום שההרהור נתדבק בו, ברחל הרהר ונתדבק בה הרצון, ע\"כ ברחל נתדבק הבכרה, והושב הכל אחר ההרהור והמחשבה."],[14,"כגוונא דא וכו':","כעין זה מצאנו, אשר ההרהור והמחשבה עושה מעשה, ונמשכה המשכה, מכל מה שהאדם נתדבק בסתר, שכתוב לא תהיה אשת המת החוצה וגו', וכאן צריך ההרהור והרצון להדבק בנשמת אחיו המת, ובאותו הרצון והמחשבה מושך המשכה, ועושה המעשה שצריך, ולא ימחה שם המת מן העולם."],[15,"וסתרא דא וכו':","וזה סוד, אם ישים אליו לבו, רוחו ונשמתו אליו יאסוף. כי הוא ודאי, שהרצון והמחשבה מושך המשכה ועושה מעשה בכל מה שצריך. ועל כן בתפלה, צריכים רצון והרהור לכוון בה. וכן בכל העבודות של הקב\"ה, ההרהור והמחשבה עושה מעשה ומושך המשכה לכל מה שצריך."],[16,"וילך ראובן וגו' דודאים בשדה:","רבי יצחק פתח ואמר, מה רבו וגו' מלאה הארץ קנינך. מקרא זה בארוהו בכמה מקומות. אלא מי יכול לספור מעשיו של הקב\"ה, כי כמה צבאות ומחנות של מדרגות ומלאכים המשונים זה מזה, שאין להם מספר. כלומר, שהכתוב מה רבו מעשיך ה', יורה שאין להם מספר, שפירושו מוחין דחסדים. וכולם בחכמה עשית יורה מוחין דמספר, שהם חכמה, ואומר, אע\"פ שמשונים זמ\"ז, יצאו כולם בזמן אחד, בבת אחת, כפטיש המכה על אבן, או על ברזל מלובן, שמוציא ניצוצות לכל צד בבת אחת. כך הקב\"ה הוציא כמה מינים ומחנות משונים זה מזה, שאין להם מספר, וכולם בבת אחת."],[17,"ת\"ח בדבורא וכו':","בוא וראה, בדבור ורוח ביחד שהם זו\"ן, נעשה העולם. שכתוב, \u0003בדבר\u0004 ה' שמים נעשו, \u0003וברוח\u0004 פיו כל צבאם. \u0003בדבר ה',\u0004 זהו דבור שהוא הנוקבא, המאירה בחכמה, \u0003וברוח פיו,\u0004 זהו רוח. שהוא ז\"א, המאיר בחסדים, זה בלי זה אינו הולך, ונכללו זה מזה, ויצאו מהם כמה צבאות לצבאות, ומחנות למחנות, המשונים זמ\"ז בהארתם שזה בחכמה וזה בחסדים כנ\"ל בדבור הסמוך, וכולם בזמן אחד."],[18,"ת\"ח כד בעא וכו':","בוא וראה, כשרצה הקב\"ה לברוא העולמות, הוציא אור סתום אחד, שהוא אור הבינה, כי הכניס \u0003י'\u0004 ב \u0003אור\u0004 הבינה ונעשה \u0003אויר,\u0004 (כנ\"ל ב\"א דף ט' ד\"ה ועביד ע\"ש.) שמן אור ההוא, יוצאים ומאירים כל האורות הנגלים. דהיינו על ידי הוצאת ה \u0003י'\u0004 מאויר, שחזר ונעשה \u0003אור\u0004 כמ\"ש שם. ומאותו האור יצאו ונתפשטו ונעשו שאר האורות, והוא עולם העליון. דהיינו בינה."],[19,"תו אתפשט וכו':","עור נתפשט אור העליון הזה, שהוא בינה, והאומן, דהיינו המאציל, עשה אור שאינו מאיר. ועשה את עולם התחתון. שהוא הנוקבא. ומשום שהוא אור שאינו מאיר, הוא צריך להתקשר למעלה וצריך להתקשר למטה, ועל ידי קשר של מטה הוא מתקשר להאיר בקשר של מעלה."],[19,"","ביאור הדברים. כי ר' יצחק נותן טעם על הדבורים הקודמים, שמביא מהכתוב מה רבו מעשיך ה' ומהכתוב בדבר ה' שמים נעשו, שאע\"פ שההארות משונות זו מזו, שזה בחכמה וזה בחסדים, מ\"מ יצאו בבת אחת. ואומר שהוא מטעם כי \u0003כד בעא קב\"ה למברי עלמין אפיק חד נהורא סתימאה\u0004 שהיא בינה המכונה עולם העליון המכוסה, \u0003דמן ההוא נהורא נפקין ונהרין כל אינון נהורין דאתגליין,\u0004 דהיינו המגולים בהארת חכמה, \u0003ואתעבידו שאר נהורין,\u0004 דהיינו הארת החסדים. \u0003ואיהו עלמא עלאה,\u0004 כי הן חכמה והן חסדים שורשם מעולם העליון, בינה, \u0003תו אתפשט האי נהורא עלאה ועבד אומנא נהורא דלא נהיר,\u0004 היינו שנתפשטה הבינה בקו שמאל שלה, שהוא אור שאינו מאיר, מטעם שהוא חכמה בלי חסדים כנודע, \u0003ועביד עלמא תתאה,\u0004 ועשה אז את עולם התחתון דהיינו הנוקבא. פירוש, כיון שהשמאל אינו מאיר בלי חסדים, ע\"כ נזדווג על המסך דחירק דזו\"ן שעלו שמה למ\"ן, והוציא עליו קומת קו אמצעי המיחד ימין ושמאל והחכמה נתלבשה בחסדים ונשלמה הארתה בסוד ג' קוין חב\"ד, ומשום דתלת נפקי מחד, חד בתלת קיימא (כנ\"ל ב\"א דף רפ\"ז ד\"ה תלת) שגם זו\"ן השיגו הארת ג' קוין ההם, ונמצא שבסבת השמאל של הבינה שאינו מאיר, הבינה הזדווגה על מסך דזו\"ן, ומשום זה השיגו הזו\"ן המוחין ממנה. וז\"ס \u0003ועביד אומנא נהורא דלא נהיר ועביד עלמא תתאה\u0004 שמשום שהמאציל עשה בשמאל הבינה, את נהורא דלא נהיר, בסבה זו, עשה ותקן את עולם התחתון בכל המוחין שלו. כמבואר."],[19,"","וזה אמרו \u0003ובגין דאיהו נהורא דלא נהיר בעי לאתקשרא לעילא בעי לאתקשרא לתתא,\u0004 משום שקו השמאל דבינה אינו מאיר, ע\"כ הוא צריך שיתקשר בסוד הקשר של ג' קוין, בב' העולמות, כי בעולם העליון לבד אינו מאיר מטעם חסרון חסדים, כנ\"ל, ובעולם התחתון בלבד, שהוא הנוקבא, אינו מאיר, משום שאין שורשו בה אלא בבינה. ע\"כ הוא מחויב להתקשר בבינה ששם שורשו, ומחויב להתקשר בנוקבא, כדי לקבל ממנה את המסך דחירק, שעליו יוצא קומת קו אמצעי, המשלים את השמאל. ואע\"פ שמסך דחירק בז\"א הוא, כמ\"ש בכמה מקומות, אמנם כל מסך הוא בחינת הנוקבא, כי הזכר הוא בחינת האור של המדרגה, ולפיכך נבחן מסך דז\"א שהיא בנוקבא. וז\"ש \u0003ובקשורא דלתתא\u0004 שהוא המסך דחירק שבעולם התחתון, \u0003אתקשר לאתנהרא בקשורא דלעילא,\u0004 מתקשר הקו שמאל להאיר בקשר הבינה למעלה, כי ע\"י המסך דחירק שבנוקבא. המוציא קו אמצעי מתקשר השמאל דבינה בימין שלה ומאיר כנ\"ל."]],[[0,"","פָּתַח רַבִּי חִיָּיא וְאָמַר, הָאָרֶץ אֲשֶׁר אַתָּה שֹׁכֵב עָלֶיהָ לְךְ אֶתְּנֶנָּה וּלְזַרְעֶךְ, וְכִי אוֹתוֹ הַמָּקוֹם לְבַדּוֹ הִבְטִיחַ לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי אַרְבַּע אַמּוֹת אוֹ חָמֵשׁ הָיוּ וְלֹא יוֹתֵר? אֶלָּא בְּאוֹתוֹ זְמַן, בְּאוֹתָם אַרְבַּע אַמּוֹת קִפֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כָּל אֶרֶץ יִשְׂרָאֵל. נִמְצָא שֶׁאוֹתוֹ מָקוֹם הוּא הַכְּלָל שֶׁל כָּל הָאָרֶץ. וּמָה אוֹתוֹ הַמָּקוֹם הוּא הַכְּלָל שֶׁל כָּל הָאָרֶץ - רַבִּי שִׁמְעוֹן שֶׁהוּא הַמָּאוֹר שֶׁל כָּל הָאָרֶץ, עַל אַחַת כַּמָּה וְכַמָּה שֶׁשָּׁקוּל כְּכָל הָעוֹלָם."],[1,"","פָּתַח רַבִּי יוֹסֵי וְאָמַר, הַפַּעַם אוֹדֶה אֶת ה', וְכִי בְּכָל מַה שֶּׁהוֹלִידָה לֹא רָאוּי לְהוֹדוֹת לַקָּדוֹשׁ-בָּרוּךְ-הוּא אֶלָּא בָּזֶה? אֶלָּא יְהוּדָה הוּא הַבֵּן הָרְבִיעִי לַכִּסֵּא, וְהוּא מַשְׁלִים אֶת הַכִּסֵּא. וּמִשּׁוּם כָּךְ יְהוּדָה לְבַדּוֹ תִּקּוּן הַכִּסֵּא וְתוֹמֵךְ שֶׁל כָּל הַתּוֹמְכִים. (שהיו שלשה, אברהם ויצחק ויעקב, ואז בא דוד מיהודה והשלים הכסא, ועל כך נקרא יהודה, שהוא השם הקדוש, והדל\"ת (ארבע רגליו) מרגלות הכסא) רַבִּי שִׁמְעוֹן שֶׁמֵּאִיר אֶת כָּל הָעוֹלָם בַּתּוֹרָה וְכַמָּה מְאוֹרוֹת מְאִירִים בִּשְׁבִילוֹ, עַל אַחַת כַּמָּה וְכַמָּה."],[2,"","מִשְׁנָה, בְּנֵי עֶלְיוֹן, קְדוֹשִׁים עֶלְיוֹנִים, בְּרוּכֵי (נבחרי) הָעוֹלָם, מֹחַ הָאֱגוֹז, הִתְכַּנְּסוּ לָדַעַת. הִנֵּה צִפּוֹר יוֹרֶדֶת בְּכָל יוֹם, מִתְעוֹרֶרֶת בַּגַּן. שַׁלְהֶבֶת אֵשׁ בִּכְנָפֶיהָ, בְּיָדֶיהָ שָׁלֹשׁ מַגְרֵפוֹת שְׁנוּנוֹת כַּחֶרֶב, מַפְתְּחוֹת שֶׁל גְּנָזִים בְּיַד יָמִין."],[3,"","קוֹרֵא בְחַיִל וְאוֹמֵר: מִי מִכֶּם שֶׁפָּנָיו מְאִירוֹת, שֶׁנִּכְנַס וְיָצָא וְהֶחֱזִיק בְּעֵץ הַחַיִּים, הִגִּיעַ לַעֲנָפָיו, אָחַז בְּשָׁרָשָׁיו, אָכַל מִפִּרְיוֹ הַמָּתוֹק מִדְּבַשׁ, נוֹתֵן חַיִּים לַנֶּפֶשׁ וּרְפוּאָה לְעַצְמוֹ?"],[4,"","הִשָּׁמֵר מֵהִרְהוּר רַע, מֵהִרְהוּר שֶׁמְּשַׁקֵּר בְּעֵץ הַחַיִּים, מְטַמֵּא הַנָּהָר וְהַנַּחַל הַמָּקוֹר שֶׁל יִשְׂרָאֵל, שֶׁנּוֹתֵן מָוֶת לַנֶּפֶשׁ וְשֶׁבֶר לְעַצְמוֹ, אֵין לוֹ כְּלָל קִיּוּם."],[5,"","הַהִרְהוּר שֶׁמְּטַמֵּא אוֹתוֹ הַמָּקוֹר שֶׁלּוֹ, עוֹשֶׂה עֵץ שֶׁל שֶׁקֶר, מִשּׁוּם שֶׁאוֹתוֹ הַהִרְהוּר עוֹלֶה וּמַחֲלִיף נֶפֶשׁ תַּחַת נֶפֶשׁ. עֵץ הַחַיִּים מִסְתַּלֵּק, וְעֵץ הַמָּוֶת מַחֲזִיק בּוֹ, מוֹשֵׁךְ מִשָּׁם הַנֶּפֶשׁ."],[6,"","אוֹי לוֹ שֶׁנֶּעֱקַר בַּהִרְהוּר הַהוּא מִתּוֹךְ עֵץ הַחַיִּים וְנִדְבַּק בְּעֵץ הַמָּוֶת, אֵין בּוֹ עֲנָפִים, לֹא רוֹאֶה טוֹב לְעוֹלָמִים, הוּא יָבֵשׁ בְּלִי לַחוּת כְּלָל, פִּרְיוֹ מַר כַּלַּעֲנָה, עָלָיו נֶאֱמַר (ירמיה יז) וְהָיָה כְּעַרְעָר בָּעֲרָבָה וְלֹא יִרְאֶה כִּי יָבוֹא טוֹב וְגוֹ'."],[7,"","מִשּׁוּם שֶׁהִרְהוּר טוֹב עוֹלֶה לְמַעְלָה, אוֹחֵז בְּעֵץ הַחַיִּים, מַחֲזִיק בַּעֲנָפָיו, אוֹכֵל מִפִּרְיוֹ, כָּל הַקְּדֻשּׁוֹת וְכָל הַבְּרָכוֹת יוֹצְאוֹת מִמֶּנּוּ, מוֹרִישׁ חַיִּים לַנֶּפֶשׁ וּרְפוּאָה לְעַצְמוֹ, עָלָיו נֶאֱמַר (שם) וְהָיָה כְּעֵץ שָׁתוּל עַל מַיִם וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו וְלֹא יִרְאֶה כִּי יָבֹא חֹם וְגוֹ'."],[8,"","כָּל דִּבְרֵי הָעוֹלָם הוֹלְכִים אַחַר הַמַּחֲשָׁבָה וְהַהִרְהוּר, וְעַל כֵּן (ויקרא יא) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים, מִשּׁוּם שֶׁכָּל הַקְּדֻשּׁוֹת שֶׁל הָעוֹלָם מוֹצִיא וּמוֹשֵׁךְ בְּהִרְהוּר טוֹב."],[9,"","מִי שֶׁנִּטְמָא בְּהִרְהוּר רַע, כְּשֶׁבָּא לְהִזְדַּוֵּג עִם אִשְׁתּוֹ וְשָׂם רְצוֹנוֹ וְהִרְהוּרוֹ בְּאִשָּׁה אַחֶרֶת, וְזוֹרֵעַ זֶרַע בְּהִרְהוּר אַחֵר, זֶהוּ שֶׁמַּחֲלִיף אֶת הַדְּרָגוֹת הָעֶלְיוֹנִים שֶׁלְּמַעְלָה, הַדַּרְגָּה שֶׁל קֹדֶשׁ בַּעֲבוּר הַדַּרְגָּה שֶׁל הַטֻּמְאָה. כְּמוֹ שֶׁהַהִרְהוּר שֶׁלּוֹ עוֹשֶׂה חִלּוּפִים לְמַטָּה, אַף כָּךְ עוֹשֶׂה חִלּוּפִים לְמַעְלָה."],[10,"","כְּמוֹ שֶׁגּוּפוֹ שֶׁל אוֹתוֹ בֵּן שֶׁיּוֹלִיד נִקְרָא בֶּן תְּמוּרָה, כָּךְ גַּם בַּנֶּפֶשׁ נִקְרָא בֶּן תְּמוּרָה, שֶׁהֲרֵי לֹא מוֹשֵׁךְ מְשִׁיכָה קְדוֹשָׁה בַּהִרְהוּר הַהוּא, וְנַפִשׁוֹ מִתְחַלֶּפֶת בְּדַרְגָּה אַחֶרֶת."],[11,"","יַעָקֹב הַשָּׁלֵם שֶׁל הַכֹּל, גָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁכָּל דְּרָכָיו הָיוּ בֶּאֱמֶת, וְהִרְהוּר שֶׁל אֱמֶת הִרְהֵר תָּמִיד בַּכֹּל, בְּאוֹתוֹ הַלַּיְלָה שֶׁשִּׁמֵּשׁ עִם אִשְׁתּוֹ לֵאָה, הַהִרְהוּר שֶׁלּוֹ הָיָה בְּרָחֵל. מְשַׁמֵּשׁ עִם לֵאָה וְחוֹשֵׁב עַל רָחֵל. וְהַמָּקוֹר שֶׁלּוֹ הָלַךְ בַּהִרְהוּר הַהוּא שֶׁלּוֹ."],[12,"","וְלֹא לְדַעַת, שֶׁהֲרֵי לֹא הָיָה יוֹדֵעַ, מִשּׁוּם כָּךְ לֹא עָלָה רְאוּבֵן בַּשֵּׁם. הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהָיָה יוֹדֵעַ, הֶרְאָה לוֹ וְאָמַר, רְאוּ בֵן שֶׁנּוֹלָד בָּעוֹלָם. וְעַל כֵּן כָּתוּב (ירמיה כג) אִם יִסָּתֵר אִישׁ בְּמִסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ. אַל תִּקְרֵי אֶרְאֶנּוּ אֶלָּא אַרְאֶנּוּ, שֶׁיִּסְתַּכְּלוּ בוֹ. וּמִשּׁוּם שֶׁהִתְגַּלָּה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהֲרֵי זֶה הָיָה לֹא לְדַעְתּוֹ וּבְדֶרֶךְ אֱמֶת הִרְהֵר בִּרְצוֹנוֹ יַעֲקֹב, לֹא נִפְסַל מִתּוֹךְ הַשְּׁבָטִים הַקְּדוֹשִׁים, שֶׁאִם לֹא כָּךְ - הָיָה נִפְסָל."],[13,"","וּמִשּׁוּם שֶׁהַהִרְהוּר הוּא עִקָּר וְעוֹשֶׂה מַעֲשֶׂה, הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהָיָה יוֹדֵעַ אוֹתוֹ הַהִרְהוּר בַּמָּקוֹם שֶׁנִּדְבַּק, בְּאוֹתָהּ הַטִּפָּה הָרִאשׁוֹנָה נִשְׁמְרָה לוֹ הַבְּכוֹרָה, שֶׁכָּתוּב (ד\"ה א ב) כִּי הוּא הַבְּכוֹר וְגוֹ'. נִתְּנָה בְּכוֹרָתוֹ לְיוֹסֵף. בְּאוֹתוֹ מָקוֹם שֶׁהַהִרְהוּר הָלַךְ וְנִדְבַּק בַּטִּפָּה הַהִיא, שָׁם נִדְבַּק וְנִמְסְרָה אוֹתָהּ הַבְּכוֹרָה, וְנִטְּלָה הַבְּכוֹרָה מֵרְאוּבֵן, וְנִמְסְרָה לַמָּקוֹם שֶׁהַהִרְהוּר נִדְבַּק בָּהּ. בְּרָחֵל הִרְהֵר וְנִדְבַּק הָרָצוֹן - בְּרָחֵל נִדְבְּקָה הַבְּכוֹרָה, וְהַכֹּל חָזַר אַחַר הַהִרְהוּר וְהַמַּחֲשָׁבָה."],[14,"","כְּמוֹ כֵן הַהִרְהוּר וְהַמַּחֲשָׁבָה עוֹשִׂים מַעֲשֶׂה, וְנִמְשֶׁכֶת מְשִׁיכָה בְּכָל מַה שֶּׁנִּדְבַּק אָדָם בַּסֵּתֶר, שֶׁכָּתוּב (דברים כה) לֹא תִהְיֶה אֵשֶׁת הַמֵּת הַחוּצָה לְאִישׁ זָר יְבָמָהּ יָבֹא עָלֶיהָ. וְכָאן צָרִיךְ הִרְהוּר וְרָצוֹן לְהִתְדַּבֵּק, וּבְאוֹתוֹ הָרָצוֹן וּמַחֲשָׁבָה מוֹשֵׁךְ מְשִׁיכָה וְעוֹשֶׂה הַמַּעֲשֶׂה שֶׁצָּרִיךְ, וְלֹא יִכְלֶה שֵׁם הַמֵּת מִן הָעוֹלָם."],[15,"","וְסֵתֶר זֶה, (איוב לד) אִם יָשִׂים אֵלָיו לִבּוֹ רוּחוֹ וְנִשְׁמָתוֹ אֵלָיו יֶאֱסֹף. שֶׁהֲרֵי וַדַּאי הָרָצוֹן וְהַמַּחֲשָׁבָה מוֹשְׁכִים מְשִׁיכָה וְעוֹשִׂים מַעֲשֶׂה בְּכָל מַה שֶּׁצָּרִיךְ. וְעַל כֵּן בַּתְּפִלָּה צָרִיךְ רָצוֹן וְהִרְהוּר לְכַוֵּן, וְכֵן בְּכָל אוֹתָן הָעֲבוֹדוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא - הַהִרְהוּר וְהַמַּחֲשָׁבָה עוֹשִׂים מַעֲשֶׂה, וּמוֹשְׁכִים מְשִׁיכָה בְּכָל מַה שֶּׁצָּרִיךְ."],[16,"","וַיֵּלֶךָ רְאוּבֵן בִּימֵי קְצִיר חִטִּים וַיִּמְצָא דוּדָאִים בַּשָּׂדֶה. רַבִּי יִצְחָק פָּתַח וְאָמַר, (תהלים קד) מָה רַבּוּ מַעֲשֶׂיךְ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ מָלְאָה הָאָרֶץ קִנְיָנֶךְ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ בְּכַמָּה מְקוֹמוֹת. אֶלָּא מִי יָכוֹל לִמְנוֹת אֶת מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִנֵּה כַּמָּה צְבָאוֹת וּמַחֲנוֹת מְשֻׁנִּים זֶה מִזֶּה שֶׁאֵין לָהֶם חֶשְׁבּוֹן, וְכֻלָּם בְּפַעַם אַחַת, כְּמוֹ פַּטִּישׁ שֶׁמּוֹצִיא זִיקִים לְכָל הַצְּדָדִים בְּפַעַם אַחַת, כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצִיא כַּמָּה מִינִים וּמַחֲנוֹת מְשֻׁנִּים זֶה מִזֶּה שֶׁאֵין לָהֶם חֶשְׁבּוֹן, וְכֻלָּם בְּפַעַם אַחַת."],[17,"","בֹּא רְאֵה, בְּדִבּוּר וּבְרוּחַ יַחַד נַעֲשָׂה הָעוֹלָם, שֶׁכָּתוּב בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ וּבְרוּחַ פִּיו כָּל צְבָאָם. בִּדְבַר ה' - זֶה הַדִּבּוּר. וּבְרוּחַ פִּיו - זוֹ הָרוּחַ. זֶה בְּלִי זֶה לֹא הוֹלֵךְ, וְנִכְלָלִים זֶה עִם זֶה וְיוֹצְאִים מֵהֶם כַּמָּה צְבָאוֹת לַצְּבָאוֹת, וּמַחֲנוֹת לַמַּחֲנוֹת, וְהַכֹּל בְּפַעַם אַחַת."],[18,"","בֹּא רְאֵה, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָמוֹת, הוֹצִיא אוֹר נִסְתָּר אֶחָד, שֶׁמֵּהָאוֹר הַהוּא יוֹצְאִים וּמְאִירִים כָּל אוֹתָם הָאוֹרוֹת שֶׁהִתְגַּלּוּ, וּמֵאוֹתוֹ הָאוֹר יוֹצְאִים וְהִתְפַּשְּׁטוּ וְנַעֲשׂוּ שְׁאָר הָאוֹרוֹת, וְהוּא הָעוֹלָם הָעֶלְיוֹן."],[19,"","וְעוֹד, הָאוֹר הָעֶלְיוֹן הַזֶּה הִתְפַּשֵּׁט וְעָשָׂה אֻמָּן, אוֹר שֶׁאֵינוֹ מֵאִיר, וְעָשָׂה אֶת הָעוֹלָם הַתַּחְתּוֹן. וּמִשּׁוּם שֶׁהוּא אוֹר שֶׁלֹּא מֵאִיר, רוֹצֶה לְהִתְקַשֵּׁר לְמַעְלָה, רוֹצֶה לְהִתְקַשֵּׁר לְמַטָּה. וּבַקֶּשֶׁר שֶׁלְּמַטָּה נִקְשָׁר לְהָאִיר בַּקֶּשֶׁר שֶׁלְּמַעְלָה."]]],[["וְהַאי נְהוֹרָא דְּלָא נָהִיר, בְּקִשּׁוּרָא דִלְעֵילָא, אַפִּיק כָּל חֵילִין וּמַשִּׁרְיָין לְזִינִין סַגִּיאִין, הֲדָא הוּא דִכְתִיב מָה רַבּוּ מַעֲשֶׂיךָ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ וְגו'.","וְכָל מַה דִּי בְאַרְעָא, הָכִי נָמֵי לְעֵילָא. וְלֵית לָךְ מִלָּה זְעֵירָא בְּהַאי עָלְמָא, דְּלָא תַלְיָיא בְּמִלָּה אָחֳרָא עִלָּאָה דְּאִתְפַּקְּדָא עֲלֵיהּ לְעֵילָא, בְּגִין דְּכַד אִתְעַר הַאי לְתַתָּא, אִתְעַר הַהוּא דְּאִתְפַּקְּדָא עֲלֵיהּ לְעֵילָא, דְּכֹלָּא אִתְאֲחַד דָּא בְּדָא.","תָּא חֲזֵי כְּתִיב, (בראשית ל׳:י״ד) תְּנִי נָא לִי מִדּוּדָאֵי בְּנֵךְ. לָאו דּוּדָאִים אוֹלִידוּ לָהּ לְרָחֵל, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא קָא גִּלְגֵּל מִלָּה עַל יְדֵי דְּאִינוּן דּוּדָאִים. בְּגִין דְּיִפּוּק יִשָּׂשכָר, דְּאָחִיד בְּאוֹרַיְיתָא יַתִּיר מִכֻּלְּהוּ שִׁבְטִין. בְּגִין דְּהָא רָחֵל אֲחִידָא בֵּיהּ בְּיַעֲקֹב, לָא שַׁבְקַת לֵיהּ לְגַבֵּי לֵאָה. הֲדָא הוּא דִכְתִיב (בראשית ל׳:ט״ו) הַמְעַט קַחְתֵּךְ אֶת אִישִׁי, וּכְתִיב לָכֵן יִשְׁכַּב עִמָּךְ הַלַּיְלָה תַּחַת דּוּדָאֵי בְּנִךְ.","אִינוּן גָּרְמוּ דְּיִפּוּק יִשָּׂשכָר לְעַלְמָא, בְּגִין דְּסָלִיק רֵיחָא דְאוֹרַיְיתָא, קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב (שיר השירים ז׳:י״ד) הַדּוּדָאִים נָתְנוּ רֵיחַ וְגו'. וּכְתִיב, (בראשית ל׳:ט״ז) וַיִּשְׁכַּב עִמָּהּ בַּלַּיְלָה הוּא. הוּא (קכ\"ד ע\"ב) וַדַּאי, וְהָא אוּקְמוּהָ, דְּעַלְמָא עִלָּאָה. הוּא, דְּסָתִים וְלָא גַלְיָא, בְּגִין דְּהָא אוֹרַיְיתָא מֵעַלְמָא (פ\"ו ע\"ב) עִלָּאָה נָפְקַת.","וּבְכָל אֲתַר, עַלְמָא עִלָּאָה. הוּא, דְּלָא אִתְגַּלְּיָא, וְהָא אִתְּמָר, (במדבר י״ח:כ״ג) וְעָבַד הַלֵּוִי הוּא, בְּגִין לְאַמְשָׁכָא מִנֵּיהּ בִּרְכָאן לְכֹלָּא, וְיִשָּׂשכָר בֵּיהּ אִתְאֲחִיד, וְעַל דָּא קָרִינָן עֵץ הַחַיִּים, אִילָנָא דְאִינוּן חַיִּין עִלָּאִין, דְּאִקְרֵי הוּא וְלא אַתָּה.","וְאִי תֵימָא דְאִלֵּין דּוּדָאִים פָּתְחוּ מְעָהָא דְרָחֵל. לָאו, דְּהָא כְּתִיב, (בראשית ל׳:כ״ב) וַיִּשְׁמַע אֵלֶיהָ אֱלהִים וַיִּפְתַּח אֶת רַחֲמָהּ, קוּדְשָׁא בְּרִיךְ הוּא, וְלָא מִלָּה אָחֳרָא. בְּגִין דְּאִינוּן דּוּדָאִים, אַף עַל גַּב דְּחֵילָא דִלְהוֹן לְעֵילָא. בְּהַהוּא חֵילָא דִלְהוֹן, לָא אִתְמַנֵּי פְּקִידָא דִבְנִין, דְּהָא בְּנִין בְּמַזָּלָא תַּלְיָין, וְלָאו בְּמִלָּה אָחֳרָא.","וְאִי תֵימָא דְּהָא אִינוּן לְמַגָּנָא אִתְבְּרִיאוּ, לָאו, דְּהָא אֲפִילּוּ לְמִלָּה דָא, סִיּוּעָא אִינוּן לְאִינוּן דְּמִתְעַכְּבֵי, וְלָאו אִינוּן עֲקָרָאן, וְלָא אִתְגְּזַר עֲלַיְיהוּ אֶלָּא בְּמַזָּלָא."],[[0,"והאי נהורא דלא נהיר וכו':","ואותו האור שאינו מאיר, דהיינו הקו שמאל בקשר ג' הקוין של מעלה, שבבינה, הוא מוציא כל הצבאות והמחנות למינים הרבה המשונים זה מזה, שזה בחכמה וזה בחסדים כנ\"ל, וזהו שכתוב מה רבו מעשיך ה' וגו'. פירוש. כי \u0003מה רבו מעשיך,\u0004 פירושו הארות החסדים שה\"ס מוחין שאין להם מספר, \u0003וכלם בחכמה עשית,\u0004 פירושו מוחין דמספר, כמ\"ש לעיל בתחלת המאמר, ועם כל זה יצאו בבת אחת, שהוא, משום שהארת השמאל קשורה בב' העולמות ביחד, ועיקר הארתו הוא בעולם העליון, ששם שולטת הארת החסדים המכוסים מחכמה, דהיינו שאין להם מספר, ולפיכך ב' מיני מוחין האמורים, אע\"פ שמשונים הם זה מזה, מ\"מ כל הארה והארה כלולה משניהם, כי יוצאים בבת אחת."],[1,"וכל מה די בארעא וכו':","וכל מה שיש בארץ יש ג\"כ למעלה, ואין לך דבר קטן בעולם הזה, דהיינו בהנוקבא, שאינו תלוי בדבר אחר, עליון, הממונה עליו מלמעלה דהיינו בבינה, כי כל מה שבנוקבא, אינה אלא ממה שמקבלת מבינה, וע\"כ, אין לך דבר בהנוקבא, שאין לו שורש בבינה. וע\"כ כשנתעורר דבר למטה בנוקבא, נתעורר מקודם השורש שלו הממונה עליו למעלה בבינה, כי הכל מיוחד זה בזה."],[2,"תא חזי כתיב וכו':","בוא וראה, כתוב תני נא לי מדודאי בנך, אין הפירוש, שהכתוב בא לומר, שהדודאים הולידו את רחל, אלא הפירוש הוא, שהקב\"ה סבב הדבר, על ידי אלו הדודאים, שיולד יששכר. שהחזיק בתורה יותר מכל השבטים. כי רחל היתה מחזקת ביעקב, ולא נתנה לו ללכת ללאה, זהו שכתוב, המעט קחתך את אישי, וכתוב, לכן ישכב עמך הלילה תחת דודאי בנך."],[2,"","ביאור הדברים. אחר שהאריך ר' יצחק וביאר היטב, אשר הנהורא דלא נהיר שה\"ס הארת חכמה שבקו שמאל, לא יוכל להאיר רק בב' עולמות, שהם בינה ונוקבא, כי שורשו הוא מבינה, אבל הוא צריך למסך דחירק שהוא בזו\"ן כדי להוציא עליו קו אמצעי המכריע, כנ\"ל, פתח בזה את כל דברי הפרשה. כי ז\"ס וילך ראובן וימצא \u0003דודאים\u0004 בשדה, ויבא אותם אל לאה \u0003אמו.\u0004 כי דודאים ה\"ס הארת השמאל, שהוא נהורא דלא נהיר, ונקרא \u0003דודאים\u0004 להיותו השורש לאהבת דודים (כנ\"ל לך דף קמ\"ז ד\"ה פנימיות) ומשמיענו הכתוב, שבן לאה מצא אותם והביאם לאמו, ללמדנו ששורש אור הזה הוא בלאה דהיינו בינה, ולא ברחל. אבל רחל מקבל אותו מלאה, כנ\"ל, וזהו שאמרה ללאה, \u0003תני נא לי מדודאי בנך,\u0004 שרצתה לזכות באור הזה. \u0003ותאמר לה המעט קחתך את אישי,\u0004 כי ז\"א שהוא בעל המסך דחירק המשלים להארת הדודאים בהכרעתו, נמצא קבוע עם המסך ברחל, כי היא נושאת המסך דחירק בעת שז\"א אצלה כנ\"ל, וזהו שטענה לאה לרחל: את רוצה בשניהם, להחזיק את המסך דחירק, שאני צריך לו, כדי להוציא קו אמצעי, וגם את רוצה בדודאים שלי, אשר בלי יעקב, שה\"ס קו אמצעי, הם אינם מאירים אפילו אצלי, ולפיכך השיבה לה \u0003לכן ישכב עמך הלילה הוא, הוא,\u0004 סובב על המסך דחירק שבו, כדי שמזווגו תמשך קומת קו אמצעי המיחדת ב' הקוין בלאה, ואז הדודאים נשלמים בה, ואח\"כ נתנה אותם גם לרחל, בסוד תלת נפקי מחד, חד בתלת קיימא כנ\"ל."],[3,"אינון גרמו דיפוק וכו':","הם גרמו שיצא יששכר לעולם, כדי שיעלה ריח תורה לפני הקב\"ה. וזהו שכתוב הדודאים נתנו ריח וגו', כי יששכר הוא נאחז בתורה יותר מכל השבטים, כנ\"ל באות קצ\"ו."],[3,"וכתיב וישכב וגו':","וכתוב וישכב עמה בלילה הוא, \u0003הוא\u0004 ודאי, ולא ההוא, וכבר בארוה, שעולם העליון נקרא \u0003הוא,\u0004 משום שסתום ואינו מגולה. ומשום שהתורה יצאה מעולם העליון, שהוא נעלם וסתום, ע\"כ נרמז זה בזווג שבשביל יששכר, וישכב עמה בלילה \u0003הוא,\u0004 מטעם שיששכר הוא מרכבה לתורה כנ\"ל."],[4,"ובכל אתר עלמא וכו':","ובכל מקום נקרא עולם העליון \u0003הוא,\u0004 כי אינו מגולה, וכן נאמר, ועבד הלוי \u0003הוא,\u0004 שפירושו שעובד לעולם העליון הנקרא \u0003הוא,\u0004 כדי להמשיך משם ברכות לכל העולמות, ויששכר נאחז בו, בעולם העליון. ועל כן אנו קוראים לז\"א עץ החיים, להיותו אילן הנמשך מן החיים העליונים, שבעולם העליון הנסתר, הנקרא הוא ולא \u0003אתה.\u0004 כי המלה \u0003אתה\u0004 יורה על נגלה, והמלה הוא יורה על נסתר (כנ\"ל דף ס\"ו אות קנ\"א)."],[5,"ואי תימא וכו':","ואם תאמר שאלו הדודאים פתחו רחמה של רחל, אינו כן, כי כתוב וישמע אליה אלקים ויפתח את רחמה. הרי שהקב\"ה פתח את רחמה ולא דבר אחר. כי אלו הדודאים, אף על פי שיש להם כח לפעול למעלה, מכל מקום לא ניתן בכח שלהם פקידה של בנים, כי בנים תלוים במזל, שה\"ס דיקנא דא\"א, ולא בדבר אחר, (כנ\"ל בראשית ב' דף ע\"א אות ק\"י ע\"ש)."],[6,"ואי תימא דהא וכו':","ואם תאמר,שהדודאים נבראו בחנם, כלומר שאינם פועלים לשום דבר. אינו כן, אלא שיש להם פעולה מיוחדת, ואפילו לדבר זה. דהיינו לבנים, המה עוזרים את אלו המתעכבות מלהוליד ואינן עקרות. אמנם לא נגזר עליהם להוליד אלא במזל. כלומר אם כבר נגזר עליהם להוליד בסוד המזל, אלא שמתעכבים משום איזה סבה, אז מועילים הדודאים."]],[[0,"","וְהָאוֹר הַזֶּה שֶׁאֵינוֹ מֵאִיר בַּקֶּשֶׁר שֶׁלְּמַעְלָה, מוֹצִיא אֶת כָּל הַחֲיָלוֹת וְהַמַּחֲנוֹת לְמִינִים רַבִּים. זֶהוּ שֶׁכָּתוּב מָה רַבּוּ מַעֲשֶׂיךְ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ וְגוֹ'."],[1,"","וְכָל מַה שֶּׁבָּאָרֶץ כָּךְ גַּם לְמַעְלָה, וְאֵין לְךְ דָּבָר קָטָן בָּעוֹלָם הַזֶּה שֶׁלֹּא תָלוּי בְּדָבָר אַחֵר עֶלְיוֹן שֶׁהִתְמַנָּה עָלָיו לְמַעְלָה. מִשּׁוּם שֶׁכְּשֶׁמִּתְעוֹרֵר זֶה שֶׁלְּמַטָּה, מִתְעוֹרֵר אוֹתוֹ שֶׁהִתְמַנָּה עָלָיו לְמַעְלָה, שֶׁהַכֹּל נֶאֱחָז זֶה עִם זֶה."],[2,"","בֹּא רְאֵה, כָּתוּב תְּנִי נָא לִי מִדּוּדָאֵי בְּנֵךְ. לֹא הַדּוּדָאִים הֵם שֶׁיִּלְּדוּ אֶת רָחֵל, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלְגֵּל אֶת הַדָּבָר עַל יְדֵי אוֹתָם דּוּדָאִים כְּדֵי שֶׁיֵּצֵא יִשָּׂשכָר, שֶׁאוֹחֵז בַּתּוֹרָה יוֹתֵר מִכָּל הַשְּׁבָטִים, מִשּׁוּם שֶׁהֲרֵי רָחֵל הָאֲחוּזָה בְּיַעֲקֹב לֹא הִשְׁאִירָה אוֹתוֹ לְלֵאָה. זֶהוּ שֶׁכָּתוּב הַמְעַט קַחְתֵּךְ אֶת אִישִׁי, וְכָתוּב לָכֵן יִשְׁכַּב עִמָּךְ הַלַּיְלָה תַּחַת דּוּדָאֵי בְנֵךְ."],[3,"","הֵם גָּרְמוּ שֶׁיֵּצֵא יִשָּׂשכָר לָעוֹלָם מִשּׁוּם שֶׁמַּעֲלֶה הָרֵיחַ שֶׁל הַתּוֹרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, זֶהוּ שֶׁכָּתוּב הַדּוּדָאִים נָתְנוּ רֵיחַ וְכוּ', וְכָתוּב וַיִּשְׁכַּב עִמָּהּ בַּלַּיְלָה הוּא, הוּא וַדַּאי, וַהֲרֵי פֵּרְשׁוּהָ שֶׁהָעוֹלָם הָעֶלְיוֹן הוּא שֶׁנִּסְתָּר וְלֹא נִגְלֶה, מִשּׁוּם שֶׁהֲרֵי הַתּוֹרָה יוֹצֵאת מֵהָעוֹלָם הָעֶלְיוֹן."],[4,"","וּבְכָל מָקוֹם הָעוֹלָם הָעֶלְיוֹן הוּא שֶׁלֹּא הִתְגַּלָּה, וַהֲרֵי נֶאֱמַר וְעָבַד הַלֵּוִי הוּא, כְּדֵי לְהַמְשִׁיךְ מִמֶּנּוּ בְּרָכוֹת לַכֹּל, וְיִשָּׂשכָר נֶאֱחָז בּוֹ, וְעַל כָּךְ קוֹרְאִים עֵץ הַחַיִּים, הָעֵץ שֶׁלְּאוֹתָם הַחַיִּים הָעֶלְיוֹנִים שֶׁנִּקְרָא הוּא וְלֹא אַתָּה."],[5,"","וְאִם תֹּאמַר שֶׁהַדּוּדָאִים הַלָּלוּ פָּתְחוּ אֶת מֵעֶיהָ שֶׁל רָחֵל - לֹא, שֶׁהִנֵּה כָּתוּב וַיִּשְׁמַע אֵלֶיהָ אֱלֹהִים וַיִּפְתַּח אֶת רַחְמָהּ. הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא דָבָר אַחֵר. מִשּׁוּם שֶׁאוֹתָם הַדּוּדָאִים, אַף עַל פִּי שֶׁכֹּחָם לְמַעְלָה, בְּאוֹתוֹ הַכֹּחַ שֶׁלָּהֶם לֹא מִתְמַנֶּה פְּקִידַת הַבָּנִים, שֶׁהֲרֵי הַבָּנִים תְּלוּיִים בְּמַזָּל, וְלֹא בְּדָבָר אַחֵר."],[6,"","וְאִם תֹּאמַר שֶׁהִנֵּה הֵם נִבְרְאוּ לְחִנָּם - לֹא, שֶׁהֲרֵי אֲפִלּוּ לַדָּבָר הַזֶּה הֵם סִיּוּעַ לְאוֹתָם שֶׁמִּתְעַכְּבִים, וְאֵינָם עֲקָרוֹת, וְלֹא נִגְזָר עֲלֵיהֶם אֶלָּא בְּמַזָּל."]]],[["\u0003סתרי תורה\u0004 וַיֵּלֶךָ רְאוּבֵן בִּימֵי קְצִּיר חִטִים וַיִּמְצָּא דוּדָאִים בַּשָׂדֶה וְגו'. תְּנַן, כּוֹס שֶׁל בְּרָכָה לָא אִתְּבָּרְכָא, אֶלָּא בִסְטַר יְמִינָא. וּבְגִין כָּךָ, בְּעוֹד דְּאִתְּעַר יְמִינָא לְגַבֵּי כּוֹס שֶׁל בְּרָכָה, שְׂמָאלָא לָא תְּסַיֵּיעַ תַּמָּן. דְּהָא יְמִינָא אַשְׁכַּח עִילָּה בְּהַהוּא כּוֹס, לְאִתְּעָרָא לְגַבֵּי עַלְמָא עִלָּאָה.","וְסִתְּרָא דָא, וַיֵּלֶךָ רְאוּבֵן, דָּא סִטְרָא דְדָרוֹם. בְּגִין כָּךָ דִּגְלֵיהּ בַּדָּרוֹם, דְּאִיהוּ רֵישָׁא לִתְּרֵיסַר תְּחוּמִין, וְתִּיאוּבְתֵּיהּ דִּסְטַר דָּרוֹם, לְאַשְׁכָּחָא עִילָּה וְתִּקְרוֹבָא לְמַטְרוֹנִיתָּא לְבָרְכָא לָהּ.","מַה כְּתִּיב, וַיִּמְצָּא דוּדָאִים בַּשָׂדֶה, אֲזַל לְחַפְּשָׂא בְּכָל אִינוּן גְּנִיזִין דִּילָהּ, וְאַשְׁכַּח בְּהַאי שָׂדֶה אִינוּן דּוּדָאִים, וְעֲלַיְיהוּ אִתְּמָר (שיר השירים ז׳:י״ד) הַדּוּדָאִים נָתְּנוּ רֵיחַ, וְאִינוּן תְּרֵין (קנ\"ב ע\"א) כְּרוּבִים, דְּאִינוּן תִּקּוּנִין דִּילָהּ, לְאִתְּעָרָא אִתְּעָרוּ לְעֵילָא, דְּהָא בְּכָל אִינוּן תִּקּוּנִין דְּהַאי שָׂדֶה, לֵיתּ תִּקּוּנָא דְּיִתְּעַר לְגַבֵּי עֵילָא, בַּר כְּרוּבִים.","סְטַר דָּרוֹם אֵימָתַּי אִתְּעַר לְגַבָּהּ, לְאַשְׁכָּחָא עִילָּה לְבָרְכָה לָהּ. בִּימֵי קְצִּיר חִטִים, בְּזִמְנָא דִּפְּלִיגַתּ חוּלַק שְׁלָלָא לְאוּכְלוּסָהָא, וְכֻלְּהוּ חַצְּדֵי חַקְלָא. מִיָּד וַיָּבֵא אוֹתָּם אל לֵאָה אִמּוֹ, סָלִיק רֵיחָא, וְאִתְּעָרוּ דִּלְהוֹן לְגַבֵי עַלְמָא עִלָּאָה, עַלְמָא דְאִתְּכַּסְּיָא, בְּגִין דְּאִתְּעַר (נ\"א דיתער) בִּרְכָאן לְעַלְמָא תַּתָּאָה.","וְכַד אִתְּבָּרְכָא, אִינוּן דּוּדָאִים נָקְטִין וְיָהֲבִין לְכָל עַלְמִין, דִּכְתִּיב, (שיר השירים ז׳:י״ד) הַדּוּדָאִים נָתְּנוּ רֵיחַ וְעַל פְּתָּחֵינוּ כָּל מְגָדִים. כַּד אִינוּן נָתְּנוּ רֵיחַ, הַהוּא רֵיחָא נָקִיט לֵיהּ סְטַר דָּרוֹם לְאִתְּעָרָא לְגַבֵּי עַלְמָא עִלָּאָה, מִיָּד על פְּתָּחֵינוּ כָּל מְגָדִים, וְכָל טוּבָא לָא חָסִיר (ס\"א מכלא) מֵעַלְמָא.","עַלְמָא תַּתָּאָה לָא אִתְּעַר לְגַבֵּי עַלְמָא עִלָּאָה, אֶלָּא כַּד אִינוּן דּוּדָאִים יַהֲבִין רֵיחָא לִימִינָא, כֵּיוָן דְּאִינוּן יָהֲבִין רֵיחָא לִימִינָא, וִימִינָא אִתְּעַר לְגַבֵּי עַלְמָא עִלָּאָה, מִיָּד עַלְמָא תַּתָּאָה אִתְּעַר לְשָׁאֲלָא מַה דְּאִצְּטְרִיךָ. מַה כְּתִּיב, (בראשית ל׳:י״ד) וַתֹּאמֶר רָחֵל אל לֵאָה תְּנִי נָא לִי מִדּוּדָאֵי בְּנִךָ, הַב לִי בִּרְכָאן מֵהַהוּא אִתְּעָרוּ, דְּאִינוּן דּוּדָאִים דְּאִתְּעַר לְגַבֵּי סְטַר יְמִינָא.","כְּדֵין עַלְמָא עִלָּאָה בְּחֶדְוָה, בְּשִׁעֲשׁוּע, אָתִּיב לְגַבָּהּ, וְאֲמְרַתּ הַמְעַט קַחְתֵּךָ אֶתּ אִישִׁי, כְּאִמָּא לְגַבֵּי בְּרַתָּא. ואִי הָכִי בַּעֲלָה דְּעַלְמָא עִלָּאָה יַעֲקֹב אִיהוּ. לָאו הָכִי, אֶלָּא תִּיאוּבְתָּא דְאַבָּא תָּדִיר, לָאו אִיהוּ, אֶלָּא לְגַבֵּי בְּרַתָּא דְנָא, (דאיהי) דְּהַאי בַּתּ, רְחִימוּ דִילֵיהּ לְגַבָּהּ תָּדִיר, בְּגִין דְּאִיהִי בַּתּ יְחִידָאָה בֵּין שִׁיתּ בְּנִין, וּלְכָל אִינוּן שִׁיתּ בְּנִין, פָּלִיג לוֹן חוּלָקִין וּנְבַזְבְּזָן וּמַתְּנָן, וְלָהּ לָא פָּלִיג, וְלֵיתּ לָהּ יְרוּתָּא כְּלוּם, וְעַל כָּל דָּא, אִיהוּ אַשְׁגַּח בָּהּ בְּתִּיאוּבְתָּא וּרְחִימוּ יַתִּיר מִכֹּלָּא.","בִּרְחִימוּ דִילֵיהּ קָרָא לָהּ בַּתּ, לָא סָפִּיק לֵיהּ דָּא, וְקָרָא לָהּ אָחוֹתּ, לָא סָפִּיק לֵיהּ דָּא, קָרָא לָהּ אֵם בְּשׁוּם אִמֵּיהּ, לָא סָפִּיק לֵיהּ דָּא, קָרָא לָהּ בִּשְׁמֵיהּ, דִּכְתִּיב, (איוב כ״ח:י״ב) וְהַחָכְמָה מֵאַיִן תִּמָּצֵּא, חָכְמָה ודַּאי. וְעַל דָּא, עַלְמָא עִלָּאָה אֲמְרַתּ לְגַבָּהּ, הַמְעַט קַחְתֵּךָ אֶתּ אִישִׁי, דְּכָל רְחִימוּ דִילֵיהּ אִתְּמְשַׁךָ לָךָ לְגַבָּךָ ועל דָּא. בְּשַׁעֲשׁוּעא וּרְחִימוּ אִימָּא לְגַבֵּי בְּרַתָּא.","מָה אֲתִּיבַתּ אִיהִי, (בראשית ל׳:ט״ו) לָכֵן יִשְׁכַּב עִמָּךָ הַלַּיְלָה. בְּכָל אֲתַּר, לָכֵן, שְׁבוּעָה אִיהִי. יִשְׁכַּב, מַהוּ יִשְׁכַּב. אֶלָּא שְׁכִיבָה בְּכָל אֲתַּר תִּקּוּנָא דְנוּקְבָא לְגַבֵּי דְכוּרָא, לְאָעֳלָא בָהּ צִּיּוּרָא דְּאַתְּוָון כֻּלְּהוּ, וְדָא אִיהוּ יִשְׁכַּב, יִ\"שׁ כַּ\"ב. י\"שׁ דָּא אִיהוּ עַלְמָא עִלָּאָה, (ס\"א כ\"ב רזא) רָזָא דְאוֹרַיְיתָּא נְקוּדָה טְמִירָא, דְּאִתְּעַר לְגַבָּהּ כ\"ב אַתְּוָון, וְדָא הוּא יִשְׁכַּב, י\"ש עַלְמָא דְאָתֵּי, דִּכְתִּיב, (משלי ח׳:כ״א) לְהַנְחִיל אוֹהֲבַי יֵשׁ. כ\"ב נְקוּדָה עִלָּאָה דְּאָעִיל כָּל כ\"ב אַתְּוון. רָזָא דְּכָל אוֹרַיְיתָּא.","וְדָא הוּא יִשְׁכַּב, יִשְׁכַּב עִמָּךָ יַעֲקֹב לָא כְּתִּיב, אֶלָּא יִשְׁכַּב עִמָּךָ. הַהוּא טְמִירָא דְּאִתְּחֲזֵי לְאִתְּעָרָא לְגַבָּךָ, וְכלָּא בְּאִתְּעָרוּ דְּאִינוּן (דכולהו) דּוּדָאִים, וכֹלָּא כְּתִּיב בִּרְחִימוּ.","(בראשית ל׳:ט״ז) וַיָּבֹא יַעֲקֹב מִן הַשָׂדֶה בָּעֶרֶב. וַיָּבֹא יַעֲקֹב, דָּא תִּפְּאֶרֶתּ קַדִּישָׁא, מֵהַהוּא שָׂדֶה דְּנָקִיט כָּל בִּרְכָאן, דִּכְתִּיב בֵּיהּ (בראשית כ״ז:כ״ז) אֲשֶׁר בֵּרֲכוֹ יְיָ. בָּעֶרֶב, אַמַּאי בָּעֶרֶב, אֶלָא בָּעֶרֶב, דִּכְתִּיב, (בראשית כ״ד:ס״ג) וַיֵּצֵּא יִצְּחָק לָשׂוּחַ בַּשָׂדֶה לִפְּנוֹתּ עֶרֶב. בְּזִמְנָא דְאִתְּעַר יִצְּחָק אֲבוֹי לְגַבֵּי הַאי שָׂדֶה, וְנָקִיט לֵיהּ, דְּהָא יִצְּחָק לָא אִתְּעַר לְגַבֵּי הַאי שָׂדֶה, כֵּיוָן דְּאִסְתַּלַּק יַעֲקֹב מִתַּמָּן בָּעֶרֶב, שָׁבִיק הַאי שָׂדֶה לְיִצְּחָק אֲבוֹי, וְאִיהוּ סָלִיק בְּהַהוּא זִמְנָא לְגַבֵּי עֵילָא.","מַה כְּתִּיב, (בראשית ל׳:ט״ז) וַתֵּצֵּא לֵאָה לִקְרָאתּוֹ. אִמָּא עִלָּאָה לְגַבֵּי בְּרָא יְחִידָא. וַתֹּאמֶר אֵלַי תָּבוֹא, תְּחוֹתּ גַּדְפָּאי לְבָרְכָא לָךָ, וּלְרַוָואָה לָךָ בְּתַּפְּנוּקִין וְעִדּוּנִין עִלָּאִין. הָא עִידַן רַעֲוָא וְעִנּוּגָא לְמֵיהַב לָךָ נַיְיחָא דְרוּחָא עִלָּאָה, לְגַבֵּי הַהוּא שָׂדֶה, עַד לָא יִתּוֹקַּד בְּתּוּקְפָּא דְיִצְּחָק.","כֵּיוָן דְּנָקְטָא לְיַעֲקֹב תְּחוֹתּ גַּדְפָּאָה, כְּדֵין (שם) וַיִּשְׁכַּב עִמָּהּ בַּלַּיְלָה הוּא. הוּא. דְּסָתִּים מִכֹּלָּא. הוּא. דְּכָל בִּרְכָאן וְכָל קִדּוּשִׁין נָפְּקֵי מִתַּמָּן. יַעֲקֹב לָא כְּתִּיב אֶלָּא הוּא. מַאן דְּאִתְּחֲזֵי לְאִתְּעָרָא לְגַבָּהּ.","וְעַד דְּלָא זַמִּין לְגַבָּהּ תְּחוֹתּ גַּדְפָּהָא, מַאן דְּנָקִיט אִינוּן קַדִּישָׁאן (קדושאן) וּבִרְכָאן לָא אִתְּמְלֵי מִנְּקוּדָה טְמִירָא, הַהוּא עַלְמָא עִלָּאָה. וְעַל דָּא דּוּדָאִים מִתְּעָרֵי כּלָּא, וְכֹלָּא כְּגַוְונָא דְּרָזָא עִלָּאָה. רְאוּבֵן מַאי רְאוּבֵן, קוּדְשָׁא בְּרִיךָ הוּא שַׁוִּי שְׁמָהָן בְּאַרְעָא, דִּכְתִּיב (תהילים מ״ו:ט׳) לְכוּ חֲזוּ מִפְּעֲלוֹתּ יְיָ אֲשֶׁר שָׂם שַׁמּוֹתּ בָּאָרְץ. (עד כאן סתרי תורה).","(בראשית ל׳:ט״ז) וַתֵּצֵא לֵאָה לִקְרָאתוֹ וַתֹּאמֶר אֵלַי תָבוֹא וְגו'. הַאי מִלָּה חֲצִיפוּתָא אִיהוּ. לָאו אִיהוּ הָכִי, אֶלָא מֵהָכָא אוֹלִיפְנָא, עִנְוְותָנוּתָא דְלֵאָה, דְּלָא אָמְרָה קַמֵּי אֲחָתָהּ מִידִּי, וְאִיהִי אַקְדִימַת לְאוֹרְחָא, וְאָמְרָה לֵיהּ בַּחֲשַׁאי, וְאוֹדְעָא לֵיהּ. דְּהָא בִרְשׁוּתָא דְרָחֵל הֲוָה, דִּכְתִיב, (שם) כִּי שָׂכוֹר שְׂכַרְתִּיךָ, מֵרָחֵל נְטִילַת רְשׁוּ, וּבְגִין דְּלָא יַבְאִישׁ בְּעֵינָאָה דְרָחֵל, אָמְרָה לֵיהּ לְבַר וְלָא בְּבֵיתָא.","וְלָא עוֹד אֶלָּא פִּתְחָא מִשְׁכְּנָא דְלֵאָה (לבר), נָפְקַת לְבַר, וְעַיְילַת לֵיהּ לְיַעֲקֹב בְּפִתְחָא דִלְבַר, עַד לָא יֵיעוּל לְמִשְׁכְּנָא דְרָחֵל. מַאי טַעְמָא, בְּגִין דְּלָא תֵימָא מִלָּה קַמֵּי דְרָחֵל, וְלָא תַחְצִיף קַמֵּי אֲחָתָהָא. וְלָא עוֹד, אֶלָּא אָמְרָה לֵאָה, אִי יֵיעוּל יַעֲקֹב בְּמִשְׁכְּנָא דְרָחֵל, לָאו דִּין הוּא לְאַפְקֵיהּ מִתַּמָּן, בְּגִין כָּךְ אַקְדִימַת לֵיהּ לְבַר.","וְכָל הַאי לָמָּה, אֶלָּא לֵאָה רוּחָא דְקוּדְשָׁא אִתְעָרַת בָּהּ, וְיָדְעַת דְּכָל הַנֵּי שִׁבְטִין עִלָּאִין, כֻּלְּהוּ קַדִּישִׁין, יִפְקוּן מִנָּהּ, וְדָחְקַת שַׁעְתָּא, בַּחֲבִיבוּתָא לְקוּדְשָׁא בְּרִיךְ הוּא, וּבְגִין כָּךְ הִיא קָרָאת לוֹן שְׁמָהָן, בְּרָזָא דְחָכְמְתָא.","רַבִּי חִיָּיא וְרַבִּי יוֹסֵי, הֲווּ אָזְלֵי בְּאוֹרְחָא, אָמַר רִבִּי יוֹסֵי לְרַבִּי חִיָּיא, בְּכָל זִמְנָא (דאנן) דְּאָזְלִינָן בְּאוֹרְחָא, וְלָעֵינָן בְּאוֹרַיְיתָא, קוּדְשָׁא בְּרִיךְ הוּא מַרְחִישׁ לָן נִסִּין, וְהַשְׁתָּא אוֹרְחָא דָא אָרִיךְ לָן, נִתְעַסַּק בְּאוֹרַיְיתָא, וְקוּדְשָׁא בְּרִיךְ הוּא יִזְדַּוֵּוג בַּהֲדָן.","פָּתַח רִבִּי חִיָּיא וְאָמַר, (שמות י״ב:י״ח) בָּרִאשׁוֹן בְּאַרְבָּעָה עָשָׂר יוֹם לַחֹדֶשׁ בָּעֶרֶב תֹּאכְלוּ מַצּוֹת, וּכְתִיב, (דבהם טז) שִׁבְעַת יָמִים תֹּאכַל עָלָיו מַצּוֹת לֶחֶם עֹנִי, לֶחֶם עָנִי כְּתִיב, הַאי מִלָּה אִתְעָרוּ בָּהּ חַבְרַיָיא. אֲבָל תָּא חֲזֵי, כַּד הֲווּ יִשְׂרָאֵל בְּמִצְרַיִם, הֲווּ בִּרְשׁוּתָא אָחֳרָא. כַּד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְקָרְבָא לוֹן לְגַבֵּיהּ, יָהַב לוֹן אֲתַר דְּלֶחֶם עֹנִי. לֶחֶם עָנִי, מַאן עָנִי. דָּא דָּוִד מַלְכָּא, דִּכְתִיב בֵּיהּ (תהלים מו) כִּי עָנִי וְאֶבְיוֹן אָנִי.","וְהַאי לֶחֶם עֹנִי אִקְרֵי מַצָּה, נוּקְבָא בְּלָא דְכוּרָא, מִסְכְּנוּתָא הֲוֵי, אִתְקְרִיבוּ לְגַבֵּי מַצָּה בְּקַדְמִיתָא, כֵּיוָן דְּקָרִיבוּ לוֹן יַתִּיר, עֲיִּיל לוֹן קוּדְשָׁא בְּרִיךְ הוּא בְּדַרְגִּין אָחֳרָנִין, וְאִתְחַבַּר דְּכוּרָא בְּנוּקְבָא. וּכְדֵין, מַצָּה כַּד אִתְחַבְּרַת בִּדְכוּרָא אִקְרֵי מִצְוָה בְּתוֹסֶפֶת וא\"ו, הֲדָא הוּא דִכְתִיב, (דברים ל׳:י״א) כִּי הַמִּצְוָה הַזֹּאת. בְּגִינִי כָּךְ, מַצָּה בְּקַדְמִיתָא, וּלְבָתַר מִצְוָה.","עַד דְּהֲווּ אָזְלֵי, שְׁמָעוּ חַד קָלָא דְּאָמַר, טוּפְסְרָא דְּקַטְנּוּן, עֲקִימָן בְּאוֹרְחָא, סְטוּ לְעֵילָא, לָא תֶחתוּן בְּקוּסְטְרָא דְּקִטְרָא דִלְתַתָּא. אָמַר רִבִּי יוֹסֵי, שְׁמַע מִינָהּ, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְנַטְרָא אוֹרְחִין. סְלִיקוּ לְעֵילָא, וְעָאלוּ בְּחַד טוּרָא, בֵּין טִנָּרִין תַּקִּיפִין, אָמְרוּ, הוֹאִיל וְקוּדְשָׁא בְּרִיךְ הוּא בָּעָא בְּאוֹרְחָא דָא, מִלָּה נְחמֵי אוֹ נִיסָּא (תרחיש) אִתְרְחִישׁ לָן.","אָזְלֵי, יָתְבֵי גַּבֵּי בְּקִיעֵי דְּטִנָּרָא. סָלִיק לוֹן חַד בַּר נָשׁ, תְּוָוהוּ, אָמַר רִבִּי יוֹסֵי מַאן אַנְתְּ. אָמַר מֵאַנְשֵׁי אַרְקָא אֲנָא, אָמַר לֵיהּ, וְתַמָּן אִית בְּנֵי נָשָׁא, אָמַר אִין, וְזָרְעִין וְחַצְדִין, מִנַּיְיהוּ בְּחֵיזוּ אָחֳרָא מְשַׁנְיָין מִנָּאי, וְסָלִיקְנָא גַבַּיְיכוּ, לְמִנְדַע מִנַּיְיכוּ, מַה שְּׁמֵיהּ דְּאַרְעָא דְּאַתּוּן בָּהּ.","אָמַר לֵיהּ, אֶרֶץ, בְּגִין דְּהָכָא אֶרֶץ הַחַיִּים שַׁרְיָא, דִּכְתִיב, (איוב כ״ח:ה׳) אֶרֶץ מִמֶּנָּה יֵצֵא לָחֶם, מֵהַאי יֵצֵא לֶחֶם, בִּשְׁאָר אַרְעָא לָא יֵצֵא לָחֶם, וְאִי נָפִיק, לָאו מִשִּׁבְעַת הַמִּינִין. אַדְּהָכִי עָאל לְאַתְרֵיהּ. תְּוָוהוּ, אָמְרוּ ודַּאי קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְאִתְעָרָא לָן בְּמִלָּה.","אָמַר רִבִּי חִיָּיא, וַדָּאי עַל הַאי קְרָא דְּאֲמַרְתָּ, דָּכִירְנָא דְּאוֹלִיפְנָא מִסָּבָאי, חַד מִלָּה עִלָּאָה. בְּפֶסַח, דְּיָהַב לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל לֶחֶם דָּא, מֵאַרְעָא דְחַיֵּי, וּלְבָתַר לֶחֶם מִן הַשָּׁמַיִם, לֶחֶם דָּא, וְהָא אוֹקִימְנָא מִלָּה."],[[0,"וילך ראובן וגו':","למדנו, כוס של ברכה, שה\"ס הנוקבא מבחינת הארת חכמה שבה, שמאירה בסוד יין המשמח אלקים ואנשים, אינה מתברכת רק בצד ימין, שהוא חסדים, כי חכמה בלי חסדים הוא חשך כנודע. ומשום זה, בעוד שהימין נתעורר להשפיע אל כוס של ברכה, שהוא הנוקבא, השמאל לא יתמך שם, כי הימין מצא סבה בכוס, שבגללה יתעורר אל עולם העליון, שה\"ס חסדים מכוסים מחכמה."],[0,"","פירוש. הנוקבא, בעת שהיא בבחינת קו שמאל, שה\"ס חכמה בלי חסדים, היא נקראת \u0003כוס,\u0004 ואז אינה מאירה, והיא צריכה \u0003לברכה\u0004 שה\"ס המשכת החסדים מקו ימין הנקראת ברכה. וז\"ש \u0003בעוד דאתער ימינא לגבי כוס של ברכה, שמאלא לא תסייע תמן.\u0004 שבעת שהימין משפיע לה חסדים, תפסוק אז לגמרי הארת השמאל, שהיא חכמה. \u0003דהא ימינא אשכח עילה בההוא כוס לאתערא לגבי עלמא עלאה,\u0004 כי הימין מצא סבה בכוס, דהיינו במה שנחשך ואינו מאיר, שבגלל סבה זו, עזב הארת החכמה שמשמאל, ונתעורר להמשיך חסדים מעולם העליון, שהוא לאה, שהיא בחסדים מכוסים מחכמה. ואם יהיה אז איזה תמיכה משמאל לא יוכל הימין להתדבק בעולם העליון המכוסה מחכמה, ולהמשיך משם חסדים. כי דבקות, פירושו השואת הצורה."],[1,"וסתרא דא, וילך וכו':","וזה סוד, וילך ראובן, שהוא צד דרום, דהיינו קו ימין, חסדים, כי משום זה, דגלו בדרום, שהוא ראש ותחילה לשנים עשר גבולים, שסוד י\"ב גבולים ה\"ס ד' רוחות חסד וגבורה ת\"ת ומלכות שבכל אחד ג' קוין (כנ\"ל דף ס\"ד ד\"ה ביאור) הרי שחסד הוא תחילה לי\"ב גבולים, ותשוקתו של צד דרום הוא, למצוא סבה (כנ\"ל בדבור הסמוך), ומתנה לרבונית, דהיינו הנוקבא, לברך אותה."],[2,"מה כתיב וימצא וכו':","מה כתוב, וימצא דודאים בשדה, הלך לחפש בכל האוצרות של הנוקבא, ומצא בשדה הזו, שהוא הנוקבא את הדודאים. ועליהם נאמר הדודאים נתנו ריח. והם שני הכרובים, שהם תקונה של הנוקבא, להתעורר התעוררות למעלה אל הבינה, כי בכל התקונים של שדה הזו, אין תקון שיתעורר למעלה לבינה, חוץ הכרובים."],[2,"","פירוש כי דודאים ה\"ס הארת חכמה שבקו שמאל. (ב\"ב פ' אות קכ\"ד. לך קמ\"ו אות תנ\"ג). וכל עוד שמחוסרת חסדים אינה מאירה ונחשב כאילו אינה. וז\"ש \u0003אזל לחפשא בכל אינון גניזין דילה ואשכח בהאי שדה אינון דודאים,\u0004 שראובן שה\"ס אור החסד, הלך לחפש ולגלות את הדודאים בשדה, שאינם נמצאים זולתו, דהיינו ע\"י שמלביש אותם באור החסד הם מתגלים ומאירים. וע\"כ נחשב שהוא מצא אותם, כלומר שגילה אותם. וז\"ש \u0003והם שני הכרובים,\u0004 כי הכרובים מהארת השמאל באים, (כנ\"ל בהקדמת ספר הזהר דף י\"ב ד\"ה ואלמלי ע\"ש) וז\"ש \u0003דאינון תקונא דילה לאתערא אתערו לעילא,\u0004 כי כל התקונים והמוחין, הנוקבא מקבלת מז\"א, ולא מבינה רק אלו המוחין דהארת השמאל בסוד הדודאים היא מקבלתם מבינה עצמה בשוה עם ז\"א, שאז היא בסוד ב' מאורות הגדולים, (כנ\"ל בראשית א' דף ק\"ג אות ק\"י) וז\"ש \u0003דהא בכל אינון תקונין\u0004 וכו' כמבואר."],[3,"סטר דרום אימתי וכו':","מתי נתעורר אליה צד דרום, שהוא החסד, למצוא סבה כדי לברך אותה, דהיינו להמשיך לה חסדים, הוא \u0003בימי קציר חטים,\u0004 שפירושו, בעת שמחלק שלל לצבאותיה, דהיינו המלאכים, בסו\"ה ותקם בעוד לילה ותתן טרף לביתה וגו', ולכל קוצרי השדה דהיינו לאותם הנשמות שזוכים לקבל פירותיה של הנוקבא הנקראת שדה. מיד, ויבא אותם אל לאה אמו, שפירושו, שהעלה הריח וההתעוררות שלהם, אל עולם העליון שנתכסה, המכונה לאה כדי שישפיע ברכות לעולם התחתון, שנק' רחל."],[4,"וכד אתברכא וכו':","וכאשר נתברכו הדודאים, דהיינו שנתלבשו בחסדים, מקבלים ונותנים לכל העולמות, שכתוב \u0003הדודאים נתנו ריח\u0004 וגו', כשהם נותנים ריח, דהיינו כשמאירים בחכמה ממטה למעלה המכונה \u0003ריח,\u0004 אותו הריח מקבל צד דרום, דהיינו החסד, לעוררו אל עולם העליון, דהיינו שיאיר ממטה למעלה, מיד, \u0003ועל פתחינו כל מגדים,\u0004 וכל טוב אינו חסר מן העולם."],[5,"עלמא תתאה וכו':","עולם התחתון, אינו מתעורר לעולם העליון, לקבל ממנו מוחין, אלא כשהדודאים נותנים ריח לימין, כיון שנותנים ריח לימין, והימין נתעורר לעולם העליון, מיד, נתעורר עולם התחתון לבקש מה שצריך. מה כתוב, ותאמר רחל אל לאה תני נא לי מדודאי בנך. שפירושו, תני לי ברכות מאותה התעוררות הדודאים שנתעוררו להכלל בצד ימין. דהיינו להתלבש בחסדים שבימין כנ\"ל."],[6,"כדין, עלמא עלאה וכו':","אז עולם העליון, משיב לה בחדוה ושעשועים, ואומרת \u0003המעט קחתך את אישי\u0004 וגו', כמו אמא המשעשעת עצמה עם בתה. ולא בתרעומת. ושואל אם כן, משמע, שבעלה של עולם העליון, בינה, הוא יעקב. כי אמרה על יעקב המעט קחתך את אישי, והלא חכמה הוא בעלה של הבינה. ומשיב, אינו כן, אלא תשוקתו של אבא, שהוא חכמה, תמיד, אינה אלא לבת הזאת, שהיא נוקבא דז\"א, כי בת זאת, אהבתו אליה הוא תמיד, משום, שהוא בת יחידה בין ששה בנים חג\"ת נה\"י, ולכל אלו ששה בנים, חלק להם מנות ותענוגים ומתנות, שיש בהם ב' מיני שפע, המכונים עיקר ותוספות: עיקר, פירושו מוחין דו\"ק, שלא יחסרו מהם, ומכונים \u0003חולקין.\u0004 תוספת, היינו מוחין דג\"ר, שלפעמים חסרים מהם, ומכונה \u0003נבזבזן ומתנן.\u0004 ולה לא חלק ואין לה ירושה כלום. כי הנוקבא אין לה מעצמה כלום, חוץ ממה שנותן לה ז\"א בעלה, שה\"ס חג\"ת נה\"י, ששה בנים הנ\"ל. ועל כל זה הוא מסתכל בה בתשוקה ואהבה יותר מבכולם."],[7,"ברחימו דיליה קרא וכו':","באהבתו קרא אותה בת. לא הספיק לו זה עד שקראה אחות. לא הספיק לו זה וקראה אם, בשם אמו. לא הספיק לו זה, וקרא אותה בשמו, שכתוב בה והחכמה מאין תמצא, חכמה, קרא אותה ודאי. פירוש שהשפיע לה בסוד ד' אותיות הוי\"ה: תחילה מה\"ת שנקראת בת. ואח\"כ מן \u0003ו'\u0004 דהוי\"ה, שנק' אח, והנוקבא נקראת מבחינתו בשם אחות. ואח\"כ מן \u0003ה'\u0004 ראשונה דהוי\"ה שנקראת אמא. ואח\"כ מן \u0003י'\u0004 דהוי\"ה שנקראת חכמה."],[7,"ועל דא עלמא וכו':","ועל כן, אמרה לה עולם העליון, שהוא בינה דהיינו אמא, \u0003המעט קחתך את אישי,\u0004 שהוא חכמה, דהיינו אבא, כי כל אהבתו נמשכה לך, וע\"כ, בשעשוע ואהבה אמרה אמא אל הבת."],[8,"מה אתיבת וכו':","מקשה, אם, המעט קחתך את אישי, לא אמרה בתרעומת, אם כן, מה השיבה רחל, לכן ישכב עמך הלילה, ומשיב בכל מקום שנאמר \u0003לכן,\u0004 הוא שבועה. פירוש, \u0003לכן\u0004 שאמרה, אינו תשובה על המעט קחתך את אישי, אלא שפירושו, לשון שבועה והחלט, כי אמרה לה, אם תתן לי הדודאים, יהיה מחויב בהחלט לשכב עמך הלילה. כמו שיתבאר לפנינו."],[8,"ישכב, מהו ישכב וכו':","שואל, מהו פירושו של המלה \u0003ישכב.\u0004 ומשיב, אלא שכיבה, בכל מקום שהוא, פירושו, תקון הנוקבא אצל הזכר, שיכניס בה הציור של כל האותיות, וזה הוא \u0003ישכב: י\"ש, כ\"ב. י\"ש\u0004 זהו עולם העליון, שהיא בינה שחזרה להיות חכמה. \u0003כ\"ב\u0004 ה\"ס התורה, דהיינו ז\"א, נקודה נסתרת, שמתעוררים אצלה כ\"ב אותיות, דהיינו נקודה דחירק, שעליה יוצא קו האמצעי, המוציא ג' קוין בבינה, שמשום זה מקבל גם הוא ג' קוין, שה\"ס כ\"ב אותיות, (כנ\"ל ב\"א דף מ\"ו ד\"ה כד סליק ע\"ש) וזה הוא \u0003יש-כב, י\"ש,\u0004 הוא עולם הבא, שכתוב להנחיל אוהבי יש. \u0003כ\"ב,\u0004 הוא נקודה העליונה, נקודה דחירק, המביאה כל כ\"ב האותיות, שהוא סוד כל התורה, שהם כל הכלים דז\"א, הנקרא תורה."],[9,"ודא הוא ישכב וכו':","וזהו שכתוב ישכב, סתם, ישכב עמך יעקב לא כתוב, אלא, \u0003ישכב עמך,\u0004 סתם. שיורה, על אותו הנסתר, דהיינו אבא עלאה, הראוי להתחבר \u0003עמך.\u0004 פירוש כי יעקב אינו הדכר של הבינה, אלא הוא עולה למ\"ן לבינה וחכמה עלאה הנקרא אבא, שהוא הדכר של הבינה, הוא מזדווג עמה. ולאה רומזת כאן, אל הבינה עלאה עצמה, כנ\"ל."],[10,"ויבא יעקב מן השדה בערב:","ויבא יעקב, זהו תפארת הקדוש, שהוא ז\"א, שבא משדה ההוא שתופש כל הברכות, שכתוב בו, \u0003אשר ברכו ה'.\u0004 דהיינו הנוקבא דז\"א. \u0003בערב\u0004 למה כתוב בערב, ומשיב, אלא בערב, כמ\"ש ויצא יצחק לשוח בשדה לפנות ערב. דהיינו, בעת שהנוקבא מקבלת מהארת שמאל בלי ימין, שאז ה\"ס חכמה בלי חסדים, שגורם בה חשך. ונקראת ערב, שהוא הזמן שיצחק אביו נתעורר לשדה הזה ואוחז אותו. כי יצחק אינו מתעורר לשדה הזה, כיון שהוא שייך ליעקב, שה\"ס ז\"א. אלא אחר שנסתלק יעקב משם \u0003בערב,\u0004 מחמת שפנה היום, שה\"ס חסדים כנ\"ל ונעשה חשך. הניח אז את שדה הזה ליצחק אביו, שה\"ס קו השמאל, ויעקב עולה באותו הזמן, למעלה, לבינה, בסוד מ\"ן."],[11,"מה כתיב ותצא לאה לקראתו:","דהיינו אמא עלאה, בינה, יצאה אל בן היחיד, ז\"א. \u0003ותאמר אלי תבוא,\u0004 תחת כנפי, לברך אותך ולהרוותך בתפנוקים ומעדנים עליונים, עתה הוא עת רצון ועונג לתת לך תענוג רוח העליון שה\"ס חסדים מאוירא דכיא, בשביל שדה ההוא שהוא הנוקבא, מטרם שנשרף בתוקף הדין של יצחק, שהוא קו השמאל, שמאיר אז בלי חסדים מימין, והוא אז בבחינת אש שורף."],[12,"כיון דנקטא וכו':","כיון שקבלה את יעקב תחת כנפיה, דהיינו שעלה אליה למ\"ן, אז \u0003וישכב עמה בלילה הוא,\u0004 ואינו כתוב, ההוא, אלא \u0003הוא,\u0004 שיורה על נסתר, דהיינו \u0003הוא,\u0004 הסתום מכל, \u0003הוא,\u0004 שכל הברכות וכל הקדושות יוצאות ממנו. דהיינו אבא עלאה. וישכב יעקב לא כתוב, אלא \u0003הוא,\u0004 שיורה על מי שראוי להתחבר עמה, דהיינו אבא עלאה, שהוא המשפיע לבינה."],[13,"ועד דלא זמין וכו':","ומטרם שנזדמן תחת כנפיה של הבינה, אותו שמקבל אלו הקדושות והברכות שהוא יעקב, דהיינו מטרם שעלה יעקב למ\"ן תחת כנפי אמא, לקבל קדושות וברכות בשביל רחל. לא נתמלא עולם העליון שהיא בינה בברכות וקדושות מן נקודה הנסתרת. כלומר שלא היה נעשה התחדשות הזווג דחכמה ובינה על המסך דנקודה דחירק, כי נקודה זו עלה עם יעקב. (כנ\"ל דף פ\"ג ד\"ה וזה) ע\"ש."],[13,"ועל דא דודאים וכו':","וע\"כ דודאים מעוררים הכל, כי בסבתם עלה יעקב לבינה למ\"ן כדי להלבישם בחסדים, ואח\"כ השפיע אותם אל רחל. והכל הוא כעין סוד העליון, כלומר שכל הכתובים שבכאן מדברים בסוד העליון כמבואר. \u0003ראובן,\u0004 מהו ראובן, כלומר, ששואל, מי נתן השם הזה ואמר עליו, ראו-בן, ומשיב, הקב\"ה שם שמות בארץ. כלומר הקב\"ה קראו ראובן, (כנ\"ל באות קפ\"ו) וע\"ש בסולם. שכתוב, לכו חזו מפעלות ה' אשר שם שמות בארץ."],[13,"","ושיעור הכתובים לפי המתבאר כאן בס\"ת, הוא, \u0003וילך ראובן\u0004 שה\"ס החסד, \u0003וימצא דודאים בשדה,\u0004 היינו שהלביש הדודאים שה\"ס נהורא דלא נהיר עם אור החסד, ואז האירו. וזה נחשב לו שמצא אותם, כלומר שגילה הארתם. \u0003ויבא אותם אל לאה אמו,\u0004 שהעלה הארתם לבינה המכונה לאה. אשר שם הם מתכסים, ומקום גילוים הוא רק ברחל, דהיינו בסוד הנוקבא שמחזה ולמטה דז\"א, ולפיכך \u0003ותאמר רחל אל לאה תני נא לי מדודאי בנך.\u0004 כי מקום הארתם אינם אלא בי. \u0003ותאמר לה המעט קחתך את אישי,\u0004 שאמרה, בדרך שעשועים, המעט לך שכל אהבת אישי שהוא חכמה, אינו אלא אליך, ובנה אותך בחו\"ב תו\"מ שה\"ס: בת, אחות, אמא וחכמה. \u0003ואז ותאמר רחל לכן ישכב עמך הלילה,\u0004 לכן, פירושו החלט, שהבטיחה, שבהחלט יעלה יעקב למ\"ן אליה, אם תתן לה הדודאים, כי יהיה מוכרח להמשיך חסדים ולהלביש את הדודאים בשביל רחל. דהיינו תחת \u0003דודאי בנך,\u0004 כדי להשלימם לי. ואחר שרחל קבלה הדודאים מלאה, שהם חכמה בלי חסדים, שאז מסתלקים האורות ונעשה חשך כנ\"ל. שנאמר, \u0003ויבא יעקב מן השדה,\u0004 שה\"ס הנוקבא רחל שבעת הדינים נקראת שדה, \u0003בערב,\u0004 שאז נעשה בה חשך מחמת הדודאים שקבלה. וע\"כ \u0003ותצא לאה לקראתו ותאמר אלי תבוא,\u0004 דהיינו שיבא אליה ויעלה לה מ\"ן מסוד הנקודה דחירק, כדי להכריע ולהלביש הדודאים בחסדים. \u0003כי שכור שכרתיך בדודאי בנך.\u0004 כלומר שאמרה לו, מחמת שנתתי הדודאים לרחל ונעשה בה חשך ע\"כ מוכרח אתה לעלות אצלי למ\"ן להמשיך לה חסדים, כדי שלא תשרף בדינים דשמאל. וזה נבחן כמו ששכרה אותו. \u0003וישכב עמה בלילה, הוא.\u0004 היינו שנזדווגה עם אבא עלאה שנקרא \u0003הוא.\u0004 שממנו נמשכות לה כל הקדושות והברכות, ונתנה אותו ליעקב. ויעקב השפיע אותם לרחל. גם תמצא כאן, מה שמובא בזהר בכמה מקומות, אשר הארת השמאל שהיא חכמה בלי חסדים מקבלת הנוקבא מן בינה עצמה בשוה עם ז\"א, וע\"כ היא אז במדרגה אחת עם ז\"א וקומתם שוה. אלא הארת הימין, דהיינו החסדים המלבישים החכמה היא מוכרחת לקבל מז\"א בעלה (ב\"א דף ק\"ז ד\"ה כגוונא) וגם כאן, קבלה רחל הדודאים מבינה עצמה דהיינו מלאה שהיא בינה, אלא הארת החסדים קבלה מיעקב, אחר שעלה למ\"ן לבינה וגרם זווג לחו\"ב, בסו\"ה וישכב עמה בלילה הוא, כנ\"ל. (ע\"כ סתרי תורה)."],[14,"ותצא לאה לקראתו ותאמר אלי תבוא וגו':","ומתמה, מלה זו, אלי תבוא, הוא חוצפה. ומשיב אינו כן, אלא להיפך, מכאן למדנו הענוה של לאה, שלא אמרה כלום בפני אחותה, והקדימה אל הדרך, ואמרה לו בלחש והודיעה לו. כי ברשות רחל היא, שכתוב, כי שכור שכרתיך מרחל, היינו, שקבלתי רשות, וכדי שלא ירע הדבר בעיני רחל, אמרה לו בחוץ ולא בבית."],[15,"ולא עוד וכו':","ולא עוד, אלא שפתח אהלה של לאה היה בחוץ, והכניסה את יעקב בפתח שמבחוץ, מטרם שנכנס באהל רחל. מהו הטעם, הוא כדי שלא תאמר הדבר בפני רחל ולא תעיז לפני אחותה. ולא עוד אלא אמרה לאה, אם יכנס יעקב באהלה של רחל, אין זה צדק להוציאו משם, לפיכך הקדימה אותו בחוץ."],[16,"וכל האי למה וכו':","שואל וכל זה למה. ומשיב, אלא לאה רוח הקודש נצנצה בה, וידעה שכל אלו שבטים העליונים, שכולם קדושים, יצאו ממנה, ודחקה את השעה מרוב אהבה אל הקב\"ה. ומשום זה שזכתה לרוח הקודש ידעה לקרות להם שמות בסוד החכמה."],[17,"רבי חייא ור' יוסי וכו':","ר\"ח ור\"י היו הולכים בדרך. א\"ר יוסי לר' חייא, בכל פעם שאנו הולכים בדרך ועוסקים בתורה, הקב\"ה מקרה לנו נסים, ועתה דרך זו ארוכה לפנינו, נעסוק בתורה והקב\"ה יתחבר עמנו."],[18,"פתח ר' חייא וכו':","פתח ר\"ח ואמר. בראשון בארבעה עשר יום לחדש בערב תאכלו מצות וכתוב שבעת ימים תאכלו מצות לחם עני. לחם עני בלי \u0003ו'\u0004 כתוב. בדבר זה נתעוררו החברים. (לעיל ב\"א דף רצ\"ח אות שע\"ח) אבל בוא וראה, כשהיו ישראל במצרים היו ברשות אחר, וכשרצה הקב\"ה לקרבם אליו נתן להם מדרגת לחם עני, ושואל, \u0003לחם עני,\u0004 מי הוא העני, ומשיב, זהו דוד המלך שכתוב בו כי עני ואביון אני."],[18,"","פירוש. דוד המלך ה\"ס הנוקבא בעת שמקבלת הארת השמאל מן בינה שאז היא בקומה שוה עם ז\"א, בסוד רגל רביעי של הכסא שהיא בינה, ואז הנוקבא דבוקה בבינה, ואינה מזדווגת עם ז\"א בעלה, ועל כן היא עניה בלי אור, ונקראת \u0003לחם עני,\u0004 מחמת שהחכמה אינה מאירה בלי חסדים. (כנ\"ל וירא דף ה' ד\"ה ואע\"ג עש\"ה) ואז אומרת הכתוב כי עני ואביון אנכי, ומדרגה זו של הנוקבא היא מדרגה ראשונה שלה (כמ\"ש שם) וז\"ש \u0003כד בעא קב\"ה לקרבא לון לגביה יהב לון אתר דלחם עני,\u0004 כי כשהוציאם ממצרים מרשות הס\"א, ורצה לקרבם אל הקדושה נתן להם מדרגת \u0003לחם עני\u0004 שבנוקבא, כי היא מדרגה הראשונה של הנוקבא כמבואר."],[19,"והאי לחם עני אקרי וכו':","ולחם עני זה, נקרא מצה, בלי \u0003ו',\u0004 שהוא ז\"א. כי נוקבא בלי זכר עניה היא, מטעם שמחוסרת חסדים כנ\"ל בסמוך, ונתקרבו ישראל בתחילה לבחינת מצה, להיותה מדרגה הראשונה, כנ\"ל, ואחר שקירבם יותר, הביאם הקב\"ה במדרגות אחרות, ונתחבר הזכר בנוקבא, דהיינו שנזדווגה עם ז\"א ומקבלת חסדים ממנו (כנ\"ל בדבור הסמוך) ואז, \u0003מצה\u0004 אחר שנתחברה עם הזכר, נקראת \u0003מצוה\u0004 בתוספות \u0003ו',\u0004 כי \u0003ו'\u0004 רומזת על ז\"א, וזהו שכתוב, \u0003כי המצוה\u0004 הזאת. וע\"כ במדרגתה הראשונה נקראת \u0003מצה,\u0004 ואח\"כ במדרגות האחרות נקראת \u0003מצוה.\u0004"],[20,"עד דהוו אזלי וכו':","בעוד שהיו הולכים, שמעו קול אחד, שאמר: גדוד מרצחים אורבים לכם בדרך, נטו למעלה, לא תרדו בטירה הבלתי מקורה שלמטה. \u0003טופסרא,\u0004 פירושו, לפי הענין, גדוד. \u0003דקטנון,\u0004 פירושו של מרצחים, מלשון קטנטון, (במדרש תהלים נ\"ח:) לקטנטון שהיה רודף אחר חבירו. \u0003עקימן,\u0004 פירושו מארבים. \u0003קוסטרא,\u0004 פירושו טירה. כי, בחצריהם ובטירותם, תרגומו כפרניהון וקסטרוותהון. (בראשית כ\"ה ט\"ז) \u0003קטרא,\u0004 פירושו בית בלי גג, כמ\"ש (מדות ב') אין קטורות אלא שאינן מקורות."],[20,"אמר ר' יוסי וכו':","אר\"י, משמע מזה, שהקב\"ה רוצה לשמור את דרכנו. עלו למעלה ובאו בהר אחד, בין סלעים חזקים. אמרו, לפי שהקב\"ה רוצה בדרך הזה, נראה דבר מה, או שיקרה לנו נס."],[21,"אזלי יתבי וכו':","הלכו, וישבו אצל בקעות הסלע. עלה אליהם אדם אחד מתוך הבקעות שבסלע, תמהו, אמר ר' יוסי, מי אתה. אמר האיש, מאנשי ארקא אני. הוא ארץ אחת מז' ארצות, (שנתבאר לעיל בהקדמת ספר הזהר דף קנ\"א ד\"ה פירוש ע\"ש בכל ההמשך ו בבראשית ב' דף כ' ד\"ה תהו, ע\"ש) אמר לו, ויש שם בני אדם אמר לו כן. והם זורעים וקוצרים, ומהם, בצורה אחרת משונה ממני, דהיינו שיש להם ב' ראשים (כנ\"ל בהקדמת ספר הזהר דף קנ\"ב אות קנ\"ד, וכמו שנתבאר ענינם בהסולם שם) ועליתי אליכם לדעת מכם, מה שמה של הארץ אשר אתם בה."],[22,"א\"ל ארץ וכו':","אמר לו שהיא נקראת ארץ. משום, שכאן שורה ארץ החיים. שכתוב ארץ ממנה יצא לחם, מארץ הזו שלנו, יוצא לחם אבל בשאר ארצות אין יוצא לחם, ואם יוצא, אינו משבעת המינים. בינתיים חזר למקומו. תמהו. אמרו, ודאי, שהקב\"ה, רוצה לעורר אותנו בדבר זה."],[23,"א\"ר חייא וכו':","אר\"ח, ודאי על מקרא הזה שהזכרת, אני זוכר, שלמדתי מזקני, דבר עליון אחד בחג הפסח. אשר נתן הקב\"ה לישראל לחם זה, שה\"ס מוחין, מארץ החיים, דהיינו מהנוקבא, הנקראת מצה, ואח\"כ היה לחם זה לחם מן השמים דהיינו מז\"א הנקרא שמים. וכבר בארו הדבר."]],[[0,"","וַיֵּלֶךָ רְאוּבֵן בִּימֵי קְצִיר חִטִּים וַיִּמְצָא דוּדָאִים בַּשָּׂדֶה וְגוֹ'. שָׁנִינוּ, כּוֹס שֶׁל בְּרָכָה אֵין מִתְבָּרֶכֶת אֶלָּא בְּצַד יָמִין, וּמִשּׁוּם כָּךְ, בְּעוֹד שֶׁמִּתְעוֹרֵר הַיָּמִין לְכוֹס שֶׁל בְּרָכָה, הַשְּׂמֹאל לֹא תְסַיַּע לְשָׁם, שֶׁהֲרֵי הַיָּמִין מוֹצֵא עִלָּה בַּכּוֹס הַהִיא לְעוֹרֵר כְּלַפֵּי הָעוֹלָם הָעֶלְיוֹן."],[1,"","וְהַסֵּתֶר הַזֶּה, וַיֵּלֶךְ רְאוּבֵן, זֶה צַד הַדָּרוֹם, מִשּׁוּם כָּךְ דִּגְלוֹ בַּדָּרוֹם, שֶׁהוּא רֹאשׁ לִשְׁנֵים עָשָׂר הַתְּחוּמִים, וּתְשׁוּקָתוֹ שֶׁל צַד הַדָּרוֹם לִמְצֹא עִלָּה וְתִקְרֹבֶת לַגְּבִירָה לְבָרֵךְ אוֹתָהּ."],[2,"","מַה כָּתוּב? וַיִּמְצָא דוּדָאִים בַּשָּׂדֶה. הָלַךְ לְחַפֵּשׂ בְּכָל אוֹתָם הַגְּנָזִים שֶׁלָּהּ, וּמָצָא בַּשָּׂדֶה הַזּוֹ אוֹתָם הַדּוּדָאִים, וַעֲלֵיהֶם נֶאֱמַר הַדּוּדָאִים נָתְנוּ רֵיחַ, וְאוֹתָם שְׁנֵי כְרוּבִים שֶׁהֵם הַתִּקּוּנִים שֶׁלָּהּ, לְהָעִיר הִתְעוֹרְרוּת לְמַעְלָה, שֶׁהֲרֵי בְּכָל אוֹתָם הַתִּקּוּנִים שֶׁל הַשָּׂדֶה הַזּוֹ אֵין תִּקּוּן שֶׁיְּעוֹרֵר כְּלַפֵּי מַעְלָה, רַק הַכְּרוּבִים."],[3,"","מָתַי צַד הַדָּרוֹם מִתְעוֹרֵר אֵלֶיהָ לִמְצֹא עִלָּה לְבָרֵךְ אוֹתָהּ? בִּימֵי קְצִיר חִטִּים, בִּזְמַן שֶׁמְּחַלֶּקֶת חֵלֶק שָׁלָל לְאוּכְלוּסֶיהָ, וְכָל קוֹצְרֵי הַשָּׂדֶה. מִיָּד - וַיָּבֵא אֹתָם אֶל לֵאָה אִמּוֹ. מַעֲלֶה רֵיחַ וְהִתְעוֹרְרוּתָם לָעוֹלָם הָעֶלְיוֹן, הָעוֹלָם הַנִּכְסֶה, מִשּׁוּם שֶׁמֵּעִיר (שיעורר) בְּרָכוֹת לָעוֹלָם הַתַּחְתּוֹן."],[4,"","וְכַאֲשֶׁר מִתְבָּרֶכֶת, אוֹתָם הַדּוּדָאִים לוֹקְחִים וְנוֹתְנִים לְכָל הָעוֹלָמוֹת, שֶׁכָּתוּב הַדּוּדָאִים נָתְנוּ רֵיחַ וְעַל פְּתָחֵינוּ כָּל מְגָדִים. כַּאֲשֶׁר הֵם נָתְנוּ רֵיחַ, אוֹתוֹ הָרֵיחַ לוֹקֵחַ אוֹתוֹ צַד הַדָּרוֹם לְהִתְעוֹרֵר לָעוֹלָם הָעֶלְיוֹן. מִיָּד - עַל פְּתָחֵינוּ כָּל מְגָדִים, וְכָל טוּב לֹא חָסֵר (הכל) מֵהָעוֹלָם."],[5,"","הָעוֹלָם הַתַּחְתּוֹן לֹא מִתְעוֹרֵר לָעוֹלָם הָעֶלְיוֹן, אֶלָּא כְּשֶׁאוֹתָם דּוּדָאִים נוֹתְנִים רֵיחַ לַיָּמִין. כֵּיוָן שֶׁהֵם נוֹתְנִים רֵיחַ לַיָּמִין, וְהַיָּמִין מִתְעוֹרֵר לָעוֹלָם הָעֶלְיוֹן, מִיָּד הָעוֹלָם הַתַּחְתּוֹן מִתְעוֹרֵר לִשְׁאֹל מַה שֶּׁצָּרִיךְ. מַה כָּתוּב? וַתֹּאמֶר רָחֵל אֶל לֵאָה תְּנִי נָא לִי מִדּוּדָאֵי בְּנֵךְ. תֵּן לִי בְּרָכוֹת מֵאוֹתָהּ הַהִתְעוֹרְרוּת שֶׁל אוֹתָם דּוּדָאִים שֶׁמִּתְעוֹרֵר לְצַד הַיָּמִין."],[6,"","אָז הָעוֹלָם הָעֶלְיוֹן בְּשִׂמְחָה, בְּשַׁעֲשׁוּעַ, מֵשִׁיב אֵלֶיהָ, וְאוֹמֶרֶת הַמְעַט קַחְתֵּךְ אֶת אִישִׁי, כְּאֵם אֶל בִּתָּהּ. וְאִם כָּךְ, בַּעְלָהּ שֶׁל הָעוֹלָם הָעֶלְיוֹן הוּא יַעֲקֹב? לֹא כָּךְ, אֶלָּא תְּשׁוּקַת הָאָב תָּמִיד אֵינָהּ אֶלָּא כְּלַפֵּי הַבַּת הַזּוֹ, (שהיא) שֶׁהַבַּת הַזּוֹ אַהֲבָתוֹ אֵלֶיהָ תָּמִיד, מִשּׁוּם שֶׁהִיא בַּת יְחִידָה בֵּין שִׁשָּׁה בָנִים, וּלְכָל אוֹתָם שֵׁשֶׁת הַבָּנִים חִלֵּק לָהֶם חֲלָקִים וְאוֹצָרוֹת וּמַתָּנוֹת, וְלָהּ לֹא חִלֵּק, וְאֵין לָהּ יְרֻשָּׁה כְּלוּם, וְעַל כָּל זֶה הוּא מַשְׁגִּיחַ בָּהּ בִּתְשׁוּקָה וְאַהֲבָה יוֹתֵר מִן הַכֹּל."],[7,"","בָּאַהֲבָה שֶׁלּוֹ הוּא קוֹרֵא לָהּ בַּת. לֹא הִסְפִּיק לוֹ זֶה, וְקָרָא לָהּ אָחוֹת. לֹא הִסְפִּיק לוֹ זֶה, קָרָא לָהּ אֵם בְּשֵׁם אִמּוֹ. לֹא הִסְפִּיק לוֹ זֶה, קָרָא לָהּ בִּשְׁמוֹ, שֶׁכָּתוּב וְהַחָכְמָה מֵאַיִן תִּמָּצֵא, חָכְמָה וַדַּאי. וְעַל כֵּן הָעוֹלָם הָעֶלְיוֹן אוֹמֶרֶת לָהּ, הַמְעַט קַחְתֵּךְ אֶת אִישִׁי, שֶׁכָּל אַהֲבָתוֹ נִמְשְׁכָה לָךְ אֵלַיִךְ וְעַל זֶה, בְּשַׁעֲשׁוּעַ וְאַהֲבָה הָאֵם אֶל הַבַּת."],[8,"","מַה הִיא מְשִׁיבָה? לָכֵן יִשְׁכַּב עִמָּךְ הַלַּיְלָה. בְּכָל מָקוֹם לָכֵן הִיא שְׁבוּעָה. יִשְׁכַּב, מַה זֶּה יִשְׁכַּב? אֶלָּא שְׁכִיבָה בְּכָל מָקוֹם הִיא תִקּוּן הַנְּקֵבָה לַזָּכָר לְהַכְנִיס בָּהּ צִיּוּר שֶׁל כָּל הָאוֹתִיּוֹת. וְזֶהוּ יִשְׁכַּב, י\"ש כ\"ב. י\"ש זֶהוּ הָעוֹלָם הָעֶלְיוֹן, (כ\"ב סוד) הַסּוֹד שֶׁל הַתּוֹרָה, נְקֻדָּה טְמִירָה שֶׁמִּתְעוֹרְרִים אֵלֶיהָ כ\"ב אוֹתִיּוֹת. וְזֶהוּ יִשְׁכַּ\"ב. י\"ש - הָעוֹלָם הַבָּא, שֶׁכָּתוּב (משלי א) לְהַנְחִיל אוֹהֲבַי יֵשׁ. כ\"ב - נְקֻדָּה עֶלְיוֹנָה שֶׁמַּכְנִיסָה כָּל כ\"ב הָאוֹתִיּוֹת, הַסּוֹד שֶׁל כָּל הַתּוֹרָה."],[9,"","וְזֶהוּ יִשְׁכַּב. לֹא כָתוּב יִשְׁכַּב עִמָּךְ יַעֲקֹב, אֶלָּא יִשְׁכַּב עִמָּךְ, אוֹתוֹ הַטָּמִיר שֶׁרָאוּי לְהִתְעוֹרֵר אֵלַיִךְ, וְהַכֹּל בַּהִתְעוֹרְרוּת שֶׁל אוֹתָם (שכלם) דּוּדָאִים, וְהַכֹּל כָּתוּב בְּאַהֲבָה."],[10,"","וַיָּבֹא יַעֲקֹב מִן הַשָּׂדֶה בָּעֶרֶב. וַיָּבֹא יַעֲקֹב - זוֹ תִּפְאֶרֶת הַקְּדוֹשָׁה, מֵאוֹתָהּ הַשָּׂדֶה שֶׁלּוֹקַחַת אֶת כָּל הַבְּרָכוֹת, שֶׁכָּתוּב בּוֹ אֲשֶׁר בֵּרֲכוֹ ה'. בָּעֶרֶב, לָמָּה בָּעֶרֶב? אֶלָּא בָּעֶרֶב שֶׁכָּתוּב (בראשית כד) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה לִפְנוֹת עָרֶב. בִּזְמַן שֶׁהִתְעוֹרֵר יִצְחָק אָבִיו לַשָּׂדֶה הַזּוֹ וְלָקַח אוֹתוֹ, שֶׁהֲרֵי יִצְחָק לֹא מִתְעוֹרֵר לַשָּׂדֶה הַזּוֹ. כֵּיוָן שֶׁהִסְתַּלֵּק יַעֲקֹב מִשָּׁם בָּעֶרֶב, הִשְׁאִיר אֶת הַשָּׂדֶה הַזּוֹ לְיִצְחָק אָבִיו, וְהוּא עָלָה בְּאוֹתוֹ הַזְּמַן לְמַעְלָה."],[11,"","מַה כָּתוּב? וַתֵּצֵא לֵאָה לִקְרָאתוֹ. הָאֵם הָעֶלְיוֹנָה, לַבֵּן הַיָּחִיד. וַתֹּאמֶר אֵלַי תָּבוֹא, תַּחַת כְּנָפַי, לְבָרֵךְ אוֹתְךְ וּלְהַרְווֹת אוֹתְךְ בְּתַפְנוּקִים וְעִדּוּנִים עֶלְיוֹנִים. הִנֵּה עֵת רָצוֹן וְעֹנֶג לָתֵת לְךְ נַחַת רוּחַ עֶלְיוֹנָה לְאוֹתָהּ הַשָּׂדֶה טֶרֶם שֶׁיִּשָּׂרֵף בַּחֹזֶק שֶׁל יִצְחָק."],[12,"","כֵּיוָן שֶׁלָּקְחָה אֶת יַעֲקֹב תַּחַת כְּנָפֶיהָ, אָז וַיִּשְׁכַּב עִמָּהּ בַּלַּיְלָה הוּא. הוּא - שֶׁנִּסְתָּר מִן הַכֹּל. הוּא - שֶׁכָּל הַבְּרָכוֹת וְכָל הַקְּדֻשּׁוֹת יוֹצְאוֹת מִשָּׁם. לֹא כָתוּב יַעֲקֹב, אֶלָּא הוּא, מִי שֶׁרָאוּי לְהִתְעוֹרֵר אֵלֶיהָ."],[13,"","וְטֶרֶם מְזֻמָּן אֵלֶיהָ תַּחַת כְּנָפֶיהָ, מִי שֶׁלּוֹקֵחַ אוֹתָם הַקְּדוֹשִׁים (הקדשות) וְהַבְּרָכוֹת, לֹא מִתְמַלֵּא מֵהַנְּקֻדָּה הַטְּמִירָה, הָעוֹלָם הָעֶלְיוֹן הַהוּא. וְעַל כֵּן הַדּוּדָאִים מְעוֹרְרִים הַכֹּל, וְהַכֹּל כְּמוֹ שֶׁסּוֹד עֶלְיוֹן. רְאוּבֵן, מַה זֶּה רְאוּבֵן? הַקָּדוֹשׁ בָּרוּךְ הוּא שָׂם שֵׁמוֹת בָּאָרֶץ, שֶׁכָּתוּב (תהלים מו) לְכוּ חֲזוּ מִפְעֲלוֹת ה' אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ."],[14,"","וַתֵּצֵא לֵאָה לִקְרָאתוֹ וַתֹּאמֶר אֵלַי תָּבוֹא וְגוֹ'. הַדָּבָר הַזֶּה הוּא חֻצְפָּה? אֵינוֹ כָּךְ, אֶלָּא מִכָּאן לָמַדְנוּ עַנְוְתָנוּתָהּ שֶׁל לֵאָה, שֶׁלֹּא אָמְרָה דָּבָר לִפְנֵי אֲחוֹתָהּ, וְהִיא הִקְדִּימָה לַדֶּרֶךְ וְאָמְרָה לוֹ בַּחֲשַׁאי וְהוֹדִיעָה לוֹ, שֶׁהֲרֵי זֶה הָיָה בִּרְשׁוּת רָחֵל, שֶׁכָּתוּב כִּי שָׂכֹר שְׂכַרְתִּיךְ. מֵרָחֵל נָטְלָה רְשׁוּת. וּכְדֵי שֶׁלֹּא יֵרַע בְּעֵינֵי רָחֵל, אָמְרָה לוֹ בַּחוּץ, וְלֹא בַּבַּיִת."],[15,"","וְלֹא עוֹד, אֶלָּא בַּפֶּתַח שֶׁל מִשְׁכַּן לֵאָה (לחוץ) יָצְאָה הַחוּצָה, וְהִכְנִיסָה אֶת יַעֲקֹב בַּפֶּתַח שֶׁבַּחוּץ טֶרֶם שֶׁיִּכָּנֵס לְמִשְׁכַּן רָחֵל. מָה הַטַּעַם? כְּדֵי שֶׁלֹּא תֹאמַר דָּבָר לִפְנֵי רָחֵל, וְלֹא תִתְחַצֵּף לִפְנֵי אֲחוֹתָהּ. וְלֹא עוֹד, אֶלָּא אָמְרָה לֵאָה, אִם יִכָּנֵס יַעֲקֹב לְמִשְׁכַּן רָחֵל, אֵינוֹ דִין לְהוֹצִיאוֹ מִשָּׁם, מִשּׁוּם כָּךְ הִקְדִּימָה לוֹ בַּחוּץ."],[16,"","וְכָל זֶה לָמָּה? אֶלָּא שֶׁרוּחַ הַקֹּדֶשׁ הִתְעוֹרְרָה בְּלֵאָה, וְיָדְעָה שֶׁכָּל הַשְּׁבָטִים הָעֶלְיוֹנִים הַלָּלוּ, כֻּלָּם קְדוֹשִׁים, יֵצְאוּ מִמֶּנָּה, וְדָחֲקָה הַשָּׁעָה בַּחֲבִיבוּת לַקָּדוֹשׁ-בָּרוּךְ- הוּא, וּמִשּׁוּם כָּךְ קָרְאָה לָהֶם שֵׁמוֹת בְּסוֹד הַחָכְמָה."],[17,"","רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי לְרַבִּי חִיָּיא, בְּכָל פַּעַם (שאנו) הוֹלְכִים בַּדֶּרֶךְ וְעוֹסְקִים בַּתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַרְחִישׁ לָנוּ נִסִּים, וְכָעֵת הַדֶּרֶךְ הַזּוֹ אֲרֻכָּה לָנוּ, נִתְעַסֵּק בַּתּוֹרָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְחַבֵּר עִמָּנוּ."],[18,"","פָּתַח רַבִּי חִיָּיא וְאָמַר, (שמות יב) בָּרִאשּן בְּאַרְבָּעָה עָשָׂר יוֹם לַחֹדֶשׁ בָּעֶרֶב תֹּאכְלוּ מַצּת, וְכָתוּב (דברים טז) שִׁבְעַת יָמִים תֹּאכַל עָלָיו מַצּוֹת לֶחֶם עֹנִי. לֶחֶם עָנִי כָּתוּב. בַּדָּבָר הַזֶּה הִתְעוֹרְרוּ בוֹ הַחֲבֵרִים. אֲבָל בּא רְאֵה, כְּשֶׁהָיוּ יִשְׂרָאֵל בְּמִצְרַיִם, הָיוּ בִּרְשׁוּת אַחֶרֶת. כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְקָרֵב אוֹתָם אֵלָיו, נָתַן לָהֶם מָקוֹם שֶׁל לֶחֶם עֹנִי, לֶחֶם עָנִי. מִי הֶעָנִי? זֶה דָּוִד הַמֶּלֶךְ, שֶׁכָּתוּב בּוֹ (תהלים פז) כִּי עָנִי וְאֶבְיוֹן אָנִי."],[19,"","וְלֶחֶם עֹנִי הַזֶּה נִקְרָא מַצָּה, נְקֵבָה בְּלִי זָכָר הִיא עֹנִי. הִתְקָרְבוּ לַמַּצָּה בַּהַתְחָלָה. כֵּיוָן שֶׁקֵּרְבוּ אוֹתָם יוֹתֵר, הִכְנִיס אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא בִּדְרָגוֹת אֲחֵרוֹת, וְהִתְחַבֵּר זָכָר עִם נְקֵבָה. וְאָז, כְּשֶׁמַּצָּה מִתְחַבֶּרֶת בַּזָּכָר, נִקְרָא מִצְוָה, בְּתוֹסֶפֶת וָא\"ו. זֶהוּ שֶׁכָּתוּב (דברים ל) כִּי הַמִּצְוָה הַ את. מִשּׁוּם כָּךְ מַצָּה בָּרִאשׁוֹנָה, וְאַחַר כָּךְ מִצְוָה."],[20,"","בְּעוֹדָם הוֹלְכִים שָׁמְעוּ קוֹל אֶחָד שֶׁאוֹמֵר: גְּדוּד שֶׁל רוֹצְחִים אוֹרְבִים בַּדֶּרֶךְ, סְטוּ לְמַעְלָה, אַל תֵּרְדוּ לַטִּירָה חַסְרַת הַגַּג שֶׁלְּמַטָּה. אָמַר רַבִּי יוֹסֵי, מִזֶּה נִשְׁמָע שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לִשְׁמֹר אֶת דְּרָכֵינוּ. עָלוּ לְמַעְלָה וְנִכְנְסוּ לְהַר אֶחָד, בֵּין סְלָעִים חֲזָקִים. אָמְרוּ, הוֹאִיל וְהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה בַּדֶּרֶךְ הַזּוֹ, נִרְאֶה דָבָר, אוֹ יִתְרַחֵשׁ לָנוּ נֵס."],[21,"","הָלְכוּ, יָשְׁבוּ עַל בְּקִיעֵי הַסֶּלַע. עָלָה לָהֶם אִישׁ אֶחָד. תָּמְהוּ. אָמַר רַבִּי יוֹסֵי, מִי אַתָּה? אָמַר, אֲנִי מֵאַנְשֵׁי אַרְקָא. אָמַר לוֹ, וְשָׁם יֵשׁ בְּנֵי אָדָם? אָמַר, כֵּן, וְזוֹרְעִים וְקוֹצְרִים, מֵהֶם בְּמַרְאֶה אַחֵר מְשֻׁנִּים מִמֶּנִּי, וְעָלִיתִי אֲלֵיכֶם לְהַכִּיר מִכֶּם, מַה שְּׁמָהּ שֶׁל הָאָרֶץ שֶׁאַתֶּם בָּהּ?"],[22,"","אָמַר לוֹ, אֶרֶץ, מִשּׁוּם שֶׁכָּאן שׁוֹרָה אֶרֶץ הַחַיִּים, שֶׁכָּתוּב (איוב כח) אֶרֶץ מִמֶּנָּה יֵצֵא לָחֶם. מִזּוֹ יֵצֵא לָחֶם? בִּשְׁאָר הָאָרֶץ לֹא יֵצֵא לֶחֶם, וְאִם יוֹצֵא, לֹא מִשִּׁבְעַת הַמִּינִים. בֵּינְתַיִם נִכְנַס לִמְקוֹמוֹ. תָּמְהוּ. אָמְרוּ, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְעוֹרֵר אוֹתָנוּ בְּאֵיזֶה דָבָר."],[23,"","אָמַר רַבִּי חִיָּיא, וַדַּאי עַל הַפָּסוּק הַזֶּה שֶׁאָמַרְתָּ, זָכַרְתִּי שֶׁלָּמַדְתִּי מִסָּבִי דָּבָר אֶחָד עֶלְיוֹן בְּפֶסַח, שֶׁנָּתַן לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל הַלֶּחֶם הַזֶּה מֵאֶרֶץ הַחַיִּים, וְאַחַר כָּךְ לֶחֶם מִן הַשָּׁמַיִם, הַלֶּחֶם הַזֶּה, וְהִנֵּה בֵּאַרְנוּ אֶת הַדָּבָר."]]],[["תוּ הֲוָה אָמַר, דְּבַר נָשׁ, כַּד נָפִיק לְהַאי עַלְמָא, לָא יָדַע מִידִּי, עַד דְּאַטְעִים נַהֲמָא. כֵּיוָן דְאָכִיל נַהֲמָא, אִתְעַר לְמִנְדַע וּלְאִשְׁתְּמוֹדְעָא. כָּךְ כַּד נָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, לָא הֲווּ יָדְעֵי מִדֵּי, עַד דְּאַטְעִים לוֹן קוּדְשָׁא בְּרִיךְ הוּא לֶחֶם מֵהַאי אֶרֶץ, דִּכְתִיב אֶרֶץ מִמֶּנָּה יֵצֵא לָחֶם, וּכְדֵין עָאלוּ יִשְׂרָאֵל, לְמִנְדַע וּלְאִשְׁתְּמוֹדְעָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. וִינוּקָא לָא יָדַע, וְלָא אִשְׁתְּמוֹדְעָא, עַד דְּטָעִים נַהֲמָא דְּהַאי עַלְמָא.","יִשְׂרָאֵל לָא יָדְעוּ, וְלָא אִשְׁתְּמוֹדְעוּ בְּמִלִּין דִּלְעֵילָא, עַד דְּאָכְלוּ לֶחֶם עִלָּאָה, וּכְדֵין יָדְעוּ וְאִשְׁתְּמוֹדְעוּ בְּהַהוּא אֲתַר וּבָעָא קוּדְשָׁא בְּרִיךְ הוּא דְּיִנְדְּעוּן יִשְׂרָאֵל יַתִּיר, בְּהַהוּא אֲתַר דְּאִתְחֲזֵי לְהַאי אֶרֶץ. וְלָא יָכִילוּ, עַד דְּטָעֲמוּ לֶחֶם, מֵהַהוּא אֲתַר, וּמַאן אִיהוּ, שָׁמַיִם. דִּכְתִיב, (שמות ט״ז:ד׳) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמַיִם, וּכְדֵין יָדְעוּ וְאִסְתַּכָּלוּ בְּהַהוּא אֲתַר, וְעַד דְּאָכְלוּ לֶחֶם מֵהַהוּא אֲתַר, (ס\"א ועד דלא אכלו לחם מאלין אתרי) לָא יָדְעוּ מִידִּי וְלָא אִשְׁתְּמוֹדְעוּ.","אֲתָא רַבִּי יוֹסֵי וּנְשָׁקֵיהּ. אָמַר, וַדַּאי עַל דָּא אִתְעַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא בְּהַאי, וְעַל דָּא שֵׁירוּתָא דְיִשְׂרָאֵל לְמִנְדַע, לֶחֶם הֲוָה. קָמוּ וְאֲזְלוּ, עַד דְּהֲווּ אָזְלוּ, חָמוּ תְּרֵי דַּרְמוּסְקִין, חַד דְּכַר וְחַד נוּקְבָא. אָמַר רִבִּי יוֹסֵי, לֵית לָן מִלָּה בְּעָלְמָא, דְּלָא הֲוֵי דְּכַר וְנוּקְבָא, וְכָל מַה דִּי בְאַרְעָא, הָכִי נָמֵי בְּיַמָּא.","פָּתַח רִבִּי יוֹסֵי וְאָמַר, (בראשית ל׳:ט״ז) וַיָּבֹא יַעֲקֹב מִן הַשָּׂדֶה בָּעֶרֶב וַתֵּצֵא לֵאָה לִקְרָאתוֹ וְגו', וַתֵּצֵא לֵאָה לִקְרָאתוֹ, מְנָא יָדְעַת. הָא אָמְרוּ דְּגָעָא חֲמָרָא, וְלֵאָה יָדְעַת, וְנָפְקַת לֵיהּ, וְגָרִים לֵיהּ דְּנָפַק מִנָּהּ יִשָּׂשכָר. הֲדָא הוּא דִכְתִיב יִשָּׂשכָר חֲמוֹר גָּרְם, אַל תִּקְרֵי גָרְם, אֶלָּא גָּרַם דְּחֲמָרָא גָּרְמָא לֵיהּ. אֲמְרַת לֵאָה, וַדַּאי יָדַעְנָא דְּאִי יֵיעוּל יַעֲקֹב בְּמִשְׁכְּנָא דְרָחֵל, לֵית לִי לְאֲפָקָא לֵיהּ, אֶלָּא אוֹרִיךְ לֵיהּ הָכָא, וְיֵיעוּל בְּמִשְׁכָּנִי.","(בראשית ל׳:ט״ז) כִּי שָׂכֹר שְׂכַרְתִּיךָ בְּדוּדָאֵי בְּנִי, מַאי בְּדוּדָאֵי בְּנִי, בְּגִין דְּנִיחָא לֵיהּ לְיַעֲקֹב עַל דָּא, דְּאִלֵּין מְסַיְיעִין לְאוֹלָדָא. וְיַעֲקֹב הֲוָה יָדַע, דְּמִלָּה לָא קָיְימָא בַּדּוּדָאִים, אֶלָּא לְעֵילָא.","פָּתַח וְאָמַר, (תהילים קי״ג:ט׳) מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת אֵם הַבָּנִים שְׂמֵחָה הַלְּלוּיָה. אָמַר רִבִּי חִיָּיא רוּחָא דְקוּדְשָׁא קָאֲמַר, מוֹשִׁיבִי (קנ\"ד ע\"א) עֲקֶרֶת הַבַּיִת, דָּא רָחֵל. אֵם הַבָּנִים שְׂמֵחָה, דָּא לֵאָה. מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת, דָּא עַלְמָא תַּתָּאָה. אֵם הַבָּנִים שְׂמֵחָה (הללויה), דָּא עַלְמָא עִלָּאָה, בְּגִינֵי (קנ\"ד ע\"א) כָּךְ הַלְּלוּיָה.","אָמַר רִבִּי יְהוּדָה, כָּל אִלֵּין שִׁבְטִין, תִּקּוּנִין דִּלְתַתָּא אִינוּן, וְכֻלְּהוּ כְּגַוְונָא דִלְעֵילָא. תָּא חֲזֵי, כִּי שָׂכֹר שְׂכַרְתִּיךָ, לְנַסְבָא מִנֵּיהּ גּוּפָא וּמַאן אִיהוּ תּוֹרָה. שָׂכֹר שְׂכַרְתִּיךָ, לְךָ, לְגוּפָךְ מַמָּשׁ. שָׂכֹר שְׂכַרְתִּיךָ, לְאוֹלָדָא דְּיוּקְנָךְ."],[[0,"תו הוה אמר וכו':","עוד אמר, בן אדם כשיוצא לעולם הזה, אינו יודע מאומה, מטרם שטועם טעם לחם, כיון שאכל לחם מתעורר לדעת ולהשיג. כך כשיצאו ישראל ממצרים, לא היו יודעים מאומה, עד שהטעים להם הקב\"ה לחם מארץ הזו, שהיא הנוקבא הנקראת מצה, שכתוב ארץ ממנה יצא לחם ואז באו ישראל לדעת ולהשיג את הקב\"ה, כהתינוק שאינו יודע ואינו משיג עד שטועם לחם מעולם הזה. כלומר שלחם זה שקבלו ישראל בפסח, מן הנוקבא בלבדה, הנקרא מצה, ה\"ס מדרגה ראשונה בהשגה, כמו התינוק המתחיל לטעום טעם לחם."],[1,"ישראל לא ידעו וכו':","ישראל לא ידעו ולא השיגו בדברים של מעלה, דהיינו במדרגות יותר עליונות, עד שאכלו לחם העליון, דהיינו הנמשך מז\"א הנקרא שמים, ואז מטרם שאכלו לחם העליון, ידעו והשיגו רק במקום ההוא, דהיינו בנוקבא, ולא יותר, ורצה הקב\"ה, שידעו ישראל יותר במקום ההוא, הראוי לארץ הזו, דהיינו מדרגות יותר עליונות, המאירות ממקום ז\"א אל הנוקבא, ולא יכלו עד שטעמו לחם ממקום ההוא העליון, ומי הוא, הוא הנקרא \u0003שמים,\u0004 דהיינו ז\"א, שכתוב, הנני ממטיר לכם לחם מן השמים. ואז ידעו והסתכלו במקום ההוא העליון, ומטרם שאכלו מאותו מקום העליון, לא ידעו מאומה ולא השיגו, באותו מקום העליון שהוא ז\"א."],[2,"אתא ר' יוסי וכו':","בא ר' יוסי ונשקו. אמר ודאי על זה העיר אותנו הקב\"ה בזה, דהיינו לדבר עם האדם מאנשי ארקא, שבסבתו באנו למקרא הזה כנ\"ל, ועל כן, ההתחלה שהתחילו ישראל לדעת היה לחם, דהיינו לחם עני כנ\"ל. קמו והלכו. בעוד שהיו הולכים, ראו שני דרמוסקין (שהם פירות ויש אומרים שהם ירקות) אחד זכר ואחד נקבה. אמר ר' יוסי, אין לנו דבר בעולם שלא יהיה בו זכר ונקבה. וכל מה שיש בארץ, יש גם כן בים."],[3,"פתח ר' יוסי וכו':","פתח ר\"י ואמר, ויבא יעקב וגו' ותצא לאה לקראתו, שואל מאין ידעה שהוא בא. ומשיב, הנה אמרו שחמורו געה, וידעה לאה ויצאה לקראתו. וגרם החמור שיצא יששכר מלאה, וז\"ש יששכר חמור גרם, אל תקרא גרם עם ר' סגולה, אלא גרם עם ר' פתוחה, שפירושו שהחמור גרם ביאתו לעולם."],[3,"אמרת לאה וכו':","אמרה לאה, יודע אני ודאי, שאם יבא יעקב באהלה של רחל אין לי להוציאו משם, לכן אחכה לו כאן, ויבא לאהלי."],[4,"כי שכור שכרתיך בדודאי בני:","שואל, למה אמרה בדודאי בני, היה מספיק שתאמר בדודאים. ומשיב, כדי שיהיה ליעקב נחת ממה שהם עוזרים להוליד בנים. אבל יעקב היה יודע שהדבר אינו תלוי בדודאים. אלא למעלה במזלא (כנ\"ל באות ר'). פירוש. כי דורש שדודאי בני פירושו, דודאים המולידים בנים, והזכירה זה ליעקב, כדי שיהיה לו נחת מן הסגולה שניתנה לרחל להוליד בנים."],[5,"פתח ואמר מושיבי עקרת הבית וגו':","א\"ר חייא, רוח הקודש אמר, מושיבי עקרת הבית, זו רחל. אם הבנים שמחה, זו לאה. ומפרש יותר, מושיבי עקרת הבית, זה עולם התחתון שהוא הנוקבא דז\"א המכונה רחל. אם הבנים שמחה, זה עולם העליון, בינה, המכונה לאה. ומשום זה הללויה. שהוא נוטריקון הללו-יה, כי עולם העליון נברא ב \u0003י'\u0004 ועולם התחתון נברא ב \u0003ה'.\u0004 (כמ\"ש בזהר האזינו אות רכ\"ו)"],[6,"א\"ר יהודה וכו':","אר\"י, כל אלו השבטים הם תקונים שלמטה, דהיינו של הנוקבא, וכלם נתקנו כעין שלמעלה, בינה."],[6,"ת\"ח, כי שכור שכרתיך:","היינו לקחת ממנו גוף, ומי הוא, הוא תורה. \u0003שכור שכרתיך,\u0004 היינו לך, לגופך ממש. \u0003שכור שכרתיך,\u0004 היינו להוליד צורתך."],[6,"","פירוש. כי הוקשה לו כפל המלות, שכור שכרתיך. והנה נתבאר לעיל (באות ר\"י) שלאה ה\"ס בינה, והזווג היה עם חכמה שע\"כ נאמר וישכב עמו בלילה \u0003הוא,\u0004 ולא נאמר יעקב, \u0003ואלי תבא,\u0004 הפירוש הוא לעלות למ\"ן. וז\"ש \u0003כי שכור שכרתיך,\u0004 היינו שכיריות הרבה. א) לקחת ממנו מן חכמה גוף, שהוא תורה. דהיינו יששכר שהוא מרכבה לתורה יותר מכל השבטים (כנ\"ל באות קצ\"ו) ונופל השכירות על הזווג עם החכמה בסבתו. ב) \u0003שכור שכרתיך\u0004 לך לגופך ממש. שהשכירות הוא על גופו של יעקב דהיינו שיעלה למ\"ן לזווג חכמה ובינה (כמ\"ש לעיל דף פ\"ט ד\"ה ועד ע\"ש). ג) \u0003שכור שכרתיך,\u0004 להוליד צורתך. שהשכירות הוא על לידת הצורה, דהיינו להוליד בן. וכל אלו ג' שכירות נכללות בכפל המלות שכור שכרתיך."]],[[0,"","עוֹד הָיָה אוֹמֵר, שֶׁאָדָם, כְּשֶׁיּוֹצֵא לָעוֹלָם הַזֶּה, לֹא יוֹדֵעַ דָּבָר עַד שֶׁטּוֹעֵם לֶחֶם. כֵּיוָן שֶׁאוֹכֵל לֶחֶם, מִתְעוֹרֵר לָדַעַת וּלְהַכִּיר. כָּךְ כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, לֹא הָיוּ יוֹדְעִים דָּבָר, עַד שֶׁהִטְעִים לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לֶחֶם מִן הָאָרֶץ הַזּוֹ, שֶׁכָּתוּב אֶרֶץ מִמֶּנָּה יֵצֵא לָחֶם, וְאָז נִכְנְסוּ יִשְׂרָאֵל לָדַעַת וּלְהַכִּיר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. וְתִינוֹק לֹא יוֹדֵעַ וְלֹא מַכִּיר עַד שֶׁטּוֹעֵם לֶחֶם שֶׁל הָעוֹלָם הַזֶּה."],[1,"","יִשְׂרָאֵל לֹא יָדְעוּ וְלֹא הִכִּירוּ בַּדְּבָרִים שֶׁלְּמַעְלָה עַד שֶׁאָכְלוּ לֶחֶם עֶלְיוֹן, וְאָז יָדְעוּ וְהִכִּירוּ אֶת אוֹתוֹ מָקוֹם, וְרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּשְׂרָאֵל יֵדְעוּ יוֹתֵר בְּאוֹתוֹ מָקוֹם שֶׁרָאוּי לָאָרֶץ הַזּוֹ, וְלֹא יָכְלוּ, עַד שֶׁטָּעֲמוּ לֶחֶם מֵאוֹתוֹ הַמָּקוֹם, וּמִי הוּא? שָׁמַיִם, שֶׁכָּתוּב (שמות טז) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם, וְאָז יָדְעוּ וְהִסְתַּכְּלוּ לְאוֹתוֹ מָקוֹם. וְעַד שֶׁאָכְלוּ לֶחֶם מֵאוֹתוֹ מָקוֹם, (ועד שלא אכלו לחם באלו המקומות) לֹא יָדְעוּ דָבָר וְלֹא הִכִּירוּ."],[2,"","בָּא רַבִּי יוֹסֵי וּנְשָׁקוֹ. אָמַר, וַדַּאי עַל זֶה הֵעִיר אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּזֶה, וְעַל כֵּן הָרֵאשִׁית שֶׁל יִשְׂרָאֵל לָדַעַת הָיָה הַלֶּחֶם. קָמוּ וְהָלְכוּ. בְּעוֹדָם הוֹלְכִים רָאוּ שְׁנֵי פֵּרוֹת, אֶחָד זָכָר וְאֶחָד נְקֵבָה. אָמַר רַבִּי יוֹסֵי, אֵין לָנוּ דָּבָר בָּעוֹלָם שֶׁאֵינוֹ זָכָר וּנְקֵבָה, וְכָל מַה שֶּׁבָּאָרֶץ - כָּךְ גַּם בַּיָּם."],[3,"","פָּתַח רַבִּי יוֹסֵי וְאָמַר, וַיָּבֹא יַעֲקֹב מִן הַשָּׂדֶה בָּעֶרֶב וַתֵּצֵא לֵאָה לִקְרָאתוֹ וְגוֹ'. וַתֵּצֵא לֵאָה לִקְרָאתוֹ, מִנַּיִן יָדְעָה? הֲרֵי אָמְרוּ שֶׁגָּעָה הַחֲמוֹר, וְלֵאָה יָדְעָה וְיָצְאָה אֵלָיו, וְגָרַם לוֹ שֶׁיֵּצֵא מִמֶּנָּה יִשָּׂשכָר. זֶהוּ שֶׁכָּתוּב יִשָּׂשכָר חֲמוֹר גָּרֶם, אַל תִּקְרֵי גָּרֶם אֶלָּא גָרַם, שֶׁהַחֲמוֹר גָּרַם לוֹ. אָמְרָה לֵאָה: וַדַּאי יָדַעתִּי שֶׁאִם יִכָּנֵס יַעֲקֹב לְמִשְׁכַּן רָחֵל, אֵין לִי לְהוֹצִיא אוֹתוֹ, אֶלָּא אֲחַכֶּה לוֹ כָּאן וְיִכָּנֵס לְמִשְׁכָּנִי."],[4,"","כִּי שָׂכֹר שְׂכַרְתִּיךְ בְּדוּדָאֵי בְּנִי, מַה זֶּה בְּדוּדָאֵי בְּנִי? מִשּׁוּם שֶׁנּוֹחַ לְיַעֲקֹב עַל זֶה, שֶׁאֵלּוּ מְסַיְּעִים לְהוֹלִיד. וְיַעֲקֹב הָיָה יוֹדֵעַ שֶׁהַדָּבָר לֹא עוֹמֵד בַּדּוּדָאִים, אֶלָּא לְמַעְלָה."],[5,"","פָּתַח וְאָמַר, מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת אֵם הַבָּנִים שְׂמֵחָה הַלְלוּיָהּ. אָמַר רַבִּי חִיָּיא, רוּחַ הַקֹּדֶשׁ אוֹמֶרֶת: מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת - זוֹ רָחֵל. אֵם הַבָּנִים שְׂמֵחָה - זוֹ לֵאָה. מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת - זֶה הָעוֹלָם הַתַּחְתּוֹן. אֵם הַבָּנִים שְׂמֵחָה (הללויה) - זֶה הָעוֹלָם הָעֶלְיוֹן. מִשּׁוּם כָּךְ הַלְלוּיָהּ."],[6,"","אָמַר רַבִּי יְהוּדָה, כָּל הַשְּׁבָטִים הַלָּלוּ הֵם תִּקּוּנִים שֶׁלְּמַטָּה, וְכֻלָּם כְּמוֹ שֶׁלְּמַעְלָה. בּא רְאֵה, כִּי שָׂכֹר שְׂכַרְתִּיךְ - לָקַחַת מִמֶּנּוּ הַגּוּף, וּמִי הוּא? תּוֹרָה. שָׂכֹר שְׂכַרְתִּיךְ - לְךְ, לְגוּפְךְ מַמָּשׁ. שָׂכֹר שְׂכַרְתִּיךְ - לְהוֹלִיד אֶת דְּמוּתְךְ."]]],[["מֵהָכָא, מַאן דְּלָעֵי בְּאוֹרַיְיתָא, אַחְסִין עַלְמָא דְאָתֵי וְאַחְסִין אַחְסַנְתָּא דְיַעֲקֹב. אַחְסִין עַלְמָא דְאָתֵי, דִּכְתִיב יִשָּׂשכָר יֵשׁ שָׂכָר, (ירמיהו ל״א:ט״ז) כִּי יֵשׁ שָׂכָר לִפְעֻלָּתֵךְ. וּכְתִיב, (משלי ח׳:כ״א) לְהַנְחִיל אֹהֲבַי יֵשׁ וְאֹצְרֹתֵיהֶם אֲמַלֵּא.","(בראשית ל׳:כ׳) כִּי יָלַדְתִּי לוֹ שִׁשָּׁה בָנִים. אָמַר רִבִּי חִזְקִיָּה, אִלֵּין עֵילָא וְתַתָּא וְאַרְבַּע סִטְרִין דְּעַלְמָא. וּמַאן דְּאָרִיךְ בְּאֶחָד, בָּעֵי לֵיהּ לְאַמְלָכָא לְקוּדְשָׁא בְּרִיךְ הוּא לְעֵילָא וְתַתָּא, וּלְאַרְבַּע סִטְרֵי דְעַלְמָא, וְהַיְינוּ אֶחָד.","אָמַר רִבִּי חִזְקִיָּה, כְּתִיב, (שיר השירים ב) עַל הָרֵי בָתֶר, וּכְתִיב, (שיר השירים ח) עַל הָרֵי בְשָׂמִים, מַאן אִינוּן הָרֵי בְשָׂמִים. אִלֵּין שִׁית בְּנִין דְּלֵאָה, דְּאַכְלָלָן שִׁית אָחֳרָנִין, וְאִינוּן תְּרֵיסַר, וְאִינוּן שִׁית. בְּגִין (רמ\"א ע\"א) דְּכָל חַד כָּלִיל בְּחַבְרֵיהּ, וְלֵאָה עֲלַיְיהוּ, לְקַיְימָא (תהילים קי״ג:ט׳) אֵם הַבָּנִים שְׂמֵחָה הַלְּלוּיָה.","וְעַל דָּא כְּתִיב, (דברים כ״ב:ו׳) לֹא תִקַּח הָאֵם עַל הַבָּנִים, בְּגִין דְּאִיהוּ עַלְמָא דְאִתְכַּסְּיָא, וְלָא אִתְגַּלְּיָא, וְעַל דָּא (שם) שַׁלַּח תְּשַׁלַּח אֶת הָאֵם וְאֶת הַבָּנִים תִּקַּח לָךְ. בְּגִין דְּאִיהוּ עַלְמָא דְאִתְכַּסְּיָא, וְלָא אִתְגַּלְּיָא כְּלָל.","וְאֶת הַבָּנִים תִּקַּח לָךְ, הַיְינוּ דִכְתִיב, (דברים ד׳:ל״ב) כִּי שְׁאַל נָא לְיָמִים רִאשׁוֹנִים וְגו' (שם) וּלְמִקְצֵה הַשָּׁמַיִם וְעַד קְצֵה הַשָּׁמָיִם. וְכָל הַנֵּי, אִקְרוּן הָרֵי בְשָׂמִים, מִכָּאן וּלְתַתָּא אִקְרוּן הָרֵי בָתֶר, (כ\"ט ע\"ב) דִּכְתִיב, (בראשית ב׳:י׳) וּמִשָּׁם יִפָּרֶד, וְהָיָה לְאַרְבָּעָה רָאשִׁים, טוּרֵי דְפִירוּדָא.","אָמַר רִבִּי יֵיסָא, בְּנֵי הַשְּׁפָחוֹת קְשִׁירוּ קִשְׁרִין, (קנ\"ד ע\"א) אַרְבַּע קִשְׁרִין דְּאִצְטְרִיכוּ לְתִקּוּנָא. וְאָמַר רִבִּי אֶלְעָזָר, דִּבְגִין כָּךְ נָפְקֵי לְבַר אִינוּן קִשְׁרִין, וְאַף עַל גַּב דְּכֻלְּהוּ חַד, וּמִכָּאן וּלְהָלְאָה כֻּלְּהוּ חַד, בְּאוֹרַח מֵישָׁר. וְעַל דָּא, כֻּלְּהוּ שִׁבְטִין סָלְקִין בְּסַהֲדוּתָא דִלְעֵילָא, הֲדָא הוּא דִכְתִיב, (תהילים קכ״ב:ד׳) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל לְהוֹדוֹת לְשֵׁם ה'.","וְאָמַר רִבִּי אֶלְעָזָר, כְּתִיב, (בראשית ל׳:כ״ה) וַיְהִי כַּאֲשֶׁר יָלְדָה רָחֵל אֶת יוֹסֵף וְגו', מַה חָמָא יַעֲקֹב לְמֵיהַךְ לְאוֹרְחֵיהּ, כָּד אִתְיְלִיד יוֹסֵף, וְעַד לָא אִתְיְלִיד יוֹסֵף לָא בָעָא לְמֵיהַךְ לְאוֹרְחֵיהּ. אֶלָּא הָא אוּקְמוּהָ, דְּחָמָא דְאִתְיְלִיד שִׂטְנָא דְעֵשָׂו.","וְתָא חֲזֵי, יוֹסֵף אַשְׁלִים דּוּכְתֵּיהּ בַּתְרֵיהּ וְיוֹסֵף זָכֵי לֵיהּ, דְּאִקְרֵי צַדִּיק, וְהָכָא סִיּוּמָא דְגוּפָא. כֵּיוָן דְּחָמָא יַעֲקֹב, דְּאִשְׁתְּלִים גּוּפָא, בָּעָא גּוּפָא לְמֵהַךְ לְאוֹרְחֵיהּ, וְסִיּוּמָא דְגוּפָא הוּא בְּרִית. וְעִם כָּל דָּא בִּנְיָמִן אַשְׁלִים חוּשְׁבְּנָא, דְּבֵיהּ אִשְׁתְּלִימוּ תְּרֵיסַר.","וְאִי תֵימָא, וְכִי לָא הֲוָה יָדַע יַעֲקֹב, דְּעַד כְּעָן לָא אִשְׁתַּלִּימוּ שִׁבְטִין, אַף עַל גַּב דְּאִתְיְלִיד יוֹסֵף, מַאי טַעְמָא לָא אוֹרִיךְ עַד דְּיִתְיְלִיד בִּנְיָמִין וְיִשְׁתַּלִּימוּ שִׁבְטִין. אֶלָּא, יַעֲקֹב בְּחָכְמְתָא עֲבַד, וּמִלָּה יָדַע. אָמַר, וַדַּאי אִי אִשְׁתַּלִּימוּ הָכָא כֻּלְּהוּ שִׁבְטִין, הָא יְדַעְנָא דְּתִקּוּנָא דִּלְעֵילָא שַׁרְיָא עֲלַיְיהוּ כְּדְקָא יְאוּת. וּבְאַרְעָא דָא, לָא לִיבָּעֵי דְּיִשְׁתְּלִימוּ, אֶלָּא בְּאַרְעָא קַדִּישָׁא.","תָּא חֲזֵי דְּהָכִי הוּא, דְּכֻלְּהוּ תְּרֵיסַר שִׁבְטִין, תִּקּוּנָא דְעַלְמָא תַּתָּאָה נִינְהוּ, וְכֵיוָן דְּאִתְיְלִיד בִּנְיָמִין, מִיתַת רָחֵל, וְנָטְלָא דוּכְתָּא הַאי עַלְמָא תַּתָּאָה, לְאִתְתַּקָּנָא בְּהוּ. וְעַל דָּא לָא אִתְיְלִיד בִּנְיָמִין, אֶלָּא בְּאַרְעָא קַדִּישָׁא, הֲדָא הוּא דִכְתִיב, (בראשית מ״ח:ז׳) וַאֲנִי בְּבוֹאִי מִפַּדָּן מֵתָה עָלַי רָחֵל בְּאֶרֶץ כְּנַעַן בַּדֶּרֶךְ, וְתַמָּן מִיתַת רָחֵל וְנָטְלָא דוּכְתָּא, הַאי עַלְמָא תַּתָּאָה, לְאִתְיַשְּׁבָא בְּבֵיתָא שְׁלֵימָתָא, וְכָל זִמְנָא דְרָחֵל קָיְימָא, עַלְמָא תַּתָּאָה לָא אִתְתַּקְּנָא בְּהוּ, מִיתַת רָחֵל, נָטְלָא (ד\"א ל\"ג לעילא) בֵּיתָא בִּשְׁלִימוּ.","וְאִי תֵימָא, לֵאָה אַמַּאי לָא מִיתַת בְּהַהוּא זִמְנָא. אֶלָּא בְּגִין דְּבֵיתָא בְּעַלְמָא תַּתָּאָה (נ\"א עלאה) אִיהוּ, וְכֹלָּא מִנֵּיהּ הֲווּ לְאִתְתַּקְּנָא, וְלָאו מֵעָלְמָא עִלָּאָה (נ\"א תתאה), וּבְגִין כָּךְ לָא מִיתַת בְּהַהִיא שַׁעְתָּא. וְכָל עוֹבָדוֹי דְּלֵאָה בְּאִתְכַּסְּיָא אִינוּן, בְּגִין דְּעַלְמָא עִלָאָה אִיהוּ בְּאִתְכַּסְּיָא, וְלָאו בְּאִתְגַּלְּיָא, וּבְגִין כָּךְ לָא אִדְכַּר מִיתָתָהּ דְלֵאָה, כְּמִיתָתָהּ דְּרָחֵל.","וְתָא חֲזֵי, דְּהָכִי הוּא וַדַּאי. בְּגִין דְּעַלְמָא עִלָּאָה, כָּל מִלּוֹי בְּאִתְכַּסְּיָא, וְעַלְמָא תַּתָּאָה כָּל מִלּוֹי בְּאִתְגַּלְּיָא. בְּגִין כָּךְ, אִתְכַּסְּיָא לֵאָה בִּמְעַרְתָּא דְּכָפֶלְתָּא, וְרָחֵל בְּגִלּוּיָיא דְּאוֹרְחָא, דָּא בְּסִתְרָא, וְדָא בְּאִתְגַּלְּיָא. וּבְאִתְכַּסְּיָא עַלְמָא עִלָּאָה אִתְרְשִׁים, דִּכְתִיב, (בראשית ל׳:י״ג) וַתֹּאמֶר לֵאָה בְּאָשְׁרִי כִּי אִשְׁרוּנִי בָנוֹת, וּבְגִין כָּךְ קָרְאָה שְׁמֵיהּ אָשֵׁר."],[[0,"מהכא מאן דלעי וכו':","מכאן נשמע, שמי שעוסק בתורה יורש עולם הבא, שהוא המוחין דבינה, ויורש נחלת יעקב, שהוא המוחין דאו\"א עלאין. שכתוב \u0003יששכר\u0004 שהוא נוטריקון יש שכר, והיינו, יש שכר לפעולתך, שפעולתו הוא עסק התורה כנ\"ל. והשכר הוא כמו שכתוב, להנחיל אוהבי, \u0003יש,\u0004 שהוא בינה שחזרה לחכמה. ואוצרותיהם \u0003אמלא,\u0004 ה\"ס המוחין דאו\"א עלאין שה\"ס נחלת יעקב, שנחל מהם, וה\"ס נחלה בלי מצרים. ואלו ב' מיני מוחין הם שכרו של העוסק בתורה."],[1,"כי ילדתי לו ששה בנים:","אמר ר' חזקיה אלו הם מעלה ומטה שהם נצח והוד, וארבע רוחות העולם שהם: חסד, גבורה, ת\"ת, ויסוד. למי שמאריך \u0003באחד,\u0004 היינו באחד דקריאת שמע, צריך להמליך את הקב\"ה למעלה ומטה, ולארבע רוחות העולם. והיינו \u0003אחד.\u0004 כלומר שאחדותו ית' מתגלה בששה קצוות הללו."],[2,"אמר ר' חזקיה וכו':","אר\"ח, כתוב על הרי בתר וכתוב על הרי בשמים. ושואל, מי הם הרי בשמים. ומשיב, אלו הם ששה בנים של לאה, הכוללים ששה אחרים, דהיינו יוסף ובנימין, ובני השפחות, והם שני עשר והם ששה, כלומר שאפשר לומר שהם שני עשר, ואפשר לומר שהם ששה, משום שכל אחד כלול בחבירו, ואם תחשוב ששה העיקרים הם שש, ואם תחשוב גם את הנכללים בהם, הם שני עשר. ולאה עומדת עליהם, וה\"ס י\"ג. לקיים הכתוב, אם הבנים שמחה הללויה."],[3,"ועל דא כתיב וכו':","ועל כן כתוב, לא תקח האם על הבנים, משום שהיא עולם הנסתר ולא נתגלה, שאין לתחתונים השגה בה. ועל כן, \u0003שלח תשלח את האם ואת הבנים תקח לך,\u0004 משום שהאם היא עולם הנסתר ואינו מתגלה כלל. פירוש, \u0003תקח לך,\u0004 פירושו תקח להשגתך היינו שתמשיך בהם הארת חכמה ותגלה אותם, והוא חיוב, משום שהאם שהיא לאה, הוא נסתרת, כלומר בלי השגה. לכן תשיג את הבנים."],[4,"ואת הבנים תקח לך:","היינו שכתוב, כי שאל נא לימים ראשונים וגו' ולמקצה השמים, שהוא חסד, קצה הראשין דז\"א הנקרא שמים, ועד קצה השמים שהוא יסוד, קצה האחרון דז\"א. דהיינו ששה קצוות חג\"ת נה\"י דז\"א, המכונים ששה בני לאה. ומשמיענו הכתוב, שבהם נוהג שאלה, שה\"ס העלאת מ\"ן להמשכת חכמה. (כמ\"ש לעיל בהקסה\"ז דף י\"ח ד\"ה מי ע\"ש) וכל אלו נקראים \u0003הרי בשמים.\u0004 מכאן ולמטה, היינו אחר המלכות דאצילות, נקראים \u0003הרי בתר,\u0004 שכתוב ומשם יפרד והיה לארבעה ראשים, שהם הרי פירוד, פי' עד המלכות דאצילות הוא עולם היחוד, דאיהו וגרמוהי וחיוהי חד בהון (כמ\"ש במבוא לספר הזהר אות כ\"ט ע\"ש) ולמטה ממנה הם ג' עולמות בי\"ע דפרודא. כמ\"ש שם."],[5,"אמר ר' ייסא וכו':","בני השפחות קשרו קשרים, ארבעה הקשרים שצריכים לתקון. (כמ\"ש לעיל דף ס\"ג ד\"ה תו ע\"ש) ואמר ר' אלעזר, משום זה אלו הקשרים יוצאים ובולטים לחוץ מן הגוף, ואע\"פ שכולם אחד. כלומר אע\"פ שכבר נתקנו בסוד וכל אחוריהם ביתה מ\"מ נשארו בולטים מחוץ לגוף להיותם מתחילה מטרם היחוד, ריקנים בלי אור כלל. (כמ\"ש שם ד\"ה דהא ע\"ש) ומכאן ולהלאה, כלומר שאר הקשרים, הם כולם אחד בדרך מישור, שאינם בולטים מגוף (דף ס\"ד בד\"ה כל ע\"ש). ועל כן כל השבטים עולים \u0003בעדות\u0004 של מעלה, שהם המוחין דבינה הנק' עדות, בסו\"ה ונהר יוצא \u0003מעדן.\u0004 וזהו שכתוב, ששם עלו שבטים שבטי יה \u0003עדות\u0004 לישראל להודות לשם ה'."],[6,"ואמר ר' אלעזר וכו':","ואר\"א. ויהי כאשר ילדה רחל את יוסף וגו' שואל, מה ראה יעקב שבקש ללכת לדרכו כשנולד יוסף. ומטרם שנולד יוסף לא בקש כלל ללכת לדרכו. ומשיב, אלא כבר בארוה, שראה שנולד שטנו של עשו. כי יוסף הוא שטן של עשו, שנאמר והיה בית יעקב לאש ובית יוסף להבה ובית עשו לקש."],[7,"ותא חזי יוסף וכו':","ובוא וראה יוסף השלים מקומו של יעקב אחריו. כי הוא ספירת היסוד, שהיא ספירה אחרונה של יעקב. ויוסף זכה שנקרא צדיק, דהיינו יסוד, וכאן הוא סיום הגוף, ספירה אחרונה כנ\"ל, כיון שראה יעקב שנשלם הגוף עם לידת יוסף, בקש הגוף ללכת לדרכו. וסיום הגוף הוא ברית, דהיינו יוסף. ועם כל זה, בנימין השלים החשבון, כי עמו נשלם מספר י\"ב."],[8,"ואי תימא וכו':","ואם תאמר, וכי יעקב לא היה יודע, שעד עתה עוד לא נשלמו השבטים, אע\"פ שנולד יוסף. מהו הטעם, שלא חכה עד שיולד בנימין, וישלמו השבטים. ומשיב, אלא יעקב עשה בחכמה, וידע הדבר, שעוד לא נשלמו השבטים, אמר ודאי אם יושלמו כאן כל השבטים, הרי אני יודע שתקון העליון יניח עליהם כראוי, ובארץ הזו איני רוצה שיושלמו, אלא בארץ הקדושה."],[9,"ת\"ח דהכי הוא וכו':","בוא וראה שכך הוא, כי כל י\"ב השבטים, המה תקון של עולם התחתון, שהוא הנוקבא דז\"א שמחזה שלו ולמטה, וכיון שנולד בנימין, ונשלמו י\"ב, מתה רחל, ועולם התחתון, שהוא נוקבא דז\"א, לקחה מקום להתתקן בהם."],[9,"","פירוש. כי אין הנוקבא מתתקנת פחות מי\"ב, וכשהיא מתתקנת בי\"ב השבטים, שה\"ס מוחין השלמים דהארת החכמה, אז נעשו ב' הנוקבין דז\"א רחל ולאה פרצוף אחד, אשר לאה היא בפנימיות ורחל היא בחצוניות. וז\"ס כי כשנולד בנימין ונשלמו י\"ב השבטים, אז נתקנה בהם נוקבא דז\"א שמחזה ולמטה שלו, דהיינו שעלתה ונתאחדה עם הנוקבא שמחזה ולמעלה המכונה לאה, כי נעשו לפרצוף אחד. אמנם מטרם שנשלמו י\"ב השבטים, מתחלקת נוקבא דז\"א לב' פרצופין, שלשתיהן אין שלמות, כי לעליונה, לאה, חסרים תנה\"י דז\"א, ולתחתונה, רחל, חסרים הג\"ר שמחזה ולמעלה דז\"א. וז\"ס שמתה אז רחל, כלומר, שנתבטל בחינת הנוקבא שמחזה ולמטה דז\"א, כי שתי הנוקבות נעשו לאחת, כמבואר. וז\"ש \u0003וכיון דאתיליד בנימין,\u0004 שנשלמו י\"ב השבטים, \u0003מיתת רחל ונטלא דוכתא האי עלמא תתאה לאתתקנא בהו,\u0004 נתבטל בחינת הנוקבא שמחזה ולמטה דז\"א, כי עולם התחתון נתתקן בי\"ב השבטים, ונעשה משום זה פרצוף אחר עם עולם העליון, כמבואר."],[9,"ועל דא לא אתיליד וכו':","ועל כן לא נולד בנימין אלא בארץ הקדושה, וז\"ש ואני בבואי מפדן ארם וגו', ושם מתה רחל, ועולם התחתון הזה, שהוא נוקבא דז\"א שמחזה ולמטה קבל מקום להתיישב בבית שלם, דהיינו בכל קומת ז\"א, כי נעשה אחד עם עולם העליון, שלמעלה מחזה, כנ\"ל בסמוך. וכל זמן שרחל היתה קימת, דהיינו שהיה לו ב' נוקבין, הרי עולם התחתון עוד לא נתתקן בי\"ב השבטים, כנ\"ל, מתה רחל, כי נעשתה אחת עם הנוקבא העליונה, קבלה בית בשלמות. דהיינו כנגד כל קומתו דז\"א."],[10,"ואי תימא לאה וכו':","ושואל, ואם תאמר, למה לא מתה לאה באותו הזמן, שנשלמו י\"ב השבטים, וב' הנוקבין דז\"א נעשו לאחת, שהרי אז נתבטלה גם בחינת לאה כמו בחינת רחל, וגם לאה היתה צריכה למות כמו רחל. ומשיב, הוא משום שהבית הוא בעולם התחתון, דהיינו בנוקבא שמחזה ולמטה הנקראת רחל, והכל צריכים להתתקן ממנו, כלומר שבשלמותו תלוי שלמות כל התחתונים שבבי\"ע, ולא מעולם העליון, וע\"כ אין בחינת עולם העליון, שהוא לאה, מתבטל במשהו, אפילו אחר שנשלמו י\"ב השבטים, כלומר שגם אז היא בחסדים מכוסים כמטרם השלמות. ומשום זה לא מתה לאה באותו הזמן, כי לא נתבטלה, כמבואר."],[11,"ותא חזי דהכי הוא וכו':","ובוא וראה שכן הוא בודאי, כי עולם העליון, שהוא לאה, כל דבריו בהסתר, ועולם התחתון כל דבריו בגלוי. ומשום זה נסתרה לאה ונקברה במערת המכפלה, ורחל נקברה בדרך הגלוי, זו בסתר וזו בגלוי. וכן נצטיין עולם העליון בהסתר, שכתוב, ותאמר לאה באשרי כי אשרוני בנות, ומשום זה קראה שמו אשר."],[11,"","פירוש. כי השם \u0003אשר\u0004 יורה על חסדים מכוסים, כמ\"ש לעיל (ב\"א דף י\"ב אות ו') \u0003אשר, ראש דנפיק מראשית,\u0004 שנתבאר שם בהסולם, שה\"ס בינה שיצאה מראש א\"א הנק' ראשית, שפירושו שנעשתה מכוסה ונעלמת מבחינת ראש שה\"ס חכמה. כי אותיות \u0003אשר\u0004 הן אותיות \u0003ראש\u0004 למפרע. דהיינו בהיפך מבחינת \u0003ראש\u0004 ע\"ש. וכן אומר בת\"ז (תק' ל\"ט דף ע\"ט ע\"ב) \u0003מסטרא דנוקבא\u0004 שהיא אמא \u0003אתקרי אשר,\u0004 ומסטרא דדכורא \u0003אתקרי ראש\u0004 רישא דכל רישין דהיינו א\"א שה\"ס חכמה. וזסו\"ה באשרי וגו' ותקרא את שמו \u0003אשר,\u0004 דהיינו שקראה אותו בשמה עצמה. דהיינו ע\"ש החסדים המכוסים שבה. הרי שלאה נצטיינה בחסדים המכוסים שבה, ומתפארת עמהם, באופן שאפילו בעת שב' הנוקבות נעשו פרצוף אחד, ויכולה לקבל חכמה, מ\"מ אינה חפצה בחכמה אלא נשארה בחסדים מכוסים, בסו\"ה כי חפץ חסד הוא. וז\"ס שלא מתה אז לאה."]],[[0,"","מִכָּאן מִי שֶׁעוֹסֵק בַּתּוֹרָה, יוֹרֵשׁ אֶת הָעוֹלָם הַבָּא וְיוֹרֵשׁ אֶת נַחֲלַת יַעֲקֹב. יוֹרֵשׁ הָעוֹלָם הַבָּא, שֶׁכָּתוּב יִשָּׂשכָר, יֵשׁ שָׂכָר, (ירמיה לא) כִּי יֵשׁ שָׂכָר לִפְעֻלָּתֵךְ, וְכָתוּב (משלי ח) לְהַנְחִיל אֹהֲבַי יֵשׁ וְאֹצְרֹתֵיהֶם אֲמַלֵּא."],[1,"","כִּי יָלַדְתִּי לוֹ שִׁשָּׁה בָנִים. אָמַר רַבִּי חִזְקִיָּה, אֵלּוּ מַעְלָה וּמַטָּה וְאַרְבַּעַת הַצְּדָדִים שֶׁל הָעוֹלָם. וּמִי שֶׁמַּאֲרִיךְ בְּאֶחָד, צָרִיךְ לוֹ לְהַמְלִיךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּלְמַטָּה וּלְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְהַיְינוּ אֶחָד."],[2,"","אָמַר רַבִּי חִזְקִיָּה, כָּתוּב (שיר ב) עַל הָרֵי בָתֶר, וְכָתוּב (שם ח) עַל הָרֵי בְשָׂמִים. מִי הֵם הָרֵי בְשָׂמִים? אֵלּוּ שֵׁשֶׁת הַבָּנִים שֶׁל לֵאָה שֶׁכּוֹלְלִים שִׁשָּׁה אֲחֵרִים, וְהֵם שְׁנֵים עָשָׂר, וְהֵם שִׁשָּׁה, מִשּׁוּם שֶׁכָּל אֶחָד כָּלוּל בַּחֲבֵרוֹ, וְלֵאָה עֲלֵיהֶם, לְקַיֵּם (תהלים קיג) אֵם הַבָּנִים שְׂמֵחָה הַלְלוּיָהּ."],[3,"","וְעַל כֵּן כָּתוּב לֹא תִקַּח הָאֵם עַל הַבָּנִים, מִשּׁוּם שֶׁהוּא הָעוֹלָם הַנִּסְתָּר וְלֹא הַנִּגְלֶה, וְעַל כֵּן שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם וְאֶת הַבָּנִים תִּקַּח לָךְ, מִשּׁוּם שֶׁהוּא הָעוֹלָם שֶׁנִּסְתָּר וְלֹא הִתְגַּלָּה כְּלָל."],[4,"","וְאֶת הַבָּנִים תִּקַּח לָךְ, הַיְנוּ שֶׁכָּתוּב כִּי שְׁאַל נָא לְיָמִים רִאשׁוֹנִים וְגוֹ' וּלְמִקְצֵה הַשָּׁמַיִם וְעַד קְצֵה הַשָּׁמָיִם. וְכָל אֵלּוּ נִקְרָאִים הָרֵי בְשָׂמִים. מִכָּאן וּלְמַטָּה נִקְרְאוּ הָרֵי בָתֶר, שֶׁכָּתוּב וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים, הֶהָרִים שֶׁל הַפֵּרוּד."],[5,"","אָמַר רַבִּי יֵיסָא, בְּנֵי הַשְּׁפָחוֹת קָשְׁרוּ קְשָׁרִים, אַרְבָּעָה קְשָׁרִים שֶׁהִצְטָרְכוּ לְתִקּוּן. וְאָמַר רַבִּי אֶלְעָזָר, שֶׁמִּשּׁוּם כָּךְ יוֹצְאִים הַחוּצָה אוֹתָם הַקְּשָׁרִים. וְאַף עַל גַּב שֶׁכֻּלָּם אֶחָד, וּמִכָּאן וָהָלְאָה כֻּלָּם אֶחָד, בְּדֶרֶךְ יְשָׁרָה, וְעַל כֵּן כָּל הַשְּׁבָטִים עוֹלִים בְּעֵדוּת לְמַעְלָה. זֶהוּ שֶׁכָּתוּב (תהלים קכב) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל לְהוֹדוֹת לְשֵׁם ה'."],[6,"","וְאָמַר רַבִּי אֶלְעָזָר, כָּתוּב וַיְהִי כַּאֲשֶׁר יָלְדָה רָחֵל אֶת יוֹסֵף וְגוֹ'. מָה רָאָה יַעֲקֹב לָלֶכֶת לְדַרְכּוֹ כְּשֶׁנּוֹלַד יוֹסֵף, וְטֶרֶם שֶׁנּוֹלַד יוֹסֵף לֹא רָצָה לָלֶכֶת לְדַרְכּוֹ? אֶלָּא הִנֵּה פֵּרְשׁוּהָ, שֶׁרָאָה שֶׁנּוֹלַד שְׂטָנוֹ שֶׁל עֵשָׂו."],[7,"","וּבֹא וּרְאֵה, יוֹסֵף הִשְׁלִים אֶת מְקוֹמוֹ אַחֲרָיו וְיוֹסֵף זָכָה לוֹ, שֶׁנִּקְרָא צַדִּיק, וְכָאן סִיּוּם הַגּוּף. כֵּיוָן שֶׁרָאָה יַעֲקֹב שֶׁנִּשְׁלַם הַגּוּף, רָצָה הַגּוּף לָלֶכֶת לְדַרְכּוֹ, וְסִיּוּם הַגּוּף הוּא הַבְּרִית, וְעִם כָּל זֶה בִּנְיָמִין הִשְׁלִים אֶת הַחֶשְׁבּוֹן, שֶׁבּוֹ נִשְׁלְמוּ שְׁנֵים עָשָׂר."],[8,"","וְאִם תֹּאמַר, וְכִי לֹא הָיָה יוֹדֵעַ יַעֲקֹב שֶׁעַד עַכְשָׁו לֹא הִשְׁתַּלְּמוּ הַשְּׁבָטִים, אַף עַל גַּב שֶׁנּוֹלַד יוֹסֵף, מָה הַטַּעַם לֹא חִכָּה עַד שֶׁנּוֹלַד בִּנְיָמִין וְיִשְׁתַּלְּמוּ הַשְּׁבָטִים? אֶלָּא יַעֲקֹב עָשָׂה בְּחָכְמָה וְיָדַע הַדָּבָר. אָמַר, וַדַּאי אִם יִשְׁתַּלְּמוּ כָּאן כָּל הַשְּׁבָטִים, הִנֵּה יָדַעְתִּי שֶׁהַתִּקּוּן שֶׁל מַעְלָה שָׁרוּי עֲלֵיהֶם כָּרָאוּי, וּבָאָרֶץ הַזּוֹ לֹא צְרִיכִים שֶׁיִּשְׁתַּלְּמוּ, אֶלָּא בָּאָרֶץ הַקְּדוֹשָׁה."],[9,"","בֹּא רְאֵה שֶׁכָּךְ הוּא, שֶׁכָּל שְׁנֵים עָשָׂר הַשְּׁבָטִים הֵם הַתִּקּוּן שֶׁל הָעוֹלָם הַתַּחְתּוֹן, וְכֵיוָן שֶׁנּוֹלַד בִּנְיָמִין, מֵתָה רָחֵל, וְלָקְחָה אֶת הַמָּקוֹם הָעוֹלָם הַתַּחְתּוֹן הַזֶּה לְהִתְתַּקֵּן בָּהֶם, וְעַל כֵּן לֹא נוֹלַד בִּנְיָמִין אֶלָּא בָּאָרֶץ הַקְּדוֹשָׁה. זֶהוּ שֶׁכָּתוּב וַאֲנִי בְּבֹאִי מִפַּדָּן מֵתָה עָלַי רָחֵל בְּאֶרֶץ כְּנַעַן בַּדֶּרֶךְ, וְשָׁם מֵתָה רָחֵל וְנָטְלָה אֶת הַמָּקוֹם, הָעוֹלָם הַתַּחְתּוֹן הַזֶּה, לְהִתְיַשֵּׁב בְּבַיִת שָׁלֵם. וְכָל זְמַן שֶׁרָחֵל קַיֶּמֶת, הָעוֹלָם הַתַּחְתּוֹן אֵינוֹ נִתְקָן בָּהֶם. מֵתָה רָחֵל - נָטְלָה (למעלה) הַבַּיִת בִּשְׁלֵמוּתוֹ."],[10,"","וְאִם תֹּאמַר, לָמָּה לֹא מֵתָה לֵאָה בְּאוֹתוֹ הַזְּמַן? אֶלָּא מִשּׁוּם שֶׁהַבַּיִת הוּא בָּעוֹלָם הַתַּחְתּוֹן (העליון), וְהַכֹּל הָיוּ מִמֶּנּוּ לְהִתְתַּקֵּן, וְלֹא מִן הָעוֹלָם הָעֶלְיוֹן (התחתון), וּמִשּׁוּם כָּךְ לֹא מֵתָה בְּאוֹתָהּ שָׁעָה. וְכָל מַעֲשֵׂי לֵאָה הֵם בְּנִסְתָּר, מִשּׁוּם שֶׁהָעוֹלָם הָעֶלְיוֹן הוּא בְּנִסְתָּר וְלֹא בְּנִגְלֶה, וּמִשּׁוּם כָּךְ לֹא נִזְכְּרָה מִיתָתָהּ שֶׁל לֵאָה כְּמִיתָתָהּ שֶׁל רָחֵל."],[11,"","וּבֹא וּרְאֵה שֶׁכָּךְ זֶה וַדַּאי, מִשּׁוּם שֶׁהָעוֹלָם הָעֶלְיוֹן כָּל דְּבָרָיו בְּנִסְתָּר, וְהָעוֹלָם (העליון) הַתַּחְתּוֹן כָּל דְּבָרָיו בְּנִגְלֶה, מִשּׁוּם כָּךְ נִתְכַּסְּתָה לֵאָה בִּמְעָרַת הַמַּכְפֵּלָה, וְרָחֵל בַּדֶּרֶךְ הַגְּלוּיָה. זוֹ בְּנִסְתָּר, וְזוֹ בְּגָלוּי. וּבַנִּסְתָּר הָעוֹלָם הָעֶלְיוֹן נִרְשַׁם, שֶׁכָּתוּב וַתֹּאמֶר לֵאָה בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָנוֹת, וּמִשּׁוּם כָּךְ קָרְאָה שְׁמוֹ אָשֵׁר. (משום כך כל הברכות של שני העולמות בנגלה ובנסתר, ועם כל זה)."]]],[["(בגין כך כל ברכאן דתרין עלמין באתגליא ובאתכסיא ועם כל דא). וּבְגִין דָּא, כֹּלָּא חַד, דְּהָא כֹּלָּא הֲוֵי מֵעַלְמָא עִלָּאָה. הָכִי נָמֵי וּבְכָל אֲתַר, תְּרֵין עָלְמִין, דָּא בְּאִתְגַּלְּיָא וְדָא בְּאִתְכַּסְּיָא. וְאֲנַן לָא מְבָרְכִינָן לְקוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא בִּתְרֵין עָלְמִין, דִּכְתִיב, (תהילים ק״ו:מ״ח) בָּרוּךְ ה' אֱלהֵי יִשְׂרָאֵל (קנ\"ג ע\"ב) מִן הָעוֹלָם וְעַד הָעוֹלָם. בְּגִינֵי כָּךְ, עַלְמָא עִלָּאָה קָרֵינָן הו\"א, וְקָרֵינָן לְעַלְמָא (שמות קל\"ח ע\"ב) תַּתָּאָה אַתָּ\"ה, בְּגִין דְּאִיהוּ בָּרוּךְ מֵעַלְמָא עִלָּאָה, עַל יְדָא דְצַדִּיק. הֲדָא הוּא דִכְתִיב (תהילים קל״ה:כ״א) בָּרוּךְ ה' מִצִּיּוֹן שׁוֹכֵן יְרוּשָׁלָם וְגו'. וַדַּאי מִצִּיּוֹן אִיהוּ בָּרוּךְ.","תָּא חֲזֵי, כְּגַוְונָא דָא (שמות לה) ה' ה' תְּרֵין עָלְמִין (נשא קל\"ח ע\"א) נִינְהוּ, דָּא בְּאִתְגַּלְּיָא וְדָא בְּאִתְכַּסְּיָא, וְעַל דָּא פָּסִיק טַעְמָא בְּגַוַּוְיְיהוּ, וּמֵעַלְמָא דָא עַד עַלְמָא דָא, כֹּלָּא חָד.","(בראשית לא) וַיְהִי כַּאֲשֶׁר יָלְדָה רָחֵל אֶת יוֹסֵף וְגו', אָמַר (נדפס דף קס\"ה ע\"א בסתרי תורה) רִבִּי יְהוּדָה, תָּא חֲזֵי, שְׁלֵימוּתָא דְיַעֲקֹב דְּלָא בָעָא לְמֵיזַל אֶלָּא בִּרְשׁוּתֵיהּ דְּלָבָן. וְאִי תֵימָא, זִמְנָא אַחֲרִינָא אַמַּאי לָא אָזִיל בִּרְשׁוּתֵיהּ. אֶלָא בְּגִין דְּדָחִיל יַעֲקֹב, דְּלָא יִשְׁבּוֹק לֵיהּ, וְיִשְׁתְּלִימוּ תְּרֵיסַר שִׁבְטִין בְּאַרְעָא אָחֳרָא. וְעַל דָּא כֵּיוָן דְּחָמָא דְּמָטָא שַׁעְתָּא דְבִנְיָמִין, בָּרַח. כְּמָה דְאַתְּ אָמֵר, וַיִּבְרַח הוּא וְכָל אֲשֶׁר לוֹ.","דְּכֵיוָן דְּאִתְיְלִיד בִּנְיָמִין, אִתְקַשְׁרַת שְׁכִינְתָּא בְּכֻלְּהוּ שִׁבְטִין, וְנָטְלָא בֵּיתָא בְּכֻלְּהוּ. וְיַעֲקֹב הֲוָה יָדַע בְּרָזָא דְּחָכְמְתָא, דְּכַד יִשְׁתַּלִּימוּ תְּרֵיסַר שִׁבְטִין, דִּשְׁכִינְתָּא תִּתְקַשֵּׁט וְתִתְקַשֵּׁר בְּהוּ, וְרָחֵל תָּמוּת, וְאִיהִי נָטְלָא בֵּיתָא.","תָּא חֲזֵי, הָכִי אוֹלִיפְנָא, עַלְמָא תַּתָּאָה אִתְחֲזֵי לֵיהּ לְיַעֲקֹב כְּמָה דְאִתְחֲזֵי לְמשֶׁה, אֶלָּא דְּלָא יְכִילַת, עַד דְּהֲווּ תְּרֵיסַר שִׁבְטִין בְּבֵיתָא לְאִתְקַשְּׁרָא בְּהוּ, וּכְדֵין אִתְדַּכִּיאַת (נ\"א אתדחיית) רָחֵל, וְנָטְלָא אִיהִי בֵיתָא בְּכֻלְּהוּ שִׁבְטִין, וַהֲוַת עִקְּרָא דְבֵיתָא, וּכְדֵין (תהילים קי״ג:ט׳) מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת וַדַּאי.","אָמַר יַעֲקֹב, הָא מָטָא זִמְנָא, דְּאִשְׁתְּלִימוּ תְּרֵיסַר שִׁבְטִין, וַדַּאי עַלְמָא דִּלְעֵילָא יֵחוֹת הוּא לְבֵיתָא לְאִתְקַשְּׁרָא בְּהוּ, וּמִסְכְּנוּתָא דָא אִתְדַּחְיָיא קַמֵּיהּ. אִי תָּמוּת הָכָא, לָא אִפּוּק מֵהָכָא לְעָלְמִין. וְלָא עוֹד, אֶלָּא בְאַרְעָא דָא, לָא אִתְחֲזֵי לְאַשְׁלָמָא בֵיתָא. בְּגִין כָּךְ וַיְהִי כַּאֲשֶׁר יָלְדָה וְגו', עַד לָא אִשְׁתַּלִּימוּ שִׁבְטִין.","שָׁמַע רִבִּי שִׁמְעוֹן, אָמַר, וַדַּאי כָּל מִלּוֹי דְּרַבִּי יְהוּדָה שַׁפִּיר, וְדָא סָלִיק עַל כֹּלָּא. וְאִי תֵימָא אַמַּאי לָא אֲזַל לֵיהּ לְאוֹרְחֵיהּ מִיָּד. אֶלָּא, כָּל זְמַן דְּרָחֵל לָא מִתְעַבְּרָא מִבִּנְיָמִין, אִתְעַכַּב תַּמָּן. כֵּיוָן דְּמָטָא זִמְנָא דְּבִנְיָמִין, עָרַק וְלָא בָעָא רְשׁוּתָא, בְּגִין דְּלָא יִתְעַכֵּב תַּמָּן וְיִתְחַבֵּר יַעֲקֹב בְּכוּלְהוּ שִׁבְטִין, בְּאַתְרָא (דלא) דְאִצְטְרִיךְ.","רִבִּי אַבָּא פָּתַח, (שמות ד׳:י״ח) וַיֵּלֶךְ משֶׁה וַיָּשָׁב אֶל יֶתֶר חוֹתְנוֹ וְגו'. תָּא חֲזֵי, משֶׁה רָעֵי עָנָא דְיִתְרוֹ חָמוּי הֲוָה, וְדִיּוּרֵיהּ הֲוָה בֵּיהּ. וְכַד בָּעֵי לְמֵיזַל, לָא אֲזַל אֶלָּא בִּרְשׁוּתָא דִידֵיהּ. וְיַעֲקֹב דְּהֲוָה שְׁלִים וְדִיּוּרֵיהּ הֲוָה תָּדִיר עִמֵּיהּ דְּלָבָן, אַמַּאי לָא בָעָא רְשׁוּתָא מִנֵּיהּ. אֶלָּא הָא אִתְּמָר דְּלָא יְגַלְגֵּל לָבָן עִמֵּיהּ גִּלְגּוּלִין וְיִשְׁתָּאַר תַּמָּן. דְּהָא בְּקַדְמִיתָא אָמַר לֵיהּ, וּמִיָּד גִּלְגֵּל עֲלֵיהּ גִּלְגּוּלִין וְאִשְׁתָּאַר תַּמָּן, וְהַשְׁתָּא דָחִיל מִנֵּיהּ.","אֲבָל יִתְרוֹ, לָא הֲוָה הָכִי לְגַבֵּי משֶׁה. בְּגִין דְּלָבָן חָרָשָׁא הֲוָה, וּבְחָרָשָׁא הֲוָה כָּל עוֹבָדוֹי לְגַבֵּי דְיַעֲקֹב, וְהַשְׁתָּא לָא בָעָא יַעֲקֹב לְאִתְעַכְּבָא תַּמָּן, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ (בראשית ל״א:ג׳) שׁוּב אֶל אֶרֶץ אֲבוֹתֶיךָ וְגו'. וְעַל דָּא לָא בָעָא לְאִתְעַכְּבָא וּלְמִישְׁבַּק פִּקּוּדָא דְמָרֵיהּ.","תָּא חֲזֵי כְּתִיב, (בראשית ל׳:כ״ב) וַיִּזְכֹּר אֱלֹהִים אֶת רָחֵל וְגו', פָּתַח וְאָמַר, (תהילים מ״ו:א׳) לַמְנַצֵּחַ לִבְנֵי קֹרַח עַל עֲלָמוֹת שִׁיר. הַאי קְרָא, אִית לְאִסְתַּכָּלָא בֵּיהּ, דְּרָזָא דְּחָכְמְתָא אִיהוּ. וְכָל הַנֵּי שִׁירִין וְתוּשְׁבְּחָן, דְּהֲווּ אָמְרֵי בְּנֵי קֹרַח, כֻּלְּהוּ מֵחַדְתִּין אִינוּן שִׁירִין וְתוּשְׁבְּחָן דְּהֲווּ מִלְּקַדְּמִין, וְכֵן כָּל אִינוּן שִׁירִין וְתוּשְׁבְּחָן דְּאָמַר דָּוִד וְכָל אִינוּן דְּהֲווּ עִמֵּיהּ, כֻּלְּהוּ הֲווּ בְּרָזָא עִלָּאָה, בְּרָזָא דְחָכְמְתָא.","תָּא חֲזֵי, עֲבַד קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא תַּתָּאָה כְּגַוְונָא דְּעַלְמָא עִלָּאָה, וְכָל אִינוּן סִדְּרִין דְּסִדְּרוּ דָּוִד וּשְׁלֹמֹה בְּרֵיהּ, וְכָל אִינוּן נְבִיאֵי קְשׁוֹט כֻּלְּהוּ סִדְּרוּ כְּגַוְונָא דִלְעֵילָא."],[[0,"ובגין דא כלא חד וכו':","ומשום זה נעשה הכל אחד, דהיינו שב' הנוקבות נעשו פרצוף אחד, משום שהכל הוא מעולם העליון. פירוש, שמרחיב ביאור, ואומר הרי כל הסוד שנעשו ב' הנוקבות לאחד, הוא מטעם שנוקבא תחתונה שמחזה ולמטה נשלמה ונעשה לגמרי כמו נוקבא עלאה, ואם כן במצב זה רק הנוק' תחתונה רחל נתבטלה, שנעשה כמו העליונה, לאה, אבל העליונה עצמה לא נתבטלה, וע\"כ לא מתה לאה."],[0,"הכי נמי ובכל אתר וכו':","וכן הוא אשר בכל מקום, הן בשעת שלמות והן שלא בשעת שלמות, הם שני עולמות זה בנגלה וזה בנסתר, כלומר, שאפילו בעת שלמות, שרחל תופס כל קומתו דז\"א ואפילו מחזה ולמטה, יש ג\"כ ב' עולמות, אלא זה בפנימיות בהסתר, וזה בחיצוניות בגלוי, שמלבישים אשה על אחותה. ואין אנו מברכים לקב\"ה, אלא בשני עולמות, שכתוב ברוך ה' מן העולם ועד העולם, ומשום זה אנו קוראים את עולם העליון \u0003הוא,\u0004 שהוא לשון נסתר, ואנו קוראים את עולם התחתון בשם \u0003אתה,\u0004 שהוא לשון נכח ונגלה, משום שהוא ברוך מעולם העליון על ידי הצדיק, וז\"ש ברוך ה' מציון שוכן ירושלים וגו', כלומר משום שעולם התחתון מתברך בחסדים מעולם העליון, ע\"כ הוא נגלה לנו, ודאי הוא, כי מציון שהוא יסוד דעולם העליון הוא ברוך. וע\"כ מחויב עולם העליון להתקיים בבחינתו תמיד."],[1,"תא חזי כגוונא וכו':","בוא וראה, כעין זה, הוי\"ה הוי\"ה, שבתחילת י\"ג מדות, הם ב' עולמות זה בנגלה וזה בנסתר, שה\"ס ב' פאתי הראש, שהימנית הוא חסדים מכוסים, והשמאלית ה\"ס הארת חכמה המגולה. וע\"כ יש פסיק בין ב' הויות. ומעולם זה עד עולם זה הכל אחד, כי עולם הנגלה אין לו משלו כלום וכל מה שיש בו הוא מקבל מעולם הנסתר, כנ\"ל."],[2,"ויהי כאשר ילדה רחל וגו':","אמר ר' יהודה בוא נראה שלימותו של יעקב, שלא רצה ללכת, אלא ברשותו של לבן, ואם תאמר, בפעם האחרת, למה לא הלך ברשותו, כי ברח ממנו. ומשיב, אלא משום שיעקב היה מתירא, שלא יעזוב אותו ללכת ממנו, ויישלמו י\"ב השבטים בארץ נכריה, ועל כן כיון שראה יעקב. שהגיעה השעה ללידת בנימין, ברח, כמו שאתה אומר, ויברח הוא וכל אשר לו."],[3,"דכיון דאתיליד וכו':","כיון שנולד בנימין, נתקשרה השכינה דהיינו הנוקבא תתאה, בכל השבטים, משום שנעשתה פרצוף אחד עם הנוקבא עלאה, לאה, כנ\"ל, ונאחזה הנוקבא תתאה גם בששה בני לאה, וקבלה הבית בכל השבטים. \u0003בית,\u0004 פירושו המוחין דהארת חכמה, בסו\"ה בחכמה יבנה בית."],[3,"ויעקב הוה ידע וכו':","ויעקב היה יודע בסוד החכמה, כשיושלמו י\"ב השבטים השכינה תתקשט ותתקשר בהם, כלומר שתתקשט ע\"י במוחין דגדלות, ותתקשר בהם לפרצוף אחד עם הנוקבא עלאה שלמעלה מחזה כנ\"ל, ורחל תמות, כי תתבטלה (כנ\"ל דף צ\"ח ד\"ה פירוש) והשכינה תקבל הבית כמ\"ש שם."],[4,"תא חזי הכי אוליפנא וכו':","בוא וראה כך למדנו, עולם התחתון, שהוא השכינה, היה ראוי שתתחבר עם יעקב, כמו שהיה ראוי אל משה, אלא שלא יכלה מטרם שהיו י\"ב שבטים בבית להתקשר בהם, כיון שנשלמו י\"ב, אז נדחה רחל, והשכינה קבלה הבית בכל י\"ב השבטים, (כמ\"ש לעיל) ונעשה עקרת הבית. ואז נאמר מושיבי עקרת הבית, ודאי."],[5,"אמר יעקב הא וכו':","אמר יעקב, כבר הגיעה השעה, שיולד בנימין, ויושלמו י\"ב השבטים, ודאי, העולם שלמעלה, דהיינו הנוקבא שלמעלה מחזה, ירד כאן אל הבית להתקשר בהם, כלומר, שיתקשרו ב' הנוקבות להיות פרצוף אחד, ועניה זו, רחל, תהיה נדחית לפניו, כמ\"ש לעיל, אם תמות כאן, לא אצא עוד מכאן לעולם. ולא עוד אלא בארץ הזו אינו ראוי להשלים את הבית, אלא בארץ הקדושה, משום זה, ויהי כאשר ילדה וגו', דהיינו מטרם שנשלמו השבטים."],[6,"שמע ר\"ש וכו':","שמע ר\"ש, אמר, ודאי, כל דבריו של ר' יהודה טובים, ואלו, עולים על כולם. ואם תאמר למה לא הלך לדרכו מיד, אלא שעוד נתעכב ועבד שש שנים בצאן לבן. הוא משום, שכל עוד שרחל לא נתעברה עם בנימין, נתעכב שם, כיון שהגיעה השעה שנתעברה עם בנימין, ברח ולא בקש רשות מלבן, כדי שלא יתעכב שם, ויתחבר יעקב בכל השבטים במקום הצריך. דהיינו בארץ הקדושה."],[7,"ר' אבא פתח וכו':","רא\"פ וילך משה וישב אל יתר חותנו וגו'. בוא וראה, משה, היה רועה צאן יתרו חותנו, ומעונו היה אצלו, וכשרצה ללכת, לא הלך אלא ברשותו. ויעקב שהיה איש תם ומעונו היה תמיד אצל לבן, למה לא בקש רשות ממנו, כמו משה."],[7,"אלא הא אתמר וכו':","ומשיב, אלא למדנו, שע\"כ לא בקש רשות מלבן, מפחד, שלא יגלגל עליו גלגולים עד שישאר שם. כי מקודם לכן כבר אמר לו, שרוצה ללכת לביתו, ומיד גלגל עליו גלגולים, ונשאר שם, וע\"כ עתה היה מתירא ממנו, ולא בקש ממנו רשות."],[8,"אבל יתרו וכו':","אבל יתרו, לא היה כך לנגד משה, כי לבן היה מכשף, ובכשוף עשה כל מעשיו כנגד יעקב. ומשום שעתה לא רצה יעקב להתעכב שם, שהרי הקב\"ה אמר לו שוב אל ארץ אבותיך וגו', ולכן לא רצה להתעכב ולעזוב מצות רבונו. וע\"כ לא בקש רשות ממנו."],[9,"תא חזי כתיב ויזכור אלקים את רחל וגו':","פתח ואמר, למנצח לבני קרח על עלמות שיר. מקרא זה יש להסתכל בו, כי סוד החכמה הוא. וכל אלו שירות ותשבחות שבני קרח היו אומרים, כולם אינם חדשים, אלא חדשו שירות ותשבחות ישנות, שכבר היו מקודם לכן. וכן כל אלו שירות ותשבחות שאמר דוד, וכל אלו שהיו עמו, ששמותיחם נזכרים בראשי המזמורים שבתהלים, כולם היו בסוד העליון, שהיא בינה, בסוד החכמה."],[9,"","פירוש. המוחין נמשכים ומתפשטים בשירה. כי הטעמים נקודות תגין ואותיות שבשירה הם סדרי היחודים, שבדרכיהם מתפשטים המוחין. והשירים שבתהלים, הם סדרי יחודי המוחין שבעולם התחתון, שהוא הנוקבא דז\"א. ונודע, ששרשי המוחין בכל צורותיהם, הם בעולם העליון, בבינה, ומעולם העליון נמשכים אל עולם התחתון. ויש הפרש בין קו שמאל לשאר הקוין. כי הקו שמאל מקבלת הנוקבא מבינה עצמה, ולא מז\"א בעלה, והיינו בעת שהיא בסוד ב' מאורות הגדולים, (כנ\"ל דף צ' ד\"ה ושיעור ע\"ש) משא\"כ שאר הקוין היא מקבלת מז\"א בעלה, ולא מבינה. ונמצא שבקו שמאל של הנוקבא לא נעשה שום שינוי בעברו מן הבינה אל הנוקבא, משא\"כ שאר הקוין, משתנים הרבה בסבת העברתם לז\"א, שדרכו בחסדים מכוסים, שהנוקבא מוכרחת לקבל ממנו."],[9,"","וז\"ש \u0003וכל הני שירין ותושבחן דהוו אמרי בני קרח, כלהו מחדתין, אינון שירין ותושבחן דהוו מלקדמין.\u0004 כי שירת בני קרח, ה\"ס התפשטות הקו שמאל בנוקבא, אשר אין בו שום שינוי מסדר הארתו בבינה, אלא רק התחדשות שירת הבינה במקום הנוקבא יש כאן, ולא יותר. וע\"כ נבחנת שירתם כשירה ישנה המחודשת. משא\"כ שאר הקוין, הגם שנמשכים ג\"כ מבינה, מ\"מ יש בהם שינוים מפאת העברתם בז\"א. וז\"ש, \u0003וכן כל אינון שירין ותושבחן דאמר דוד וכל אינון דהוו עמיה, כלהו הוו ברזא עלאה ברזא דחכמתא\u0004 כלומר, שמשמיענו שאין הכונה לומר שרק שירת בני קרח היא מבינה ולא שירת דוד ושאר הזקנים שעמו, אלא \u0003וכן כל אינון שירין\u0004 וכו' הם מבינה. אלא שהם רק \u0003ברזא עלאה,\u0004 בסוד הבינה, אבל אינם שירת הבינה ממש, כי משתנים בעברם בז\"א. אבל שירת בני קרח לא משתנה כלום."],[10,"ת\"ח עבד קב\"ה וכו':","בוא וראה, עשה הקב\"ה את עולם התחתון, שהוא הנוקבא, כעין עולם העליון, שהוא בינה, להיותו מקבל ממנו כנ\"ל, וכל אלו הדברים שסדרו דוד ושלמה בנו, וכל אלו נביאי אמת, כולם סדרו בעולם התחתון, כעין של מעלה, בבינה."]],[[0,"","וּמִשּׁוּם כָּךְ הַכֹּל אֶחָד, שֶׁהֲרֵי הַכֹּל הוּא מִן הָעוֹלָם הָעֶלְיוֹן. כָּךְ גַּם, וּבְכָל מָקוֹם, שְׁנֵי עוֹלָמוֹת, זֶה בְּנִגְלֶה וְזֶה בְּנִסְתָּר, וְאָנוּ לֹא מְבָרְכִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא בִּשְׁנֵי עוֹלָמוֹת, שֶׁכָּתוּב בָּרוּךְ ה' אֱלֹהֵי יִשְׂרָאֵל מִן הָעוֹלָם וְעַד הָעוֹלָם. מִשּׁוּם כָּךְ לָעוֹלָם הָעֶלְיוֹן קוֹרְאִים הוּ\"א, וְלָעוֹלָם הַתַּחְתּוֹן קוֹרְאִים אַתָּ\"ה, מִשּׁוּם שֶׁהוּא בָּרוּךְ מִן הָעוֹלָם הָעֶלְיוֹן עַל יְדֵי הַצַּדִּיק. זֶהוּ שֶׁכָּתוּב בָּרוּךְ ה' מִצִּיּוֹן שֹׁכֵן יְרוּשָׁלם וְגוֹ'. וַדַּאי מִצִּיּוֹן הוּא בָּרוּךְ."],[1,"","בֹּא רְאֵה, כְּמוֹ כֵן ה' ה' שְׁנֵי עוֹלָמוֹת הֵם, זֶה בְּנִגְלֶה וְזֶה בְּנִסְתָּר, וְעַל כֵּן מַפְסִיק הַטַּעַם בְּתוֹכָם, וּמֵהָעוֹלָם הַזֶּה וְעַד הָעוֹלָם הַזֶּה הַכֹּל אֶחָד."],[2,"","וַיְהִי כַּאֲשֶׁר יָלְדָה רָחֵל אֶת יוֹסֵף וְגוֹ'. אָמַר רַבִּי יְהוּדָה, בּא רְאֵה הַשְּׁלֵמוּת שֶׁל יַעֲקֹב, שֶׁלֹּא רָצָה לָלֶכֶת אֶלָּא בִּרְשׁוּת לָבָן. וְאִם תֹּאמַר, לָמָּה לֹא הָלַךְ פַּעַם אַחֶרֶת בִּרְשׁוּתוֹ? אֶלָּא מִשּׁוּם שֶׁפָּחַד יַעֲקֹב שֶׁלֹּא יַעֲזֹב אוֹתוֹ וְיִשְׁתַּלְּמוּ שְׁנֵים עָשָׂר שְׁבָטִים בְּאֶרֶץ אַחֶרֶת, וְעַל כֵּן, כֵּיון שֶׁרָאָה שֶׁהִגִּיעָה שְׁעָתוֹ שֶׁל בִּנְיָמִין, בָּרַח, כְּמוֹ שֶׁנֶּאֱמַר וַיִּבְרַח הוּא וְכָל אֲשֶׁר לוֹ."],[3,"","שֶׁכֵּיוָן שֶׁנּוֹלַד בִּנְיָמִין, נִקְשְׁרָה הַשְּׁכִינָה בְּכָל הַשְּׁבָטִים וְנָטְלָה הַבַּיִת עִם כֻּלָּם. וְיַעֲקֹב הָיָה יוֹדֵעַ בְּסוֹד הַחָכְמָה, שֶׁכַּאֲשֶׁר יִשְׁתַּלְּמוּ שְׁנֵים עָשָׂר שְׁבָטִים, שֶׁהַשְּׁכִינָה תִּתְקַשֵּׁט וְתִתְקַשֵּׁר עִמָּם וְרָחֵל תָּמוּת, וְהִיא נוֹטֶלֶת אֶת הַבַּיִת."],[4,"","בֹּא רְאֵה, כָּךְ לָמַדְנוּ, הָעוֹלָם הַתַּחְתּוֹן נִרְאָה לְיַעֲקֹב כְּמוֹ שֶׁנִּרְאָה לְמֹשֶׁה, אֶלָּא שֶׁלֹּא יָכְלָה עַד שֶׁהָיוּ שְׁנֵים עָשָׂר שְׁבָטִים בַּבַּיִת לְהִתְקַשֵּׁר עִמָּם, וְאָז נִטְהֲרָה (נדחתה) רָחֵל, וְהִיא נָטְלָה אֶת הַבַּיִת בְּכָל הַשְּׁבָטִים וְהָיְתָה עִקַּר הַבַּיִת, וְאָז וַדַּאי מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת."],[5,"","אָמַר יַעֲקֹב, הִנֵּה הִגִּיעַ הַזְּמַן שֶׁנִּשְׁלְמוּ שְׁנֵים עָשָׂר הַשְּׁבָטִים, וַדַּאי יֵרֵד הָעוֹלָם שֶׁלְּמַעְלָה לַבַּיִת לְהִתְקַשֵּׁר עִמָּם, וְהַמִּסְכֵּנָה הַ את נִדְחֵית לְפָנָיו. אִם תָּמוּת כָּאן, לֹא אֵצֵא מִכָּאן לְעוֹלָמִים. וְלֹא עוֹד, אֶלָּא בָּאָרֶץ הַזּוֹ לֹא רָאוּי לְהַשְׁלִים אֶת הַבַּיִת. מִשּׁוּם כָּךְ וַיְהִי כַּאֲשֶׁר יָלְדָה וְגוֹ', טֶרֶם יִשְׁתַּלְּמוּ הַשְּׁבָטִים."],[6,"","שָׁמַע רַבִּי שִׁמְעוֹן וְאָמַר, וַדַּאי יָפִים הֵם כָּל דִּבְרֵי רַבִּי יְהוּדָה, וְזֶה עוֹלֶה עַל הַכֹּל. וְאִם תֹּאמַר, לָמָּה לֹא הָלַךְ לוֹ לְדַרְכּוֹ מִיָּד? אֶלָּא כָּל זְמַן שֶׁרָחֵל לֹא הִתְעַבְּרָה מִבִּנְיָמִין, הִתְעַכֵּב שָׁם. כֵּיוָן שֶׁהִגִּיעַ הַזְּמַן שֶׁל בִּנְיָמִין, בָּרַח וְלֹא בִקֵּשׁ רְשׁוּת, כְּדֵי שֶׁלֹּא יִתְעַכֵּב שָׁם, וְיִתְחַבֵּר יַעֲקֹב בְּכָל הַשְּׁבָטִים בְּמָקוֹם (שלא) שֶׁצָּרִיךְ."],[7,"","רַבִּי אַבָּא פָּתַח, וַיֵּלֶךְ מֹשֶׁה וַיָּשָׁב אֶל יֶתֶר חֹתְנוֹ וְגוֹ'. בּא רְאֵה, מֹשֶׁה הָיָה רוֹעֶה אֶת צֹאן חוֹתְנוֹ, וְדִיּוּרוֹ הָיָה עִמּוֹ. וּכְשֶׁרָצָה לָלֶכֶת, לֹא הָלַךְ אֶלָּא בִּרְשׁוּתוֹ. וְיַעֲקֹב, שֶׁהָיָה שָׁלֵם, וְדִיּוּרוֹ תָּמִיד הָיָה עִם לָבָן, לָמָּה לֹא בִקֵּשׁ מִמֶּנּוּ רְשׁוּת? אֶלָּא הֲרֵי נִתְבָּאֵר שֶׁלֹּא יְגַלְגֵּל לָבָן עִמּוֹ גִּלְגּוּלִים וְיִשָּׁאֵר שָׁם, שֶׁהֲרֵי בָּרִאשׁוֹנָה אָמַר לוֹ, וּמִיָּד גִּלְגֵּל עָלָיו גִּלְגּוּלִים וְנִשְׁאַר שָׁם, וְכָעֵת פָּחַד מִמֶּנּוּ."],[8,"","אֲבָל יִתְרוֹ לֹא הָיָה כָּךְ כְּלַפֵּי מֹשֶׁה, מִשּׁוּם שֶׁלָּבָן הָיָה מְכַשֵּׁף, וּבְכִשּׁוּף הָיָה כָּל מַעֲשֵׂהוּ כְּלַפֵּי יַעֲקֹב, וְכָעֵת לֹא רָצָה יַעֲקֹב לְהִתְעַכֵּב שָׁם, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לוֹ שׁוּב אֶל אֶרֶץ אֲבֹתֶיךְ וְגוֹ', וְעַל כֵּן"],[9,"","לֹא רָצָה לְהִתְעַכֵּב וְלַעֲזֹב אֶת מִצְוַת רִבּוֹנוֹ. בֹּא רְאֵה, כָּתוּב וַיִּזְכֹּר אֱלֹהִים אֶל רָחֵל וְגוֹ'. פָּתַח וְאָמַר, (תהלים מו) לַמְנַצֵּחַ לִבְנֵי קֹרַח עַל עֲלָמוֹת שִׁיר. בַּפָּסוּק הַזֶּה יֵשׁ לְהִסְתַּכֵּל שֶׁהוּא סוֹד שֶׁל חָכְמָה, וְכָל הַשִּׁירִים וְהַתִּשְׁבָּחוֹת הַלָּלוּ שֶׁהָיוּ אוֹמְרִים בְּנֵי קֹרַח, כֻּלָּם מְחַדְּשִׁים הֵם אוֹתָם שִׁירִים וְתִשְׁבָּחוֹת שֶׁהָיוּ מִלְּפָנִים, וְכֵן כָּל אוֹתָם שִׁירוֹת וְתִשְׁבָּחוֹת שֶׁאָמַר דָּוִד וְכָל אוֹתָם שֶׁהָיוּ עִמּוֹ, כֻּלָּם הָיוּ בְּסוֹד עֶלְיוֹן, בְּסוֹד הַחָכְמָה."],[10,"","בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת הָעוֹלָם הַתַּחְתּוֹן כְּמוֹ הָעוֹלָם הָעֶלְיוֹן, וְכָל אוֹתָם הַסְּדָרִים שֶׁסִּדְּרוּ דָּוִד וּשְׁלֹמֹה בְּנוֹ וְכָל אוֹתָם נְבִיאֵי הָאֱמֶת - כֻּלָּם סִדְּרוּ כְּמוֹ שֶׁלְּמַעְלָה."]]],[["תָּא חֲזֵי, כְּגַוְונָא דְאִיכָּא מִשְׁמָרוֹת בְּאַרְעָא, הָכִי נָמֵי בִּרְקִיעָא. דִּמְזַמְּרֵי לְמָרַיְיהוּ, וְאָמְרֵי שִׁירָתָא תָּדִיר. וְכֻלְּהוּ קָיְימִין אִלֵּין לָקֳבֵל אִלֵּין, וְכֹלָּא בְּסִדְּרָן דְּשִׁירִין וְתוּשְׁבְּחָן, וְהָא אוּקְמוּהָ חַבְרַיָיא.","עֲלָמוֹת שִׁיר, מַאי עֲלָמוֹת שִׁיר. אֶלָא כְּמָה דְאַתְּ אָמֵר, (שיר השירים ו׳:ח׳) שִׁשִּׁים הֵמָּה מְלָכוֹת וּשְׁמוֹנִים פִּלַגְשִׁים וַעֲלָמוֹת אֵין מִסְפָּר. מַאי וַעֲלָמוֹת אֵין מִסְפָּר. כְּמָה דְאַתְּ אָמֵר (איוב כ״ה:ג׳) הֲיֵשׁ מִסְפָּר לִגְדוּדָיו. וּבְגִין דְּלֵית לוֹן חוּשְׁבְּנָא, כְּתִיב וַעֲלָמוֹת אֵין מִסְפָּר.","וְכֻלְּהוּ שׁוּרִין שׁוּרִין, מְסַחֲרָן סְדָרִין, אִלֵּין לָקֳבֵיל אִלֵּין, לְזַמְּרָא וּלְשַׁבָּחָא לְמָרֵיהוֹן, וְאִלֵּין אִינוּן עֲלָמוֹת שִׁיר. וּבְגִין דְּאִית עֲלָמוֹת דְּלָא מְזַמְּרִין כְּאִלֵּין, אִלֵּין אִקְרוּן עֲלָמוֹת שִׁיר.","תְּלַת (נדפס פקודי רכ\"ח ע\"א) סִדְּרִין מִתְפָּרְשָׁן לְכָל סְטַר לְד' סִטְרֵי עַלְמָא, וּבְכָל סִדְּרָא וְסִדְּרָא דְּאִיהִי לְכָל סְטַר, תְּלַת סִדְּרִין אָחֳרָנִין. סִדְּרָא קַדְמָאָה דְלִסְטַר מִזְרָח, תְּלַת סִדְרִין אִינוּן. וְאִינוּן תִּשְׁעָה סִדְּרִין, בְּגִין דְּכָל סִדְּרָא מֵאִינוּן תְּלַת, אִית לֵיהּ תְּלַת סִדְּרִין, וְאִשְׁתַּכָּחוּ דְּאִינוּן תִּשְׁעָה, וְכַמָּה אֶלֶף וְרִבְבָן תְּחוֹתַיְיהוּ.","הַנֵּי סִדְּרִין תִּשְׁעָה, כּוּלְהוּ מִתְנַהֲגֵי בְּאַתְוָון רְשִׁימָן, וְכָל סִדְּרָא אִסְתְּכֵי לְאִינוּן אַתְוָון רְשִׁימָן, (ס\"א והא אוקמוה וכן לכל סדרא וסדרא, וכלהו נטלי באתוון רשימין ואלין עלאי מאלין וקיימאן אלין על אלין) וּמִתְחַבְּרָן כֻּלְּהוּ, וְאָמְרֵי שִׁירָתָא. וְכַד אִינוּן אַתְוָון פָּרְחֵי גּוֹ אֲוִירָא דְּרוּחָא (ההוא) דִּמְמַנָּא עַל כֹּלָּא, כְּדֵין אִינוּן נָטְלֵי, וְשִׁירָתָא אִתְבַּסַּם, וְחַד אָת אִתְבַּטַּשׁ מִתַּתָּא. וְהַהוּא אָת סָלְקָא וְנָחֲתָא וּתְרֵין אַתְוָון פָּרְחֵי עֲלַיְיהוּ, וְהַאי אָת מִתַּתָּא, סָלְקָא סִדְּרָא מִתַּתָּא לְעֵילָא וְאִתְחַבַּר בְּהוּ, וְאִתְעֲבִידוּ תְּלַת אַתְוָון, כֻּלְּהוּ לְפוּם אַתְוָון יה\"ו, דְּאִינוּן תְּלַת גּוֹ אַסְפַּקְלַרְיָא הַמְאִירָה. מֵאִילֵּין אִתְפָּרְשׁוּ תְּלַת סִדְּרִין וְאִינוּן תְּרֵין אָתְוָון, וְהַהוּא אָת דְּסָלְקָא, מִתְחַבְּרָא עִמְּהוֹן וְאִינוּן תְּלַת.","תָּא חֲזֵי, אִינוּן תְּרֵין אָתְוָון עִלָּאִין, דְּסָלְקִין בַּאֲוִירָא, אִינוּן כְּלִילָן דָּא בְּדָא, רַחֲמֲי בְּדִינָא. וּבְגִין כָּךְ אִינוּן תְּרֵין, וְאִינוּן מֵעַלְמָא עִלָּאָה בְּרָזָא דִדְכוּרָא, וְהַאי דְסַלְקָא וְאִתְחַבְּרָא עִמְּהוֹן אִיהִי נוּקְבָא, וְאִתְכְּלִילַת בְּתַרְוַויְיהוּ. כְּגַוְונָא דְּנוּקְבָא אִתְכְּלִילַת בִּתְרֵי סִטְרֵי, בִּימִינָא וּבִשְׂמָאלָא, וְאִתְחַבְּרַת בְּהוּ, הָכִי נָמֵי הַאי אָת נוּקְבָא, דְּאִתְחַבְּרַת בִּתְרֵי אַתְוָון אָחֳרָנִין, וְאִינוּן בִּתְרֵין סִטְרִין, אִלֵּין עִלָּאִין, וְדָא לְתַתָּא, וְכֹלָּא אִיהוּ חַד, דְּכַר וְנוּקְבָא. (בר) דְּכַד אִתְבְּרֵי עַלְמָא, דְּאִינוּן אַתְוָון מֵעַלְמָא עִלָּאָה נִינְהוּ, דְּאִינוּן אוֹלִידוּ כָּל עוֹבָדִין לְתַתָּא, כְּגַוְּונָא דִּלְהוֹן מַמָּשׁ, וּבְגִין כָּךְ מַאן דְּיָדַע לוֹן וְאִזְדְּהַר בְּהוּ, רָחִים לְעֵילָא וּרָחִים לְתַתָּא.","רִבִּי שִׁמְעוֹן אָמַר, אִלֵּין אַתְוָון כֻּלְּהוּ, דְּכַר וְנוּקְבָא, לְאִתְכְּלָלָא כְּחֲדָא בְּרָזָא דְּמַיִין עִלָּאִין וּמַיִין תַּתָּאִין, וְכֹלָּא חַד, וְדָא אִיהוּ יִחוּדָא שְׁלִים. וּבְגִין כָּךְ, מַאן דְּיָדַע לְהוּ, וְאִזְדְּהַר בְּהוּ, זַכָּאָה אִיהוּ חוּלָקֵיהּ בְּהַאי עָלְמָא וּבְעַלְמָא דְאָתֵי, בְּגִין דְּאִיהוּ עִקָּרָא דְּיִחוּדָא שְׁלִים כְּדְקָא יְאוּת. תְּלַת תְּלַת מִסִּטְרָא דָא וּמִסִּטְרָא דָא, בְּיִחוּדָא חָדָא בִּשְׁלִימוּ דְּכֹלָּא. וְכֻלְּהוּ רָזָא דְסִדְּרָא עִלָּאָה כְּדְקָא חָזֵי, כְּגַוְונָא דִלְעֵילָא, דְּהַהוּא סִדְּרָא תְּלַת תְּלַת בְּרָזָא חָדָא.","סִדְּרָא תִּנְיָינָא דְּלִסְטַר דָּרוֹם, תְּלַת סִדְּרִין אִינוּן לְהַהוּא סִטְרָא. וְכָל סִדְּרָא וְסִדְּרָא תְּלַת תְּלַת, וְאִינוּן תִּשְׁעָה, כְּמָה דְאִתְּמָר. וְאַתְוָון אִתְפְּלָגוּ הָכִי. לְכָל סִטְרֵי, לְאִתְחַבְּרָא כֹּלָּא כְּחַד, בְּגִין דְּאִית אַתְוָון בְּרָזָא דְנוּקְבָא, וְאַתְוָון בְּרָזָא דִדְכוּרָא, וְאִתְחַבָּרוּ כֻּלְּהוּ כְּחֲדָא, וְהֲווּ חַד בְּרָזָא דִשְׁמָא קַדִּישָׁא שְׁלִים. וּלְגַבַּיְיהוּ סִדְּרִין מְמַנָּן תְּלַת תְּלַת, כְּמָה דְאִתְּמָר. וְכֹלָּא נַפְקָא מִסִּדְּרָא דְּאֲבָהָן דִּלְעֵילָא, כְּסִדְּרָא דְּאִתְתַּקְּנָא אַתְוָון דִּשְׁמָא קַדִּישָׁא יה\"ו, כְּמָה דְאִתְּמָר. הַנֵּי סִדְּרִין כֻּלְּהוּ, מִתְנַהֲגֵי בְּאִלֵּין אַתְוָון יְדִיעָן, וְנַטְלֵי בְּהוּ, וְכַמָּה חֵילִין וְרִבְוָון כֻּלְּהוּ לְתַתָּא, דְּנָטְלֵי וְאִתְנַהֲגֵי בְּסִדְּרָא דָא.","סִדְּרָא תְּלִיתָאָה דְּלִסְטַר צָפוֹן, בִּתְלַת סִדְּרִין אִינוּן לְהַהוּא סִטְרָא, וְאִינוּן תִּשְׁעָה. וּבִתְלַת סִטְרִין תְּלַת תְּלַת לְכָל סְטַר אִינוּן תִּשְׁעָה, וְאִינוּן סִדְרִין מִתְּלַת סִטְרִין כְּמָה דְאִתְּמָר."],[[0,"ת\"ח כגוונא וכו':","בוא וראה, כמו שיש משמרות בארץ, שי\"ב שעות הלילה, מתחלקות על ג' פעמים ארבע, יש גם כן ברקיע, שג' כתות מלאכים מזמרים בהם לרבונם, ואומרים בהם שירה תמיד. וכולם עומדים אלו מעל אלו, דהיינו לפי סדר מדרגתם, בסו\"ה גבוה מעל גבוה שומר עליהם. וכולם הם במערכות של שירים ותשבחות. שכל כתה משוררת לפי מדרגתה. וכבר בארוהו החברים."],[1,"עלמות שיר:","שואל, מהו עלמות שיר. ומשיב, הוא, כמו שאתה אומר, ששים המה מלכות ושמונים פלגשים ועלמות אין מספר. מהו עלמות אין מספר. הוא, כמו שאתה אומר, היש מספר לגדודיו, ומשום שהם בלי מספר לכן כתוב, ועלמות אין מספר."],[1,"","פירוש. \u0003מספר,\u0004 פירושו המוחין דהארת חכמה. בסו\"ה השמים מספרים וגו', \u0003בלי מספר\u0004 ה\"ס מוחין דאור החסדים. (כנ\"ל בהקדמת ספר הזהר דף כ\"ט ד\"ה במספר ע\"ש) וז\"ש \u0003ובגין דלית לון חושבנא,\u0004 דהיינו שהם בבחינת מוחין דאור החסדים הנבחנים לבלי מספר, ע\"כ כתוב ועלמות אין מספר, כי השם \u0003עלמות\u0004 יורה לשון העלם, דהיינו שהם חסדים מכוסים ואין בהם הארת החכמה, ולכן כתוב בהם \u0003אין מספר,\u0004 להורות על מוחין דאור החסדים שבהם. וכן \u0003עלמות שיר,\u0004 יורה על מוחין של אור החסדים שבהם."],[2,"וכלהו שורין שורין וכו':","וכולם, שורות שורות מסתדרים במערכות אלה לעומת אלה, לזמר ולשבח לרבונם. ואלה הם \u0003עלמות שיר\u0004 שבכתוב הנזכר, ומשום שיש \u0003עלמות\u0004 שאינם מזמרים כמו אלה, לכן נקראים אלה, \u0003עלמות שיר.\u0004"],[2,"","פירוש. כי שירה וזמרה נוהגת בעיקר במדרגות הנמשכות מהארת חכמה מקו שמאל, אמנם אין הארת חכמה מאירה בלי התלבשות בחסדים, ומשום זה נוהגת שירה גם באור החסדים הנכללים מהארת חכמה, ולפיכך יש ב' מיני \u0003עלמות,\u0004 שהם אור החסדים כנ\"ל. א) הנכללות מחכמה, והן העלמות שיר של בני קרח. ב) שאינן נכללות בחכמה, ובהן אינה נוהגת שירה, ונקראות עלמות סתם."],[3,"תלת סדרין מתפרשן וכו':","ג' מערכות מתחלקות לכל רוח, מן ד' רוחות העולם, ובכל מערכה ומערכה שבכל רוח, יש שלש מערכות אחרות. באופן, אשר למערכה הראשונה שברוח מזרח, יש שלש מערכות והן תשע, משום שבכל מערכה מאלו השלש, יש שלש מערכות, ונמצא שהן תשע. וכן בשאר ג' רוחות העולם, יש תשע בכל אחד. וכמה אלף ורבבות תחתיהם. הגם שמאמר הזה נדפס בפרשת פקודי דף מ\"ז אות קל\"ב ושם מקומו ולא כאן. עכ\"ז כיון שנדפס לפנינו, אבארו כאן. וחסר כאן תחילת המאמר, וז\"ל, ורזא דיליה דמשכנא, בתלת תלת באילן מתכן, שהם זהב וכסף ונחשת, ובשארא, ארבע, כגון תכלת וארגמן, ותולעת שני ושש, וכגון ארבעה טורי אבן. \u0003אמר ר' יהודה מנהון בתלת, מנהון בארבע מנהון בתרין, מנהון בחד, אבל כל סדרא וסדרא לאו איהו אלא בתלת.\u0004 תלת סדרין אינון, וכו' כמו שנדפס כאן."],[3,"","וביאור הדברים. ד' רוחות העולם ה\"ס חו\"ב תו\"מ. ואף על פי שנכללים זה מזה, והיה צריך להיות בכל אחד מהם חו\"ב תו\"מ, מכל מקום, אין שם רק חו\"ב ות\"ת בכל אחד, ומלכות חסרה, ואפילו ברוח מערב, שהוא מלכות, אין שם אלא חו\"ב ות\"ת, ובחינתה עצמה שהיא מלכות חסרה בה. והטעם היא, כי מלכות נמתקה בבינה, ונחשבת משום זה כבחינת מלכות דבינה שהיא בחינת עטרת יסוד, ומלכות עצמה נעלמה מכח מיתוק הזה. (כנ\"ל ב\"א דף פ\"ה ד\"ה ביאור ע\"ש.) ולפיכך הגם שיש ארבע רוחות שהם חו\"ב תו\"מ, מ\"מ רוח מערב שהיא מלכות אינו אלא בחינת עטרת יסוד שהיא בחינת ת\"ת ולא מלכות. וכשנכללים זה מזה אין בכל אחד אלא ג' שהם חו\"ב ות\"ת, ואפילו ברוח מערב אין שם אלא ג' שהם חו\"ב ות\"ת."],[3,"","וז\"ש, \u0003תלת סדרין מתפרשן לכל סטר לד' סדרי עלמא,\u0004 דהיינו אפילו לרוח מערב, שהיא מלכות, ויש ד' סדרים. אבל, \u0003ובכל סדרא וסדרא דאיהו לכל סטר, תלת סדרין אחרנין,\u0004 ולא ארבעה, כי עצם המלכות חסרה, והרוח מערב הוא רק מלכות הממותקת בבינה, ולא מלכות עצמה. ולפיכך נבחנות ב' מיני התכללות הספירות זב\"ז. א) שחו\"ב תו\"מ נכללים זה בזה והם י\"ב ולא ט\"ז. ואינה התכללות גמורה, כי צריך להיות כאן ט\"ז, וע\"כ צריכים להתכללות ב', אשר הג' שבכל רוח יתכללו ג\"כ זב\"ז ונעשה ג' בכל אחד, שהם תשע בכל רוח, וז\"ש \u0003ואינון תשעה סדרין בגין דכל סדרא מאינון תלת אית ליה תלת סדרין,\u0004 דהיינו התכללות הב' שהוא התכללות גמור, וכולו רחמים, שאין שם אפילו התכללות מרוח מערב."],[3,"","ועם כל זה מכח התקונים והמוחין של מספר י\"ב הנ\"ל שמלכות חסרה מבחינתה עצמה, מ\"מ מקבלת תיקונה מהם. וז\"ש \u0003וכמה אלף ורבוון תחותייהו,\u0004 כי הארות החכמה, הנמשכות מישסו\"ת נבחנות לאלף, כי \u0003י'\u0004 ספירותיהם הן במספר אלף. והארות החסדים הנמשכות מאו\"א עלאין נבחנות לרבבות, כי \u0003י'\u0004 ספירותיהם הן במספר רבבה. וכנגדם יש קליפות לעומת בחינת אלף. והם נאחזים במלכות הממותקת, שה\"ס עטרת יסוד, הראויה למוחין \u0003דאלף.\u0004 ויש קליפות לעומת בחינת \u0003רבבה,\u0004 שהם נאחזים במלכות הבלתי ממותקת, דהייני בעצם המלכות. וזסו\"ה \u0003יפול מצדך אלף,\u0004 דהיינו על ידי המוחין דהארת חכמה הנמשכים מישסו\"ת, שהם בבחינת אלף, והם נמשכים מקו שמאל בעיקר, שז\"ס מצדך, שפירושו, מצד שמאל, \u0003ורבבה\u0004 מימינך אליך לא יגש, דהיינו על ידי המוחין דחסדים הנמשכים מאו\"א עלאין, שהם בבחינת רבבה, נצלים מן הקליפות, שהם בבחינת רבבה, ואינם מניחים אותם להתקרב אל האדם. והם נמשכים מקו ימין, ועל כן אומר \u0003מימינך.\u0004 ואלו הקליפות דרבבה חזקות הן, ואי אפשר להפילן כמו הקליפות שבבחינת אלף, וע\"כ אינו אומר עליהן, אלא, \u0003אליך לא יגש.\u0004 כי אי אפשר להפילן מטרם גמר התקון. וז\"ש \u0003וכמה אלף ורבוון תחותייהו,\u0004 דהיינו ב' בחינת הארות הנ\"ל המפילים הקליפות דאלף, ומרחיקים הקליפות דרבבה. ונמצא שמגיע תקון גם לעצם המלכות החסרה בסוד המספר י\"ב, דהיינו בשיעור שמרחיקים הקליפות דבחינת רבבה."],[4,"הני סדרין תשעה וכו':","אלו תשעה הסדרים מתנהגים כולם באותיות רשומות, כלומר באותיות מסוימות, וכל סדר מסתכל דהיינו לקבל שפע, לאלו אותיות רשומות המתיחסות אליו. וכאשר אלו האותיות פורחות באויר של רוח ההוא הממונה על הכל, אז הן נוסעות, ואות אחת מלמטה מקבלת הכאה, והאות עולה ויורדת, ושתי אותיות פורחות עליו. ואות הזה שלמטה מעלה את הסדר ממטה למעלה ומתחברת בהם, בב' אותיות הפורחות, ונעשו שלש אותיות, שכולן הם על פי האותיות יה\"ו, שהן שלש בתוך המראה המאירה, שהוא ז\"א, מאלו יה\"ו מתחלקים שלשה סדרים, שהן שתי אותיות והאות העולה ומתחברת עמהן, שהן שלש."],[4,"","ביאור הדברים. כי נתבאר, שתשעה הסדרים שבכל רוח, הם חו\"ב ות\"ת שבכל אחד מהם חו\"ב ות\"ת. ואומר, שהם מתנהגים באותיות מסוימות, דהיינו על פי תקון קוין. כי נקודות הן בבינה, ואותיות בזו\"ן, וע\"כ סוד ג' הקוין שבבינה נקראים ג' נקודות: חולם שורק חירק, ובזו\"ן הם ג' אותיות."],[4,"","וז\"ש \u0003הני סדרין תשעה,\u0004 שהם חו\"ב ות\"ת שבכל אחד מהם חו\"ב ות\"ת, \u0003כולהו מתנהגי באתוון רשימן\u0004 שהם ג' אותיות בבחי' ימין שמאל אמצע, הנמשכות מג' נקודות שבבינה חולם שורק חירק, \u0003וכל סדרא אסתכי לאינון אתוון רשימן,\u0004 שכל סדר וסדר שבט' סדרים מסתכל, דהיינו שמקבל מאות אחת שבג' אותיות, ימין שמאל אמצע, הללו, המיוחסת אליו, אם מימין שבימין אם משמאל שבימין אם מאמצע שבימין, או מימין שבשמאל, וכו' עד\"ז, ועתה מבאר ג' האותיות מה טיבן. ואומר, \u0003וכד אינון אתוון פרחי וכו',\u0004 והיינו אות הימין ואות השמאל, שהן נמשכות מב' נקודות שבבינה, חולם שורק, שבעת שה \u0003י'\u0004 נכנסת ב \u0003אור\u0004 הבינה והאור נעשה ל \u0003אויר\u0004 נפלו ממנה אותיות \u0003אל\"ה\u0004 דאלקים לזו\"ן, והיא נשארה באותיות \u0003מ\"י\u0004 דאלקים, שה\"ס נקודת החולם, וחסדים, ושורש הימין. ואחר כך שיצאה ה \u0003י' מאויר\u0004 הבינה, ואותיות \u0003אל\"ה\u0004 חזרו אליה, נעשו אותיות אל\"ה אז לשורש השמאל, וחכמה בלי חסדים, וה\"ס נקודת השורק. ואז נמצאים ב' הקוין מ\"י, אל\"ה, שהם במחלוקת שזה כולו חסדים וזה כולו חכמה, וכל אחד רוצה לבטל את הארת חבירו, (כנ\"ל ב\"א דף נ\"ו ד\"ה כד) ונמצאים מחמת זה, שהם מטולטלים מדין לרחמים ומרחמים לדין, כי בהתגבר קו השמאל שהוא אותיות אל\"ה מתחזק הדין לשלוט. ובהתגבר קו הימין, שהוא אותיות \u0003מ\"י\u0004 מתחזקים הרחמים לשלוט, דהיינו החסדים שבימין. ולפיכך אע\"פ שכבר יצאה ה \u0003י' מאויר,\u0004 נבחנים עוד ב' הקוין שנמצאים ב \u0003אויר,\u0004 שפירושו ו\"ק, דהיינו קומת רוח. להיותם מטולטלים ואינם מאירים."],[4,"","וז\"ש \u0003וכד אינון אתוון פרחי גו אוירא\u0004 דהיינו אות הימין הנמשכת מ \u0003מ\"י,\u0004 ואות השמאל הנמשכת מ \u0003אל\"ה,\u0004 מטרם ביאת קו אמצעי, שהם פורחים ב \u0003אויר, דרוחא ההוא דממנא על כלא,\u0004 דהיינו באויר דבינה, שהוא ממונה על כל המוחין שבעולמות. כלומר שכל המוחים נמשכים ממנה. כי שורש הפריחה באויר, שפירושו מחלוקת הימין והשמאל, הוא שם בבינה, שבשעה שמתגבר השמאל יוצאת ה \u0003י'\u0004 מאויר, ובשעה שמתגבר הימין חוזרת ונכנסת ה \u0003י'\u0004 באור ונעשה אויר. וז\"ש \u0003כדין אינון נטלי,\u0004 שאז הם נוסעות, כלומר שמטולטלות פעם לימין ורחמים, ופעם לשמאל ודין."],[4,"","ונודע שכדי להכריע בין ימין ושמאל וליחדם זה בזה, נעשה ז\"א לבחינת מ\"ן בבינה, כי עלה אליה, עם אותיות אל\"ה שהוא דבוק בהם, (כנ\"ל דף י\"ט ד\"ה וז\"ש) ואז נעשה זווג דהכאה מאור העליון על המסך דז\"א, ויוצאת קומת חסדים המכריע ומיחד ב' הקוין מ\"י אל\"ה זה בזה, ונשתלם אז השם אלקים בשלמות. וה\"ס נקודת החירק, וקו אמצעי."],[4,"","וזה אמרו. \u0003וחד את,\u0004 דהיינו אות הנמשך מנקודת החירק שבבינה, \u0003אתבטש מתתא\u0004 שנעשה בו זווג הכאה, והוא מלמטה, דהיינו מז\"א שעלה אל הבינה בבחינת מיין נוקבין, וכן בכל המדרגות נבחן קו אמצעי שבא מן המדרגה התחתונה, בסוד מ\"ן, דהיינו שהתחתון עולה תמיד עם אח\"פ דעליון הדבוק בהם, ונעשה שם לקו אמצעי (כנ\"ל דף י\"ט ד\"ה ונודע) וז\"ש \u0003וההוא את סלקא ונחתא ותרין אתוון פרחי עלייהו,\u0004 שאותו אות האמצעי עולה מלמטה, ומכריע ב' הקוין שבעליון, וב' אותיות שבעליון פורחים עליו, כלומר, שעושה שלום ביניהם. כי מקיים הארת שניהם, דהיינו שהשמאל יאיר ממטה למעלה, והימין ממעלה למטה, (כנ\"ל ב\"א דף ס' ד\"ה מחלוקת) וז\"ש \u0003והאי את מתתא סלקא סדרא מתתא לעילא\u0004 שהאות הבא מלמטה, מעלה את הסדר, דהיינו הארת השמאל, שיאיר ממטה למעלה. \u0003ואתחבר בהו ואתעבידו תלת אתוון,\u0004 שהאות הבאה מלמטה בסוד מ\"ן מתחבר בב' אותיות עליונות, באות הימין ואות השמאל, ונעשו ג' אותיות: ימין, שמאל, אמצע, \u0003כלהו לפום אתוון יה\"ו, דאינון תלת גו אספקלריא המאירה.\u0004 פירוש, יה\"ו שבגו אספקלריא המאירה, ה\"ס חג\"ת דז\"א, והיינו ג' קוין שבו. ואומר שאלו ג' אותיות שבכאן, דהיינו במשכן, שהוא הנוקבא, נמשכות ומתנהגות לפי ג' הקוין שבז\"א שה\"ס יה\"ו. \u0003מאלין אתפרשו תלת סדרין\u0004 מאלו יה\"ו נמשכים ג' סדדים, דהיינו ג' קוין, \u0003ואינון, תרין אתוון,\u0004 אות הימין ואות השמאל, \u0003וההוא את דסלקא,\u0004 שהיא אות אמצעי \u0003מתחברא עמהון,\u0004 מתחברת עם השתים, \u0003ואינון תלת,\u0004 והם שלש בסוד יהיו דז\"א."],[4,"","ובדברים הללו, כבר הספיק רבי יהודה לבאר דבריו, שאמר בראש המאמר. כי סדרי מלאכת המשכן מתחלקים: \u0003מנהון בתלת,\u0004 היינו כנגד חו\"ב ות\"ת, הכלול בכל רוח. \u0003מנהון בארבע,\u0004 היינו כנגד ד' רוחות חו\"ב תו\"מ. דהיינו כמ\"ש לעיל בסוד י\"ב שד' רוחות הן חו\"ב תו\"מ, הנכללים זה בזה, ובכל אחד מהם רק ג' לבד, חו\"ב ות\"ת, וחסר מלכות. \u0003מנהון בתרין,\u0004 היינו כנגד ב' אותיות, ימין ושמאל שבנוקבא, הנמשכות מחולם שורק כנ\"ל, \u0003מנהון בחד,\u0004 היינו כנגד אות האמצעי הבא מלמטה מנוקבא, שנמשך בסוד החירק, ונעשה בה מ\"ן שעליו יוצא זווג דהכאה, המוציא קומת רוח ומכריע ומייחד הימין והשמאל זה בזה. אמנם צריך עוד להמשיך הביאור בענין ג' הקוין, לבאר מה שאמר ענין תשעה סדרין בכל רוח וכו', שיתבאר לפנינו."],[5,"ותא חזי אינון תרין וכו':","בוא וראה, אלו ב' אותיות העליונות העולים באויר, שהן אות הימין ואות השמאל, הם כלולים זה בזה, רחמים בדין. כי אות הימין ה\"ס חסדים ורחמים, ואות השמאל הוא חכמה בלי חסדים ודין, ומשום הפכיותם הם נבחנים לשתים. והן מעולם העליון בסוד הזכר. ואות הזו העולה ומתחברת עמהם, דהיינו אות האמצעי, היא נוקבא, כי על המסך שבה, נעשה הזווג דהכאה כנ\"ל. והיא נכללת בשתיהן, כלומר שב' האותיות ימין ושמאל מתחברים באות האמצעי ונעשה בה עצמה ג' אותיות ימין ושמאל ואמצע, כי כמו שהנוקבא בכללה נכללת מב' צדדים ימין ושמאל, שמקבלת מז\"א בסו\"ה שמאלו תחת לראשי וימינו תחבקני, ומתחברת בהם, כן אות האמצעי שהיא נוקבא, היא מתחברת בב' אותיות האחרות, והם נעשו באות האמצעי לב' צדדים ימין ושמאל, ב' האותיות שבה נעשו לעליונות, והיא עצמה למטה מהן וכל ג' האותיות נעשו אחד: זכר ונקבה, כלומר, שנעשו אחד בסוד הזווג כמו זכר ונקבה. שב' אותיות העליונות הן זכר, ואות האמצעית ה\"ס נקבה. כי כשנברא העולם, דהיינו בעת שיצאו ג' קוין בבינה כדי לברוא העולם, שהוא זו\"ן היו אלו ב' אותיות הימנית והשמאלית, מעולם העליון, מן בינה, והן הולידו כל הפעולות שלמטה בצורה שלהם ממש. ולא קו האמצעי שבבינה, ולפיכך נבחנות ב' אותיות הללו לזכרים ומשום זה, כל מי שמשיג אותם ונזהר בהם, אהוב הוא למעלה ואהוב הוא למטה."],[5,"","פירוש. כי בריאת העולם שהוא זו\"ן, נעשה ע\"י עלית זו\"ן למ\"ן לב' קוין ימין ושמאל שבבינה, ונעשה שם לקו אמצעי, ואז קבל כל המוחין שבבינה, בסוד תלת נפקי מחד חד בתלת קיימא. (כנ\"ל ב\"א דף רפ\"ז אות שס\"ג ע\"ש) ונמצא שרק ב' הקוין ימין ושמאל שבבינה הם המשפיעים המוחין כולם אל זו\"ן כי קו אמצעי דבינה היא בחינת זו\"ן עצמם. הרי שבריאת העולם היתה ע\"י ב' אותיות ימין ושמאל בלבדן, ועל כן נבחנות לזכרים. והאמצעית לנקבה."],[6,"רבי שמעון אמר וכו':","רש\"א, אלו האותיות כולם, דהיינו כל כ\"ז אותיות שבאלפא ביתא, הם זכר ונקבה להתכלל זה בזה כאחד. שהאותיות השייכות לימין ושמאל הן זכרים והשייכות לקו אמצעי הן נקבות כמ\"ש לעיל, וכמ\"ש להלן (באות רס\"ה) בסוד מים עליונים ומים נקבות, שאותיות הזכרים משפיעות מים עליונים, ואותיות הנקבות מעלות מ\"ן, ומתחבר הכל ונעשה אחד. וזה הוא יחוד השלם. ועל כן מי שיודע את היחודים ההם, ונזהר לכוון אותם, אשרי חלקו בעולם הזה ובעולם הבא. כי הוא עיקר יחוד השלם כראוי, שלש שלש, שהאותיות מתחלקות לקבוצות של שלש שלש, ב' זכרים למעלה ונוקבא אחת למטה. מצד זה ומצד זה ביחוד אחד, דהיינו שהימין והשמאל יתיחדו כאחד, בהאמצעי שהוא שלמות הכל, וכולם, דהיינו כל הקבוצות של שלוש, שבאלפא ביתא, הם סוד סדר העליון כראוי, כעין שהוא למעלה, בבינה, שסדר ההוא הוא שם שלש שלש בסוד אחד. פירוש. כי בעת שיצאו ג' קוין השורשיים בבינה, נכללו זה מזה, ונעשו בה ג' קבוצות של ג' קוין. ולפיכך גם כ\"ז האותיות שבנוקבא, מתחלקות אחריהם לקבוצות של ג' אותיות."],[7,"סדרא תניינא דלסטר דרום וכו':","אחר שנתבאר תשעה הסדרים שבמערכה הראשונה לרוח מזרח, שהוא ת\"ת, מבאר עתה מערכה השניה של רוח דרום, שהוא חסד, ששלשה סדרים הם לרוח ההוא, שבכל סדר וסדר שלש שלש, והם ט' סדרים, כמו שנתבאר לעיל (באות רנ\"ח) ברוח מזרח. וכולם יוצאים מסדר האבות, דהיינו ג' הקוין, שלמעלה, שבבינה, המכונים אברהם יצחק יעקב, כהסדר שנתקנו האותיות יה\"ו שבשם הקדוש, כמו שנתבאר (לעיל באות רנ\"ט ברות מזרח) אלו ט' הסדרים כולם מתנהגים באלו אותיות הידועות דהיינו ג' קבוצות של ג' אותיות ימין ושמאל אמצע, כנ\"ל ברוח מזרח, ונוסעות בהם, וכמה צבאות ורבבות מלאכים, שהם למטה בבי\"ע, נוסעים ומתנהגים בסדר הזה, שלרוח דרום."],[8,"סדרא תליתאה דלסטר צפון וכו':","מערכה השלישית שלרוח צפון, שהוא גבורה, שלשה סדרים הם לרוח ההוא, שהם תשעה. כי בשלשה הסדרים יש ג' ג' לכל צד והם תשעה. ואלו ט' הסדרים הם מג' צדדים ימין שמאל אמצע, כמו שנתבאר. לעיל (באות רנ\"ט) ברוח מזרח. והם סוד זכרים ונקבות הכל כמ\"ש שם."]],[[0,"","בֹּא רְאֵה, כְּמוֹ שֶׁיֵּשׁ מִשְׁמָרוֹת בָּאָרֶץ - כָּךְ גַּם בָּרָקִיעַ שֶׁמְּזַמְּרִים לְרִבּוֹנָם וְאוֹמְרִים תָּמִיד שִׁירָה, וְכֻלָּם עוֹמְדִים אֵלּוּ כְּנֶגֶד אֵלּוּ, וְהַכֹּל בִּסְדָרִים שֶׁל שִׁירוֹת וְתִשְׁבָּחוֹת, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים."],[1,"","עָלָמוֹת שִׁיר, מַה זֶּה עֲלָמוֹת שִׁיר? אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר (שיר ו) שִׁשִּׁים הֵמָּה מְלָכוֹת וּשְׁמֹנִים פִּילַגְשִׁים וַעֲלָמוֹת אֵין מִסְפָּר. מַה זֶּה וַעֲלָמוֹת אֵין מִסְפָּר? כְּמוֹ שֶׁנֶּאֱמַר הֲיֵשׁ מִסְפָּר לִגְדוּדָיו. וּמִשּׁוּם שֶׁאֵין לָהֶם חֶשְׁבּוֹן, כָּתוּב וַעֲלָמוֹת אֵין מִסְפָּר."],[2,"","וְכֻלָּם שׁוּרוֹת שׁוּרוֹת, מַקִּיפִים סְדָרִים, אֵלּוּ כְּנֶגֶד אֵלּוּ, לְזַמֵּר וּלְשַׁבֵּחַ אֶת רִבּוֹנָם, וְאֵלּוּ הֵם עֲלָמוֹת שִׁיר. וּמִשּׁוּם שֶׁיֵּשׁ עֲלָמוֹת שֶׁאֵין מְזַמְּרוֹת כְּמוֹ אֵלּוּ, אֵלּוּ נִקְרָאוֹת עֲלָמוֹת שִׁיר."],[3,"","שְׁלשָה סְדָרִים נִפְרָדִים לְכָל צַד לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וּבְכָל סֵדֶר וְסֵדֶר, שֶׁהוּא לְכָל צַד, שְׁלֹשָׁה סְדָרִים אֲחֵרִים. סֵדֶר רִאשׁוֹן שֶׁלְּצַד מִזְרָח - שְׁלֹשָׁה סְדָרִים הֵם, וְהֵם תִּשְׁעָה סְדָרִים, מִשּׁוּם שֶׁכָּל סֵדֶר מֵהַשְּׁלֹשָׁה הַלָּלוּ יֵשׁ לוֹ שְׁלֹשָׁה סְדָרִים, וְנִמְצְאוּ שֶׁהֵם תִּשְׁעָה, וְכַמָּה אֲלָפִים וּרְבָבוֹת תַּחְתֵּיהֶם."],[4,"","תִּשְׁעַת הַסְּדָרִים הַלָּלוּ, כֻּלָּם מִתְנַהֲגִים בְּאוֹתִיּוֹת רְשׁוּמוֹת, וְכָל סֵדֶר מִסְתַּכֵּל לְאוֹתָן אוֹתִיּוֹת רְשׁוּמוֹת, (והרי בארוה וכן לכל סדר וסדר, וכלם נוסעים באותיות רשומות, ואלו עליונים מאלו, ועומדים אלו על אלו) וְכֻלָּן מִתְחַבְּרוֹת וְאוֹמְרוֹת שִׁירָה. וּכְשֶׁאוֹתָן הָאוֹתִיּוֹת פּוֹרְחוֹת לְתוֹךְ הָאֲוִיר שֶׁל הָרוּחַ (ההיא) הַמְמֻנָּה עַל הַכֹּל, אָז הֵם נוֹסְעִים, וְהַשִּׁירָה נִמְתֶּקֶת, וְאוֹת אַחַת מֻכָּה מִלְּמַטָּה, וְאוֹתָהּ אוֹת עוֹלָה וְיוֹרֶדֶת, וּשְׁתֵּי אוֹתִיּוֹת פּוֹרְחוֹת עֲלֵיהֶן. וְהָאוֹת הַזּוֹ מִלְּמַטָּה מַעֲלָה סֵדֶר מִמַּטָּה לְמַעְלָה וּמִתְחַבֶּרֶת עִמָּם, וְנַעֲשׂוֹת שָׁלֹשׁ אוֹתִיּוֹת, כֻּלָּם לְפִי הָאוֹתִיּוֹת יה\"ו, שֶׁהֵן שָׁלֹשׁ בְּתוֹךְ הָאַסְפַּקְלַרְיָה הַמְּאִירָה. מֵאֵלּוּ נִפְרָדִים שְׁלֹשָׁה סְדָרִים וְאוֹתָן שְׁתֵּי הָאוֹתִיּוֹת, וְאוֹתָהּ הָאוֹת שֶׁעוֹלָה מִתְחַבֶּרֶת עִמָּהֶן, וְהֵן שָׁלֹשׁ."],[5,"","בֹּא רְאֵה, אוֹתָן שְׁתֵּי אוֹתִיּוֹת עֶלְיוֹנוֹת שֶׁעוֹלוֹת בָּאֲוִיר, הֵן כְּלוּלוֹת זוֹ בְּזוֹ, רַחֲמִים בְּדִין, וּמִשּׁוּם כָּךְ הֵן שְׁתַּיִם, וְהֵן מִן הָעוֹלָם הָעֶלְיוֹן, בְּסוֹד שֶׁל זָכָר. וְזוֹ שֶׁעוֹלָה וּמִתְחַבֶּרֶת עִמָּהֶן הִיא נְקֵבָה, וְנִכְלֶלֶת בִּשְׁתֵּיהֶן. כְּמוֹ שֶׁהַנְּקֵבָה נִכְלֶלֶת בִּשְׁנֵי צְדָדִים, בְּיָמִין וּבִשְׂמֹאל, וּמִתְחַבֶּרֶת עִמָּהֶם, כָּךְ גַּם הָאוֹת הַנְּקֵבָה הַזּוֹ שֶׁמִּתְחַבֶּרֶת עִם שְׁתֵּי אוֹתִיּוֹת אֲחֵרוֹת, וְהֵן בִּשְׁנֵי צְדָדִים אֵלּוּ הָעֶלְיוֹנִים, וְזֶה לְמַטָּה, וְהַכֹּל הוּא אֶחָד, זָכָר וּנְקֵבָה. (חוץ) שֶׁכַּאֲשֶׁר נִבְרָא הָעוֹלָם, שֶׁאוֹתָם הָאוֹתִיּוֹת הֵן מִן הָעוֹלָם הָעֶלְיוֹן, שֶׁהֵם הוֹלִידוּ אֶת כָּל הַמַּעֲשִׂים לְמַטָּה כְּמוֹ שֶׁלָּהֶם מַמָּשׁ. וּמִשּׁוּם כָּךְ, מִי שֶׁיּוֹדֵעַ אוֹתָן וְנִזְהָר בָּהֶן, אָהוּב הוּא לְמַעְלָה וְאָהוּב לְמַטָּה."],[6,"","רַבִּי שִׁמְעוֹן אָמַר, כָּל הָאוֹתִיּוֹת הַלָּלוּ, זָכָר וּנְקֵבָה, לְהִכָּלֵל יַחַד בְּסוֹד הַמַּיִם הָעֶלְיוֹנִים וְהַמַּיִם הַתַּחְתּוֹנִים, וְהַכֹּל אֶחָד, וְזֶהוּ הַיִּחוּד הַשָּׁלֵם. וּמִשּׁוּם כָּךְ, מִי שֶׁמַּכִּיר אוֹתָם וְנִזְהָר בָּהֶם, אַשְׁרֵי חֶלְקוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, מִשּׁוּם שֶׁהוּא עִקַּר הַיִּחוּד הַשָּׁלֵם כָּרָאוּי, שָׁלֹשׁ שָׁלֹשׁ מִצַּד זֶה וּמִצַּד זֶה, בְּיִחוּד אֶחָד בִּשְׁלֵמוּת הַכֹּל, וְכֻלָּם הַסּוֹד שֶׁל הַסֵּדֶר הָעֶלְיוֹן כָּרָאוּי כְּמוֹ שֶׁלְּמַעְלָה, שֶׁאוֹתוֹ סֵדֶר שְׁלֹשָׁה שְׁלֹשָׁה בְּסוֹד אֶחָד."],[7,"","סֵדֶר שֵׁנִי שֶׁלְּצַד הַדָּרוֹם, שְׁלֹשָׁה סְדָרִים הֵם לְאוֹתוֹ הַצַּד, וְכָל סֵדֶר וְסֵדֶר שְׁלֹשָׁה שְׁלֹשָׁה, וְהֵם תִּשְׁעָה, כְּמוֹ שֶׁנֶּאֱמַר, וְכָךְ נֶחֱלָקוֹת הָאוֹתִיּוֹת לְכָל צַד לְהִתְחַבֵּר הַכֹּל יַחַד. מִשּׁוּם שֶׁיֵּשׁ אוֹתִיּוֹת בְּסוֹד שֶׁל נְקֵבָה, וְאוֹתִיּוֹת בְּסוֹד שֶׁל זָכָר, וְכֻלָּן הִתְחַבְּרוּ יַחַד, וְהֵן אַחַת בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ הַשָּׁלֵם, וַאֲלֵיהֶם סְדָרִים מְמֻנִּים שְׁלֹשָׁה שְׁלֹשָׁה, כְּמוֹ שֶׁנִּתְבָּאֵר, וְהַכֹּל יוֹצֵא מֵהַסֵּדֶר שֶׁל הָאָבוֹת שֶׁלְּמַעְלָה, כַּסֵּדֶר שֶׁנִּתְקְנוּ אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ יה\"ו, כְּמוֹ שֶׁנִּתְבָּאֵר. כָּל הַסְּדָרִים הַלָּלוּ מִתְנַהֲגִים בָּאוֹתִיּוֹת הַיְדוּעוֹת הַלָּלוּ וְנוֹסְעִים בָּהֶן, וְכַמָּה צְבָאוֹת וּרְבָבוֹת כֻּלָּם לְמַטָּה שֶׁנּוֹסְעִים וּמִתְנַהֲגִים בַּסֵּדֶר הַזֶּה."],[8,"","סֵדֶר שְׁלִישִׁי שֶׁלְּצַד צָפוֹן, בִּשְׁלֹשָׁה סְדָרִים הֵם לְאוֹתוֹ הַצַּד, וְהֵם תִּשְׁעָה, וּבִשְׁלֹשָׁה צְדָדִים שְׁלֹשָׁה שְׁלֹשָׁה לְכָל צַד הֵם תִּשְׁעָה, וְאוֹתָם סְדָרִים מִשְּׁלֹשֶׁת הַצְּדָדִים, כְּמוֹ שֶׁנִּתְבָּאֵר. שִׁבְעָה וְעֶשְׂרִים, בְּסוֹד הָאוֹתִיּוֹת שֶׁהֵן שֶׁבַע וְעֶשְׂרִים. וְאַף עַל גַּב שֶׁהֵן עֶשְׂרִים וּשְׁתַּיִם, שְׁלֵמוּת הָאוֹתִיּוֹת הֵן עֶשְׂרִים וָשֶׁבַע. וְכָךְ הַסִּדּוּר שֶׁל הַסְּדָרוֹת הַלָּלוּ."]]],[["שִׁבְעָה וְעֶשְׂרִים, בְּרָזָא דְאַתְוָון דְּאִינוּן שִׁבְעָה וְעֶשְׂרִין. וְאַף עַל גַּב דְּאִינוּן תְּרֵין וְעֶשְׂרִין, שְׁלִימוּ דְּאַתְוָון אִינוּן שִׁבְעָה וְעֶשְׂרִין. וְהָכִי סִדּוּרָא דְּסִדְּרִין אִלֵּין. שִׁבְעָה וְעֶשְׂרִין לִתְלַת תְּלַת סִדְּרִין לְכָל סְטַר. וְאִשְׁתַּכָּחוּ אִלֵּין ג' מֵהַאי סִטְרָא דְּאִינוּן ט', וְאִלֵּין תְּלַת מֵהַאי סִטְרָא דְּאִינוּן תִּשְׁעָה, וְאִלֵּין תְּלַת דְּהַאי סִטְרָא דְּאִינוּן תִּשְׁעָה. אִשְׁתַּכָּחוּ כֻּלְּהוּ שִׁבְעָה וְעֶשְׂרִין.","וְרָזָא דְאִלֵּין שִׁבְעָה וְעֶשְׂרִין, אִינוּן תִּשְׁעָה אַתְוָון (אינון) דְּאִינוּן בְּרָזָא דְנוּקְבֵי, לְאִתְחַבְּרָא בְּהוּ נוּקְבָא, עִם אִינוּן תְּמַנֵי סָרֵי סִטְרֵי אָחֳרָנִין, בְּרָזָא דְּאִתָּמַר (נ\"א דדכר), וְכֹלָּא אִיהוּ כְּדְקָא חָזֵי.","תָּא חֲזֵי, כְּגַוְונָא דְּאִינוּן אַתְוָון עִלָּאִין דְּעַלְמָא עִלָּאָה, הָכִי נָמֵי אַתְוָון אָחֳרָנִין לְתַתָּא. אַתְוָון עִלָאִין רַבְרְבִין, וְאַתְוָון תַּתָּאִין זְעִירִין, וְכֹלָּא דָא כְּגַוְונָא דָא, וְכָל הַנֵּי רָזִין, בְּרָזָא דִּדְכַר וְנוּקְבָא, כֹּלָּא חַד בִּשְׁלִימוּ.","(בראשית ל׳:כ״ב) וַיִּזְכֹּר אֱלֹהִים אֶת רָחֵל, דְּהָא בְּמַזָּלָא תַּלְיָא, וּבְגִין כָּךְ כְּתִיב בָּהּ זְכִירָה. (בראשית כ״א:א׳) וַה' פָּקַד אֶת שָׂרָה, לָאו מִמַּזָּלָא הֲוָה. וְאִי תֵימָא דְּהָא בְּנִין בְּמַזָּלָא תַּלְיָין וְלָא לְתַתָּא, הָכָא בְּשָׂרָה לָאו בְּמַזָּלָא הֲוָה. אֶלָּא וַה' כְּתִיב, כֹּלָּא כְּחֲדָא.","אִי הָכִי אַמַּאי כְּתִיב פְּקִידָה, אֶלָּא וַדַּאי זְכִירָה, (דא) הֲוַת מִקַּדְמַת דְּנָא, וְאִתְמָסַר מַפְתְּחָא דָּא לְתַתָּא, כְּמָה דִכְתִיב, (בראשית י״ז:כ״א) וְאֶת בְּרִיתִי אָקִים אֶת יִצְחָק אֲשֶׁר תֵּלֵד לְךָ שָׂרָה לַמּוֹעֵד הַזֶּה וְגו'. וּלְבָתַר כְּגַוְונָא דָא, וְכֵיוָן דְּאִדְכַּר, בְּרָזָא דִּלְעֵילָא, לְבָתַר אִתְּמָר בְּרָזָא דְנוּקְבָא פְּקִידָה, לְמֶהֱוֵי כְּלָלָא דְּכֹלָּא כְּחֲדָא.","וַיִּזְכֹּר אֱלהִים אֶת רָחֵל. רַבִּי חִיָּיא פָּתַח וְאָמַר, (שמות ו׳:ה׳) וְגַם אֲנִי שָׁמַעְתִּי אֶת נַאֲקַת בְּנֵי יִשְׂרָאֵל אֲשֶׁר מִצְרַיִם מַעֲבִידִים אֹתָם וָאֶזְכֹּר אֶת בְּרִיתִי. וָאֶזְכֹּר הָא זְכִירָה, בְּגִין דְּאִיהוּ לְעֵילָא. דְּהַאי מַזָּלָא דְּאִיהוּ לְעֵילָא בִּדְכוּרָא, אֲתָא עַל פְּקִידָה דְּאִיהִי בְּגָלוּתָא לְתַתָּא בְנוּקְבָא. כְּגַוְונָא דָא וַיִּזְכֹּר אֱלֹהִים אֶת רָחֵל, כְּמָה דְאַתְּ אָמֵר וָאֶזְכֹּר אֶת בְּרִיתִי.","תָּא חֲזֵי, כְּתִיב, (שמות ג׳:ט״ז) פָּקֹד פָּקַדְתִּי אֶתְכֶם, וְכִי פָּקֹד פָּקַדְתִּי, וְהָא פְּקִידָה בְּנוּקְבָא קַיְימָא וּבְהַהוּא זִמְנָא בְּגָלוּתָא הֲוַת, וְאִיהִי אֲמְרַת פָּקֹד פָּקַדְתִּי. אֶלָּא הָכָא אִית לְאִסְתַּכָּלָא, וְרָזָא דְּחָכְמְתָא הָכָא וְאִיהִי בְּגָלוּתָא הֵיךְ אִתְחֲזֵי לְמשֶׁה הָכָא, וְהֵיךְ אֲמְרַת פָּקֹד פָּקַדְתִּי.","אֶלָּא הָכִי אוֹלִיפְנָא שִׁמְשָׁא כַּד נָהִיר, אִיהוּ בִּשְׁמַיָא, וְתוּקְפֵּיהּ וְחֵילֵיהּ שָׁלְטָא עַל אַרְעָא בְּכָל אֲתַר. כְּגַוְונָא דָא (ישעיהו ו׳:ג׳) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ, בְּזִמְנָא דְּמַקְדְּשָׁא קָאִים, מְלא כָל הָאָרֶץ כְּבוֹדוֹ, דָּא אַרְעָא קַדִּישָׁא. וְהַשְׁתָּא דְיִשְׂרָאֵל בְּגָלוּתָא, אִיהִי לְעֵילָא, וְתוּקְפָּא סַחֲרָא לְהוּ לְיִשְׂרָאֵל לְאֲגָנָא עֲלַיְיהוּ, וְאַף עַל גַּב דְּאִינוּן בְּאַרְעָא אָחֳרָא.","וְתָא חֲזֵי, שְׁכִינְתָּא לְתַתָּא וּשְׁכִינְתָּא לְעֵילָא. שְׁכִינְתָּא לְעֵילָא בִּתְרֵיסַר תְּחוּמֵי רְתִיכִין קַדִּישִׁין, וּתְרֵיסַר חֵיוָון עִלָּאִין. שְׁכִינְתָּא לְתַתָּא בִּתְרֵיסַר שִׁבְטִין קַדִּישִׁין, וּכְדֵין אִתְכְּלִילַת שְׁכִינְתָּא לְעֵילָא וְתַתָּא, וְכֹלָּא בְּחַד זִמְנָא כְּחֲדָא. וְאַף עַל גַּב דְּבְּזִמְנָא דְּיִשְׂרָאֵל בְּגָלוּתָא לְתַתָּא, לָא אִתְתַּקָּנַת לְעֵילָא, הָכִי נָמֵי לָא אִתְתַּקָּנַת, בְּגִין דִּלְתַתָּא לָא אִתְתַּקָּנַת, וְדָא הוּא בְּגָלוּתָא עִמְּהוֹן דְּיִשְׂרָאֵל, דְּאִיהִי בְּגָלוּתָא עִמְּהוֹן.","בְּמָּה אִתְתַּקָּנַת, לְמַלְכָּא דְּמִית בְּרֵיהּ, מָה עֲבַד כָּפָא לֵיהּ לְעַרְסֵיהּ עַל אֶבְלָא דִבְרֵיהּ, וְלָא אַתְקִין לֵיהּ לְעַרְסֵיהּ, אֶלָּא נָטַל כּוּבִין וְדַרְדַּרִין, וְאַטִּיל תְּחוֹת עַרְסֵיהּ, וְשָׁכִיב עֲלֵיהּ, כָּךְ קוּדְשָׁא בְּרִיךְ הוּא, כֵּיוָן דְּאִתְגָּלוּ יִשְׂרָאֵל, וְאִתְחָרֵב מַקְדְּשָׁא, נָטַל כּוּבִין וְדַרְדַּרִין וְשַׁוֵּי תְּחוֹתֵיהּ, הֲדָא הוּא דִכְתִיב, (שמות ג׳:ב׳) וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה. בְּגִין דְּיִשְׂרָאֵל הֲווּ בְּגָלוּתָא.","פָּקֹד פָּקַדְתִּי אֶתְכֶם, מַאן דְּלָא קָיְימָא בִּרְשׁוּתֵיהּ, מַה פַּקִּיד, וּמַה עֲבִיד. אֶלָּא פָּקֹד מִלְּעֵילָא, פָּקַדְתִּי מִלְּתַתָּא, מַאי טַעְמָא, בְּגִין דְּהַאי זְכִירָה הֲוַת עֲלָהּ מִקַּדְּמַת דְּנָא, דִּכְתִיב וָאֶזְכֹּר אֶת בְּרִיתִי. כֵּיוָן דִּכְתִיב וָאֶזְכֹּר, הָא זְכִירָה אִתְמְנָא עֲלָה, וּבְּגִין כָּךְ אֲמְרַת לְבָתַר פָּקֹד פָּקַדְתִּי. דְּהָא סִימָנָא נָקְטַת מִקַּדְּמַת דְּנָא. כְּגַוְּונָא דָא שָׂרָה דִּכְתִיב, (בראשית כ״א:א׳) וַה' פָּקַד אֶת שָׂרָה. אֲבָל הָכָא רָחֵל דְלָא אִדְכָּרַת מִקַּדְּמַת דְּנָא, לָא אִתְּמָר בָּהּ פְּקִידָה אֶלָּא זְכִירָה, וְכֹלָּא בִּזְכִירָה אִיהוּ, בְּרָזָא דְּמַזָּלָא."],[[0,"שבעה ועשרים ברזא וכו':","כ\"ז סדרים הם בסוד האותיות שהם כ\"ז, ואע\"פ שהם רק כ\"ב אותיות, הרי האותיות בשלימות, דהיינו עם מנצפ\"ך הכפולות, הם כ\"ז. וכך הוא הסדר. השבעה ועשרים סדרים אלו, מתחלקים לשלשה שלשה סדרים לכל רוח, דהיינו ג' לרוח מזרח, ג' לרוח דרום, וג' לרוח צפון כנ\"ל, ובהיות הג' שבכל רוח נכללים זה מזה, נמצא שהג' מרוח הזה הם ט', והג' מרוח הזה הם ט' והג' שמרוח הזה הם ט', ונמצאים כולם יחד שהם שבעה ועשרים אותיות."],[1,"ורזא דאלין שבעה ועשרים,","והסוד הוא שאלו שבעה ועשרים, הם ט' אותיות שהם בסוד נקבות, להתחבר עם הי\"ח סדרים האחרים, שהם בסוד זכרים, והכל הוא כראוי להיות."],[1,"","פירוש. כי נתבאר לעיל שכל ג' אותיות ה\"ס ג' קוין, הנמשכות מג' קוין שבבינה, אשר ב' אותיות העליונות, שהן אות הימין ואות השמאל, הם זכרים, ואות הג' שמתחתיהן הם נקבות, (כנ\"ל דף ק\"ח ד\"ה רבי ע\"ש) וט' האותיות הנמצאים בכל רוח, הם ג' קבוצות של ג' ג' כנ\"ל. ונמצא לפי\"ז שיש בכל רוח, ששה אותיות זכרים, שהם ג\"פ שתי אותיות הימניות והשמאליות, שבכל קבוצה, וג' אותיות נקבות, שהם ג' אותיות האמצעיות שבכל קבוצה. ונמצא שיש ו' זכרים וג' נקבות ברוח מזרח, וכן ו' זכרים וג' נקבות ברוח דרום, וכן ו' זכרים וג' נקבות ברוח צפון. שביחד הם י\"ח זכרים ותשע נקבות. וז\"ש ורזא דאלין שבעה ועשרין, \u0003אינון תשעה אתוון דאינון ברזא דנוקבי,\u0004 כי ג' אותיות נקבות הן בכל רוח וגפ\"ג הן ט'. \u0003לאתחברא עם אינון תמני סרי, סטרי אחרנין ברזא דדכר\u0004 כי ששה אותיות זכרים הם בכל רוח וג\"פ ששה הם י\"ח. הרי שכ\"ז האותיות נחלקות לי\"ח זכרים, ותשעה נקבות."],[2,"ת\"ח כגוונא דאינון וכו':","בוא וראה, כעין אלו האותיות, שיש בעולם העליון, בבינה, כן יש אותיות אחרות למטה, בנוקבא. אותיות העליונות, שבבינה, הן גדולות, ואותיות התחתונות, שבנוקבא, הן קטנות. והכל הוא זה כמו זה, שכל הנוהג באותיות שבבינה נוהג ג\"כ באותיות שבנוקבא, וכן נוהג בהם כל אלו הסודות שבסוד דכר ונוקבא, שבאותיות, והכל אחד בשלימות, כלומר שכל שנוהג בעולם העליון נוהג בעולם התחתון."],[3,"ויזכור אלקים את רחל:","כי בנים תלוים במזלא, שה\"ס הנהר היוצא מעדן, המזיל ומשקה את הגן. שה\"ס ז\"א, (כנ\"ל וירא דף קכ\"ה אות תכ\"ד) ומשום זה כתוב בה \u0003זכירה,\u0004 כי זכירה הוא מזכור, שה\"ס ז\"א, ופקידה היא מנוקבא (כמ\"ש שם באות תכ\"ג) ושואל, וה' פקד את שרה, שלא ממזל הוא, כי לא כתוב בה זכירה, ואם תאמר שבנים תלוים דוקא במזל, ולא למטה בנוקבא הרי כאן בשרה לא היה במזל. ומשיב, אלא \u0003והוי\"ה,\u0004 כתוב, שכתוב והוי\"ה פקד וגו', שכולל הכל כאחד. כי \u0003והוי\"ה\u0004 יורה הוא ובית דינו שפירושו, ז\"א עם הנוקבא, ביחד (כנ\"ל וירא דף פ\"א ד\"ה כד) הרי יש כאן בשרה, גם \u0003זכירה\u0004 מז\"א, שה\"ס מזל."],[4,"אי הכי אמאי וכו':","שואל אם כן אשר והוי\"ה כולל ז\"א ונוקבא ביחד שה\"ס זכירה ופקידה. למה כתוב \u0003פקידה,\u0004 הרי והוי\"ה כולל כבר גם פקידה. ומשיב אלא ודאי שזכירה כבר היתה מקודם לכן, וכבר נמסר מפתח הזה של בנים למטה, כמו שכתוב, ואת בריתי וגו' אשר תלד לך שרה וגו', וכן לאח\"כ כתיב כעין זה דהיינו ויאמר הוי\"ה וגו' למועד אשוב אליך כעת חיה ולשרה בן. וכיון שכבר היתה זכירה, בסוד של מעלה של ז\"א כיון שכתוב ואת בריתי שפירושו יסוד דז\"א. נאמר אחר כך בסוד \u0003פקידה,\u0004 שהיא הנוקבא, כדי שתהיה כללות הכל ביחד, דהיינו שתהיה בה, \u0003זכירה ופקידה\u0004 ביחד."],[5,"ויזכור אלהים את רחל:","ר' חייא פתח ואמר, וגם אני שמעתי וגו' \u0003ואזכור\u0004 את בריתי, \u0003ואזכור,\u0004 הוא \u0003זכירה,\u0004 כי הוא למעלה, בז\"א, כי מזל זה, שהוא למעלה בזכר, בא על \u0003פקידה,\u0004 שהיא הנוקבא למטה, שהיא בגלות, לגאול אותה. וכעין זה ויזכור אלקים את רחל, הוא כמ\"ש ואזכור את בריתי. פירוש. שהכתוב \u0003ויזכור\u0004 הוא זכירה, דהיינו ז\"א, כמו בכתוב, ואזכור וגו', \u0003את רחל,\u0004 היא הנוקבא, שהיא \u0003פקידה,\u0004 ויורה, שהזכירה המרומז בויזכור וגו', באה על רחל שה\"ס פקידה, והשפיע לה שפע הבנים. והשם אלקים, שכתוב, ויזכור אלקים, ה\"ס בינה שנקראת אלקים."],[6,"ת\"ח כתיב פקד פקדתי אתכם:","שואל, וכי יתכן שיאמר הכתוב, \u0003פקד פקדתי,\u0004 והרי פקידה היא בנוקבא, שבעת ההוא היתה בגלות, והיא תאמר, \u0003פקד פקדתי,\u0004 בעת שהיא עצמה היא בגלות. ומשיב, אלא כאן יש להסתכל, וסוד החכמה יש כאן, שיש לשאול, א) כיון שהיא בגלות, איך היא נתגלתה כאן למשה, ב) ואיך אמרה, פקד פקדתי. כלומר, שמוסיף תמיהא, ואומר, שיש ב' קושיות כאן."],[7,"אלא הכי אוליפנא וכו':","ומשיב, אלא כך למדנו, כשהשמש מאיר, הוא בשמים, וגבורתו וכחו מושל בכל מקום על הארץ. כעין זה, נאמר בה', מלא כל הארץ כבודו. בזמן שבית המקדש היה קיים: מלא כל הארץ כבודו, זהו ארץ הקדושה, דהיינו הנוקבא, ואז נוהג גילוי שכינה. ועתה שישראל הם בגלות, השכינה היא למעלה, דהיינו מחזה ולמעלה דז\"א, ששם בחינת שמים, דהיינו חסדים מכוסים, ואינה מתגלה בארץ, אלא, תוקפה נמשך לארץ, כמו השמש המסתתרת בשמים, וכחה וגבורתה מלא הארץ. כנ\"ל. ומסבבת את ישראל להגין עליהם, ואף על פי שנמצאים בארץ אחרת, בגלות."],[8,"ות\"ח שכינתא לתתא וכו':","ומבאר יותר ואומר ובוא וראה, יש שכינה למטה מחזה דז\"א, ויש שכינה למעלה מחזה דז\"א, השכינה שלמעלה, היא בי\"ב גבולי מרכבות קדושות, וי\"ב חיות עליונות. דהיינו ד' ספירות חו\"ב תו\"מ, שבכל אחת חו\"ב ות\"ת, שהם במספר י\"ב (כנ\"ל פ' לך דף ח' ד\"ה ומכח) שה\"ס י\"ב גבולים, וכן י\"ב חיות גדולות להיותם מחזה ולמעלה השכינה שלמטה היא בי\"ב שבטים הקדושים, (כנ\"ל דף ע' ד\"ה ות\"ח ע\"ש) ואז, (כששתיהן הן בסוד י\"ב) נכללת השכינה למעלה ולמטה, ששתיהן נעשו פרצוף אחד, (כנ\"ל דף צ\"ח ד\"ה ת\"ח ע\"ש) והכל מאיר בזמן אחד בבת אחת. ואז נאמר מלא כל הארץ כבודו, ויש גילוי שכינה למטה בעולם הזה. כנ\"ל בדבור הסמוך."],[8,"ואע\"ג דבזמנא דישראל וכו':","ואף על פי, שאמרנו לעיל בדיבור הסמוך, שבזמן שישראל הם בגלות, לא נתקנה השכינה למטה, מחזה, אלא שעלתה למעלה מחזה, הנה למעלה גם כן לא נתקנה, שנבחנת כחסרה ג\"ר, משום שלא נתקנה למטה מחזה, שנבחנת משום זה כחסרה נהי\"מ שלמטה מחזה, וזה הוא שאמרו, שהשכינה היא בגלות עם ישראל, כי היא בגלות עמהם. פירוש כי משום עליתה למעלה, נחסרה בג\"ר דאורות ונה\"י דכלים, וזה נבחן לגלות."],[9,"במה אתתקנת וכו':","שואל, במה מתתקנת הנוקבא בזמן הגלות, שתוכל להתגלות למטה. ואומר בדומה למלך, שמת בנו, מה עשה, כפה מטתו, בשביל האבל על בנו, ולא התקין אותה, אלא שלקח קוצים ודרדרים והטילם תחת מטתו, ושכב עליהם. כך הקב\"ה כיון שגלו ישראל, ונחרב בית המקדש, לקח קוצים ודרדרים ונתן תחתיו, וזהו שכתוב, וירא מלאך ה' אליו בלבת אש מתוך \u0003הסנה,\u0004 ועשה זה, משום שישראל היו בגלות. ומיושב בזה קושיא הראשונה הנ\"ל, (באות ר\"ע) שהקשה כיון שהשכינה היתה בגלות, איך נתגלתה למשה. והתירוץ הוא, שעל כן, נתגלתה אליו אז, מתוך הסנה, שה\"ס בלתי שלימות ודינים, שבאופן זה, היא יכולה להתגלות גם בזמן הגלות, וקושיא השניה מתרץ להלן."],[10,"פקד פקדתי אתכם:","חוזר על הקושיא הנ\"ל, (באות ר\"ע). מי שהוא עצמו אינו ברשותו, אלא בגלות, מה הוא יכול לפקוד, ומה הוא יכול לעשות, ואיך אמרה השכינה, פקד פקדתי, בזמן שהיא בגלות. ומשיב, אלא \u0003פקד,\u0004 פירושו מלמעלה מז\"א, שה\"ס \u0003זכירה,\u0004 כנ\"ל. \u0003פקדתי,\u0004 הוא למטה בנוקבא, ומהו הטעם שאמרה \u0003פקד,\u0004 שפירושו זכירה. ולא אמר \u0003זכור\u0004 במפורש, הוא, משום שזכירה זו כבר היתה עליה מקודם לכן, שכתוב, \u0003ואזכור\u0004 את בריתי, כיון שכתוב ואזכור, הרי כבר ניתנה בה \u0003זכירה\u0004 ומשום זה אמרה אחר כך פקד פקדתי, שהמלה, \u0003פקד,\u0004 רומזת על הזכירה שניתנה בה מכבר. כי אחזה סימן זה של הלשון, פקד פקדתי, מקודם לכן. פירוש כמו שאמרו ז\"ל, סימן זה מסור בידם מיעקב ומיוסף, שיעקב אמר פקד יפקוד אתכם, וכן יוסף אמר פקד יפקוד אלקים אתכם. ומובא (ברש\"י ז\"ל בראשית ג' י\"ח) והיינו משום שצריכים זכירה ופקידה לגאולה, \u0003ופקד\u0004 רומז על זכירה שמכבר, פקדתי על פקידה."]],[[0,"","שִׁבְעָה וְעֶשְׂרִים, לִשְׁלֹשָׁה שְׁלֹשָׁה סְדָרִים לְכָל צַד. וְנִמְצְאוּ שְׁלֹשָׁה אֵלֶּה מִצַּד זֶה שֶׁהֵם תִּשְׁעָה, וּשְׁלֹשָׁה הַלָּלוּ מֵהַצַּד הַזֶּה שֶׁהֵם תִּשְׁעָה, וּשְׁלֹשָׁה הַלָּלוּ מֵהַצַּד הַזֶּה שֶׁהֵם תִּשְׁעָה, נִמְצְאוּ כֻלָּם שִׁבְעָה וְעֶשְׂרִים."],[1,"","וְהַסּוֹד שֶׁל הַשִּׁבְעָה וְעֶשְׂרִים הַלָּלוּ הֵן תֵּשַׁע אוֹתִיּוֹת (הן) שֶׁהֵן בְּסוֹד הַנְּקֵבוֹת, לְחַבֵּר עִמָּהֶם נְקֵבָה עִם אוֹתָם שְׁמוֹנָה עָשָׂר צְדָדִים אֲחֵרִים בַּסּוֹד שֶׁנִּתְבָּאֵר (של הזכר), וְהַכֹּל הוּא כָּרָאוּי."],[2,"","בֹּא רְאֵה, כְּמוֹ שֶׁאוֹתָן אוֹתִיּוֹת עֶלְיוֹנוֹת שֶׁל הָעוֹלָם הָעֶלְיוֹן, כָּךְ גַּם הָאוֹתִיּוֹת הָאֲחֵרוֹת לְמַטָּה, אוֹתִיּוֹת עֶלְיוֹנוֹת גְּדוֹלוֹת, וְאוֹתִיּוֹת תַּחְתּוֹנוֹת קְטַנּוֹת, וְהַכֹּל זֶה כְּמוֹ זֶה. וְכָל הַסּוֹדוֹת הַלָּלוּ הֵם בְּסוֹד שֶׁל זָכָר וּנְקֵבָה, הַכֹּל אֶחָד בִּשְׁלֵמוּת."],[3,"","וַיִּזְכֹּר אֱלֹהִים אֶל רָחֵל, שֶׁהֲרֵי בְּמַזָּל זֶה תָלוּי, וּמִשּׁוּם כָּךְ כָּתוּב בָּהּ זְכִירָה. וַה' פָּקַד אֶת שָׂרָה - זֶה לֹא הָיָה מֵהַמַּזָּל. וְאִם תֹּאמַר שֶׁהֲרֵי הַבָּנִים תְּלוּיִים בְּמַזָּל וְלֹא לְמַטָּה - כָּאן בְּשָׂרָה זֶה לֹא הָיָה בְּמַזָּל, אֶלָּא כָּתוּב וַה', הַכֹּל יַחַד."],[4,"","אִם כָּךְ, לָמָּה כָּתוּב פְּקִידָה? אֶלָּא וַדַּאי הַזְּכִירָה (הזו) הָיְתָה מִקֹּדֶם לָכֵן, וְהַמַּפְתֵּחַ הַזֶּה נִמְסַר לְמַטָּה, כְּמוֹ שֶׁכָּתוּב (בראשית יז) וְאֶת בְּרִיתִי אָקִים אֶת יִצְחָק אֲשֶׁר תֵּלֵד לְךְ שָׂרָה לַמּוֹעֵד הַזֶּה וְגוֹ'. אַחֲרֵי כֵן כְּמוֹ זֶה - כֵּיוָן שֶׁנִּזְכַּר בַּסּוֹד שֶׁלְּמַעְלָה, אַחַר כָּךְ נֶאֱמַר בַּסּוֹד שֶׁל הַנְּקֵבָה פְּקִידָה, שֶׁיִּהְיֶה הַכְּלָל שֶׁל הַכֹּל יַחַד."],[5,"","וַיִּזְכֹּר אֱלֹהִים אֶל רָחֵל. רַבִּי חִיָּיא פָּתַח וְאָמַר, (שמות ו) וְגַם אֲנִי שָׁמַעְתִּי אֶת נַאֲקַת בְּנֵי יִשְׂרָאֵל אֲשֶׁר מִצְרַיִם מַעֲבִידִים אֹתם וָאֶזְכֹּר אֶת בְּרִיתִי. וָאֶזְכֹּר - הֲרֵי זְכִירָה, מִשּׁוּם שֶׁהִיא לְמַעְלָה, שֶׁהַמַּזָּל הַזֶּה הוּא לְמַעְלָה בַּזָּכָר, בָּא עַל פְּקִידָה שֶׁהִיא בַּגָּלוּת לְמַטָּה בַּנְּקֵבָה. כְּמוֹ כֵן וַיִּזְכֹּר אֱלֹהִים אֶת רָחֵל, כְּמוֹ שֶׁנֶּאֱמַר וָאֶזְכֹּר אֶת בְּרִיתִי."],[6,"","בֹּא רְאֵה, כָּתוּב פָּקֹד פָּקַדְתִּי אֶתְכֶם. וְכִי פָּקֹד פָּקַדְתִּי? וַהֲרֵי הַפְּקִידָה עוֹמֶדֶת בַּנְּקֵבָה, וּבְאוֹתוֹ הַזְּמַן הָיְתָה בַּגָּלוּת, וְהִיא אוֹמֶרֶת פָּקֹד פָּקַדְתִּי? אֶלָּא שֶׁכָּאן יֵשׁ לְהִסְתַּכֵּל, וְכָאן סוֹד שֶׁל הַחָכְמָה, וְהִיא בַּגָּלוּת, אֵיךְ נִרְאֶה לְמֹשֶׁה כָּאן וְאֵיךְ אָמְרָה פָּקֹד פָּקַדְתִּי."],[7,"","אֶלָּא כָּךְ לָמַדְנוּ, כְּשֶׁהַשֶּׁמֶשׁ מֵאִיר - הוּא בַּשָּׁמַיִם, וְתָקְפּוֹ וְכֹחוֹ עַל הָאָרֶץ בְּכָל מָקוֹם. כְּמוֹ כֵן מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. בִּזְמַן שֶׁהַמִּקְדָּשׁ עָמַד - מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ, זוֹ הָאָרֶץ הַקְּדוֹשָׁה, וְכָעֵת שֶׁיִּשְׂרָאֵל בַּגָּלוּת - הִיא לְמַעְלָה, וְהַתֹּקֶף מַקִּיף אֶת יִשְׂרָאֵל לְהָגֵן עֲלֵיהֶם, וְאַף עַל גַּב שֶׁהֵם בְּאֶרֶץ אַחֶרֶת."],[8,"","וּבֹא תִרְאֶה, שְׁכִינָה לְמַטָּה וּשְׁכִינָה לְמַעְלָה. שְׁכִינָה לְמַעְלָה בִּשְׁנֵים עָשָׂר תְּחוּמִים מֶרְכָּבוֹת קְדוֹשׁוֹת וּשְׁתֵּים עֶשְׂרֵה חַיּוֹת עֶלְיוֹנוֹת. שְׁכִינָה לְמַטָּה בִּשְׁנֵים עָשָׂר שְׁבָטִים קְדוֹשִׁים. וְאָז נִכְלֶלֶת הַשְּׁכִינָה לְמַעְלָה וּלְמַטָּה, וְהַכֹּל בְּפַעַם אַחַת יַחַד. וְאַף עַל גַּב שֶׁבִּזְמַן שֶׁיִּשְׂרָאֵל בַּגָּלוּת לְמַטָּה לֹא נִתְקֶנֶת לְמַעְלָה, כָּךְ גַּם לֹא נִתְקֶנֶת מִשּׁוּם שֶׁלְּמַטָּה לֹא נִתְקֶנֶת, וְזֶהוּ בַּגָּלוּת עִם יִשְׂרָאֵל, שֶׁהִיא בַּגָּלוּת עִמָּהֶם."],[9,"","בַּמֶּה נִתְקֶנֶת? לְמֶלֶךְ שֶׁמֵּת בְּנוֹ, מֶה עָשָׂה? כָּפָה אֶת מִטָּתוֹ עַל אֵבֶל בְּנוֹ, וְלֹא הִתְקִין לוֹ אֶת מִטָּתוֹ, אֶלָּא נָטַל קוֹצִים וְדַרְדָּרִים וְהִטִּיל תַּחַת מִטָּתוֹ וְשָׁכַב עָלֶיהָ. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, כֵּיוָן שֶׁגָּלוּ יִשְׂרָאֵל וְנֶחֱרַב הַמִּקְדָּשׁ, לָקַח קוֹצִים וְדַרְדָּרִים וְשָׂם תַּחְתָּיו. זֶהוּ שֶׁכָּתוּב וַיֵּרָא אֵלָיו מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה, מִשּׁוּם שֶׁיִּשְׂרָאֵל הָיוּ בַּגָּלוּת."],[10,"","פָּקֹד פָּקַדְתִּי אֶתְכֶם. מִי שֶׁלֹּא עוֹמֵד בִּרְשׁוּתוֹ, מַה מְצַוֶּה וּמָה עוֹשֶׂה? אֶלָּא פָּקֹד מִלְמַעְלָה, פָּקַדְתִּי מִלְּמַטָּה. מָה הַטַּעַם? מִשּׁוּם שֶׁהַזְּכִירָה הַזּוֹ הָיְתָה עָלֶיהָ מִקֹּדֶם לָכֵן, שֶׁכָּתוּב וָאֶזְכֹּר אֶת בְּרִיתִי. כֵּיוָן שֶׁכָּתוּב וָאֶזְכֹּר - הִנֵּה זְכִירָה הִתְמַנְּתָה עָלֶיהָ, וּמִשּׁוּם כָּךְ אָמְרָה אַחַר כָּךְ פָּקֹד פָּקַדְתִּי, שֶׁהֲרֵי סִימָן לָקְחָה מִקֹּדֶם לָכֵן. כְּמוֹ כֵן שָׂרָה, שֶׁכָּתוּב וַה' פָּקַד אֶת שָׂרָה. אֲבָל כָּאן רָחֵל, שֶׁלֹּא נִזְכְּרָה מִקֹּדֶם לָכֵן, לֹא נֶאֱמַר בָּהּ פְּקִידָה, אֶלָּא זְכִירָה, וְהַכֹּל הוּא בִּזְכִירָה, בַּסּוֹד שֶׁל הַמַּזָּל."]]],[["רִבִּי יְהוּדָה וְרִבִּי חִזְקִיָּה, הֲווּ אָזְלֵי מִקַּפּוֹטְקִיָא לְלוֹד, וְהֲוָה רִבִּי יְהוּדָה רָכִיב, וְרִבִּי חִזְקִיָּה עַל רַגְלוֹי, אַדְּהָכִי נָחַת רִבִּי יְהוּדָה, אָמַר מִכָּאן וּלְהָלְאָה נִתְעַסֵּק בְּאוֹרַיְיתָא, כְּמָה דִכְתִיב, (דברים ל״ב:ג׳) הָבוּ גֹּדֶל לֵאלֹהֵינוּ.","אָמַר לֵיהּ אִלּוּ הֲוֵינָא תְּלָתָא, יָאוֹת הוּא דְּחַד יֵימָא, וּתְרֵין יָתִיבוּ לֵיהּ. אָמַר לֵיהּ, הַנֵּי מִלֵּי בְּבִרְכָאן. בְּגִין דְּאִדְכַּר חַד שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וּתְרֵין יָתִיבוּ לֵיהּ. הֲדָא הוּא דִכְתִיב, (דברים ל״ב:ג׳) כִּי שֵׁם ה' אֶקְרָא הָבוּ גֹּדֶל לֵאלהֵינוּ. כִּי שֵׁם ה' אֶקְרָא, דָּא חַד דִּמְבָרֵךְ, הָבוּ גֹּדֶל לֵאלהֵינוּ, אִלֵּין תְּרֵין אָחֳרָנִין. אֲבָל בְּאוֹרַיְיתָא אֲפִילּוּ תְּרֵי יַתְבֵי וְיַהֲבֵי רְבוּ וְתוּקְפָּא דְּשִׁבְחָא דְּאוֹרַיְיתָא לְקוּדְשָׁא בְּרִיךְ הוּא.","אָמַר לֵיהּ רִבִּי חִזְקִיָּה, לְגַבֵּי בִּרְכָאן אַמַּאי תְּלַת. אָמַר לֵיהּ, הָא אוּקְמוּהָ וְאִתְּמָר, דִּכְתִיב הָבוּ גֹּדֶל לֵאלהֵינוּ. אֲבָל רָזָא דְמִלָּה הָכָא, דְּהָא כָּל רָזִין דְּבִרְכָאן הָכִי אִיהוּ, חַד לְבָרְכָא וּתְרֵין לְאֲתָבָא, בְּגִין דִּיסַלַּק (דיסתלק) שְׁבָחָא דְקוּדְשָׁא בְּרִיךְ הוּא בְּרָזָא דִתְלָתָא. חַד מְבָרֵךְ וּתְרֵין (אמרי אמן) דְּאוֹדוּ, וְדָא הוּא קִיּוּמָא דְּבִרְכָאן, וּבְרָזָא עִלָּאָה כְּדְקָא יְאוּת, וּבְרָזָא דִּתְלַת כְּמָה דְאוּקְמוּהָ.","עַד דְּהֲווּ אָזְלֵי, אָמַר רִבִּי יְהוּדָה, תָּנִינָן, אִית זְכִירָה לְטַב, וְאִית זְכִירָה לְבִישׁ, אִית פְּקִידָה לְטַב, וְאִית פְּקִידָה לְבִישׁ. אִית זְכִירָה לְטַב, כְּמָה דְאוּקְמוּהָ, דִּכְתִיב (ויקרא כ״ו:מ״ה) וְזָכַרְתִּי לָהֶם בְּרִית רִאשׁוֹנִים וְגו'. (בראשית ח׳:א׳) וַיִּזְכֹּר אֱלהִים אֶת נֹחַ. (שמות ב׳:כ״ד) וַיִּזְכֹּר אֱלֹהִים אֶת בְּרִיתוֹ. וְאִית זְכִירָה לְבִישׁ, דִּכְתִיב, (תהילים ע״ח:ל״ט) וַיִּזְכֹּר כִּי בָשָׂר הֵמָּה רוּחַ הוֹלֵךְ וְלא יָשׁוּב. פְּקִידָה לְטַב, דִּכְתִיב, (שמות ג׳:ט״ז) פָּקֹד פָּקַדְתִּי אֶתְכֶם. פְּקִידָה לְבִישׁ, דִּכְתִיב, (תהילים פ״ט:ל״ג) וּפָקַדְתִּי בְּשֵׁבֶט פִּשְׁעָם וּבִנְגָעִים עֲוֹנָם. וְכֻלְּהוּ רָזִין עִלָּאִין.","כָּל הַנֵּי זְכִירָה וּפְקִידָה לְטַב, אִלֵּין אִינוּן דַּרְגִּין יְדִיעָן. רָזָא דִּמְהֵימְנוּתָא דְּכַר וְנוּקְבָא רָזָא חָדָא, זְכִירָה וּפְקִידָה, וְאִלֵּין אִינוּן לְטַב. זְכִירָה וּפְקִידָה לְבִישׁ, אִלֵּין אִינוּן רָזָא דְסִטְרָא אָחֳרָא, דְּקָיְימָא בְּרָזָא דְּאֱלֹהִים אֲחֵרִים, דְּכַר וְנוּקְבָא כְּחֲדָא, זְכִירָה בְּהַאי, וּפְקִידָה בְּהַאי, וְאִלֵּין אִינוּן דְּקָיְימִין תָּדִיר לְבִישׁ. וְאִלֵּין לָקֳבֵיל אִלֵּין. מֵהָכָא נָפְקֵי כָּל רָזֵי דִּמְהֵימְנוּתָא וְכָל קִדּוּשִׁין עִלָּאִין, כְּמָה דְאוּקְמוּהָ. וּמֵהָכָא נָפְקֵי כָּל זִינִין בִּישִׁין וְכָל מוֹתָא, וְכָל סִטְרִין וְזִינִין בִּישִׁין בְּעַלְמָא וְאוּקְמוּהָ. וְדָא בְּהִפּוּכָא מִן דָּא.","אָמַר רִבִּי חִזְקִיָּה, הָכִי הוּא וַדַּאי, זַכָּאָה אִיהוּ, מַאן דְּחוּלָקֵיהּ אִתְקְיַּים בְּסִטְרָא טָבָא, וְלָא יַרְכִין גַּרְמֵיהּ לְסִטְרָא אָחֳרָא, וְיִשְׁתְּזִיב מִנְהוֹן. אָמַר לֵיהּ רִבִּי יְהוּדָה, הָכִי הוּא וַדַּאי, וְזַכָּאָה מַאן דְּיָכִיל לְאִשְׁתְּזָבָא מִנֵּיהּ מֵהַהוּא סִטְרָא, וְזַכָּאִין אִינוּן צַדִּיקַיָּא, דְּיָכְלֵי לְאִשְׁתְּזָבָא מִנַּיְיהוּ, וְלַאֲגָחָא קְרָבָא בְּהַהוּא סִטְרָא. אָמַר רִבִּי חִזְקִיָּה בְּמָּה. פָּתַח וְאָמַר, (משלי כ״ד:ו׳) כִּי בְּתַחְבּוּלוֹת תַּעֲשֶׂה לְךָ מִלְחָמָה וְגו'. מַאן מִלְחָמָה, דָּא מִלְחָמָה דְּהַהוּא סִטְרָא בִּישָׁא, דְּאִצְטְרִיךְ בַּר נָשׁ לַאֲגָחָא בֵּיהּ קְרָבָא, וּלְשַׁלְטָאָה עֲלוֹי וּלְאִשְׁתְּזָבָא מִנֵּיהּ.","תָּא חֲזֵי, דְּיַעֲקֹב הָכִי אִשְׁתָּדַּל לְגַבֵּי עֵשָׂו, בְּגִין הַהוּא סִטְרָא דִילֵיהּ. לְאִתְחַכְּמָא עֲלוֹי וּלְמֵיזַל עִמֵּיהּ בְּעֲקִימוּ בְּכָל מַה דְּאִצְטְרִיךְ, בְּגִין לְשַׁלְטָאָה עֲלוֹי בְּרֵישָׁא וְסוֹפָא, וְכֹלָּא כְּדְקָא יְאוּת. וְרֵישָׁא וְסוֹפָא כְּחֲדָא דָּא כְּגַוְונָא דָא, כְּמָה דִכְתִיב, (בראשית כה) בְּכֹרָתִי, וּלְבָתַר בִּרְכָתִי, שֵׁירוּתָא וְסוֹפָא כְּחֲדָא, דָּא כְּגַוְונָא דָא. בְּגִין לְשַׁלְּטָאָה עֲלוֹי בְּאוֹרַח מֵישַׁר כְּדְקָא חָזֵי לֵיהּ. וּבְגִין כָּךְ זַכָּאָה אִיהוּ מַאן דְּאִשְׁתְּזִיב מִנַּיְיהוּ, וְיָכִיל לְשַׁלְּטָאָה עֲלַיְיהוּ.","תָּא חֲזֵי, זְכִירָה וּפְקִידָה לְטַב אִינוּן כְּחֲדָא בְּרָזָא דִמְהֵימְנוּתָא, וְזַכָּאָה אִיהוּ מַאן דְּאִשְׁתַּדַּל בָּתַר מְהֵימְנוּתָא, כְּמָה דְאַתְּ אָמֵר, (הושע י״א:י׳) אַחֲרֵי ה' יֵלְכוּ כְּאַרְיֵה יִשְׁאָג וְגו'. אָמַר רִבִּי חִזְקִיָּה הָכִי הוּא וַדַּאי.","וְתָּא חֲזֵי, בַּר נָשׁ כַּד צַלֵּי צְלוֹתֵיהּ, לָא יֵימָא עֲלֵיהּ זָכְרֵנִי וּפָקְדֵנִי. בְּגִין דְּאִיכָּא זְכִירָה וּפְקִידָה לְטַב, וּזְכִירָה וּפְקִידָה לְבִישׁ, וְזַמִּינִין לְנַטְלָא מִלָּה מִן פּוּמָא, וְאַתְיָין לְאַדְכָּרָא חוֹבוֹי דְּבַר נָשׁ וְלַעֲנָשָׁא לֵיהּ. בַּר אִי אִיהוּ זַכָּאָה שְׁלִים, דְּכַד בַּדְקֵי חוֹבוֹי, הַהִיא זְכִירָה וּפְקִידָה לְבִישׁ לָא יִשְׁכְּחוּן לוֹן, כְּגוֹן עֶזְרָא דְּאָמַר (נחמיה י״ג:ל״א) זָכְרָה לִי אֱלהַי לְטוֹבָה."],[[0,"רבי יהודה ורבי חזקיה וכו':","ר\"י ור\"ח היו הולכים מקפוטקיא ללוד. והיה ר' יהודה רוכב, ור' חזקיה הלך ברגליו. בתוך זה, ירד ר' יהודה מן החמור, אמר מכאן ולהלאה נעסוק בתורה. כמו שכתוב הבו גודל לאלקינו."],[1,"א\"ל, אלו הוינא וכו':","אמר לו, אלו היינו שלשה, היה טוב, כי אחד היה אומר, ושנים היו משיבים לו. אמר לו, דברים אלו נאמרו רק בברכות, אשר אחד מזכיר שמו של הקב\"ה, ושנים משיבים לו, וזה הוא שכתוב, כי שם ה' אקרא הבו גודל לאלקינו. \u0003כי שם ה' אקרא,\u0004 הוא אחד, המזכיר את השם, \u0003הבו גודל לאלקינו,\u0004 הוא שנים האחרים המשיבים. אבל בתורה, אפילו שנים יושבים ועוסקים בתורה, נותנים גדולה ועוז ותפארת התורה אל הקב\"ה."],[2,"אמר ליה ר' חזקיה וכו':","א\"ל ר\"ח ובברכות למה צריכים לג'. א\"ל הרי בארוה, שאמרו, שכתוב הבו גודל לאלקינו, שצריכים שנים משיבים, כנ\"ל, אבל סוד הדבר, כי סוד כל הברכות הוא כך, אחד לברך ושנים להשיב, כדי להעלות שבח הקב\"ה בסוד ג', דהיינו סוד ג' קוין: אחד מברך, שה\"ס קו אמצעי, שהוא הפועל לגלות האור, ושנים שיודו ויקיימו ברכותיו, שה\"ס ב' הקוין המקבלים פעולת קו אמצעי, ומאירים בכחו. וזהו הקיום של הברכות, שיהיו בסוד העליון כראוי ובסוד שלשה. כמו שבארוה."],[3,"עד דהוו אזלי וכו':","בעוד שהיו הולכים, אמר ר' יהודה למדנו, יש זכירה לטוב, ויש זכירה לרע, יש פקידה לטוב, ויש פקידה לרע. ומפרש, יש זכירה לטוב, הוא כמו שבארוהו, שכתוב, וזכרתי להם ברית ראשונים וגו'. ויזכור אלקים את נח וגו'. ויזכור אלקים את בריתו. ויש זכירה לרע, שכתוב ויזכור כי בשר המה רוח הולך ולא ישוב \u0003פקידה לטב וכו':\u0004 ויש פקידה לטוב, שכתוב, פקד פקדתי אתכם. פקידה לרע שכתוב ופקדתי בשבט פשעם ובנגעים עונם. וכולם הם סודות העליונים."],[4,"כל הני זכירה וכו':","כל אלו זכירה ופקידה לטוב, אלו הם מדרגות ידועות סוד האמונה. זכר ונקבה בסוד אחד, הם זכירה ופקידה. זכירה ה\"ס זכר, ופקידה ה\"ס הנקבה כנ\"ל. ואלו הם לטוב. זכירה ופקידה לרע, אלו הם סוד הצד האחר, הנמצא בסוד אלהים אחרים זכר ונקבה כאחד, זכירה בזה בזכר, ופקידה בזה בנקבה. ואלו הם העומדים תמיד לרע. והם זה לעומת זה, זכר ונקבה דס\"א, לעומת זכר ונקבה דקדושה. מכאן, מזכירה ופקידה דקדושה, יוצאים כל סודות האמונה וכל מדרגות קדושות העליונות כמו שבארוהו, ומכאן, מזכירה ופקידה דס\"א, יוצאים כל מינים הרעים, וכל המות, וכל הצדדים של מינים הרעים שבעולם. ובארוהו וזה הס\"א להיפך מזה, מן הקדושה."],[5,"א\"ר חזקיה וכו':","אר\"ח, כן הוא ודאי, אשרי הוא, מי שחלקו נמצא בצד הטוב, ואינו מטה עצמו לסטרא אחרא, וניצל מהם. אמר ליה ר' יהודה כן הוא ודאי, ואשרי מי שיכול להנצל מאותו הצד, ואשרי הם הצדיקים שיכולים להנצל מהם, ולעשות מלחמה באותו הצד."],[5,"אמר ר' חזקיה וכו':","אר\"ח, במה עושים עמהם מלחמה. פתח ואמר, כי בתחבולות תעשה לך מלחמה וגו', איזה מלחמה, זהו מלחמה של אותו צד הרע, שהאדם צריך לעשות עמו מלחמה, ולמשול עליו, ולהנצל ממנו."],[6,"ת\"ח דיעקב וכו':","בוא וראה, שיעקב היה עושה כל כך כלפי עשו, בשביל להכניע אותו הצד שלו, להערים עליו, וללכת עמו בערמה בכל כמה שצריך, כדי למשול עליו בתחילה ובסוף, שיהיה הכל כראוי. והתחילה והסוף היו כאחד, זה כעין זה, כמו שכתוב בתחלה בכרתי ולבסוף ברכתי שאותיותיהן שוות, (כמ\"ש לעיל תולדות דף ע\"ז ד\"ה ויעקבני עש\"ה) הרי שהתחילה והסוף היו אחד, זה כעין זה, וכל זה היה כדי למשול עליו בדרך הישר כראוי לו. ועל כן אשרי הוא מי שניצל מהם, מס\"א, ויכול למשול עליהם."],[7,"ת\"ח זכירה ופקידה וכו':","בוא וראה, זכירה ופקידה לטוב, היינו בעת שהם כאחד בסוד האמונה, שהיא הנוקבא, כלומר, כשז\"א שה\"ס זכירה והנוקבא שה\"ס פקידה, הם בזווג. ואשרי הוא מי שמשתדל אחר האמונה, לזכות בה, כמו שאתה אומר, אחרי ה' ילכו כאריה ישאג וגו'. אמר ר' חזקיה, כן הוא ודאי."],[8,"ות\"ח","\u0003בר נש כד וכו':\u0004 ובוא וראה, כשאדם מתפלל תפילתו, לא יאמר על עצמו זכרני ופקדני. משום שיש זכירה ופקידה לטוב, וזכירה ופקידה לרע, ועתידים המקטריגים, לקבל המלה זכרני ופקדני, מפיו, ויבואו להזכיר חטאיו של האדם ולענוש אותו, דהיינו שיביאו עליו זכירה ופקידה לרע. זולת אם הוא צדיק גמור, שאם אותו זכירה ופקידה לרע, שהם זו\"ן דקליפה, יבדקו אחר חטאיו ולא ימצאו אותן, אז מותר לו לומר זכרני ופקדני, כמו עזרא, שאמר, זכרה לי אלקי לטובה."]],[[0,"","רַבִּי יְהוּדָה וְרַבִּי חִזְקִיָּה הָיוּ הוֹלְכִים מִקַּפּוֹטְקִיָּא לְלוֹד, וְרַבִּי יְהוּדָה הָיָה רוֹכֵב, וְרַבִּי חִזְקִיָּה עַל רַגְלָיו. בֵּינְתַיִם יָרַד רַבִּי יְהוּדָה. אָמַר, מִכָּאן וָהָלְאָה נִתְעַסֵּק בַּתּוֹרָה, כַּכָּתוּב (דברים לב) הָבוּ גֹדֶל לֵא לֹהֵינוּ."],[1,"","אָמַר לוֹ, אִלּוּ הָיִינוּ שְׁלֹשָׁה - יָפֶה הוּא, שֶׁאֶחָד יֹאמַר - וּשְׁנַיִם יָשִׁיבוּ לוֹ. אָמַר לוֹ, הַדְּבָרִים הַלָּלוּ שֶׁל הַבְּרָכוֹת, מִשּׁוּם שֶׁאֶחָד מַזְכִּיר שֵׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּשְׁנַיִם יָשִׁיבוּ לוֹ. זֶהוּ שֶׁכָּתוּב כִּי שֵׁם ה' אֶקְרָא הָבוּ גֹדֶל לֵאלֹהֵינוּ. כִּי שֵׁם ה' אֶקְרָא - זֶה אֶחָד שֶׁמְּבָרֵךְ. הָבוּ גֹדֶל לֵאלֹהֵינוּ - אֵלּוּ שְׁנַיִם אֲחֵרִים. אֲבָל בַּתּוֹרָה, אֲפִלּוּ שְׁנַיִם יוֹשְׁבִים וְנוֹתְנִים גֹּדֶל וְחֹזֶק שֶׁל שֶׁבַח הַתּוֹרָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא."],[2,"","אָמַר לוֹ רַבִּי חִזְקִיָּה, כְּלַפֵּי הַבְּרָכוֹת לָמָּה שְׁלֹשָׁה? אָמַר לוֹ, הֲרֵי פֵּרְשׁוּהָ וְנִתְבָּאֵר, שֶׁכָּתוּב הָבוּ גֹדֶל לֵאלֹהֵינוּ. אֲבָל סוֹד הַדָּבָר כָּאן, שֶׁהֲרֵי כָּל הַסּוֹדוֹת שֶׁל הַבְּרָכוֹת הוּא כָּךְ - אֶחָד לְבָרֵךְ וּשְׁנַיִם לְהָשִׁיב, כְּדֵי שֶׁיַּעֲלֶה הַשֶּׁבַח שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּסוֹד שֶׁל שְׁלֹשָׁה, אֶחָד מְבָרֵךְ וּשְׁנַיִם (אומרים אמן) שֶׁמּוֹדִים, וְזֶהוּ קִיּוּם הַבְּרָכוֹת, וּבְסוֹד עֶלְיוֹן כָּרָאוּי, וּבַסּוֹד שֶׁל שְׁלֹשָׁה, כְּמוֹ שֶׁבֵּאֲרוּהוּ."],[3,"","בְּעוֹדָם הוֹלְכִים, אָמַר רַבִּי יְהוּדָה, שָׁנִינוּ, יֵשׁ זְכִירָה לְטוֹב וְיֵשׁ זְכִירָה לְרַע, יֵשׁ פְּקִידָה לְטוֹב וְיֵשׁ פְּקִידָה לְרַע. יֵשׁ זְכִירָה לְטוֹב - כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (ויקרא כו) וְזָכַרְתִּי לָהֶם בְּרִית רִאשֹׁנִים וְגוֹ', (בראשית ח) וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ, (שמות ב) וַיִּזְכֹּר אֱלֹהִים אֶת בְּרִיתוֹ. וְיֵשׁ זְכִירָה לְרַע - שֶׁכָּתוּב (תהלים עח) וַיִּזְכֹּר כִּי בָשָׂר הֵמָּה רוּחַ הֹלֵךְ וְלֹא יָשׁוּב. פְּקִידָה לְטוֹב - שֶׁכָּתוּב (שמות ג) פָּקֹד פָּקַדְתִּי אֶתְכֶם. פְּקִידָה לְרַע - שֶׁכָּתוּב (תהלים פט) וּפָקַדְתִּי בְשֵׁבֶט פִּשְׁעָם וּבִנְגָעִים עֲונָם. וְכֻלָּם סוֹדוֹת עֶלְיוֹנִים."],[4,"","כָּל אֵלּוּ - זְכִירָה וּפְקִידָה - לְטוֹב, אֵלּוּ הֵן דְּרָגוֹת יְדוּעוֹת, סוֹד הָאֱמוּנָה, זָכָר וּנְקֵבָה, סוֹד אֶחָד, זְכִירָה וּפְקִידָה, אֵלּוּ הֵם לְטוֹב. זְכִירָה וּפְקִידָה לְרַע אֵלּוּ הֵם הַסּוֹד שֶׁל הַצַּד הָאַחֵר שֶׁעוֹמֵד בְּסוֹד שֶׁל אֱלֹהִים אֲחֵרִים. זָכָר וּנְקֵבָה יַחַד, זְכִירָה בָּזֶה וּפְקִידָה בָּזֶה, וְאֵלּוּ הֵם שֶׁתָּמִיד עוֹמְדִים לְרַע וְאֵלּוּ כְּנֶגֶד אֵלּוּ. מִכָּאן יוֹצְאִים כָּל סוֹדוֹת הָאֱמוּנָה וְכָל הַקְּדֻשּׁוֹת הָעֶלְיוֹנוֹת, כְּמוֹ שֶׁבֵּאֲרוּהָ, וּמִכָּאן יוֹצְאִים כָּל הַמִּינִים הָרָעִים וְכָל מָוֶת וְכָל הַצְּדָדִים וְהַמִּינִים הָרָעִים בָּעוֹלָם, וּבֵאֲרוּהָ, וְזֶה בְּהִפּוּךְ מִזֶּה."],[5,"","אָמַר רַבִּי חִזְקִיָּה, כָּךְ זֶה וַדַּאי. אַשְׁרֵי הוּא מִי שֶׁחֶלְקוֹ מִתְקַיֵּם בַּצַּד הַטּוֹב וְלֹא יַרְכִּין עַצְמוֹ לְצַד אַחֵר וְיִנָּצֵל מֵהֶם. אָמַר לוֹ רַבִּי יְהוּדָה, כָּךְ זֶה וַדַּאי, וְאַשְׁרֵי מִי שֶׁיָּכוֹל לְהִנָּצֵל מִמֶּנּוּ מֵהַצַּד הַהוּא, וְאַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיְּכוֹלִים לְהִנָּצֵל מֵהֶם וּלְהִלָּחֵם קְרָב עִם אוֹתוֹ הַצַּד. אָמַר רַבִּי חִזְקִיָּה, בַּמֶּה? פָּתַח וְאָמַר, (משלי כד) כִּי בְתַחְבֻּלוֹת תַּעֲשֶׂה לְּךְ מִלְחָמָה. מִי הַמִּלְחָמָה? זוֹ הַמִּלְחָמָה שֶׁל אוֹתוֹ הַצַּד הָרָע שֶׁצָּרִיךְ אָדָם לְהִלָּחֵם בּוֹ קְרָב וְלִשְׁלֹט עָלָיו וּלְהִנָּצֵל מִמֶּנּוּ."],[6,"","בֹּא רְאֵה שֶׁיַּעֲקֹב כָּךְ הִשְׁתַּדֵּל אֵצֶל עֵשָׂו מִשּׁוּם אוֹתוֹ הַצַּד שֶׁלּוֹ, לְהִתְחַכֵּם עָלָיו וְלָלֶכֶת עִמּוֹ בְּעַקְמוּמִיּוֹת בְּכָל מַה שֶּׁצָּרִיךְ כְּדֵי לִשְׁלֹט עָלָיו בָּרֹאשׁ וּבַסּוֹף, וְהַכֹּל כָּרָאוּי, וְהָרֹאשׁ וְהַסּוֹף יַחַד זֶה כְּמוֹ זֶה, כַּכָּתוּב בְּכֹרָתִי, וְאַחַר כָּךְ בִּרְכָתִי. הָרֵאשִׁית וְהַסּוֹף יַחַד זֶה כְּמוֹ זֶה, כְּדֵי לִשְׁלֹט עָלָיו בְּדֶרֶךְ יְשָׁרָה כָּרָאוּי לוֹ, וּמִשּׁוּם כָּךְ צַדִּיק הוּא מִי שֶׁנִּצָּל מֵהֶם וְיָכוֹל לִשְׁלֹט עֲלֵיהֶם."],[7,"","בֹּא רְאֵה, זְכִירָה וּפְקִידָה לְטוֹב הֵם כְּאֶחָד בְּסוֹד הָאֱמוּנָה, וְאַשְׁרֵי הוּא מִי שֶׁמִּשְׁתַּדֵּל אַחַר הָאֱמוּנָה, כְּמוֹ שֶׁנֶּאֱמַר (הושע יא) אַחֲרֵי ה' יֵלְכוּ כְּאַרְיֵה יִשְׁאָג וְגוֹ'. אָמַר רַבִּי חִזְקִיָּה, כָּךְ הוּא וַדַּאי."],[8,"","וּבֹא וּרְאֵה, כְּשֶׁאָדָם מִתְפַּלֵּל תְּפִלָּתוֹ, אַל יֹאמַר עָלֶיהָ זָכְרֵנִי וּפָקְדֵנִי, מִשׁוּם שֶׁיֵּשׁ זְכִירָה וּפְקִידָה לְטוֹב, וּזְכִירָה וּפְקִידָה לְרַע, וַעֲתִידִים לִטֹּל אֶת הַדִּבּוּר מִפִּיו, וּבָאִים לְהַזְכִּיר חֲטָאֵי הָאָדָם וּלְהַעֲנִישׁוֹ. פְּרָט אִם הוּא צַדִּיק שָׁלֵם, שֶׁכַּאֲשֶׁר בּוֹדְקִים אֶת חֲטָאָיו, אוֹתָהּ זְכִירָה וּפְקִידָה לְרַע לֹא יִמְצְאוּ אוֹתָם, כְּמוֹ עֶזְרָא שֶׁאָמַר זָכְרָה לִי אֱלֹהַי לְטוֹבָה."]]],[["דְּהָא בְּכָל אֲתַר, דְּבַר נָשׁ צַלֵּי צְלוֹתֵיהּ, יַכְלִיל גַּרְמֵיהּ בֵּין סַגִּיאִין בִּכְלָלָא דְסַגִּיאִין. וְתָא חֲזֵי שׁוּנַמִּית, כַּד אָמַר לָהּ אֱלִישָׁע, (מלכים ב ד׳:י״ג) הֲיֵשׁ לְדַבֵּר לָךְ אֶל הַמֶּלֶךְ אוֹ אֶל שַׂר הַצָּבָא. הֲיֵשׁ לְדַבֵּר לָךְ אֶל הַמֶּלֶךְ, הַהוּא יוֹמָא, יוֹם טוֹב דְּרֹאשׁ הַשָּׁנָה הֲוָה, וְהַהוּא יוֹמָא דְמַלְכוּתָא דִרְקִיעָא שָׁלְטָא לְמֵידַן עַלְמָא, וְקוּדְשָׁא בְּרִיךְ הוּא אִקְרֵי מֶלֶךְ הַמִּשְׁפָּט בְּהַהוּא זִמְנָא. וּבְגִין כָּךְ אָמַר לָהּ, הֲיֵשׁ לְדַבֵּר לָךְ אֶל הַמֶּלֶךְ.","מַה כְּתִיב, (מלכים ב ד׳:י״ג) וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יוֹשֶׁבֶת. מַאי קָאָמְרָה. לָא בָעֵינָא, לְמֶהֱוֵי רְשִׁימָאָה לְעֵילָא, אֶלָּא לְאַעֲלָאָה רֵישָׁאי בֵּין סַגִּיאִין, וְלָא לְאֲפָקָא מִכְּלָלָא דִלְהוֹן. וְכָךְ בָּעֵי לֵיהּ לְבַר נָשׁ, לְאִתְכְּלָלָא בִּכְלָלָא דְסַגִּיאִין וְלָא לְאִתְיַיחֲדָא בִּלְחוֹדוֹי, בְּגִין דְּלָא יִשְׁגְּחוּן עֲלֵיהּ, לְאַדְכָּרָא חוֹבוֹי כִּדְקָאֲמָרָן.","פָּתַח רִבִּי יְהוּדָה וְאָמַר (איוב ל״ח:י״ז) הֲנִגְלוּ לְךָ שַׁעֲרֵי מָוֶת וְשַׁעֲרֵי צַלְמָוֶת תִּרְאֶה. הַאי קְרָא, קוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ לְאִיּוֹב, כַּד חָמָא דְּאִיּוֹב דָּחִיק גַרְמֵיהּ עַל דִּינוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא. תָּא חֲזֵי, אִיּוֹב אָמַר (איוב י״ג:ט״ו) הֵן יִקְטְלֵנִי לוֹ אֲיַחֵל, כְּתִיב לא בְּאל\"ף וְקָרֵי לוֹ בְּוא\"ו, וְכֹלָּא אִיהוּ.","אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְכִי אֲנָא קָטִיל בְּנֵי נָשָׁא, הֲנִגְלוּ לְךָ שַׁעֲרֵי מָוְת וְשַׁעֲרֵי צַלְמָוֶת תִּרְאֶה, כַּמָּה תַּרְעִין אִינוּן פְּתִיחָן בְּהַהוּא סִטְרָא. וּמוֹתָא שָׁלְטָא עֲלַיְיהוּ, וְכֻלְּהוּ סְתִימִין מִבְּנֵי נָשָׁא, (ס\"א ולא יכלין לאסתמרא מנייהו בגין דאינון סתימין מבני נשא) וְלָא יָדְעִין אִינוּן שְׁעָרִים.","וְשַׁעֲרֵי צַלְמָוֶת תִּרְאֶה. מַאן אִינוּן שַׁעֲרֵי מָוֶת ומַאן אִינוּן שַׁעֲרֵי צַלְמָוֶת. אֶלָּא מָוֶת וְצַלְמָוֶת כְּחֲדָא אִינוּן, וְזִוּוּגָא חָדָא אִינוּן. מָוֶת הָא אִתְּמָר, דָּא מַלְאַךְ הַמָּוְת, וְהָא אוּקְמוּהָ. צַלְמָוֶת, צֵל מָוֶת. הַאי אִיהוּ מַאן דְּרָכִיב עֲלֵיהּ, וְאִיהוּ צִלָּא דִילֵיהּ, וְתוּקְפָא דִילֵיהּ, לְאִזְדַּוְּוגָא כְּחֲדָא, בְּקִשּׁוּרָא חַד וְאִינוּן חַד.","וְכָל אִינוּן דַּרְגִּין דְּנָפְקֵי מִנַּיְיהוּ וּמִתְקַשְּׁרָן בְּהוּ אִינוּן שְׁעָרִים דִּלְהוֹן כְּמָה דִלְעֵילָא, כְּמָה דְאַתְּ אָמֵר, (תהילים כ״ד:ז׳) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְגו'. וְאִלֵּין (אינון שערים) אִיקְּרוּ נַהֲרִין וְנַחֲלִין, שִׁית סִטְרִין דְּעָלְמָא. אוּף הָכִי אִינוּן שַׁעֲרֵי מָוֶת, וְשַׁעֲרֵי צַלְמָוֶת מִסִּטְרָא אָחֳרָא, דַּרְגִּין יְדִיעָן דְּשָׁלְטִין בְּעַלְמָא. שַׁעֲרֵי מָוְת וְשַׁעֲרֵי צַלְמָוֶת, דָּא נוּקְבָא וְדָא דְכוּרָא, וְתַרְוַויְיהוּ כְּחֲדָא.","וְעַל דָּא, אָמַר קוּדְשָׁא בְּרִיךְ הוּא לֵיה לְאִיּוֹב, בְּגִין כָּל אִינוּן מִלִּין, דְּאִיהוּ אָמַר (איוב ז׳:ט׳) כָּלָה עָנָן וַיֵּלַךְ כֵּן יוֹרֵד שְׁאוֹל לֹא יַעֲלֶה, וְכָל אִינוּן שְׁאָר מִלִּין. אָמַר קוּדְשָׁא בְּרִיךְ הוּא הֲנִגְלוּ לְךָ שַׁעֲרֵי מָוֶת, לְמִנְדַע דְּהָא כֻּלְּהוּ בִּרְשׁוּתִי, וְכֻלְּהוּ זְמִינִין לְאִתְבַּעֲרָא מֵעַלְמָא, דִּכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוְת לָנֶצַח וְגו'.","תָּא חֲזֵי, (בראשית ל׳:כ״ב-כ״ג) וַיִּזְכֹּר אֱלהִים אֶת רָחֵל וַיִּשְׁמַע אֵלֶיהָ אֱלהִים וַיִפְתַּח אֶת רַחֲמָהּ. תְּרֵי זִמְנִין, אֱלֹהִים אֱלהִים, אַמַּאי. אֶלָּא, חַד מֵעַלְמָא דִּדְכוּרָא, וְחַד מֵעַלְמָא דְנוּקְבָא, בְּגִין דִּבְמַזָּלָא תַּלְיָיא מִלְּתָא.","וְכַד אִתְעָרַת רָחֵל בִּשְׁמָא דָא, דִּכְתִיב, (בראשית ל׳:כ״ד) יוֹסֵף ה' לִי בֵּן אַחֵר, יָדַע יַעֲקֹב דְּאִיהִי אִתְחַזְּיָיא לְאַשְׁלָמָא כֻּלְּהוּ שִׁבְטִין וְלָא תִתְקַיֵּים בְּעַלְמָא, בְּגִין כָּךְ בָּעָא לְמֵיזַל וְלָא יָכִיל. וְכַד מָטָא זִמְנָא דְּבִנְיָמִין, עָרַק וְאֲזַל לֵיהּ, בְּגִין דְּבְאַרְעָא אָחֳרָא לָא יִשְׁתְּלַם בֵּיתָא, לְאִתְקַשְּׁרָא עַלְמָא קַדִּישָׁא בֵּיהּ.","וְהַיְינוּ דִּכְתִיב, (בראשית ל״א:ג׳) וַיֹּאמֶר ה' אֶל יַעֲקֹב שׁוּב אֶל אֶרֶץ אֲבוֹתֶיךָ וּלְמוֹלַדְתֶּךָ וְאֶהְיֶה עִמָּךְ. מַאי וְאֶהְיֶה עִמָּךְ. אֶלָּא אָמַר לֵיהּ, עַד הָכָא, רָחֵל הֲוַת עִמָּךְ עִקְּרָא דְבֵיתָא. מִכָּאן וּלְהָלְאָה, אֲנָא אֱהֵא עִמָּךְ וֶאֱטוֹל בֵּיתָא בַּהֲדָךְ בִּתְרֵיסַר שִׁבְטִין. וְהַיְינוּ דִכְתִיב, וַאֲנִי בְּבֹאִי מִפַּדָּן מֵתָה עָלַי רָחֵל. עָלַי הֲוָה, וּבְגִינִי הֲוָה מִלָּה דְּאִתְדַּחְיָא אִיהִי וְאַתְיָא דִיּוּרָא אָחֳרָא, וְנָטְלָא בֵיתָא בְּגִינִי לְדָיְירָא עִמִּי.","(בראשית ל׳:כ״ח) וַיֹּאמֶר נָקְבָה שְׂכָרְךָ עָלַי וְאֶתֵּנָה, מַאי נָקְבָה. אָמַר רִבִּי יִצְחָק, הַהוּא רָשָׁע אָמַר, אֲנָא חָמֵי, דְּיַעֲקֹב לָא אִסְתַּכֵּל אֶלָּא בְּנוּקְבֵי, וּבְגִין כָּךְ יִפְלַח לִי. אָמַר נָקְבָה שְׂכָרְךָ, הָא נְקֵבָה דְּאִיהוּ שְׂכָרְךָ כַּד בְּקַדְמִיתָא. וְאֶתֵּנָה, אֵימָא מַאן נְקֵבָה אִסְתַּכַּלְתְּ בָּהּ, וְאֶתֵּנָה, וּפְלַח לִי בְּגִינָהּ."],[[0,"דהא בכל אתר וכו':","כי בכל מקום שאדם מתפלל תפלתו יכלול את עצמו בין הרבים, בתוך כלל הרבים. ובוא וראה, שונמית, כשאמר לה אלישע היש לדבר לך אל המלך או אל שר הצבא. \u0003היש לדבר לך אל המלך,\u0004 פירושו, כי אותו יום היה יום טוב של ראש השנה, ואותו יום שמלכות הרקיע שולט לדון את העולם. והקב\"ה נקרא באותו זמן \u0003מלך המשפט.\u0004 ומשום זה אמר לה, היש לדבר לך אל המלך. שקרא את הקב\"ה בשם מלך."],[1,"מה כתיב, ותאמר וכו':","מה כתוב, ותאמר בתוך עמי אנכי יושבת. שואל, מה אמרה, מה כונתה בזה. ומשיב, שאמרה, איני רוצה להיות מצוינת למעלה אלא להכניס את ראשי בין הרבים, ולא לצאת מן הכלל. וכן צריך האדם להכלל בכלל הרבים, ולא להתיחד בפני עצמו, כדי שלא יביטו עליו המקטריגים להזכיר את חטאיו, כמו שאמרנו."],[2,"פתח ר' יהודה וכו':","פתח ר\"י ואמר, הנגלו לך שערי מות ושערי צלמות תראה, זה אמר הקב\"ה לאיוב. כשהיה מצער את עצמו על דיניו של הקב\"ה. בוא וראה איוב אמר, הן יקטלני לו איחל. כתוב לא באלוף, וקוראים לו עם \u0003ו'\u0004 והכל הוא בו, כלומר שיש בו ב' ההוראות, דהיינו שאמר גם כן, אם יקטל אותו לא ייחל לו."],[3,"א\"ל קב\"ה וכו':","אמר לו הקב\"ה, וכי אני הורג בני אדם, הנגלו לך שערי מות ושערי צלמות תראה, כמה שערים הם פתוחים באותו הצד, שאפשר להנצל מהמות על ידיהם, ומכל מקום המות שולט עליהם. כי כולם סתומים מבני אדם, ואינם יודעים משערים אלו. ולעתיד לבא כשיקוים ומלאה הארץ דעה, ואמר באמת בלע המות לנצח כמ\"ש להלן. ונמצא שהם מתים מחמת שאינם יודעים להזהר, ולא שהקב\"ה הורג אותם."],[4,"ושערי צלמות תראה:","שואל, מי המה שערי מות, ומי המה שערי צלמות. ומשיב. אלא מות וצלמות כאחד הם, וזווג אחד הם, כלומר שהם זכר ונקבה בזווג כאחד, \u0003מות\u0004 הרי למדנו שהוא מלאך המות, ובארוהו. שה\"ס הנחש שהוא נקבה, (כנ\"ל ב\"א דף שכ\"ט ד\"ה תנינא) \u0003צלמות\u0004 הוא נוטריקון \u0003צל מות,\u0004 וזה הוא מי שרוכב על המות, דהיינו ס\"מ הרוכב על הנחש, והוא הצל שלו ותוקף שלו, להזדווג ביחד בקשר אחד, והם אחד."],[5,"וכל אינון דרגין וכו':","וכל אלו המדרגות ויוצאות מהם ומתקשרות בהם, בזו\"ן דקליפה הללו, הן השערים שלהם, כמו למעלה בקדושה, כמש\"א, שאו שערים ראשיכם וגו' שאלו הם הנקראים נהרים ונחלים דהיינו יסודות דשש קצוות העולם, שהם זו\"ן דקדושה. אף כאן, שערי מות ושערי צלמות מסטרא אחרא, הם מדרגות ידועות שלהם השולטות בעולם. \u0003שערי מות. ושערי צלמות,\u0004 זה נקבה וזה זכר, ושניהם דבוקים זה בזה כאחד."],[6,"ועל דא אמר קב\"ה וכו':","ועל כן אמר הקב\"ה לאיוב על כל הדברים שהוא אמר, דהיינו על מה שאמר, כלה ענן וילך כן יורד שאול לא יעלה, וכל שאר דבריו, אמר לו הקב\"ה, הנגלו לך שערי מות, לדעת שכולם הם ברשותי, וכולם עתידים להתבלע מן העולם, שכתוב, בלע המות לנצח וגו'. דהיינו כמ\"ש לעיל בד\"ה א\"ל קב\"ה, ע\"ש."],[7,"תא חזי, ויזכור אלקים וגו':","שואל, למה כתוב כאן ב' פעמים אלקים, שהיה די לומר, וישמע אליה ויפתח את רחמה. ומשיב, אלא אחד הוא מעולם הזכר, דהיינו בינה הנקראת אלקים. ואחד הוא מעולם הנקבה, דהיינו הנוקבא דז\"א הנקראת ג\"כ אלקים. משום שהדבר תלוי במזל, שהיא מעולם הזכר, כמ\"ש לעיל שבנים במזל תלוים (בדף פ\"ה אות ר')."],[8,"וכד אתערה רחל וכו':","וכאשר נתעוררה רחל בשם הזה של בנימין, שכתוב, יוסף ה' לי בן אחר, שהוא בנימין. ידע יעקב, שיהיה כן כי היא ראויה להשלים כל השבטים במספר י\"ב. וידע שאחר זה, לא תתקיים עוד בעולם, משום זה רצה אז ללכת לארץ ישראל כדי שישלמו השבטים בארץ ישראל, וכדי שלא תמות רחל בחוץ לארץ. ולא יכול ללכת כי לבן עכבו. וכשהגיע הזמן של בנימין דהיינו אחר שנתעברה עמו (כנ\"ל דף ק\"ב אות ר\"נ) ברח והלך לו, כדי שלא ישתלם הבית בי\"ב שבטים, ועולם הקדוש, דהיינו הנוקבא דז\"א, יתקשר בו בארץ אחרת."],[9,"והיינו דכתיב וכו':","והיינו שכתוב, ויאמר ה' אל יעקב שוב וגו' ואהיה עמך. ושואל מה הפירוש של \u0003ואהיה עמך.\u0004 ומשיב אלא אמר לו הקב\"ה, עד עתה, היתה רחל עקרת הבית עמך, מכאן ואילך, אני אהיה עמך ואקח הבית, דהיינו השכינה, עמך, בי\"ב השבטים. והיינו שכתוב, ואני בבואי מפדן מתה \u0003עלי\u0004 רחל, \u0003עלי\u0004 היה, ובשבילי היה הדבר, שרחל נדחית, ושכן אחר בא, דהיינו השכינה, ולקח הבית בשבילי לשכון עמי."],[10,"ויאמר נקבה שכרך וגו':","שואל מהו נקבה. אמר ר' יצחק אותו הרשע אמר, אני רואה שיעקב אינו מסתכל רק בנקבות, ומשום זה יעבוד לי, ע\"כ אמר נקבה שכרך. הנה \u0003נקבה\u0004 תהיה שכרך, כמו בתחילה. \u0003ואתנה,\u0004 אמור, באיזו נקבה הסתכלת בה, \u0003ואתנה\u0004 אותה לך, ותעבוד לי בשבילה."]],[[0,"","שֶׁהִנֵּה בְּכָל מָקוֹם שֶׁאָדָם מִתְפַּלֵּל תְּפִלָּתוֹ, יִכְלֹל אֶת עַצְמוֹ בֵּין רַבִּים, בַּכְּלָל שֶׁל הָרַבִּים. וּבֹא וּרְאֵה, הַשּׁוּנַמִּית, כַּאֲשֶׁר אָמַר לָהּ אֱלִישָׁע (מלכים ב ד) הֲיֵשׁ לְדַבֶּר לָךְ אֶל הַמֶּלֶךְ אוֹ אֶל שַׂר הַצָּבָא, הֲיֵשׁ לְדַבֶּר לָךְ אֶל הַמֶּלֶךְ - אוֹתוֹ הַיּוֹם הָיָה יוֹם טוֹב שֶׁל רֹאשׁ הַשָּׁנָה, וְאוֹתוֹ הַיּוֹם שֶׁשּׁוֹלֶטֶת מַלְכוּת הָרָקִיעַ לָדוּן אֶת הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא הַמֶּלֶךְ הַמִּשְׁפָּט בְּאוֹתוֹ הַזְּמַן, וּמִשּׁוּם כָּךְ אָמַר לָהּ הֲיֵשׁ לְדַבֶּר לָךְ אֶל הַמֶּלֶךְ."],[1,"","מַה כָּתוּב? וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יֹשָׁבֶת. מָה אָמְרָה? לֹא רוֹצָה לִהְיוֹת רְשׁוּמָה לְמַעְלָה, אֶלָּא לְהַכְנִיס אֶת רֹאשִׁי בֵּין רַבִּים, וְלֹא לָצֵאת מֵהַכְּלָל שֶׁלָּהֶם. וְכָךְ צָרִיךְ לְאָדָם לְהִכָּלֵל בִּכְלָל שֶׁל רַבִּים וְלֹא לְהִתְיַחֵד לְבַדּוֹ, כְּדֵי שֶׁלֹּא יַשְׁגִּיחוּ עָלָיו לְהַזְכִּיר חֲטָאָיו, כְּמוֹ שֶׁאָמַ רְנוּ."],[2,"","פָּתַח רַבִּי יְהוּדָה וְאָמַר, (איוב לח) הֲנִגְלוּ לְךְ שַׁעֲרֵי מָוֶת וְשַׁעֲרֵי צַלְמָוֶת תִּרְאֶה. הַפָּסוּק הַזֶּה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאִיּוֹב כְּשֶׁרָאָה שֶׁאִיּוֹב דּוֹחֵק עַצְמוֹ עַל דִּין הַקָּדוֹשׁ בָּרוּךְ הוּא. בֹּא רְאֵה, אִיּוֹב אָמַר הֵן יִקְטְלֵנִי לוֹ אֲיַחֵל. כָּתוּב לֹא בְּאָלֶ\"ף, וְקוֹרְאִים לוֹ בְּוָא\"ו, וְהַכֹּל הוּא."],[3,"","אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכִי אֲנִי הוֹרֵג בְּנֵי אָדָם!? הֲנִגְלוּ לְךְ שַׁעֲרֵי מָוֶת וְשַׁעֲרֵי צַלְמָוֶת תִּרְאֶה!? כַּמָּה שְׁעָרִים פְּתוּחִים בְּאוֹתוֹ הַצַּד, וְהַמָּוֶת שׁוֹלֵט עֲלֵיהֶם, וְכֻלָּם סְתוּמִים מִבְּנֵי אָדָם, (ולא יכולים להשמר מהם משום שהם סתומים מבני אדם) שֶׁלֹּא מַכִּירִים אֶת אוֹתָם הַשְּׁעָרִים."],[4,"","וְשַׁעָרֵי צַלְמָוֶת תִּרְאֶה. מִי הֵם שַׁעֲרֵי מָוֶת וּמִי הֵם שַׁעֲרֵי צַלְמָוֶת? אֶלָּא מָוֶת וְצַלְמָוֶת הֵם יַחַד, וְהֵם זִוּוּג אֶחָד. מָוֶת - הֲרֵי נִתְבָּאֵר, זֶה מַלְאַךְ הַמָּוֶת, וַהֲרֵי פֵּרְשׁוּהָ. צַלְמָוֶת - צֵל מָוֶת, זֶהוּ מִי שֶׁרוֹכֵב עָלָיו, וְהוּא הַצֵּל שֶׁלּוֹ וְהַכֹּחַ שֶׁלּוֹ לְהִזְדַּוֵּג יַחַד בְּקֶשֶׁר אֶחָד, וְהֵם אֶחָד."],[5,"","וְכָל אוֹתָם הַדְּרָגוֹת שֶׁיּוֹצְאוֹת מֵהֶם וְנִקְשָׁרוֹת בָּהֶם הֵם הַשְּׁעָרִים שֶׁלָּהֶם, כְּמוֹ שֶׁלְּמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כד) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְגוֹ'. וְאֵלּוּ (אותם שערים) נִקְרָאִים נְהָרוֹת וּנְחָלִים. שֵׁשֶׁת הַצְּדָדִים שֶׁל הָעוֹלָם, אַף כָּךְ הֵם שַׁעֲרֵי מָוֶת, וְשַׁעֲרֵי צַלְמָוֶת מֵהַצַּד הָאַחֵר, דְּרָגוֹת יְדוּעוֹת שֶׁשּׁוֹלְטוֹת בָּעוֹלָם. שַׁעֲרֵי מָוֶת וְשַׁעֲרֵי צַלְמָוֶת - זֶה נְקֵבָה וְזֶה זָכָר, וּשְׁנֵיהֶם יַחַד."],[6,"","וְעַל זֶה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאִיּוֹב בִּשְׁבִיל כָּל אוֹתָם דְּבָרִים שֶׁהוּא אָמַר, (איוב ז) כָּלָה עָנָן וַיֵּלַךְ כֵּן יוֹרֵד שְׁאוֹל לֹא יַעֲלֶה, וְכָל אוֹתָם שְׁאָר דְּבָרִים. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, הֲנִגְלוּ לְךְ שַׁעֲרֵי מָוֶת, לָדַעַת שֶׁהֲרֵי הַכֹּל בִּרְשׁוּתִי, וְכֻלָּם עֲתִידִים לְהִתְבַּעֵר מִן הָעוֹלָם, שֶׁכָּתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח וְגוֹ'."],[7,"","בֹּא רְאֵה, וַיִּזְכֹּר אֱלֹהִים אֶת רָחֵל וַיִּשְׁמַע אֵלֶיהָ אֱלֹהִים וַיִּפְתַּח אֶת רַחְמָהּ. פַּעֲמַיִם אֱלֹהִים אֱלֹהִים, לָמָּה? אֶלָּא אֶחָד מֵעוֹלַם הַזָּכָר, וְאֶחָד מֵעוֹלַם הַנְּקֵבָה, מִשּׁוּם שֶׁהַדָּבָר תָּלוּי בְּמַזָּל."],[8,"","וּכְשֶׁמִּתְעוֹרֶרֶת רָחֵל בַּשֵּׁם הַזֶּה, שֶׁכָּתוּב יֹסֵף ה' לִי בֵּן אַחֵר, יָדַע יַעֲקֹב שֶׁהִיא רְאוּיָה לְהַשְׁלִים אֶת כָּל הַשְּׁבָטִים וְלֹא תִתְקַיֵּם בָּעוֹלָם, מִשּׁוּם כָּךְ רָצָה לָלֶכֶת וְלֹא יָכֹל, וּכְשֶׁהִגִּיעַ זְמַנּוֹ שֶׁל בִּנְיָמִין, בָּרַח וְהָלַךְ לוֹ, כְּדֵי שֶׁהַבַּיִת לֹא יִשְׁתַּלֵּם בְּאֶרֶץ אַחֶרֶת, לְהִתְקַשֵּׁר בּוֹ הָעוֹלָם הַקָּדוֹשׁ."],[9,"","וְהַיְנוּ שֶׁכָּתוּב (בראשית לא) וַיֹּאמֶר ה' אֶל יַעֲקֹב שׁוּב אֶל אֶרֶץ אֲבוֹתֶיךְ וּלְמוֹלַדְתֶּךְ וְאֶהְיֶה עִמָּךְ. מַה זֶּה וְאֶהְיֶה עִמָּךְ? אֶלָּא אָמַר לוֹ, עַד כָּאן רָחֵל הָיְתָה עִמְּךְ עִקַּר הַבַּיִת, מִכָּאן וָהָלְאָה אֲנִי אֶהְיֶה עִמְּךְ וְאֶטֹּל אֶת הַבַּיִת עִמְּךְ עִם שְׁנֵים עָשָׂר הַשְּׁבָטִים. וְהַיְנוּ שֶׁכָּתוּב וַאֲנִי בְּבֹאִי מִפַּדָּן מֵתָה עָלַי רָחֵל. עָלַי הָיָה זֶה, וּבִגְלָלִי הָיָה הַדָּבָר שֶׁהִיא נִדְחֲתָה, וּבָאָה דַיֶּרֶת אַחֶרֶת וְנָטְלָה אֶת הַבַּיִת בִּשְׁבִילִי לָדוּר עִמִּי."],[10,"","וַיֹּאמַר נָקְבָה שְׂכָרְךְ עָלַי וְאֶתֵּנָה. מַה זֶּה נָקְבָה? אָמַר רַבִּי יִצְחָק, אוֹתוֹ רָשָׁע אָמַר, אֲנִי רוֹאֶה שֶׁיַּעֲקֹב לֹא מִסְתַּכֵּל אֶלָּא בִּנְקֵבוֹת, וּמִשּׁוּם זֶה יַעֲבֹד אוֹתִי. אָמַר נָקְבָה שְׂכָרְךְ, הִנֵּה נְקֵבָה, שֶׁהִיא שְׂכָרְךְ, כְּבָרִאשׁוֹנָה. וְאֶתֵּנָה, אֱמֹר בְּאֵיזוֹ נְקֵבָה הִסְתַּכַּלְתָּ וְאֶתֵּנָה, וַעֲבֹד אוֹתִי בִּשְׁבִילָהּ."]]],[["(שם) וַיֹּאמֶר יַעֲקֹב לא תִתֵּן לִי מְאוּמָה, אָמַר יַעֲקֹב חָלִילָה, דְּהָא אֲנָא כָּל מַה דְּעֲבִידְנָא, לְשֵׁם יְקָרָא דְמַלְכָּא קַדִּישָׁא עֲבִידְנָא, (ס\"א ולאו לכסופא דגרמאי) וְעַל דָּא לא תִּתֵּן לִי מְאוּמָה, דְּהָא לַאו דַּעְתָּאי בְּהַאי, אֶלָּא אִם תַּעֲשֶׂה לִי (את) הַדָּבָר הַזֶּה וְגו'.","(שם) וַיָּסַר בַּיּוֹם הַהוּא אֶת הַתְּיָשִׁים. רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהילים ט״ו:א׳) יְיָ מִי יָגוּר בְּאָהֳלֶךָ וְגו', הָא אוֹקִימְנָא, וְאוּקְמוּהָ חַבְרַיָיא, (שם) הוֹלֵךְ תָּמִים, דָּא אַבְרָהָם, דְּכַד אִתְגְּזַר תָּמִים אִקְרֵי. וּפוֹעֵל צֶדֶק, דָּא יִצְחָק. וְדוֹבֵר אֱמֶת, דָּא יַעֲקֹב. וַדַּאי יַעֲקֹב בֶּאֱמֶת אִתְדָּבַּק, אִי הוּא בֶּאֱמֶת אִתְדָּבַּק, מַאי טַעֲמָא עֲבַד עִם לָבָן כְּגַוְונָא דָא.","אֶלָא, יַעֲקֹב בָּחִין שַׁעְתָּא דְמַזְּלֵיהּ הֲוָה. דְּשָׁרֵי לֵיהּ לְאֵינַשׁ, לְמִבְחַן שַׁעְתֵּיהּ, עַד לָא יָתוּב לְאַרְעֵיהּ, וְאִי מַזָּלֵיהּ קָאִים בְּמָּה דְּעֲבִיד שַׁפִּיר, וְאִי לָאו לָא יוֹשִׁיט רַגְלוֹי עַד דְּיִסְלַק (ס\"א דקאים במה דעביד) לְגַבֵּיהּ.","תָּא חֲזֵי, כְּתִיב, (בראשית ל׳:ל״ג) וְעָנְתָה בִּי צִדְקָתִי בְּיוֹם מָחָר וְגו', דְּהָא אִיהוּ לָא עֲבַד בְּגִין דְּיִטּוֹל מִדִּילֵיהּ לְמַגָּנָא, אֶלָּא כֹּלָּא בְּקוּשְׁטָא וּשְׁלִימוּ דִּרְעוּתָא, וְלָא עוֹד אֶלָּא דְּאִיהוּ נָטִיל רְשׁוּ מִלָּבָן, וְעַל דָּא כְּתִיב, (בראשית ל׳:כ״ז) נִחַשְׁתִּי וַיְבָרַכֵנִי יְיָ בִּגְלָלֶךָ. כַּמָּה חֳרָשִׁין וְזִינִין עֲבַד לָבָן, וּבָחִין מַזָּלֵיהּ בְּגִינֵיהּ דְּיַעֲקֹב, וְהֲוָה אַשְׁכַּח בְּגִינֵיהּ דְּיַעֲקֹב, מְאָה עָאנָא כָּל יַרְחָא, וּמְאָה אִמְרִין וּמְאָה עִזִּין יַתִּיר עַל עָאנֵיהּ.","רַבִּי אַבָּא אָמַר, אֶלֶף עָאנִין, וְאֶלֶף אִמְרִין, וְאֶלֶף עִזִּין, הֲוָה מַיְיתֵי לֵיהּ יַעֲקֹב יַתִּיר בְּכָל יַרְחָא וְיַרְחָא. הֲדָא הוּא דִכְתִיב, (בראשית ל׳:ל׳) כִּי מְעַט אֲשֶׁר הָיָה לְךָ לְפָנַי וַיִּפְרֹץ לָרֹב וַיְבָרֶךְ יְיָ אוֹתְךָ לְרַגְלִי, וּבִרְכְתָא דִלְעֵילָא לָאו אִיהוּ פָּחוֹת מֵאֶלֶף מִכָּל זִינָא וְזִינָא, מֵעָאנִין אֶלֶף אִשְׁתַּכַּח, מֵאִמְרִין אֶלֶף אִשְׁתַּכַּח, מֵעִזִּין אֶלֶף אִשְׁתַּכַּח. עַל כָּל מַה דְּשַׁרְיָא בִּרְכְתָא דִלְעֵילָא, לָא פָּחוֹת מֵאֶלֶף. עַד דִּבְגִינֵיהּ דְּיַעֲקֹב אִסְתַּלַּק לָבָן לְכַמָּה עוּתְרָא.","וְכַד בָעָא יַעֲקֹב לְנַטְלֵיהּ אַגְרֵיהּ, לָא אַשְׁכַּח אֶלָּא עֲשָׂרָה מִכָּל זִינָא וְזִינָא, וְיַעֲקֹב חָשִׁיב לֵיהּ לְעוּתְרָא סַגִּי. חָמֵי כַּמָּה נָטִיל מִדִּילֵיהּ, מִמַּה דְּהֲוָה יָהִיב אִיהוּ בִּזְכוּתֵיהּ לְלָבָן. וְכָל דָּא דְּסָלִיק בֵּיהּ יַעֲקֹב, לָא הֲוָה אֶלָּא בִּזְרוֹעַ דְּאִינוּן מַקְלוֹת, דְּשַׁוֵּי לְגַבֵּי עָנָא.","תָּא חֲזֵי, כַּמָּה טָרַח הַהוּא שְׁלֵימָא דְיַעֲקֹב, אֲבַתְרֵיהּ דְּלָבָן. כְּתִיב, (בראשית ל) וַיָּשֶׂם דֶּרֶךְ שְׁלשֶׁת יָמִים וְגו', וְהֲוָה אַיְיתֵי לֵיהּ כָּל הַאי עוּתְרָא. וְעִם כָּל דָּא, לָא בָעָא לָבָן דִּיהֵא אַגְרֵיהּ דְּיַעֲקֹב הָכִי, אֶלָּא נְטַל עֲשָׂרָה מִן דָּא וַעֲשָׂרָה מִן דָּא וְיָהַב (בידא דבני) לֵיהּ. וְאָמַר לֵיהּ טוֹל הַנֵּי. וְאִי יוֹלִידוּ כְּמָה דַאֲמַרְתְּ, בְּהַאי גַוְונָא יְהֵא אַגְרָךְ. הֲדָא הוּא דִכְתִיב, (בראשית ל) וַתַּחְלֵף אֶת מַשְׂכּוּרְתִּי עֲשֶׂרֶת מוֹנִים, (ובהני) עֲשָׂרָה מִן דָּא וַעֲשָׂרָה מִן דָּא, וּכְתִיב, (בראשית ל) וַאֲבִיכֶן הֵתֶל בִּי וְהֶחֱלִיף אֶת מַשְׂכּוּרְתִּי עֲשֶׂרֶת מוֹנִים. (ובהני עשרה) אִשְׁתַּדַּל בָּתַר קוּדְשָׁא בְּרִיךְ הוּא, וּבָרְכֵיהּ. וּמִכָּל מַה דְּשַׁוֵּי לָבָן עִמֵּיהּ דְּיַעֲקֹב, אַהֲדַר בְּמִלּוּלֵיהּ, וְנָטִיל מִיַּעֲקֹב כֹּלָּא, עַד דְּקוּדְשָׁא בְּרִיךְ הוּא חָס עֲלֵיהּ, וְנָטַל מִדִּילֵיהּ בִּזְרוֹעַ.","אָמַר רִבִּי אֶלְעָזָר כָּל הַנֵּי קְרָאֵי, לְאַחֲזָאָה חָכְמָתָא קָא אַתְיָין. דְּתָנִינָן מִלִּין דִּלְעֵילָא, מִנְּהוֹן תַּלְיָין בְּעוֹבָדָא, וּמִנְהוֹן בְּמִלּוּלָא וּמִנְּהוֹן בִּרְעוּתָא דְלִבָּא. וּמַאן דְּבָעֵי לְאַמְשָׁכָא בִּרְכָאן, בִּצְלוֹתָא, בְּמִלּוּלָא, וּרְעוּתָא. וּמִנְּהוֹן דְּלָא בִּצְלוֹתָא, אֶלָּא בְּעוֹבָדָא תַּלְיָין.","תָּא חֲזֵי, יַעֲקֹב שְׁלִים, כָּל מַה דְּעֲבַד, בְּחָכְמְתָא עָבִיד, כְּתִיב (בראשיתל) וַיַּצֵּג אֶת הַמַּקְלוֹת אֲשֶׁר פִּצֵּל בָּרְהָטִים בְּשִׁקַּתוֹת הַמַּיִם, כֹּלָּא בְּחָכְמְתָא, לְאַמְשָׁכָא בִּרְכָאן מִמַּבּוּעָא דְכֹלָּא, לְכֻלְּהוּ דַּרְגִּין עִלָּאִין דְּאִינוּן חוּלָקֵיהּ וְעַדְבֵיהּ.","אֶת הַמַּקְלוֹת. מַאן מַקְלוֹת, אִלֵּין דַּרְגִּין דְּאִינוּן בֵּי דִינָא. אֲשֶׁר פִּצֵּל, דְּאַעֲבַר מִנְּהוֹן דִּינָא. בָּרְהָטִים, הַיְינוּ דִכְתִיב, (שיר השירים ז׳:ו׳) מֶלֶךְ אָסוּר בָּרְהָטִים, דְּהָא מֵהַהוּא מֶלֶךְ, אַתְיָין בִּרְכָאן לְכֻלְּהוּ עָלְמִין."],[[0,"ויאמר יעקב לא תתן לי מאומה:","אמר יעקב, חלילה, כי אני, כל מה שעשיתי, בשביל כבוד המלך הקדוש עשיתי ולא בשביל תאותי, ועל כן לא תתן לי מאומה, כי לא היתה כונתי לזה מעולם, אלא אם תעשה לי וגו'."],[1,"ויסר ביום ההוא את התישים:","ר' אלעזר פתח ואמר, ה' מי יגור באהלך וגו': הוא נתבאר. ובארוהו החברים, \u0003הולך תמים\u0004 זה אברהם, כי כשנמול נקרא תמים. \u0003ופועל צדק,\u0004 זה יצחק. \u0003ודובר אמת,\u0004 זה יעקב. ודאי יעקב נתדבק במדת האמת. ושואל, אם הוא נתדבק במדת האמת, מהו הטעם שעשה עם לבן דברים כאלו. דהיינו פיצול המקלות וכו'."],[2,"אלא יעקב וכו':","ומשיב, אלא יעקב, בוחן שעת המזל היה, בכל אלו המעשים שעשה, כי מותר לו לאדם לבחון שעתו, טרם שחוזר לארצו, שאם מזלו עומד לו במה שעושה, טוב, ואם לא, לא ירים רגלו ללכת עד שישחק לו המזל. פירוש. כי \u0003מזוני לאו בזכותא תלייא\u0004 שפירושו כלים זכים, \u0003אלא במזלא,\u0004 שה\"ס עוביות המלכות, שעליה יוצא קו אמצעי, ששורשו דיקנא דא\"א (כנ\"ל ב\"ב דף ע\"א ד\"ה כל) וארץ ישראל, ה\"ס המלכות בשעה שמלבשת לאמא, שהכלים שלה זכים מאוד בסוד אין \u0003מזל\u0004 לישראל, וע\"כ היה צריך להמשיך בחינת \u0003מזל\u0004 בעודו בחוץ לארץ. וז\"ש \u0003דשרי ליה לאינש למבחן שעתיה עד לא יתוב לארעיה ואי מזליה קאים וכו'\u0004 דהיינו שהיה צריך להמשיך בחינת המזל בעודו בחו\"ל בטרם שישוב לארץ ישראל. והמשיך זה בסוד המקלות שעשה, כמ\"ש להלן."],[3,"ת\"ח כתיב, וענתה בי צדקתי וגו':","הרי שהוא לא עשה כדי שיקח מלבן משהו בחנם, אלא הכל עשה באמת ובשלמות הרצון. ולא עוד אלא שקבל רשות על כל זה מן לבן, ועל זה, כתוב, השיב לו, נחשתי ויברכני ה' בגללך. כי כמה מיני כשפים, עשה לבן ובחן את מזלו אם הוא מצליח בשביל יעקב, והיה מוצא בכל חודש, מאה צאן ומאה כבשים ומאה עזים, יותר על צאנו, בגלל יעקב. ולפיכך נתן לו רשות."],[4,"ר' אבא אמר וכו':","רא\"א. אלף צאן, אלף כבשים, ואלף עזים היה מביא לו יעקב יותר, בכל חדש וחדש. וזהו שכתוב, כי מעט אשר היה לך לפני וגו', והברכה של מעלה אינה פחות מאלף מכל מין ומין, מצאן נמצא אלף, ומכבשים נמצא אלף, ומעזים נמצא אלף, על כל מה שהברכה של מעלה שורה, אינה פחות מאלף, עד שבגלל יעקב נתעלה לבן להרבה עושר. פירוש. כי שורש לבן הוא קו שמאל דבינה, שמטרם שבא יעקב שם להעלות מ\"ן להמשיך לו קו אמצעי, הוא חושך ואינו מאיר. וז\"ש לבן, נחשתי ויברכני ה' בגללך, וכן הכתוב, כי מעט אשר היה לך לפני, כי מטרם שבא יעקב היה לו מעט, כי היה חשך מחמת חסרון חסדים. וכשבא יעקב שה\"ס ז\"א והמשיך לו קו אמצעי, אז, ויפרוץ לרוב ויברך ה' אותך לרגלי. כי ע\"י יעקב יצאו ג' קוין בבינה, בסוד \u0003תלת נפקי מחד\u0004 ואז הרויח לבן בחינת הספירות מבינה, שהם במספר מאה, או דאבא, שהם במספר אלף. אבל יעקב, שה\"ס קו אמצעי ולא בינה, לא לקח אלא קומת ז\"א, שספירותיו בסוד עשרה. כמ\"ש לפנינו."],[5,"וכד בעא יעקב וכו':","וכשבקש יעקב לקבל שכרו, לא מצא אלא עשרה מכל מין ומין. להיותו בחינת קו אמצעי שהוא ז\"א, שספירותיו בסוד עשרה כנ\"ל. ויעקב חשב את זה לעשירות גדולה. מטעם שקבל בחינת הדעת שבראש ראה ההפרש, כמה לקח משל לבן, ממה שהיה נותן הוא בזכותו ללבן. וכל זה שהגיע ליעקב, לא היה אלא בכח אלו המקלות ששם אצל הצאן. פי' כי המקלות ה\"ס העוביות דמלכות שממנו מתתקן סוד המסך דחירק, שבכח שממעט קו השמאל מג\"ר לו\"ק, בכח זה הוא מיחד אותו בקו ימין, (כנ\"ל ב\"א דף רצ\"ד ד\"ה רבי) ומיעוט זה מג\"ר לו\"ק מכונה זרוע. וז\"ש \u0003וכל דא דסליק ביה יעקב לא הוה אלא בזרוע\u0004 דאינון מקלות וגו', כי מתוך שהמשיך קו אמצעי על המסך דמקלות, ויצאו ג' קוין בבינה, בסוד \u0003תלת נפקי מחד\u0004 זכה גם יעקב בג' הקוין בסוד \u0003חד בתלת קיימא.\u0004"],[6,"ת\"ח כמה טרח וכו':","בוא וראה, כמה טרח אותו השלם, יעקב, אחר לבן. כתוב, וישם דרך שלשת ימים וגו', והיה מביא לו כל עושר הזה. ועם כל זה לא רצה לבן, שיהיה שכרו של יעקב כך, כמו שהתנה עמו, אלא שלקח עשרה מן מין זה ועשרה מן מין זה ונתן לו, ואמר לו, קח את אלו, ואם יולידו כמו שאמרת, דהיינו עקוד ונקוד, באופן זה יהיה שכרך, דהיינו שיקח עשרה מכל מין. וז\"ש ותחלף את משכורתי עשרת \u0003מונים,\u0004 דהיינו עשרה \u0003מן\u0004 זה ועשרה \u0003מן\u0004 זה. ודורש \u0003מונים\u0004 מלשון, מן, מן. וכתוב ואביכן וגו' עשרת מונים. ובאלו העשרה היה משתדל אחר הקב\"ה וברך אותו. ומכל מה שהתנה לבן עם יעקב חזר בדבורו, ולקח מיעקב הכל, עד שהקב\"ה רחם עליו ולקח משל לבן בזרוע, דהיינו בכח המסך דחירק שה\"ס המקלות, הממעט קו השמאל מג\"ר לו\"ק כנ\"ל."],[7,"אמר ר' אלעזר וכו':","אר\"א, כל אלו המקראות ללמד חכמה באות, כי למדנו, דברים העליונים, יש מהם שתלוים במעשים, כמו תפלין וציצית, ומהם בדבורים, כמו קריאת שמע ותפילה, ומהם בכונת הלב, כמו אהבה ויראה. ומי שרוצה להמשיך ברכות, הוא על ידי תפלה בדבור ובכונה, ומהם שאינם נמשכים על ידי תפלה אלא שתלוים במעשים."],[8,"ת\"ח יעקב שלים וכו':","בוא וראה, יעקב השלם, כל מה שעשה בחכמה עשה. כתוב, ויצג את המקלות וגו', הכל עשה בחכמה להמשיך ברכות ממקור כל, לכל מדרגות העליונות שהם חלקו וגורלו."],[9,"את המקלות:","שואל מהו מקלות. ומשיב, אלו הם מדרגות הדין, הנכללים מעוביות המלכות, \u0003אשר פצל,\u0004 פירושו, שהעביר מהם הדין ע\"י שהמשיך עליהם קומת חסדים, \u0003ברהטים,\u0004 היינו שכתוב מלך אסור ברהטים. כי ממלך ההוא שה\"ס מלך העליון בינה, באות הברכות לכל העולמות. פירוש. כי רהטים ה\"ס הכלים דקו השמאל שבבינה, כנ\"ל אשר בסבת היחוד דקו אמצעי אינם מאירים אלא ממטה למעלה (כנ\"ל דף ק\"כ ד\"ה וכד) וז\"ס \u0003מלך אסור ברהטים,\u0004 כי הבינה שהיא נקרא \u0003מלך\u0004 עליון, \u0003אסור ברהטים\u0004 הללו שלא יתפשט משם ולמטה. וזה נעשה, מסבה שיעקב הציג המקלות, שעליהם יצא קו אמצעי, בתוך הרהטים, ואינם יכולים עוד להאיר ממעלה למטה."]],[[0,"","וַיֹּאמֶר יַעֲקֹב לֹא תִתֵּן לִי מְאוּמָה. אָמַר יַעֲקֹב, חָלִילָה, שֶׁהֲרֵי אֲנִי כָּל מַה שֶּׁעָשִׂיתִי, לְשֵׁם כְּבוֹד הַמֶּלֶךְ הַקָּדוֹשׁ עָשִׂיתִי, וְעַל כֵּן לֹא תִתֵּן לִי מְאוּמָה, שֶׁהֲרֵי אֵין דַּעְתִּי בָּזֶה, אֶלָּא אִם תַּעֲשֶׂה לִי (את) הַדָּבָר הַזֶּה וְגוֹ'."],[1,"","וַיָּסַר בַּיּוֹם הַהוּא אֶת הַתְּיָשִׁים. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהלים טו) ה' מִי יָגוּר בְּאָהֳלֶךְ וְגוֹ'. הֲרֵי בֵּאַרְנוּ וּבֵאֲרוּ הַחֲבֵרִים, הוֹלֵךְ תָּמִים - זֶה אַבְרָהָם, שֶׁכַּאֲשֶׁר נִמּוֹל נִקְרָא תָמִים. וּפֹעֵל צֶדֶק - זֶה יִצְחָק. וְדבֵר אֱמֶת - זֶה יַעֲקֹב. וַדַּאי שֶׁיַּעֲקֹב נִדְבַּק בָּאֱמֶת. אִם הוּא בָּאֱמֶת נִדְבַּק, מָה הַטַּעַם עָשָׂה עִם לָבָן בַּצּוּרָה הַזּוֹ?"],[2,"","אֶלָּא יַעֲקֹב הִבְחִין אֶת שְׁעַת הַמַּזָּל שֶׁלּוֹ שֶׁהָיְתָה, שֶׁמֻּתָּר לָאָדָם לִבְחֹן אֶת שְׁעָתוֹ טֶרֶם יָשׁוּב לְאַרְצוֹ, וְאִם מַזָּלוֹ עוֹמֵד בְּמַה שֶּׁעוֹשֶׂה - יָפֶה, וְאִם לֹא - אַל יוֹשִׁיט רַגְלוֹ עַד שֶׁיַּעֲלֶה (שיעמד במה שעשה) אֵלָיו."],[3,"","בֹּא רְאֵה, כָּתוּב וְעָנְתָה בִּי צִדְקָתִי בְּיוֹם מָחָר וְגוֹ'. שֶׁהֲרֵי הוּא לֹא עָשָׂה כְּדֵי שֶׁיִּטֹּל מִשֶּׁלּוֹ לְחִנָּם, אֶלָּא הַכֹּל בֶּאֱמֶת וּשְׁלֵמוּת הָרָצוֹן, וְלֹא עוֹד, אֶלָּא שֶׁהוּא נָטַל רְשׁוּת מִלָּבָן, וְעַל כֵּן כָּתוּב נִחַשְׁתִּי וַיְבָרֲכֵנִי ה' בִּגְלָלֶךְ. כַּמָּה כְשָׁפִים וּמִינִים עָשָׂה לָבָן וּבָחַן אֶת מַזָּלוֹ מִשּׁוּם יַעֲקֹב, וְהָיָה מוֹצֵא בִּגְלַל יַעֲקֹב מֵאָה צֹאן כָּל חֹדֶשׁ, וּמֵאָה כְבָשִׁים וּמֵאָה עִזִּים יוֹתֵר עַל צֹאנוֹ."],[4,"","רַבִּי אַבָּא אָמַר, אֶלֶף צֹאן וְאֶלֶף כְּבָשִׂים וְאֶלֶף עִזִּים הָיָה מֵבִיא לוֹ יַעֲקֹב יוֹתֵר בְּכָל חֹדֶשׁ וְחֹדֶשׁ. זֶהוּ שֶׁכָּתוּב כִּי מְעַט אֲשֶׁר הָיָה לְךְ לְפָנַי וַיִּפְרֹץ לָרֹב וַיְבָרֶךְ ה' אֹתְךְ לְרַגְלִי. וְהַבְּרָכָה שֶׁלְּמַעְלָה אֵינָהּ פָּחוֹת מֵאֶלֶף מִכָּל מִין וּמִין. נִמְצָא אֶלֶף מֵהַצּאן, מֵהַכְּבָשִׂים נִמְצְאוּ אֶלֶף, מֵהָעִזִּים נִמְצְאוּ אֶלֶף, עַל כָּל מַה שֶּׁשּׁוֹרָה הַבְּרָכָה שֶׁלְּמַעְלָה לֹא פָחוֹת מֵאֶלֶף, עַד שֶׁבִּשְׁבִיל יַעֲקֹב הִתְעַלָּה לָבָן לְעֹשֶׁר רַב."],[5,"","וּכְשֶׁרָצָה יַעֲקֹב לִטֹּל שְׂכָרוֹ, לֹא מָצָא אֶלָּא עֲשָׂרָה מִכָּל מִין וּמִין, וְיַעֲקֹב חָשַׁב אוֹתוֹ לְעֹשֶׁר רַב. רָאָה כַּמָּה נָטַל מִשֶּׁלּוֹ מִמַּה שֶּׁהָיָה נוֹתֵן הוּא בִּזְכוּתוֹ לְלָבָן. וְכָל זֶה שֶׁעָלָה בּוֹ בְּיַעֲקֹב, לֹא הָיָה אֶלָּא בַּזְּרוֹעַ שֶׁל אוֹתָם מַקְלוֹת שֶׁשָּׂם אֵצֶל הַצֹּאן."],[6,"","בֹּא רְאֵה כַּמָּה טָרַח אוֹתוֹ יַעֲקֹב הַשָּׁלֵם אַחֲרֵי לָבָן. כָּתוּב וַיָּשֶׂם דֶּרֶךְ שְׁלֹשֶׁת יָמִים וְגוֹ', וְהֵבִיא לוֹ כָּל הָעֹשֶׁר הַזֶּה, וְעִם כָּל זֶה לֹא רָצָה לָבָן שֶׁיִּהְיֶה כָּךְ שְׂכָרוֹ שֶׁל יַעֲקֹב, אֶלָּא נָטַל עֲשָׂרָה מִזֶּה וַעֲשָׂרָה מִזֶּה, וְנָתַן (בידי בניו) לוֹ וְאָמַר לוֹ: טֹל אֶת אֵלֶּה, וְאִם יוֹלִידוּ כְּמוֹ שֶׁאָמַרְתָּ - בַּצּוּרָה הַזּוֹ יִהְיֶה שְׂכָרְךְ. זֶהוּ שֶׁכָּתוּב וַתַּחֲלֵף אֶת מַשְׂכֻּרְתִּי עֲשֶׂרֶת מֹנִים. (ובאלו) עֲשָׂרָה מִזֶּה וַעֲשָׂרָה מִזֶּה, וְכָתוּב וַאֲבִיכֶן הֵתֶל בִּי וְהֶחֱלִף אֶת מַשְׂכֻּרְתִּי עֲשֶׂרֶת מֹנִים. (ובאלו העשרה) הִשְׁתַּדֵּל אַחַר הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבֵרְכוֹ. וּמִכָּל מַה שֶּׁהִתְנָה לָבָן עִם יַעֲקֹב - חָזַר בְּדִבּוּרוֹ וְנָטַל מִיַּעֲקֹב הַכֹּל, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלָיו וְנָטַל מִשֶּׁלּוֹ בִּזְרוֹעַ."],[7,"","אָמַר רַבִּי אֶלְעָזָר, כָּל הַפְּסוּקִים הַלָּלוּ בָּאוּ לְהַרְאוֹת הַחָכְמָה, שֶׁשָּׁנִינוּ שֶׁדְּבָרִים שֶׁלְּמַעְלָה, מֵהֶם תְּלוּיִים בְּמַעֲשֶׂה, וּמֵהֶם בְּדִבּוּר, וּמֵהֶם בִּרְצוֹן הַלֵּב, וּמִי שֶׁרוֹצֶה לִמְשֹׁךְ בְּרָכוֹת בִּתְפִלָּה, בְּדִבּוּר וְרָצוֹן. וּמֵהֶם שֶׁלֹּא בִּתְפִלָּה, אֶלָּא תְּלוּיִים בְּמַעֲשֶׂה."],[8,"","בֹּא רְאֵה, יַעֲקֹב הַשָּׁלֵם, כָּל מַה שֶּׁעָשָׂה, עָשָׂה בְּחָכְמָה. כָּתוּב וַיַּצֵּג אֶת הַמַּקְלוֹת אֲשֶׁר פִּצֵּל בָּרְהָטִים בְּשִׁקֲתוֹת הַמָּיִם. הַכֹּל בְּחָכְמָה, לִמְשֹׁךְ בְּרָכוֹת מֵהַמַּעְיָן שֶׁל הַכֹּל לְכָל הַדְּרָגוֹת הָעֶלְיוֹנוֹת שֶׁהֵן חֶלְקוֹ וְגוֹרָלוֹ."],[9,"","אֶת הַמַּקְלוֹת - אֵיזֶה מַקְלוֹת? אֵלּוּ הַדְּרָגוֹת שֶׁהֵן בֵּית הַדִּין. אֲשֶׁר פִּצֵּל - שֶׁהֶעֱבִיר מֵהֶן אֶת הַדִּין. בָּרְהָטִים - הַיְנוּ שֶׁכָּתוּב (שיר ז) מֶלֶךְ אָסוּר בָּרְהָטִים, שֶׁזֶּה מֵהַמֶּלֶךְ הַהוּא בָּאוֹת בְּרָכוֹת לְכָל הָעוֹלָמוֹת."]]],[["דָבָר אַחֵר מֶלֶךְ אָסוּר בָּרְהָטִים, מֶלֶךְ דָּא, אָסוּר וְקָשׁוּר בְּאִינוּן רְהָטִין עִלָּאִין, דְּמִנַּיְיהוּ אִשְׁתַּקְיָין כֹּלָּא, (נ\"א אתמשכן ברכאן לכולא) מִמֶּלֶךְ עִלָּאָה. בְּשִׁקַּתוֹת הַמַּיִם, (ס\"א ומתמן אשתקיין כלא שקתות המים), אִלֵּין אִינוּן נַחֲלִין דְּנָפְקִין וְאַתְיָין, עַד דְּמָטוּ לְאֲתַר דְּמִתְכַּנְשֵׁי תַּמָּן. אֲשֶׁר תָּבֹאנָה הַצֹּאן לִשְׁתּוֹת, כְּמָה דְאַתְּ אָמֵר, (תהילים ק״ד:י״א) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם. וּבְהַהוּא אֲתַר, דְּמִתְכַּנְשֵׁי תַּמָּן מַיָא, כֻּלְּהוּ אַתְיָין לְאַשְׁקָאָה מִנֵּיהּ.","(בראשית ל) וַיֵּחַמְנָה, מַאי וַיֵּחַמְנָה. תָּא חֲזֵי, בְּשַׁעְתָּא דְרוּחַ צָפוֹן נָשִׁיב, מַיִין גְּלִידִין וְלָא נָגְדִין לְבַר וְלָא אִשְׁתַּקְיָין, בְּגִין דְּדִינָא תַּלְיָא, וּקְרִירוּ דְּצָפוֹן גָּלִיד מַיָא. וְכַד אִתְעַר רוּחַ דָּרוֹם, מִתְחַמְמֵי מַיָא, וְאִתְעֲבַר גְּלִידוּ דִּלְהוֹן וְנָגְדִין, כְּדֵין אִתְשַׁקְיָין כֹּלָּא. בְּגִין דְּחֲמִימוּ דְּדָרוֹם שָׁרָאן מַיָא, וְכֻלְּהוּ מִתְחַמְמֵי וְחָדָאן לְמִשְׁתֵּי מֵהַהוּא קְרִירוּ דְּצָפוֹן, דְּהֲוָה לוֹן בְּקַדְמִיתָא, הֲדָא הוּא דִכְתִיב וַיֵּחַמְנָה. וַיֵּחַמְנָה, וְהָא (ולא) כְּתִיב וַיֶּחֱמוּ. אֶלָּא דְּאִינוּן כֻּלְּהוּ נוּקְבֵי.","וְעַל דָּא אִתְכַּוַּון יַעֲקֹב, לְמֶעְבַּד עוֹבָדָא בְּחָכְמְתָא, וְדָא הוּא דִכְתִיב (בראשית ל׳:ל״ז) וַיִּקַּח לוֹ יַעֲקֹב מַקַל לִבְנֶה לַח וְגו'. פָּתַח (נ\"א רבי אלעזר) וְאָמַר (תהילים קל״ה:ד׳) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ יִשְׂרָאֵל לִסְגֻלָּתוֹ, תָּא חֲזֵי כִּי יַעֲקֹב בָּחַר לוֹ יָהּ, עַד כָּאן לָא יָדַעְנָא מַאן בָּרִיר לְמַאן, אִי קוּדְשָׁא בְּרִיךְ הוּא בָּרִיר לֵיהּ לְיַעֲקֹב, אִי יַעֲקֹב בָּרִיר לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. אֶלָּא מִמַּה דְּגָלֵי קְרָא, יָדַעְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא נָטִיל לֵיהּ לְיַעֲקֹב לְעַדְבֵיהּ, דִּכְתִיב, (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.","תָּא חֲזֵי, הָכִי נָמֵי יַעֲקֹב, בִּירֵר אַחְסַנְתֵּיהּ וְעַדְבֵיהּ לְחוּלָקֵיהּ, וְסָלִיק לְעֵילָא מִכָּל דַּרְגִּין, וְנָטִיל לֵיהּ לְעַדְבֵיהּ. מַקַּל לִבְנֶה לַח, הַיְינוּ דַּרְגָּא חִוָּורָא דִּסְטַר יְמִינָא. וְלוּז וְעַרְמוֹן, הַיְינוּ דַרְגָּא סוּמְקָא דִּסְטַר שְׂמָאלָא.","וַיְפַצֵּל בָּהֶן פְּצָלוֹת לְבָנוֹת, דְּאַעֲבַר דִּינָא מִן דָּא, וְאִתְחַבַּר לֵיהּ בִּימִינָא, וְהוּא עָאל בֵּינַיְיהוּ וְנָטִיל לוֹן כְּחֲדָא וְאִתְעֲבִיד כֹּלָּא חַד בִּתְרִי גַוְונֵי. וְעִם כָּל דָּא, מַחְשׂף הַלָּבָן, דְּיִתְגַּלֵּי חִוָּורָא עַל סוּמְקָא. וְכָל דָּא לְמַאי, לְאַמְשָׁכָא לְדַרְגָא דָא דְעַדְבֵיהּ בִּרְכָאן מִמַּבּוּעָא דְכֹלָּא (נ\"א דנחלא), וּלְשַׁוָּאָה לְדַרְגָא דָא דְּאִיהוּ תְּלָתָא כְּחֲדָא.","בָּרְהָטִים בְּשִׁקַּתוֹת הַמַּיִם, כְּמָה דְאוֹקִימְנָא. וּכְדֵין בְּעוֹבָדָא דָא דְּחָכְמְתָא נָגְדִין בִּרְכָאן לְתַתָּא, וּמִתְשַׁקְיָין (נ\"א ומתברכאן) כֻּלְּהוּ עָלְמִין וְשַׁרְיָין עֲלֵיהּ בִּרְכָאן, כְּמָה דְּאוּקְמוּהָ. דִּכְתִיב, (בראשית מ״ט:כ״ז) בַּבֹּקֶר יאכַל עַד וְגו', וּלְבָתַר מִכָּאן, (שם) וְלָעֶרֶב יְחַלֵּק שָׁלָל, לְאִתְבָּרְכָא כֻּלְּהוּ עַלְמִין לְתַתָּא. וְיַעֲקֹב נָטַל חוּלָקֵיהּ, מֵאִינוּן בִּרְכָאן, דְּשַׁרְיָין עֲלֵיהּ לְתַתָּא, בְּגִין דְּאִיהוּ חוּלָקֵיהּ וְעַדְבָא דְּקוּדְשָׁא בְּרִיךְ הוּא."],[[0,"ד\"א, מלך אסור ברהטים:","מלך זה, דהיינו ז\"א, אסור ומקושר באלו רהטים העליונים, שהם הכלים דקו שמאל שבבינה, שמהם נשקים הכל ממלך העליון. כלומר, \u0003שמלך\u0004 שהוא ז\"א \u0003אסור,\u0004 דהיינו שאינו מאיר ממעלה למטה, מסבת הרהטים, שהם הכלים דבינה, שבו, כמ\"ש לעיל בדבור הסמוך. \u0003בשקתות המים,\u0004 אלו הם הנחלים הנמשכים ובאים עד שמגיעים אל המקום שמתקבצים שם, דהיינו הנוקבא דז\"א אשר רהטים דבינה נמשכים אליה, ונעשו בה שקתות המים. \u0003אשר תבאנה הצאן לשתות,\u0004 הוא כמו שאתה אומר, ישקו כל חיתו שדי וגו' שבמקום ששם מתקבצים המים, שהוא הנוקבא, כולם, כל דרי בי\"ע, באים לשתות ממנו."],[1,"ויחמנה.","שואל, מהו ויחמנה. ומשיב, בוא וראה, בשעה שרוח צפון נושב, על הנוקבא, דהיינו הארת השמאל, שהוא חכמה בלי חסדים, המים, שהוא השפע, נקפאים, ואינם נוזלים לחוץ, לג' עולמות בי\"ע, וכאשר נתעורר רוח דרום, שה\"ס הארת הימין דהיינו חסדים, המים מתחממים, והקפאון שלהם נעבר ונמשכים לעולמות, אז שותים כולם, כי חמימות הדרום פותחים קפאון המים, וכולם מתחממים, ושמחים לשתות, מתוך שנעבר מהם אותה הקרירות מצפון, שהיה להם מקודם לכן. (וביאור הדברים תמצא לעיל ב\"א דף רמ\"ז ד\"ה ימא דקפא) וזהו שכתוב, ויחמנה. שואל, כתוב \u0003ויחמנה,\u0004 ולא כתוב ויחמו כמ\"ש לאח\"ז, כי צאן לשון זכר הוא. ומשיב, אלא משום שהם כולם נקבות. פירוש כי הצאן הבאים לשתות, ה\"ס המדרגות של הנוקבא, וע\"כ נבחנים לנקבות כמוה ולפיכך כתוב ויחמנה שמרומז בו לשון נקבה."],[2,"ועל דא אתכוון יעקב:","ועל זה נתכוון יעקב לעשות מעשה בחכמה, דהיינו לכוון מעשיו על פי מדרגות העליונות, וזהו שכתוב, ויקח לו יעקב מקל לבנה לח וגו'. פתח ר' אלעזר ואמר, כי יעקב בחר לו יה ישראל לסגולתו, בוא וראה, \u0003כי יעקב בחר לו יה,\u0004 עדיין אין אנו יודעים מי בחר למי, אם הקב\"ה בחר לו את יעקב, או יעקב בחר לו את הקב\"ה. כי אין הכרע לכאן או לכאן בדברי הכתוב הזה. ומשיב, אלא ממה שגילה הכתוב, אני יודע, שהקב\"ה לקח לו את יעקב לחלקו, שכתוב, כי חלק ה' עמו יעקב חבל נחלתו."],[3,"תא חזי הכי וכו':","בוא וראה, יעקב גם כן בחר נחלתו וגורלו לחלקו, ועלה למעלה מכל המדרגות, ולקח לו לחלקו, \u0003מקל לבנה לח,\u0004 היינו מדרגת הלבן שמצד ימין, שהיא אור החסדים. \u0003ולוז וערמון.\u0004 היינו מדרגת האדום שמצד שמאל, שהוא בחינת דינים של הבינה, אחר שחזרה לחכמה, כי ב' בחינות הדינים, מימין, ומשמאל, היו כלולים במקלות."],[4,"ויפצל בהם פצלות לבנות:","שהעביר הדין מן זה, מלוז וערמון שהם שמאל, וחבר אותו בקו ימין, והוא עצמו שהוא קו אמצעי, נכנס ביניהם ולקחם כאחד, ונעשה הכל אחד בב' צבעים, דהיינו שהוציא קומת חסדים על בחינת המסך שבעוביות המקלות, אשר קומה זו ה\"ס קו אמצעי הכולל לבן ואדום, שהם ימין ושמאל, חסדים והארת חכמה. ועם כל זה \u0003מחשוף הלבן,\u0004 שעשה אותם באופן, שיתגלה הלבן על האדום, דהיינו שתתלבש הארת החכמה שהיא אדום, בחסדים שהם לבן. וכל זה למה לו, הוא כדי להמשיך ברכות למדרגה זו של חלקו, שהוא קו אמצעי, ממקור הכל מבינה שהיא מקורם של ג' הקוין ולתקן מדרגה זו דתקון קוין, שהיא שלשה קוין כאחד."],[5,"ברהטים בשקתות המים:","הוא כמו שבארנו (לעיל באות ש\"ד) ואז, על ידי פעולה זו של חכמה, דהיינו תקון ג' הקוין, נמשכות הברכות למטה, וכל העולמות נשקים, והברכות שורות עליהם. כמו שבארוהו שכתוב, בבקר יאכל עד וגו', ואחר כך, ולערב יחלק שלל, שיתברכו כל העולמות למטה, שהם ג' העולמות בי\"ע. ויעקב לקח חלקו מאלו הברכות השורות עליו למטה, משום שהוא חלקו וגורלו של הקב\"ה. פירוש, שיעקב הוא בחינת קו אמצעי, וקו אמצעי הוא חלקו של הקב\"ה, וכל אותם האורות שקו אמצעי גרם בהכרעתו למעלה, מקבל אותם קו אמצעי למטה. וז\"ש \u0003ויעקב נטל חולקיה מאנון ברכאן, דשריין עליה לתתא.\u0004"]],[[0,"","דָּבָר אַחֵר מֶלֶךְ אָסוּר בָּרְהָטִים - מֶלֶךְ זֶה אָסוּר וְקָשׁוּר בְּאוֹתָם הָרְהָטִים הָעֶלְיוֹנִים שֶׁמֵּהֶם מַשְׁקִים אֶת הַכֹּל (נמשכות ברכות לכל) מִן הַמֶּלֶךְ הָעֶלְיוֹן. בְּשִׁקְתוֹת הַמָּיִם - (ומשם משקים כל שקתות המים) אֵלּוּ הֵם הַנְּחָלִים שֶׁיּוֹצְאִים וּבָאִים עַד שֶׁמַּגִּיעִים לְמָקוֹם שֶׁשָּׁם מִתְכַּנְּסִים. אֲשֶׁר תָּבֹאןָ הַצֹּאן לִשְׁתּוֹת - כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם. וּבְאוֹתוֹ הַמָּקוֹם שֶׁשָּׁם מִתְכַּנְּסִים הַמַּיִם, כֻּלָּם בָּאִים לְהַשְׁקוֹת מִמֶּנּוּ."],[1,"","וַיֵּחַמְנָה - מַה זֶּה וַיֵּחַמְנָה? בֹּא רְאֵה, בְּשָׁעָה שֶׁרוּחַ צָפוֹן נוֹשֶׁבֶת, הַמַּיִם קוֹפְאִים וְלֹא נִמְשָׁכִים לַחוּץ וְלֹא מַשְׁקִים, מִשּׁוּם שֶׁהַדִּין תָּלוּי, וְקֹר הַצָּפוֹן מַקְפִּיא אֶת הַמַּיִם. וּכְשֶׁמִּתְעוֹרֶרֶת רוּחַ הַדָּרוֹם, מִתְחַמְּמִים הַמַּיִם וְהַקִּפָּאוֹן שֶׁלָּהֶם עוֹבֵר וְשׁוֹפְעִים. אָז הַכֹּל מֻשְׁקִים, מִשּׁוּם שֶׁהַחֹם שֶׁל הַדָּרוֹם מַפְשִׁירִים הַמַּיִם, וְכֻלָּם מִתְחַמְּמִים וּשְׂמֵחִים לִשְׁתּוֹת מֵאוֹתוֹ הַקֹּר שֶׁל הַצָּפוֹן שֶׁהָיָה לָהֶם בָּרִאשׁוֹנָה. זֶהוּ שֶׁכָּתוּב וַיֵּחַמְנָה. וַיֵּחַמְנָה, וַהֲרֵי (ולא) כָתוּב וַיֶּחֱמוּ. אֶלָּא שֶׁהֵם כֻּלָּם נְקֵבוֹת."],[2,"","וְעַל זֶה הִתְכַּוֵּן יַעֲקֹב לַעֲשׂוֹת מַעֲשֶׂה בְּחָכְמָה, וְזֶהוּ שֶׁכָּתוּב וַיִּקַּח לוֹ יַעֲקֹב מַקַּל לִבְנֶה לַח וְגוֹ'. פָּתַח (רבי אלעזר) וְאָמַר, כִּי יַעֲקֹב בָּחַר לוֹ יָהּ יִשְׂרָאֵל לִסְגֻלָּתוֹ. בּא רְאֵה, כִּי יַעֲקֹב בָּחַר לוֹ יָהּ, עַד כָּאן לֹא יָדַעְנוּ מִי בָחַר אֶת מִי - אִם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּחַר אֶת יַעֲקֹב, אִם יַעֲקֹב בָּחַר לוֹ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, אֶלָּא מִמַּה שֶּׁגִּלָּה הַכָּתוּב יָדַעְנוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָטַל אֶת יַעֲקֹב לְגוֹרָלוֹ, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ."],[3,"","בֹּא רְאֵה, כָּךְ גַּם יַעֲקֹב בָּחַר אֶת יְרֻשָּׁתוֹ וְגוֹרָלוֹ לְחֶלְקוֹ, וְעָלָה לְמַעְלָה מִכָּל הַדְּרָגוֹת וְנָטַל אוֹתוֹ לְגוֹרָלוֹ. מַקַּל לִבְנֶה לַח - הַיְנוּ הַדַּרְגָּה הַלְּבָנָה שֶׁל צַד הַיָּמִין. וְלוּז וְעַרְמוֹן - הַיְנוּ הַדַּרְגָּה הָאֲדֻמָּה שֶׁל צַד שְׂמֹאל."],[4,"","וַיְפַצֵל בָּהֶם פְּצָלוֹת לְבָנוֹת - שֶׁהֶעֱבִיר מִזֶּה אֶת הַדִּין וְחִבֵּר אוֹתוֹ לַיָּמִין, וְהוּא נִכְנַס בֵּינֵיהֶם וְנָטַל אוֹתָם יַחַד וְנַעֲשָׂה הַכֹּל אֶחָד בִּשְׁנֵי גְוָנִים. וְעִם כָּל זֶה מַחְשּף הַלָּבָן, שֶׁיִּתְגַּלֶּה הַלָּבָן עַל הָאָדם. וְכָל זֶה לָמָּה? לִמְשֹׁךְ אֶת הַדַּרְגָּה הַזּוֹ שֶׁל גּוֹרָלוֹ בְּרָכוֹת מִן הַמַּעְיָן שֶׁל הַכֹּל (של הנחל), וְלָשִׂים אֶת הַדַּרְגָּה הַזּוֹ שֶׁהִיא שָׁלֹשׁ כְּאַחַת."],[5,"","בָּרְהָטִים בְּשִׁקֲתוֹת הַמָּיִם - כְּמוֹ שֶׁבֵּאַרְנוּ, וְאָז בַּמַּעֲשֶׂה הַזֶּה שֶׁל חָכְמָה שׁוֹפְעוֹת הַבְּרָכוֹת לְמַטָּה וּמֻשְׁקִים (ומתברכים) כָּל הָעוֹלָמוֹת וְשׁוֹרוֹת עֲלֵיהֶם הַבְּרָכוֹת, כְּמוֹ שֶׁפֵּרְשׁוּהָ (בראשית מט) שֶׁכָּתוּב בַּבֹּקֶר יֹאכַל עַד וְגוֹ', וְאַחַר מִכָּאן - וְלָעֶרֶב יְחַלֵּק שָׁלָל, שֶׁיִּתְבָּרְכוּ כָּל הָעוֹלָמוֹת לְמַטָּה. וְיַעֲקֹב נָטַל חֶלְקוֹ מֵאוֹתָן הַבְּרָכוֹת שֶׁשּׁוֹרוֹת עָלָיו לְמַטָּה, מִשּׁוּם שֶׁהוּא חֶלְקוֹ וְגוֹרָלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא."]]],[["\u0003סתרי תורה\u0004 (בראשית ל׳:ל״ז) וַיִּקַּח לוֹ יַעֲקֹב מַקַּל לִבְנְה וְגו', מַתְּנִיתִּין, רְעוּתָּא דְעוֹבָדָא, קִטְרֵי דִמְהֵימְנוּתָּא, קָל קָלָא דְּקָלְיָא אִתְּעַר מֵעֵילָא לְתַּתָּא, אֲנַן פְּתִּיחִין עַיְינִין הֲוִינָן. גַּלְגְּלָא אַסְחַר מֵעֵילָא לְכַמָּה סִטְרִין, קָל נְעִימוּתָּא אִתְּעָר. אִתְּעָרוּ נַיְימִין דְּמִיכִין דְּשִׁינְתָּא בְּחוֹרֵיהוֹן, וְלָא יָדְעֵי וְלָא מִסְתַּכְּלָן, וְלָא חָמָאן. אֲטִימִין אוּדְנִין, כְּבֵדִין דְלִבָּא, נַיְימִין וְלָא יָדְעִין. אוֹרַיְיתָּא קָיְימָא קַמַּיְיהוּ, וְלָא מַשְׁגִּיחִין וְלָא יָדְעֵי בְּמָּה מִסְתַּכְּלָן, חָמָאן וְלָא חָמָאן. אוֹרַיְיתָּא רָמַאתּ קָלִין אִסְתְּכָּלוּ טִפְּשִׁין, פִּתְּחוּ עַיְינִין, ותִּנְדְּעוּן. לֵיתּ מַאן דְּיִשְׁגַּח, וְלֵיתּ מַאן דְּיַרְכִין אוּדְנֵיהּ, עַד מָה תֶּהֱווּן בְּגוֹ חשוֹכָא דִּרְעוּתַּיְיכוּ. אִסְתַּכָּלוּ לְמִנְדַע, וְאִתְּגְּלִי לְכוֹן נְהוֹרָא דְּנהִיר.","בְּזִמְנָא דְיַעֲקֹב שְׁלֵימָא, מִגּוֹ עָאקוּ דְּאַרְעָא וּרְשׁוּ אָחֳרָא, בְּגוֹ דַּרְגִּין נוּכְרָאִין דָּחָה לְכֻלְּהוּ, וּבָרִיר חוּלַק עַדְבֵיהּ וְאַחְסַנְתֵּיהּ. נְהוֹרָא מִגּוֹ חֲשׁוֹכָא, חָכְמְתָּא מִגּוֹ טִפְּשׁוּתָּא, וְאוֹקִיר לֵיהּ לְמָארֵיהּ כַּד הֲוָה קָאִים בְּגוֹ רְשׁוּתָּא דְּאל זָר. עַל דָּא כְּתִּיב, (ישעיהו כ״ט:כ״ב) לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב ולא עַתָּה פָּנָיו יֶחֱורוּ.","\u0003תוספתא\u0004 קוּטְרָא דְקוּטְרָא דַכְיָא, הֲוָה סָלִיק לְגוֹ לְגוֹ, עַד לָא אַשְׁכַּח אֲתַּר בֵּיתּ מוֹתָּבָא. הַהוּא אֲתַּר לָאו אֲתַּר, לָאו אִשְׁתַּכַּח לְעֵילָא ותַּתָּא. מִכּלָּא אִתְּאֲבִיד, אֲבַדּוֹן הֲוִי מִכֹּלָּא, אֲבַדּוֹן דְּכוּרָא, סמא\"ל דְּנָפַּק מֵהִתּוּכָא דְּתּוּקְפָּא דְיִצְּחָק. אֲבַדּוֹן וּמָוְתּ נוּקְבָא דִילֵיהּ, נָחָשׁ קַדְמָאָה, אֵשֶׁתּ זְנוּנִים, דִּכְתִּיב (משלי ה׳:ה׳) רַגְלֶיהָ יוֹרְדּוֹתּ מָוְתּ. ואִלֵּין תְּרֵין, אֲבַדּוֹן וּמָוְתּ, שְׁמָעוּ תּוּקְפָּא דְּהוּרְמָנוּ דְמַלְכָּא.","רָזָא וסִתְּרָא סְתִּימָא (נ\"א טמירא) עִלָּאָה אִתְּאֲבִיד (נ\"א טמיר) מִכֹּלָּא, אִתְּאֲבִיד (נ\"א טמיר) מֵרַעֲיוֹנִין (נ\"א מעיינין) והִרְהוּרִין. (ס\"א מאן דאתמשך בתר אילין אתאביד מכלא. כולא בהפוכא דא מן דא טבוהי דגבר שלים כיעקב דסליק ולא אתחשכו עיינין בהאי תננא וזכה לאתקרבא באמת חותמא דמלכא קדישא. תא חזי, טמירא עלאה מכלא) מִנֵּיהּ נָפַּק אָתּ י', נְקוּדָה עִלָּאָה. מֵהַאי נְקוּדָה עִלָּאָה נָפַּק כֹּלָּא. אַמְשִׁיךָ ואַפִּיק ה', אִמָּא עִלָּאָה דְּאַשְׁקֵי לְכֹלָּא. מֵהַאי נפִּיק ו', רָזָא דְשִׁיתּ דְאָחִיד לְכָל סִטְרִין, דְּאִיהוּ, מַקַּל לִבְנְה לַח, ולתּ, וְעַרְמוֹן.","תְּרֵין דְּרוֹעִין דְּאֲחִידָן בֵּיהּ, אִלֵּין נָפְּקֵי ואֲחִידוּ בְּה\"א תַּתָּאָה, לְחַבְּרָא מַשְׁכְּנָא כְּחַד וּלְמֶהֱוִי חַד. כְּדֵין, תְּלֵיסַר מְכִילָן הֲווּ חַד. וחִוָּורָא אִתְּגְּלִיף עַל גְּוָונִין וסָלִיק עַל גַּוָּון כֻּלְּהוּ. הֲדָא הוּא דִכְתִּיב (בראשית ל׳:ל״ז) מַחְשׂף הַלָּבָן, וּכְדֵין אִקְרֵי (זכריה י״ד:ט׳) יְיָ אֶחָד וּשְׁמוֹ אֶחָד. וּכְדֵין (תהילים כ״ג:ב׳) יְיָ רוֹעִי לֹא אֶחְסָר. וּכְתִּיב בִּנְאוֹתּ דֶּשֶׁא יַרְבִּיצֵּנִי על מֵי מְנוּחוֹתּ יְנַהֲלֵנִי נַפְּשִׁי יְשׁוֹבֵב וגו'. (ע\"כ תוספתא)","ויקח לו יעקב, (בראשית ל׳:ל״ז) בריר ליה לחולקיה לעדביה, מקל לבנה לח, סטרא דימינא, גוון חוור. לח, סטרא איהו דמים. ולוז, דא סטרא דשמאלא, סומקא כוורדא. וערמון, כליל דא בדא. וכלהו אחיד ימינא חוורא בגווניה, וסלקא בהו. דכתיב מחשף הלבן, דאף על גב דאחיד לתרין סטרין, נטל (ס\"א נטה) חולקיה לסטר ימינא, ואגליף בכלא, בהאי סטרא ובהאי סטרא, כדין אקרי גבר שלים, שלים בכלא.","מה כתיב בתריה, (שם) והיה בכל יחם הצאן המקשרות ושם יעקב את המקלות וגו'. סתרא דסתרין, לחכימי לבא אתמסר. בגו משריין עלאין קדישין אית דרגין עלאין אלין על אלין, אלין פנימאין, ואלין לבר. אינון פנימאין מתקשרין במלכא קדישא, ומתקשרין בישראל, בנין קדישין לקדשא בריך הוא, ואלין אקרון הצאן המקשרות, משריין דאינון מקשרות, עילא ותתא.","בשעתא דתיאובתא דלהון לגבי זוהרא עלאה דלעילא. עמודא דאמצעיתא, יעקב שלימא נטל אינון מקלות, תפלין דרישא, ברהטים, אתר ודוכתא, לדיורי תפלין. ומהכא נטלי נהורא וזיווא, כל חילין ומשריין עלאין, אינון דמתקשרן לעילא ומתקשרן לתתא. כיון דאינון נטלין מגו רהטין שקתות המים, כדין, אינון הוו מקורין ומבועין לנחתא לתתא ולמיהב לכלא.","ובגין כך, אפריש יעקב בין דרגין עלאין קדישין, לדרגין אחרנין, דשאר עממין. כמה דאת אמר, (בראשית ל׳:מ׳) וישת לו עדרים לבדו ולא שתם על צאן לבן. (אינון) עדרים אפריש ליה לגרמיה, דלא יהא ליה חולק בשאר עממין, כמה דאפריש ליה, דרגי דמהימנותא לעילא, לחולקיה ועדביה, הכי אצטריך לאפרשא דרגין דמשריין קדישין לתתא, לקשרא לון בהדיה, באינון היכלין דמטרוניתא."],[[0,"ויקח לו יעקב מקל לבנה וגו':","הכונה של מעשה זו היה, לקשרי האמונה. להמשיך ג' קשרים לנוקבא שנקראת אמונה, דהיינו ג' קוין."],[0,"קל קלא דקליא וכו':","קול הקול של הקולות נתעורר ממעלה למטה, ונעשינו פתוחי עינים, ומפרש, הגלגל הסב לכמה צדדים, וקול של נעימות נתעורר."],[0,"גלגל","פירושו הסתובבות ההארה בג' מקומות שה\"ס חולם שורק חירק, כמ\"ש לעיל (וירא דף י\"ז ד\"ה וזה אמרו ע\"ש) דהיינו בג' קוין. ומה שאומר, שמסובב לכמה צדדים, הענין הוא, כי ההארות נכללות זו בזו, ויוצאים ג' קוין שבכל אחד מהם יש ג' קוין, באופן, שיש ג' קוין חב\"ד בקו ימין, וכולם מוח חכמה. ויש ג' קוין חב\"ד בקו שמאל, וכולם מוח בינה. ויש ג' קוין חב\"ד בקו אמצעי, וכולם מוח דעת. ונודע שכל שיעור ההארה שקו האמצעי גרם שיצא בב' קוין העליונים, זוכה בו קו האמצעי בעצמו, וע\"כ נבחן שמוח הדעת שהוא קו האמצעי, כלול בפני עצמו, בג' קוין, שכל אחד מהם כלול מג' קוין, באופן שיש חב\"ד בחכמה דמוח הדעת, ויש חב\"ד בבינה דמוח הדעת, ויש חב\"ד בדעת דמוח הדעת. וז\"ש, \u0003גלגלא אסחר מעילא לכמה סטרין,\u0004 דהיינו ג' סטרין במוח החכמה, וג' סטרין במוח הבינה, וט' סטרין במוח הדעת."],[0,"","ונודע שב' הקוין ימין ושמאל, שייכים תמיד לעליון עצמו, וכל המתפשט למטה, הוא רק קו האמצעי, שהוא מוח הדעת. ולפי זה נמצא, שג' סטרין שבמוח החכמה, וג' סטרין שבמוח הבינה, אינם מתפשטים למטה, אלא מוח הדעת לבדו הוא המתפשט למטה. וזה שמשמיענו הסתרי תורה, שלא כל ט' סטרין שבמוח הדעת מתפשטים מלמעלה למטה, אלא סטרא אחד מהם בלבד, והיינו סטרא אמצעי שבג' קוין דדעת שבמוח הדעת, כי חב\"ד דחכמה דמוח הדעת, וכן חב\"ד דבינה דמוח הדעת, וכן חו\"ב דדעת דמוח הדעת, נחשבים לבחינת ב' קוין העליונים, ואינו מתפשט למטה אלא הדעת דדעת שבמוח הדעת, דהיינו רק סטרא אחד מן הט' סטרין שבמוח הדעת. וז\"ש \u0003קל קלא דקליא אתער מעילא לתתא,\u0004 הדעת, שה\"ס ז\"א העולה למ\"ן ונעשה קו אמצעי בין חו\"ב, מכונה \u0003קול,\u0004 (כנ\"ל פרשת לך דף ד' ד\"ה בשעתא ע\"ש) וע\"כ מוח הדעת בכללו מכונה קול, וכיון שיש ט' סטרין במוח הדעת דהיינו ג\"פ חב\"ד, נמצא ש \u0003החב\"ד דדעת,\u0004 דמוח הדעת נבחן \u0003לקלא\u0004 האמצעי, דב' \u0003קליא\u0004 שהם חב\"ד דחכמה דדעת וחב\"ד דבינה דדעת. ובחינת הדעת שבקלא דקליא הזה, נבחן \u0003לקל קלא דקליא,\u0004 אשר רק הוא בלבדו \u0003אתער מעילא לתתא,\u0004 ולא שאר ח' סטרין. ועל קול הזה המתפשט למטה, אומר \u0003קל נעימותא אתער.\u0004"],[0,"אתערו ניימין דמיכין וכו':","מבאר עתה ענין סבוב הגלגל לכמה צדדים, שהם ג', דחכמה וג' דבינה, וט' דדעת כנ\"ל, אלא שמבארם מבחינת השלילה וההפסד, שאותם הדבקים בשמאל, המכונים ישינים ונרדמים, מפסידים אותם. ואומר, מנמנמים וישנים שהשינה בנקבי עיניהם, דהיינו הדבקים בקו שמאל, התעוררו. ומפריט הפסדם מכל הט\"ו סטרין הנ\"ל, היוצאים עם קו אמצעי. וכנגד הפסדם דחב\"ד שבימין, שהוא מוח החכמה, אומר, ואינם יודעים, דעת, ואינם מסתכלים, בינה. ואינם רואים, חכמה. וכנגד הפסדם דחב\"ד שבשמאל, שהוא מוח בינה, אומר, שהם אטומי אזנים, חכמה. כבדי הלב, בינה. ישנים ואינם יודעים, דעת. וכנגד הפסדם דחב\"ד שבימין מוח הדעת אומר, התורה עומדת לפניהם, דעת. ואינם משגיחים ואינם יודעים במה שמסתכלים, בינה. רואים ואינם רואים, חכמה. וכנגד הפסדם דחב\"ד שבשמאל מוח הדעת, אומר, התורה מרימה קולות הסתכלו טפשים, בינה. פתחו עינים, חכמה. ותדעו, דעת. וכנגד הפסדם דחב\"ד שבקו אמצעי דמוח הדעת, אומר, אין מי שישגיח, חכמה. ואין מי שיטה אזנו, בינה. עד מה תהיו בתוך החשך מחמת רצונכם הרע, דעת. הסתכלו לדעת ע\"י קו אמצעי, ויתגלה לכם אור המאיר, שהוא אור ז\"א. שהוא קו אמצעי, המכונה אספקלריאה המאירה."],[1,"בזמנא דיעקב שלימא וכו':","בשעה שיעקב השלם, מתוך הצרה שהיה בארץ ורשות אחרת, ולא בארץ הקדושה, ובתוך מדרגות נכריות, דחה את כולם, ובחר חלק גורלו ונחלתו, דהיינו בקו אמצעי. אור מתוך החשך, הוא קו ימין. חכמה מתוך טפשות, הוא קו שמאל. וכבד את רבונו בעודו נמצא ברשות זר, בפדן ארם, הוא קו אמצעי, הנה אז, נאמר עליו לא עתה יבוש יעקב וגו'."],[2,"קוטרא דקוטרא דכיא וכו':","בעל התוספתא סובב על הכתוב, ויקח לו, יעקב מקל לבנה וכו', שמפרשו לקו אמצעי, וע\"כ מבאר לנו רוב הדינים ששלטו בשמאל מטרם ביאת קו אמצעי, ורוב השלמות שיצאה עם ביאת קו אמצעי. ואומר, בביאור הכתוב ויקח לו יעקב, שקיחה זו פירושו, אשר קשר הטהור, דהיינו העוביות דמסך דחירק, שנעשה קשר טהור לקשור בו בטהרה את ג' הקוין זה בזה, עלה לפני ולפנים, שהיא בינה, בסוד עלית מ\"ן, ושם יצא עליו קו אמצעי. ומשם נמשך להנוקבא, ונעשתה למקום ישוב לבני אדם, דהיינו להשפיע להם כל השלמות. כמ\"ש להלן. ואומר, מטרם שמצא מקום ישוב בנוקבא ע\"י עלית מ\"ן, אותו המקום שהיא בחי' השמאל שבנוקבא, לא היה מקום. ונאבד מכל אור ושפע, אבדון היה מכל, התחתונים, שלא היה להם מה לקבל משם. אבדון זה הוא זכר, הוא סמאל, שיצא מפסולת הגבורה של יצחק, כי שמאל זה מטרם שיצא קו אמצעי, נבחן לפסולת, והוא חלקו של סמאל ומות היא הנוקבא שלו, והיא נחש הקדמוני, הנקרא אשת זנונים, שכתוב עליה, רגליה יורדות \u0003מות.\u0004 ואלו השנים \u0003אבדון ומות,\u0004 שמעו תוקף פקודת המלך. פירוש. המלך, ה\"ס קו אמצעי ז\"א, שעל ידי המשכת החסדים הוא מבטל הדינים דאבדון ומות, ונבחן זה, כמו שנתן להם פקודה, שלא להחריב העולם, ושמעו לו."],[3,"רזא וסתרא סתימא וכו':","סוד נסתר, הסתום העליון הנעלם מכל נעלם מכל רעיון והרהור, שהוא א\"א המרומז בקוץ העליון של ה \u0003י'\u0004 דהוי\"ה ממנו יצאה אות \u0003י'\u0004 משם הוי\"ה, שהיא נקודה העליונה, דהיינו או\"א הנקראים ביחד, אבא, מנקודה עליונה הזו יוצא הכל, הן חכמה והן חסדים. ה \u0003י'\u0004 המשיכה והוציאה אות \u0003ה'\u0004 משם הוי\"ה, שהיא אמא עלאה דהיינו ישסו\"ת המכונים אמא, שהיא משקה את הכל, דהיינו מוחין דחכמה המכונים שתיה, שמיוחדים לאמא. מ \u0003ה'\u0004 זו יוצאת אות \u0003ו'\u0004 משם הוי\"ה, שהוא סוד שש ספירות חג\"ת נה\"י, שנקראים ז\"א, המייחד לכל הצדדים, שהוא קו האמצעי המיחד צד ימין וצד שמאל זה בזה, שהוא נקרא \u0003מקל לבנה לח ולוז וערמון\u0004 פירוש, שהם רומזים על ג' הקוין הכלולים בקו אמצעי, אשר, \u0003מקל לבנה לח,\u0004 הוא קו ימין שבו. \u0003ולוז,\u0004 הוא קו שמאל שבו. \u0003וערמון,\u0004 הוא קו אמצעי עצמו."],[4,"תרין דרועין דאחידן וכו':","שתי זרועות נכללים בו בז\"א, כלומר, אע\"פ שהוא רק קו אמצעי מכל מקום נכללים בו גם ב' הקוין העליונים, ימין ושמאל, המכונים זרועות. אלו הזרועות יוצאות ונכללות ב \u0003ה'\u0004 אחרונה שבשם הוי\"ה, שהיא הנוקבא דז\"א, שאז מתלבשת החכמה שבזרוע שמאל בחסדים שבזרוע ימין, לחבר את המשכן, שהיא הנוקבא, עם ז\"א כאחד, ולהיות אחד שענינו נתבאר לעיל (ב\"א דף קי\"ח, ד\"ה ועל דא. עש\"ה) אז י\"ג מדות הרחמים נעשו אחד, כי \u0003אחד\u0004 הוא בגמטריא י\"ג (כמ\"ש שם) והלבן דהיינו החסדים, נחקק על הגוונים שהם חו\"ב תו\"מ שבמקלות ועולה, דהיינו ששולט על כל הגוונים שבהם, זהו שכתוב, \u0003מחשוף הלבן.\u0004 ואז נאמר, ה' אחד ושמו אחד ששניהם בסוד אחד (כמ\"ש שם) ואז ה' רועי לא אחסר, שה\"ס קו ימין. וכתוב בנאות דשא ירביצני, שה\"ס קו שמאל. על מי מנוחות ינהלני נפשי ישובב וגו', שה\"ס קו אמצעי."],[5,"ויקח לו יעקב:","פירושו שבחר לו לחלקו ולגורלו. \u0003מקל לבנה לח,\u0004 הוא קו ימין, שהוא צבע לבן, והוא \u0003לח,\u0004 שהוא בחינת מים, שהוא חסדים. \u0003ולוז,\u0004 זה קו שמאל, שהוא אדום כמו ורד. \u0003וערמון\u0004 כולל אותם זה בזה, שהוא קו אמצעי הכולל הימין והשמאל זה בזה. וכולם, אוחז הימין בצבע שלו שהוא לבן, ושולט עליהם, שכתוב, \u0003מחשוף הלבן,\u0004 ללמד, שאע\"פ שז\"א שהוא קו אמצעי, אוחז בשני הקוין שהם ימין ושמאל, מכל מקום חלקו הוא לקו ימין, וחקק הארת הימין בכולם, בקו זה ובקו זה. ואז נקרא איש תם, שהוא שלם בכל."],[6,"מה כתיב בתריה, והיה וגו':","סתר הסתרים נמסר לחכמי לב. בתוך מחנות מלאכים העליונים יש מדרגות עליונות אלו על אלו, אלו פנימים ואלו לחוץ. הפנימים מתקשרים במלך הקדוש, שהוא ז\"א, ומתקשרים בישראל, שהם בנים קדושים אל הקב\"ה, ואלו נקראים \u0003הצאן המקשרות,\u0004 דהיינו, מחנות מלאכים המקושרים למעלה בקו ימין, ולמטה בקו אמצעי."],[6,"","ביאור הדברים. \u0003בנים,\u0004 פירושו אור של תולדה, דהיינו שאינו בא בדרך השתלשלות המדרגות זו מזו, אלא ע\"י עליית מ\"ן מתחתון לעליון, שה\"ס המסך דחירק, שהתחתון נעשה על ידו, קו אמצעי בימין ושמאל דעליון, וגורם בו התחדשות אור, בסוד \u0003תלת נפקי מחד,\u0004 וכשיעור הזה זוכה בו גם התחתון, בסוד, \u0003חד בתלת קיימא,\u0004 ושיעור זה, שזכה בו התחתון מכונה בן לעליון. וב' הקוין שבעליון, שקבלו קו האמצעי מן התחתון מכונים אבא ואמא אל התחתון. וכבר בארנו את זה לעיל (דף ס\"ח ד\"ה ביאור) ע\"ש, ואין להכפיל דברים."],[6,"","וזה סוד, שנשמות ישראל מכונים בנים להקב\"ה, בסו\"ה בנים אתם לה' אלקיכם, כי ז\"א ונוקביה מטרם הזווג ה\"ס ב' קוין ימין ושמאל, שאינם מאירים זולת ע\"י העלאת מ\"ן של ישראל לזו\"ן, את סוד המסך דחירק שעליו יוצא קו אמצעי המכריע, והוא מזווג ז\"א ונוקביה. ומתחדש ויוצא בהם האור, בסוד \u0003תלת מחד נפקי,\u0004 שפירושו, שע\"י התחתון שעלה למ\"ן, נתחדש בעליון ג' קוין, וכשיעור הזה זוכים ישראל שהעלו מ\"ן וגרמו לחידוש אור הזה, וזוכים גם הם בג' מוחין, המכונים \u0003נשמות,\u0004 בסוד \u0003חד בתלת קיימא,\u0004 שמוחין הללו מכונים \u0003בנים\u0004 לזו\"ן, וזו\"ן נבחנים לאו\"א אליהם, וזסו\"ה בנים אתם לה' אלקיכם."],[6,"","וביחד עם הנשמות נולדים מזו\"ן, גם מלאכים קדושים, ויש בהם ב' בחינות שהם פנימים וחיצונים. כי היוצאים מכללות ג' קוין נחשבים לפנימים, והיוצאים משעת שליטת קו השמאל שבעת הזווג, מטרם שנכלל בקו אמצעי הם מלאכים חיצונים."],[6,"","וזה אמרו, \u0003משריין עלאין קדישין וכו' אלין פנימאין ואלין לבר,\u0004 שהנמשכים מתקון ג' קוין הם פנימים, והנמשכים משמאל הם חיצונים. וז\"ש, \u0003אינון פנימאין מתקשרין במלכא קדישא ומתקשרין בישראל,\u0004 מלכא קדישא, היינו ז\"א, שהוא קו ימין, וישראל, הם קו אמצעי, שגרמו הזווג, כנ\"ל. וסוד \u0003הקשר,\u0004 ה\"ס המסך דחירק, שעליו יוצא קומת החסדים, שנקרא קו אמצעי, (כנ\"ל דף קי\"ט ד\"ה ר' אבא ע\"ש) שעל ידו גם קו השמאל נקשר בחסד, ומאיר, ונמצא שיש כאן ב' קשרים הממשיכים חסדים, א' הוא קו ימין, ב' הוא קו אמצעי. וז\"ש, \u0003מתקשרין במלכא קדישא,\u0004 שהוא קו ימין, \u0003ומתקשרין בישראל,\u0004 שהם קו אמצעי. וז\"ש, \u0003בישראל בנין קדישין לקב\"ה,\u0004 שהוא מטעם שנמשכים מסוד התחדשות האור, שגרמו לז\"א ונוקביה, המכונה בן, כמ\"ש לעיל, שזסו\"ה בנים אתם לה' אלקיכם. וז\"ש \u0003ואלין אקרון הצאן המקשרות משריין דאינון מקשרות עילא ותתא,\u0004 עילא, פירושו בקו ימין, שה\"ס ז\"א, ותתא, פירושו בקו אמצעי, שה\"ס ישראל. כנ\"ל."],[7,"בשעתא דתיאובתא וכו':","בשעה שתשוקתם היא לזהר העליון של מעלה, אז עמוד האמצעי, שהוא יעקב השלם, לוקח אלו המקלות, שהם פרשיות התפילין של ראש דהיינו ד' מוחין חו\"ב תו\"מ, (כנ\"ל בהקדמה ספר הזהר דף ק\"פ אות רל\"ז עי' שם), אשר \u0003מקל,\u0004 ה\"ס המסך, שעליו נעשה הזווג \u0003לבנה לח\u0004 ה\"ס קו ימין ופרשת \u0003קדש. לוז\u0004 ה\"ס קו שמאל, ופרשת \u0003והיה כי יביאך. וערמון,\u0004 ה\"ס קו אמצעי הכולל ז\"א ונוקביה שהם, \u0003שמע, והיה אם שמוע.\u0004 ומשים אותם \u0003ברהטים,\u0004 שהם מקום ובית קבול להשכנת התפילין. (עי' לעיל דף קכ\"א ד\"ה ד\"א). ומכאן מקבלים אור וזיו, כל הצבאות והמחנות העליונים אלו המתקשרים למעלה בקו ימין, ומתקשרים למטה, בקו אמצעי, דהיינו צאן המקשרות, כנ\"ל, כיון שהם מקבלים מתוך הרהטים ושקתות המים, אז נעשו מקורות ומעיינות לירד למטה לבי\"ע, ולתת שפע לכל."],[8,"ובגין כך אפריש יעקב וכו':","ומשום זה הפריד יעקב בין מדרגות העליונות הקדושות, למדרגות אחרות של שאר העמים, כמו שאתה אומר, וישת לו עדרים לבדו וגו', הפריד עדרים לעצמו, ולא יהיה חלקו כשאר העמים, כמו שיעקב הפריש לו את מדרגות האמונה למעלה, דהיינו הצאן המקושרות, הנולדים מהנוקבא הנקראת אמונה, שהפרידם ממחנות החיצונים הנמשכות משמאל כנ\"ל בסמוך, כן הוצרך להפריד המדרגות של מחנות הקדושות למטה, שה\"ס הכשבים שנולדו מצאן המקושרות, שהפרידם מהעטופים, שהם הנולדים ממחנות החצונים, ולקשרם עמו בהיכלות הרבונית, שהיא הנוקבא, שעליהם נאמר והכשבים הפריד יעקב וגו'."]],[[0,"","וַיִּקַּח לוֹ מַקַּל לִבְנֶה וְגוֹ'. מִשְׁנָה. הָרָצוֹן שֶׁל הַמַּעֲשֶׂה, קִשְׁרֵי הָאֱמוּנָה, קוֹל הַקּוֹל שֶׁל הַקּוֹלוֹת, מִתְעוֹרֵר מִמַּעְלָה לְמַטָּה. אָנוּ הָיִינוּ פְּתוּחֵי עֵינַיִם. הַגַּלְגַּל סוֹבֵב מִמַּעְלָה לְכַמָּה צְדָדִים, קוֹל שֶׁל נְעִימוּת הִתְעוֹרֵר. הִתְעוֹרְרוּ יְשֵׁנִים נִרְדָּמִים שֶׁשֵּׁנָה בִּנְחִירֵיהֶם, וְלֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים וְלֹא רוֹאִים, אֲטוּמֵי אָזְנַיִם, כִּבְדֵי לֵב, יְשֵׁנִים וְאֵין יוֹדְעִים, הַתּוֹרָה עוֹמֶדֶת לִפְנֵיהֶם וְלֹא מַשְׁגִּיחִים וְלֹא יוֹדְעִים בַּמֶּה מִסְתַּכְּלִים, רוֹאִים וְלֹא רוֹאִים. הַתּוֹרָה מְרִימָה קוֹלוֹת: הִסְתַּכְּלוּ טִפְּשִׁים, יִפָּתְחוּ הָעֵינַיִם וְתֵדְעוּ. אֵין מִי שֶׁיַּשְׁגִּיחַ, אֵין מִי שֶׁיַּרְכִּין אָזְנוֹ. עַד מָתַי תִּהְיוּ בְּתוֹךְ הַחֲשֵׁכָה שֶׁל רְצוֹנְכֶם? הִסְתַּכְּלוּ לָדַעַת, וְיִתְגַּלֶּה לָכֶם הָאוֹר הַמֵּאִיר."],[1,"","בִּזְמַן שֶׁיַּעֲקֹב הַשָּׁלֵם, מִתּוֹךְ הַצָּרָה שֶׁל הָאָרֶץ וְרָשׁוּת אַחֶרֶת, בְּתוֹךְ דְּרָגוֹת זָרוֹת דָּחָה אֶת כֻּלָּם, וּבָחַר חֵלֶק גּוֹרָלוֹ וְנַחֲלָתוֹ, הָאוֹר מִתּוֹךְ הַחֲשֵׁכָה, חָכְמָה מִתּוֹךְ הַטִּפְּשׁוּת, וְכִבֵּד אֶת רִבּוֹנוֹ, כְּשֶׁהָיָה עוֹמֵד בְּתוֹךְ הָרָשׁוּת שֶׁל אֵל זָר. עַל כֵּן כָּתוּב (ישעיה כט) לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ."],[2,"","הַקֶּשֶׁר שֶׁל הַקֶּשֶׁר הַטָּהוֹר הָיָה עוֹלֶה לִפְנַי וְלִפְנִים טֶרֶם שֶׁמָּצָא מָקוֹם לְבֵית מוֹשָׁבוֹ. אוֹתוֹ מָקוֹם אֵינוֹ מָקוֹם, לֹא נִמְצָא לְמַעְלָה וּלְמַטָּה, נֶאֱבָד מִן הַכֹּל. אֲבַדּוֹן הוּא מִן הַכֹּל, אֲבַדּוֹן זָכָר. סמא\"ל שֶׁיָּצָא מֵהִתּוּךְ שֶׁל הַחֹזֶק שֶׁל יִצְחָק, אֲבַדּוֹן וּמָוֶת הִיא הַנְּקֵבָה שֶׁלּוֹ, הַנָּחָשׁ הַקַּדְמוֹנִי, אֵשֶׁת זְנוּנִים, שֶׁכָּתוּב (משלי ה) רַגְלֶיהָ יֹרְדוֹת מָוֶת. וְאֵלּוּ שְׁנַיִם - אֲבַדּוֹן וּמָוֶת - שִׁמְעוּ אֶת תֹּקֶף רְצוֹן הַמֶּלֶךְ."],[3,"","הַסּוֹד וְהַסֵּתֶר (הסתום) הַנִּסְתָּר הָעֶלְיוֹן נֶאֱבָד (הטמיר) מֵהַכֹּל, טָמִיר מֵרַעְיוֹנוֹת (מעינים) וְהִרְהוּרִים. (מי שנמשך אחר אלו, נאבד מן הכל, הכל בהפוך זה מזה, אשריו של איש שלום, כיעקב שעולה ולא נחשכו העינים בעשן הזה, וזכה להתקרב באמת חותם המלך הקדוש, בא ראה, הטמיר העליון מהכל) מִמֶּנּוּ יָצְאָה הָאוֹת י', הַנְּקֻדָּה הָעֶלְיוֹנָה. מֵהַנְּקֻדָּה הָעֶלְיוֹנָה הַזּוֹ יָצָא הַכֹּל, הִמְשִׁיךְ וְהוֹצִיא ה', הָאֵם הָעֶלְיוֹנָה שֶׁמַּשְׁקָה אֶת הַכֹּל. מִזֶּה יָצָא ו', הַסּוֹד שֶׁל שֵׁשׁ שֶׁאוֹחֵז אֶת כָּל הַצְּדָדִים, שֶׁהוּא מַקַּל לִבְנֶה לַח וְלוּז וְעַרְמוֹן."],[4,"","שְׁתֵּי הַזְּרוֹעוֹת שֶׁאוֹחֲזוֹת בּוֹ, אֵלּוּ יוֹצְאוֹת וְאוֹחֲזוֹת בַּהֵ\"א הַתַּחְתּוֹנָה לְחַבֵּר הַמַּשְׁכּוֹן יַחַד וְלִהְיוֹת אֶחָד. וְאָז שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת נִהְיוֹת אַחַת. וְהַלָּבָן נֶחְקָק עַל הַגְּוָנִים וְעוֹלֶה עַל הַגְּוָנִים כֻּלָּם. זֶהוּ שֶׁכָּתוּב מַחְשּׁף הַלָּבָן, וְאָז נִקְרָא (זכריה כ) ה' אֶחָד וּשְׁמוֹ אֶחָד. וְאָז (תהלים כג) ה' רֹעִי לֹא אֶחְסָר, וְכָתוּב בִּנְאוֹת דֶּשֶׁא יַרְבִּיצֵנִי עַל מֵי מְנֻחוֹת יְנַהֲלֵנִי נַפְשִׁי יְשׁוֹבֵב וְגוֹ'. ע\"כ תוספתא."],[5,"","וַיִּקַּח לוֹ יַעֲקֹב (בראשית ל), בָּחַר לוֹ לְחֶלְקוֹ וּלְגוֹרָלוֹ, מַקַּל לִבְנֶה לַח, צַד יָמִין, גָּוֶן לָבָן. לַח, הוּא צַד שֶׁל הַמַּיִם. וְלוּז, זֶה צַד שֶׁל הַשְּׂמֹאל, אָדם כְּוָרֹד. וְעַרְמוֹן, כָּלוּל זֶה בָּזֶה. וְכֻלָּם אוֹחֵז הַיָּמִין הַלָּבָן בְּצִבְעוֹ וְעוֹלֶה בָהֶם, שֶׁכָּתוּב מַחְשּף הַלָּבָן, שֶׁאַף עַל גַּב שֶׁאוֹחֵז לִשְׁנֵי הַצְּדָדִים, לוֹקֵחַ (נוטה) חֶלְקוֹ לְצַד יָמִין, וְנֶחְקָק בְּכֻלָּם, בְּצַד זֶה וּבְצַד זֶה, אָז נִקְרָא גֶבֶר שָׁלֵם, שָׁלֵם בַּכֹּל."],[6,"","מַה כָּתוּב אַחֲרָיו? (שם) וְהָיָה בְּכָל יַחֵם הַצּאן הַמְקֻשָּׁרוֹת וְשָׂם יַעֲקֹב אֶת הַמַּקְלוֹת וְגוֹ'. סֵתֶר הַסְּתָרִים לְחַכְמֵי לֵב נִמְסָר. בְּתוֹךְ מַחֲנוֹת עֶלְיוֹנִים קְדוֹשִׁים יֵשׁ מַדְרֵגוֹת עֶלְיוֹנוֹת אֵלּוּ עַל אֵלּוּ, אֵלּוּ פְּנִימִיִּים וְאֵלּוּ לְבַחוּץ. אֵלּוּ הַפְּנִימִיִּים מִתְחַבְּרִים בַּמֶּלֶךְ הַקָּדוֹשׁ, וּמִתְחַבְּרִים בְּיִשְׂרָאֵל, בָּנִים קְדוֹשִׁים לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וְאֵלּוּ נִקְרָאוֹת הַצּאן הַמְקֻשָּׁרוֹת, מַחֲנוֹת שֶׁל אֵלּוּ מִקֻשָּׁרוֹת, מַעְלָה וּמַטָּה."],[7,"","בְּשָׁעָֹה שֶׁהַתְּשׁוּקָה שֶׁלָּהֶם לְגַבֵּי הַזֹּהַר הָעֶלְיוֹן שֶׁלְּמַעְלָה, עַמּוּד הָאֶמְצָעִי, יַעֲקֹב הַשָּׁלֵם לָקַח אוֹתָם הַמַּקְלוֹת, תְּפִלִּין שֶׁל רֹאשׁ, בָּרְהָטִים, מָקוֹם וּמוֹשָׁב, לַהֲנָחַת הַתְּפִלִּין. וּמִכָּאן לוֹקְחִים אוֹר וְזִיו כָּל הַחֲיָלוֹת וּמַחֲנוֹת הָעֶלְיוֹנִים, אֵלּוּ שֶׁמִּתְקַשְּׁרִים לְמַעְלָה וּמִתְקַשְּׁרִים לְמַטָּה. כֵּיוָן שֶׁאֵלּוּ לוֹקְחִים מִתּוֹךְ הָרְהָטִים שִׁקְתוֹת הַמַּיִם, אָז אֵלּוּ הָיוּ מְקוֹרוֹת וּנְבִיעוֹת לְהוֹרִיד לְמַטָּה וְלָתֵת לְכֻלָּם."],[8,"","וּמִשּׁוּם כָּךְ הִפְרִישׁ יַעֲקֹב בֵּין הַמַּדְרֵגוֹת הָעֶלְיוֹנוֹת הַקְּדוֹשׁוֹת לַמַּדְרֵגוֹת הָאֲחֵרוֹת שֶׁל שְׁאָר הָעַמִּים, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ל) וַיָּשֶׁת לוֹ עֲדָרִים לְבַדּוֹ וְלֹא שָׁתָם עַל צֹאן לָבָן. (אלו) עֲדָרִים הִפְרִיד לוֹ לְעַצְמוֹ, שֶׁלֹּא יִהְיֶה לוֹ חֵלֶק בִּשְׁאָר הָאֻמּוֹת, וּכְמוֹ שֶׁהִפְרִישׁ לוֹ מַדְרֵגוֹת הָאֱמוּנָה לְמַעְלָה לְחֶלְקוֹ וּלְגוֹרָלוֹ, כָּךְ צָרִיךְ לְהַפְרִישׁ מַדְרֵגוֹת שֶׁל מַחֲנוֹת קְדוֹשִׁים לְמַטָּה, לִקְשֹׁר אוֹתָם עִמּוֹ בְּאֵלּוּ הַהֵיכָלוֹת שֶׁל הַגְּבִירָה."]]],[["וכלהו רשימין, ברשימו דמלכא עלאה. כמה דישראל, רשימין לתתא, בין כל שאר עממין, אוף דרגין דמשריין עלאין, רשימין אינון לחולקיה (דקודשא) לקודשא בריך הוא, בין כל שאר חילין, ומשריין עלאין. ועל דא בריר יעקב אינון לחולקיה ועדביה, רשימין לחולקא (ברזא) דמהימנותא, (ס\"א ובגין כך כתיב כי יעקב בחר לו יה ישראל לסגולתו יה עלאה איהו בריר חולקיה ועדביה רזא דמהימנותא) אוף הכי קדשא בריך הוא, בריר ליה, מכל שאר חילין ומשריין דעלמא.","ומשריין עלאין, מתפרשאן אלין מאלין. בשעתא דזהרא דנורא בנהירו דשכינתא אתגליא, כל אינון דרגין אחרנין, אתכספן, ומתעטפי מההוא זהרא ולא יכלו לקרבא לגביה. וכל אינון תקונין (ס\"א דרגין) קדישין, דאינון תקונא דיליה. בשעתא דאתגליא ההוא זהרא, מיד חדאן וסלקן לאתקרבא בהדיה, ולאתקשרא לגביה, ואיהו בהו אתתקנת, (אתתקן) וסתרא דא (בראשית ל׳:מ״ב) והיו העטופים ללבן והקשורים ליעקב.","ואצטריך לבררא (ס\"א לברכא) ולאתפרשא דרגין קדישין (ס\"א לחולקיה) דחולקיה. מאינון דרגין דשאר עמין, ובכלא אצטריך יעקב קדישא (ס\"א בוכרא דקדשא בריך הוא לאתקרבא) ועל דא קדשא בריך הוא כתיב באורייתא, מהימנותא דיליה, בגו סטרי (ס\"א סתרי) מלין אלין. זכאה חולקיה.","רִבִּי יֵיסָא זוּטָא הֲוָה שְׁכִיחַ קַמֵּיהּ דְּרִבִּי שִׁמְעוֹן, אָמַר לֵיהּ. הַאי דִכְתִיב (משלי י׳:ו׳) בְּרָכוֹת לְרֹאשׁ צַדִּיק, לַצַדִּיק מִבָּעֵי לֵיהּ, מַאי לְרֹאשׁ צַדִּיק. אָמַר לֵיהּ, רֹאשׁ צַדִּיק דָּא הִיא עֲטָרָה קַדִּישָׁא, וְאוּקְמוּהָ. תוּ, רֹאשׁ צַדִּיק, דָּא יַעֲקֹב, דְּאִיהוּ נָטִיל בִּרְכָאן, וְנָגִיד לוֹן לַצַדִּיק, וּמִתַּמָּן אִזְדְּרִיקוּ לְכָל עֵיבָר, וּמִתְבָּרְכָן כֻּלְּהוּ עַלְמִין.","אֲבָל הָא אוֹקִימְנָא, בְּרָכוֹת לְרֹאשׁ צַדִּיק, (ראש) צַדִּיק אִקְרֵי, הַהוּא אֲתַר (ס\"א ל\"ג רישא) דִּבְרִית, דְּמִנֵּיהּ נָפְקִין מַבּוּעִין לְבַר, נוּקְבָא דְּקִיסְטָא דְּחַמְרָא נָפִיק מִנֵּיהּ, אִיהוּ רֵישָׁא. כָּךְ רֹאשׁ צַדִּיק, הַהוּא אֲתַר, כַּד זָרִיק מַבּוּעִין לְנוּקְבָא, אִקְרֵי רֹאשׁ צַדִּיק. צַדִּיק אִיהוּ רֹאשׁ (נ\"א רישא לכל ברכאן) בְּגִין דְּכָל בִּרְכָאן בֵּיהּ שָׁרְיָין.","תוּ, הַהוּא בַּר נָשׁ, דְּזָכֵי לְמִנְטַר אָת קַיָּימָא קַדִּישָׁא, וְעֲבִיד פִּקּוּדֵי דְאוֹרַיְיתָא, צַדִּיק אִקְרֵי, וּמֵרִישֵׁיהּ וְעַד רַגְלוֹי הָכִי אִקְרֵי. וְכַד בִּרְכָאן נָגְדִין לְעָלְמָא, שַׁרְיָין עַל רֵישֵׁיהּ, וּמִנֵּיהּ קָיְימֵי בִּרְכָאן לְעַלְמָא, בִּבְנִין קַדִּישִׁין זַכָּאִין דְּאוֹקִים.","רִבִּי יֵיסָא תוּ שָׁאִיל וְאָמַר, (תהילים ל״ז:כ״ה) כְּתִיב נַעַר הָיִיתִי גַּם זָקַנְתִּי וְגו'. הַאי קְרָא אוּקְמוּהָ דְּשָׂרוֹ דְעַלְמָא אֲמָרוֹ, אִיהוּ אֲמָרוֹ בְּחָכְמְתָא, יַתִּיר מִמַּה דְּחָשְׁבִין בְּנֵי נָשָׁא. אָמַר לֵיהּ, בְּרִי יָאוֹת הוּא, דְּהָא בְּיִחוּדָא קַדִּישָׁא אִתְּמָר נַעַר הָיִיתִי גַּם זָקַנְתִּי וְהָכִי הוּא.","(תהילים ל״ז:כ״ה) וְלא רָאִיתִי צַדִּיק נֶעֱזָב, דָּא הוּא שְׁבָחָא דְּיִחוּדָא, דְּלָא אִשְׁתַּכַּח יוֹם בְּלָא לַיְלָה. דְּהָא לַיְלָה בֵּיהּ אִשְׁתַּכַּח תְּדִירָא, וְצַדִּיק אָחִיד לְעֵילָא וְאָחִיד לְתַתָּא.","וְזַרְעוֹ מְבַקֵּשׁ לָחֶם, מַאי הוּא. אֶלָּא, בְּשַׁעְתָּא דְּזָרִיק וְאִתְנְגִיד זַרְעָא, לָא תָּבַע לְנוּקְבָא. דְּהָא בַּהֲדֵיהּ שַׁרְיָא, דְּלָא אִתְפָּרְשָׁא מִנֵּיהּ לְעָלְמִין, וְזַמִּינָא הִיא לְגַבֵּיהּ. דְּהָא זַרְעָא לָא נָגִיד, אֶלָּא בְּשַׁעְתָּא דְּנוּקְבָא זְמִינָא, וְתִיאוּבְתָּא דְּתַרְוַויְיהוּ כְּחֲדָא בְּדִבּוּקָא חַד דְּלָא מִתְפָּרְשָׁן, וְעַל דָּא לָא אִצְטְרִיךְ לְמִתְבַּע עֲלָהּ.","אָמַר לֵיהּ, וּבְזִמְנָא דְגָלוּתָא לָאו הָכִי. אָמַר לֵיהּ זַרְעוֹ כְּתִיב, וְלָאו אִיהוּ. אֵימָתַי נָפִיק, כַּד נוּקְבָא בְּדִבּוּקָא חַד עִם דְּכוּרָא. וְאִי תֵימָא לא רָאִיתִי צַדִּיק נֶעֱזָב, בְּזִמְנָא דְגָלוּתָא מַאי הִיא.","אֶלָּא, הָא אָחִיד לְעֵילָא. וְלָא נֶעֱזָב לְעָלְמִין, בְּזִמְנָא אָחֳרָא, לא נֶעֱזָב מִנּוּקְבָא, אָחִיד לְעֵילָא, וְאָחִיד לְתַתָּא. אָחִיד לְעֵילָא, בְּזִמְנָא דְגָלוּתָא. בְּזִמְנָא אָחֳרָא, אָחִיד לִתְרֵין סִטְרִין, לְעֵילָא וְתַתָּא, וּלְעוֹלָם אֵינוֹ נְעֱזָב.","כְּתִיב, (בראשית א׳:י״ז) וַיִּתֵּן אֹתָם אֱלהִים בִּרְקִיעַ הַשָּׁמָיִם, דָּא צַדִּיק. וְאַף עַל גַּב דְּאִתְּמָר בִּרְקִיעַ הַשָּׁמַיִם, אֶלָּא בִּרְקִיעַ הַשָּׁמַיִם וַדַּאי, דְּאִיהוּ סִיּוּמָא דְגוּפָא.","תָּא חֲזֵי, תְּרִין רְקִיעִין אִינוּן, וְאִינוּן שֵׁירוּתָא וְסִיּוּמָא, דָּא כְּגַוְונָא דָא. שֵׁירוּתָא רְקִיעָא תְּמִינָאָה, בֵּיהּ שְׁקִיעָן כָּל כֹּכְבַיָא, זְעִירִין וְרַבְרְבִין. וְדָא הוּא רְקִיעָא עִלָּאָה סְתִימָאָה, דְּקָאִים כֹּלָּא וּמִנֵּיהּ נָפִיק כֹּלָּא. וְאִיהוּ תְּמִינָאָה, מִתַּתָּא לְעֵילָא, וְהוּא שֵׁירוּתָא לְאֲפָקָא מִנֵּיהּ כֹּלָּא.","כָּךָ אִיהוּ רְקִיעָא תְּמִינָאָה מֵעֵילָא לְתַתָּא, דְּבֵיהּ שְׁקִיעִין כָּל כֹּכְבַיָא, כָּל נְהוֹרִין וּבוֹצִינִין. וְהוּא נָטִיל כֹּלָּא וְדָא סִיּוּמָא דְכֹלָּא. כְּמָה דְהַהוּא רְקִיעָא תְּמִינָאָה, דְּאִיהוּ שֵׁירוּתָא דְּכֹלָּא. תַּלְיָין בֵּיהּ כָּל נְהוֹרִין וְנָטִיל לוֹן, וּמִנֵּיהּ נָפְקֵי. הָכִי נָמֵי הַאי, אִיהוּ רְקִיעָא תְּמִינָאָה, תַּלְיָין בֵּיהּ כָּל נְהוֹרִין וְנָטִיל לוֹן, וּמִנֵּיהּ נָפְקוּ לְכֻלְּהוּ עָלְמִין.","שֵׁירוּתָא וְסִיּוּמָא כְּגַוְונָא חַד קָיְימֵי, וְעַל דָּא אִיהוּ נָהָר דְּנָגִיד וְנָפִיק, וְלָא פָּסְקֵי מֵימוֹי לְעָלְמִין. כֹּלָּא לְמֶהוֵי סִיּוּמָא כְּשֵׁירוּתָא, וּבְגִין כָּךְ וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם, וְלָמָּה, לְהָאִיר עַל הָאָרֶץ.","וְאַף עַל גַּב דְּאִתְּמָר כֹּלָּא כְּגַוְונָא חָדָא קָיְימֵי, וְדָא הוּא בְּרִירָא דְמִלָּה, מַה בֵּין הַאי לְהַאי. אֶלָּא, דָּא אוֹקִים וְזָן לְעַלְמָא עִלָּאָה דְּאִיהוּ בֵּיהּ וּלְכָל אִינוּן סִטְרִין עִלָּאִין, וְדָא אוֹקִים וְזָן לְעַלְמָא תַּתָּאָה וּלְכָל אִינוּן סִטְרִין תַּתָּאִין.","וְאִי תֵימָא, עַלְמָא דִלְעֵילָא מַאן אִיהוּ, וְהָא (איהו) הַהוּא רְקִיעָא תְּמִינָאָה עִלָּאָה סְתִימָאָה, עַלְמָא דִלְעֵילָא אִיהוּ וְהָכִי אִקְרֵי, דְּהָא תְּרֵין עָלְמִין נִינְהוּ כְּמָה דְאִתְּמָר. אֶלָּא, אִיהוּ עַלְמָא עִלָּאָה, וְכָל אִינוּן דְּנָפְקֵי מִנֵּיהּ, עַל שְׁמֵיהּ אִקְרוּן. וְאִינוּן דְּנָפְקֵי מֵעַלְמָא תַּתָּאָה, עַל שְׁמֵיהּ אִקְרוּן. וְכָל הַאי וְהַאי כֹּלָּא חַד, בְּרִיךְ הוּא לְעָלַם וּלְעָלְמֵי עָלְמִין.","תָּא חֲזֵי (תהילים ק״ד:ט״ז) יִשְׂבְּעוּ עֲצֵי ה' אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע. מַאן לְבָנוֹן. הָא אוּקְמוּהָ וְאִתְּמָר, הַאי קְרָא (תהילים ק״ד:ט״ז) אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ חֲסִידָה בְּרוֹשִׁים בֵּיתָהּ. אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ, בְּאָן אֲתַר, בַּלְּבָנוֹן. וְאִלֵּין אִינוּן תְּרֵין צִפֳּרִים דְּקָאֲמָרָן בְּכַמָּה אֲתַר, וּמֵאִלֵּין אִתְפָּרְשָׁן כַּמָּה צִפֳּרִין אָחֳרָנִין, אֲבָל אִלֵּין עִלָּאִין וְנָפְקִין מִלְּבָנוֹן דְּאִיהוּ (ס\"א סתימאה) לְעֵילָא, וְרָזָא דְמִלָּה, (בראשית כ״ט:ט״ז) וּלְלָבָן שְׁתֵּי בָנוֹת וְגו'."],[[0,"וכלהו רשימין ברשימו וכו':","וכולם רשומים ברשימו של מלך העליון, שהוא ז\"א, דהיינו קו האמצעי, כי כמו שישראל רשומים ומצוינים בין כל שאר העמים, כך המדרגות של מחנות מלאכים העליונים הקדושים, רשומים לחלקו של הקב\"ה בין שאר הצבאות ומחנות מלאכים שאינם מקו אמצעי, ועל כן בחר יעקב לחלקו וגורלו סוד האמונה, שהיא הנוקבא, וגם הקב\"ה בחר ביעקב מכל שאר הצבאות והמחנות שבעולם."],[1,"ומשריין עלאין וכו':","המחנות העליונים נפרדים זה מזה, כי בשעה שזוהר האש, שבהארת השכינה, מתגלה, כל מדרגות האחרות, הנמשכים משמאל, מתבישים ומתעטפים, דהיינו שמתעלפים מחמת התשוקה, מאותו הזהר שאינם יכולים לקרב אליו. וכל אלו מדרגות הקדושות שהם בתקון שלו, של קו האמצעי, שהוא יעקב, הנה בשעה שזהר ההוא מתגלה, הם שמחים ועולים מיד להתקרב אליו ולהתקשר בו, והזהר מתתקן בהם. וזה סוד, \u0003והיו העטופים ללבן,\u0004 דהיינו הנמשכים משמאל, שהם מתעטפים בעת התגלות הזהר הנ\"ל. \u0003והקשורים ליעקב,\u0004 דהיינו המתוקנים להתקשר עמו כנ\"ל."],[2,"ואצטריך לבררא וכו':","והוצרך יעקב לבחור ולהפריד את המדרגות הקדושות שלחלקו, שהם הקשורות, מאלו המדרגות של שאר העמים, שהם העטופים, וכל זה הוצרך יעקב לעשות, ועל כן, כתב הקב\"ה בתורה את נאמנותו וצדקתו של יעקב, בתוך סתרי דברים האלו. אשרי חלקו. (ע\"כ ס\"ת.)"],[3,"ר' ייסא זוטא וכו':","ר\"י הקטן היה מצוי לפני ר' שמעון. אמר לו זה שכתוב, ברכות לראש צדיק, היה צריך לומר לצדיק, ולמה כתוב ראש צדיק. אמר לו, ראש צדיק הוא עטרה הקדושה, דהיינו עטרת יסוד. ובארוהו. עוד, ראש צדיק, זה יעקב, שהוא ת\"ת, וגופא ונקרא ראש צדיק, משום שהוא מקבל הברכות ומשפיע אותן לצדיק, דהיינו אל היסוד, שנקרא צדיק, ומשם נזרקים לכל צד, דהיינו לימין ושמאל שבמלכות, וכל העולמות מתברכים."],[4,"אבל הא אוקימנא וכו':","אבל בארנו את הכתוב, ברכות לראש צדיק, שאותו המקום שהוא ברית, נקרא צדיק, שממנו יוצאים מעינות לחוץ. כי הנקב של הכד שדרך שם שופכים היין, הוא ראש הכד, כך, ראש צדיק מקום ההוא בעת שזורק מעינות לנוקבא, נקרא ראש צדיק. הצדיק הוא ראש, משום שכל הברכות שורות בו ומושפעים ממנו."],[5,"תו, ההוא ב\"נ וכו':","עוד יש לפרש, כי אדם ההוא שזכה לשמור אות ברית קודש, ומקיים מצות התורה, נקרא צדיק, ומראשו ועד רגליו הוא בחינת צדיק, ועליו אמר הכתוב ברכות לראש צדיק. כי כאשר הברכות נמשכות לעולם, הן שורות על ראשו, וממנו נמצאות הברכות בעולם, בבנים קדושים וצדיקים שהוא מעמיד."],[6,"ר' ייסא תו שאיל וכו':","עוד שאל ר' ייסא, ואמר, כתוב נער הייתי גם זקנתי וגו'. מקרא זה בארוהו ששרו של עולם אמרו. והוא אמרו בחכמה רבה יותר ממה שחושבים בני אדם. וע\"כ רצה להבין ביאורו. אמר לו ר\"ש, בני, כן הוא, שיש בכתוב זה חכמה רבה, כי על היחוד הקדוש, נאמר הכתוב, נער הייתי גם זקנתי."],[7,"והכי הוא, ולא וכו':","וכן הוא ביאורו, ולא ראיתי צדיק נעזב, זה הוא שבחו של יחוד ז\"א ונוקביה, ללמדנו שאינו נמצא יום, שהוא ז\"א בלי לילה שהיא הנוקבא. כי הלילה נמצא דבוק ביום תמיד, דהיינו ז\"א בנוקביה. והצדיק, שהוא יסוד, נאחז למעלה, בז\"א, שהוא יום, ונאחז למטה, בנוקבא, שהוא לילה. שזה סוד היחוד השלם, בזווג תמידי שאינו נפסק."],[8,"וזרעו מבקש לחם:","מה הוא פירושו, ואומר, אלא בשעה שמשפיע הזרע והוא נמשך, אינו תובע ומבקש הנוקבא, כי היא נמצאת אז עמו, כי המה בזווג שאינו נפסק לעולם, והיא מוכנת לו, כי הזרע אינו נמשך רק בשעה שהנוקבא כבר מוכנת לו, ותשוקת שניהם כאחד, בדביקות אחת שאינו נפסק. וע\"כ אינו צריך לתבוע ולבקש אותה. ביאור הדברים. כי ב' חכמות הן בעולם אצילות א) חכמה עלאה שבא\"א, ב) חכמה תתאה שבנוקבא. ובכל המדרגות שבינתים, אין בהן חכמה. (כנ\"ל ב\"א דף רס\"ב ד\"ה אלא). וז\"ס השתוקקות ז\"א אל הנוקבא, כדי שישתלם על ידה בהארת החכמה. והנוקבא משתוקקת לז\"א, כדי לקבל ממנו זרעו, שהוא חסדים, כי חכמה בלי חסדים היא חשך וקפאון, (כנ\"ל דף קכ\"ב ד\"ה ויחמנה) ונמצא סוד הזרע, שהיסוד דז\"א, המכונה צדיק, משפיע לנוקבא, הוא חסדים. וז\"ש, \u0003בשעתא דזריק ואתנגיד זרעא, לא תבע לנוקבא,\u0004 שבשעה שהצדיק משפיע הזרע שהוא חסדים אינו תובע, לקבל את הארת הנוקבא, שהיא חכמה, ואומר על זה ב' טעמים, א) \u0003דהא בהדיה שריא, דלא אתפרשא מניה לעלמין,\u0004 כי הנוקבא נמצאת עמו, בזווג דלא פסיק, שפירושו, שזו\"ן מלבישים אז או\"א עלאין, שזווגם לא פסיק והם תמיד בחסדים מכוסים מחכמה. ע\"כ גם זווגם הם אינו נפסק, וגם הם בבחינת חסדים לבד כמו או\"א עלאין. ולפיכך אין הצדיק רוצה אז לקבל הארת חכמה מן הנוקבא. ב) \u0003וזמינא היא לגביה, דהא זרעא לא נגיד אלא בשעתא דנוקבא זמינא,\u0004 כי כבר נכלל בהארת הנוקבא, כי אין זרעו נמשך אלא בשעה שהנוקבא מוכנת לו, וכבר נכלל בהארתה, \u0003ותיאובתא דתרוויהו כחדא,\u0004 וע\"כ, עתה, השתוקקות שניהם אחת היא, ששניהם משתוקקים עתה אחר חסדים לבד, כי מקודם הזווג השתוקק הז\"א להכלל מחכמה, והנוקבא אחר חסדים, כנ\"ל, ועתה אחר שז\"א כבר נכלל בחכמה, אינו משתוקק יותר לחכמה אלא בחסדים לבד, וע\"כ הם \u0003בדבוקא חד דלא מתפרשן.\u0004 כלומר שזהו עצמו הוא הטעם, שהם בזווג שאינו נפסק, כי אין אחיזה לקליפות בשפע החסדים שיוצרך הזווג להפסק. אמנם אם היה חכמה בהארת הזווג, לא היו בזווג דלא פסיק, כי בעת שהתחתונים פוגמים מעשיהם. יש אחיזת הקליפה בזווג זו\"ן, והזווג נפסק."],[9,"א\"ל ובזמנא דגלותא וכו':","אמר לו, הרי בזמן הגלות אינו כן, שאין זו\"ן בזווג דלא פסיק, רק בעת שישראל בארצם ובית המקדש קיים, ולא בזמן הגלות. ומשיב, \u0003זרעו\u0004 כתוב, ולא הוא, שאינו כתוב \u0003והוא\u0004 מבקש לחם, אלא \u0003וזרעו\u0004 מבקש לחם, ומתי יוצא הזרע, רק כשהנוקבא היא בזווג עם הזכר. כלומר, שאין הכתוב מדבר, בצדיק עצמו אלא בזרעו, שהיא בהכרח בעת הזווג, ולא בעת הגלות. ושואל, ואם תאמר, הרי הכתוב אומר גם ולא ראיתי צדיק נעזב שהמדובר הוא בו עצמו, ויש לשאול, בזמן הגלות איך הוא, הרי אז הצדיק נעזב, ואין לו זווג עם הנוקבא."],[10,"אלא הא אחיד וכו':","ומשיב, אלא גם בזמן הגלות הוא נאחז למעלה בז\"א. ולעולם לא נעזב מז\"א, וע\"כ אומר הכתוב, ולא ראיתי צדיק נעזב, אפילו בזמן הגלות. ובזמן אחר, דהיינו בעת שבית המקדש קיים, הצדיק אינו נעזב גם מנוקבא, שאו הוא נאחז למעלה, בז\"א, ונאחז למטה בנוקבא. ונמצא, שבזמן הגלות הוא נאחז למעלה, בז\"א, ובזמן אחר, הוא נאחז בב' הצדדים, למעלה ולמטה, בז\"א ובנוקבא, ובין כך ובין כך לעולם אינו נעזב."],[11,"כתיב ויתן אותם אלקים ברקיע השמים:","זה הוא צדיק. דהיינו יסוד. ואע\"פ שנאמר \u0003ברקיע השמים,\u0004 והשמים הוא ז\"א ולא יסוד. אמנם \u0003ברקיע השמים,\u0004 הוא נקרא ודאי, שהוא סיום הגוף. פירוש. השמים הוא ז\"א, שהוא ת\"ת, ובחינת גוף של הספירות הכולל חג\"ת נה\"י, אשר יסוד הוא ספירה אחרונה שבו, ונבחן, כמו שהיסוד עומד בסיום הגוף, שהוא ז\"א, וע\"כ מכנהו הכתוב ברקיע השמים, דהיינו היסוד, העומד בסיום השמים, שפירושו בסיום ז\"א."],[12,"תא חזי תרין רקיעין וכו':","בוא וראה, ב' רקיעים הם, והם התחלה וסיום, וזה שוה לזה. ההתחלה, הוא, רקיע השמיני, בו תקועים כל הככבים קטנים וגדולים, וזהו רקיע העליון הסתום. המקיים את הכל וממנו יוצא הכל, והוא השמיני שממטה למעלה, והוא ההתחלה להוציא ממנו את הכל. ביאור הדברים להלן בדבור הסמוך."],[13,"כך איהו רקיעא תמינאה וכו':","כך הוא, רקיע השמיני שממעלה למטה, שבו תקועים כל הככבים, כל האורות והנרות. והוא מקבל הכל וזהו סיום הכל."],[13,"","ביאור הדברים. \u0003רקיע,\u0004 הוא הפרסא, שפירושו סיום החדש מצמצום הב', המוציא בינה ותו\"מ דכל מדרגה ומורידם להמדרגה שמתחתיה, ובעת גדלות חוזרת הפרסא, שהיא הרקיע, לסיום דצמצום א', ומחזיר הספירות בינה ותו\"מ אל המדרגה. ובדרך כלל, יש ג' פרסאות בעולם האצילות א) הוא הרקיע הראשון שבמקום הפה דא\"א, שהוציא בינה ותו\"מ מראש דא\"א למדרגת או\"א, ונשאר בראש דא\"א כתר וחכמה בלבד, והוא רקיע הראשון, כי בפרצוף עתיק אין שם בחינת צמצום ב' כמפורש, אלא בקע ולא בקע. (כנ\"ל ב\"א דף ה' ד\"ה כשהאצילה). ב) הוא רקיע האמצעי העומד במקום החזה דא\"א, ומוציא בינה ותו\"מ דחג\"ת דא\"א, למקום ישסו\"ת וזו\"ן שלמטה מחזה. ג) הוא רקיע התחתון העומד במקום סיום עולם אצילות, ומוציא בינה ותו\"מ דזו\"ן דאצילות לבי\"ע. (וכבר נתבאר זה לעיל בראשית א' דף רפ\"ט ד\"ה ביאור, ע\"ש כל ההמשך). וכאן אינו מדבר מרקיע האמצעי, אלא מרקיע הראשון והאחרון בלבד."],[13,"","וזה אמרו, \u0003ב' רקיעין אינון, ואינון שירותא וסיומא, דא כגוונא דא,\u0004 דהיינו הרקיע שבמקום פה דא\"א, שהוא התחלת כל, והרקיע שבמקום עטרת יסוד דז\"א המסיים כל העולם האצילות. \u0003רקיעא תמינאה, ביה שקיעין כל ככביא זעירין ורברבין.\u0004 ככביא הם המוחין, והן קטנות והן גדלות תלוים ויוצאים מרקיע הראשון הזה, כי בזמן שמוציא בינה ותו\"מ דראש א\"א לחוץ מושפעים מוחין דקטנות לכל הפרצופין, ובעת שהרקיע חוזר להסיום שבצמצום א' מוחזרים בינה ותו\"מ דראש א\"א, והגדלות מושפעת בכל המדרגות (כמ\"ש שם דף ר\"צ ד\"ה בגין) \u0003ודא הוא רקיעא עלאה סתימאה,\u0004 ונקרא סתימאה משום שהוא מתחת החכמה סתימאה דא\"א. \u0003דקאים כלא\u0004 היינו כל מיני הגדלות, \u0003ומניה נפיק כלא,\u0004 היינו כל מיני הקטנות, \u0003ואיהו תמינאה מתתא לעילא,\u0004 כי א\"א ה\"ס חכמה, מבחינת מ\"ה, (כנ\"ל בפתיחה לחכמת הקבלה אות קכ\"ד ע\"ש) ומן עטרת יסוד עד החכמה הוא שמונה ספירות שהם חו\"ב וחג\"ת נה\"י. וע\"כ נבחן לשמיני. \u0003והוא שירותא לאפקא מניה כלא,\u0004 כי מבחינת הפרצוף עתיק שמלפניו, אינו נמשך מוחין לאבי\"ע (כמ\"ש שם ב\"א דף ו' ר\"ה בתר ע\"ש)."],[13,"","וז\"ש \u0003כך איהו רקיע תמינאה מעילא לתתא,\u0004 דהיינו הרקיע שבמקום עטרת יסוד דז\"א, שהוא השמיני מלמעלה למטה, דהיינו כשמתחילים לספור מא\"א, שהוא חכמה, עד היסוד הוא שמונה ספירות. \u0003דביה שקיעין כל ככביא כל נהורין ובוצינין,\u0004 שממנו באים כל מיני המוחין לנוקבא ולכל התחתונים דרי בי\"ע, כי בעת שמוציא בינה ותו\"מ דזו\"ן לחוץ מאצילות נמצאים הנוקבא וכל התחתונים בקטנות, ובעת שמתבטל הצמצום ב' ומחזיר את בינה ותו\"מ דזו\"ן לאצילות מקבלים כל התחתונים מוחין דגדלות (כמ\"ש ב\"א דף ר\"צ ד\"ה בגין ע\"ש) \u0003והוא נטיל כלא,\u0004 הוא לוקח מהעליונים כל המוחין בשביל התחתונים, \u0003ודא סיומא דכלא\u0004 שהוא המסיים כל האצילות כנ\"ל. ואין לשאול, הרי המלכות מסיימת האצילות ולא היסוד. והענין הוא, כי מעטרת יסוד נבנה כל פרצוף המלכות, וע\"כ נחשב הסיום על עטרת יסוד."],[13,"כמה דההוא רקיעא וכו':","כמו שרקיע השמיני העליון, הוא התחלה לכל, ובו תלוים כל האורות שמקבל אותם מעליונים ממנו, וממנו יוצאים לכל פרצופי האצילות כמ\"ש לעיל, כך הוא רקיע השמיני התחתון, תלוים בו כל האורות שמקבל אותם מהעליונים ממנו, וממנו הם יוצאים לכל העולמות, דהיינו אל הנוקבא ובי\"ע."],[14,"שירותא וסיומא כגוונא חד וכו':","ההתחלה והסיום דהיינו ב' רקיעים הנ\"ל, באופן אחד נמצאים, ועל כן הרקיע התחתון הוא נהר הנמשך ויוצא ומימיו אינם נפסקים לעולם, הכל הוא, שישתוה הסיום אל ההתחלה, וע\"כ ויתן אותם אלקים ברקיע השמים. שהוא רקיע התחתון. ולמה הם שם בשביל להאיר על הארץ. שהוא הנוקבא ובי\"ע."],[15,"ואע\"ג דאתמר וכו':","ואע\"פ שאמרנו, שהכל, דהיינו הרקיע העליון והרקיע התחתון, הם באופן אחד, וזה הוא דבר ברור, עכ\"ז יש בהכרח איזה הפרש ביניהם, ויש לשאול, מהו בין זה לזה. ומשיב, אלא זה דהיינו הרקיע העליון, מקיים וזן לעולם העליון, שהוא בו, ולכל אלו הבחינות העליונות. וזה דהיינו הרקיע התחתון, מקיים וזן לעולם התחתון, שהוא הנוקבא, ולכל אלו הבחינות התחתונות שבבי\"ע."],[16,"ואי תימא עלמא וכו':","ואם תאמר, עולם העליון מי הוא, הלא אותו רקיע השמיני העליון הסתום, הוא עצמו הוא עולם העליון, וכן הוא נקרא, כי ב' עולמות הם ולא יותר, כמו שלמדנו, ואיך תאמר, שהוא הזן את עולם העליון, שמשמע שהוא בחינה אחרת מן עולם העליון. ומשיב, אלא רקיע העליון עצמו, הוא עולם העליון, וכל אלו המדרגות היוצאים ממנו נקראים על שמו, דהיינו עולם העליון. וכל זה וזה, דהיינו הרקיע העליון והתחתון, הכל אחד. ברוך הוא לעולם ולעולמי עולמים."],[16,"","ולא יקשה לך שלעיל אמרנו שרקיע העליון הוא במקום פה דא\"א, וכאן אומר שהוא עולם העליון, ועולם העליון הוא בינה. והענין הוא כי ע\"כ אומר \u0003דהא תרין עלמין נינהו,\u0004 כלומר שאין יותר בכל פרצוף מן שני עולמות, אשר למעלה מחזה נבחן לעולם העליון, ולמטה מחזה לעולם התחתון. ולפיכך גם למעלה מחזה דא\"א נבחן כולו לעולם העליון. וגם הוא נבחן לבינה, כי הרקיע שה\"ס צמצום ב' לא נעשה אלא על בינה דא\"א שהוציאה לחוץ מראש."],[17,"תא חזי ישבעו עצי וגו':","מה הוא \u0003לבנון,\u0004 ואומר כבר בארוהו, וה\"ס בינה שחזרה לחכמה. כי \u0003לבנון\u0004 נוטריקון \u0003ל\"ב\u0004 נתיבות החכמה ו \u0003נון\u0004 שערי בינה. (ועי' לעיל ב\"א דף רמ\"ג ד\"ה ושוי) וביארו מקרא הזה, אשר שם צפרים יקננו חסידה ברושים ביתה. ושואל \u0003אשר שם צפרים יקננו,\u0004 באיזה מקום. ומשיב היינו \u0003בלבנון\u0004 שהיא בינה עלאה דא\"א שחזרה לחכמה, ואלו הם ב' צפרים שבארנו בכמה מקומות, דהיינו ב' נוקבין דז\"א, לאה ורחל. ומאלו מתפרדות כמה צפרים אחרים, דהיינו בבי\"ע, אבל אלו ב' צפרים, הן עליונות, דהיינו שבאצילות, והן יוצאות \u0003מלבנון,\u0004 שהוא למעלה, וסוד הדבר, וללבן שתי בנות וגו', דהיינו ב' צפרים לאה ורחל. ולבן ה\"ס לבנון, (כנ\"ל ב\"א דף רמ\"ג ד\"ה ושוי ע\"ש) כי לבן ה\"ס דכר ולבנון דכר עם נוקבא."]],[[0,"","וְכֻלָּם רְשׁוּמִים בַּסִּימָן שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן, כְּמוֹ שֶׁיִּשְׂרָאֵל רְשׁוּמִים לְמַטָּה בֵּין כָּל שְׁאָר הָאֻמּוֹת, אֲף מַדְרֵגוֹת שֶׁל מַחֲנוֹת עֶלְיוֹנִים רְשׁוּמִים הֵם לְחֶלְקוֹ (של הקדשה) שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּין כָּל שְׁאָר הַחֲיָלוֹת וּמַחֲנוֹת עֶלְיוֹנִים. וְעַל זֶה בֵּרַר יַעֲקֹב אֶת אֵלּוּ לְחֶלְקוֹ וְגוֹרָלוֹ, רְשׁוּמִים לַחֵלֶק (בסוד) שֶׁל הָאֱמוּנָה, (משום כך כתוב כי י קב בחר לו יה ישראל לסגלתו, יה עליון הוא, ברר חלקו וגורלו סוד האמונה) אַף כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּרַר לוֹ מִכָּל שְׁאָר צְבָאוֹת וּמַחֲנוֹת שֶׁל הָעוֹלָם."],[1,"","וּמַחֲנוֹת עֶלְיוֹנִים נִפְרָדִים אֵלּוּ מֵאֵלּוּ. בְּשָׁעָה שֶׁזֹּהַר שֶׁל אֵשׁ בְּהֶאָרַת הַשְּׁכִינָה מִתְגַּלֶּה, כָּל הַמַּדְרֵגוֹת הָאֲחֵרוֹת הָאֵלּוּ מִתְבַּיְּשׁוֹת, וּמִתְכַּסּוֹת מֵהַזֹּהַר הַהוּא, וְלֹא יָכְלוּ לְהִתְקָרֵב אֵלָיו. וְכָל אֵלּוּ הַתִּקּוּנִים (מדרגות) הַקְּדוֹשִׁים, שֶׁהֵם תִּקּוּנִים שֶׁלּוֹ. בְּשָׁעָה שֶׁמִּתְגַּלֶּה הַזֹּהַר הַהוּא, מִיָּד שְׂמֵחִים וְעוֹלִים לְהִתְקָרֵב עִמּוֹ וּלְהִתְקַשֵּׁר אֶצְלוֹ, וְהוּא בָהֶם נִתְקָן, וְסוֹד זֶה - (בראשית ל) וְהָיָה הָעֲטֻפִים לְלָבָן וְהַקְּשֻׁרִים לְיַעֲקֹב."],[2,"","וְצָרִיךָ לְבָרֵר (לברך) וּלְהַבְדִּיל מַדְרֵגוֹת קְדוֹשׁוֹת (ס\"א לחלקו) שֶׁל חֶלְקוֹ מֵאֵלּוּ הַמַּדְרֵגוֹת שֶׁל שְׁאָר הָעַמִּים, וּבְכֻלָּם צָרִיךְ יַעֲקֹב הַקָּדוֹשׁ (בכור של הקדוש ברוך הוא להתקרב), וְעַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא כָּתַב בַּתּוֹרָה, אֱמוּנָה שֶׁלּוֹ, בְּתוֹךְ צִדְדֵי (ס\"א סתרי) מִלִּים אֵלּוּ. אַשְׁרֵי חֶלְקוֹ."],[3,"","רַבִּי יֵיסָא הַקָּטָן הָיָה מָצוּי לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, זֶה שֶׁכָּתוּב (משלי י) בְּרָכוֹת לְרֹאשׁ צַדִּיק, הָיָה צָרִיךְ לִהְיוֹת לַצַּדִּיק, מַה זֶּה לְרֹאשׁ צַדִּיק? אָמַר לוֹ, רֹאשׁ צַדִּיק זוֹ הִיא הָעֲטָרָה הַקְּדוֹשָׁה, וּבֵאֲרוּהָ. עוֹד, רֹאשׁ צַדִּיק זֶה יַעֲקֹב, שֶׁנָּטַל אֶת הַבְּרָכוֹת וְהִשְׁפִּיעַ אוֹתָם לַצַּדִּיק, וּמִשָּׁם נִזְרְקוּ לְכָל עֵבֶר, וְכָל הָעוֹלָמוֹת מִתְבָּרְכִים."],[4,"","אֲבָל הִנֵּה בֵּאַרְנוּ, בְּרָכוֹת לְרֹאשׁ צַדִּיק - (ראש) צַדִּיק נִקְרָא אוֹתוֹ הַמָּקוֹם (ראש) שֶׁל הַבְּרִית, שֶׁמִּמֶּנּוּ יוֹצְאִים מַעְיָנוֹת הַחוּצָה. הַנֶּקֶב שֶׁל הַכַּד שֶׁיּוֹצֵא מִמֶּנּוּ הַיַּיִן הוּא הָרֹאשׁ, כָּךְ רֹאשׁ צַדִּיק, אוֹתוֹ מָקוֹם, כְּשֶׁזּוֹרֵק מַעְיָנוֹת לַנְּקֵבָה, נִקְרָא רֹאשׁ צַדִּיק. הַצַּדִּיק הוּא רֹאשׁ (ראש לכל הברכות) מִשּׁוּם שֶׁכָּל הַבְּרָכוֹת שְׁרוּיוֹת בּוֹ."],[5,"","עוֹד, אוֹתוֹ הָאָדָם שֶׁזּוֹכֶה לִשְׁמֹר אֶת אוֹת בְּרִית הַקֹּדֶשׁ וְעוֹשֶׂה אֶת מִצְווֹת הַתּוֹרָה נִקְרָא צַדִּיק, וּמֵרֹאשׁוֹ וְעַד רַגְלוֹ כָּךְ נִקְרָא. וּכְשֶׁהַבְּרָכוֹת שׁוֹפְעוֹת לָעוֹלָם, הֵן שׁוֹרוֹת עַל רֹאשׁוֹ, וּמִמֶּנּוּ עוֹמְדוֹת הַבְּרָכוֹת לָעוֹלָם בַּבָּנִים הַקְּדוֹשִׁים הַצַּדִּיקִים שֶׁהֵקִים."],[6,"","עוֹד שָׁאַל רַבִּי יֵיסָא וְאָמַר, כָּתוּב (תהלים לז) נַעַר הָיִיתִי גַּם זָקַנְתִּי וְגוֹ'. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ שֶׁשָּׂרוֹ שֶׁל עוֹלָם אָמַר אוֹתוֹ. הוּא אָמַר אוֹתוֹ בְּחָכְמָה יוֹתֵר מִמַּה שֶּׁחוֹשְׁבִים בְּנֵי אָדָם. אָמַר לוֹ, בְּנִי, יָפֶה הוּא, שֶׁהֲרֵי בַּיִּחוּד הַקָּדוֹשׁ נֶאֱמַר נַעַר הָיִיתִי גַּם זָקַנְתִּי."],[7,"","וְכָךְ הוּא, וְלֹא רָאִיתִי צַדִּיק נֶעֱזָב - זֶה הַשֶּׁבַח שֶׁל הַיִּחוּד שֶׁלֹּא נִמְצָא יוֹם לְלֹא לַיְלָה, שֶׁהִנֵּה הַלַּיְלָה תָּמִיד נִמְצָא בּוֹ, וְהַצַּדִּיק אָחוּז לְמַעְלָה וְאָחוּז לְמַטָּה."],[8,"","וְזַרְעוֹ מְבַקֶּשׁ לָחֶם, מַה הוּא? אֶלָּא בְּשָׁעָה שֶׁזּוֹרֵק וְנִשְׁפָּע הַזֶּרַע, אֵינוֹ תוֹבֵעַ אֶת הַנְּקֵבָה, שֶׁהֲרֵי הִיא שׁוֹרָה עִמּוֹ, שֶׁאֵין נִפְרֶדֶת מִמֶּנּוּ לְעוֹלָמִים וּזְמִינָה הִיא אֶצְלוֹ, שֶׁהֲרֵי אֵין זֶרַע שׁוֹפֵעַ אֶלָּא בְּשָׁעָה שֶׁהַנְּקֵבָה זְמִינָה, וּתְשׁוּקַת שְׁנֵיהֶם יַחַד בְּדִבּוּק אֶחָד, שֶׁאֵין נִפְרָדִים, וְלָכֵן לֹא צָרִיךְ לִתְבֹּעַ אוֹתָהּ."],[9,"","אָמַר לוֹ, וּבִזְמַן הַגָּלוּת לֹא כָּךְ? אָמַר לוֹ, כָּתוּב זַרְעוֹ, וְאֵינוֹ. מָתַי יוֹצֵא? כְּשֶׁהַנְּקֵבָה בְּדִבּוּק אֶחָד עִם הַזָּכָר. וְאִם תֹּאמַר, לֹא רָאִיתִי צַדִּיק נֶעֱזָב - בִּזְמַן שֶׁל הַגָּלוּת מַה הִיא?"],[10,"","אֶלָּא זֶה אָחוּז לְמַעְלָה וְלֹא נֶעֱזָב לְעוֹלָמִים. בִּזְמַן אַחֵר לֹא נֶעֱזָב מֵהַנְּקֵבָה, אָחוּז לְמַעְלָה וְאָחוּז לְמַטָּה. אָחוּז לְמַעְלָה - בַּזְּמַן שֶׁל הַגָּלוּת. בִּזְמַן אַחֵר אוֹחֵז אֶת שְׁנֵי הַצְּדָדִים, לְמַעְלָה וּלְמַטָּה, וּלְעוֹלָם אֵינוֹ נֶעֱזָב."],[11,"","כָּתוּב (בראשית א) וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם, זֶה צַדִּיק, וְאַף עַל גַּב שֶׁנֶּאֱמַר בִּרְקִיעַ הַשָּׁמַיִם, אֶלָּא בִּרְקִיעַ הַשָּׁמַיִם וַדַּאי, שֶׁהוּא סִיּוּם הַגּוּף."],[12,"","בֹּא רְאֵה, שְׁנֵי רְקִיעִים הֵם, וְהֵם הָרֵאשִׁית וְהַסִּיּוּם, זֶה כְּמוֹ זֶה. רֵאשִׁית הָרָקִיעַ הַשְּׁמִינִי בּוֹ שְׁקוּעִים כָּל הַכּוֹכָבִים, קְטַנִּים וּגְדוֹלִים, וְזֶהוּ הָרָקִיעַ הָעֶלְיוֹן הַנִּסְתָּר שֶׁמְּקַיֵּם הַכֹּל, וּמִמֶּנּוּ יוֹצֵא הַכֹּל, וְהוּא הַשְּׁמִינִי מִמַּטָּה לְמַעְלָה, וְהוּא הָרֵאשִׁית לְהוֹצִיא מִמֶּנּוּ הַכֹּל."],[13,"","כָּךָ הוּא הָרָקִיעַ הַשְּׁמִינִי מִמַּעְלָה לְמַטָּה, שֶׁבּוֹ שְׁקוּעִים כָּל הַכּוֹכָבִים, כָּל הָאוֹרוֹת וְהַמְּאוֹרוֹת, וְהוּא נוֹטֵל אֶת הַכֹּל, וְזֶה הַסִּיּוּם שֶׁל הַכֹּל. כְּמוֹ שֶׁאוֹתוֹ הָרָקִיעַ הַשְּׁמִינִי, שֶׁהוּא רֵאשִׁית הַכֹּל, תְּלוּיִים בּוֹ כָּל הָאוֹרוֹת, וְנוֹטֵל אוֹתָם, וּמִמֶּנּוּ יוֹצְאִים - כָּךְ גַּם זֶה, אוֹתוֹ רָקִיעַ הַשְּׁמִינִי תְּלוּיִים בּוֹ כָּל הָאוֹרוֹת וְנוֹטֵל אוֹתָם, וּמִמֶּנּוּ יָצְאוּ לְכָל הָעוֹלָמוֹת."],[14,"","הָרֵאשִׁית וְהַסִּיּוּם עוֹמְדִים כְּגָוֶן אֶחָד, וְעַל כֵּן הוּא הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא וְלֹא פוֹסְקִים מֵימָיו לְעוֹלָמִים, הַכֹּל שֶׁיִּהְיֶה הַסִּיּוּם כְּמוֹ הָרֵאשִׁית, וּמִשּׁוּם כָּךְ וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם, וִלָמָּה? לְהָאִיר עַל הָאָרֶץ."],[15,"","וְאַףֹ עַל גַּב שֶׁנֶּאֱמַר, הַכֹּל עוֹמְדִים כְּגָוֶן אֶחָד, וְזֶהוּ בֵּרוּר הַדָּבָר. מַה בֵּין זֶה לָזֶה? אֶלָּא זֶה מֵקִים וְזָן אֶת הָעוֹלָם הָעֶלְיוֹן שֶׁהוּא בּוֹ וְאֶת כָּל אוֹתָם הַצְּדָדִים הָעֶלְיוֹנִים, וְזֶה מֵקִים וְזָן אֶת הָעוֹלָם הַתַּחְתּוֹן וְאֶת כָּל אוֹתָם הַצְּדָדִים הַתַּחְתּוֹנִים."],[16,"","וְאִם תֹּאמַר, הָעוֹלָם שֶׁלְּמַעְלָה מִי הוּא? וַהֲרֵי (הוא) אוֹתוֹ הָרָקִיעַ הַשְּׁמִינִי הָעֶלְיוֹן הַנִּסְתָּר הוּא הָעוֹלָם שֶׁלְּמַעְלָה, וְכָךְ נִקְרָא, שֶׁהֲרֵי שְׁנֵי עוֹלָמוֹת הֵם, כְּמוֹ שֶׁנִּתְבָּאֵר. אֶלָּא הוּא עוֹלָם עֶלְיוֹן, וְכָל אוֹתָם שֶׁיּוֹצְאִים מִמֶּנּוּ נִקְרָאִים עַל שְׁמוֹ, וְאוֹתָם שֶׁיּוֹצְאִים מִן הָעוֹלָם הַתַּחְתּוֹן נִקְרָאִים עַל שְׁמוֹ, וְכָל זֶה וָזֶה הַכֹּל אֶחָד, בָּרוּךְ הוּא לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים."],[17,"","בֹּא רְאֵה, (תהלים קד) יִשְׂבְּעוּ עֲצֵי ה' אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע. מִי הַלְּבָנוֹן? הֲרֵי פֵּרְשׁוּהוּ וְנִתְבָּאֵר. הַפָּסוּק הַזֶּה, אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ חֲסִידָה בְּרוֹשִׁים בֵּיתָהּ - אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ, בְּאֵיזֶה מָקוֹם? בַּלְּבָנוֹן. וְאֵלּוּ הֵן שְׁתֵּי הַצִּפֳּרִים שֶׁאָמַרְנוּ בְּכַמָּה מְקוֹמוֹת, וּמֵאֵלּוּ נִפְרָדוֹת כַּמָּה צִפֳּרִים אֲחֵרוֹת. אֲבָל אֵלּוּ עֶלְיוֹנוֹת, וְיוֹצֵאת מִן לְבָנוֹן, שֶׁהוּא (סתום) לְמַעְלָה, וְסוֹד הַדָּבָר - וּלְלָבָן שְׁתֵּי בָנוֹת וְגוֹ'."]]],[["חֲסִידָה בְּרוֹשִׁים בֵּיתָהּ, (ס\"א דא לאה) בְּאִינוּן שִׁית בְּנִין עִלָּאִין, שִׁית סִטְרִין דְּעָלְמָא, כְּמָה דְאִתְּמָר. אַמַּאי אִקְרֵי חֲסִידָה. אֶלָּא, הַאי עַלְמָא עִלָּאָה אַף עַל גַּב דְּנוּקְבָא אִיהִי, קָרִינָן לָהּ דָּכָר, דְּכַד אִתְפַּשַּׁט, כָּל טִיבוּ וְכָל נְהִירוּ מִנֵּיהּ נָפִיק.","וּבְגִין כָּךְ דְּאִיהִי חֲסִידָה, נָפִיק (מתמן) מִינָהּ חֶסֶ\"ד, דְּאִיהוּ נְהוֹרָא קַדְמָאָה, דִּכְתִיב, (בראשית א׳:ג׳) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר. וְעַל דָּא בְּרוֹשִׁים בֵּיתָהּ. בְּרוֹשִׁים, אַל תִּקְרֵי בְּרוֹשִׁים, אֶלָּא בְּרָאשִׁים. דְּהָא עַלְמָא אָחֳרָא, בְּתַתָּאִין בֵּיתָהּ, וְאִיהִי בֵּי דִינָא דְעַלְמָא. וּלְזִמְנִין אִקְרֵי כְּגַוְונָא דִלְעֵילָא, בְּכָל אִינוּן שְׁמָהָן.","וְעַל אֲתַר דָּא כְּתִיב, (בראשית ו׳:ו׳) וַיִּנָּחֶם יְיָ וַיִּתְעַצֵּב אֶל לִבּוֹ. חֲרוֹן אַף יְיָ. דְּהָא בְּאֲתַר דָּא תַּלְיָא. דְהָא כָּל מַה דִּלְעֵילָא, כֹּלָּא אִיהוּ בִּנְהִירוּ, חַיִּין לְכָל סִטְרִין. וְעַל דָּא תָּנִינָן, אֵין עַצְבוּת לִפְנֵי הַמָּקוֹם, לִפְנֵי דַיְיקָא. וְעַל דָּא כְּתִיב, (תהילים ק׳:ב׳) עִבְדּוּ אֶת יְיָ בְּשִׂמְחָה בֹּאוּ לְפָנָיו בִּרְנָנָה. עִבְדּוּ אֶת יְיָ בְּשִׂמְחָה, לָקֳבֵיל עַלְמָא עִלָּאָה, בֹּאוּ לְפָנָיו בִּרְנָנָה לָקֳבֵיל עַלְמָא תַּתָּאָה. זַכָּאִין אִינוּן יִשְׂרָאֵל בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי. בְּגִין כָּךְ כְּתִיב, (דברים ל״ג:כ״ט) אַשְׁרֶיךָ יִשְׂרָאֵל מִי כָמוֹךָ עַם נוֹשַׁע בַּיְיָ מָגֵן עֶזְרְךָ וַאֲשֶׁר חֶרֶב גַּאֲוָתֶךָ וְיִכָּחֲשׁוּ וְגו'.","(בראשית ל׳:ל״ח) וַיַּצֵּג אֶת הַמַּקְלוֹת אֲשֶׁר פִּצֵּל בָּרְהָטִים וְגו'. פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (משלי ט׳:י״ב) אִם חָכַמְתָּ חָכַמְתָּ לָךְ וְלַצְתָּ לְבַדְּךָ תִשָׂא. אִם חָכַמְתָּ חָכַמְתָּ לָךְ, תָּא חֲזֵי, וַוי לְאִינוּן חַיָּיבֵי עַלְמָא, דְּלָא יָדְעִין וְלָא מַשְׁגִּיחִין בְּמִלֵּי דְאוֹרַיְיתָא. וְכַד אִינוּן מַשְׁגִּיחִין בָּהּ, בְּגִין דְּלֵית לוֹן סֻכְלְתָנוּ, מִלִּין דְּאוֹרַיְיתָא דַמְיָין בְּעֵינַיְיהוּ כְּאִילּוּ כֻּלְּהוּ מָלֵי רֵיקַנְיָא, וְלֵית בְּהוּ תּוֹעַלְתָּא. וְכֹלָּא בְּגִין דְּאִינוּן רֵקָנִין מִדַּעְתָּא וְסֻכְלְתָנוּ. דְּהָא כָּל מִילֵי דְאוֹרַיְיתָא, כֻּלְּהוּ מִלִּין עִלָּאִין וְיַקִּירִין. וְכָל מִלָּה וּמִלָּה כְּתִיב בָּהּ (משלי ג׳:ט״ו) יְקָרָה הִיא מִפְּנִינִים וְכָל חֲפָצִים לא יִשְׁווּ בָהּ (באורייתא).","וְכָל אִינוּן טִפְּשִׁין, אֲטִימִין דְּלִבָּא, כַּד חָמָאן מִלֵּי דְאוֹרַיְיתָא, לָא דַי לוֹן דְּלָא יָדְעֵי, אֶלָּא דְּאִינוּן אָמְרֵי, דְּאִינְהוּ מִלִּין פְּגִימִין, מִלֵּי דְּלֵית בְּהוּ תּוֹעַלְתָּא. וַוי לוֹן, כַּד יִתְבַּע לוֹן קוּדְשָׁא בְּרִיךְ הוּא, עֶלְבּוֹנָא דְאוֹרַיְיתָא, וְיִתְעַנְּשׁוּן עוֹנָשָׁא דְּמָרְדֵי בְּמָארֵיהוֹן.","מַה כְּתִיב בְּאוֹרַיְיתָא, (דברים לב) כִּי לא דָבָר רֵק הוּא מִכֶּם, וְאִי אִיהוּ רֵק מִכֶּם אִיהוּ, דְּהָא אוֹרַיְיתָא כֹּלָּא, מַלְיָיא מִכָּל אֲבָנִין טָבִין וּמַרְגְּלָאן יַקִּירִין, מִכָּל טָבִין דְּעַלְמָא. כְּמָה דְאַתְּ אָמֵר וְכָל חֲפָצִים לֹא יִשְׁווּ בָהּ, וְהֵיךְ יֵימְרוּן דְּאִיהִי רֵיקַנְיָא.","וּשְׁלמֹה מַלְכָּא אָמַר, אִם חָכַמְתָּ חָכַמְתָּ לָךְ, דְּכַד יִתְחַכַּם בַּר נָשׁ בְּאוֹרַיְיתָא, תּוֹעַלְתָּא דִּילֵיהּ אִיהוּ. דְּהָא בְּאוֹרַיְיתָא לָא יָכִיל לְאוֹסָפָא אֲפִילּוּ אָת אַחַת. וְלַצְתָּ לְבַדְּךָ תִשָּׂא, דְּהָא אוֹרַיְיתָא, לָא יִגָּרַע מִשִּׁבְחָהָא כְּלוּם, וְלֵיצָנוּתָא, דִּילֵיהּ אִיהוּ, וְאִשְׁתָּאַר בֵּיהּ לְאוֹבָדָא לֵיהּ מֵהַאי עַלְמָא וּמֵעַלְמָא דְאָתֵי.","תָּא חֲזֵי, כַּד אַתְוָון עִלָּאִין, מִתְחַבְּרָן כֻּלְּהוּ בְּהַאי דַרְגָא, סוֹפָא דְּכָל דַּרְגִּין קַדִּישִׁין עִלָּאִין, וְאִתְמַלְּיָא מִנַּיְיהוּ, וְאִתְבָּרְכָא מֵעַלְמָא עִלָּאָה. כְּדֵין, הַאי דַרְגָּא קָיְימָא לְאַשְׁקָאָה לְכֻלְּהוּ עֲדָרִין, כָּל חַד וְחַד כְּדְקָא חָזֵי לֵיהּ, וְכָל חַד וְחַד אִתְשָׁקֵי מִן דִּינָא וְרַחֲמֵי.","תָּא חֲזֵי, מַה כְּתִיב, וַיַּצֵּג אֶת הַמַּקְלוֹת אֲשֶׁר פִצֵּל בָּרְהָטִים וְגו', דְּיַעֲקֹב בָּעָא לְאַתְקָנָא תְּפִלָּה שֶׁל עַרְבִית, וּלְאַנְהָרָא לְסִיהֲרָא, וּלְאַשְׁקָאָה וּלְבָרְכָא לָהּ מִכָּל סִטְרִין, דִּכְתִיב וַיַּצֵּג אֶת הַמַּקְלוֹת. אִלֵּין דִּינִין וּגְבוּרָן דְּנָפְקֵי מִגְּבוּרָה דִּלְעֵילָא.","וְיַעֲקֹב כַּד בָּעָא לְאַתְקָנָא לְהַאי דַרְגָּא, סָלִיק לְכָל אִינוּן דִּינִין וּגְבוּרָן מִינָהּ, וְאוֹקִים לוֹן בָּרְהָטִים, בְּאִינוּן רְהָטִים אַרְבַּע, דְּקָיְימֵי תְּחוֹת הַאי (במדבר כ״א:י״ח) בְּאֵר חֲפָרוּהָ שָׂרִים, דְּאִתְמַלְיָיא מֵאִינוּן נַחֲלִין וּמַבּוּעִין עִלָּאִין. בְּגִין דְּכַד נָפְקִין מַיִין מֵהַאי בְּאֵר קַדִּישָׁא, אִלֵּין אַרְבַּע נָטְלֵי כֹּלָּא. וְעַל דָּא אִקְרוּן רְהָטִים, וּמִתַּמָּן אַתְיָין כֹּלָּא לְמִשְׁתֵּי. וְאִינוּן דִּינִין וּגְבוּרָן, כֻּלְּהוּ קָיְימֵי תַּמָּן, לְנַטְלָא לְכָל חַד וְחַד כְּדְקָא חָזֵי לֵיהּ."],[[0,"חסידה ברושים ביתה:","היינו באלו ששה בנים העליונים שהם שש קצוות העולם חג\"ת נה\"י, כמו שנתבאר, שהם יוצאים מעולם העליון, שהיא בינה. והם נבחנים לביתה של בינה. ושואל, ולמה נקראה בינה חסידה. ומשיב, אלא עולם העליון הזה, אף על פי שהוא נקבה, דהיינו בינה. קוראים לה זכר, כי כאשר מתפשט כל טוב וכל אור, ממנה הוא מתפשט ויוצא. והמשפיע מכונה בשם זכר."],[1,"ובגין כך דאיהי חסידה:","ומשום זה שבינה היא \u0003חסידה,\u0004 יצא ממנה אור \u0003החסד,\u0004 שהוא אור הראשון שעליו כתוב, ויאמר אלקים יהי אור. ועל כן כתוב, ברושים ביתה, \u0003ברושים,\u0004 אל תקרי ברושים, אלא \u0003בראשים,\u0004 כי בינה היא ג\"ר, וביתה, שהוא ששה קצוות חג\"ת נה\"י שלה, הן \u0003בראשים,\u0004 דהיינו בבחינת ראש וג\"ר, כי עולם האחר, דהיינו עולם התחתון שהיא הנוקבא, בתחתונים ביתה, ולא בראשים, שהיא בחינת ו\"ק ולא ראש וג\"ר. והיא בית דין של העולם. ולפעמים נקרא עולם התחתון שהוא הנוקבא, כמו שנקרא עולם העליון, שהיא בינה, בכל השמות שלו, דהיינו בעת שהנוקבא עולה ומלבשת את הבינה."],[2,"ועל אתר דא וכו':","ועל מקום זה דהיינו הנוקבא, כתוב וינחם ה' ויתעצב וגו'. כי במקום זה תלוים הדינים והעצבון, אבל בכל מה שלמעלה, בבינה, הכל הוא באור, וחיים לכל הצדדים. ועל זה למדנו אין עצבות \u0003לפני\u0004 המקום, \u0003לפני\u0004 הוא בדיוק, שיורה על הפנימית שהיא בינה, שרק בה אין עצבות אבל החיצונית שהיא הנוקבא בה יש עצבות כנ\"ל. ועל כן כתוב, עבדו את ה' בשמחה באו לפניו ברננה. \u0003עבדו את ה' בשמחה,\u0004 הוא כנגד עולם העליון. \u0003באו לפניו ברננה,\u0004 הוא כנגד עולם התחתון. אשריהם ישראל בעולם הזה ובעולם הבא. משום זה כתוב אשריך ישראל וגו'."],[3,"ויצג את המקלות וגו':","פתח ר' אלעזר ואמר, אם חכמת חכמת לך ולצת וגו'. \u0003אם חכמת חכמת לך,\u0004 בוא וראה, ווי לרשעי עולם, שאינם יודעים ואינם מסתכלים בדברי תורה, וכשהם מסתכלים בה, הנה משום שאין בהם תבונה, דברי תורה דומים בעיניהם כאלו הכל היה דברים ריקנים ואין בהם תועלת. והכל הוא משום שהם ריקנים מדעת ותבונה, כי כל הדברים שבתורה כולם הם דברים עליונים ויקרים. ובכל מלה ומלה כתוב בה, יקרה היא מפנינים. וכל חפצים לא ישוו בה."],[4,"וכל אינון טפשין וכו':","וכל הטפשים אטומי הלב, כשרואים דברי תורה, לא די להם שאינם יודעים, אלא עוד, שהם אומרים, שהם דברים נשחתים, דברים שאין בהם תועלת. ווי להם כאשר ידרוש מהם הקב\"ה על כלימתה של התורה, ויענשו בעונש הראוי למורד ברבונו."],[5,"מה כתיב באורייתא וכו':","מה כתוב בתורה, כי לא דבר רק וגו'. ואם הוא רק, אך מכם הוא רק. כי התורה כולה מלאה מכל אבנים טובות ומרגליות היקרות, מכל טוב שבעולם, כמש\"א וכל חפצים לא ישוו בה. ואיך יאמרו, שהתורה היא ריקנה."],[6,"ושלמה מלכא וכו':","ושלמה המלך אמר \u0003אם חכמת חכמת לך.\u0004 כי כשיתחכם האדם בתורה, התועלת שלו הוא, ולא של התורה, כי בתורה, אינו יכול להוסיף אפילו אות אחת. \u0003ולצת לבדך תשא,\u0004 כי לא יגרע כלום, משום זה, משבחה של תורה. והלצנות שלו לבדו הוא, ונשאר בה, להאבידו מעולם הזה ומעולם הבא."],[7,"ת\"ח כד אתוון וכו':","בוא וראה, כאשר אותיות עליונות, שהן מדרגות הבינה, מתחברות כולן במדרגה הזו, שהיא סוף כל המדרגות הקדושות העליונות, דהיינו הנוקבא, ומתמלאת מהן, ומתברכת מעולם העליון, שהוא בינה, אז עומדת מדרגה הזו להשקות לכל העדרים, לכל אחד ואחד כראוי לו, וכל אחד ואחד נשקה מדין ורחמים."],[8,"ת\"ח מה כתיב וכו':","בוא וראה, מה כתוב, ויצג את המקלות וגו'. כי יעקב בא לתקן תפלת ערבית שהיא הנוקבא מבחינת השמאל שהיא חשך, ולהאיר אל הלבנה, שהיא הנוקבא בממשלת הלילה, ולהשקותה ולברך אותה מכל הצדדים, דהיינו מימין ומשמאל, שכתוב, ויצג את המקלות, שהם דינים מבחינת המלכות, שבסוד המסך שבה, וגבורות היוצאים מגבורה העליונה, דהיינו מקו שמאל דבינה. כלומר, שהמקלות כוללים ב' מיני דינים א' של המלכות וב' של הבינה."],[9,"ויעקב כד בעא וכו':","ויעקב, כשרצה לתקן מדרגה הזו, דהיינו להנוקבא הסיר כל אלו הדינים והגבורות מן המקלות שכנגד הדינים שבהם, נאמר, ויפצל בהם פצלות לבנות, דהיינו שהמשיך חסדים על המסך, ועל הגבורות שבהם נאמר \u0003מחשף הלבן,\u0004 והעמיד המקלות \u0003ברהטים,\u0004 באלו ארבעה רהטים שהם ד' כלים, חו\"ב תו\"מ, הנמצאים תחת באר הזו שחפרוה שרים, שהוא הנוקבא הנקראת באר, המתוקנת בחג\"ת דבינה, הנקראים \u0003שרים,\u0004 והיא כלולה מד' כלים חו\"ב תו\"מ המכונים רהטים, שהיא מתמלאת, מהנחלים ומן המעינות העליונים, שהם ספירות הבינה, כי כשיוצאים המים מאותה באר הקדושה, אלו הארבעה, שהם הכלים חו\"ב תו\"מ, לוקחים הכל, ועל כן הם נקראים \u0003רהטים,\u0004 ומשם באים הכל לשתות. דהיינו המלאכים והנשמות."]],[[0,"","חֲסִידָה בְּרוֹשִׁים בֵּיתָהּ, (זו לאה) בְּאוֹתָם שִׁשָּׁה בָנִים עֶלְיוֹנִים, שֵׁשֶׁת צִדְדֵי הָעוֹלָם, כְּמוֹ שֶׁנִּתְבָּאֵר. לָמָּה נִקְרָא חֲסִידָה? אֶלָּא הָעוֹלָם הָעֶלְיוֹן הַזֶּה, אַף עַל גַּב שֶׁהוּא נְקֵבָה, קוֹרְאִים לוֹ זָכָר. שֶׁכַּאֲשֶׁר מִתְפַּשֵּׁט, כָּל טוֹב וְכָל הָאוֹר יוֹצֵא מִמֶּנּוּ."],[1,"","וּמִשּׁוּם שֶׁהִיא חֲסִידָה, יוֹצֵא (משם) מִמֶּנָּה חֶסֶד, שֶׁהוּא הָאוֹר הָרִאשׁוֹן, שֶׁכָּתוּב (בראשית א) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר. וְעַל זֶה בְּרוֹשִׁים בֵּיתָהּ. בְּרוֹשִׁים - אַל תִּקְרֵי בְּרוֹשִׁים אֶלָּא בְּרָאשִׁים, שֶׁהֲרֵי הָעוֹלָם הָאַחֵר בַּתַּחְתּוֹנִים בֵּיתָהּ, וְהִיא בֵּית הַדִּין שֶׁל הָעוֹלָם, וְלִפְעָמִים נִקְרָא כְּמוֹ שֶׁלְּמַעְלָה בְּכָל אוֹתָם הַשֵּׁמוֹת."],[2,"","וְעַל הַמָּקוֹם הַזֶּה כָּתוּב, וַיִּנָּחֶם ה', וַיִּתְעַצֵּב אֶל לִבּוֹ. חֲרוֹן אַף ה'. שֶׁהֲרֵי בַּמָּקוֹם הַזֶּה תָּלוּי. שֶׁהֲרֵי כָּל מַה שֶּׁלְּמַעְלָה, הַכֹּל הוּא בְּאוֹר, חַיִּים לְכָל הַצְּדָדִים, וְעַל כֵּן שָׁנִינוּ, אֵין עַצְבוּת לִפְנֵי הַמָּקוֹם, בְּדִיּוּק לִפְנֵי, וְעַל זֶה כָּתוּב (תהלים ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה בּאוּ לְפָנָיו בִּרְנָנָה. עִבְדוּ אֶת ה' בְּשִׂמְחָה - כְּנֶגֶד הָעוֹלָם הָעֶלְיוֹן. בֹּאוּ לְפָנָיו בִּרְנָנָה - כְּנֶגֶד הָעוֹלָם הַתַּחְתּוֹן. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, מִשּׁוּם כָּךְ כָּתוּב (דברים לג) אַשְׁרֶיךְ יִשְׂרָאֵל מִי כָמוֹךְ עַם נוֹשַׁע בַּה' מָגֵן עֶזְרֶךְ וַאֲשֶׁר חֶרֶב גַּאֲוָתֶךְ וְיִכָּחֲשׁוּ וְגוֹ'."],[3,"","וַיַּצֵג אֶת הַמַּקְלוֹת אֲשֶׁר פִּצֵּל בָּרְהָטִים וְגוֹ'. פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (משלי ט) אִם חָכַמְתָּ חָכַמְתָּ לָּךְ וְלַצְתָּ לְבַדְּךְ תִשָּׂא. אִם חָכַמְתָּ חָכַמְתָּ לָּךְ - בּא רְאֵה, אוֹי לְאוֹתָם רִשְׁעֵי הָעוֹלָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בְּדִבְרֵי תוֹרָה. וּכְשֶׁהֵם מַשְׁגִּיחִים בָּהּ - מִשּׁוּם שֶׁאֵין לָהֶם שֵׂכֶל, דִּבְרֵי הַתּוֹרָה נִרְאִים בְּעֵינֵיהֶם כְּאִלּוּ כֻּלָּם מְלֵאִים רֵיקָנוּת וְאֵין בָּהֶם תּוֹעֶלֶת, וְהַכֹּל מִשּׁוּם שֶׁהֵם רֵיקָנִים מִדַּעַת וְשֵׂכֶל, שֶׁהֲרֵי כָּל דִּבְרֵי הַתּוֹרָה, כֻּלָּם דְּבָרִים עֶלְיוֹנִים וְנִכְבָּדִים, וְכָל דָּבָר וְדָבָר שֶׁכָּתוּב בָּהּ יְקָרָה הִיא מִפְּנִינִים וְכָל חֲפָצִים לֹא יִשְׁווּ בָהּ (בתורה)."],[4,"","וְכָל אוֹתָם הַטִּפְּשִׁים אֲטוּמֵי הַלֵּב, כְּשֶׁרוֹאִים דִּבְרֵי תוֹרָה, לֹא דַי לָהֶם שֶׁלֹּא יוֹדְעִים, אֶלָּא שֶׁהֵם אוֹמְרִים שֶׁהֵם דְּבָרִים פְּגוּמִים, דְּבָרִים שֶׁאֵין בָּהֶם תּוֹעֶלֶת. אוֹי לָהֶם כְּשֶׁיִּתְבַּע אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עֶלְבּוֹן הַתּוֹרָה, וְיֵעָנְשׁוּ עֹנֶשׁ שֶׁמּוֹרְדִים בְּרִבּוֹנָם."],[5,"","מַה כָּתוּב בַּתּוֹרָה? כִּי לֹא דָבָר רֵק הוּא מִכֶּם. וְאִם הוּא רֵק - הוּא מִכֶּם, שֶׁהֲרֵי כָּל הַתּוֹרָה מְלֵאָה מִכָּל אֲבָנִים טוֹבוֹת וּמַרְגָּלִיּוֹת יְקָרוֹת מִכָּל הַטּוֹבוֹת שֶׁל הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר וְכָל חֲפָצִים לֹא יִשְׁווּ בָהּ, וְאֵיךְ יֹאמְרוּ שֶׁהִיא רֵיקָה?!"],[6,"","וּשְׁלֹמֹה הַמֶּלֶךְ אָמַר, אִם חָכַמְתָּ חָכַמְתָּ לָּךְ. שֶׁכַּאֲשֶׁר יִתְחַכֵּם אָדָם בַּתּוֹרָה, זוֹהִי תּוֹעֶלֶת לוֹ, שֶׁהֲרֵי בַּתּוֹרָה לֹא יָכוֹל לְהוֹסִיף אֲפִלּוּ אוֹת אַחַת. וְלַצְתָּ לְבַדְּךְ תִשָּׂא, שֶׁהֲרֵי הַתּוֹרָה לֹא יִגָּרַע כְּלוּם מֵהַשֶּׁבַח שֶׁלָּהּ, וְהַלֵּיצָנוּת הִיא שֶׁלּוֹ וְנִשְׁאֶרֶת בּוֹ לְהַאֲבִיד אוֹתוֹ מִן הָעוֹלָם הַזֶּה וּמִן הָעוֹלָם הַבָּא."],[7,"","בֹּא רְאֵה, כַּאֲשֶׁר הָאוֹתִיּוֹת הָעֶלְיוֹנוֹת כֻּלָּן מִתְחַבְּרוֹת בַּדַּרְגָּה הַזּוֹ, הַסּוֹף שֶׁל כָּל הַדְּרָגוֹת הַקְּדוֹשׁוֹת הָעֶלְיוֹנוֹת, וּמִתְמַלֵּאת מֵהֶם וּמִתְבָּרֶכֶת מִן הָעוֹלָם הָעֶלְיוֹן, אָז הַדַּרְגָּה הַזּוֹ עוֹמֶדֶת לְהַשְׁקוֹת אֶת כָּל הָעֲדָרִים, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, וְכָל אֶחָד וְאֶחָד נִשְׁקָה מִדִּין וְרַחֲמִים."],[8,"","בֹּא רְאֵה מַה כָּתוּב, וַיַּצֵּג אֶת הַמַּקְלוֹת אֲשֶׁר פִּצֵּל בָּרְהָטִים וְגוֹ'. שֶׁיַּעֲקֹב רָצָה לְתַקֵּן תְּפִלַּת עַרְבִית, וּלְהָאִיר לַלְּבָנָה וּלְהַשְׁקוֹת וּלְבָרֵךְ אוֹתָהּ מִכָּל הַצְּדָדִים, שֶׁכָּתוּב וַיַּצֵּג אֶת הַמַּקְלוֹת, אֵלּוּ דִּינִים וּגְבוּרוֹת שֶׁיּוֹצְאִים מִן הַגְּבוּרָה שֶׁלְּמַעְלָה."],[9,"","וְכַאֲשֶׁר יַעֲקֹב רָצָה לְתַקֵּן אֶת הַדַּרְגָּה הַזּוֹ, סִלֵּק אֶת כָּל אוֹתָם הַדִּינִים וְהַגְּבוּרוֹת מִמֶּנָּה, וְהֵקִים אוֹתָם בָּרְהָטִים, בְּאוֹתָם אַרְבַּעַת הָרְהָטִים שֶׁעוֹמְדִים תַּחַת זוֹ בְּאֵר חֲפָרוּהָ שָׂרִים, שֶׁמִּתְמַלֵּאת מֵאוֹתָם הַנְּחָלִים וְהַמַּעְיָנוֹת הָעֶלְיוֹנִים. מִשּׁוּם שֶׁכַּאֲשֶׁר הַמַּיִם יוֹצְאִים מֵהַבְּאֵר הַקְּדוֹשָׁה הַזּוֹ, אֵלּוּ הָאַרְבָּעָה נוֹטְלִים הַכֹּל, וְעַל כֵּן נִקְרָאִים רְהָטִים, וּמִשָּׁם כֻּלָּם בָּאִים לִשְׁתּוֹת. וְאוֹתָם דִּינִים וּגְבוּרוֹת, כֻּלָּם עוֹמְדִים שָׁם לִטֹּל אֶת כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ."]]],[["אֲשֶׁר תָּבֹאנָה הַצֹּאן לִשְׁתּוֹת לְנֹכַח הַצֹּאן, אִלֵּין לָקֳבֵיל אִלֵּין. וַיֵּחַמְנָה, מַאי וַיֵּחַמְנָה. דְּכַד מִתְעַטְּרָן בְּדִינָא, מִתְחַמְּמִין בְּהַהוּא דִינָא, וְאָזְלִין וְשָׁאטִין בְּעַלְמָא, וּמְעַיְינֵי בְּאָרְחֵיהוֹן דִּבְנֵי נָשָׁא, הֵן לְטַב הֵן לְבִישׁ.","תָּא חֲזֵי, מַה כְּתִיב בַּתְרֵיהּ, (בראשית ל׳:ל״ט) וַיֶּחמוּ הַצֹּאן אֶל הַמַּקְלוֹת, בְּגִין דְּאִינוּן מַקְלוֹת הֲווּ מִתְחַמְּמָן, וּמַשְׁגִּיחִין בְּדִינִי עַלְמָא, וְאִתְפַּקְּדָן עֲלֵיהּ, וְאִתְדָּנוּ בְּנִי נָשָׁא עֲלַיְיהוּ, כְּמָה דְאַתְּ אָמֵר (דניאל ד׳:י״ד) בִּגְזֵרַת עִירִין פִּתְגָּמָא וּמֵאמַר קַדִּישִׁין שְׁאֵלְתָא וְגו'.","רִבִּי חִיָּיא פָּתַח וְאָמַר, (תהילים ס״ג:ט׳) דָּבְקָה נַפְשִׁי אַחֲרֶיךָ בִּי תָּמְכָה יְמִינֶךָ, הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ, דָּבְקָה נַפְשִׁי אַחֲרֶיךָ, בְּגִין דְּדָוִד מַלְכָּא, הֲוָה מִתְדְּבַּק נַפְשֵׁיהּ תָּדִיר, אֲבַתְרֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא. וְלָא חָיִישׁ לְמִלִּין אָחֳרָנִין דְּעַלְמָא, אֶלָּא לְאִתְדַּבְּקָא נַפְשֵׁיהּ וּרְעוּתֵיהּ בֵּיהּ, וְכֵיוָן דְּאִיהוּ הֲוָה מִתְדְּבַּק בְּקוּדְשָׁא בְּרִיךְ הוּא, (קודשא בריך הוא) הֲוָה תָּמִיךְ בֵּיהּ וְלָא שַׁבְקֵיהּ. מִכָּאן, לְבַר נָשׁ כַּד אֲתָא לְאִתְדַּבְּקָא בְּקוּדְשָׁא בְּרִיךְ הוּא, קוּדְשָׁא בְּרִיךְ הוּא אָחִיד בֵּיהּ, וְלָא שָׁבִיק לֵיהּ.","דָבָר אַחֵר דָּבְקָה נַפְשִׁי אַחֲרֶיךָ, לְאִתְעַטְּרָא דַּרְגֵּיהּ לְעֵילָא, דְּהָא כַּד אִתְדָּבַּק הַהוּא דַרְגָּא (ס\"א דיליה אתברכא וכד אתגלייא) בְּדַרְגִּין עִלָּאִין לְסַלְקָא בַּתְרַיְיהוּ, כְּדֵין יְמִינָא אָחִיד בֵּיהּ לְסַלְקָא לֵיהּ, וּלְחַבְּרָא לֵיהּ, בְּחִבּוּרָא חַד כְּדְקָא יְאוּת, כְּמָה דְאַתְּ אָמֵר, (תהילים קל״ט:י׳) וְתֹאחֲזֵנִי יְמִינֶךָ, וּכְתִיב (שיר השירים ב׳:ו׳) וִימִינוֹ תְחַבְּקֵנִי, וְעַל דָּא בִּי תָּמְכָה יְמִינֶךָ.","וְכַד אָחִיד בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, כְּדֵין כְּתִיב, (שם) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְחַבְּקֵנִי. וְאִיהוּ יִחוּדָא חַד וְחִבּוּרָא חַד, וְכַד אִיהוּ חִבּוּרָא חַד, כְּדֵין אִתְמַלְּיָא הַהוּא דַּרְגָּא דִּילֵיהּ וְאִתְבָּרְכָא.","וְכַד אִתְמַלְיָין כָּל אִינוּן רְהָטִין, אִתְמַלְיָין לְאַרְבַּע סִטְרִין דְּעַלְמָא, וְכֻלְּהוּ עֲדָרַיָיא אִשְׁתַּקְּיָין, כָּל חַד וְחַד לְסִטְרֵיהּ. וְכַד אֲתָא יַעֲקֹב לְאַתְקָנָא הַאי דַרְגָּא, בָּרִיר לֵיהּ סִטְרָא דִימִינָא, דְּאִתְחֲזֵי לֵיהּ, וְסִטְרָא אָחֳרָא דְלָא אִתְחֲזֵי לֵיהּ אִתְפָּרְשַׁת מִינֵיהּ. כְּמָה דִכְתִיב, (בראשית ל׳:מ׳-מ״א) וַיָּשֶׁת לוֹ עֲדָרִים לְבַדּוֹ וְלֹא שָׁתָם עַל צֹאן לָבָן. לְבַדּוֹ, הֲוָה בִּלְחוֹדוֹי, דְּלָא יִשְׁתַּמֵּשׁ בְּטַעֲוָון אָחֳרָנִין דִּבְסִטְרִין אָחֳרָנִין. זַכָּאָה חוּלַקְהוֹן דְּיִשְׂרָאֵל, דְּעֲלַיְיהוּ כְּתִיב, (דברים י״ד:ב׳) כִּי עַם קָדוֹשׁ אַתָּה לַיְיָ אֱלֹהֶיךָ וּבְךָ בָּחַר יְיָ וְגו'.","וְתָא חֲזֵי, יַעֲקֹב אִיהוּ תּוּשְׁבְּחָא דְּאֲבָהָן, וְאִיהוּ כְּלָלָא דְּכֻלְּהוּ, וּבְגִין דְּאִיהוּ כְּלָלָא דְּכֹלָּא, בְּגִין כָּךְ אִיהוּ קָאִים לְאַנְהָרָא לְסִיהֲרָא, דְּיַעֲקֹב אִיהוּ קָאִים לְאַתְקָנָא לִתְפִלַּת עַרְבִית.","וְכָל הַהוּא תִּקּוּנָא, אִיהוּ כְּדְקָא חָזֵי לֵיהּ, (כדין) כָּל אִינוּן סִטְרִין קַדִּישִׁין כֻּלְּהוּ בְּתִקּוּנָא אַתְקִין בְּסִטְרוֹי, וְאַפְרִישׁ חוּלָקֵיהּ, מֵחוּלָקָא דִּשְׁאָר עַמִין. אִלֵּין סִטְרִין עִלָּאִין קַדִּישִׁין בִּקְדוּשָּׁה עִלָּאָה. וְאִלֵּין סִטְרִין מְסָאֲבִין, בִּמְסָאֲבָן דִּמְסָאֲבוּתָא.","וְהָא אוֹקִימְנָא, דִּכְתִיב וַיָּשֶׁת לוֹ עֲדָרִים לְבַדּוֹ. וַיָּשֶׁת לוֹ, דְּאַתְקִין (ליה) תִּקּוּנִין לִמְהֵימְנוּתָא. לְבַדּוֹ, כְּמָה דְאַתְּ אָמֵר, (שם) וּבְךָ בָחַר יְיָ לִהְיוֹת לוֹ לְעַם סְגֻלָּה מִכָּל הָעַמִּים. וְלֹא שָׁתָם עַל צֹאן לָבָן, דְּלָא שַׁוֵּי חוּלָקֵיהּ וְעַדְבֵיהּ עִמְּהוֹן.","וְעַל דָּא יַעֲקֹב שְׁלִימוּ דְּאֲבָהָן, אַתְקִין רָזָא דִּמְהֵימְנוּתָא, וְאַפְרִישׁ חוּלָקֵיהּ וְעַדְבֵיהּ, מֵחוּלָקָא וְעַדְבָא דִּשְׁאָר עַמִּין. וְעַל דָּא כְּתִיב, (דבהם ד) וְאַתֶּם הַדְּבֵקִים בַּיְיָ אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.","רִבִּי אַבָּא אָמַר, זַכָּאָה חוּלַקְהוֹן דְּיִשְׂרָאֵל, דְּאִינוּן עִלָּאִין עַל עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, בְּגִין דְּדַרְגָא דִלְהוֹן לְעֵילָא, וְדַרְגִּין דְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת לְתַתָּא, אִלֵּין בְּסִטְרָא דִקְדוּשָׁה, וְאִלֵּין בְּסִטְרָא דִמְסָאֲבָא, אִלֵּין לִימִינָא, וְאִלֵּין לִשְׂמָאלָא.","כֵּיוָן דְּאִתְחָרַב בֵּי מַקְדְּשָׁא, מַה כְּתִיב, (איכהב) הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב, וּבְגִין כָּךְ כְּתִיב, (תהילים ס׳:ז׳) הוֹשִׁיעָה יְמִינְךָ וַעֲנֵנִי. וּשְׂמָאלָא אִתְגַּבַּר וּמְסָאֲבָא אִתְתַּקַּף, עַד דְּיִבְנִי קוּדְשָׁא בְּרִיךְ הוּא בֵּי מַקְדְּשָׁא, וְיַתְקִין עַלְמָא עַל תִּקּוּנוֹי, וִיהַדְּרוּן מִלֵּיהּ כְּדְקָא יְאוּת וְיִתְעֲבַר סִטְרָא מְסָאֲבָא מִן עָלְמָא. וְהָא אִתְּמָר, דִּכְתִיב (זכריה ג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ וְגו', וּכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוֶת לָנֶצַח וְגו'."],[[0,"ואינון דינין וגבורן וכו':","ואלו דינים וגבורות שהסיר מן המקלות, כולם עומדים שם ברהטים, כדי שכל אחד ואחד יקבל משם כראוי לו. \u0003אשר תבאנה הצאן לשתות לנכח הצאן,\u0004 שאומר ב' פעמים צאן, היינו, אלו כנגד אלו, המדרגוה הראויות לקבל חסדים עמדו לנכח המדרגות הראויות לקבל דינים וגבורות. \u0003ויחמנה,\u0004 ושואל, מהו ויחמנה. ומשיב, כי כאשר המלאכים המכונים צאן, מתעטרים בחסדים, ומקבלים הדין, הם מתחממים בדין ההוא, כי קבלת הדין בתוכם מכונה חימום, והולכים ומשוטטים בעולם, להשגיח בדרכי בני אדם, הן להטיב הן להרע. כלומר, להשכיר ולהעניש. כי הם כלולים מחסדים ומדינים כנ\"ל."],[1,"ת\"ח מה כתיב וכו':","בוא וראה, מה כתוב, אחריו, \u0003ויחמו הצאן אל המקלות,\u0004 משום שאלו המקלות, שהם דינים וגבורות כנ\"ל, היו מתחממים ומשגיחים בדינים שבעולם, וממונים עליהם, ובני אדם נדונים בהם כמש\"א, בגזירת עירין פתגמא ומאמר קדישין שאלתא וגו'."],[2,"רבי חייא פתח וכו':","ר\"ח פתח ואמר, דבקה נפשי אחריך בי וגו', מקרא זה יש להסתכל בו, שאמר דבקה נפשי אחריך, משום שדוד המלך היה מתדבק עצמו תמיד בהקב\"ה, ולא דאג לדברים אחרים שבעולם אלא להתדבק בו בנפשו ורצונו, וכיון שהיה מתדבק בהקב\"ה, היה תומך בו ולא עזבו. כמ\"ש בי תמכה ימינך. מכאן נשמע, כשבא אדם להתדבק בהקב\"ה, הקב\"ה אוחז בו ואינו עוזב אותו."],[3,"ד\"א דבקה נפשי אחריך:","היינו בשביל שתתעטר מדרגתו למעלה, כי כשמדרגתו מתדבק במדרגות העליונות לעלות אחריהן, אז אוחז בו הימין, שהוא חסדים, להעלותו ולחברו עם הימין בחבור אחד כראוי. כמו שאתה אומר ותאחזני ימינך. וכתוב וימינו תחבקני. ועל כן אומר הכתוב, בי תמכה ימינך."],[4,"וכד אחיד ביה וכו':","וכשהוא אוחז בהקב\"ה, אז כתוב, שמאלו תחת לראשי וימינו תחבקני. והוא יחוד אחד וחבור אחד עם הקב\"ה וכשהוא חבור אחד עמו, אז מתמלאה המדרגה שלו ומתברכה."],[5,"וכד אתמליין וכו':","וכשמתמלאים כל אלו הרהטים, הם מתמלאים לד' רוחות העולם, חו\"ב תו\"מ (כנ\"ל באות שמ\"ז) וכל העדרים נשקים, כל אחד ואחד לפי בחינתו, באותם ד' הבחינות חו\"ב תו\"מ. וכשבא יעקב לתקן מדרגה הזו, דהיינו הנוקבא, בחר לו צד הימין הראוי לו, וצד האחר שאינו ראוי לו נפרדה ממנו, כמ\"ש וישת לו עדרים \u0003לבדו\u0004 ולא שתם על צאן לבן, \u0003לבדו\u0004 היה בפני עצמו, שלא ישתמש באלהים אחרים שבצדדים האחרים. אשרי חלקם של ישראל, שעליהם כתוב, כי עם קדוש אתה וגו'."],[6,"ותא חזי יעקב וכו':","ובוא וראה, יעקב, הוא בחיר שבאבות, והוא כלל של כולם, כי קו האמצעי שהוא יעקב כולל בתוכו ב' הקוין ימין ושמאל (כנ\"ל דף ל\"ג ד\"ה תא חזי) שהם אברהם ויצחק. ובשביל שהוא כלל כולם, הוא עומד בשביל זה להאיר אל הלבנה, שהיא הנוקבא כנ\"ל. כי יעקב, הוא עומד לתקן את תפלת ערבית שהוא הנוקבא, כנ\"ל."],[7,"וכל ההוא תקונא וכו':","וכל תקון ההוא עשה כראוי לו, כל אלו בחינות הקדושות כולם, התקין בתקון בבחינתו, בקו אמצעי, והפריד חלקו מחלק שאר העמים, שהם בשמאל, אלו היו בחינות עליונות קדושות בקדושה עליונה. ואלו היו בחינות הטמאות בזוהמות הטומאה."],[8,"והא אוקימנא וכו':","ובארנו, שכתוב, וישת לו עדרים לבדו, \u0003וישת לו,\u0004 פירושו, שהתקין תקונים בשביל האמונה שהיא הנוקבא, בלבדה, כמו שאתה אומר, ובך בחר ה' להיות לו לעם סגולה מכל העמים. \u0003ולא שתם על צאן לבן,\u0004 שלא שם חלקו וגורלו עמהם."],[9,"ועל דא יעקב וכו':","ועל כן, יעקב בחיר שבאבות, התקין סוד האמונה, והפריד חלקו וגורלו מחלק וגורל שאר העמים, ועל זה כתוב. ואתם הדבקים בה' אלקיכם חיים כלכם היום."],[10,"רבי אבא אמר וכו':","רא\"א, אשרי חלקם של ישראל, שהם עליונים על עמים העובדים ככבים ומזלות, משום שהמדרגה שלהם היא למעלה, שמקבלים הארת השמאל בבחינת ממטה למעלה, והמדרגות של העמים עכו\"ם הן למטה, שממשיכים אור השמאל ממעלה למטה, אלו הם בצד הקדושה, ואלו הם בצד הטומאה. אלו לימין, ואלו לשמאל."],[11,"כיון דאתחרב וכו':","כיון שנחרב בית המקדש, מה כתוב, השיב אחור ימינו מפני אויב, ומשום זה כתוב, הושיעה ימינך וענני שהשמאל נתגבר אז והטומאה נתגברה, עד שיבנה הקב\"ה את בית המקדש ויתקן העולם על תקונו, וישובו הדברים לשלמותם, כראוי, וצד הטומאה יעבור מן העולם. ולמדנו שכתוב, ואת רוח הטומאה אעביר מן הארץ וכתוב, בלע המות לנצח וגו'."]],[[0,"","אֲשֶׁר תָּבאנָה הַצֹּאן לִשְׁתּוֹת לְנֹכַח הַצֹאן, אֵלּוּ כְּנֶגֶד אֵלּוּ. וַיֵּחַמְנָה, מַה זֶּה וַיֵּחַמְנָה? שֶׁכַּאֲשֶׁר מִתְעַטְּרִים בְּדִין, מִתְחַמְּמִים בְּאוֹתוֹ הַדִּין, וְהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם, וּמְעַיְּנִים בְּדַרְכֵי בְּנֵי הָאָדָם, הֵן לְטוֹב הֵן לְרַע."],[1,"","בֹּא רְאֵה מַה כָּתוּב אַחֲרָיו, וַיֶּחֱמוּ הַצּאן אֶל הַמַּקְלוֹת. מִשּׁוּם שֶׁאוֹתָם הַמַּקְלוֹת הָיוּ מִתְחַמְּמִים וּמַשְׁגִּיחִים בְּדִינֵי הָעוֹלָם, וְנִפְקָדִים עָלָיו, וְנִדּוֹנִים אֲנָשִׁים עֲלֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ד) בִּגְזֵרַת מַלְאָכִים הַדָּבָר וּבִפְקֻדַּת קְדוֹשִׁים הַגְּזֵרָה וְגוֹ'."],[2,"","רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים סג) דָּבְקָה נַפְשִׁי אַחֲרֶיךְ בִּי תָּמְכָה יְמִינֶךְ. בַּפָּסוּק הַזֶּה יֵשׁ לְהִסְתַּכֵּל, דָּבְקָה נַפְשִׁי אַחֲרֶיךְ - מִשּׁוּם שֶׁדָּוִד הַמֶּלֶךְ הָיָה מַדְבִּיק תָּמִיד אֶת נַפְשׁוֹ אַחֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא חָשַׁשׁ לִדְבָרִים אֲחֵרִים שֶׁל הָעוֹלָם, אֶלָּא לְהַדְבִּיק נַפְשׁוֹ וּרְצוֹנוֹ בּוֹ. וְכֵיוָן שֶׁהוּא הָיָה נִדְבָּק בַּקָּדוֹשׁ- בָּרוּךְ-הוּא, הָיָה תּוֹמֵךְ בּוֹ וְלֹא עוֹזֵב אוֹתוֹ. מִכָּאן שֶׁכַּאֲשֶׁר אָדָם בָּא לְהִדָּבֵק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹחֵז בּוֹ וְלֹא עוֹזֵב אוֹתוֹ."],[3,"","דָּבָר אַחֵר דָּבְקָה נַפְשִׁי אַחֲרֶיךְ - לְהִתְעַטֵּר דַּרְגָּתוֹ לְמַעְלָה. שֶׁהֲרֵי כַּאֲשֶׁר נִדְבֶּקֶת הַדַּרְגָה הַהִיא (שלו נתברכה, וכשהתגלתה) בַּדְּרָגוֹת הָעֶלְיוֹנוֹת לַעֲלוֹת אַחֲרֵיהֶן, אָז הַיָּמִין אוֹחֵז בָּהּ לְהַעֲלוֹתָהּ וּלְחַבְּרָהּ בְּחִבּוּר אֶחָד כָּרָאוּי, כְּמוֹ שֶׁנֶּאֱמַר וְתֹאחֲזֵנִי יְמִינֶךְ, וְכָתוּב וִימִינוֹ תְחַבְּקֵנִי, וְעַל כֵּן בִּי תָּמְכָה יְמִינֶךְ."],[4,"","וּכְשֶׁאוֹחֵז בּוֹ בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, אָז כָּתוּב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְחַבְּקֵנִי. וְהוּא יִחוּד אֶחָד וְחִבּוּר אֶחָד. וּכְשֶׁהוּא חִבּוּר אֶחָד, אָז מִתְמַלֵּאת אוֹתָהּ דַּרְגָּה שֶׁלּוֹ וּמִתְבָּרֶכֶת."],[5,"","וּכְשֶׁמִּתְמַלְּאִים כָּל אוֹתָם הָרְהָטִים, מִתְמַלְּאִים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְכָל הָעֲדָרִים מֻשְׁקִים, כָּל אֶחָד וְאֶחָד לְצִדּוֹ. וּכְשֶׁבָּא יַעֲקֹב לְתַקֵּן אֶת הַדַּרְגָּה הַזּוֹ, בָּחַר לוֹ צַד הַיָּמִין שֶׁרָאוּי לוֹ, וְהַצַּד הָאַחֵר שֶׁלֹּא רָאוּי לוֹ נִפְרַד מִמֶּנּוּ, כְּמוֹ שֶׁכָּתוּב וַיָּשֶׁת לוֹ עֲדָרִים לְבַדּוֹ וְלֹא שָׁתָם עַל צֹאן לָבָן. לְבַדּוֹ - הָיָה לְבַדּוֹ שֶׁלֹּא יִשְׁתַּמֵּשׁ בַּתּוֹעֵבוֹת הָאֲחֵרוֹת שֶׁבַּצְּדָדִים הָאֲחֵרִים. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁעֲלֵיהֶם כָּתוּב (דברים יד) כִּי עַם קָדוֹשׁ אַתָּה לַה' אֱלֹהֶיךְ וּבְךְ בָּחַר ה' וְגוֹ'."],[6,"","וּבֹא וּרְאֵה, יַעֲקֹב הוּא הַמְשֻׁבָּח שֶׁל הָאָבוֹת וְהוּא הַכְּלָל שֶׁל כֻּלָּם, וּמִשּׁוּם שֶׁהוּא הַכְּלָל שֶׁל הַכֹּל, מִשּׁוּם כָּךְ הוּא עוֹמֵד לְהָאִיר לַלְּבָנָה, שֶׁיַּעֲקֹב הוּא עוֹמֵד לְתַקֵּן אֶת תְּפִלַּת עַרְבִית."],[7,"","וְכָל הַתִּקּוּן הַהוּא הוּא כָּרָאוּי לוֹ. כָּל אוֹתָם הַצְּדָדִים הַקְּדוֹשִׁים, כֻּלָּם בְּתִקּוּן הִתְקִין בְּצִדּוֹ, וְהִפְרִיד חֶלְקוֹ מֵחֶלְקָם שֶׁל שְׁאָר הָעַמִּים. אֵלּוּ הַצְּדָדִים הָעֶלְיוֹנִים הַקְּדוֹשִׁים בִּקְדֻשָּׁה עֶלְיוֹנָה, וְאֵלּוּ צְדָדִים טְמֵאִים בְּטֻמְאוֹת הַטֻּמְאָה."],[8,"","וַהֲרֵי בֵּאַרְנוּ, שֶׁכָּתוּב וַיָּשֶׁת לוֹ עֲדָרִים לְבַדּוֹ. וַיָּשֶׁת לוֹ - שֶׁהִתְקִין תִּקּוּנִים לָאֱמוּנָה. לְבַדּוֹ - כְּמוֹ שֶׁנֶּאֱמַר וּבְךְ בָּחַר ה' לִהְיוֹת לוֹ לְעַם סְגֻלָּה מִכָּל הָעַמִּים. וְלֹא שָׁתָם עַל צֹאן לָבָן - שֶׁלֹּא שָׂם חֶלְקוֹ וְגוֹרָלוֹ עִמָּהֶם."],[9,"","וְעַל כֵּן יַעֲקֹב, שְׁלֵמוּת הָאָבוֹת, הִתְקִין סוֹד הָאֱמוּנָה, וְהִפְרִיד חֶלְקוֹ וְגוֹרָלוֹ מֵהַחֵלֶק וְהַגּוֹרָל שֶׁל שְׁאָר הָעַמִּים. וְעַל זֶה כָּתוּב וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם."],[10,"","רַבִּי אַבָּא אָמַר, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁהֵם עֶלְיוֹנִים עַל הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, מִשּׁוּם שֶׁדַּרְגָּתָם לְמַעְלָה, וְהַדְּרָגוֹת שֶׁל הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת לְמַטָּה. אֵלּוּ בְּצַד הַקְּדֻשָּׁה, וְאֵלּוּ בְּצַד הַטֻּמְאָה. אֵלּוּ לְיָמִין, וְאֵלּוּ לִשְׂמֹאל."],[11,"","כֵּיוָן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ מַה כָּתוּב? (איכה ב) הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב. וּמִשּׁוּם כָּךְ כָּתוּב הוֹשִׁיעָה יְמִינְךְ וַעֲנֵנִי. וְהַשְּׂמֹאל מִתְגַּבֵּר וְהַטֻּמְאָה מִתְחַזֶּקֶת, עַד שֶׁיִּבְנֶה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בֵּית הַמִּקְדָּשׁ וִיתַקֵּן אֶת הָעוֹלָם עַל תִּקּוּנוֹ, וְיַחְזְרוּ דְבָרָיו כָּרָאוּי, וְיַעֲבֹר צַד הַטֻּמְאָה מִן הָעוֹלָם. וְהִנֵּה נֶאֱמַר, שֶׁכָּתוּב (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ וְגוֹ', וְכָתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח וְגוֹ'."]]],[["וְיִשְׁתָּאַר קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, כְּמָה דִכְתִיב, (ישעיהו ב׳:י״א) וְהָאֱלִילִים כָּלִיל יַחֲלף, וּכְתִיב, (שם) וְנִשְׂגָּב יְיָ לְבַדּוֹ בַּיּוֹם הַהוּא. הוּא בִּלְחוֹדוֹי, כְּמָה דִכְתִיב, (דברים לכ) וְאֵין עִמּוֹ אֵל נֵכָר, בְּגִין דְּיִשְׁתְּצֵי חֵילָא מְסָאֲבָא מֵעַלמָא, וְלָא יִשְׁתָּאַר לְעֵילָא וְתַתָּא. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, וְיִשְׂרָאֵל לְפוּלְחָנֵיהּ, עַם קַדִּישׁ, וְיִתְקְרֵי קַדִּישׁ, דִּכְתִיב, (ישעיהו ד׳:ג׳) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלַם קָדוֹשׁ יֵאָמֶר לוֹ כָּל הַכָּתוּב לַחַיִּים בִּירוּשָׁלָםִ. וּכְדֵין יְהֵא מַלְכָּא יְחִידָאי, לְעֵילָא וְתַתָּא, וְעַמָּא יְחִידָאָה לְפוּלְחָנֵיהּ, כְּמָה דִכְתִיב, (דברי הימים א י״ז:כ״א) וּמִי כְּעַמְךָ יִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ.","רִבִּי יִצְחָק וְרַבִּי יֵיסָא, הֲווּ אָזְלֵי בְּאָרְחָא, אָמַר רִבִּי יֵיסָא, הָא שְׁכִינְתָּא לְגַבָּן נִתְעַסַּק בְּמִלֵּי דְאוֹרַיְיתָא, דְּכָל מַאן דְּעָסִיק בְּמִלֵּי דְאוֹרַיְיתָא וְיִשְׁתַּדַּל בָּהּ, זָכֵי לְאַמְשָׁכָא לֵיהּ בַּהֲדֵיהּ.","פָּתַח רִבִּי יִצְחָק וְאָמַר, (תהילים י״ח:מ״ז) חַי יְיָ וּבָרוּךְ צוּרִי וְיָרוּם אֱלֹהֵי יִשְׁעִי, הַאי קְרָא אִיהוּ רָזָא. חַי יְיָ, וְכִי לָא יְדַעְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִקְרֵי חַי, אֶלָּא אֲפִילּוּ צַדִּיק, אִיהוּ אִקְרֵי חַי, דְּהָא חַי, צַדִּיק אִיהוּ לְעֵילָא וְצַדִּיק אִיהוּ לְתַתָּא. לְעֵילָא קוּדְשָׁא בְּרִיךְ הוּא אִקְרֵי חַי. לְתַתָּא צַדִּיק אִקְרֵי חַי, דִּכְתִיב, (שמואל ב כ״ג:כ׳) וּבְנָיָהוּ בֶּן יְהוֹיָדָע בֶּן אִישׁ חַי, אַמַּאי אִקְרֵי חַי בְּגִין דְּאִיהוּ צַדִּיק, דְּהָא צַדִּיק חַי אִקְרֵי, חַי הָעוֹלָמִים. וּבָרוּךְ צוּרִי, כֹּלָּא חַד, חַי וּבָרוּךְ, דְּלָא מִתְפָּרְשֵׁי מֵהַדָּדֵי, דְּכַד מִתְחַבְּרִין כְּחֲדָא. אִקְרֵי (שיר השירים ד׳:ט״ו) בְּאֵר מַיִם חַיִּים. דָּא נְבִיעַ לְגוֹ, וְדָא אִתְמַלְיָיא מִנֵּיהּ.","וְיָרוּם אֱלהֵי יִשְׁעִי, דָּא עַלְמָא עִלָּאָה, דְּאִיהוּ רָם וְנִשָּׂא, רָם עַל כֹּלָּא. דְּהָא מִינֵיהּ נָפִיק כֹּלָּא, (מקורא דלא פסיק) וְכָל נְבִיעוּ דִּנְבִיעַ, לְאִתְמַלְיָיא בֵּירָא כְּדְקָא יְאוּת. וּמִתַּמָּן אִתְבָּרְכָא, לְאַנְהָרָא לְכָל אִינוּן דִּלְתַתָּא, וְכַד (האי) אִתְמַלְיָיא, כֹּלָּא כְּדְקָא יְאוּת, כְּדֵין וְיָרוּם אֱלהֵי יִשְׁעִי.","פָּתַח רִבִּי יֵיסָא וְאָמַר, (איוב ל״ו:ז׳) לא יִגְרַע מִצַּדִּיק עֵינָיו וְאֶת מְלָכִים לַכִּסֵּא וַיּשִׁיבֵם לָנֶצַח וַיִּגְבָּהוּ, תָּא חֲזֵי, כַּד חַיָּיבַיָא לָא שָׁלְטִין בְּעַלְמָא וְאִתְאֲבִידוּ מִינֵיהּ, (בעלמא) (מעלמא) כְּדֵין צַּדִּיק אִיהוּ שַׁלִּיט בְּעַלְמָא, הֲדָא הוּא דִכְתִיב, (שם) לא יְחַיֶּה רָשָׁע וּמִשְׁפַּט עֲנִיִּים יִתֵּן. מַה כְּתִיב בַּתְרֵיהּ, לא יִגְּרַע מִצַּדִּיק עֵינָיו, מַהוּ עֵינָיו, כְּמָה דְאַתְּ אָמֵר (תהלים לה) עֵינֵי יְיָ אֶל צַדִּיקִים.","וְאֶת מְלָכִים לַכִּסֵּא, אִלֵּין אִינוּן מְלָכִין שַׁלִּיטִין, דְּאִתְאַחֲדָן לַכִּסֵּא. וַיּשִׁיבֵם לָנֶצַח, דְּאִתְקַיְימוּ בְּכֻּרְסְיָיא, בְּקִיּוּמָא שְׁלִים. וַיִּגְבָּהוּ, אַמַּאי וַיִּגְבָּהוּ, לְשַׁלְטָאָה בְּעַלְמָא, וְיִתְקַיֵּים כֻּרְסְיָיא עַל סַמְכוֹהִי. דָּבָר אַחֵר וַיִּגְבָּהוּ, דְּנָטְלֵי כֻּרְסְיָיא, וְזָקְפִין לָהּ לְעֵילָא, לְאִתְאַחֲדָא בְּאַתְרֵיהּ כְּדְקָא יְאוּת, וּכְדֵין כֹּלָּא יִחוּדָא חָדָא.","עַד דְּהֲווּ אָזְלֵי, חָמוּ חַד בַּר נָשׁ, דְּהֲוָה אָתֵי וְחַד יְנוּקָא עִמֵּיהּ, רָכִיב עַל כִּתְפֵיהּ. אָמַר רִבִּי יִצְחָק, וַדַּאי הַאי בַּר נָשׁ יוּדָאי אִיהוּ, וּבְגִין לְזַכָּאָה לִבְנֵי נָשָׁא קָא אָתֵי. אָמַר רִבִּי יֵיסָא, נִזְכֶּה אֲנַן בְּקַדְמִיתָא בֵּיהּ.","כַּד מָטָא לְגַבַּיְיהוּ, אָמַר רִבִּי יֵיסָא אָן קִיסְתָא דִּטְרִימָא (ס\"א קיסטא דעמירא) בְּקִירְטוֹי דְּאוֹרְחָא, אָמַר בְּגִין דְּיִזְכּוּן (ד\"א ל\"ג בי) בְּנֵי נְשָׁא, דְּהָא תְּרֵין בְּנִין אִית לִי, וְאָתָא טוּרָנָא לְמָתָא, וְאִשְׁתַּבּוּ. וְהָאִידְנָא אָזִילְנָא, בְּגִין דְּיִזְכּוּן בְּהוּ בְּנִי נָשָׁא. זָכוּ בַּהֲדֵיהּ, וְיַהֲבוּ לֵיהּ לְמֵיכַל.","אַדְהָכִי פָּתַח הַהוּא יוּדָאי וְאָמַר, (במדבר כ״ח:ב׳) אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי וְגו'. קָרְבָּנָא דְקוּדְשָׁא בְּרִיךְ הוּא בְּכָל יוֹמָא, בְּגִין לְמֵיזַן עַלְמָא וּלְמֵיהַב סִפּוּקָא לְעֵילָא וְתַתָּא. דְּהָא בְּאִתְעֲרוּתָא דִלְתַתָּא, אִתְעַר לְעֵילָא. וּבְדָא מִסְתַּפְּקִין כָּל חַד וְחַד כְּדְקָא יְאוּת.","אֶת קָרְבָּנִי לַחְמִי, הֲדָא הוּא דִכְתִיב, (שיר השירים ה׳:א׳) אָכַלְתִּי יַעֲרִי עִם דִּבְשִׁי שָׁתִיתִי יִיִנִי עִם חֲלָבִי. לְאִשַּׁי, הֲדָא הוּא דִכְתִיב, (שיר השירים ה׳:א׳) אִכְלוּ רֵעִים וְגו', וּמַה קוּדְשָׁא בְּרִיךְ הוּא פַּקִּיד לְאִתְעָרָא מְזוֹנָא לְעֵילָא (לתתא) בְּגִין לְאִתְעָרָא מְזוֹנָא (לעילא) לְתַתָּא מֵהַהוּא מְזוֹנָא. מַאן דְיָהִיב מְזוֹנָא לְקַיְימָא נַפְשָׁא, עַל אַחַת כַּמָּה וְכַמָּה דְּקוּדְשָׁא בְּרִיךְ הוּא בָּרִיךְ לֵיהּ, וְיִתְעַר לֵיהּ מְזוֹנָא דִלְעֵילָא, וְיִתְבָּרַךְ עַלְמָא בְּגִינֵיהּ.","אָמַר רִבִּי יִצְחָק, וַדַּאי רָזָא דָא כְּדְקָא חָזֵי, וְשַׁפִּיר קָאֲמַר. אָמַר רִבִּי יֵיסָא, וַדַּאי עַל דָּא אֲמְרוּ, דְּלָא יְזַלְזֵל בַּר נָשׁ, לְשׁוּם בַּר נָשׁ אָחֳרָא בְּעַלְמָא, בִּתְרֵי גַוְונִי זָכִינָא לְהַאי בַּר נָשׁ."],[[0,"וישתאר קב\"ה בלחודוי וכו':","וישאר הקב\"ה לבדו, כמ\"ש והאלילים כליל יחלוף, וכתוב, ונשגב ה' לבדו ביום ההוא, הוא בלבדו, כמ\"ש ואין עמו אל נכר. משום שיכלה כח הטומאה מן העולם, ולא ישאר למעלה ולמטה אלא הקב\"ה לבדו, וישראל עם קדוש לעבודתו, וקדוש יקראו, שכתוב, והיה הנשאר בציון והנותר בירושלים קדוש יאמר לו כל הכתוב לחיים בירושלים. ואז יהיה מלך אחד למעלה ולמטה, ועם אחד לעבודתו, כמ\"ש ומי כעמך ישראל גוי אחד בארץ."],[1,"ר' יצחק ור' ייסא הוו אזלי וכו':","ר' יצחק ור' ייסא היו הולכים בדרך א\"ר ייסא הרי השכינה עמנו, כי השכינה מתקשרת עם הולכי דרכים לשמרם, (כנ\"ל בראשית ב' דף קמ\"א אות רכ\"ד) נעסוק בדברי תורה, כי כל מי שעוסק בדברי תורה, ומתאמץ בה, זוכה להמשיך אותה דהיינו להמשיך את ז\"א שה\"ס תורה, ואז יתקשר בהם ז\"א, ונוקביה שהיא השכינה, ביחוד אחד."],[2,"פתח ר' יצחק ואמר וכו':","פתח ר\"י ואמר, חי ה' וברוך צורי וירום אלקי ישעי. מקרא זה הוא סוד שכתוב, \u0003חי ה',\u0004 וכי איני יודע שהקב\"ה הוא חי. ומשיב, אלא אפילו צדיק שהוא יסוד, נקרא \u0003חי,\u0004 כי צדיק הוא ממשיך הארת החכמה, שנקרא אור \u0003החיה,\u0004 וע\"כ נקרא \u0003חי,\u0004 כי \u0003חי\u0004 הוא צדיק למעלה וצדיק למטה, כלומר הן ז\"א שהוא למעלה, והן יסוד שלו למטה, נקראים \u0003חי,\u0004 למעלה נקרא הקב\"ה, שהוא ז\"א \u0003חי,\u0004 דהיינו שכתוב \u0003חי הויה,\u0004 ולמטה נקרא הצדיק \u0003חי,\u0004 דהיינו יסוד דז\"א, שכתוב ובניהו בן יהוידע בן, איש חי, שיורה על יסוד. ולמה נקרא הקב\"ה \u0003חי,\u0004 משום שהוא צדיק, כלומר שהוא כולל גם בחינת יסוד צדיק, כי צדיק נקרא \u0003חי\u0004 דהיינו \u0003חי העולמים.\u0004 להיותו ממשיך הארת החכמה שנקרא אור החיה כנ\"ל. ואין הקב\"ה משפיע חכמה אלא אחר שנשלמים נה\"י דכלים, שעקרו הוא יסוד צדיק, ואז נאמר \u0003חי הויה.\u0004 דהיינו על שם המשכת החכמה."],[2,"וברוך צורי:","הכל אחד הוא \u0003חי וברוך,\u0004 כי אינם נפרדים זה מזה. כי \u0003חי\u0004 פירושו הארת חכמה, \u0003וברוך\u0004 פירושו הארת החסדים, ומחויבים להתלבש זה בזה, כי חכמה בלי חסדים חשך הוא. וזסו\"ה, \u0003חי הוי\"ה וברוך,\u0004 דהיינו חכמה וחסדים יחדיו. \u0003צורי\u0004 פירושו הנוקבא דז\"א. כאשר מתחברים \u0003חי הויה וצור\u0004 כאחד, נקרא הצור, באר מים חיים, זה נובע מבפנים של הבאר, דהיינו חי הויה וברוך, וזו מתמלאת ממנו, דהיינו הצור, שהוא הבאר. והטעם שנקראת \u0003באר מים חיים,\u0004 הוא, כי \u0003מים\u0004 ה\"ס חסדים שמקבלת מן \u0003ברוך, חיים\u0004 ה\"ס הארת חכמה שמקבלת מן \u0003חי.\u0004 ועל שם המבוע הנובע בה ב' הארות הללו, היא נקראת \u0003באר.\u0004 ונתבאר סוד הכתוב, \u0003חי הוי\"ה וברוך צורי,\u0004 שיורה על שלמות הזווג דז\"א ונוקביה, בשעה שמקבלת ממנו מוחין השלמים המרומזים בהמלות, \u0003חי, וברוך.\u0004"],[3,"וירום אלקי ישעי:","זהו עולם העליון, דהיינו בינה, שהוא רם ונשא, רם על כל, כי ממנו יוצא כל, דהיינו כל המוחין שבזו\"ן ובי\"ע מבינה הם, וכל נביעה שנובע למלאות הבאר, ממנו הן, ומשם מתברכת הנוקבא, להאיר לכל אלו שלמטה מאצילות, וכשכולם מתמלאים ממנה בשפע. אז וירום אלקי ישעי, כי העליון מתרומם ומתנשא ע\"י ריבוי השפע שמשפיע לתחתונים."],[4,"פתח ר' ייסא וכו':","פתח ר\"י ואמר, לא יגרע מצדיק עיניו וגו'. בוא וראה, כשהרשעים אינם שולטים בעולם, ונאבדו מן העולם, אז צדיק שולט בעולם וז\"ש לא יחיה רשע ומשפט עניים יתן, דהיינו שהרשעים יאבדו מן העולם, מה כתוב אחריו, לא יגרע מצדיק עיניו, מהו \u0003עיניו,\u0004 הוא כמש\"א עיני ה' אל הצדיקים. דהיינו שזוכים אז במוחין דהארת חכמה, המכונים עינים. שאז שולט הצדיק בעולם. שה\"ס קו אמצעי, כי אין שליטה אלא באור החכמה."],[5,"ואת מלכים לכסא:","אלו הם מלכים השולטים, דהיינו שיש בהם הארת חכמה שה\"ס השליטה, המאוחזים בכסא. \u0003ויושיבם לנצח,\u0004 היינו שהם מתקיימים בכסא בקיום שלם. \u0003ויגבהו,\u0004 ושואל למה נגבהו, ומשיב, שנגבהו כדי לשלוט בעולם, והכסא יתקיים על עמודיו."],[5,"","פירוש. בשעה שהקו שמאל שולט בלי התכללות בימין, שהארתו נמשכת אז ממעלה למטה, מקבלים הרשעים מהארתו זו, חיות וכח לשלוט בעולם, ומשחיתים ומחריבים בכל שימצאו, בסו\"ה \u0003ארץ נתנה ביד רשע וגו'.\u0004 וכשהתחתונים מעלים מ\"ן לזו\"ן, עולה ז\"א למ\"ן לבינה עם מסך דחירק שלו ויוצא עליו קומת חסדים מבחי\"א, וממעט בזה את הג\"ר דקו שמאל, (כנ\"ל לך דף י\"ג ד\"ה ונתבאר) ואין הארתו נמשכת יותר ממעלה למטה, אלא ממטה למעלה בלבד, ואז מתבטל חיותם של הרשעים ונאבדים, בסו\"ה, \u0003לא יחיה רשע וגו'.\u0004 ואע\"פ שנתבטלו הג\"ר דקו שמאל שה\"ס הארת החכמה, משמיענו הכתוב, \u0003לא יגרע מצדיק עיניו,\u0004 שלא נגרע מחמת זה העינים שה\"ס. החכמה, לצדיק, שה\"ס קו אמצעי, כי הוא מקבל בחינת ו\"ק דג\"ר דשמאל, הנכללים בימין שזהו כל שלימותה של הארת החכמה, (כנ\"ל נח דף פ\"ד ד\"ה ובג\"כ) וז\"ש, \u0003כד חייביא לא שלטין בעלמא ואתאבידו מניה,\u0004 דהיינו בשעה שז\"א מעלה את המסך דחירק למ\"ן אל הבינה שאז שאז נאבדים הרשעים, \u0003כדין צדיק איהו שליט,\u0004 מקבל אז הצדיק הארת החכמה שה\"ס השליטה. וז\"ש \u0003ואת מלכים לכסא, אלין אנון מלכין שליטין דאתאחדן לכסא,\u0004 שאלו המלכים השולטים בארץ, מקבלים השליטה מן המלכות כשהוא בסוד \u0003כסא.\u0004 שהם בחינת מוחין דישיבה והרמז הוא, כי כשאדם יושב על הכסא, מתמעט קומתו בסבת הישיבה שהיא נוחה לו, כן אלו המוחין מתמעטים מג\"ר לו\"ק דג\"ר, כדי לבער הרשעים מן העולם, כנ\"ל. וז\"ש, \u0003ויושיבם לנצח דאתקיימו בכרסיא בקיומא שלים,\u0004 דהיינו שלא יפסוק שליטתם לנצח, מחמת שנתבערו הרשעים ולא יוכלו עוד להתאחז באלו המוחין, כנ\"ל, וז\"ש \u0003ויגבהו, לשלטאה בעלמא, ויתקיים כרסיא על סמכוהי,\u0004 כי ויגבהו, פירושו שמקבלים המוחין ממטה למעלה וצריכים משום זה לעלות במקום גבורה שהיא הנוקבא דז\"א, לקבל שם המוחין. וז\"ש \u0003אמאי ויגבהו\u0004 ומשיב, \u0003לשלטאה וכו'\u0004 דהיינו שהם עושים זאת, כדי לשלוט בעולם, דהיינו לקבל המוחין דחכמה, ולקיים תקון הכסא על עמודיו שה\"ס התקון קוין של הכסא שהוא הנוקבא, באופן שיתקיימו לנצח."],[5,"דבר אחר ויגבהו וכו':","פירוש אחר על, \u0003ויגבהו,\u0004 שלוקחים הכסא, שהוא הנוקבא, ומעמידים אותו למעלה במקום בינה, לייחדה במקומה כראוי. פי', כי אין המוחין דנוקבא בכל שלמותה אלא אחר שעולה אל הבינה ומלבישה אותה. וע\"כ אומר \u0003ויגבהו,\u0004 שמעלים אותה למעלה אל הבינה."],[6,"עד דהוו אזלי וכו':","בעוד שהיו הולכים. ראו איש אחר שהיה בא, וילד אחד עמו, שהיה רוכב על כתפו. אמר ר' יצחק, ודאי הוא, שאדם זה הוא יהודי, ובכדי לזכות אנשים הוא בא. כלומר שבא לקבל צדקה ולזכות אנשים בעולם הבא. אמר ר' ייסא, נזכה בו אנחנו תחילה."],[7,"כד מטי לגבייהו וכו':","כאשר הגיע אצלם, אמר לו ר' ייסא, איפה הכלי עם מאכלי הדרך שלך. כי לא ראוהו נושא שום דבר, זולת הילד שעל כתפיו. \u0003קיסתא,\u0004 פירושו כלי. \u0003דטרימא בקירטוי,\u0004 הוא כמו, טרימא דקורטמי (ברכות ל\"ח) שפירושו, מין מאכל של תמרים מעוכים עם שומשמין. אמר להם, אין לי דבר, כדי שיזכו על ידי אנשים בנתינת צדקה. כי שני בנים יש לי, וצבא בא לעיר, ונשבו, ועתה אני הולך כדי שיזכו על ידיהם בני אדם, כלומר שיתנו לי כסף לפדותם. זכו עמו, דהיינו שנתנו לו צדקה, ונתנו לו לאכול."],[8,"אדהכי פתח וכו':","בינתיים, פתח היהודי ואמר, \u0003את קרבני לחמי וגו'.\u0004 הקרבן של הקב\"ה בכל יום, הוא, לזון העולם, ולתת כלכלה למעלה ולמטה, כי בהתעוררות שלמטה, עם הקרבת קרבן תמיד, מתעורר למעלה השפעת השפע, שבזה מתכלכלים כל אחד ואחד כראוי. \u0003מזון\u0004 פירושו שפע אור החסדים. \u0003כלכלה,\u0004 פירושו חכמה מלובשת בחסדים, דהיינו שכלול מב' הצדדים, שזהו הוראת השם, \u0003כלכלה.\u0004"],[9,"את קרבני לחמי:","זהו שכתוב, אכלתי יערי עם דבשי שתיתי ייני עם חלבי שזה יורה על \u0003כלכלה\u0004 הנ\"ל. \u0003לאשי\u0004 זה הוא שכתוב, אכלו רעים וגו', שזה יורה על \u0003מזון\u0004 הנ\"ל: וכשם שהקב\"ה מצוה לעורר מזונות למעלה, כדי להשפיע מזונות למטה מאותו המזון של מעלה, מי שנותן מזונות לעני לקיים הנפש, על אחת כמה וכמה שהקב\"ה מברך אותו ומשפיע לו מזונות של מעלה והעולם מתברך בשבילו."],[10,"אמר ר' יצחק וכו':","אר\"י, ודאי סוד זה ביאר כראוי, ויפה אמר, אמר ר' ייסא, ודאי, על זה אמרו, שלא יזלזל אדם בשום איש שבעולם. כי בתחילה חשבוהו לעם הארץ, וכמעט שהיו מזלזלים בו. כי בשני אופנים זכיתי על ידי אדם הזה. פירוש. א) שזכה על ידו בעולם הבא על ידי נתינת צדקה. ב) שזכה לשמוע ממנו חידוש תורה נפלא."]],[[0,"","וְיִשָּׁאֵר הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, כְּמוֹ שֶׁכָּתוּב וְהָאֱלִילִים כָּלִיל יַחֲלֹף, וְכָתוּב וְנִשְׂגָּב ה' לְבַדּוֹ בַּיּוֹם הַהוּא. הוּא לְבַדּוֹ, כְּמוֹ שֶׁכָּתוּב (דברים לב) וְאֵין עִמּוֹ אֵל נֵכָר, מִשּׁוּם שֶׁיִּכְלֶה כֹּחַ הַטֻּמְאָה מִן הָעוֹלָם, וְלֹא יִשָּׁאֵר לְמַעְלָה וּלְמַטָּה אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, וְיִשְׂרָאֵל לַעֲבוֹדָתוֹ, עַם קָדוֹשׁ. וְיִקָּרֵא קָדוֹשׁ, שֶׁכָּתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלם קָדוֹשׁ יֵאָמֶר לוֹ כָּל הַכָּתוּב לַחַיִּים בִּירוּשָׁלם. וְאָז יִהְיֶה מֶלֶךְ יְחִידִי לְמַעְלָה וּלְמַטָּה, וְעַם יְחִידִי לַעֲבוֹדָתוֹ, כְּמוֹ שֶׁכָּתוּב וּמִי כְּעַמְּךְ יִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ."],[1,"","רַבִּי יִצְחָק וְרַבִּי יֵיסָא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יֵיסָא, הִנֵּה שְׁכִינָה אֶצְלֵנוּ, נִתְעַסֵּק בְּדִבְרֵי תוֹרָה, שֶׁכָּל מִי שֶׁעוֹסֵק בְּדִבְרֵי תוֹרָה וּמִשְׁתַּדֵּל בָּהּ, זוֹכֶה לְהַמְשִׁיךְ אוֹתָהּ עִמּוֹ."],[2,"","פָּתַח רַבִּי יִצְחָק וְאָמַר, (תהלים יח) חַי ה' וּבָרוּךְ צוּרִי וְיָרוּם אֱלוֹהֵי יִשְׁעִי. הַפָּסוּק הַזֶּה הוּא סוֹד. חַי ה', וְכִי לֹא יָדַעְנוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא חַי? אֶלָּא אֲפִלּוּ צַדִּיק גָּמוּר, הוּא נִקְרָא חַי, שֶׁהֲרֵי חַי - צַדִּיק הוּא לְמַעְלָה וְצַדִּיק הוּא לְמַטָּה. לְמַעְלָה הַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא חַי - לְמַטָּה הַצַּדִּיק נִקְרָא חַי, שֶׁכָּתוּב (שמואל ב כג) וּבְנָיָהוּ בֶּן יְהוֹיָדָע בֶּן אִישׁ חַי. לָמָּה נִקְרָא חַי? מִשּׁוּם שֶׁהוּא צַדִּיק, שֶׁהֲרֵי צַדִּיק נִקְרָא חַי, חֵי הָעוֹלָמִים. וּבָרוּךְ צוּרִי - הַכֹּל אֶחָד. חַי וּבָרוּךְ - שֶׁלֹּא נִפְרָדִים זֶה מִזֶּה. שֶׁכַּאֲשֶׁר מִתְחַבְּרִים יַחַד נִקְרָא בְּאֵר מַיִם חַיִּים. זֶה נוֹבֵעַ הַחוּצָה, וְזֶה מִתְמַלֵּא מִמֶּנּוּ."],[3,"","וְיָרוּם אֱלוֹהֵי יִשְׁעִי - זֶה הָעוֹלָם הָעֶלְיוֹן, שֶׁהוּא רָם וְנִשָּׂא, רָם עַל הַכֹּל, שֶׁהֲרֵי מִמֶּנּוּ יוֹצֵא הַכֹּל, (מקור שלא פוסק) וְכָל הַנְּבִיעָה שֶׁנּוֹבֵעַ לְמַלֵּא הַבְּאֵר כָּרָאוּי, וּמִשָּׁם מִתְבָּרֶכֶת לְהָאִיר לְכָל אוֹתָם שֶׁלְּמַטָּה. וּכְשֶׁמִּתְמַלֵּאת (זו) הַכֹּל כָּרָאוּי, אָז וְיָרוּם אֱלוֹהֵי יִשְׁעִי."],[4,"","פָּתַח רַבִּי יֵיסָא וְאָמַר, (איוב לו) לֹא יִגְרַע מִצַּדִּיק עֵינָיו וְאֶת מְלָכִים לַכִּסֵּא וַיֹּשִׁיבֵם לָנֶצַח וַיִּגְבָּהוּ. בֹּא רְאֵה, כְּשֶׁרְשָׁעִים לֹא שׁוֹלְטִים בָּעוֹלָם וְנֶאֱבָדִים מִמֶּנּוּ (מהעולם), אָז הַצַּדִּיק שׁוֹלֵט בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב לֹא יְחַיֶּה רָשָׁע וּמִשְׁפַּט עֲנִיִּים יִתֵּן. מַה כָּתוּב אַחֲרָיו? לֹא יִגְרַע מִצַּדִּיק עֵינָיו. מַה זֶּה עֵינָיו? כְּמוֹ שֶׁנֶּאֱמַר (תהלים לד) עֵינֵי ה' אֶל צַדִּיקִים."],[5,"","וְאֶת מְלָכִים לַכִּסֵּא - אֵלּוּ הֵם הַמְּלָכִים הַשּׁוֹלְטִים שֶׁנֶּאֱחָזִים בַּכִּסֵּא. וַיֹּשִׁיבֵם לָנֶצַח - שֶׁהִתְקַיְּמוּ בַּכִּסֵּא בְּקִיּוּם שָׁלֵם. וַיִּגְבָּהוּ - לָמָּה וַיִּגְבָּהוּ? לִשְׁלֹט בָּעוֹלָם, וְיִתְקַיֵּם הַכִּסֵּא עַל עַמּוּדָיו. דָּבָר אַחֵר וַיִּגְבָּהוּ - שֶׁנּוֹטְלִים אֶת הַכִּסֵּא וּמַעֲמִידִים אוֹתוֹ לְמַעְלָה לְהֵאָחֵז בִּמְקוֹמוֹ כָּרָאוּי, וְאָז הַכֹּל יִחוּד אֶחָד."],[6,"","בְּעוֹדָם הוֹלְכִים רָאוּ אִישׁ אֶחָד שֶׁהָיָה בָּא, וְעֶלֶם אֶחָד עִמּוֹ רוֹכֵב עַל כְּתֵפוֹ. אָמַר רַבִּי יִצְחָק, וַדַּאי שֶׁהָאִישׁ הַזֶּה הוּא יְהוּדִי, וּכְדֵי לְזַכּוֹת אֲנָשִׁים הוּא בָּא. אָמַר רַבִּי יֵיסָא, נִזְכֶּה אָנוּ בּוֹ בָּרִאשׁוֹנָה."],[7,"","כְּשֶׁהִגִּיעַ אֲלֵיהֶם, אָמַר רַבִּי יֵיסָא, אֵיפֹה הַכְּלִי (המדה של העמיר) עִם מַאַכְלֵי הַדֶּרֶךְ? אָמַר, כְּדֵי שֶׁיִּזְכּוּ (בו) אֲנָשִׁים, שֶׁהֲרֵי יֵשׁ לִי שְׁנֵי בָנִים, וְהִגִּיעַ הַצָּבָא לָעִיר וְנִשְׁבּוּ, וְכָעֵת אֲנִי הוֹלֵךְ כְּדֵי שֶׁיִּזְכּוּ בָהֶם בְּנֵי אָדָם. זָכוּ עִמּוֹ וְנָתְנוּ לוֹ לֶאֱכֹל."],[8,"","בֵּינְתַיִם פָּתַח אוֹתוֹ יְהוּדִי וְאָמַר, (במדבר כח) אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי וְגוֹ'. הַקָּרְבָּן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל יוֹם כְּדֵי לָזוּן אֶת הָעוֹלָם וְלָתֵת כַּלְכָּלָה לְמַעְלָה וּלְמַטָּה, שֶׁהֲרֵי בַּהִתְעוֹרְרוּת שֶׁלְּמַטָּה מִתְעוֹרֵר לְמַעְלָה, וּבָזֶה מִתְכַּלְכְּלִים כָּל אֶחָד וְאֶחָד כָּרָאוּי."],[9,"","אֶת קָרְבָּנִי לַחְמִי - זֶהוּ שֶׁכָּתוּב (שיר ה) אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי שָׁתִיתִי יֵינִי עִם חֲלָבִי. לְאִשַּׁי - זֶהוּ שֶׁכָּתוּב אִכְלוּ רֵעִים וְגוֹ'. וּמָה הַקָּדוֹשׁ בָּרוּךְ הוּא צִוָּה לְעוֹרֵר מָזוֹן לְמַעְלָה (למטה) כְּדֵי לְעוֹרֵר מָזוֹן (למעלה) לְמַטָּה מֵהַמָּזוֹן הַהוּא - מִי שֶׁנּוֹתֵן לְקַיֵּם נֶפֶשׁ עַל אַחַת כַּמָּה וְכַמָּה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְבָרֵךְ אוֹתוֹ, וְיָעִיר לוֹ מָזוֹן שֶׁלְּמַעְלָה, וְיִתְבָּרֵךְ הָעוֹלָם בִּשְׁבִילוֹ."],[10,"","אָמַר רַבִּי יִצְחָק, וַדַּאי זֶה הַסּוֹד כָּרָאוּי, וְיָפֶה אָמַר. אָמַר רַבִּי יֵיסָא, וַדַּאי עַל זֶה אָמַר אוֹתוֹ, שֶׁלֹּא יְזַלְזֵל אָדָם בְּשׁוּם אָדָם אֶחָד בָּעוֹלָם, בִּשְׁתֵּי צוּרוֹת זָכִינוּ לָאִישׁ הַזֶּה."]]],[["פָּתַח וְאָמַר, הַאי קְרָא אָמַר רִבִּי אֶלְעָזָר (במדבר כ״ח:ב׳) אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי, אֶת קָרְבָּנִי, רָזָא דִכְנְסֶת יִשְׂרָאֵל. דִּכְתִיב אֶת, אֶת דַּיְיקָא. קָרְבָּנִי, דָּא אִיהוּ קָרְבָּנָא, וְקִשּׁוּרָא לְאִתְקַשְּׁרָא. לַחְמִי, דָּא מְזוֹנָא דְּאָתֵי מִלְעֵילָא, בְּאִתְעֲרוּתָא דִלְתַתָּא. לְאִשַּׁי, לְאִתְכְּלָלָא שְׁאָר חֵילִין אָחֳרָנִין דְּאִצְטְרִיכוּ לְאִתְּזָנָא, כָּל חַד וְחַד כְּדְקָא חָזֵי לֵיהּ. רֵיחַ נִיחֹחִי, דָּא רְעוּתָא וְקִשּׁוּרָא, דְּאִתְאַחֲדָא כֹּלָּא בְּרָזָא דְעַלְמָא עִלָּאָה.","תִּשְׁמְרוּ לְהַקְרִיב לִי בְּמוֹעֲדוֹ, מַאן מוֹעֲדוֹ, בִּזְמַן דְּאִתְעַר אַבְרָהָם לְמֶעְבַּד רְעוּתֵיהּ, דִּכְתִיב, (בראשית כ״ב:ג׳) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. וּבְזִמְנָא דְאִתְעֲקַד יִצְחָק עַל גַּבֵּי מַדְבְּחָא, דְּהַהִיא שַׁעְתָּא, בֵּין הָעַרְבַּיִם הֲוָה. וְאָמַר רִבִּי (חייא) יֵיסָא, אִי הָכִי, הַאי דִכְתִיב בְּמוֹעֲדוֹ, בְּמוֹעֲדִים מִבָּעֵי לֵיהּ. אָמַר לֵיהּ, הַהִיא שַׁעְתָּא, אִתְכְּלִיל אֶשָׁא בְּמַיָא וּמַיָא בְּאֶשָׁא, וּבְגִין כָּךְ כְּתִיב בְּמוֹעֲדוֹ.","תָּא חֲזֵי, בְּכָל קָרְבָּנִין לָא כְּתִיב כְּמָה דִכְתִיב הָכָא, תִּשְׁמְרוּ לְהַקְרִיב לִי. תִּשְׁמְרוּ, רָזָא דְשָׁמוֹר, דְּאִיהוּ צְרִיכָא לְקָרְבָא לְגַבֵּי עֵילָא, דִּכְתִיב תִּשְׁמְרוּ לְהַקְרִיב לִי בְּמוֹעֲדוֹ. בִּימִינָא וּשְׂמָאלָא, כְּמָה דְאִתְּמָר בְּאַבְרָהָם וְיִצְחָק, וְכֹלָּא בְּרָזָא עִלָּאָה.","אָמַר רִבִּי יֵיסָא אִלְמָלֵא לָא אָתֵינָא הָכָא, אֶלָּא לְמִשְׁמַע מִלִּין אִלֵּין, דַּיַּי. זַכָּאִין אִינוּן יִשְׂרָאֵל, בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי. עַל דָּא כְּתִיב, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר.","(בראשית ל״א:י״ט) וְלָבָן הָלַךְ לִגְזֹז אֶת צֹאנוֹ וְגו'. אָמַר רִבִּי יוֹסֵי מַאן תְּרָפִים, אֶלָּא עֲבוֹדָה זָרָה הֲווּ, וְאַמַּאי אִקְרֵי תְּרָפִים, לִגְנַאי הֲוָה, כְּמָה דְתָנִינָן בְּמָקוֹם הַתּוֹרֶף. וּמְנָלָן דְּעֲבוֹדָה זָרָה הֲווּ, דִּכְתִיב, (שם) לָמָּה גָנַבְתָּ אֶת אֱלֹהָי. וּכְתִיב, (שם) עִם אֲשֶׁר תִּמְצָא אֶת אֱלֹהֶיךָ וְגו'. וְלָבָן חָרָשָׁא דְּכָל חֳרָשִׁין דְּעַלְמָא הֲוָה, וּבְהַאי הֲוָה יָדַע בְּכָל מַאן דְּבָעֵי לְמִנְדַע.","אָמַר רִבִּי חִיָּיא, בְּקֶסֶם אִתְעֲבִיד. רִבִּי יוֹסֵי אוֹמֵר, בְּנַחַשׁ. אָמַר רִבִּי יְהוּדָה, לָא אִתְעֲבִידוּ אֶלָּא בְּשַׁעְתֵּי יְדִיעָן. וְאַמַּאי אִקְרֵי תְּרָפִים. בְּגִין דְּבַטְשֵׁי הַאי שַׁעְתָּא, וְהַאי שַׁעְתָּא אַרְפֵּי יְדָא, כְּמָה דְאַתְּ אָמֵר, (שמואל ב כ״ד:ט״ז) רַב עַתָּה הֶרֶף יָדֶךָ.","אוּמָנָא כַּד עָבִיד לֵיהּ, הַהוּא דְיָדַע רִגְעֵי וְשַׁעְתֵּי קָאִים עֲלֵיהּ, וְאָמַר, הַשְׁתָּא אַרְפֵּי, וְהַשְׁתָּא עָבִיד. וְלָא תִשְׁכַּח עֲבִידְתָּא דְּאִצְטְרִיךְ דְּיִרְפּוּן מִינָהּ אֶלָּא הַאי. וְאִיהוּ מַלִּיל תָּדִיר, וְיָהִיב עֵיטִין בִּישִׁין לְאַבְאָשָׁא לְנַפְשֵׁיהּ דְּבַר נָשׁ.","וְרָחֵל דְּחִילַת, בְּגִין דְּיָהַב עֵיטָא לְאַבְאָשָׁא לֵיהּ לְיַעֲקֹב, וּבְגִין בִּזְיוֹנָא דְּעֲבוֹדָה זָרָה, שַׁוֵּי לוֹן תְּחוֹתָהּ, עַד דְּלָא יָכִיל לְמַלָּלָא. דְהָא כַּד אִיהוּ מִתְתַּקַּן לְמַלָּלָא, מְכַבְּדִין וּמַרְבִּיצִין קַמֵּיהּ, וְהַשְׁתָּא מַה כְּתִיב, (בראשית ל״א:ל״ד) וַתֵּשֶׁב עֲלֵיהֶם. דְּכַר וְנוּקְבָא הֲווּ, וּפוּלְחָנִין סַגִּיאִין קָא עָבְדִין עַד לָא מְמַלְּלָן. וּבְגִינִי כָּךְ אִתְעַכַּב לָבָן תְּלַת יוֹמִין, דְּלָא יָדַע דְּעָרַק יַעֲקֹב, דִּכְתִיב, (שם) וַיֻּגַּד לְלָבָן בַּיּוֹם הַשְּׁלִישִׁי כִּי בָרַח יַעֲקֹב.","וְאָמַר רִבִּי יְהוּדָה, זַמִּין גַּרְמֵיהּ בִּתְרֵין מִלִּין, אִזְדָּרַז בְּכָל חֳרָשִׁין דְּהֲוָה לֵיהּ וְאִזְדָּרַז בְּזַיְינִין, בְּגִין לְאוֹבָדָא לֵיהּ מִן עָלְמָא, דִּכְתִיב (דברים כ״ו:ה׳) אֲרַמִּי אֹבֵד אָבִי. כֵּיוָן דְּחָמָא קוּדְשָׁא בְּרִיךְ הוּא, דְּבָעָא לְאוֹבָדָא לְיַעֲקֹב. מַה כְּתִיב, (בראשית ל״א:כ״ד) הִשָּׁמֶר לְךָ פֶּן תְּדַבֵּר עִם יַעֲקֹב מִטּוֹב עַד רָע. וְהַיְינוּ דִּכְתִיב, (שם) יֵשׁ לְאֵל יָדִי לַעֲשׂוֹת עִמָּכֶם רָע. בַּמֶּה אִתְרְחִיץ, בָּחֳרָשִׁין דְּהֲווּ בִּידֵיהּ.","תָּא חֲזֵי, לָבָן אֲזַל בְּיוֹמָא חַד, אֹרַח שִׁבְעָה יָמִים דְּאֲזַל יַעֲקֹב, בְּגִין לְאַעֲקָרָא לֵיהּ מִן עָלְמָא. חַד, עַל דְּאֲזַל. וְחַד, עַל אִינוּן תְּרָפִים. וְאַף עַל גַּב דְּרָחֵל אִיהִי עָבְדַת לְאַעֲקָרָא לֵיהּ לַאֲבוּהָ מִבָּתַר עֲבוֹדָה זָרָה, אִתְעֲנָשַׁת. דְּלָא רְבִיאַת לֵיהּ לְבִנְיָמִן, וְלָא קָיְימָא בַּהֲדֵיהּ שַׁעְתָּא חָדָא, בְּגִין צַעֲרָא דְּאֲבוּהָ, אַף עַל גַּב דְּאִתְכַּוְּונַת לְטַב.","רִבִּי יִצְחָק אָמַר, כָּל הַהִיא תּוֹכַחְתָּא דְּהֲוָה לֵיהּ לְיַעֲקֹב בְּלָבָן. אַהֲדַר לֵיהּ לְלָבָן, לְאוֹדָאָה לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִיב (בראשית ל״א:נ׳) רְאֵה אֱלֹהִים עֵד בֵּינִי וּבֵינֶיךָ. תָּא חֲזֵי, כְּתִיב, (בראשית ל״א:נ״ג) אֱלהֵי אַבְרָהָם וִאלהֵי נָחוֹר יִשְׁפְּטוּ בֵּינֵינוּ, אַהֲדַר הַהוּא רָשָׁע לְתַקְלֵיהּ, כֵּיוָן דְּאָמַר אֱלֹהֵי אַבְרָהָם, אַהֲדַר וְאָמַר וִאלהֵי נָחוֹר."],[[0,"פתח ואמר וכו':","פתח האיש ואמר, מקרא זה אמר ר' אלעזר, את קרבני לחמי לאשי, \u0003את קרבני,\u0004 הוא סוד כנסת ישראל, שהיא הנוקבא, שכתוב \u0003את,\u0004 שפירושו הנוקבא, \u0003את\u0004 הוא מדויק, כלומר, שהכתוב מרמז בזה, שהכונה היא על הנוקבא. \u0003קרבני,\u0004 זה הוא קרבה וקשר להתקשר דהיינו לקרב ולקשר הנוקבא בז\"א. \u0003לחמי\u0004 זה הוא המזונות, דהיינו שפע המוחין, הבא למעלה, בסבת ההתעוררות של מטה, שבהקרבת התמיד, \u0003לאשי,\u0004 הוא לכלול שאר המלאכים האחרים, שצריכים להיות נזונים מכאן, כל אחד כראוי לבחינתו. \u0003ריח ניחוחי,\u0004 זה הוא הרצון והיחוד שהכל מתייחד בסוד עולם העליון שהוא בינה, פירוש. שה\"ס גילוי הארת החכמה מעולם העליון, המאיר ממטה למעלה, שה\"ס הריח. (כנ\"ל תולדות דף נ\"ח ד\"ה וירח ע\"ש)."],[1,"תשמרו להקריב לי במועדו:","שואל מתי הוא מועדו. ומשיב, הוא בזמן שאברהם נתעורר לעשות רצונו יתברך, שנאמר וישכם אברהם בבקר. שהוא הזמן דתמיד של שחרית. ובזמן שנעקד יצחק על המזבח, ששעה ההיא בין הערבים היה. והוא הזמן של תמיד בין הערבים. אמר ר' ייסא, אם כן, למה כתוב במועדו, לשון יחיד, במועדם היה צריך לומר, לשון רבים, כי יש ב' מועדים. אמר לו, בשעה ההיא של הקרבת התמיד, נכלל אש במים ומים באש, כלומר שמדת אברהם שהוא מים נכלל במדת יצחק שהוא אש, וכן להיפך, ומשום זה כתוב במועדו לשון יחיד. כי נכללו להיות אחד."],[2,"ת\"ח בכל קרבנין וכו':","בוא וראה, בכל הקרבנות לא כתוב, לשון תשמרו, כמ\"ש כאן, תשמרו להקריב, הוא, כי \u0003תשמרו\u0004 הוא סוד \u0003שמור,\u0004 שהיא הנוקבא, שהיא צריכה לקרב למעלה, לז\"א, שכתוב \u0003תשמרו להקריב לי.\u0004 דהיינו להקריב את הנוקבא \u0003במועדו,\u0004 היינו בימין ושמאל, דז\"א, כמו שנתבאר, לעיל, שהם אברהם ויצחק, והכל הוא בסוד העליון."],[3,"אמר ר' ייסא וכו':","אר\"י, אלו לא באתי לכאן אלא לשמוע דברים אלו, דיי. אשריהם ישראל בעולם הזה, ובעולם הבא. על זה כתוב, ועמך כולם צדיקים לעולם ירשו ארץ וגו'."],[4,"ולבן הלך לגזוז את צאנו וגו':","אמר ר' יוסי, מה הם התרפים. ואומר, שעבודה זרה היו, ולמה נקראו תרפים, הוא לבזיון, כמו שלמדנו, שהוא מלשון במקום התורף. שפירושו בית התורפה. ומאין לנו שהיו עבודה זרה, כי כתוב, למה גנבת את אלהי, וכתוב, עם אשר תמצא את אלהיך וגו'. ולבן מכשף דכל מכשפי העולם היה, ובאלו התרפים היה יודע, כל מה שהיה צריך לדעת."],[5,"אמר ר' חייא וכו':","אר\"ח בקסמים נעשו התרפים. ר' יוסי אומר בנחש נעשו. אמר ר' יהודה, לא נעשו אלא בשעות ידועות, ולמה נקראים תרפים, משום שדופקים עליהם בשעה זו ומרפים ידם מהם בשעה זו כמו שאתה אומר, רב עתה \u0003הרף\u0004 ידך. ועל שם החיוב \u0003להרפות\u0004 היד מהם בשעות ידועות, הם נקראים \u0003תרפים.\u0004"],[6,"אומנא כד עביד וכו':","האומן כשעושה אותו, מי שיודע הרגעים והשעות, מתי לפעול ומתי להרפות הידים עומד עליו, ואומר, עתה הרפה. ועתה עשה. ולא תמצא עוד פעולה שצריכים בשעה ידועה להרפות ידים ממנה, חוץ מזו של התרפים. והוא מדבר תמיד ונותן עצות רעות להזיק נפשו של אדם."],[7,"ורחל דחילת וכו':","ורחל יראה, שלא יתנו התרפים עצה להרע ליעקב, ומשום בזיון עבודה זרה, נתנה אותם תחתיה, עד שלא יכלו לדבר, כי כשמתקנים אותם לדבר מטאטאים ומרביצים לפניו, דהיינו שצריכים לכבדם, ועתה מה כתוב, \u0003ותשב עליהם,\u0004 שבזתה אותם, וכיון שרחל בזתה אותם לא יכלו לדבר. זכר ונקבה היו, התרפים, ועבודות רבות עבדו להם, עד שהתחילו לדבר."],[7,"ובגיני כך אתעכב וכו':","ומשום זה שלא היה לו התרפים, נעצר לבן ג' ימים שלא היה יודע שברח יעקב, שכתוב, ויוגד ללבן ביום השלישי כי ברח יעקב."],[8,"ואמר ר' יהודה וכו':","ואר\"י, הכין עצמו בב' דברים, שנתאזר בבל הכשפים שהיו לו, ונתאזר בכלי זיין, כדי להאביד את יעקב מן העולם, שכתוב ארמי אובד אבי, כיון שראה הקב\"ה שרוצה להאביד את יעקב, מה כתוב, השמר לך פן תדבר עם יעקב מטוב עד רע. והיינו שכתוב יש לאל ידי לעשות עמכם רע. ושואל, במה בטח כל כך. ומשיב, שבטח בכשפים שבידו."],[9,"תא חזי לבן וכו':","בוא וראה, לבן הלך ביום אחד, דרך שבעה ימים שהלך יעקב, כדי לעקור אותו מן העולם: א', משום שהלך ממנו, וא', על התרפים שגנבו ממנו. ואף על פי שרחל עשתה זה, כדי לעקור את אביה מעבודה זרה, מכל מקום נענשה, שלא גידלה את בנימין, ולא היתה עמו, אפילו שעה אחת, בעולם, משום הצער של אביה, ואף על פי שנתכוונה לטוב."],[10,"רבי יצחק אמר וכו':","כל התוכחה הזו, שהיתה ליעקב עם לבן, החזירה את לבן בתשובה, להודות להקב\"ה. שכתוב ראה אלקים עד ביני וביניך. שהזכיר השם אלקים. בוא וראה, כתוב, אלקי אברהם ואלהי נחור ישפטו בינינו, שחזר אותו רשע לסורו, כיון שאמר אלקי אברהם, שהוא קדוש, חזר והזכיר אלהי נחור, שהם עבודה זרה."]],[[0,"","פָּתַח וְאָמַר, הַפָּסוּק הַזֶּה אָמַר רַבִּי אֶלְעָזָר, אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי. אֶת קָרְבָּנִי - הַסּוֹד שֶׁל כְּנֶסֶת יִשְׂרָאֵל, שֶׁכָּתוּב אֶת, אֶת דַּוְקָא. קָרְבָּנִי - זֶהוּ קָרְבָּן וְקֶשֶׁר לְהִתְקַשֵּׁר. לַחְמִי - זֶה הַמָּזוֹן שֶׁבָּא מִלְמַעְלָה בַּהִתְעוֹרְרוּת שֶׁלְּמַטָּה. לְאִשַּׁי - לְהַכְלִיל שְׁאָר הַחֲיָלוֹת הָאֲחֵרִים שֶׁהִצְטָרְכוּ לְהִזּוֹן כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ. רֵיחַ נִיחֹחִי - זֶה הָרָצוֹן וְהַקֶּשֶׁר שֶׁאוֹחֵז אֶת הַכֹּל בְּסוֹד הָעוֹלָם הָעֶלְיוֹן."],[1,"","תִּשְׁמְרוּ לְהַקְרִיב לִי בְּמוֹעֲדוֹ, מִי הוּא מוֹעֲדוֹ? בַּזְּמַן שֶׁמִּתְעוֹרֵר אַבְרָהָם לַעֲשׂוֹת רְצוֹנוֹ, שֶׁכָּתוּב (בראשית כב) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר, וּבַזְּמַן שֶׁנֶּעֱקַד יִצְחָק עַל גַּבֵּי הַמִּזְבֵּחַ, שֶׁאוֹתָהּ הַשָּׁעָה הָיְתָה בֵּין הָעַרְבַּיִם. וְאָמַר רַבִּי (חייא) יֵיסָא, אִם כָּךְ, זֶה שֶׁכָּתוּב בְּמוֹעֲדוֹ הָיָה צָרִיךְ לִהְיוֹת בְּמוֹעֲדִים! אָמַר לוֹ, אוֹתָהּ הַשָּׁעָה נִכְלַל אֵשׁ בְּמַיִם וּמַיִם בְּאֵשׁ, וּמִשּׁוּם כָּךְ כָּתוּב בְּמוֹעֲדוֹ."],[2,"","בֹּא רְאֵה, בְּכָל הַקָּרְבָּנוֹת לֹא כָתוּב כְּמוֹ שֶׁכָּתוּב כָּאן תִּשְׁמְרוּ לְהַקְרִיב לִי. תִּשְׁמְרוּ - הַסּוֹד שֶׁל שָׁמוֹר, שֶׁהוּא צָרִיךְ לְהַקְרִיב לְמַעְלָה, שֶׁכָּתוּב תִּשְׁמְרוּ לְהַקְרִיב לִי בְּמוֹעֲדוֹ, בְּיָמִין וּבִשְׂמֹאל, כְּמוֹ שֶׁנֶּאֱמַר בְּאַבְרָהָם וְיִצְחָק, וְהַכֹּל בְּסוֹד עֶלְיוֹן."],[3,"","אָמַר רַבִּי יֵיסָא, אִלְמָלֵא לֹא בָאתִי לְכָאן אֶלָּא לִשְׁמֹעַ הַדְּבָרִים הַלָּלוּ - דַּי לִי. אַשְׁרֵיהֵם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. עַל זֶה כָּתוּב (ישעיה ה) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר."],[4,"","וְלָבָן הָלַךְ לִגְזז אֶת צֹאנוֹ וְגוֹ'. אָמַר רַבִּי יוֹסֵי, מַה זֶּה תְּרָפִים? אֶלָּא עֲבוֹדָה זָרָה. וְלָמָּה נִקְרָאִים תְּרָפִים? לִגְנַאי הָיָה, כְּמוֹ שֶׁשָּׁנִינוּ בִּמְקוֹם הַתֹּרֶף. וּמִנַּיִן לָנוּ שֶׁהָיוּ עֲבוֹדָה זָרָה? שֶׁכָּתוּב לָמָּה גָנַבְתָּ אֶת אֱלֹהָי וְכָתוּב עִם אֲשֶׁר תִּמְצָא אֶת אֱלֹהֶיךְ וְגוֹ'. וְלָבָן הַמְכַשֵּׁף שֶׁל כָּל הַמְכַשְּׁפִים שֶׁל הָעוֹלָם הָיָה, וּבָזֶה הָיָה יוֹדֵעַ אֶת כָּל מַה שֶּׁרוֹצֶה לָדַעַת."],[5,"","אָמַר רַבִּי חִיָּיא, בְּקֶסֶם נַעֲשָׂה. רַבִּי יוֹסֵי אוֹמֵר, בְּנַחַשׁ. אָמַר רַבִּי יְהוּדָה, לֹא נַעֲשׂוּ אֶלָּא בְּשָׁעוֹת יְדוּעוֹת. וְלָמָּה נִקְרָאִים תְּרָפִים? מִשּׁוּם שֶׁמַּכִּים אֶת הַשָּׁעָה הַזּוֹ, וְהַשָּׁעָה מַרְפָּה הַיָּד, כְּמוֹ שֶׁנֶּאֱמַר רַב עַתָּה הֶרֶף יָדֶךְ."],[6,"","כְּשֶׁהָאֻמָּן עוֹשֶׂה אוֹתוֹ, אוֹתוֹ שֶׁיּוֹדֵעַ רְגָעִים וְשָׁעוֹת עוֹמֵד עָלָיו וְאוֹמֵר: כָּעֵת הַרְפֵּה וְכָעֵת עֲשֵׂה. וְלֹא תִמְצָא מַעֲשֶׂה שֶׁצָּרִיךְ שֶׁיַּרְפּוּ מִמֶּנּוּ אֶלָּא זֶה. וְהוּא מְדַבֵּר תָּמִיד וְנוֹתֵן עֵצוֹת רָעוֹת לְהָרַע לְנֶפֶשׁ הָאָדָם."],[7,"","וְרָחֵל פָּחֲדָה, מִשּׁוּם שֶׁנָּתַן עֵצָה לְהָרַע לְיַעֲקֹב, וּבִשְׁבִיל בִּזְיוֹן עֲבוֹדָה זָרָה שָׂמָה אוֹתָם תַּחְתֶּיהָ עַד שֶׁאֵין יְכוֹלִים לְדַבֵּר. שֶׁהֲרֵי כְּשֶׁהוּא מְתֻקָּן לְדַבֵּר, מְכַבְּדִים וּמַרְבִּיצִים לְפָנָיו. וְכָעֵת מַה כָּתוּב? וַתֵּשֶׁב עֲלֵיהֶם. זָכָר וּנְקֵבָה הָיוּ, וַעֲבוֹדוֹת רַבּוֹת עוֹשִׂים טֶרֶם מְדַבְּרִים. וּמִשּׁוּם כָּךְ הִתְעַכֵּב לָבָן שְׁלֹשָׁה יָמִים, שֶׁלֹּא יָדַע שֶׁבָּרַח יַעֲקֹב, שֶׁכָּתוּב וַיֵּגּד לְלָבָן בַּיּוֹם הַשְּׁלִישִׁי כִּי בָרַח יַעֲקֹב."],[8,"","וְאָמַר רַבִּי יְהוּדָה, הִזְמִין עַצְמוֹ בִּשְׁלֹשָׁה דְבָרִים: הִזְדָּרֵז בְּכָל הַכְּשָׁפִים שֶׁהָיוּ לוֹ, וְהִזְדָּרֵז בִּכְלֵי זַיִן כְּדֵי לְאַבֵּד אוֹתוֹ מִן הָעוֹלָם, שֶׁכָּתוּב (דברים כו) אֲרַמִּי אֹבֵד אָבִי. כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁרָצָה לְאַבֵּד אֶת יַעֲקֹב, מַה כָּתוּב? הִשָּׁמֶר לְךְ פֶּן תְּדַבֵּר עִם יַעֲקֹב מִטּוֹב עַד רָע. וְהַיְנוּ שֶׁכָּתוּב יֶשׁ לְאֵל יָדִי לַעֲשׂוֹת עִמָּכֶם רָע. בַּמֶּה בָּטַח? בַּכְּשָׁפִים שֶׁהָיוּ בְיָדוֹ."],[9,"","בֹּא רְאֵה, לָבָן הָלַךְ בְּיוֹם אֶחָד הַדֶּרֶךְ שֶׁהָלַךְ יַעֲקֹב שִׁבְעָה יָמִים כְּדֵי לַעֲקֹר אוֹתוֹ מִן הָעוֹלָם. אֶחָד עַל שֶׁהָלַךְ, וְאֶחָד עַל אוֹתָם הַתְּרָפִים. וְאַף עַל גַּב שֶׁרָחֵל הִיא שֶׁעָשְׂתָה כְּדֵי לַעֲקֹר אֶת אָבִיהָ מֵאַחֲרֵי עֲבוֹדָה זָרָה - נֶעֶנְשָׁה שֶׁלֹּא גִדְּלָה אֶת בִּנְיָמִין, וְלֹא עָמְדָה עִמּוֹ שָׁעָה אַחַת בִּשְׁבִיל הַצַּעַר שֶׁל אָבִיהָ, אַף עַל גַּב שֶׁהִתְכַּוְּנָה לְטוֹב."],[10,"","רַבִּי יִצְחָק אָמַר, כָּל אוֹתָהּ הַתּוֹכָחָה שֶׁהָיְתָה לְיַעֲקֹב עִם לָבָן, הֶחֱזִיר לוֹ לְלָבָן לְהוֹדוֹת לַקָּדוֹשׁ- בָּרוּךְ-הוּא, שֶׁכָּתוּב רְאֵה אֱלֹהִים עֵד בֵּינִי וּבֵינֶיךְ. בֹּא רְאֵה, כָּתוּב אֱלֹהֵי אַבְרָהָם וֵאלֹהֵי נָחוֹר יִשְׁפְּטוּ בֵינֵינוּ. חָזַר אוֹתוֹ הָרָשָׁע לְתַקָּלָתוֹ. כֵּיוָן שֶׁאָמַר אֱלֹהֵי אַבְרָהָם, חָזַר וְאָמַר וֵאלֹהֵי נָחוֹר."]]],[["(בראשית ל״א:נ״ג) וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק, מַאי טַעְמָא בְּפַחַד יִצְחָק, וְלָא בֵּאלֹהֵי אַבְרָהָם. אֶלָּא, דְּלָא בָעָא לְאַטְרָחָא לִימִינָא בְּגִינֵיהּ דְּלָבָן. וְלָא עוֹד, אֶלָא דְּלָא לִבָּעֵי לֵיהּ לְאִינִישׁ, אַף עַל גַּב דְּאוֹמֵי בְּקוּשְׁטָא, לְאוֹמָאָה בְּאֲתַר עִלָּאָה דְּכֹלָּא.","אָמַר רִבִּי יוֹסֵי, וַדַּאי לְקִיּוּמָא (ס\"א לאומאה) כְּדְקָא יְאוּת, אוֹמֵי יַעֲקֹב כָּךְ, וְהָכִי אִתְחֲזֵי, וְיַעֲקֹב אַשְׁגַּח בְּמִלָּה, אָמַר, הָא אִיהוּ אָמַר אֱלהֵי אַבְרָהָם, וְשָׁבַק לְאַבָּא, אֲנָא אַשְׁלִים כֹּלָּא, מִיָּד וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. דָבָר אַחֵר, לְאִתְכְּלָלָא בְּדִינָא, לְמֵיקַם עֲלֵיהּ דְּלָבָן.","(בראשית ל״ב:ב׳) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלהִים. רִבִּי אַבָּא פָּתַח וְאָמַר, (בראשית ה׳:ב׳) זָכָר וּנְקֵבָה בְּרָאָם וְגו', כַּמָּה אִית לָן לְאִסְתַּכָּלָא בְּמִלֵּי דְאוֹרַיְיתָא. וַוי לוֹן לְאִינוּן אֲטִימֵי לִבָּא וּסְתִימִין עַיְינִין, הָא אוֹרַיְיתָא קָארֵי קַמַּיְיהוּ, (משלי ט׳:ה׳-ו׳) לְכוּ לַחֲמוּ בְלַחְמִי וּשְׁתוּ בְּיַיִן מָסָכְתִּי. (שם) מִי פֶּתִי יָסוּר הֵנָּה חֲסַר לֵב אָמְרָה לוֹ, וְלֵית מַאן דְּיַשְׁגַּח.","תָּא חֲזֵי, הַאי קְרָא, אִית בֵּיהּ רָזִין עִלָאִין, אִיהוּ לְגוֹ, וְאִיהוּ לְבַר. זָכָר וּנְקֵבָה בְּרָאָם, אִשְׁתְּמַע לְהַאי גַוְונָא, וְאִשְׁתְּמַע לְהַאי גַוְונָא. וְאִשְׁתְּמַע דְּשִׁמְשָׁא וְסִיהֲרָא בְּחִבּוּרָא חָדָא אִינוּן, דִּכְתִיב בְּרָאָם. כְּמָה דְאַתְּ אָמֵר, (חבקוק ג׳:י״א) שֶׁמֶשׁ יָרֵחַ עָמַד זְבוּלָה. וְאִשְׁתְּמַע, דְּאָדָם וְחַוָּה כְּחֲדָא אִתְבְּרִיאוּ, בְּזִוּוּגָא חַד. וְכֵיוָן דְּאִשְׁתַּכָּחוּ בְּזִוּוּגָא חַד, מִיָּד וַיְבָרֶךְ אֹתָם. דְּלֵית בִּרְכָתָא שַׁרְיָא, אֶלָּא בְּאֲתַר דְּאִשְׁתַּכָּחוּ דְּכַר וְנוּקְבָא.","תָּא חֲזֵי, כַּד נָפַק יַעֲקֹב לְמֵיהַךְ לְחָרָן, בִּלְחוֹדוֹי הֲוָה, דְּלָא אִינְסִיב. מַה כְּתִיב, (בראשית כ״ח:י״א) וַיִּפְגַּע בַּמָּקוֹם וְגו', וְלָא אָתִיבוּ לֵיהּ אֶלָּא בְּחֶלְמָא, הַשְׁתָּא דְאִנְסִיב וְהֲוָה אָתֵי בְּכֻלְּהוּ שִׁבְטִין. כִּבְיָכוֹל מַשִּׁרְיָין עִלָּאִין, פָּגְעִין בֵּיהּ, וְאִתְחַנְּנוּ לֵיהּ. דִּכְתִיב וַיִּפְגְּעוּ בוֹ, אִינוּן אַהֲדָרוּ לְמִפְגַּע בֵּיהּ. בְּקַדְמִיתָא אִיהוּ וַיִּפְגַּע בַּמָּקוֹם, הַשְׁתָּא אִינוּן וַיִּפְגְּעוּ בוֹ.","בְּגִין דִּבְגִינֵיהּ דְּיַעֲקֹב וּבְאִינוּן שִׁבְטִין, אִתְשַׁקְיָין אִינוּן מִמַּיָא דְיַמָּא רַבָּא. וְלָא עוֹד, אֶלָּא בְּקַדְמִיתָא בַּלַּיְלָה בְּחֶלְמָא. הַשְׁתָּא בְּחֵיזוּ דְעֵינָא, וּבִימָמָא. הֲדָא הוּא דִכְתִיב, (בראשית ל״ב:ג׳) וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם מַחֲנֵה אֱלהִים זֶה וְגו'."],[[0,"וישבע יעקב בפחד אביו יצחק:","שואל, מה הטעם שנשבע בפחד יצחק ולא באלקי אברהם, ומשיב, אלא שלא רצה להכביד על הימין, שהוא אברהם. להמשיך אותו בשביל לבן, ולפיכך לא נשבע באלקי אברהם שה\"ס הימין. ולא עוד, אלא אדם אינו צריך לשבע במקום העליון על כל, אע\"פ שנשבע באמת. פירוש, שע\"כ לא נשבע באלקי אברהם, משום שה\"ס החסד, שהוא העליון מז\"ס חג\"ת נהי\"מ. ואין אדם צריך להשבע במקום גבוה כל כך."],[1,"א\"ר יוסי וכו':","אר\"י, ודאי שלקיום כראוי נשבע יעקב כך, כלומר, שנתכוון בודאי במ\"ש, בפחד אביו יצחק, כדי ליתן יותר חיזוק לשבועתו, שכן צריך להיות. ויעקב הסתכל בדבר, אמר, הרי לבן כבר אמר אלקי אברהם, ועזב את אבי יצחק. אף אשלים את הכל, מיד וישבע יעקב בפחד אביו יצחק. פירוש אחר, להכלל בדין כדי לעמוד בפני לבן."],[2,"ויפגעו בו מלאכי אלקים וגו':","ר' אבא פתח ואמר, זכר ונקבה בראם וגו'. כמה יש לנו להסתכל בדברי תורה, שה\"ס ז\"א, קו האמצעי. ווי להם, לאלו ערלי לב וסתומי עינים דהיינו הדבקים בקו שמאל, שנסתמו מחכמה, שנקראת עינים, ומבינה, המכונה לב. הרי התורה, שהיא מקו אמצעי, קוראת לפניהם, לכו לחמו בלחמי, שהוא נמשך מקו ימין של התורה, ושתו ביין מסכתי, הנמשך מקו שמאל של התורה. מי פתי, דהיינו כל הדבוק בשמאל, יסור הנה, חסר לב אמרה לו. ואין מי שישגיח בה."],[3,"ת\"ח האי קרא וכו':","בוא וראה מקרא זה זכר ונקבה בראם, יש בו סודות עליונים, הוא נוהג בפנימיות בזו\"ן, והוא נוהג בחיצוניות, באדם וחוה. כלומר, שיש חיבור זכר ונקבה בפנימיות, דהיינו בגדלות, ויש חיבור זכר ונקבה בחיצוניות, דהיינו בקטנות. הוא נשמע באופן זה, בפנימיות, ונשמע באופן זה, בחיצוניות. כי נשמע, שהשמש ולבנה שהם זו\"נ, הם בחבור א', שכתוב עליהם \u0003בראם,\u0004 כמו שאתה אומר, שמש ירח עמד זבולה. שה\"ס זכר ונקבה בפנימיות. ונשמע מהמקרא, שאדם וחוה נבראו ויצאו מזווג אחד מזו\"ן העליונים, שיצאו תחלה בחצוניות, וכיון שנמצאו בזווג כאחד, מיד ויברך אותם אלקים. כי אין הברכה שורה אלא במקום שנמצא זכר ונקבה. ואחר זה נעשו זכר ונקבה בפנימיות, בסוד פא\"פ."],[4,"תא חזי, כד נפק וכו':","בוא וראה, כאשר יצא יעקב ללכת לחרן, היה אז בלבדו, שעוד לא נשא אשה. מה כתוב, \u0003ויפגע במקום וגו'.\u0004 ולא ענו לו אלא בחלום. ועתה שכבר נשא אשה, ובא בכל השבטים, כביכול, מחנות העליונים פגעו בו, והתחננו אליו, שכתוב, \u0003ויפגעו בו,\u0004 שחזרו הם לפגוע בו, דהיינו להתחנן אליו, מתחילה התחנן הוא, שכתוב \u0003ויפגע במקום.\u0004 עתה התחננו הם. שכתוב ויפגעו בו."],[5,"בגין דבגיניה","וכו': משום שבשביל יעקב והשבטים, הם מושקים ממימי הים הגדול, שהוא השפע של הנוקבא בגדלות המכונה אז \u0003הים הגדול.\u0004 וע\"כ התחננו אליו שימשיך להם השפע הזה. ולא עוד אלא מתחילה ראה אותם בלילה ובחלום שכתוב ויחלום וגו' והנה מלאכי אלקים עולים ויורדים בו, ועתה ראה אותם בראות העין וביום, וזהו שכתוב, ויאמר יעקב כאשר ראם מחנה אלקים זה וגו'."],[5,"","פירוש. שהוקשה לו, כי למעלה כתוב ויפגע במקום, וכאן כתוב ויפגעו בו, ובשניהם כתוב הפגיעה, שפירושו פיוסא, דהיינו המשכת הארת השמאל בתחילת הזווג (כמ\"ש לעיל בראשית ב' דף קל\"ו ד\"ה פנימיות, עש\"ה) וא\"כ מהו ההפרש ביניהם, ששם היה יעקב שה\"ס ז\"א, המפייס את הנוקבא, וכאן היו מלאכי הנוקבא מפייסים אותו. ולבאר את זה, מביא תחילה הכתוב זכר ונקבה בראם, ומבארו, שיש ב' בחינות זווגים א' פנימית וא' חיצונית. ומחלק עם זה, אשר הכתוב ויפגע במקום ה\"ס הארת השמאל מבחינת חיצוניות, \u0003וז\"ש כלחודוי הוה דלא אנסיב,\u0004 כלומר שהנוקבא עוד לא היתה מתוקנת לו פנים בפנים, \u0003מה כתיב ויפגע במקום,\u0004 שהוא היה צריך לפייס הנוקבא, דהיינו להמשיך לה בזווג מהארת הקו השמאלי, \u0003ולא אתיבו ליה אלא בחלמא,\u0004 דהיינו בחינת חצוניות, כי חלום ה\"ס חצוניות, (כנ\"ל דף כ\"ו ד\"ה חצוניות) \u0003השתא דאנסיב,\u0004 כלומר, שהנוקבא נתקנה לו פנים בפנים, \u0003ויפגעו בו, אינון אהדרו למפגע ביה,\u0004 כי אחר שהנוקבא היא בגדלות אינו צריך עוד להמשיך לה מקו שמאל, אלא שמשפיע לה חסדים מימין בלבד, ובענין הארת השמאל הוא להיפך, כי היות שהנוקבא כבר מתוקנת בסוד חכמה תתאה, אז המלאכים שלה משפיעים עליו מהארת השמאל שהסו\"ה ויפגעו בו מלאכי אלקים, כנ\"ל."],[5,"","וז\"ש \u0003בגין דבגיניה דיעקב ובאינון שבטין,\u0004 דהיינו בכח שיעקב כבר היה נשוי לאשה ומתוקן בי\"ב שבטים, שה\"ס פנים בפנים, \u0003אתשקיין אינון ממיא דימא רבא,\u0004 שכבר היו שתוים מהארת החכמה שבשמאל, המכונה הים הגדול, וע\"כ \u0003ויפגעו בו,\u0004 שהם השפיעו אליו מהארת השמאל. וז\"ש \u0003ולא עוד אלא בקדמיתא בלילה בחלמא,\u0004 כי מתחילה, כשיעקב היה צריך לפייסה ולהמשיך לה מהארת קו שמאל, היה זה בלתי אפשרי אלא בלילה, כי בעת הארת השמאל בלי ימין נעשה אז חשך ולילה, (כנ\"ל בראשית ב' דף קל\"ז ד\"ה וילן שם) \u0003השתא בחיזו דעינא וביממא,\u0004 כי עתה אין צריך להשפיע לה עוד מן השמאל אלא מימין, שה\"ס הארת החסדים, שזמן השפעתו הוא ביום."]],[[0,"","וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. מָה הַטַּעַם בְּפַחַד יִצְחָק וְלֹא בֵּאלֹהֵי אַבְרָהָם? אֶלָּא שֶׁלֹּא רָצָה לְהַטְרִיחַ אֶת הַיָּמִין בִּשְׁבִיל לָבָן, וְלֹא עוֹד, אֶלָּא שֶׁלֹּא צָרִיךְ לָאָדָם - אַף עַל גַּב שֶׁנִּשְׁבָּע בֶּאֱמֶת - לְהִשָּׁבַע בַּמָּקוֹם הָעֶלְיוֹן שֶׁל הַכֹּל."],[1,"","אָמַר רַבִּי יוֹסֵי, וַדַּאי לְקִיּוּם (לשבועה) כָּרָאוּי נִשְׁבַּע כָּךְ יַעֲקֹב, וְכָךְ רָאוּי. וְיַעֲקֹב הִשְׁגִּיחַ בַּדָּבָר. אָמַר, הֲרֵי הוּא אָמַר אֱלֹהֵי אַבְרָהָם, וְעָזַב אֶת אַבָּא. אֲנִי אַשְׁלִים אֶת הַכֹּל. מִיָּד - וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. דָּבָר אַחֵר, לְהִכָּלֵל בַּדִּין, לַעֲמֹד עַל לָבָן."],[2,"","וְיַעָקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים. רַבִּי אַבָּא פָּתַח וְאָמַר, (בראשית ה) זָכָר וּנְקֵבָה בְּרָאָם וְגוֹ'. כַּמָּה יֵשׁ לָנוּ לְהִסְתַּכֵּל בְּדִבְרֵי הַתּוֹרָה. אוֹי לָהֶם לְאוֹתָם אֲטוּמֵי הַלֵּב וּסְתוּמֵי הָעֵינַיִם. הִנֵּה הַתּוֹרָה קוֹרֵאת לִפְנֵיהֶם, (משלי ט) לְכוּ לַחֲמוּ בְלַחְמִי וּשְׁתוּ בְּיַיִן מָסָכְתִּי. מִי פֶתִי יָסֻר הֵנָּה. חֲסַר לֵב אָמְרָה לוֹ, וְאֵין מִי שֶׁיַּשְׁגִּיחַ."],[3,"","בֹּא רְאֵה, בַּפָּסוּק הַזֶּה יֵשׁ סוֹדוֹת עֶלְיוֹנִים, הוּא בִּפְנִים וְהוּא בַּחוּץ. זָכָר וּנְקֵבָה בְּרָאָם, נִשְׁמָע לַצּוּרָה הַזּוֹ וְנִשְׁמָע לַצּוּרָה הַזּוֹ, וְנִשְׁמָע שֶׁהַשֶּׁמֶשׁ וְהַלְּבָנָה הֵם בְּחִבּוּר אֶחָד, שֶׁכָּתוּב בְּרָאָם, כְּמוֹ שֶׁנֶּאֱמַר (חבקוק ג) שֶׁמֶשׁ יָרֵחַ עָמַד זְבֻלָה. וְנִשְׁמָע שֶׁאָדָם וְחַוָּה נִבְרְאוּ יַחַד בְּזִוּוּג אֶחָד, וְכֵיוָן שֶׁנִּמְצְאוּ בְּזִוּוּג אֶחָד, מִיָּד וַיְבָרֶךְ אֹתָם, שֶׁאֵין הַבְּרָכָה שׁוֹרָה אֶלָּא בְּמָקוֹם שֶׁנִּמְצָאִים זָכָר וּנְקֵבָה."],[4,"","בֹּא רְאֵה, כְּשֶׁיָּצָא יַעֲקֹב לָלֶכֶת לְחָרָן, הָיָה לְבַדּוֹ, שֶׁלֹּא נִשָּׂא, מַה כָּתוּב? וַיִּפְגַּע בַּמָּקוֹם וְגוֹ', וְלֹא הֵשִׁיבוּ לוֹ אֶלָּא בַחֲלוֹם. כָּעֵת שֶׁנִּשָּׂא, וְהָיָה בָּא עִם כָּל הַשְּׁבָטִים, כִּבְיָכוֹל הַמַּחֲנוֹת הָעֶלְיוֹנִים פָּגְשׁוּ בוֹ וְהִתְחַנְּנוּ לוֹ, שֶׁכָּתוּב וַיִּפְגְּעוּ בוֹ. הֵם חָזְרוּ לְהִפָּגֵשׁ בּוֹ. בָּרִאשׁוֹנָה - וַיִּפְגַּע הוּא בַּמָּקוֹם, וְכָעֵת הֵם - וַיִּפְגְּעוּ בוֹ."],[5,"","מִשּׁוּם שֶׁבִּשְׁבִיל יַעֲקֹב וּבְאוֹתָם הַשְּׁבָטִים הֵם מֻשְׁקִים, מִן הַמַּיִם שֶׁל הַיָּם הַגָּדוֹל. וְלֹא עוֹד, אֶלָּא בָּרִאשׁוֹנָה בַּלַּיְלָה בַּחֲלוֹם, וְכָעֵת בְּמַרְאֵה הָעַיִן וּבַיּוֹם. זֶהוּ שֶׁכָּתוּב וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם מַחֲנֵה אֱלֹהִים זֶה וְגוֹ'."]]],[["בְּמָּה אִשְׁתְּמוֹדַע לוֹן, אֶלָא חָמָא, דְּאִינוּן הֲווּ, אִינוּן דְּחָמָא בְּחֶלְמָא, בְּגִינֵי כָּךְ קָרָא לוֹן מַחֲנָיִם, מַשִּׁרְיָין דְּאִתְחֲזוּ לְעֵילָא, וּמַשִּׁרְיָין דְּאִתְחֲזוּ לְתַתָּא.","אַמַּאי אִתְגַּלִּיאוּ לְמִפְגַע לֵיהּ. אֶלָא שְׁכִינְתָּא אָזְלָא לְגַבֵּיהּ, לְנַטְלָא לְבֵיתֵיהּ. וּמְחַכָּא לֵיהּ לְבִנְיָמִן, לְנַטְלָא בֵּיתָא עִמֵּיהּ דְּיַעֲקֹב כְּדְקָא יְאוּת. וּכְדֵין כְּתִיב, (ירמיהו מ״ו:כ״ז) וְשָׁב יַעֲקֹב ושָׁקַט וְשַׁאֲנָן ואֵין מַחֲרִיד. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן ואָמֵן. (ע\"כ פרשת ויצא)","\u0003סתרי תורה\u0004 (בראשית ל״ב:ב׳) וְיַעֲקֹב הָלַךָ לְדַרְכּוֹ וַיִּפְּגְּעוּ בוֹ מַלְאֲכֵי אֱלהִים. מַתְּנִיתִּין, תּוֹקְפֵּי דְהוּרְמְנֵי, זְקִיפִּין מִלְּעֵילָא, וְשִׁנְּנָא דְחַרְבָּא דִמְלַהֲטָא מְמַנָּא על כָּל (ס\"א כמה) חֵילִין וּמַשִׁירְיָין.","הַהוּא חַרְבָּא מְלַהֲטָא, הִיא חַרְבָּא סוּמְקָא. דִּכְתִּיב, (ישעיה לה) חֶרֶב לַיְיָ מָלְאָה דָם. הַהוּא חַרְבָּא דְּתַּלְיָא בֵּיהּ הִפּוּכָא, אִינוּן דִּמְהַפְּכֵי לְכַמָּה גְוָונִין. הוּא נַשְׁיָין, הוּא גוּבְרִין, בְּסִטְרִין סַגִּיאִין, מִתְּפָּרְשִׁין גְּוָונִין אָחֳרָנִין לְכַמָּה דַרְגִּין.","מִסִּטְרָא דְאִילָנָא דְחַיֵּי, נָפְּקֵי אִינוּן. דְּמִתְּיַחֲדֵי בְּיִחוּדָא בְּקִשׁוּרָא. קַדִּישִׁין אִלֵּין, אִשְׁתָּאֲבָן תָּדִיר מִטַל הַשָׁמַיִם, שְׁמֵיהּ דֵּאלקִים, אִתְּתַּקִּין בְּהוּ. (ס\"א ועל דא אמר משמני הארץ ואתתקן) בְּאַרְבַּע סִטְרִין דְּעָלְמָא, אִתְּעֲבִידוּ סַמְכִין דְּכֻּרְסְיָיא. כֻּלְּהוּ מַרְגְּלִיטִין, שַׁיְיפִּין וְסַמְכִין, לָא מִתְּפָּרְשִׁין לְעַלְמָא. מִגּוֹ דָא שְׁמָא, אִינוּן קִשׁוּרִין דְּיַעֲקֹב, דְּבָרִיר לְחוּלָקֵיהּ. וּמִתְּקַשְׁרָן בִּשְׁמָא דָא, כֻּלְּהוּ נָפְּקוּ (בערב) (ביעקב).","וְיַעֲקֹב כַּד נָפַּק לְמֵיזַל לְאָרְחֵיהּ, לְאַרְבַּע סִטְרִין אֲקִיפּוּ לֵיהּ, לְאַרְבַּע זָוְויָין דְּעַלְמָא נָטְרוּ לֵיהּ, בְּשַׁעְתָּא קַלָּה אִתְּרְגִישׁ מֵאִילָנָא (ס\"א מאתר) לְעֵילָא, לְמִיטַר אִילָנָא דִלְתַּתָּא, וּכְדֵין (בראשית ל׳:כ״ה) וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם מַחֲנֵה אֱלֹהִים זֶה. כְּדֵין (בראשית ל׳:כ״ה) וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם. (נדפס דף קנ\"ח ע\"ב ושם מפורש)","אָמַר רַבִּי יְהוּדָה, תָּא חֲזֵי, שְׁלֵמוּתֵּיהּ דְּיַעֲקֹב, דְּלָא בָּעֵי (בעא) לְמֵיזַל אֶלָּא בִּרְשׁוּתֵּיהּ דְּלָבָן, וְאִי תֵּימָא, זִמְנָא אָחֳרָא אַמַּאי לָא. אֶלָּא בְּגִין דְּדָחִיל יַעֲקֹב דְּלָא יִשְׁבּוֹק לֵיהּ, וְיִשְׁתְּלִימוּ תְּרֵיסַר שִׁבְטִין בְּאַרְעָא אָחֳרָא. וְעַל דָּא כֵּיוָן דְּחָמָא דְּמָטָא שַׁעְתָּא דְבִנְיָמִן, בָּרַח. כְּמָה דְאַתְּ אָמֵר, (בראשית לא) וַיִּבְרַח הוּא וְכָל אֲשֶׁר לוֹ. דְּכֵיוָן דְּאִתְּיָלִיד בִּנְיָמִן, אִתְּקַשַׁר שְׁכִינְתָּא בְּכֻלְּהוּ שִׁבְטִין, וְנָטַל בֵּיתָּא בְּהוּ. וְיַעֲקֹב הֲוָה יָדַע בְּרוּחָא דְחָכְמְתָּא, דְּכַד יִשְׁתַּלִּימוּ תְּרֵיסַר שִׁבְטִין, דִּשְׁכִינְתָּא תִּתְּקַשַׁר בְּהוּ, וְרָחֵל תָּמוּתּ, וְאִיהִי נָטְלָא בֵּיתָּא.","וְתָּא חֲזֵי, הָכִי אוֹלִיפְּנָא, עַלְמָא תַּתָּאָה, אִתְּחֲזֵי לֵיהּ לְיַעֲקֹב, כְּמָה דְּאִתְּחֲזֵי לֵיהּ לְמשֶׁה, אֶלָּא דְּלָא יְכִילַתּ, עַד דְּהֲווּ י\"ב שִׁבְטִין בְּבֵיתָּא, לְאִתְּקַשְׁרָא בְּהוּ. וּכְדֵין, אִתְּדַּחְיַיתּ רָחֵל, וּנְטָלַתּ אִיהִי בֵּיתָּא בְּכֻלְּהוּ שִׁבְטִין, וְהֲוַתּ עִקְרָא דְּבֵיתָּא. וּכְדֵין (תהילים קי״ג:ט׳) מוֹשִׁיבִי עֲקֶרֶתּ הַבַּיִתּ. אָמַר יַעֲקֹב, הָא מָטָא זִמְנָא דְּיִשְׁתַּלִּימוּ י\"ב שִׁבְטִין, וּוַדַּאי עַלְמָא דִלְעֵילָא יֵיחוּתּ לֵיהּ לְבֵיתָּא, ואִתְּקַשְׁרָא (נ\"א עלמא דלעילא ייחות ליה בביתיה, ואתקשרא) בְּהוּ, וּמִסְכְּנָתָּא דָא אִתְּדַּחְיָיא קַמֵּיהּ. אִי תִּימוּתּ הָכָא, לָא אֶפּוֹק מִכָּאן לְעָלְמִין. ולא עוֹד, אֶלָּא בְּאַרְעָא דָא, לָא אִתְּחֲזֵי לְאַשְׁלָמָא בֵּיתָּא. בְּגִין כָּךָ, (בראשית ל׳:כ״ה) וַיְהִי כַּאֲשֶׁר יָלְדָה רָחֵל אֶתּ יוֹסֵף, עַד לָא יִשְׁתַּלִּימוּ שִׁבְטִין.","שָׁמַע רִבִּי שִׁמְעוֹן, אָמַר, ודַּאי כָּל מִלּוֹי דְּרִבִּי יְהוּדָה שַׁפִּיר, ודא סָלִיק עַל כֹּלָּא. וְאִי תֵּימָא, אַמַּאי לָא אָזַל לֵיהּ לְאָרְחֵיהּ מִיָּד. אֶלָּא, כָּל זִמְנָא דְרָחֵל לָא מִתְּעַבְּרָא מִבִּנְיָמִן, אִתְּעַכַּב תַּמָּן. כֵּיוָן דְּמָטָא זִמְנָא דְּבִנְיָמִן, עָרַק, ולא בָעָא רְשׁוּתָּא. בְּגִין דְּלָא יִתְּעַכַּב תַּמָּן, ואִתְּחַבַּר יַעֲקֹב בְּכֻלְּהוּ שִׁבְטִין, בְּאֲתַּר דְּאִצְּטְרִיךָ. (ע\" פרשת ויצא)"],[[0,"במה אשתמודע לון וכו':","שואל, במה הכירם שהם מלאכי אלקים, ומשיב אלא שראה שהם היו אותם המלאכים שראם בחלום. ומשום זה קרא אותם \u0003מחנים,\u0004 דהיינו על שם הכתוב, והנה מלאכי אלקים עולים ויורדים בו. שראם בחלומו, שנראו למעלה ונראו למטה, שהם ב' מחנות."],[1,"אמאי אתגליאו וכו':","שואל, למה נגלו עתה המלאכים לפגוע בו. דהיינו לפייסו בהארת החכמה כנ\"ל. ומשיב, אלא השכינה הלכה אל יעקב, לקחת את ביתו, דהיינו להתכלל עם הנוקבא העליונה לאה, להיות פרצוף אחד, שאז יהיה לה כל בית יעקב, כל י\"ב השבטים, דהיינו גם ששת בני לאה, והשכינה היתה מחכה לבנימין לקחת את הבית עם יעקב כראוי, דהיינו בכל י\"ב השבטים. ולפיכך נגלו אליו המלאכים, בסוד הפיוס, שהוא הארת השמאל, להשלימו לגמרי, ואז כתוב ושב יעקב ושקט ושאנן ואין מחריד, כי עם הארת החכמה מכניעים כל הקליפות שבעולם, \u0003ואין מחריד.\u0004 ברוך ה' לעולם אמן ואמן."],[2,"ויעקב הלך לדרכו וגו':","מגיני השרים זקופים מלמעלה, ולהט החרב הלוהטת ממונה על כל הצבאות והמחנות. פירוש. \u0003שרים\u0004 ה\"ס או\"א. והמוחין שבבחינת קו שמאל דאו\"א, נקראים \u0003מגיני השרים. זקיפין\u0004 פירושו ג\"ר, כי מוחין דו\"ק נבחנים לכפופים, והג\"ר \u0003זוקף\u0004 אותם. וז\"ש, \u0003תוקפי דהורמני,\u0004 מגיני השרים, \u0003זקיפין מלעילא,\u0004 דהיינו שהג\"ר מאירות בקו שמאל דאו\"א הנקראים שרים, אז הם זקיפים. והנוקבא המקבלת אז מאו\"א, נעשית ללהט החרב המתהפכת, ושולטת בכח הדין הזה על כל הצבאות ומחנות המלאכים הנמשכים ממנה, הן הנמשכים מימין והן משמאל, וכולם פועלים בדין. וז\"ש באר חפרוה שרים. ש \u0003באר\u0004 ה\"ס הנוקבא, \u0003שרים\u0004 הם או\"א, \u0003חפרוה,\u0004 היינו בכח הדינים הנ\"ל."],[3,"ההוא חרבא מלהטא וכו':","החרב הלוהטת ההיא, היא חרב אדומה, משום שדינים אלו נמשכים בה מקו שמאל דבינה שהיא אדום. שכתוב עליה, חרב לה' מלאה דם. בחרב ההיא תלויה ההתהפכות, דהיינו אלו המלאכים המתהפכים לכמה אופנים, פעם הם נשים פעם הם גברים. ובבחינה זו מתפרשות בחינות אחרות לכמה מדרגות. כי יש עוד ב' בחינות המכונים \u0003עירין ורוחין\u0004 בנשים, וכן ב' בחינות עירין ורוחין בגברים. וענין התהפכות הזו כבר נתבאר לעיל (בזהר בראשית ב' דף ע\"ז מן אות ק\"ט עד אות קכ\"ב, ובהסולם שם) ואין להכפיל דברים."],[3,"","ביאור הדברים. כי הוקשה לו בפירוש הכתוב שלפנינו, א) שאומר ויעקב הלך לדרכו, שאיני יודע לאיזה דרך. ב) כאשר ראם, הוא מיותר, כיון שפגעו בו ודאי ראה אותם. ג) למה בפגיעה נאמר מלאכי אלקים ובקריאת שם מחנה אלקים. ועוד דקדוקים יש בו. ולהלן מבאר הכתוב, אשר \u0003ויעקב הלך לדרכו,\u0004 הוא להמשכת מוחין מאו\"א אל הנוקבא. ובתחילה, כשהמשיך הקו השמאלי באו\"א, נתגלו מלאכי הדין בנוקבא, שעליהם נאמר ויפגעו בו מלאכי אלקים. ויעקב נתעורר לשמור הנוקבא מדינים אלו, ואז נאמר, \u0003ויאמר יעקב כאשר ראם,\u0004 שפירושו, כשגילה בהם \u0003הראיה,\u0004 על ידי המשכת קו אמצעי המיחד ב' הקוין ימין ושמאל זב\"ז, אמר אז, \u0003מחנה אלקים זה, מחנה\u0004 פירושו שקשר את ד' הבחינות שבמלאכים למחנה אחד. ואח\"כ נעשו סמכין לנוקבא בד' זויות שלה, ואז \u0003ויקרא שם המקום ההוא,\u0004 דהיינו שם הנוקבא הנקראת \u0003מקום,\u0004 קרא אותה עתה \u0003מחנים,\u0004 כי מחנה אלקים נתפשטה לד' מחנות, בד' זויות שלה. ולפיכך הוצרך לבאר תחילה, מקום יציאת המוחין שהם מאו\"א, ושמאו\"א מקבלת הנוקבא, ומן הנוקבא מתפשטים המלאכים. והוצרך לבאר אלו ג' הבחינות בשליטת השמאל שזהו שמבאר כאן. א) סוד \u0003תוקפי דהורמני זקיפין מלעילא,\u0004 שהם מוחין דשמאל שבאו\"א. ב) שמהם נמשך \u0003להט החרב\u0004 שה\"ס הנוקבא במוחין דשמאל, ג) דתליא ביה הפוכא \u0003אינון דמהפכי לכמה גוונין,\u0004 שהם המלאכים הנמשכים מנוקבא. ואחר זה להלן, מבאר אותם ג' בחינות דקו אמצעי. ומהם בא לביאור הכתוב בדרך הנ\"ל. כמ\"ש לפנינו."],[4,"מסטרא דאילנא דחיי וכו':","מצד עץ החיים, שהוא קו אמצעי, יוצאים, באו\"א, אלו המתיחדים ביחוד על ידי קשר, דהיינו שיוצאים ג' קוין באו\"א ביחוד אחד, על ידי הקשר דמסך דחירק (כנ\"ל דף קכ\"ז ד\"ה ביאור) שהעלה שם יעקב בסוד מ\"ן. ג' קוין קדושים אלו מתמלאים תמיד מטל השמים, כלומר, אע\"פ שיש שם כל ג' קוין כאחד, מ\"מ אינו שולט בהם השמאל כלום, ורק הימין שולט על כולם, שה\"ס חסדים מכוסים, המכונים טל השמים, משום שאין גילוי לשמאל רק בנוקבא בלבדה. וז\"ס בחינה א) דקו אמצעי. השם אלקים, דהיינו הנוקבא, מתתקן בהם, דהיינו במוחין דאו\"א, וזוהי בחינה ב' דקו אמצעי. בארבע רוחות העולם, שהיא הנוקבא, נעשו המוחין לעמודים של הכסא, שה\"ס הנוקבא המכונה כסא. כלומר, לד' רגלים של הכסא, שהם ד' המלאכים מיכאל גבריאל אוריאל רפאל. וזהו בחינה ג') דקו אמצעי. ונתבארו ג' הבחינות, שהם או\"א, ונוקבא, ומלאכים. גם מבחינת הקו האמצעי."],[4,"כלהו מרגליטין שייפין וכו':","כולם, כל ג' הבחינות הנ\"ל, שהם, מרגליות, אברים, ועמודים, אינם נפרדים לעולם מן השם הזה אלקים, שהוא הנוקבא. והם הקשורים של יעקב, שבחר לחלקו ונתקשרו בשם הזה, שהוא הנוקבא. וכולם יצאו ביעקב."],[4,"","פירוש. כל ג' הבחינות הנ\"ל, שהן: מקור יציאתם באו\"א, וביאתם אל הנוקבא, והתפשטותם במלאכים, מתחברות בהנוקבא, ומכונות אצלה, \u0003מרגליטין שייפין וסמכין.\u0004 כי נה\"י דאו\"א מתלבשים בנוקבא עם המוחין שלהם, שנה\"י הללו ה\"ס אמא אוזיפת לברתא מאנהא, (כנ\"ל בהקסה\"ז דף כ\"ו ד\"ה ואמא) ע\"ש. והם מכונים \u0003מרגלית,\u0004 שהוא מלשון ותגל \u0003מרגלותיו.\u0004 כי נה\"י מכונים רגלים. ואז כשמתפשטים בה המוחין הללו, היא מכונית \u0003כסא.\u0004 והמלאכים המתפשטים ממנה נעשו ד' רגלי הכסא כנ\"ל, והמוחין המתפשטים בנוקבא עצמה נקראים \u0003שייפין,\u0004 כלומר איברים וחלקים של הכסא עצמו. והמתפשטים אל המלאכים מכונים \u0003סמכין,\u0004 שהם סומכים את הכסא ואינם הכסא עצמו. ונתבאר חיבור ג' הבחינות ביחד בתוך הנוקבא. ואומר \u0003כלהו נפקו ביעקב,\u0004 כלומר אע\"פ שאמרנו שהנוקבא מקבלת ג' הבחינות הללו מאו\"א, אינה מקבלתם ישר מאו\"א, אלא הם יוצאים מקודם ביעקב, שהוא ז\"א, והנוקבא מקבלתם מיעקב."],[5,"כד נפק למיזל לארחיה וכו':","כשיעקב הלך לדרכו, כלומר כשהלך לקבל אלו ג' הבחינות הנ\"ל מאו\"א, בשביל הנוקבא, לארבעה צדדים, חו\"ב תו\"מ, הקיפו אותו, שעלה למ\"ן לאו\"א, ובסוד הקו האמצעי וגילה שם ד' אורות חו\"ב תו\"מ, בסוד אור מקיף. לארבע זויות העולם, שהיא הנוקבא הנקראת עולם, שמרו אותו, שהמשיך את חו\"ב תו\"מ מאו\"א. לנוקבא בכל השלמות, ורק בזמן מועט נתרגש מהמקום העליון, דהיינו מן, תוקפי דהורמני זקיפין מלעילא, שהוא שליטת השמאל שבאו\"א. שמשם מתפשטים מלאכים המתהפכים לכמה גוונים, ועליהם נאמר \u0003ויפגעו בו מלאכי אלקים,\u0004 דהיינו \u0003שנפגע\u0004 ונתרגש מהדין שבהם. והיה זה, כדי לשמור האילן שלמטה, פירוש, כדי שיעלה מ\"ן לאו\"א ויגלה שם הקו האמצעי, לשמירת האילן שמלמטה, שהיא הנוקבא, מן הדינים, ואחר שהמשיך קו האמצעי, אז נאמר, \u0003ויאמר יעקב כאשר ראם,\u0004 כשגילה בהם \u0003הראיה\u0004 שהיא המוחין דחו\"ב תו\"מ היוצאים על הקו האמצעי, אמר \u0003מחנה אלקים זה,\u0004 שייחד את מלאכי אלקים למחנה אחת ונעשו סמכין אל הנוקבא, לד' זוית שלה. ואז, \u0003ויקרא שם המקום ההוא מחנים,\u0004 דהיינו שנעשו ד' מחנות לד' זוית של הנוקבא. בסוד ד' רגלי הכסא כנ\"ל."],[6,"אמר רבי יהודה וכו':","מכאן עד סיום הפרשה, כבר נתבאר לעיל דף ק' מאות רמ\"ו עד אות רנ\"א."]],[[0,"","בַּמָּה הִכִּיר אוֹתָם? אֶלָּא רָאָה שֶׁהֵם הָיוּ אוֹתָם שֶׁרָאָה בַּחֲלוֹם, מִשּׁוּם כָּךְ קָרָא לָהֶם מַחֲנָיִם, מַחֲנוֹת שֶׁנִּרְאוּ לְמַעְלָה וּמַחֲנוֹת שֶׁנִּרְאוּ לְמַטָּה."],[1,"","לָמָּה נִתְגַּלּוּ לִפְגֹּשׁ אוֹתוֹ? אֶלָּא הַשְּׁכִינָה הָלְכָה אֵלָיו לִטֹּל אֶת בֵּיתוֹ, וּמְצַפָּה לְבִנְיָמִין לִטֹּל אֶת הַבַּיִת עִם יַעֲקֹב כָּרָאוּי, וְאָז כָּתוּב וְשָׁב יַעֲקֹב וְשָׁקַט וְשַׁאֲנַן וְאֵין מַחֲרִיד. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."],[2,"","וְיַעָקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים. מִשְׁנָה. חָזְקֵי הַשָּׂרִים זְקוּפִים מִלְמַעְלָה, וְלַהַט הַחֶרֶב הַשְּׁנוּנָה מְמֻנָּה עַל כָּל (כמה) הַצְּבָאוֹת וְהַמַּחֲנוֹת."],[3,"","אוֹתָהּ הַחֶרֶב הַלּוֹהֶטֶת הִיא חֶרֶב אֲדֻמָּה, שֶׁכָּתוּב (ישעיה לד) חֶרֶב לַה' מָלְאָה דָם. הַחֶרֶב הַ את שֶׁתְּלוּיָה בָּהּ הַהִפּוּךְ, הֵם שֶׁמִּתְהַפְּכִים לְכַמָּה צוּרוֹת. הוּא נָשִׁים, הוּא גְבָרִים, בִּצְדָדִים רַבִּים, נִפְרָדוֹת הַצּוּרוֹת הָאֲחֵרוֹת לְכַמָּה דְרָגוֹת."],[4,"","מֵהַצַד שֶׁל עֵץ הַחַיִּים הֵם יוֹצְאִים, שֶׁמִּתְיַחֲדִים בְּיִחוּד בְּקֶשֶׁר. אֵלּוּ הַקְּדוֹשִׁים נִשְׁאָבִים תָּמִיד מִטַּל הַשָּׁמַיִם. הַשֵּׁם שֶׁל אֱלֹהִים מִתְתַּקֵּן בָּהֶם. (ועל זה אמר משמני הארץ ונתקן) בְּאַרְבָּעָה הַצְּדָדִים שֶׁל הָעוֹלָם נַעֲשׂוּ לְעַמּוּדֵי הַכִּסֵּא. כֻּלָּם מַרְגָּלִיּוֹת וְאֵיבָרִים וְעַמּוּדִים, לֹא נִפְרָדִים לְעוֹלָם מִתּוֹךְ הַשֵּׁם הַזֶּה, הֵם הַקְּשָׁרִים שֶׁל יַעֲקֹב שֶׁבָּחַר לְחֶלְקוֹ וְנִקְשָׁרִים בַּשֵּׁם הַזֶּה, כֻּלָּם יָצְאוּ (בערב)."],[5,"","וְיַעָקֹב, כְּשֶׁיָּצָא לָלֶכֶת לְדַרְכּוֹ, הִקִּיפוּ אוֹתוֹ לְאַרְבָּעָה צְדָדִים. לְאַרְבַּע הַזָּוִיּוֹת שֶׁל הָעוֹלָם שָׁמְרוּ אוֹתוֹ. בְּשָׁעָה קַלָּה הִתְרַגֵּשׁ מֵהָעֵץ (מהמקום) שֶׁלְּמַעְלָה לִשְׁמֹר אֶת הָעֵץ שֶׁלְּמַטָּה, וְאָז וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם מַחֲנֵה אֱלֹהִים זֶה. אָז וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם."],[6,"","אָמַר רַבִּי יְהוּדָה, בֹּא רְאֵה אֶת שְׁלֵמוּתוֹ שֶׁל יַעֲקֹב שֶׁלֹּא רָצָה לָלֶכֶת אֶלָּא בִּרְשׁוּתוֹ שֶׁל לָבָן. וְאִם תֹּאמַר, בְּפַעַם אַחֶרֶת לָמָּה לֹא? אֶלָּא מִשּׁוּם שֶׁיַּעֲקֹב פָּחַד שֶׁלֹּא יַעֲזב אוֹתוֹ, וְיִשְׁתַּלְּמוּ שְׁנֵים עָשָׂר הַשְּׁבָטִים בְּאֶרֶץ אַחֶרֶת. וְעַל כֵּן, כֵּיוָן שֶׁרָאָה שֶׁהִגִּיעָה הַשָּׁעָה שֶׁל בִּנְיָמִין, בָּרַח, כְּמוֹ שֶׁנֶּאֱמַר וַיִּבְרַח הוּא וְכָל אֲשֶׁר לוֹ. כֵּיוָן שֶׁנּוֹלַד בִּנְיָמִין, נִקְשְׁרָה הַשְּׁכִינָה עִם כָּל הַשְּׁבָטִים, וְנָטְלָה אֶת הַבַּיִת עִמָּם. וְיַעֲקֹב הָיָה יוֹדֵעַ בְּרוּחַ הַחָכְמָה, שֶׁכַּאֲשֶׁר יִשְׁתַּלְּמוּ שְׁנֵים עָשָׂר הַשְּׁבָטִים, שֶׁהַשְּׁכִינָה תִּתְקַשֵּׁר עִמָּהֶם וְרָחֵל תָּמוּת, וְהִיא נוֹטֶלֶת אֶת הַבַּיִת."],[7,"","וּבֹא וּרְאֵה, כָּךְ לָמַדְנוּ, הָעוֹלָם הַתַּחְתּוֹן רָאוּי לוֹ לְיַעֲקֹב כְּמוֹ שֶׁרָאוּי לְמֹשֶׁה, אֶלָּא שֶׁלֹּא יָכְלָה עַד שֶׁהָיוּ שְׁנֵים עָשָׂר שְׁבָטִים בַּבַּיִת לְהִתְקַשֵּׁר עִמָּהֶם, וְאָז נִדְחֲתָה רָחֵל, וְהִיא נָטְלָה אֶת הַבַּיִת עִם כָּל הַשְּׁבָטִים וְהָיְתָה עִקַּר הַבַּיִת, וְאָז (תהלים קיג) מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת. אָמַר יַעֲקֹב, הִנֵּה הִגִּיעַ הַזְּמַן שֶׁיִּשְׁתַּלְּמוּ שְׁנֵים עָשָׂר הַשְּׁבָטִים, וּוַדַּאי שֶׁהָעוֹלָם שֶׁלְּמַעְלָה יָרַד לוֹ לַבַּיִת וְיִתְקַשֵּׁר (העולם שלמעלה ירד לו בביתו והתקשר) בָּהֶם, וְהָעֲנִיָּה הַ את נִדְחֵית לְפָנָיו. אִם תָּמוּת כָּאן, לֹא אֵצֵא מִכָּאן לְעוֹלָמִים. וְלֹא עוֹד, אֶלָּא בָּאָרֶץ הַזּוֹ לֹא רָאוּי לְהַשְׁלִים אֶת הַבַּיִת. מִשּׁוּם כָּךְ, (בראשית ל) וַיְהִי כַּאֲשֶׁר יָלְדָה רָחֵל אֶת יוֹסֵף, טֶרֶם שֶׁיִּשְׁתַּלְּמוּ הַשְּׁבָטִים."],[8,"","שָׁמַע רַבִּי שִׁמְעוֹן, אָמַר, וַדַּאי שֶׁכָּל דִּבְרֵי רַבִּי יְהוּדָה יָפִים, וְזֶה עוֹלֶה עַל הַכֹּל. וְאִם תֹּאמַר, לָמָּה לֹא הָלַךְ לוֹ לְדַרְכּוֹ מִיָּד? אֶלָּא כָּל זְמַן שֶׁרָחֵל לֹא הִתְעַבְּרָה מִבִּנְיָמִין, הִתְעַכֵּב שָׁם. כֵּיוָן שֶׁהִגִּיעַ הַזְּמַן שֶׁל בִּנְיָמִין, בָּרַח, וְלֹא בִקֵּשׁ רְשׁוּת, כְּדֵי שֶׁלֹּא יִתְעַכֵּב שָׁם, וְהִתְחַבֵּר יַעֲקֹב עִם כָּל הַשְּׁבָטִים בַּמָּקוֹם שֶׁצָּרִיךְ. ע\"כ סתרי תורה"]]]]};
